/// The first no-repair notification namespace is only observation data.
/// The cold notification adapter must later authenticate canonical control,
/// mapping, owned-ID provenance and drain contents, request exact policy,
/// and prove OS absence
/// before any generation unlink. An absent root is changed only by the
/// operation-bound checked createRootFromFirstAbsence effect.
@MainActor
final class EraseSchema2ColdNotificationSourceV1 {
    static let creationRecordName = "notification-root-create.json"
    static let creationTemporaryName =
        ".notification-root-create.json.next"
    static let creationStageName =
        ".AppLockNotificationControlV1.create-next"
    static let ownedIDsName = "notification-owned-ids.json"
    static let ownedIDsTemporaryName =
        ".notification-owned-ids.json.next"
    static let drainName = "notification-drain.json"
    static let drainTemporaryName =
        ".notification-drain.json.next"
    private weak var manifestOwner: EraseSchema2ColdManifestOwnerV1?
    private weak var operation: EraseColdPreparationOperationV1?
    let eraseID: UUID
    let rootIdentity: String?
    fileprivate var projectedRootIdentity: String?
    let names: [String]
    let rootFact: EraseColdControlLeafFactV1?
    let rootPolicy: TemporalPolicyObservationV1?
    let hasAuthenticatedCreationRecord: Bool
    let leafBytes: [String: Data]
    let leafFacts: [String: EraseColdControlLeafFactV1]
    let leafPolicies: [String: TemporalPolicyObservationV1]
    fileprivate let manifestIdentity: ObjectIdentifier

    fileprivate init(manifest: EraseSchema2ColdManifestOwnerV1,
        operation: EraseColdPreparationOperationV1,
        eraseID: UUID, rootIdentity: String?, names: [String],
        rootFact: EraseColdControlLeafFactV1?,
        rootPolicy: TemporalPolicyObservationV1?,
        hasAuthenticatedCreationRecord: Bool,
        leafBytes: [String: Data],
        leafFacts: [String: EraseColdControlLeafFactV1],
        leafPolicies: [String: TemporalPolicyObservationV1]) {
        manifestIdentity = ObjectIdentifier(manifest)
        manifestOwner = manifest
        self.operation = operation
        self.eraseID = eraseID
        self.rootIdentity = rootIdentity
        self.names = names
        self.rootFact = rootFact
        self.rootPolicy = rootPolicy
        self.hasAuthenticatedCreationRecord =
            hasAuthenticatedCreationRecord
        self.leafBytes = leafBytes
        self.leafFacts = leafFacts
        self.leafPolicies = leafPolicies
    }

    func withHeldRoot<T>(_ body: (Int32, URL) throws -> T)
        throws -> T {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner.withHeldSchema2ColdNotificationRoot(
            source: self, operation: operation, body)
    }

    func withHeldRootForMutation<T>(
        token: EraseSchema2ColdNotificationMutationTokenV1,
        _ body: (Int32, URL) throws -> T
    ) throws -> T {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner.withHeldSchema2ColdNotificationRootForMutation(
            source: self, token: token, operation: operation, body)
    }

    func beginMutation(
        stage: EraseSchema2ColdNotificationMutationStageV1
    ) throws -> EraseSchema2ColdNotificationMutationTokenV1 {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner.beginSchema2ColdNotificationMutation(
            stage: stage, source: self, operation: operation)
    }

    func finishMutation(
        token: EraseSchema2ColdNotificationMutationTokenV1,
        receipt: EraseSchema2ColdNotificationMutationReceiptV1
    ) throws {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try manifestOwner.finishSchema2ColdNotificationMutation(
            token: token, receipt: receipt, operation: operation)
    }

    func createRootFromFirstAbsence()
        throws -> EraseSchema2ColdNotificationRootCreatedV1 {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner
            .createSchema2ColdNotificationRootFromFirstAbsence(
                source: self, operation: operation)
    }

    func requireCurrentRootIdentity() throws -> String {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner.requireSchema2ColdNotificationCurrentRootIdentity(
            source: self, operation: operation)
    }

    func settleCanonicalCreationAfterReplay()
        throws -> EraseSchema2ColdNotificationRootCreatedV1 {
        guard let manifestOwner, let operation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return try manifestOwner
            .settleSchema2ColdNotificationCanonicalCreationAfterReplay(
                source: self, operation: operation)
    }

    /// Exact retained actor association only. The actual OP registration
    /// proves this same observation scope; no scanner or projection callback
    /// is invoked from this getter.
    fileprivate func requireColdScratchObservationOperation(
        _ observation: ColdEraseScratchNotificationObservationScopeV1
    ) throws -> EraseColdPreparationOperationV1 {
        guard let manifestOwner, let operation,
              observation.manifest === manifestOwner,
              observation.source === self,
              observation.operationID == operation.retainedColdOperationIDForComparison else {
            throw StoreMigrationFailure.invalidIdentity
        }
        // This actual OP registration proves the SAME Source's durable
        // eraseID against its retained intent, independently of runtime UUID.
        try operation.requireColdScratchNotificationObservationScope(observation,
            manifest: manifestOwner, source: self, store: observation.store,
            ranges: observation.ranges, scope: observation.heldScope)
        return operation
    }

    func requireColdScratchOutsideOperation(
        _ admission: ColdEraseScratchCleanupInitialAdmissionV1
    ) throws -> EraseColdPreparationOperationV1 {
        guard let manifestOwner, let operation,
              admission.operationID == operation.retainedColdOperationIDForComparison else {
            throw StoreMigrationFailure.invalidIdentity
        }
        // Runtime admission identity and durable Source/intent lineage are
        // distinct. The actual OP proves this SAME Source against its intent.
        try operation.requireColdScratchNotificationOutsideSource(self, admission: admission)
        try admission.requireColdNotificationOutsideBinding()
        guard manifestIdentity == ObjectIdentifier(manifestOwner) else { throw StoreMigrationFailure.invalidIdentity }
        return operation
    }
}

/// One actual readback window and projection metadata, privately retained by
/// the Manifest after the Range's typed reservation and before any syscall.
/// This owner never opens/closes a descriptor or issues an effect. Failure
/// retains the exact scope, raw return, readback and existing pin association.
@MainActor
final class ColdEraseScratchNotificationObservationBackingV1 {
    fileprivate enum Role: UInt8 {
        case control, controlPending, mapping, mappingPending, revocation, revocationPending
        case ownedIDs, ownedIDsPending, drain, drainPending, creation
        case operations, notificationRoot, registry

        fileprivate var isDirectory: Bool {
            self == .operations || self == .notificationRoot || self == .registry
        }

        fileprivate static func notification(_ name: String) throws -> Role {
            switch name {
            case AppLockNotificationControlStoreV1.recordName: return .control
            case AppLockNotificationControlStoreV1.pendingName: return .controlPending
            case AppLockNotificationControlStoreV1.mappingName: return .mapping
            case AppLockNotificationControlStoreV1.mappingPendingName: return .mappingPending
            case AppLockNotificationControlStoreV1.eraseName: return .revocation
            case AppLockNotificationControlStoreV1.erasePendingName: return .revocationPending
            case EraseSchema2ColdNotificationSourceV1.ownedIDsName: return .ownedIDs
            case EraseSchema2ColdNotificationSourceV1.ownedIDsTemporaryName: return .ownedIDsPending
            case EraseSchema2ColdNotificationSourceV1.drainName: return .drain
            case EraseSchema2ColdNotificationSourceV1.drainTemporaryName: return .drainPending
            default: throw StoreMigrationFailure.invalidIdentity
            }
        }
    }
    private enum State { case active, complete, outside, released, uncertain }
    private struct Storage {
        weak var manifest: EraseSchema2ColdManifestOwnerV1?
        weak var observation: ColdEraseScratchNotificationObservationScopeV1?
        var retainedObservation: ColdEraseScratchNotificationObservationScopeV1?
        weak var admission: ColdEraseScratchCleanupInitialAdmissionV1?
        var retainedAdmission: ColdEraseScratchCleanupInitialAdmissionV1?
        let loan: ColdEraseScratchBorrowedParentsV1
        let source: EraseSchema2ColdNotificationSourceV1
        var state: State = .active
        var role: Role?
        var descriptor: Int32 = -1
        var parent: Int32 = -1
        var name: String?
        var expectedFact: EraseColdControlLeafFactV1?
        var held = stat(), named = stat()
        var statEntered = false, statNamed = false
        var statReturned: Int32?, statErrno: Int32?
        var readback: Data?
        var readCalls: UInt64 = 0
        var readOffset = 0
        var readEntered = false
        var readReturned: Int?, readErrno: Int32?
        var eofByte: UInt8 = 0
        var eofEntered = false
        var eofReturned: Int?, eofErrno: Int32?
        var leafFacts: [String: String] = [:]
        var leafSHA256: [String: String] = [:]
        var creation: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild?
    }
    private var storage: Storage

    /// Actual stored scalar/reference backing plus closed metadata/value
    /// windows. Allocator, object, Foundation and VM overhead is unmeasured;
    /// these declared charges are not an RSS admission claim.
    static func requiredBackingBytes() throws -> UInt64 {
        var result = UInt64(MemoryLayout<Storage>.stride)
        func add(_ value: UInt64) throws {
            let next = result.addingReportingOverflow(value)
            guard !next.overflow else { throw StoreMigrationFailure.invalidIdentity }
            result = next.partialValue
        }
        try add(UInt64(MemoryLayout<stat>.stride))
        try add(UInt64(MemoryLayout<ColdEraseScratchNotificationFullFactMatcherV1>.stride))
        try add(UInt64(MemoryLayout<SHA256.Digest>.stride))
        try add(UInt64(MemoryLayout<Dictionary<String, String>.Element>.stride) * 20)
        try add(UInt64(10 * (255 + 241 + 64)))
        try add(UInt64(4 * 241 + 3 * 64))
        try add(UInt64(AppLockNotificationControlStoreV1.maximumRecordBytes))
        return result
    }

    fileprivate init(manifest: EraseSchema2ColdManifestOwnerV1,
        observation: ColdEraseScratchNotificationObservationScopeV1,
        source: EraseSchema2ColdNotificationSourceV1) {
        storage = Storage(manifest: manifest, observation: observation,
            retainedObservation: observation, admission: nil, retainedAdmission: nil,
            loan: observation.loan, source: source)
        storage.leafFacts.reserveCapacity(10)
        storage.leafSHA256.reserveCapacity(10)
    }

    fileprivate func requireAssociation(manifest: EraseSchema2ColdManifestOwnerV1,
        observation: ColdEraseScratchNotificationObservationScopeV1,
        source: EraseSchema2ColdNotificationSourceV1) throws {
        guard storage.state == .active, storage.manifest === manifest,
              storage.observation === observation, storage.retainedObservation === observation,
              storage.source === source, observation.manifest === manifest,
              observation.source === source else { throw StoreMigrationFailure.invalidIdentity }
    }

    fileprivate func begin(role: Role, descriptor: Int32, parent: Int32,
        name: String, expectedFact: EraseColdControlLeafFactV1) throws {
        guard (storage.state == .active || storage.state == .outside),
              storage.role == nil, storage.readback == nil,
              descriptor >= 0, parent >= 0,
              expectedFact.mode & S_IFMT == (role.isDirectory ? S_IFDIR : S_IFREG),
              (role.isDirectory ? expectedFact.links > 0 : expectedFact.links == 1),
              expectedFact.size >= 0,
              role.isDirectory || expectedFact.size <= off_t(AppLockNotificationControlStoreV1.maximumRecordBytes) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.role = role; storage.descriptor = descriptor; storage.parent = parent
        storage.name = name; storage.expectedFact = expectedFact
        storage.readCalls = 0; storage.readOffset = 0
        storage.readEntered = false; storage.readReturned = nil; storage.readErrno = nil
        storage.eofEntered = false; storage.eofReturned = nil; storage.eofErrno = nil
    }

    fileprivate func requireExactPin() throws {
        guard (storage.state == .active || storage.state == .outside), storage.role != nil,
              let name = storage.name, let expected = storage.expectedFact else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireCurrentOwnerFrame()
        storage.statEntered = true; storage.statNamed = false
        let descriptor = storage.descriptor, parent = storage.parent
        let heldResult = Darwin.fstat(descriptor, &storage.held), heldErrno = errno
        storage.statReturned = heldResult; storage.statErrno = heldErrno
        guard heldResult == 0, EraseColdControlLeafFactV1(storage.held) == expected else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.statEntered = true; storage.statNamed = true
        let namedResult = Darwin.fstatat(parent, name, &storage.named, AT_SYMLINK_NOFOLLOW)
        let namedErrno = errno
        storage.statReturned = namedResult; storage.statErrno = namedErrno
        guard namedResult == 0, EraseColdControlLeafFactV1(storage.named) == expected else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireCurrentOwnerFrame()
    }

    fileprivate func readAndRequire(_ expected: Data) throws {
        guard (storage.state == .active || storage.state == .outside),
              let role = storage.role, !role.isDirectory, storage.readback == nil,
              let fact = storage.expectedFact,
              expected.count == Int(fact.size) else { throw StoreMigrationFailure.invalidIdentity }
        let budget = UInt64(expected.count).addingReportingOverflow(1)
        guard !budget.overflow else { throw StoreMigrationFailure.invalidIdentity }
        storage.readback = Data(count: expected.count) // retained before the first entered read
        while storage.readOffset < expected.count {
            try requireCurrentOwnerFrame()
            let call = storage.readCalls.addingReportingOverflow(1)
            guard !call.overflow, call.partialValue <= budget.partialValue else {
                throw StoreMigrationFailure.invalidIdentity
            }
            storage.readCalls = call.partialValue; storage.readEntered = true
            let offset = storage.readOffset
            let requested = min(65_536, expected.count - offset)
            let descriptor = storage.descriptor
            let returned = storage.readback!.withUnsafeMutableBytes { raw in
                Darwin.pread(descriptor, raw.baseAddress!.advanced(by: offset),
                    requested, off_t(offset))
            }
            let savedErrno = errno
            storage.readReturned = returned; storage.readErrno = savedErrno
            // EINTR is a retained refusal; no unbounded retry is admitted.
            guard returned > 0, returned <= requested else { throw StoreMigrationFailure.invalidIdentity }
            storage.readOffset += returned
            try requireCurrentOwnerFrame()
        }
        try requireCurrentOwnerFrame()
        let call = storage.readCalls.addingReportingOverflow(1)
        guard !call.overflow, call.partialValue <= budget.partialValue else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.readCalls = call.partialValue; storage.eofEntered = true
        let descriptor = storage.descriptor
        let returned = Darwin.pread(descriptor, &storage.eofByte, 1, off_t(expected.count))
        let savedErrno = errno
        storage.eofReturned = returned; storage.eofErrno = savedErrno
        guard returned == 0, storage.readback == expected else { throw StoreMigrationFailure.invalidIdentity }
        try requireCurrentOwnerFrame()
    }

    fileprivate func finishRead() throws {
        try requireExactPin()
        guard storage.eofEntered, storage.eofReturned == 0 else { throw StoreMigrationFailure.invalidIdentity }
        storage.readback = nil; storage.role = nil
        storage.descriptor = -1; storage.parent = -1; storage.name = nil; storage.expectedFact = nil
    }

    fileprivate func finishPinOnly() throws {
        guard let role = storage.role, role.isDirectory,
              storage.readback == nil, !storage.readEntered, !storage.eofEntered else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireExactPin()
        storage.role = nil; storage.descriptor = -1; storage.parent = -1
        storage.name = nil; storage.expectedFact = nil
    }

    fileprivate func requireNamedAbsence(role: Role, parent: Int32, name: String) throws {
        guard (storage.state == .active || storage.state == .outside), storage.role == nil,
              storage.readback == nil, parent >= 0,
              (role == .notificationRoot && name == AppLockNotificationControlStoreV1.rootName)
                || (role == .creation && name == EraseSchema2ColdNotificationSourceV1.creationRecordName) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireCurrentOwnerFrame()
        storage.role = role; storage.parent = parent; storage.name = name
        storage.statEntered = true; storage.statNamed = true
        let returned = Darwin.fstatat(parent, name, &storage.named, AT_SYMLINK_NOFOLLOW)
        let savedErrno = errno
        storage.statReturned = returned; storage.statErrno = savedErrno
        guard returned != 0, savedErrno == ENOENT else { throw StoreMigrationFailure.invalidIdentity }
        try requireCurrentOwnerFrame()
        storage.role = nil; storage.parent = -1; storage.name = nil
    }

    private func requireCurrentOwnerFrame() throws {
        if storage.state == .active, let observation = storage.retainedObservation {
            try observation.requireCurrentBinding()
        } else if storage.state == .outside, let admission = storage.retainedAdmission,
                  storage.admission === admission {
            try admission.requireColdNotificationOutsideBinding()
        } else { throw StoreMigrationFailure.invalidIdentity }
    }

    fileprivate func transferToOutside(admission: ColdEraseScratchCleanupInitialAdmissionV1,
        manifest: EraseSchema2ColdManifestOwnerV1, source: EraseSchema2ColdNotificationSourceV1) throws {
        if storage.state == .outside {
            guard storage.manifest === manifest, storage.source === source,
                  storage.admission === admission, storage.retainedAdmission === admission else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try requireCurrentOwnerFrame(); return
        }
        guard storage.state == .complete, storage.retainedObservation == nil,
              storage.manifest === manifest, storage.source === source,
              let observation = storage.observation,
              observation.source === source, observation.manifest === manifest,
              observation.operationID == admission.operationID,
              observation.ranges === admission.ranges,
              observation.heldScope === admission.heldScope,
              storage.role == nil, storage.readback == nil,
              storage.admission == nil, storage.retainedAdmission == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.admission = admission; storage.retainedAdmission = admission // before the fallible actual join
        storage.state = .outside
        try admission.requireColdNotificationOutsideBinding() // proves genuine completed initial consumption
    }

    fileprivate func releaseAfterRevokedLoan(operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard storage.state == .outside, storage.role == nil, storage.readback == nil,
              let admission = storage.retainedAdmission, storage.admission === admission,
              admission.operationID == operation.retainedColdOperationIDForComparison, admission.heldScope === scope,
              let observation = storage.observation, observation.heldScope === scope,
              observation.loan === storage.loan else { throw StoreMigrationFailure.invalidIdentity }
        try storage.loan.requireCheckedColdScratchLoanRevoked(operation: operation, scope: scope)
        storage.state = .released
        storage.retainedAdmission = nil // positive pure loan-release proof only; no old FD IO
    }

    fileprivate func recordLeaf(name: String, fact: String, sha256: String) throws {
        guard storage.state == .active, storage.role == nil,
              storage.leafFacts[name] == nil, storage.leafSHA256[name] == nil,
              storage.leafFacts.count < 10, fact.utf8.count <= 241, sha256.utf8.count == 64 else {
            throw StoreMigrationFailure.invalidIdentity
        }
        _ = try Role.notification(name)
        storage.leafFacts[name] = fact; storage.leafSHA256[name] = sha256
    }
    fileprivate var leafFacts: [String: String] { storage.leafFacts }
    fileprivate var leafSHA256: [String: String] { storage.leafSHA256 }
    fileprivate var creation: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild? {
        get { storage.creation }
        set { storage.creation = newValue }
    }

    fileprivate func finishCheckedObservation() throws {
        guard storage.state == .active, storage.role == nil, storage.readback == nil,
              let observation = storage.retainedObservation else { throw StoreMigrationFailure.invalidIdentity }
        try observation.requireCurrentBinding()
        storage.state = .complete
        storage.retainedObservation = nil // positive final consumer only; uncertain paths retain the cycle
    }
    fileprivate func requireCheckedInitialReadbackSettlement(
        observation: ColdEraseScratchNotificationObservationScopeV1,
        manifest: EraseSchema2ColdManifestOwnerV1) throws {
        guard storage.state == .complete, storage.manifest === manifest,
              storage.observation === observation, storage.source === observation.source,
              storage.retainedObservation == nil, storage.role == nil,
              storage.readback == nil, storage.descriptor == -1, storage.parent == -1 else {
            throw StoreMigrationFailure.invalidIdentity
        }
    }
    fileprivate func poisonOnUncertainObservation() {
        storage.state = .uncertain
        storage.retainedObservation?.poisonOnUncertainObservation()
        storage.retainedAdmission?.poisonOnUncertainCleanup()
    }
}

/// Three canonical notification records, borrowed from this Manifest's
/// authentic Source or positively completed own mutation projection. This
/// carrier is DATA only: it issues no policy request, OS absence or effect.
/// The Range reserves and retains it before the first readback allocation.
@MainActor
final class ColdEraseScratchNotificationCanonicalRecordsV1 {
    enum Role: Equatable { case ownedIDs, revocation, drain }
    struct Record {
        let fact: EraseColdControlLeafFactV1
        let policy: TemporalPolicyObservationV1
        let sha256: String
        let byteCount: UInt64
    }
    fileprivate struct StoredRecord {
        let bytes: Data
        let metadata: Record
        var fact: EraseColdControlLeafFactV1 { metadata.fact }
    }
    fileprivate enum State { case allocated, checking, validated, uncertain }
    fileprivate struct Slot {
        let record: StoredRecord?
    }
    fileprivate struct RawStat {
        let returned: Int32
        let savedErrno: Int32
        let fact: EraseColdControlLeafFactV1?
    }
    fileprivate struct Storage {
        weak var manifest: EraseSchema2ColdManifestOwnerV1?
        let source: EraseSchema2ColdNotificationSourceV1
        weak var operation: EraseColdPreparationOperationV1?
        weak var store: EraseIntentStore?
        weak var ranges: ColdEraseScratchPayloadRangesV1?
        weak var scope: ColdEraseScratchCleanupHeldGScopeV1?
        let ownedIDs: Slot
        let revocation: Slot
        let drain: Slot
        var ownedIDsPasses: UInt8 = 0
        var revocationPasses: UInt8 = 0
        var drainPasses: UInt8 = 0
        var state: State = .allocated
        var activeRole: Role?
        var activeBorrowRole: Role?
        var readback: Data?
        var readOffset = 0
        var readReturned: Int?
        var readErrno: Int32?
        var readCalls = 0
        var eofByte: UInt8 = 0
        var eofEntered = false
        var eofReturned: Int?
        var eofErrno: Int32?
        var heldStat: RawStat?
        var namedStat: RawStat?
    }
    private var storage: Storage

    /// Actual fixed storage, one retained readback buffer, and bounded local
    /// stat/digest/member windows. Existing immutable Source Data are COW
    /// aliases, not copied raw backing. Allocator/class/header/VM costs are
    /// unmeasured; this is declared backing accounting, not RSS admission.
    static func requiredBackingBytes() throws -> UInt64 {
        let fixed = UInt64(MemoryLayout<Storage>.stride
            + 2 * MemoryLayout<StoredRecord>.stride + MemoryLayout<Record>.stride
            + 4 * MemoryLayout<stat>.stride
            + MemoryLayout<SHA256.Digest>.stride
            + MemoryLayout<ColdEraseScratchNotificationFullFactMatcherV1>.stride
            + 2 * MemoryLayout<String.UTF8View>.stride
            + 2 * MemoryLayout<String.UTF8View.Iterator>.stride)
        let members = UInt64(10 * (MemoryLayout<String>.stride + 255)
            + 2 * MemoryLayout<[String]>.stride)
        let readback = UInt64(AppLockNotificationControlStoreV1.maximumRecordBytes)
        let pair = fixed.addingReportingOverflow(members)
        let total = pair.partialValue.addingReportingOverflow(readback)
        guard !pair.overflow, !total.overflow else { throw StoreMigrationFailure.invalidIdentity }
        return total.partialValue
    }

    fileprivate init(manifest: EraseSchema2ColdManifestOwnerV1,
        source: EraseSchema2ColdNotificationSourceV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        ownedIDs: StoredRecord?, revocation: StoredRecord?, drain: StoredRecord?) {
        storage = Storage(manifest: manifest, source: source, operation: operation,
            store: store, ranges: ranges, scope: scope, ownedIDs: Slot(record: ownedIDs),
            revocation: Slot(record: revocation), drain: Slot(record: drain))
    }

    /// Pure private object association only. In particular this checker
    /// cannot call Range/OP/G, observe a file or grant read/effect permission.
    func requireReservationAssociation(manifest: EraseSchema2ColdManifestOwnerV1,
        source: EraseSchema2ColdNotificationSourceV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1, scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard storage.state != .uncertain, storage.manifest === manifest,
              storage.source === source, storage.operation === operation,
              storage.store === store, storage.ranges === ranges, storage.scope === scope,
              source.manifestIdentity == ObjectIdentifier(manifest) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try manifest.requireColdScratchNotificationCanonicalCarrier(self, source: source)
    }

    func record(_ role: Role) throws -> Record? {
        guard storage.state == .validated, storage.activeRole == nil,
              storage.readback == nil else { throw StoreMigrationFailure.invalidIdentity }
        return expectedRecord(role)?.metadata
    }

    /// The pointer is borrowed only during this synchronous Void callback.
    /// No Data, dictionary, pointer-bearing DTO or generic return escapes.
    /// The closed Native caller owns its separately charged write window.
    func withCanonicalBytes(role: Role, operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore, ranges: ColdEraseScratchPayloadRangesV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        _ body: (UnsafeRawBufferPointer) throws -> Void) throws {
        do {
            guard let manifest = storage.manifest,
                  storage.operation === operation, storage.store === store,
                  storage.ranges === ranges, storage.scope === scope,
                  storage.activeBorrowRole == nil else {
                throw StoreMigrationFailure.invalidIdentity
            }
            guard try manifest.requireColdScratchNotificationCanonicalRecords(operation: operation,
                    store: store, ranges: ranges, scope: scope) === self else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try ranges.requireColdScratchNotificationCanonicalRecordsFrame(self, manifest: manifest,
                source: storage.source, operation: operation, store: store, scope: scope)
            guard storage.state == .validated, let expected = expectedRecord(role) else {
                throw StoreMigrationFailure.invalidIdentity
            }
            storage.activeBorrowRole = role // retained before the nonescaping callback
            try expected.bytes.withUnsafeBytes(body)
            storage.activeBorrowRole = nil // only after the actual callback returns positively
            guard try manifest.requireColdScratchNotificationCanonicalRecords(operation: operation,
                    store: store, ranges: ranges, scope: scope) === self else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try ranges.requireColdScratchNotificationCanonicalRecordsFrame(self, manifest: manifest,
                source: storage.source, operation: operation, store: store, scope: scope)
        } catch { poisonOnUncertainEffect(); throw error }
    }

    fileprivate func expectedRecord(_ role: Role) -> StoredRecord? {
        switch role { case .ownedIDs: return storage.ownedIDs.record
        case .revocation: return storage.revocation.record
        case .drain: return storage.drain.record }
    }

    fileprivate func beginVerification() throws {
        guard (storage.state == .allocated || storage.state == .validated),
              storage.activeRole == nil, storage.activeBorrowRole == nil,
              storage.readback == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.state = .checking
        storage.ownedIDsPasses = 0; storage.revocationPasses = 0; storage.drainPasses = 0
    }

    fileprivate func beginRole(_ role: Role) throws {
        guard storage.state == .checking, storage.activeRole == nil,
              storage.readback == nil else { throw StoreMigrationFailure.invalidIdentity }
        storage.activeRole = role
        storage.heldStat = nil; storage.namedStat = nil
        storage.readReturned = nil; storage.readErrno = nil; storage.readOffset = 0
        storage.readCalls = 0; storage.eofEntered = false
        storage.eofReturned = nil; storage.eofErrno = nil
    }

    fileprivate func recordStat(named: Bool, returned: Int32, savedErrno: Int32, information: stat) {
        let value = RawStat(returned: returned, savedErrno: savedErrno,
            fact: returned == 0 ? EraseColdControlLeafFactV1(information) : nil)
        if named { storage.namedStat = value } else { storage.heldStat = value }
    }

    fileprivate func readAndRequire(descriptor: Int32, role: Role, expected: StoredRecord) throws {
        guard storage.state == .checking, storage.activeRole == role,
              storage.readback == nil, expected.fact.size >= 0,
              expected.fact.size <= off_t(AppLockNotificationControlStoreV1.maximumRecordBytes),
              Int64(expected.bytes.count) == expected.fact.size else {
            throw StoreMigrationFailure.invalidIdentity
        }
        storage.readback = Data(count: expected.bytes.count) // retained before the first pread
        let budget = expected.bytes.count.addingReportingOverflow(1)
        guard !budget.overflow else { throw StoreMigrationFailure.invalidIdentity }
        while true {
            guard storage.readCalls < budget.partialValue else { throw StoreMigrationFailure.invalidIdentity }
            storage.readCalls += 1 // entered raw call before IO; failed/EINTR is never retried
            let offset = storage.readOffset
            if offset == expected.bytes.count {
                storage.eofEntered = true
                let returned = withUnsafeMutablePointer(to: &storage.eofByte) {
                    Darwin.pread(descriptor, $0, 1, off_t(offset))
                }
                let savedErrno = errno
                storage.eofReturned = returned; storage.eofErrno = savedErrno
                guard returned == 0 else { throw StoreMigrationFailure.invalidIdentity }
                break
            }
            let returned = storage.readback!.withUnsafeMutableBytes { raw in
                Darwin.pread(descriptor, raw.baseAddress!.advanced(by: offset),
                    min(65_536, raw.count - offset), off_t(offset))
            }
            let savedErrno = errno
            storage.readReturned = returned; storage.readErrno = savedErrno // before refusal
            guard returned > 0, returned <= expected.bytes.count - offset else {
                throw StoreMigrationFailure.invalidIdentity
            }
            storage.readOffset += returned
        }
        guard storage.readback == expected.bytes else { throw StoreMigrationFailure.invalidIdentity }
    }

    fileprivate func finishRole(_ role: Role) throws {
        guard storage.state == .checking, storage.activeRole == role else {
            throw StoreMigrationFailure.invalidIdentity
        }
        if let expected = expectedRecord(role) {
            guard storage.readback == expected.bytes,
                  storage.eofEntered, storage.eofReturned == 0,
                  storage.heldStat?.returned == 0, storage.heldStat?.fact == expected.fact,
                  storage.namedStat?.returned == 0, storage.namedStat?.fact == expected.fact else {
                throw StoreMigrationFailure.invalidIdentity
            }
        } else {
            guard storage.readback == nil, storage.namedStat?.returned != 0,
                  storage.namedStat?.savedErrno == ENOENT else { throw StoreMigrationFailure.invalidIdentity }
        }
        switch role {
        case .ownedIDs:
            guard storage.ownedIDsPasses < 2 else { throw StoreMigrationFailure.invalidIdentity }
            storage.ownedIDsPasses += 1
        case .revocation:
            guard storage.revocationPasses < 2 else { throw StoreMigrationFailure.invalidIdentity }
            storage.revocationPasses += 1
        case .drain:
            guard storage.drainPasses < 2 else { throw StoreMigrationFailure.invalidIdentity }
            storage.drainPasses += 1
        }
        storage.readback = nil // only after positive byte AND after-read physical settlement
        storage.activeRole = nil
    }

    fileprivate func finishVerification() throws {
        guard storage.state == .checking, storage.activeRole == nil, storage.readback == nil,
              storage.ownedIDsPasses == 2, storage.revocationPasses == 2,
              storage.drainPasses == 2 else { throw StoreMigrationFailure.invalidIdentity }
        storage.state = .validated // comparison DATA, never an accepted policy or IO authority
    }

    fileprivate func poisonOnUncertainEffect() {
        storage.state = .uncertain
        storage.ranges?.poison()
        storage.operation?.poisonColdScratchOwner()
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    fileprivate func requireColdScratchNotificationCanonicalCarrier(
        _ records: ColdEraseScratchNotificationCanonicalRecordsV1,
        source: EraseSchema2ColdNotificationSourceV1) throws {
        guard coldScratchNotificationCanonicalRecords === records,
              schema2ColdNotificationWitness === source,
              source.manifestIdentity == ObjectIdentifier(self) else {
            throw StoreMigrationFailure.invalidIdentity
        }
    }

    /// Initial-core DATA only. This distinct route never calls the old
    /// notification Source/receipt observer while genuine Scratch G is held.
    /// Native's closed reservation must exist before any carrier or readback
    /// allocation; every later call repeats the current two-pass comparison.
    func requireColdScratchNotificationCanonicalRecords(
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1, scope: ColdEraseScratchCleanupHeldGScopeV1)
        throws -> ColdEraseScratchNotificationCanonicalRecordsV1 {
        let source = try operation.requireColdScratchRetainedNotificationLineage(
            manifest: self, store: store, ranges: ranges, scope: scope)
        guard schema2ColdNotificationWitness === source,
              let projection = postGenerationProjection,
              let after = coldScratchNotificationAfter,
              !schema2ColdNotificationCaptureInFlight,
              !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let records: ColdEraseScratchNotificationCanonicalRecordsV1
        if let retained = coldScratchNotificationCanonicalRecords {
            records = retained
        } else {
            try ranges.reserveColdScratchNotificationCanonicalRecords(manifest: self,
                source: source, operation: operation, store: store, scope: scope)
            // Immutable aliases are borrowed only after the reservation.
            // An own projected leaf must use its actual retained bytes/fact;
            // an unchanged first leaf must use the actual Source fields.
            let names = schema2ColdNotificationProjectedNames ?? source.names
            let bytes = schema2ColdNotificationProjectedBytes ?? source.leafBytes
            let facts = schema2ColdNotificationProjectedFacts ?? source.leafFacts
            guard names.count <= 10, bytes.count == names.count,
                  facts.count == names.count else { throw StoreMigrationFailure.invalidIdentity }
            func record(_ name: String) throws -> ColdEraseScratchNotificationCanonicalRecordsV1.StoredRecord? {
                if !names.contains(name) {
                    guard bytes[name] == nil, facts[name] == nil,
                          after.notificationControlNodes?.contains(where: { $0.path == name }) != true else {
                        throw StoreMigrationFailure.invalidIdentity
                    }
                    return nil
                }
                guard let raw = bytes[name], let fact = facts[name],
                      let device = UInt64(exactly: fact.device),
                      fact.mode & S_IFMT == S_IFREG, fact.links == 1,
                      fact.size > 0, fact.size <= off_t(AppLockNotificationControlStoreV1.maximumRecordBytes),
                      Int64(raw.count) == fact.size,
                      let nodes = after.notificationControlNodes,
                      nodes.lazy.filter({ $0.path == name }).count == 1,
                      let node = nodes.first(where: { $0.path == name }),
                      let sha = node.contentSHA256 else { throw StoreMigrationFailure.invalidIdentity }
                var matcher = ColdEraseScratchNotificationFullFactMatcherV1()
                guard try matcher.matches(node.fullFact, fact: fact),
                      try Self.coldScratchNotificationDigestMatches(raw, sha: sha),
                      node.policy.device == device,
                      node.policy.inode == UInt64(fact.inode),
                      node.policy.mode == fact.mode, node.policy.linkCount == UInt64(fact.links),
                      node.policy.isDirectory == false else { throw StoreMigrationFailure.invalidIdentity }
                _ = try ColdEraseSchema2NamespacePolicyDataCodecV1.encode(node.policy) // comparison DATA only
                return .init(bytes: raw, metadata: .init(fact: fact, policy: node.policy,
                    sha256: sha, byteCount: UInt64(raw.count)))
            }
            let made = try ColdEraseScratchNotificationCanonicalRecordsV1(manifest: self,
                source: source, operation: operation, store: store, ranges: ranges, scope: scope,
                ownedIDs: record(EraseSchema2ColdNotificationSourceV1.ownedIDsName),
                revocation: record(AppLockNotificationControlStoreV1.eraseName),
                drain: record(EraseSchema2ColdNotificationSourceV1.drainName))
            coldScratchNotificationCanonicalRecords = made // before Range postchecks or first IO
            do {
                try ranges.retainColdScratchNotificationCanonicalRecords(made, manifest: self,
                    source: source, operation: operation, store: store, scope: scope)
            } catch { made.poisonOnUncertainEffect(); throw error }
            records = made
        }
        do {
            try records.requireReservationAssociation(manifest: self, source: source,
                operation: operation, store: store, ranges: ranges, scope: scope)
            try records.beginVerification()
            for _ in 0..<2 {
                try ranges.requireColdScratchNotificationCanonicalRecordsFrame(records,
                    manifest: self, source: source, operation: operation, store: store, scope: scope)
                guard try operation.requireColdScratchRetainedNotificationLineage(manifest: self,
                        store: store, ranges: ranges, scope: scope) === source else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                try requireColdScratchCapsuleNamedFrame(projection: projection,
                    store: store, operation: operation, scope: scope)
                try requireColdScratchNotificationCanonicalRoot(source: source, after: after)
                try requireColdScratchNotificationCanonicalRecord(records, role: .ownedIDs,
                    name: EraseSchema2ColdNotificationSourceV1.ownedIDsName)
                try requireColdScratchNotificationCanonicalRecord(records, role: .revocation,
                    name: AppLockNotificationControlStoreV1.eraseName)
                try requireColdScratchNotificationCanonicalRecord(records, role: .drain,
                    name: EraseSchema2ColdNotificationSourceV1.drainName)
                try requireColdScratchNotificationCanonicalRoot(source: source, after: after)
                try requireColdScratchCapsuleNamedFrame(projection: projection,
                    store: store, operation: operation, scope: scope)
                try ranges.requireColdScratchNotificationCanonicalRecordsFrame(records,
                    manifest: self, source: source, operation: operation, store: store, scope: scope)
            }
            try records.finishVerification()
            return records
        } catch { records.poisonOnUncertainEffect(); throw error }
    }

    private func requireColdScratchNotificationCanonicalRoot(source: EraseSchema2ColdNotificationSourceV1,
        after: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot) throws {
        guard schema2ColdNotificationWitness === source,
              let operations, !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil else { throw StoreMigrationFailure.invalidIdentity }
        if let root = operationsChildren[AppLockNotificationControlStoreV1.rootName] {
            let names = schema2ColdNotificationProjectedNames ?? source.names
            guard names.count <= 10, names == (try namesChecked(in: root)),
                  let nodes = after.notificationControlNodes,
                  nodes.count == names.count + 1,
                  nodes.lazy.filter({ $0.path.isEmpty }).count == 1,
                  let origin = nodes.first(where: { $0.path.isEmpty }),
                  let retainedChild = after.operationsChildren[AppLockNotificationControlStoreV1.rootName],
                  case .directory(let originalRootFact, _) = retainedChild,
                  origin.fullFact == originalRootFact else { throw StoreMigrationFailure.invalidIdentity }
            var held = stat(), named = stat()
            guard Darwin.fstat(root.descriptor, &held) == 0,
                  Darwin.fstatat(operations.descriptor, AppLockNotificationControlStoreV1.rootName,
                    &named, AT_SYMLINK_NOFOLLOW) == 0,
                  EraseColdControlLeafFactV1(held) == EraseColdControlLeafFactV1(named) else {
                throw StoreMigrationFailure.invalidIdentity
            }
            var matcher = ColdEraseScratchNotificationFullFactMatcherV1()
            guard try matcher.matches(originalRootFact, fact: EraseColdControlLeafFactV1(held)),
                  Fact(held) == root.fact else { throw StoreMigrationFailure.invalidIdentity }
        } else {
            guard source.rootIdentity == nil, source.projectedRootIdentity == nil,
                  (schema2ColdNotificationProjectedNames ?? source.names).isEmpty,
                  after.notificationControlNodes == nil,
                  after.operationsChildren[AppLockNotificationControlStoreV1.rootName] == nil else {
                throw StoreMigrationFailure.invalidIdentity
            }
            var absent = stat()
            guard Darwin.fstatat(operations.descriptor, AppLockNotificationControlStoreV1.rootName,
                    &absent, AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
    }

    private func requireColdScratchNotificationCanonicalRecord(
        _ records: ColdEraseScratchNotificationCanonicalRecordsV1,
        role: ColdEraseScratchNotificationCanonicalRecordsV1.Role, name: String) throws {
        try records.beginRole(role)
        guard let operations else { throw StoreMigrationFailure.invalidIdentity }
        let root = operationsChildren[AppLockNotificationControlStoreV1.rootName]
        if let expected = records.expectedRecord(role) {
            guard let root, let node = schema2ColdNotificationFiles[name],
                  node.parent == root.descriptor, node.name == name else { throw StoreMigrationFailure.invalidIdentity }
            func exact() throws {
                var held = stat(), named = stat()
                let heldResult = Darwin.fstat(node.descriptor, &held), heldErrno = errno
                records.recordStat(named: false, returned: heldResult, savedErrno: heldErrno, information: held)
                guard heldResult == 0, EraseColdControlLeafFactV1(held) == expected.fact else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                let namedResult = Darwin.fstatat(root.descriptor, name, &named, AT_SYMLINK_NOFOLLOW), namedErrno = errno
                records.recordStat(named: true, returned: namedResult, savedErrno: namedErrno, information: named)
                guard namedResult == 0, EraseColdControlLeafFactV1(named) == expected.fact,
                      Fact(held) == node.fact else { throw StoreMigrationFailure.invalidIdentity }
            }
            try exact()
            try records.readAndRequire(descriptor: node.descriptor, role: role, expected: expected)
            try exact()
        } else {
            guard schema2ColdNotificationFiles[name] == nil else { throw StoreMigrationFailure.invalidIdentity }
            var absent = stat()
            let result: Int32
            if let root { result = Darwin.fstatat(root.descriptor, name, &absent, AT_SYMLINK_NOFOLLOW) }
            else { result = Darwin.fstatat(operations.descriptor, AppLockNotificationControlStoreV1.rootName,
                &absent, AT_SYMLINK_NOFOLLOW) }
            let savedErrno = errno
            records.recordStat(named: true, returned: result, savedErrno: savedErrno, information: absent)
            guard result != 0, savedErrno == ENOENT else { throw StoreMigrationFailure.invalidIdentity }
        }
        try records.finishRole(role)
    }

    private static func coldScratchNotificationDigestMatches(_ bytes: Data, sha: String) throws -> Bool {
        guard sha.utf8.count == 64 else { throw StoreMigrationFailure.invalidIdentity }
        var iterator = sha.utf8.makeIterator()
        func hex(_ value: UInt8) -> UInt8 { value < 10 ? value + 48 : value + 87 }
        for value in SHA256.hash(data: bytes) {
            guard iterator.next() == hex(value >> 4), iterator.next() == hex(value & 15) else { return false }
        }
        return iterator.next() == nil
    }
}

/// Canonical full11 comparison without an allocated split array/formatter.
/// A matching string is DATA from an existing authentic observation only.
private struct ColdEraseScratchNotificationFullFactMatcherV1 {
    private var field = 0
    private var magnitude: UInt64 = 0
    private var digits = 0
    private var negative = false
    private var leadingZero = false

    mutating func matches(_ text: String, fact: EraseColdControlLeafFactV1) throws -> Bool {
        guard field == 0, text.utf8.count <= 241 else { throw StoreMigrationFailure.invalidIdentity }
        for byte in text.utf8 {
            if byte == 124 { guard try finish(fact) else { return false }; continue }
            if byte == 45 && digits == 0 && !negative { negative = true; continue }
            guard byte >= 48, byte <= 57, digits < 20, !(digits > 0 && leadingZero) else {
                throw StoreMigrationFailure.invalidIdentity
            }
            if digits == 0 { leadingZero = byte == 48 }
            let multiplied = magnitude.multipliedReportingOverflow(by: 10)
            let added = multiplied.partialValue.addingReportingOverflow(UInt64(byte - 48))
            guard !multiplied.overflow, !added.overflow else { throw StoreMigrationFailure.invalidIdentity }
            magnitude = added.partialValue; digits += 1
        }
        return try finish(fact) && field == 11
    }
    private mutating func finish(_ fact: EraseColdControlLeafFactV1) throws -> Bool {
        guard field < 11, digits > 0, !(negative && magnitude == 0),
              !negative || field == 7 || field == 9 else { throw StoreMigrationFailure.invalidIdentity }
        let expected: UInt64
        switch field {
        case 0: guard fact.device >= 0 else { return false }; expected = UInt64(fact.device)
        case 1: expected = UInt64(fact.inode)
        case 2: expected = UInt64(fact.mode)
        case 3: expected = UInt64(fact.user)
        case 4: expected = UInt64(fact.group)
        case 5: expected = UInt64(fact.links)
        case 6: guard fact.size >= 0 else { return false }; expected = UInt64(fact.size)
        case 7: expected = fact.modifiedSeconds.magnitude
        case 8: guard fact.modifiedNanoseconds >= 0 else { return false }; expected = UInt64(fact.modifiedNanoseconds)
        case 9: expected = fact.changedSeconds.magnitude
        case 10: guard fact.changedNanoseconds >= 0 else { return false }; expected = UInt64(fact.changedNanoseconds)
        default: throw StoreMigrationFailure.invalidIdentity
        }
        let expectedNegative = (field == 7 && fact.modifiedSeconds < 0) || (field == 9 && fact.changedSeconds < 0)
        let equal = magnitude == expected && negative == expectedNegative
        field += 1; magnitude = 0; digits = 0; negative = false; leadingZero = false
        return equal
    }
}

/// Authenticates a prospective absent-root cut before a notification
/// directory is created. This record lives in the already held Operations
/// directory, outside the root whose creation it authorizes.
private struct EraseSchema2ColdNotificationRootCreationRecordV1:
    Codable, Equatable {
    let schemaVersion: Int
    let eraseID: String
    let targetGenerationID: String
    let intentSHA256: String
    let preparationSHA256: String
    let supportDevice: UInt64
    let supportInode: UInt64
    let operationsDevice: UInt64
    let operationsInode: UInt64
    let canonicalName: String
    let stagingName: String

    init(intent: EraseIntentV1, preparation: ErasePreparationV2,
        support: stat, operations: stat) throws {
        schemaVersion = 1
        eraseID = intent.eraseID.uuidString.lowercased()
        targetGenerationID = intent.newGenerationID.uuidString.lowercased()
        intentSHA256 = StoreMigrationCanonicalJSONV1.sha256(
            try EraseIntentCodecV1.encode(intent))
        preparationSHA256 = StoreMigrationCanonicalJSONV1.sha256(
            try ErasePreparationCodecV2.encode(preparation))
        supportDevice = UInt64(support.st_dev)
        supportInode = UInt64(support.st_ino)
        operationsDevice = UInt64(operations.st_dev)
        operationsInode = UInt64(operations.st_ino)
        canonicalName = AppLockNotificationControlStoreV1.rootName
        stagingName = EraseSchema2ColdNotificationSourceV1.creationStageName
        try validate()
    }

    func validate() throws {
        guard schemaVersion == 1,
              UUID(uuidString: eraseID)?.uuidString.lowercased() == eraseID,
              UUID(uuidString: targetGenerationID)?.uuidString.lowercased()
                == targetGenerationID,
              [intentSHA256, preparationSHA256].allSatisfy({
                   StoreMigrationCanonicalJSONV1.isLowercaseSHA256($0)
               }),
              supportDevice > 0, supportInode > 0,
              operationsDevice > 0, operationsInode > 0,
              canonicalName == AppLockNotificationControlStoreV1.rootName,
              stagingName == EraseSchema2ColdNotificationSourceV1
                .creationStageName else {
            throw StoreMigrationFailure.invalidIdentity
        }
    }

    func canonicalData() throws -> Data {
        try validate()
        return try StoreMigrationCanonicalJSONV1.encode(self)
    }

    static func decodeCanonical(_ bytes: Data) throws -> Self {
        try StoreMigrationCanonicalJSONV1.decodeCanonicalContract(
            Self.self, from: bytes, validate: { try $0.validate() })
    }
}

