/// Retained raw outcomes of this exact replacement's two sole closes.
/// This owns no operation, Session or lease and grants no effect.
fileprivate final class OriginalEraseWriterPermanentCloseDataV1 {
    struct Entry {
        var descriptor: Int32 = -1
        var entered = false
        var result: Int32?
        var savedErrno: Int32?
        var consumed = false
    }
    struct Storage {
        var original = Entry()
        var temporary = Entry()
        var active: Int32 = 0
        var uncertain = false
    }
    private(set) var storage = Storage()
    func begin(descriptor: Int32, original: Int32, temporary: Int32) throws {
        guard !storage.uncertain, storage.active == 0,
              original >= 0, temporary >= 0, original != temporary else {
            storage.uncertain = true
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if descriptor == original, !storage.original.entered {
            storage.original.descriptor = descriptor; storage.original.entered = true; storage.active = 1
        } else if descriptor == temporary, !storage.temporary.entered {
            storage.temporary.descriptor = descriptor; storage.temporary.entered = true; storage.active = 2
        } else {
            storage.uncertain = true
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func returned(descriptor: Int32, result: Int32, savedErrno: Int32) {
        if storage.active == 1 {
            storage.original.result = result; storage.original.savedErrno = savedErrno
            if storage.original.descriptor != descriptor { storage.uncertain = true }
        } else if storage.active == 2 {
            storage.temporary.result = result; storage.temporary.savedErrno = savedErrno
            if storage.temporary.descriptor != descriptor { storage.uncertain = true }
        } else { storage.uncertain = true }
        if result != 0 { storage.uncertain = true }
    }
    func consume(descriptor: Int32) throws {
        guard !storage.uncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if storage.active == 1, storage.original.descriptor == descriptor,
           storage.original.result == 0, storage.original.savedErrno != nil {
            storage.original.consumed = true
        } else if storage.active == 2, storage.temporary.descriptor == descriptor,
                  storage.temporary.result == 0, storage.temporary.savedErrno != nil {
            storage.temporary.consumed = true
        } else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.active = 0
    }
    func requirePositive(original: Int32, temporary: Int32) throws {
        guard !storage.uncertain, storage.active == 0,
              original >= 0, temporary >= 0, original != temporary,
              storage.original.descriptor == original, storage.original.entered,
              storage.original.result == 0, storage.original.savedErrno != nil, storage.original.consumed,
              storage.temporary.descriptor == temporary, storage.temporary.entered,
              storage.temporary.result == 0, storage.temporary.savedErrno != nil, storage.temporary.consumed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

@MainActor
fileprivate final class OriginalEraseWriterPermanentGReturnV1 {
    struct Storage {
        let previous: OriginalEraseWriterPermanentGReturnV1?
        let descriptor: Int32
        var lockEntered = false
        var lockResult: Int32?
        var lockErrno: Int32?
        var bodyReturned = false
        var bodySucceeded = false
        var scopeSucceeded = false
        var bodyError: Error?
        var boundaryError: Error?
        var retryAllowed = false
        var unlockEntered = false
        var unlockResult: Int32?
        var unlockErrno: Int32?
        var returned = false
    }
    var storage: Storage
    init(previous: OriginalEraseWriterPermanentGReturnV1?, descriptor: Int32) {
        storage = .init(previous: previous, descriptor: descriptor)
    }
    static var declaredStoredCellBytes: UInt64 { UInt64(MemoryLayout<Storage>.stride) }
    func requirePositive(descriptor: Int32) throws {
        var node: OriginalEraseWriterPermanentGReturnV1? = self
        var latest = true
        while let actual = node {
            let s = actual.storage
            guard s.descriptor == descriptor, s.lockEntered, s.lockResult == 0, s.lockErrno != nil,
                  s.unlockEntered, s.unlockResult == 0, s.unlockErrno != nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            if latest {
                guard s.bodyReturned, s.bodySucceeded, s.scopeSucceeded, s.returned,
                      s.bodyError == nil, s.boundaryError == nil, !s.retryAllowed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            } else {
                guard !s.returned, !s.scopeSucceeded, s.retryAllowed,
                      (s.bodyError != nil || s.boundaryError != nil) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            }
            latest = false; node = s.previous
        }
    }
}

@MainActor
fileprivate final class OriginalEraseWriterPermanentBackingReservationV1 {
    struct AllocationCells {
        var reservation: OriginalEraseWriterPermanentBackingReservationV1?
        var publication: OriginalEraseWriterPermanentSettlementV1?
        var release: OriginalEraseWriterPermanentSettlementV1?
    }
    struct ProjectionCells {
        let publication: OriginalEraseWriterPermanentSettlementV1
        let release: OriginalEraseWriterPermanentSettlementV1
    }
    struct Storage {
        weak var registry: GenerationLeaseRegistryV1?
        weak var operation: EraseRouterOperationV1?
        weak var allocation: GenerationWriterAllocationAttemptV1?
        let initialDeclaredBytes: UInt64
        var chargedBytes: UInt64
        var publicationEntered = false
        var releaseEntered = false
        var gBirths: UInt64 = 0
        let selectedControlBackingV1 = OriginalEraseSelectedControlSnapshotBackingV1()
        var uncertain = false
    }
    var storage: Storage
    static var declaredInitialStoredCellBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + MemoryLayout<AllocationCells>.stride + MemoryLayout<ProjectionCells>.stride)
            + 2 * OriginalEraseWriterPermanentSettlementV1.declaredStoredCellBytes
            + 2 * UInt64(MemoryLayout<OriginalEraseWriterPermanentCloseDataV1.Storage>.stride)
            + OriginalEraseSelectedControlSnapshotBackingV1.declaredStoredCellBytes
            + 2 * EraseAbortCheckedSnapshotIOV1.selectedControlOwnerDeclaredCellBytesV1
            + 4 * UInt64(MemoryLayout<OriginalEraseSelectedControlSnapshotOwnerV1.Frame?>.stride)
    }
    init(registry: GenerationLeaseRegistryV1, operation: EraseRouterOperationV1,
        allocation: GenerationWriterAllocationAttemptV1) {
        let bytes = Self.declaredInitialStoredCellBytes
        storage = .init(registry: registry, operation: operation, allocation: allocation,
            initialDeclaredBytes: bytes, chargedBytes: bytes)
    }
    func requireAssociation(registry: GenerationLeaseRegistryV1, operation: EraseRouterOperationV1,
        allocation: GenerationWriterAllocationAttemptV1) throws {
        guard storage.registry === registry, storage.operation === operation, storage.allocation === allocation,
              !storage.uncertain, storage.initialDeclaredBytes == Self.declaredInitialStoredCellBytes else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let (work, overflow) = storage.gBirths.multipliedReportingOverflow(
            by: OriginalEraseWriterPermanentGReturnV1.declaredStoredCellBytes)
        let (expected, addOverflow) = storage.initialDeclaredBytes.addingReportingOverflow(work)
        guard !overflow, !addOverflow, storage.chargedBytes == expected else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
    func chargeGBirth() throws {
        let (count, countOverflow) = storage.gBirths.addingReportingOverflow(1)
        let (bytes, byteOverflow) = storage.chargedBytes.addingReportingOverflow(
            OriginalEraseWriterPermanentGReturnV1.declaredStoredCellBytes)
        guard !storage.uncertain, !countOverflow, !byteOverflow else {
            storage.uncertain = true
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.gBirths = count; storage.chargedBytes = bytes // permanently charged before ctor
    }
}

