extension GenerationLeaseRegistryV1 {
    @MainActor
    static var originalErasePermanentWriterAllocationCellsV1: UInt64 {
        UInt64(MemoryLayout<OriginalEraseWriterPermanentBackingReservationV1.AllocationCells>.stride)
    }
    @MainActor
    static var originalErasePermanentWriterInitialDeclaredCellsV1: UInt64 {
        OriginalEraseWriterPermanentBackingReservationV1.declaredInitialStoredCellBytes
    }
    @MainActor
    static var originalErasePermanentWriterGDeclaredCellsV1: UInt64 {
        OriginalEraseWriterPermanentGReturnV1.declaredStoredCellBytes
    }
    private static func originalErasePermanentTokensV1(_ actual: [GenerationLeaseTokenV1],
        removing removed: GenerationLeaseTokenV1, equals expected: [GenerationLeaseTokenV1]) -> Bool {
        var index = 0, removedCount = 0
        for token in actual {
            if token == removed { removedCount += 1 }
            else {
                guard index < expected.count, expected[index] == token else { return false }
                index += 1
            }
        }
        return removedCount == 1 && index == expected.count
    }
    @MainActor
    private func permanentOriginalEraseOperationV1(
        _ settlement: OriginalEraseWriterPermanentSettlementV1) throws -> EraseRouterOperationV1 {
        guard let operation = settlement.storage.operation else { throw Self.uncertainOwnerFailure() }
        return operation
    }
    @MainActor
    private func beginOriginalErasePermanentSettlementV1(
        allocation: GenerationWriterAllocationAttemptV1, operation: EraseRouterOperationV1,
        oldWriter: GenerationLeaseHandleV1,
        kind: OriginalEraseWriterPermanentSettlementV1.Kind) throws -> OriginalEraseWriterPermanentSettlementV1 {
        try allocation.requirePreparationAcquiring(operation)
        try requireOriginalEraseWriterProjectionSettled(allocation: allocation)
        let reservation: OriginalEraseWriterPermanentBackingReservationV1
        if let retained = allocation.originalErasePermanentBackingV1 {
            reservation = retained
        } else {
            reservation = OriginalEraseWriterPermanentBackingReservationV1(registry: self,
                operation: operation, allocation: allocation)
            allocation.originalErasePermanentBackingV1 = reservation // before settlement birth
        }
        try reservation.requireAssociation(registry: self, operation: operation, allocation: allocation)
        switch kind {
        case .publication:
            guard !reservation.storage.publicationEntered,
                  allocation.originalErasePermanentPublicationV1 == nil else { throw Self.uncertainOwnerFailure() }
            reservation.storage.publicationEntered = true
            let actual = OriginalEraseWriterPermanentSettlementV1(registry: self, operation: operation,
                oldWriter: oldWriter, allocation: allocation, kind: kind, reservation: reservation)
            allocation.originalErasePermanentPublicationV1 = actual
            return actual
        case .oldWriterRelease:
            if let retained = allocation.originalErasePermanentReleaseV1 {
                guard reservation.storage.releaseEntered, allocation.originalEraseOldWriterRetryPending,
                      retained.storage.operation === operation, retained.storage.oldWriter === oldWriter,
                      !retained.storage.issued, !retained.storage.oldWriterReturned else { throw Self.uncertainOwnerFailure() }
                return retained // actual retained-attempt retry; no raw close or unlock replay here
            }
            guard !reservation.storage.releaseEntered else { throw Self.uncertainOwnerFailure() }
            reservation.storage.releaseEntered = true
            let actual = OriginalEraseWriterPermanentSettlementV1(registry: self, operation: operation,
                oldWriter: oldWriter, allocation: allocation, kind: kind, reservation: reservation)
            allocation.originalErasePermanentReleaseV1 = actual
            return actual
        }
    }
    @MainActor
    private func requireOriginalErasePermanentSettlementDataV1(
        _ settlement: OriginalEraseWriterPermanentSettlementV1,
        operation: EraseRouterOperationV1, oldWriter: GenerationLeaseHandleV1,
        allocation: GenerationWriterAllocationAttemptV1, target: GenerationLeaseHandleV1,
        facts: OriginalEraseRetainedWriterProjectionFactsV1) throws {
        let s = settlement.storage
        guard s.registry === self, s.operation === operation, s.oldWriter === oldWriter,
              s.allocation === allocation, s.target === target, s.issued,
              allocation.registry === self, allocation.handle === target,
              allocation.token == target.token, target.token.role == .writer,
              target.token.ownerID == ownerID,
              oldWriter.token.role == .writer, oldWriter.token.ownerID == ownerID,
              target.token.leaseID != oldWriter.token.leaseID,
              allocation.originalErasePermanentBackingV1 === s.reservation,
              let actualFacts = s.facts, let g = s.lastG, let io = s.treeIO,
              let attempt = s.actualAttempt as? TemporalReleaseAttempt,
              attempt.originalBytes == facts.firstRegistryBytes,
              attempt.replacementBytes == facts.afterRegistryBytes,
              attempt.preRenameFullFact == facts.preparedTemporaryFact,
              attempt.originalWriterCreatedTemporaryFact != nil,
              actualFacts.operationsFact == facts.operationsFact,
              actualFacts.firstOperationsDigest == facts.firstOperationsDigest,
              actualFacts.afterOperationsDigest == facts.afterOperationsDigest,
              actualFacts.firstLeaseRootFact == facts.firstLeaseRootFact,
              actualFacts.firstLeaseDigest == facts.firstLeaseDigest,
              actualFacts.afterLeaseRootFact == facts.afterLeaseRootFact,
              actualFacts.afterLeaseDigest == facts.afterLeaseDigest,
              actualFacts.firstLeaseNames == facts.firstLeaseNames,
              actualFacts.afterLeaseNames == facts.afterLeaseNames,
              actualFacts.firstRegistryFact == facts.firstRegistryFact,
              actualFacts.preparedTemporaryFact == facts.preparedTemporaryFact,
              actualFacts.afterRegistryFact == facts.afterRegistryFact,
              actualFacts.firstRegistryBytes == facts.firstRegistryBytes,
              actualFacts.afterRegistryBytes == facts.afterRegistryBytes,
              actualFacts.priorTokens == facts.priorTokens,
              actualFacts.afterTokens == facts.afterTokens else { throw Self.uncertainOwnerFailure() }
        try s.reservation.requireAssociation(registry: self, operation: operation, allocation: allocation)
        try requireOriginalEraseWriterProjectionSettled(allocation: allocation)
        try g.requirePositive(descriptor: mutationLockDescriptor)
        try attempt.requireOriginalErasePermanentCloseDataV1(s.closes)
        try io.requireSettled() // pure actual Snapshot IO uncertainty fence
    }
    @MainActor
    fileprivate func requirePermanentOriginalErasePublicationDataV1(
        _ settlement: OriginalEraseWriterPermanentSettlementV1,
        projection: OriginalEraseRetainedWriterPublicationProjectionV1,
        operation: EraseRouterOperationV1, oldWriter: GenerationLeaseHandleV1,
        allocation: GenerationWriterAllocationAttemptV1, target: GenerationLeaseHandleV1) throws {
        guard allocation.originalEraseWriterPublicationProjection === projection,
              allocation.originalErasePermanentPublicationV1 === settlement,
              settlement.storage.kind == .publication,
              let record = settlement.storage.actualReplacement as? FreshAdoptionReplacement,
              let attempt = settlement.storage.actualAttempt as? TemporalReleaseAttempt,
              record.replacement === attempt, record.token == target.token,
              attempt.token == target.token, !record.closeUncertain,
              record.original == -1, !settlement.storage.oldWriterReturnEntered,
              !settlement.storage.oldWriterReturned,
              projection.priorTokens.contains(oldWriter.token),
              !projection.priorTokens.contains(target.token),
              projection.afterTokens.contains(oldWriter.token),
              projection.afterTokens.contains(target.token),
              Self.originalErasePermanentTokensV1(projection.afterTokens,
                removing: target.token, equals: projection.priorTokens) else {
            throw Self.uncertainOwnerFailure()
        }
        try requireOriginalErasePermanentSettlementDataV1(settlement, operation: operation,
            oldWriter: oldWriter, allocation: allocation, target: target, facts: projection.facts)
    }
    @MainActor
    fileprivate func requirePermanentOriginalEraseReleaseDataV1(
        _ settlement: OriginalEraseWriterPermanentSettlementV1,
        projection: OriginalEraseRetainedOldWriterReleaseProjectionV1,
        operation: EraseRouterOperationV1, oldWriter: GenerationLeaseHandleV1,
        allocation: GenerationWriterAllocationAttemptV1, target: GenerationLeaseHandleV1) throws {
        guard allocation.originalEraseOldWriterReleaseProjection === projection,
              allocation.originalErasePermanentReleaseV1 === settlement,
              settlement.storage.kind == .oldWriterRelease,
              settlement.storage.oldWriterReturnEntered, settlement.storage.oldWriterReturned,
              settlement.storage.actualReplacement == nil,
              let attempt = settlement.storage.actualAttempt as? TemporalReleaseAttempt,
              attempt.token == oldWriter.token,
              attempt.originalWriterAllocationIdentity == ObjectIdentifier(allocation),
              !allocation.originalEraseOldWriterRetryPending,
              allocation.originalEraseOldWriterRetainedAttemptIdentity == nil,
              projection.priorTokens == projection.publication.afterTokens,
              projection.firstOperationsDigest == projection.publication.afterOperationsDigest,
              projection.firstLeaseRootFact == projection.publication.afterLeaseRootFact,
              projection.firstLeaseDigest == projection.publication.afterLeaseDigest,
              projection.firstRegistryBytes == projection.publication.facts.afterRegistryBytes,
              Self.originalErasePermanentTokensV1(projection.priorTokens,
                removing: oldWriter.token, equals: projection.afterTokens),
              projection.afterTokens.contains(target.token),
              !projection.afterTokens.contains(oldWriter.token) else { throw Self.uncertainOwnerFailure() }
        try projection.publication.requirePermanentOriginalEraseWriterData(registry: self,
            operation: operation, oldWriter: oldWriter, targetAllocation: allocation, targetHandle: target)
        try oldWriter.requireClosedForOriginalEraseWriterTransition(registry: self)
        try requireOriginalErasePermanentSettlementDataV1(settlement, operation: operation,
            oldWriter: oldWriter, allocation: allocation, target: target, facts: projection.facts)
    }
}
