    fileprivate init(intent: EraseIntentV1,
        preparation: ErasePreparationV2, roster: EraseSchema2ColdDeletionRosterV1,
        controls: EraseIntentStore.Schema2ColdPostGenerationControlCutV1,
        cut: EraseSchema2ColdCheckedDeletionExecutorV1.Cut,
        pointerBytes: Data, pointerFact: EraseColdControlLeafFactV1,
        retiredBytes: Data, retiredFact: EraseColdControlLeafFactV1,
        manifestBytes: Data, supportFact: EraseColdControlLeafFactV1,
        cachesFact: EraseColdControlLeafFactV1,
        temporaryFact: EraseColdControlLeafFactV1,
        auxiliary: EraseSchema2ColdObservedOriginalAuxiliaryRosterV1,
        manifest: EraseSchema2ColdManifestOwnerV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1) {
        self.intent = intent; self.preparation = preparation
        self.roster = roster; self.controls = controls
        deletedCount = cut.deletedCount; survivorSHA256 = cut.sha256
        generationsFact = cut.generationsFact; generationNames = cut.names
        self.pointerBytes = pointerBytes; self.pointerFact = pointerFact
        self.retiredBytes = retiredBytes; self.retiredFact = retiredFact
        self.manifestBytes = manifestBytes; self.supportFact = supportFact
        self.cachesFact = cachesFact; self.temporaryFact = temporaryFact
        self.auxiliary = auxiliary
        manifestIdentity = ObjectIdentifier(manifest)
        storeIdentity = ObjectIdentifier(store)
        operationIdentity = ObjectIdentifier(operation)
    }

    func requireColdScratchPhysicalRoster(manifest: EraseSchema2ColdManifestOwnerV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1)
        throws -> EraseSchema2ColdAuxiliaryPhysicalRosterV1 {
        try requireBound(manifest: manifest, store: store, operation: operation)
        try operation.requireColdScratchManifestFrame(manifest: manifest,
            store: store, projection: self, scope: scope)
        return auxiliary.roster
    }

