    ]

    func openExisting(applicationSupportURL: URL,
        expectedSupportDevice: dev_t, expectedSupportInode: ino_t,
        phase: EraseIntentPhaseV1?,
        operation: EraseColdPreparationOperationV1) throws {
        try operation.requireSchema2ColdManifestOwner(self)
        guard !opened, !closeAttempted, applicationSupportURL.isFileURL else {
            throw StoreMigrationFailure.invalidIdentity
        }
        opened = true
        erasePhase = phase
        let root = applicationSupportURL.standardizedFileURL
        support = try openDirectory(path: root)
        guard let support, support.fact.device == expectedSupportDevice,
              support.fact.inode == expectedSupportInode else {
            throw StoreMigrationFailure.invalidIdentity
        }
        data = try openDirectory(parent: support, name: "FieldEvidenceData")
        guard let data else { throw StoreMigrationFailure.invalidIdentity }
        var firstDataHeld = stat(), firstDataNamed = stat()
        guard Darwin.fstat(data.descriptor, &firstDataHeld) == 0,
              Darwin.fstatat(support.descriptor, "FieldEvidenceData", &firstDataNamed,
                AT_SYMLINK_NOFOLLOW) == 0,
              Fact(firstDataHeld) == data.fact,
              FullRetiredFact(firstDataHeld) == FullRetiredFact(firstDataNamed),
              coldCapsuleDataIdentity == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        coldCapsuleDataIdentity = AuxiliaryIdentity(firstDataHeld)
        operations = try openOptionalDirectory(parent: support,
            name: "FieldEvidenceOperations")
        if let operations {
            migration = try openOptionalDirectory(parent: operations,
                name: "schema-migration")
            migrationAbsent = migration == nil
        } else {
            operationsAbsent = true
        }
        if operationsAbsent || migrationAbsent {
            guard phase == .sessionActivated || phase == .cleanupComplete else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
        if let migration { try requireMigrationNames(migration) }
        try requireHeldNamed()
    }

    /// Loan the actual already-open parents. The immutable parent identity
    /// remains pinned while the Scratch engine proves its exact mutable image.
    /// No ordinary owner, reopen, or new exclusion is acquired here.
    func withColdScratchRetainedParents<Value>(
        projection: EraseSchema2ColdPostGenerationProjectionV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        _ body: (Int32, Int32, Int32) throws -> Value) throws -> Value {
        try projection.requireBound(manifest: self, store: store, operation: operation)
        try operation.requireColdScratchManifestFrame(manifest: self, store: store,
            projection: projection, scope: scope)
        guard !coldScratchParentLoanInFlight, coldScratchOperationsIdentity == nil,
              let operations, let caches = auxiliaryCachesParent,
              let temporary = auxiliaryTemporaryParent else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireNamed(operations)
        var value = stat()
        guard Darwin.fstat(operations.descriptor, &value) == 0,
              Fact(value) == operations.fact else {
            throw StoreMigrationFailure.invalidIdentity
        }
        coldScratchOperationsIdentity = AuxiliaryIdentity(value)
        coldScratchParentLoanInFlight = true
        do {
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            let result = try body(caches.descriptor, temporary.descriptor, operations.descriptor)
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            coldScratchParentLoanInFlight = false
            return result
        } catch {
            // The loan and all failed owners remain retained; no recapture.
            coldScratchParentsUncertain = true
            operation.poisonColdScratchOwner()
            throw error
        }
    }

    func requireColdScratchRetainedParents(support: Int32, caches: Int32,
        temporary: Int32, operations: Int32,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        guard let projection = postGenerationProjection,
              let store = coldScratchStore, coldScratchParentLoanInFlight,
              self.support?.descriptor == support,
              auxiliaryCachesParent?.descriptor == caches,
              auxiliaryTemporaryParent?.descriptor == temporary,
              self.operations?.descriptor == operations else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: scope)
    }

    /// Metadata slots originate in the authentic named Data/target-manifest
    /// opens. Data's mutable nine fields remain the exact retained own pointer
    /// publication projection; UID/GID and inode identity are the immutable
    /// first open. The target manifest remains the same authenticated full11
    /// leaf and pinned bytes. This getter never captures a new baseline.
    func requireColdScratchCapsuleMetadataOrigins(
        projection: EraseSchema2ColdPostGenerationProjectionV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1)
        throws -> (data: EraseColdControlLeafFactV1,
                   targetManifest: EraseColdControlLeafFactV1) {
        try operation.requireColdScratchRangeOwner(ranges, scope: scope, store: store)
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: scope)
        guard let data, let identity = coldCapsuleDataIdentity,
              let origin = coldCapsuleTargetManifestOrigin,
              let targetLeaf = held.first(where: { $0.descriptor == origin.descriptor }),
              let dataParent = data.parent, let dataName = data.name,
              let manifestParent = targetLeaf.parent, let manifestName = targetLeaf.name,
              capturedManifestBytes == projection.manifestBytes else {
            throw StoreMigrationFailure.invalidIdentity
        }
        var dataHeld = stat(), dataNamed = stat(), manifestHeld = stat(), manifestNamed = stat()
        guard Darwin.fstat(data.descriptor, &dataHeld) == 0,
              Darwin.fstatat(dataParent, dataName, &dataNamed, AT_SYMLINK_NOFOLLOW) == 0,
              Fact(dataHeld) == data.fact, AuxiliaryIdentity(dataHeld) == identity,
              FullRetiredFact(dataHeld) == FullRetiredFact(dataNamed),
              Darwin.fstat(targetLeaf.descriptor, &manifestHeld) == 0,
              Darwin.fstatat(manifestParent, manifestName, &manifestNamed, AT_SYMLINK_NOFOLLOW) == 0,
              FullRetiredFact(manifestHeld) == origin.fact,
              FullRetiredFact(manifestNamed) == origin.fact,
              try readExact(targetLeaf, kind: .journal,
                maximumBytes: 32 * 1_024 * 1_024) == projection.manifestBytes else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: scope)
        var afterData = stat(), afterManifest = stat()
        guard Darwin.fstat(data.descriptor, &afterData) == 0,
              Darwin.fstat(targetLeaf.descriptor, &afterManifest) == 0,
              FullRetiredFact(afterData) == FullRetiredFact(dataHeld),
              FullRetiredFact(afterManifest) == origin.fact else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try operation.requireColdScratchRangeOwner(ranges, scope: scope, store: store)
        return (EraseColdControlLeafFactV1(dataHeld), EraseColdControlLeafFactV1(manifestHeld))
    }

    /// Called only at the existing authenticated target-manifest read, before
    /// any Scratch/capsule Attempt. A second different leaf is a conflict.
    private func retainColdCapsuleTargetManifestOrigin(_ node: Opened, bytes: Data) throws {
        try requireNamed(node)
        var heldValue = stat(), namedValue = stat()
        guard let parent = node.parent, let name = node.name,
              Darwin.fstat(node.descriptor, &heldValue) == 0,
              Darwin.fstatat(parent, name, &namedValue, AT_SYMLINK_NOFOLLOW) == 0,
              Fact(heldValue) == node.fact,
              FullRetiredFact(heldValue) == FullRetiredFact(namedValue),
              heldValue.st_mode & S_IFMT == S_IFREG, heldValue.st_nlink == 1,
              try readExact(node, kind: .journal, maximumBytes: 32 * 1_024 * 1_024) == bytes else {
            throw StoreMigrationFailure.invalidIdentity
        }
        var after = stat(), namedAfter = stat()
        guard Darwin.fstat(node.descriptor, &after) == 0,
              Darwin.fstatat(parent, name, &namedAfter, AT_SYMLINK_NOFOLLOW) == 0,
              FullRetiredFact(after) == FullRetiredFact(heldValue),
              FullRetiredFact(namedAfter) == FullRetiredFact(heldValue) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        if let origin = coldCapsuleTargetManifestOrigin {
            guard origin.descriptor == node.descriptor,
                  origin.fact == FullRetiredFact(heldValue) else {
                throw StoreMigrationFailure.invalidIdentity
            }
        } else {
            coldCapsuleTargetManifestOrigin = (node.descriptor, FullRetiredFact(heldValue))
        }
    }

    /// This proof is deliberately nonrecursive into Store/ranges/image scans.
    /// Those owners separately prove their own exact changed directory prefix.
    func requireColdScratchCapsuleNamedFrame(
        projection: EraseSchema2ColdPostGenerationProjectionV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try operation.requireColdScratchManifestFrame(manifest: self, store: store,
            projection: projection, scope: scope)
        try projection.requireBound(manifest: self, store: store, operation: operation)
        guard opened, !closeAttempted, !coldScratchParentsUncertain,
              uncertainFDs.isEmpty, !uncertainStreamClose,
              enumerationFD == nil, directoryStream == nil,
              !leaseReaderPublicationInFlight, !leaseReaderSettlementInFlight,
              !schema2ColdNotificationMutationInFlight,
              targetLiveOpenState == .settled, !pointerPublicationInFlight,
              postGenerationProjection === projection,
              let support, let operations, let generations,
              let caches = auxiliaryCachesParent,
              let temporary = auxiliaryTemporaryParent,
              let currentPointer, let retiredPointer,
              let operationsIdentity = coldScratchOperationsIdentity else {
            throw StoreMigrationFailure.invalidIdentity
        }
        if let old = coldScratchStore {
            guard old === store else { throw StoreMigrationFailure.invalidIdentity }
        } else { coldScratchStore = store }
        try requireAuxiliaryParent(caches)
        try requireAuxiliaryParent(temporary)
        var heldValue = stat(), namedValue = stat()
        guard Darwin.fstat(support.descriptor, &heldValue) == 0,
              EraseColdControlLeafFactV1(heldValue) == projection.supportFact,
              Darwin.fstat(operations.descriptor, &heldValue) == 0,
              AuxiliaryIdentity(heldValue) == operationsIdentity,
              heldValue.st_mode & S_IFMT == S_IFDIR, heldValue.st_nlink > 0,
              Darwin.fstatat(support.descriptor, "FieldEvidenceOperations",
                &namedValue, AT_SYMLINK_NOFOLLOW) == 0,
              FullRetiredFact(heldValue) == FullRetiredFact(namedValue),
              Darwin.fstat(generations.descriptor, &heldValue) == 0,
              EraseColdControlLeafFactV1(heldValue) == projection.generationsFact,
              try namesChecked(in: generations) == projection.generationNames,
              try readExact(currentPointer, kind: .generationPointer) == projection.pointerBytes,
              try readExact(retiredPointer, kind: .generationPointer) == projection.retiredBytes,
              capturedManifestBytes == projection.manifestBytes else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let scratchPrefix = operations.path.appendingPathComponent("ScratchDataV1").path
        let ingressPrefix = operations.path.appendingPathComponent("ProtectedIngressReceiptsV1").path
        for node in held {
            if node.descriptor == operations.descriptor
                || node.path.path == scratchPrefix || node.path.path.hasPrefix(scratchPrefix + "/")
                || node.path.path == ingressPrefix || node.path.path.hasPrefix(ingressPrefix + "/") {
                continue // exact full prefix belongs to the genuine image owner
            }
            try requireNamed(node)
        }
        if let targetManifest, let capturedTargetManifestBytes {
            guard try readExact(targetManifest, kind: .journal,
                maximumBytes: 32 * 1_024 * 1_024) == capturedTargetManifestBytes else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
        if let targetSource, !targetSource.isCheckedClosed {
            try targetSource.requirePhysicalIdentity()
        }
        try scope.requireNonrecursiveCurrentFrame()
    }

    func requireColdScratchOutside(admission: ColdEraseScratchCleanupInitialAdmissionV1,
        operationsFact: String, operationsNames: [String],
        borrowedParents: ColdEraseScratchBorrowedParentsV1,
        store: EraseIntentStore, operation: EraseColdPreparationOperationV1) throws {
        try admission.requireHeld()
        guard let projection = postGenerationProjection else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let observer = try operation.requireColdScratchFirstObserver(
            manifest: self, store: store, scope: admission.heldScope)
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: admission.heldScope)
        try observer.requireColdScratchOutside(admission: admission,
            operationsFact: operationsFact, operationsNames: operationsNames,
            support: borrowedParents.support, caches: borrowedParents.caches,
            temporary: borrowedParents.temporary, operations: borrowedParents.operations)
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: admission.heldScope)
        try admission.requireHeld()
    }

    /// Immutable path DATA from this same retained physical owner. Native
    /// reserves the real Window before this getter; no descriptor is opened
    /// and no new effect or policy authority is returned.
    func requireColdScratchNotificationReadSupportURL(
        observationScope: ColdEraseScratchNotificationObservationScopeV1) throws -> URL {
        guard !closeAttempted, let support, observationScope.manifest === self,
              schema2ColdNotificationWitness === observationScope.source,
              !schema2ColdNotificationMutationInFlight, !schema2ColdNotificationCaptureInFlight,
              support.path.isFileURL else { throw StoreMigrationFailure.invalidIdentity }
        let operation = try observationScope.source.requireColdScratchObservationOperation(observationScope)
        try observationScope.requireRegisteredAssociation(operation: operation, manifest: self,
            source: observationScope.source, store: observationScope.store,
            ranges: observationScope.ranges, scope: observationScope.heldScope)
        try observationScope.requireCurrentBinding()
        return support.path
    }

    /// A projection of already checked Notification and own Registry effects.
    /// The typed scope and all charged backing are retained before metadata or
    /// comparison IO. Expected full facts come only from immutable first data
    /// or a positively completed own effect, never from a survivor scan.
    func requireColdScratchNotificationAfter(store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        borrowedParents: ColdEraseScratchBorrowedParentsV1,
        observationScope: ColdEraseScratchNotificationObservationScopeV1)
        throws -> EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot {
        let source = observationScope.source, ranges = observationScope.ranges
        guard let projection = postGenerationProjection, let operations,
              schema2ColdNotificationWitness === source,
              observationScope.manifest === self, observationScope.store === store,
              observationScope.heldScope === scope, observationScope.loan === borrowedParents,
              !schema2ColdNotificationMutationInFlight, !schema2ColdNotificationCaptureInFlight,
              schema2ColdNotificationMutationToken == nil,
              coldScratchNotificationAfter == nil, coldScratchNotificationObservationBacking == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try observationScope.requireRegisteredAssociation(operation: operation, manifest: self,
            source: source, store: store, ranges: ranges, scope: scope)
        try ranges.requireColdScratchNotificationObservationScopeFrame(observationScope,
            manifest: self, source: source, store: store, scope: scope)
        let backing = ColdEraseScratchNotificationObservationBackingV1(manifest: self,
            observation: observationScope, source: source)
        coldScratchNotificationObservationBacking = backing // before first field/readback allocation or syscall
        do {
            try observationScope.requireCurrentBinding()
            try backing.requireAssociation(manifest: self, observation: observationScope, source: source)
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            try operation.requireColdScratchNotificationReceipt(manifest: self, store: store, scope: scope)
            try scope.requireCurrentTokenCensus()
            let first = try operation.requireColdScratchFirstSnapshot(store: store, scope: scope)
            let observer = try operation.requireColdScratchFirstObserver(manifest: self, store: store, scope: scope)
            let names = schema2ColdNotificationProjectedNames ?? source.names
            let bytes = schema2ColdNotificationProjectedBytes ?? source.leafBytes
            let facts = schema2ColdNotificationProjectedFacts ?? source.leafFacts
            guard names.count <= 10, names == names.sorted(),
                  names.count == bytes.count, names.count == facts.count,
                  names.count == schema2ColdNotificationFiles.count,
                  let operationsOrigin = schema2ColdNotificationProjectedOperationsFact ?? coldScratchFirstOperationsFact,
                  let leaseOrigin = coldScratchProjectedLeaseFact ?? coldScratchFirstLeaseFact,
                  let lease = operationsChildren["generation-leases"] else {
                throw StoreMigrationFailure.invalidIdentity
            }
            for name in names {
                guard let raw = bytes[name], let fact = facts[name],
                      let pin = schema2ColdNotificationFiles[name] else { throw StoreMigrationFailure.invalidIdentity }
                try coldScratchReadNotificationPin(backing: backing, node: pin,
                    role: .notification(name), fact: fact, bytes: raw)
                try backing.recordLeaf(name: name, fact: Self.coldScratchFullFactString(fact),
                    sha256: StoreMigrationCanonicalJSONV1.sha256(raw))
            }
            let notificationRootFact: String?
            if let root = operationsChildren[AppLockNotificationControlStoreV1.rootName] {
                guard let rootOrigin = schema2ColdNotificationProjectedRootFact ?? source.rootFact else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                try coldScratchRequireNotificationDirectory(backing: backing, node: root,
                    role: .notificationRoot, fact: rootOrigin)
                notificationRootFact = Self.coldScratchFullFactString(rootOrigin)
            } else {
                guard source.rootFact == nil, source.rootIdentity == nil, source.projectedRootIdentity == nil,
                      schema2ColdNotificationProjectedRootFact == nil, names.isEmpty else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                try backing.requireNamedAbsence(role: .notificationRoot, parent: operations.descriptor,
                    name: AppLockNotificationControlStoreV1.rootName)
                notificationRootFact = nil
            }
            try coldScratchRequireNotificationDirectory(backing: backing, node: operations,
                role: .operations, fact: operationsOrigin)
            try coldScratchRequireNotificationDirectory(backing: backing, node: lease,
                role: .registry, fact: leaseOrigin)
            let registryDigest = try coldScratchProjectionIO.postRetiredTree(
                parent: operations.descriptor, name: "generation-leases")
            try coldScratchRequireNotificationDirectory(backing: backing, node: lease,
                role: .registry, fact: leaseOrigin)
            let creation = try coldScratchRequireNotificationCreation(backing: backing)
            backing.creation = creation
            let value = try observer.requireColdNotificationProjected(first: first,
                operationsFact: Self.coldScratchFullFactString(operationsOrigin),
                operationsNames: try namesChecked(in: operations),
                notificationRootFact: notificationRootFact, notificationNames: names,
                notificationLeafFacts: backing.leafFacts, notificationLeafSHA256: backing.leafSHA256,
                registryChild: .directory(rootFact: Self.coldScratchFullFactString(leaseOrigin), digest: registryDigest),
                creationRecord: creation, support: borrowedParents.support,
                caches: borrowedParents.caches, temporary: borrowedParents.temporary,
                observationScope: observationScope)
            try coldScratchProjectionIO.requireSettled()
            try scope.requireCurrentTokenCensus()
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            try ranges.requireColdScratchNotificationObservationScopeFrame(observationScope,
                manifest: self, source: source, store: store, scope: scope)
            try backing.finishCheckedObservation()
            coldScratchNotificationAfter = value // actual two-scan result, once only
            return value
        } catch { backing.poisonOnUncertainObservation(); throw error }
    }

    /// Called only by the genuine typed scope's projection comparison. It
    /// never calls the scope's projection callback or a Ninth scanner.
    func requireColdScratchNotificationObservationProjection(
        observationScope: ColdEraseScratchNotificationObservationScopeV1,
        source: EraseSchema2ColdNotificationSourceV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        first: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
        operationsFact: String, operationsNames: [String], notificationRootFact: String?,
        notificationNames: [String], notificationLeafFacts: [String: String],
        notificationLeafSHA256: [String: String],
        registryChild: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild,
        creationRecord: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild?) throws {
        guard schema2ColdNotificationWitness === source,
              observationScope.manifest === self, observationScope.source === source,
              observationScope.store === store, observationScope.ranges === ranges,
              observationScope.heldScope === scope,
              let backing = coldScratchNotificationObservationBacking,
              let projection = postGenerationProjection, let operations,
              let firstOperations = coldScratchFirstOperationsFact,
              let firstLease = coldScratchFirstLeaseFact,
              let projectedOperations = schema2ColdNotificationProjectedOperationsFact ?? coldScratchFirstOperationsFact,
              let projectedLease = coldScratchProjectedLeaseFact ?? coldScratchFirstLeaseFact else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let operation = try source.requireColdScratchObservationOperation(observationScope)
        try observationScope.requireCurrentBinding()
        try ranges.requireColdScratchNotificationObservationScopeFrame(observationScope,
            manifest: self, source: source, store: store, scope: scope)
        try backing.requireAssociation(manifest: self, observation: observationScope, source: source)
        guard first == (try operation.requireColdScratchFirstSnapshot(store: store, scope: scope)),
              let firstOperationsString = first.operations.rootFact,
              case .directory(let firstLeaseString, _) = first.operationsChildren["generation-leases"] else {
            throw StoreMigrationFailure.invalidIdentity
        }
        var matcher = ColdEraseScratchNotificationFullFactMatcherV1()
        guard try matcher.matches(firstOperationsString, fact: firstOperations),
              try matcher.matches(firstLeaseString, fact: firstLease),
              try matcher.matches(operationsFact, fact: projectedOperations),
              operationsNames == capturedOperationsNames,
              operationsNames == (try namesChecked(in: operations)) else { throw StoreMigrationFailure.invalidIdentity }
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: scope)
        try coldScratchRequireNotificationDirectory(backing: backing, node: operations,
            role: .operations, fact: projectedOperations)
        try coldScratchRequireNotificationProjectionMembers(backing: backing, source: source,
            notificationRootFact: notificationRootFact, notificationNames: notificationNames,
            notificationLeafFacts: notificationLeafFacts, notificationLeafSHA256: notificationLeafSHA256,
            registryChild: registryChild, creationRecord: creationRecord)
        try scope.requireCurrentTokenCensus()
        try requireColdScratchCapsuleNamedFrame(projection: projection,
            store: store, operation: operation, scope: scope)
        try ranges.requireColdScratchNotificationObservationScopeFrame(observationScope,
            manifest: self, source: source, store: store, scope: scope)
        try observationScope.requireCurrentBinding()
    }

    /// The live Scratch admission consumes the already completed initial
    /// comparison backing. Mutable Operations metadata belongs to the
    /// genuine Scratch image/request and is deliberately not compared here.
    func requireColdScratchNotificationOutsideProjection(
        admission: ColdEraseScratchCleanupInitialAdmissionV1,
        source: EraseSchema2ColdNotificationSourceV1, store: EraseIntentStore,
        ranges: ColdEraseScratchPayloadRangesV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        notificationAfter: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot) throws {
        guard schema2ColdNotificationWitness === source,
              admission.ranges === ranges, admission.heldScope === scope,
              admission.notificationAfter == notificationAfter,
              coldScratchNotificationAfter == notificationAfter,
              let backing = coldScratchNotificationObservationBacking,
              let projection = postGenerationProjection else { throw StoreMigrationFailure.invalidIdentity }
        let operation = try source.requireColdScratchOutsideOperation(admission)
        do {
            try admission.requireColdNotificationOutsideBinding()
            try backing.transferToOutside(admission: admission, manifest: self, source: source)
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            let names = schema2ColdNotificationProjectedNames ?? source.names
            guard names.count <= 10, names.count == backing.leafFacts.count,
                  names.count == backing.leafSHA256.count,
                  let registry = notificationAfter.operationsChildren["generation-leases"] else {
                throw StoreMigrationFailure.invalidIdentity
            }
            let notificationRoot: String?
            if let child = notificationAfter.operationsChildren[AppLockNotificationControlStoreV1.rootName] {
                guard case .directory(let fact, _) = child else { throw StoreMigrationFailure.invalidIdentity }
                notificationRoot = fact
            } else { notificationRoot = nil }
            try coldScratchRequireNotificationProjectionMembers(backing: backing, source: source,
                notificationRootFact: notificationRoot, notificationNames: names,
                notificationLeafFacts: backing.leafFacts, notificationLeafSHA256: backing.leafSHA256,
                registryChild: registry,
                creationRecord: notificationAfter.operationsChildren[EraseSchema2ColdNotificationSourceV1.creationRecordName])
            try scope.requireCurrentTokenCensus()
            try requireColdScratchCapsuleNamedFrame(projection: projection,
                store: store, operation: operation, scope: scope)
            try admission.requireColdNotificationOutsideBinding()
        } catch { backing.poisonOnUncertainObservation(); throw error }
    }

    /// Positive data-owner release after the actual borrowed parent loan was
