    /// Retained only for the exact actual handle's maintenance release. A
    /// failed write/rename/fsync never adopts an unrelated preexisting temp.
    private final class TemporalReleaseAttempt {
        let token: GenerationLeaseTokenV1
        let original: Int32
        let originalSnapshot: FileSnapshot
        let originalBytes: Data
        let replacementBytes: Data
        var temporary: Int32 = -1
        var temporaryIdentity: Identity?
        var preparedSnapshot: FileSnapshot?
        var preRenameFullFact: String?
        var originalWriterCreatedTemporaryFact: String?
        var originalWriterFirstImage:
            OriginalEraseRetainedLeaseTreeImageV1?
        var originalWriterFirstRegistryFact: String?
        var selectedControlOriginalPreV1: OriginalEraseSelectedControlSnapshotOwnerV1.Frame?
        var selectedControlEffectFrameV1: OriginalEraseSelectedControlSnapshotOwnerV1.Frame?
        var originalWriterAllocationIdentity: ObjectIdentifier?
        var renamed = false
        var temporaryRemoved = false
        // Completed startup retains concrete issuer-owned resources. These
        // fields do not lend the ordinary descriptor disposal origin.
        var completedSchema2Scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1?
        var completedSchema2OriginalResource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1?
        var completedSchema2TemporaryResource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1?
        func closeForSchema2CompletedStartup(scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
            guard completedSchema2Scope === scope, !closeUncertain,
                  let originalResource = completedSchema2OriginalResource,
                  let temporaryResource = completedSchema2TemporaryResource,
                  originalResource.descriptor == original, temporaryResource.descriptor == temporary,
                  temporary >= 0, renamed, !temporaryRemoved else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            do {
                checkedClosed.insert(original)
                try originalResource.closeChecked()
                try originalResource.requirePositiveClosed()
                checkedClosed.insert(temporary)
                try temporaryResource.closeChecked()
                try temporaryResource.requirePositiveClosed()
                try requireCompletedSchema2PositiveClose(scope: scope)
            } catch { closeUncertain = true; scope.poisonOnUncertainEffect(); throw error }
        }
        func requireCompletedSchema2PositiveClose(scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
            guard completedSchema2Scope === scope, !closeUncertain,
                  let originalResource = completedSchema2OriginalResource,
                  let temporaryResource = completedSchema2TemporaryResource,
                  checkedClosed.contains(original), checkedClosed.contains(temporary),
                  originalResource.descriptor == original, temporaryResource.descriptor == temporary,
                  temporary >= 0, renamed, !temporaryRemoved else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try originalResource.requirePositiveClosed()
            try temporaryResource.requirePositiveClosed()
        }
        private var checkedClosed = Set<Int32>()
        private var closeUncertain = false
        func requireCertainDescriptors() throws {
            guard !closeUncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
        func closeOwnedDescriptorsChecked(permanentData: OriginalEraseWriterPermanentCloseDataV1? = nil) throws {
            guard completedSchema2Scope == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requireCertainDescriptors()
            for descriptor in [original, temporary] where descriptor >= 0 && !checkedClosed.contains(descriptor) {
                checkedClosed.insert(descriptor)
                try permanentData?.begin(descriptor: descriptor, original: original, temporary: temporary)
                let closeResult = Darwin.close(descriptor), closeErrno = errno
                permanentData?.returned(descriptor: descriptor, result: closeResult, savedErrno: closeErrno)
                guard closeResult == 0 else {
                    closeUncertain = true
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try permanentData?.consume(descriptor: descriptor)
            }
        }
        func requireOriginalErasePermanentCloseDataV1(_ data: OriginalEraseWriterPermanentCloseDataV1) throws {
            try requireCertainDescriptors()
            guard checkedClosed.contains(original), checkedClosed.contains(temporary),
                  renamed, preparedSnapshot != nil, preRenameFullFact != nil,
                  originalWriterCreatedTemporaryFact != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try data.requirePositive(original: original, temporary: temporary)
        }
        init(token: GenerationLeaseTokenV1, original: Int32, snapshot: FileSnapshot,
             originalBytes: Data, replacementBytes: Data) {
            self.token = token; self.original = original; originalSnapshot = snapshot
            self.originalBytes = originalBytes; self.replacementBytes = replacementBytes
        }
        deinit {
            guard completedSchema2Scope == nil else { return }
            if !checkedClosed.contains(original) { _ = Darwin.close(original) }
            if temporary >= 0, !checkedClosed.contains(temporary) { _ = Darwin.close(temporary) }
        }
    }
    private final class FreshAdoptionReplacement {
        let token: GenerationLeaseTokenV1
        var original: Int32 = -1
        var originalCloseAttempted = false
        var closeUncertain = false
        var replacement: TemporalReleaseAttempt?
        var completedSchema2Scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1?
        var completedSchema2OriginalResource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1?
        func closeForSchema2CompletedStartup(scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
            guard completedSchema2Scope === scope, !closeUncertain,
                  original < 0, !originalCloseAttempted, let replacement,
                  replacement.completedSchema2Scope === scope,
                  replacement.completedSchema2OriginalResource === completedSchema2OriginalResource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            do { try replacement.closeForSchema2CompletedStartup(scope: scope) }
            catch { closeUncertain = true; scope.poisonOnUncertainEffect(); throw error }
            try requireCompletedSchema2PositiveClose(scope: scope)
        }
        func requireCompletedSchema2PositiveClose(scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
            guard completedSchema2Scope === scope, !closeUncertain,
                  original < 0, !originalCloseAttempted, let replacement,
                  replacement.completedSchema2Scope === scope,
                  replacement.completedSchema2OriginalResource === completedSchema2OriginalResource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try replacement.requireCompletedSchema2PositiveClose(scope: scope)
        }
        var completed = false
        init(token: GenerationLeaseTokenV1) { self.token = token }
        func closeOwnedDescriptorsChecked(permanentData: OriginalEraseWriterPermanentCloseDataV1? = nil) throws {
            guard completedSchema2Scope == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            guard !closeUncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if let replacement {
                do { try replacement.closeOwnedDescriptorsChecked(permanentData: permanentData) }
                catch { closeUncertain = true; throw error }
            }
            if original >= 0, !originalCloseAttempted {
                originalCloseAttempted = true
                guard Darwin.close(original) == 0 else {
                    closeUncertain = true
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
        }
        deinit {
            guard completedSchema2Scope == nil else { return }
            if original >= 0, !originalCloseAttempted { _ = Darwin.close(original) }
        }
    }
