    deinit {
        if completedSchema2RegistryEngine == nil || completedSchema2OrdinaryLifetimeOwnsDescriptors() {
        if !coldSchema2RetirementUncertain && coldSchema2NamespaceCloseAttempt == nil {
        // The Restore transition owns an explicit one-way close. If it began,
        // a deinit fallback could close an ambiguous descriptor twice or
        // silently release an unresolved owner guard.
        if !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) {
        if didCompleteInitialization {
            #if DEBUG
            initializationTesting?.cleanup(.ownerGuardCleanupRequested)
            #endif
            try? removeOwnerGuardIfUnused()
        }
        StoreControlInitializationTestHooksV1.unlockOwner(ownerLockDescriptor,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(ownerLockDescriptor, role: .ownerLock,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(mutationLockDescriptor, role: .mutationLock,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(ownersDescriptor, role: .owners,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(leaseDescriptor, role: .lease,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(operationsDescriptor, role: .operations,
            owner: .object, testing: initializationTesting)
        StoreControlInitializationTestHooksV1.close(rootDescriptor, role: .applicationSupport,
            owner: .object, testing: initializationTesting)
        }
        }
        }
    }

    func acquire(
        epoch: GenerationEpochV1,
        role: GenerationLeaseRoleV1
    ) throws -> GenerationLeaseTokenV1 {
        try epoch.validate()
        // Acquire before G, never upgrade a producer SH handle to EX. Existing
        // callers already under G still use a nonblocking acquisition, so they
        // cannot wait for a normalizer which needs their generation lock.
        // Readers also change the exact source census. Every ordinary lease
        // registration takes SH; the fixed normalization owner uses its
        // separate reader-only registration while already holding EX.
        let temporalRegistration = try acquireTemporalWriterRegistrationActivity()
        defer { temporalRegistration.close() }
        return try withExclusiveGenerationMutationLock {
            try requireNoMigrationReservationLocked()
            var state = try loadStateLocked()
            guard state.leases.count < Self.maximumActiveLeaseCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let owners = Set(state.leases.map(\.ownerID))
            guard owners.contains(ownerID)
                    || owners.count < Self.maximumOwnerCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let leaseID = makeLeaseID()
            guard leaseID != GenerationEpochV1.zeroUUID,
                  !state.leases.contains(where: { $0.leaseID == leaseID }) else {
                throw GenerationLeaseRegistryFailureV1.duplicateLease
            }
            let token = try GenerationLeaseTokenV1(
                leaseID: leaseID,
                ownerID: ownerID,
                epoch: epoch,
                role: role,
                acquiredAt: now()
            )
            var leases = state.leases
            leases.append(token)
            state = try RegistryStateV1(leases: leases)
            try replaceStateLocked(with: state)
            try validateActiveLocked(token, requiredRole: role)
            return token
        }
    }

    func acquireHandle(
        epoch: GenerationEpochV1,
        role: GenerationLeaseRoleV1
    ) throws -> GenerationLeaseHandleV1 {
        try GenerationLeaseHandleV1(
            registry: self,
            token: acquire(epoch: epoch, role: role)
        )
    }

    func release(_ token: GenerationLeaseTokenV1) throws {
        try Self.processMutationLock.withLock {
            guard !completedSchema2StartupReaderPublications.values.contains(where: { $0.token == token }),
                  !completedSchema2StartupWriterPublications.values.contains(where: { $0.token == token }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        try token.validate()
        let temporalRegistration = try acquireTemporalWriterRegistrationActivity()
        defer { temporalRegistration.close() }
        try withExclusiveGenerationMutationLock {
            // A retained normalization release must finish through its exact
            // held-inode attempt; ordinary close/deinit cannot adopt its temp.
            guard temporalReleaseAttempts[token.leaseID] == nil,
                  freshAdoptionReleases[token.leaseID] == nil,
                  !freshWriterPublications.values.contains(where: { $0.token == token }),
                  !freshReaderPublications.values.contains(where: { $0.token == token }),
                  !coldPreparationReaderPublications.values.contains(where: { $0.token == token }),
                  !preparationReaderPublications.values.contains(where: { $0.token == token }),
                  !preparationWriterPublications.values.contains(where: { $0.token == token }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let state = try loadStateLocked()
            guard token.ownerID == ownerID else {
                throw GenerationLeaseRegistryFailureV1.leaseNotActive
            }
            let matches = state.leases.filter {
                $0.leaseID == token.leaseID
            }
            if matches.isEmpty {
                // Idempotent adoption after registry rename succeeded but its
                // directory fsync reported failure.
                guard Darwin.fsync(leaseDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return
            }
            guard matches == [token] else {
                throw GenerationLeaseRegistryFailureV1.leaseNotActive
            }
            let replacement = try RegistryStateV1(
                leases: state.leases.filter { $0.leaseID != token.leaseID }
            )
            try replaceStateLocked(with: replacement)
        }
    }

    func validateActive(
        _ token: GenerationLeaseTokenV1,
        requiredRole: GenerationLeaseRoleV1
    ) throws {
        try withExclusiveGenerationMutationLock {
            try validateActiveLocked(token, requiredRole: requiredRole)
        }
    }

    /// A Restore transition supplies its actual retained wrappers. Epoch or
    /// owner counts would collapse unknown same-epoch leases; compare the full
    /// durable token set under one G interval and refuse any unfinished
    /// publication or migration reservation before source-reader release.
    @MainActor
    func requireExactRestoreTransitionLeases(
        _ expected: [GenerationLeaseHandleV1]
    ) throws {
        guard !expected.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try withExclusiveGenerationMutationLock {
            try requireNoMigrationReservationLocked()
            guard temporalReleaseAttempts.isEmpty,
                  temporalReaderAllocations.isEmpty,
                  freshAdoptionReleases.isEmpty,
                  freshWriterPublications.isEmpty,
                  freshReaderPublications.isEmpty,
                  coldPreparationReaderPublications.isEmpty,
                  preparationReaderPublications.isEmpty,
                  preparationWriterPublications.isEmpty else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            for handle in expected {
                try handle.requireLiveTemporalIdentity(mutationRegistry: self)
                try validateActiveLocked(handle.token,
                    requiredRole: handle.token.role)
            }
            let observed = try observeTemporalRegistryLocked()
            let expectedTokens = try RegistryStateV1(
                leases: expected.map(\.token)).leases
            guard observed.leases == expectedTokens else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    private func retainRestoreExitUncertainDescriptor(_ descriptor: Int32) {
        restoreSourceCloseLock.withLock {
            restoreExitUncertainDescriptors.append(descriptor)
            restoreSourceTerminal = true
        }
    }

    private func withRestoreExitOpened<Value>(parent: Int32?, name: String,
        flags: Int32, optional: Bool = false,
        _ body: (Int32) throws -> Value) throws -> Value? {
        let descriptor = parent.map { Darwin.openat($0, name, flags) }
            ?? Darwin.open(name, flags)
        if descriptor < 0, optional, errno == ENOENT { return nil }
        guard descriptor >= 0 else { throw Self.identityFailure(errorNumber: errno) }
        var closeAttempted = false
        do {
            let value = try body(descriptor)
            closeAttempted = true
            guard Darwin.close(descriptor) == 0 else {
                retainRestoreExitUncertainDescriptor(descriptor)
                throw Self.uncertainOwnerFailure()
            }
            return value
        } catch {
            if !closeAttempted {
                closeAttempted = true
                guard Darwin.close(descriptor) == 0 else {
                    retainRestoreExitUncertainDescriptor(descriptor)
                    throw Self.uncertainOwnerFailure()
                }
            }
            throw error
        }
    }

    private func requireRestoreExitNamedIdentity(parent: Int32,
        name: String, expected: Identity, directory: Bool) throws {
        let flags = O_RDONLY | O_NOFOLLOW |
            (directory ? O_DIRECTORY : 0)
        _ = try withRestoreExitOpened(parent: parent, name: name,
            flags: flags) { descriptor in
            let actual: Identity
            if directory { actual = try Self.directoryIdentity(descriptor) }
            else { actual = try Self.regularFileIdentity(descriptor) }
            guard actual == expected else { throw Self.identityFailure() }
            return ()
        }
    }

    /// The final A exit uses the same held and named identities as verify(),
    /// but every new descriptor has a checked one-attempt disposition.
    private func verifyRestoreExitLocked() throws {
        guard !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) else {
            throw Self.uncertainOwnerFailure()
        }
#if DEBUG
        try requireOriginalEraseAdmission()
        guard eraseAbandonmentLock.withLock({ !eraseAbandonedForColdRestart }) else {
            throw Self.uncertainOwnerFailure()
        }
#endif
        guard try Self.directoryIdentity(rootDescriptor) == rootIdentity,
              try Self.directoryIdentity(operationsDescriptor) == operationsIdentity,
              try Self.directoryIdentity(leaseDescriptor) == leaseIdentity,
              try Self.directoryIdentity(ownersDescriptor) == ownersIdentity,
              try Self.regularFileIdentity(mutationLockDescriptor) == mutationLockIdentity,
              try Self.regularFileIdentity(ownerLockDescriptor) == ownerLockIdentity else {
            throw Self.identityFailure()
        }
        let reopened: Identity? = try withRestoreExitOpened(parent: nil,
            name: applicationSupportURL.path,
            flags: O_RDONLY | O_DIRECTORY | O_NOFOLLOW) { descriptor in
                try Self.directoryIdentity(descriptor)
            }
        guard reopened == rootIdentity else {
            throw Self.identityFailure()
        }
        try requireRestoreExitNamedIdentity(parent: rootDescriptor,
            name: Self.operationsName, expected: operationsIdentity, directory: true)
        try requireRestoreExitNamedIdentity(parent: operationsDescriptor,
            name: Self.leaseDirectoryName, expected: leaseIdentity, directory: true)
        try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
            name: Self.ownerDirectoryName, expected: ownersIdentity, directory: true)
        try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
            name: Self.mutationLockName, expected: mutationLockIdentity, directory: false)
        try requireRestoreExitNamedIdentity(parent: ownersDescriptor,
            name: Self.ownerLockName(ownerID), expected: ownerLockIdentity, directory: false)
    }

    private func readRestoreExitControl(parent: Int32, name: String,
        policyKind: OwnedFileKindV1? = nil,
        policyURL: URL? = nil) throws -> Data? {
        try Self.requireSafeName(name)
        return try withRestoreExitOpened(parent: parent, name: name,
            flags: O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC,
            optional: true) { descriptor in
            let before = try Self.regularFileSnapshot(descriptor)
            if let policyKind, let policyURL {
                _ = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                    policyKind, at: policyURL,
                    retainUncertainDescriptor: retainRestoreExitUncertainDescriptor)
            }
            let data = try Self.readAll(from: descriptor)
            guard try Self.regularFileSnapshot(descriptor) == before,
                  data.count == Int(before.byteCount) else {
                throw Self.identityFailure()
            }
            try requireRestoreExitNamedIdentity(parent: parent,
                name: name, expected: before.identity, directory: false)
            return data
        }
    }

    private func observeRestoreExitRegistryLocked() throws
        -> TemporalGenerationRegistryObservationV1 {
        try verifyRestoreExitLocked()
        let directoryPolicy = try ProtectedFilePolicyV1
            .observeTemporalPolicyWithCheckedClose(
                .stagingDirectory, at: leaseURL,
                retainUncertainDescriptor: retainRestoreExitUncertainDescriptor)
        let url = leaseURL.appendingPathComponent(Self.registryName)
        let data = try readRestoreExitControl(parent: leaseDescriptor,
            name: Self.registryName,
            policyKind: try Self.controlKind(for: Self.registryName),
            policyURL: url)
        guard let data else { throw GenerationLeaseRegistryFailureV1.corruptRegistry }
        let policy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            try Self.controlKind(for: Self.registryName), at: url,
            retainUncertainDescriptor: retainRestoreExitUncertainDescriptor)
        let state: RegistryStateV1
        do { state = try RegistryStateV1.decodeCanonical(from: data) }
        catch { throw GenerationLeaseRegistryFailureV1.corruptRegistry }
        try verifyRestoreExitLocked()
        return TemporalGenerationRegistryObservationV1(
            leases: state.leases, registryBytes: data,
            registryPolicy: policy, directoryPolicy: directoryPolicy)
    }

    /// Mirrors the canonical published/pending relationship of the aggregate
    /// reader. The exact retained Operations FD supplies the parent: no new
    /// reparative controller or unchecked deinit is admitted at final A exit.
    private func requireNoRestoreExitMigrationReservationLocked() throws {
        let observed: StoreAggregateMigrationJournalV1?? = try
            withRestoreExitOpened(parent: operationsDescriptor,
                name: "schema-migration",
                flags: O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC,
                optional: true) { directory in
                let before = try Self.directoryIdentity(directory)
                let currentData = try readRestoreExitControl(parent: directory,
                    name: StoreAggregateMigrationControlV1.name)
                let pendingData = try readRestoreExitControl(parent: directory,
                    name: StoreAggregateMigrationControlV1.temporaryName)
                let current = try currentData.map {
                    try StoreAggregateMigrationJournalV1.decodeCanonical(from: $0)
                }
                let pending = try pendingData.map {
                    try StoreAggregateMigrationJournalV1.decodeCanonical(from: $0)
                }
                if let pending {
                    if let current {
                        if pending.revision == current.revision + 1 {
                            try pending.validateReplacement(of: current)
                        } else if current.revision == pending.revision + 1 {
                            try current.validateReplacement(of: pending)
                        } else { throw StoreMigrationFailure.invalidPhaseTransition }
                    } else {
                        guard pending.phase == .recoveringSource,
                              pending.revision == 0 else {
                            throw StoreMigrationFailure.invalidPhaseTransition
                        }
                    }
                }
                guard try Self.directoryIdentity(directory) == before else {
                    throw Self.identityFailure()
                }
                try requireRestoreExitNamedIdentity(parent: operationsDescriptor,
                    name: "schema-migration", expected: before, directory: true)
                return current ?? pending
            }
        let result = observed ?? nil
        guard result?.reservationIsActive != true else {
            throw Self.uncertainOwnerFailure()
        }
    }

    /// The original reader is removed under the actual A Registry G while B's
    /// exact reader and writer stay published. This one-way attempt owns both
    /// opened inodes before the first write; no ordinary release/reparative
    /// load or unchecked transient control read participates in A's exit.
    @MainActor
    fileprivate func releaseOriginalRestoreSourceReader(
        _ reader: GenerationLeaseHandleV1,
        targetRegistry: GenerationLeaseRegistryV1,
        targetReader: GenerationLeaseHandleV1,
        targetWriter: GenerationLeaseHandleV1,
        reproveSource: () throws -> Void
    ) throws {
        guard targetRegistry !== self,
              restoreExitReaderRelease == nil,
              !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) else {
            throw Self.uncertainOwnerFailure()
        }
        try reader.requireExactRegistry(self)
        try targetReader.requireExactRegistry(targetRegistry)
        try targetWriter.requireExactRegistry(targetRegistry)
        let token = reader.token
        try token.validate()
        guard token.role == .reader, token.ownerID == ownerID,
              targetReader.token.role == .reader,
              targetWriter.token.role == .writer else {
            throw Self.uncertainOwnerFailure()
        }
        let attempt = RestoreExitReaderRelease(token: token)
        restoreExitReaderRelease = attempt
        Self.processMutationLock.lock()
        var generationLocked = false
        var unlockAttempted = false
        var failure: Error?
        do {
            guard flock(mutationLockDescriptor, LOCK_EX) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            generationLocked = true
            try verifyRestoreExitLocked()
            try targetRegistry.verifyRestoreExitLocked()
            try reproveSource()
            try requireNoRestoreExitMigrationReservationLocked()
            let observed = try observeRestoreExitRegistryLocked()
            let beforeTokens = try RegistryStateV1(
                leases: [token, targetReader.token, targetWriter.token]).leases
            guard observed.leases == beforeTokens,
                  temporalReleaseAttempts.isEmpty,
                  temporalReaderAllocations.isEmpty,
                  freshAdoptionReleases.isEmpty,
                  freshWriterPublications.isEmpty,
                  freshReaderPublications.isEmpty,
                  coldPreparationReaderPublications.isEmpty,
                  preparationReaderPublications.isEmpty,
                  preparationWriterPublications.isEmpty,
                  try readRestoreExitControl(parent: leaseDescriptor,
                      name: Self.registryTemporaryName) == nil else {
                throw Self.uncertainOwnerFailure()
            }
            let replacement = try RegistryStateV1(
                leases: [targetReader.token, targetWriter.token]).canonicalData()
            attempt.original = Darwin.openat(leaseDescriptor,
                Self.registryName, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            guard attempt.original >= 0 else { throw Self.mappedFailure() }
            let oldSnapshot = try Self.regularFileSnapshot(attempt.original)
            try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
                name: Self.registryName, expected: oldSnapshot.identity,
                directory: false)
            let oldBytes = try Self.readAll(from: attempt.original)
            guard oldBytes == observed.registryBytes,
                  try Self.regularFileSnapshot(attempt.original) == oldSnapshot else {
                throw Self.identityFailure()
            }
            attempt.temporary = Darwin.openat(leaseDescriptor,
                Self.registryTemporaryName,
                O_RDWR | O_CREAT | O_EXCL | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC,
                mode_t(0o600))
            guard attempt.temporary >= 0 else { throw Self.mappedFailure() }
            let temporaryIdentity = try Self.regularFileIdentity(attempt.temporary)
            try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
                name: Self.registryTemporaryName, expected: temporaryIdentity,
                directory: false)
            // The existing setter applies the frozen control policy only to
            // this newly created, retained temp inode; the final observation
            // uses Restore's checked-close policy reader.
            try protectFile(.generationLeaseControlTemporary,
                parent: leaseDescriptor, directoryURL: leaseURL,
                name: Self.registryTemporaryName, expected: temporaryIdentity)
            guard Darwin.ftruncate(attempt.temporary, 0) == 0,
                  Darwin.lseek(attempt.temporary, 0, SEEK_SET) == 0 else {
                throw Self.mappedFailure()
            }
            try Self.writeAll(replacement, to: attempt.temporary)
            guard Darwin.fsync(attempt.temporary) == 0,
                  Darwin.lseek(attempt.temporary, 0, SEEK_SET) == 0 else {
                throw Self.mappedFailure()
            }
            let prepared = try Self.regularFileSnapshot(attempt.temporary)
            guard try Self.readAll(from: attempt.temporary) == replacement,
                  try Self.regularFileSnapshot(attempt.temporary) == prepared else {
                throw Self.identityFailure()
            }
            _ = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
                .generationLeaseControlTemporary,
                at: leaseURL.appendingPathComponent(Self.registryTemporaryName),
                retainUncertainDescriptor: retainRestoreExitUncertainDescriptor)
            try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
                name: Self.registryName, expected: oldSnapshot.identity,
                directory: false)
            try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
                name: Self.registryTemporaryName, expected: temporaryIdentity,
                directory: false)
            guard try Self.regularFileSnapshot(attempt.original) == oldSnapshot,
                  try Self.regularFileSnapshot(attempt.temporary) == prepared,
                  Darwin.renameat(leaseDescriptor, Self.registryTemporaryName,
                      leaseDescriptor, Self.registryName) == 0,
                  Darwin.fsync(leaseDescriptor) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            let persisted = try observeRestoreExitRegistryLocked()
            guard persisted.registryBytes == replacement else {
                throw Self.uncertainOwnerFailure()
            }
            let expectedPersistedLeases = try RegistryStateV1(
                leases: [targetReader.token, targetWriter.token]).leases
            guard persisted.leases == expectedPersistedLeases else {
                throw Self.uncertainOwnerFailure()
            }
            try requireRestoreExitNamedIdentity(parent: leaseDescriptor,
                name: Self.registryName, expected: temporaryIdentity,
                directory: false)
            try reproveSource()
            try attempt.closeChecked()
            try reader.recordRestoreTransitionRelease(registry: self)
            unlockAttempted = true
            guard flock(mutationLockDescriptor, LOCK_UN) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            generationLocked = false
        } catch {
            failure = error
            restoreSourceCloseLock.withLock { restoreSourceTerminal = true }
        }
        if generationLocked && !unlockAttempted {
            if flock(mutationLockDescriptor, LOCK_UN) != 0 {
                failure = Self.uncertainOwnerFailure()
            }
        }
        Self.processMutationLock.unlock()
        if let failure { throw failure }
        restoreExitReaderRelease = nil
    }

    /// Final A-provider exit after the original source reader's durable close.
    /// B owns distinct open descriptions of the same physical controls; only
    /// this A instance's guard and descriptors are touched. Any failed step
    /// remains terminal, with the actual Registry retained by Router.
    @MainActor
    func closeOriginalRestoreSourceOwner(
        sourceReader: GenerationLeaseHandleV1,
        targetRegistry: GenerationLeaseRegistryV1,
        targetReader: GenerationLeaseHandleV1,
        targetWriter: GenerationLeaseHandleV1
    ) throws {
        guard targetRegistry !== self,
              !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // The reader has already entered its one-way durable release. Even
        // an early identity/census failure here must bar ordinary A reuse and
        // unchecked deinit closure of its still-held control descriptors.
        defer { restoreSourceCloseLock.withLock { restoreSourceTerminal = true } }
        try sourceReader.requireClosedForRestoreTransition(registry: self)
        try verifyRestoreExitLocked()
        try targetRegistry.verifyRestoreExitLocked()
        guard rootIdentity == targetRegistry.rootIdentity,
              operationsIdentity == targetRegistry.operationsIdentity,
              leaseIdentity == targetRegistry.leaseIdentity,
              mutationLockIdentity == targetRegistry.mutationLockIdentity else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try targetReader.requireExactRegistry(targetRegistry)
        try targetWriter.requireExactRegistry(targetRegistry)
        let ownDescriptors = [ownerLockDescriptor, mutationLockDescriptor,
            ownersDescriptor, leaseDescriptor, operationsDescriptor, rootDescriptor]
        let targetDescriptors = [targetRegistry.ownerLockDescriptor,
            targetRegistry.mutationLockDescriptor, targetRegistry.ownersDescriptor,
            targetRegistry.leaseDescriptor, targetRegistry.operationsDescriptor,
            targetRegistry.rootDescriptor]
        guard Set(ownDescriptors).count == ownDescriptors.count,
              Set(ownDescriptors).isDisjoint(with: Set(targetDescriptors)) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }

        Self.processMutationLock.lock()
        var generationLocked = false
        var generationUnlockAttempted = false
        var primaryFailure: Error?
        do {
            guard flock(mutationLockDescriptor, LOCK_EX) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            generationLocked = true
            try verifyRestoreExitLocked()
            try requireNoRestoreExitMigrationReservationLocked()
            let observation = try observeRestoreExitRegistryLocked()
            let expected = try RegistryStateV1(
                leases: [targetReader.token, targetWriter.token]).leases
            guard observation.leases == expected,
                  !observation.leases.contains(where: { $0.ownerID == ownerID }),
                  temporalReleaseAttempts.isEmpty,
                  temporalReaderAllocations.isEmpty,
                  freshAdoptionReleases.isEmpty,
                  freshWriterPublications.isEmpty,
                  freshReaderPublications.isEmpty,
                  coldPreparationReaderPublications.isEmpty,
                  preparationReaderPublications.isEmpty,
                  preparationWriterPublications.isEmpty else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try targetReader.token.validate()
            try targetWriter.token.validate()
            guard targetReader.token.role == .reader,
                  targetWriter.token.role == .writer else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // No ordinary operation may reenter this A Registry from here.
            restoreSourceCloseLock.withLock { restoreSourceTerminal = true }
            try requireRestoreExitNamedIdentity(parent: ownersDescriptor,
                name: Self.ownerLockName(ownerID), expected: ownerLockIdentity,
                directory: false)
            guard Darwin.unlinkat(ownersDescriptor,
                    Self.ownerLockName(ownerID), 0) == 0,
                  Darwin.fsync(ownersDescriptor) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            generationUnlockAttempted = true
            guard flock(mutationLockDescriptor, LOCK_UN) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            generationLocked = false
        } catch {
            primaryFailure = error
            restoreSourceCloseLock.withLock { restoreSourceTerminal = true }
        }
        if generationLocked && !generationUnlockAttempted {
            if flock(mutationLockDescriptor, LOCK_UN) != 0 {
                primaryFailure = Self.uncertainOwnerFailure()
            }
        }
        Self.processMutationLock.unlock()
        if let primaryFailure { throw primaryFailure }

        // The guard was durably unlinked under G. Close exactly A's own open
        // descriptions once; a close error is ambiguous and stops this list.
        guard flock(ownerLockDescriptor, LOCK_UN) == 0 else {
            throw Self.uncertainOwnerFailure()
        }
        for descriptor in ownDescriptors {
            guard Darwin.close(descriptor) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
        }
    }

#if DEBUG
    /// The original operation supplies the captured wrapper. Check that the
    /// exact lease remains active within one G interval before test cold exit.
    func requireCapturedOriginalReaderActiveForV949Fixture(
        _ reader: GenerationLeaseHandleV1
    ) throws {
        guard reader.token.role == .reader else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try withExclusiveGenerationMutationLock {
            try reader.requireLiveTemporalIdentity(mutationRegistry: self)
            try validateActiveLocked(reader.token, requiredRole: .reader)
        }
    }
#endif

    func activeEpochs() throws -> Set<GenerationEpochV1> {
        try withExclusiveGenerationMutationLock {
            let state = try loadStateLocked()
            return Set(state.leases.map(\.epoch))
        }
    }

    private func migrationReservationLocked() throws -> StoreAggregateMigrationJournalV1? {
        guard let control = try StoreAggregateMigrationControlV1(applicationSupportURL: applicationSupportURL),
              let journal = try control.load(), journal.reservationIsActive else { return nil }
        return journal
    }

    fileprivate func requireNoMigrationReservationLocked() throws {
        guard try migrationReservationLocked()?.ownerID == nil else { throw Self.uncertainOwnerFailure() }
    }

    func requireNoMigrationReservation() throws {
        try withExclusiveGenerationMutationLock { try requireNoMigrationReservationLocked() }
    }

    func withNoMigrationReservation<T>(_ operation: () throws -> T) throws -> T {
        try withExclusiveGenerationMutationLock {
            try requireNoMigrationReservationLocked()
            return try operation()
        }
    }

    /// Only this exact operation owner may act inside its durable reservation.
    /// This does not grant an ordinary lease or a canonical writer capability.
    func withMigrationReservation<T>(expected: StoreAggregateMigrationJournalV1,
                                      _ operation: () throws -> T) throws -> T {
        try withExclusiveGenerationMutationLock {
            guard expected.ownerID == ownerID, expected.reservationIsActive,
                  try migrationReservationLocked() == expected else { throw Self.uncertainOwnerFailure() }
            guard let control = try StoreAggregateMigrationControlV1(applicationSupportURL: applicationSupportURL) else {
                throw Self.uncertainOwnerFailure()
            }
            try control.requireNoConflictingIntentAuthority()
            return try operation()
        }
    }

    /// Retains the exact abandoned owner's guard through CAS transfer. A
    /// missing file or process-ID difference is never proof of abandonment.
    func withProvenAbandonedMigrationOwner<T>(ownerID previousOwner: UUID,
                                               _ replaceReservation: () throws -> T) throws -> T {
        try withExclusiveGenerationMutationLock {
            guard previousOwner != ownerID,
                  let expected = try migrationReservationLocked(), expected.ownerID == previousOwner else {
                throw Self.uncertainOwnerFailure()
            }
            let name = Self.ownerLockName(previousOwner)
            let fd = Darwin.openat(ownersDescriptor, name, O_RDWR | O_NONBLOCK | O_NOFOLLOW)
            guard fd >= 0 else { throw Self.uncertainOwnerFailure() }
            defer { _ = Darwin.close(fd) }
            let identity = try Self.regularFileIdentity(fd)
            try requireNamedIdentity(parent: ownersDescriptor, name: name, expected: identity)
            guard flock(fd, LOCK_EX | LOCK_NB) == 0 else { throw Self.uncertainOwnerFailure() }
            defer { _ = flock(fd, LOCK_UN) }
            try requireNamedIdentity(parent: ownersDescriptor, name: name, expected: identity)
            let result = try replaceReservation()
            guard let replacement = try migrationReservationLocked(), replacement.ownerID == ownerID else {
                throw Self.uncertainOwnerFailure()
            }
            try replacement.validateReplacement(of: expected)
            try requireNamedIdentity(parent: ownersDescriptor, name: name, expected: identity)
            let state = try loadStateLocked()
            if !state.leases.contains(where: { $0.ownerID == previousOwner }) {
                guard Darwin.unlinkat(ownersDescriptor, name, 0) == 0, Darwin.fsync(ownersDescriptor) == 0 else {
                    throw Self.uncertainOwnerFailure()
                }
            }
            return result
        }
    }

    /// Removes only leases whose exact owner guard is provably unlocked. A
    /// missing, malformed, or unprobeable owner guard is uncertain and retains
    /// all associated lease records.
    @discardableResult
    func reconcileAbandonedOwners() throws -> Int {
        try withExclusiveGenerationMutationLock {
            let state = try loadStateLocked()
            let reservedOwner = try migrationReservationLocked()?.ownerID
            let owners = Set(state.leases.map(\.ownerID)).subtracting(
                Set([ownerID])
            )
            var abandoned = Set<UUID>()
            var retainedDescriptors: [(UUID, Int32, Identity)] = []
            defer {
                for (_, descriptor, _) in retainedDescriptors {
                    _ = flock(descriptor, LOCK_UN)
                    _ = Darwin.close(descriptor)
                }
            }
            for candidate in owners.sorted(by: Self.idOrder) {
                let name = Self.ownerLockName(candidate)
                let descriptor = Darwin.openat(
                    ownersDescriptor,
                    name,
                    O_RDWR | O_NOFOLLOW
                )
                guard descriptor >= 0 else {
                    throw Self.uncertainOwnerFailure()
                }
                let identity: Identity
                do {
                    identity = try Self.regularFileIdentity(descriptor)
                } catch {
                    _ = Darwin.close(descriptor)
                    throw Self.uncertainOwnerFailure()
                }
                if flock(descriptor, LOCK_EX | LOCK_NB) == 0 {
                    abandoned.insert(candidate)
                    retainedDescriptors.append((candidate, descriptor, identity))
                } else {
                    let failure = errno
                    _ = Darwin.close(descriptor)
                    guard failure == EWOULDBLOCK || failure == EAGAIN else {
                        throw Self.uncertainOwnerFailure()
                    }
                }
            }
            guard !abandoned.isEmpty else {
                guard Darwin.fsync(leaseDescriptor) == 0,
                      Darwin.fsync(ownersDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return 0
            }
            let replacement = try RegistryStateV1(
                leases: state.leases.filter { !abandoned.contains($0.ownerID) }
            )
            try replaceStateLocked(with: replacement)
            for (candidate, descriptor, identity) in retainedDescriptors {
                // The aggregate can reference an owner with no ordinary lease.
                // Its guard survives until exact guarded reservation takeover.
                if candidate == reservedOwner { continue }
                try requireNamedIdentity(
                    parent: ownersDescriptor,
                    name: Self.ownerLockName(candidate),
                    expected: identity
                )
                guard Darwin.unlinkat(
                    ownersDescriptor,
                    Self.ownerLockName(candidate),
                    0
                ) == 0 else {
                    throw Self.uncertainOwnerFailure()
                }
                _ = descriptor
            }
            guard Darwin.fsync(ownersDescriptor) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            return state.leases.count - replacement.leases.count
        }
    }

    /// Serializes lease acquisition/release, canonical commits, current-pointer
    /// publication, and prune. The closure must be synchronous and must not
    /// suspend while the cross-process lock is held.
    func withExclusiveGenerationMutationLock<Value>(
        _ operation: () throws -> Value
    ) throws -> Value {
        let activity = try acquireTemporalWriterRegistrationActivity()
        defer { activity.close() }
        return try withExclusiveGenerationMutationLock(
            verifyAfterOperation: true,
            operation
        )
    }

    /// The only EX-preserving G entry is private and consumes an actual live
    /// exclusive descriptor. Fixed owner operations below use it; ordinary
    /// caller closures cannot bypass their shared admission.
    private func withTemporalNormalizationMutationLock<Value>(
        activity: GenerationTemporalActivityHandleV1,
        _ operation: () throws -> Value
    ) throws -> Value {
        try activity.validateSharedNormalizationRegistry(self)
        return try withExclusiveGenerationMutationLock(verifyAfterOperation: true) {
            try activity.validateSharedNormalizationRegistry(self)
            let result = try operation()
            try activity.validateSharedNormalizationRegistry(self)
            return result
        }
    }

    /// Commit-only lock path. Root authority is proved before the closure and
    /// StaleWriterFenceV1 proves the exact active writer lease/current epoch
    /// inside this same cross-process critical section. Once the synchronous
    /// closure returns, its durable commit must not be reported as an ordinary
    /// failure by a post-commit path reproof; pointer mutations are serialized
    /// by this lock and the next operation performs the normal prevalidation.
    fileprivate func withExclusiveGenerationCommitLock<Value>(
        _ operation: () throws -> Value
    ) throws -> Value {
        let activity = try acquireTemporalWriterRegistrationActivity()
        defer { activity.close() }
        return try withExclusiveGenerationMutationLock(
            verifyAfterOperation: false,
            operation
        )
    }

    private func withExclusiveGenerationMutationLock<Value>(
        verifyAfterOperation: Bool,
        _ operation: () throws -> Value
    ) throws -> Value {
        Self.processMutationLock.lock()
        defer { Self.processMutationLock.unlock() }
        if generationMutationLockDepth == 0 {
            guard flock(mutationLockDescriptor, LOCK_EX) == 0 else {
                throw Self.identityFailure(errorNumber: errno)
            }
        }
        generationMutationLockDepth += 1
        defer {
            generationMutationLockDepth -= 1
            if generationMutationLockDepth == 0 {
                _ = flock(mutationLockDescriptor, LOCK_UN)
            }
        }
        try verify()
        let result = try operation()
        if verifyAfterOperation { try verify() }
        return result
    }

    func loadPruneIntent() throws -> GenerationPruneIntentV1? {
        try withExclusiveGenerationMutationLock {
            try loadControlLocked(
                name: Self.pruneIntentName,
                decode: GenerationPruneIntentV1.decodeCanonical
            )
        }
    }

    func createPruneIntent(_ intent: GenerationPruneIntentV1) throws {
        try intent.validate()
        try withExclusiveGenerationMutationLock {
            guard try !itemExistsLocked(Self.pruneIntentName) else {
                let existing: GenerationPruneIntentV1? = try loadControlLocked(
                    name: Self.pruneIntentName,
                    decode: GenerationPruneIntentV1.decodeCanonical
                )
                guard existing == intent else {
                    throw GenerationLeaseRegistryFailureV1.corruptRegistry
                }
                // This may be a retry after canonical rename succeeded but
                // its parent-directory fsync failed.
                guard Darwin.fsync(leaseDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return
            }
            try publishNewControlLocked(
                name: Self.pruneIntentName,
                temporaryName: Self.pruneIntentTemporaryName,
                data: try intent.canonicalData()
            )
        }
    }

    func replacePruneIntent(
        expected: GenerationPruneIntentV1,
        with replacement: GenerationPruneIntentV1
    ) throws {
        try replacement.validateReplacement(of: expected)
        try withExclusiveGenerationMutationLock {
            let current: GenerationPruneIntentV1? = try loadControlLocked(
                name: Self.pruneIntentName,
                decode: GenerationPruneIntentV1.decodeCanonical
            )
            if current == replacement {
                guard Darwin.fsync(leaseDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return
            }
            guard current == expected else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            try replaceControlLocked(
                name: Self.pruneIntentName,
                temporaryName: Self.pruneIntentTemporaryName,
                data: try replacement.canonicalData()
            )
        }
    }

    /// A prepared intent has not removed bytes or changed the retired pointer.
    /// It may therefore be abandoned when a newly live or uncertain lease
    /// makes the frozen plan ineligible. Later phases are forward-only.
    func discardPreparedPruneIntent(
        expected: GenerationPruneIntentV1
    ) throws {
        guard expected.phase == .prepared else {
            throw GenerationLeaseRegistryFailureV1.invalidContract
        }
        try withExclusiveGenerationMutationLock {
            let current: GenerationPruneIntentV1? = try loadControlLocked(
                name: Self.pruneIntentName,
                decode: GenerationPruneIntentV1.decodeCanonical
            )
            if current == nil {
                guard Darwin.fsync(leaseDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return
            }
            guard current == expected else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            try removeControlLocked(
                name: Self.pruneIntentName,
                expectedData: try expected.canonicalData()
            )
        }
    }

    func loadLastPruneReceipt() throws -> GenerationPruneReceiptV1? {
        try withExclusiveGenerationMutationLock {
            try loadControlLocked(
                name: Self.pruneReceiptName,
                decode: GenerationPruneReceiptV1.decodeCanonical
            )
        }
    }

    /// Publishes a durable receipt for a no-mutation prune decision. Actual
    /// byte removal remains coupled to the exact forward-only intent overload
    /// below, so a caller cannot use this seam to bypass recovery authority.
    func publishPruneReceipt(
        _ receipt: GenerationPruneReceiptV1
    ) throws {
        try receipt.validate()
        guard receipt.disposition != .pruned,
              receipt.prunedEpochs.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.invalidContract
        }
        try withExclusiveGenerationMutationLock {
            guard try !itemExistsLocked(Self.pruneIntentName) else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            let data = try receipt.canonicalData()
            if try itemExistsLocked(Self.pruneReceiptName) {
                try replaceControlLocked(
                    name: Self.pruneReceiptName,
                    temporaryName: Self.pruneReceiptTemporaryName,
                    data: data
                )
            } else {
                try publishNewControlLocked(
                    name: Self.pruneReceiptName,
                    temporaryName: Self.pruneReceiptTemporaryName,
                    data: data
                )
            }
        }
    }

    func publishPruneReceipt(
        _ receipt: GenerationPruneReceiptV1,
        completing intent: GenerationPruneIntentV1
    ) throws {
        try receipt.validate()
        guard receipt.operationID == intent.operationID,
              intent.phase == .receiptPublished,
              receipt.currentEpoch == intent.currentEpoch,
              receipt.retainedEpochs == intent.retainedEpochs,
              receipt.prunedEpochs == intent.candidateEpochs,
              receipt.activeRetainedEpochs == intent.activeRetainedEpochs,
              receipt.uncertainRetainedGenerationIDs
                == intent.uncertainRetainedGenerationIDs,
              receipt.inventoryBeforeSHA256 == intent.inventoryBeforeSHA256,
              receipt.disposition == .pruned else {
            throw GenerationLeaseRegistryFailureV1.invalidContract
        }
        try withExclusiveGenerationMutationLock {
            let current: GenerationPruneIntentV1? = try loadControlLocked(
                name: Self.pruneIntentName,
                decode: GenerationPruneIntentV1.decodeCanonical
            )
            if current == nil {
                let persisted: GenerationPruneReceiptV1? = try loadControlLocked(
                    name: Self.pruneReceiptName,
                    decode: GenerationPruneReceiptV1.decodeCanonical
                )
                guard persisted == receipt else {
                    throw GenerationLeaseRegistryFailureV1.corruptRegistry
                }
                guard Darwin.fsync(leaseDescriptor) == 0 else {
                    throw Self.mappedFailure()
                }
                return
            }
            guard current == intent else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            let data = try receipt.canonicalData()
            if try itemExistsLocked(Self.pruneReceiptName) {
                try replaceControlLocked(
                    name: Self.pruneReceiptName,
                    temporaryName: Self.pruneReceiptTemporaryName,
                    data: data
                )
            } else {
                try publishNewControlLocked(
                    name: Self.pruneReceiptName,
                    temporaryName: Self.pruneReceiptTemporaryName,
                    data: data
                )
            }
            try removeControlLocked(
                name: Self.pruneIntentName,
                expectedData: try intent.canonicalData()
            )
        }
    }

    fileprivate func validateActiveLocked(
        _ token: GenerationLeaseTokenV1,
        requiredRole: GenerationLeaseRoleV1
    ) throws {
        try token.validate()
        guard token.role == requiredRole else {
            throw GenerationLeaseRegistryFailureV1.wrongLeaseRole
        }
        let matches = try loadStateLocked().leases.filter {
            $0.leaseID == token.leaseID
        }
        guard matches == [token] else {
            throw GenerationLeaseRegistryFailureV1.leaseNotActive
        }
    }

    private func ensureRegistryLocked() throws {
        guard try !itemExistsLocked(Self.registryName) else {
            // Adopt an already-published first registry only after closing a
            // possible rename-success/directory-fsync-failure ambiguity.
            guard Darwin.fsync(leaseDescriptor) == 0 else {
                throw Self.mappedFailure()
            }
            return
        }
        try publishNewControlLocked(
            name: Self.registryName,
            temporaryName: Self.registryTemporaryName,
            data: try RegistryStateV1(leases: []).canonicalData()
        )
    }

    private func removeOwnerGuardIfUnused() throws {
        let activity = try acquireTemporalWriterRegistrationActivity()
        defer { activity.close() }
        try withExclusiveGenerationMutationLock(
            verifyAfterOperation: false
        ) {
            let state = try loadStateLocked()
            guard !state.leases.contains(where: { $0.ownerID == ownerID }),
                  try migrationReservationLocked()?.ownerID != ownerID else {
                return
            }
            try requireNamedIdentity(
                parent: ownersDescriptor,
                name: Self.ownerLockName(ownerID),
                expected: ownerLockIdentity
            )
            guard Darwin.unlinkat(
                ownersDescriptor,
                Self.ownerLockName(ownerID),
                0
            ) == 0 else {
                throw Self.identityFailure(errorNumber: errno)
            }
            guard Darwin.fsync(ownersDescriptor) == 0 else {
                throw Self.identityFailure(errorNumber: errno)
            }
        }
    }

    private func loadStateLocked() throws -> RegistryStateV1 {
        guard let value: RegistryStateV1 = try loadControlLocked(
            name: Self.registryName,
            decode: RegistryStateV1.decodeCanonical
        ) else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        return value
    }

    private func replaceStateLocked(with replacement: RegistryStateV1) throws {
        try replacement.validate()
        try replaceControlLocked(
            name: Self.registryName,
            temporaryName: Self.registryTemporaryName,
            data: try replacement.canonicalData()
        )
    }

    private func reconcileConservativeTemporariesLocked() throws {
        for name in [
            Self.registryTemporaryName,
            Self.pruneIntentTemporaryName,
            Self.pruneReceiptTemporaryName,
        ] {
            // A temporary is never authority. Keeping the current published
            // file conservatively retains leases and prune intent state. The
            // absent path also fsyncs the parent to close a prior unlink whose
            // directory fsync reported failure.
            try removeControlLocked(name: name, expectedData: nil)
        }
    }

    private func loadControlLocked<Value>(
        name: String,
        decode: (Data) throws -> Value
    ) throws -> Value? {
        guard try itemExistsLocked(name) else { return nil }
        let captured = try readControlLocked(name: name)
        do {
            return try decode(captured.data)
        } catch {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
    }

    private func createControlLocked(
        name: String,
        data: Data,
        kind: OwnedFileKindV1
    ) throws {
        try Self.requireSafeName(name)
        guard data.count <= Self.maximumControlFileBytes,
              try !itemExistsLocked(name) else {
            throw Self.identityFailure()
        }
        let descriptor = Darwin.openat(
            leaseDescriptor,
            name,
            O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
            mode_t(0o600)
        )
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        var cleanupSnapshot: FileSnapshot?
        var permitsProtectionMetadataDrift = false
        var completed = false
        defer {
            _ = Darwin.close(descriptor)
            if !completed,
               let cleanupSnapshot,
               let namedSnapshot = try? Self.namedRegularFileSnapshot(
                   parent: leaseDescriptor,
                   name: name
               ),
               namedSnapshot.identity == cleanupSnapshot.identity,
               namedSnapshot.byteCount == cleanupSnapshot.byteCount,
               (permitsProtectionMetadataDrift
                    || namedSnapshot == cleanupSnapshot) {
                if Darwin.unlinkat(leaseDescriptor, name, 0) == 0 {
                    _ = Darwin.fsync(leaseDescriptor)
                }
            }
        }
        let initialSnapshot = try Self.regularFileSnapshot(descriptor)
        cleanupSnapshot = initialSnapshot
        permitsProtectionMetadataDrift = true
        let identity = initialSnapshot.identity
        // Protection and backup exclusion are established while the file is
        // still empty. A protected-data failure therefore cannot leave
        // plaintext control bytes at the canonical or temporary name.
        try protectFile(
            kind,
            parent: leaseDescriptor,
            directoryURL: leaseURL,
            name: name,
            expected: identity
        )
        permitsProtectionMetadataDrift = false
        cleanupSnapshot = try Self.regularFileSnapshot(descriptor)
        try Self.writeAll(data, to: descriptor)
        guard Darwin.fsync(descriptor) == 0 else { throw Self.mappedFailure() }
        cleanupSnapshot = try Self.regularFileSnapshot(descriptor)
        guard Darwin.fsync(leaseDescriptor) == 0 else {
            throw Self.mappedFailure()
        }
        guard try readControlLocked(name: name).data == data else {
            throw Self.identityFailure()
        }
        completed = true
    }

    /// Publishes a previously absent control through a fully protected,
    /// fsynced temporary. A retry after rename success and directory-fsync
    /// failure adopts only the exact desired canonical bytes.
    private func publishNewControlLocked(
        name: String,
        temporaryName: String,
        data: Data
    ) throws {
        try Self.requireSafeName(name)
        try Self.requireSafeName(temporaryName)
        guard data.count <= Self.maximumControlFileBytes,
              name != temporaryName else {
            throw Self.identityFailure()
        }
        if name == Self.registryName,
           !((try RegistryStateV1.decodeCanonical(from: data)).leases.isEmpty) {
            // The first registry publication is also a lease insertion.
            // It must not evade the durable C05 admission seal merely
            // because no canonical registry file existed yet.
            try requireNoDrainedC05PreparationForLeaseInsertionLocked()
        }

        if try itemExistsLocked(name) {
            let current = try readControlLocked(name: name)
            guard current.data == data else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            if try itemExistsLocked(temporaryName) {
                try removeControlLocked(
                    name: temporaryName,
                    expectedData: data
                )
            }
            guard Darwin.fsync(leaseDescriptor) == 0 else {
                throw Self.mappedFailure()
            }
            return
        }

        if try itemExistsLocked(temporaryName) {
            guard try readControlLocked(name: temporaryName).data == data else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
        } else {
            try createControlLocked(
                name: temporaryName,
                data: data,
                kind: .generationLeaseControlTemporary
            )
        }

        let temporary = try readControlLocked(name: temporaryName)
        guard temporary.data == data,
              try !itemExistsLocked(name) else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: temporaryName,
            expected: temporary.identity
        )
        guard Darwin.renameatx_np(
            leaseDescriptor,
            temporaryName,
            leaseDescriptor,
            name,
            UInt32(RENAME_EXCL)
        ) == 0 else {
            throw Self.mappedFailure()
        }
        // If this fsync fails, canonical already contains complete desired
        // bytes and the next identical call takes the adoption path above.
        guard Darwin.fsync(leaseDescriptor) == 0 else {
            throw Self.mappedFailure()
        }
        let persisted = try readControlLocked(name: name)
        guard persisted.identity == temporary.identity,
              persisted.data == data,
              try !itemExistsLocked(temporaryName) else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
    }

    private func replaceControlLocked(
        name: String,
        temporaryName: String,
        data: Data
    ) throws {
        try Self.requireSafeName(name)
        try Self.requireSafeName(temporaryName)
        guard data.count <= Self.maximumControlFileBytes,
              name != temporaryName,
              try itemExistsLocked(name) else {
            throw Self.identityFailure()
        }
        let expected = try readControlLocked(name: name)
        if name == Self.registryName, expected.data != data {
            let old = try RegistryStateV1.decodeCanonical(from: expected.data)
            let next = try RegistryStateV1.decodeCanonical(from: data)
            let oldIDs = Set(old.leases.map(\.leaseID))
            if next.leases.contains(where: { !oldIDs.contains($0.leaseID) }) {
                // All ordinary and temporal replacement insertions converge
                // here while G is held. A durable DRAINED marker seals new
                // leases across the later G-unlocked Store actor await.
                try requireNoDrainedC05PreparationForLeaseInsertionLocked()
            }
        }
        if expected.data == data {
            if try itemExistsLocked(temporaryName) {
                try removeControlLocked(
                    name: temporaryName,
                    expectedData: data
                )
            }
            guard Darwin.fsync(leaseDescriptor) == 0 else {
                throw Self.mappedFailure()
            }
            return
        }
        if try itemExistsLocked(temporaryName) {
            guard try readControlLocked(name: temporaryName).data == data else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
        } else {
            try createControlLocked(
                name: temporaryName,
                data: data,
                kind: .generationLeaseControlTemporary
            )
        }
        let temporary = try readControlLocked(name: temporaryName)
        guard temporary.data == data else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: name,
            expected: expected.identity
        )
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: temporaryName,
            expected: temporary.identity
        )
        guard Darwin.renameat(
            leaseDescriptor,
            temporaryName,
            leaseDescriptor,
            name
        ) == 0 else {
            throw Self.mappedFailure()
        }
        // Rename has committed a complete protected file. A directory-fsync
        // failure is intentionally retryable: the desired-data branch above
        // recognizes this exact post-rename state without another mutation.
        guard Darwin.fsync(leaseDescriptor) == 0 else {
            throw Self.mappedFailure()
        }
        let persisted = try readControlLocked(name: name)
        guard persisted.identity == temporary.identity,
              persisted.data == data else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
    }

    private func withCheckedC05AdmissionProbe<T>(
        _ descriptor: Int32,
        _ body: (Int32) throws -> T
    ) throws -> T {
        guard eraseC05AdmissionProbeUncertainDescriptors.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let result = Result { try body(descriptor) }
        guard Darwin.close(descriptor) == 0 else {
            eraseC05AdmissionProbeUncertainDescriptors.append(descriptor)
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return try result.get()
    }

    /// An observation, never a repair. It is called under G at the common
    /// registry insertion edge; malformed or ambiguous controls deny a new
    /// token. The cold operation's retained reader remains the authority for
    /// advancing the preparation itself.
    private func requireNoDrainedC05PreparationForLeaseInsertionLocked()
        throws {
        guard eraseC05AdmissionProbeUncertainDescriptors.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let eraseFD = Darwin.openat(rootDescriptor, "FieldEvidenceErase",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        if eraseFD < 0 {
            guard errno == ENOENT else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return
        }
        try withCheckedC05AdmissionProbe(eraseFD) { heldErase in
            var directory = stat(), namedDirectory = stat(), temp = stat()
            guard Darwin.fstat(heldErase, &directory) == 0,
                  (directory.st_mode & S_IFMT) == S_IFDIR,
                  Darwin.fstatat(rootDescriptor, "FieldEvidenceErase",
                      &namedDirectory, AT_SYMLINK_NOFOLLOW) == 0,
                  directory.st_dev == namedDirectory.st_dev,
                  directory.st_ino == namedDirectory.st_ino,
                  Darwin.fstatat(heldErase, ".preparation.json.next",
                      &temp, AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let rootPolicy = try ProtectedFilePolicyV1.observeTemporalPolicy(
                .stagingDirectory,
                at: applicationSupportURL.appendingPathComponent(
                    "FieldEvidenceErase", isDirectory: true))
            guard rootPolicy.state == .strictComplete,
                  rootPolicy.device == UInt64(directory.st_dev),
                  rootPolicy.inode == UInt64(directory.st_ino) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let preparationFD = Darwin.openat(heldErase,
                "preparation.json", O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            if preparationFD < 0 {
                guard errno == ENOENT else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                return
            }
            try withCheckedC05AdmissionProbe(preparationFD) { heldPreparation in
                var leaf = stat(), namedLeaf = stat()
                guard Darwin.fstat(heldPreparation, &leaf) == 0,
                      (leaf.st_mode & S_IFMT) == S_IFREG,
                      leaf.st_nlink == 1, leaf.st_size > 0,
                      leaf.st_size <= 96 * 1024 * 1024,
                      Darwin.fstatat(heldErase, "preparation.json",
                          &namedLeaf, AT_SYMLINK_NOFOLLOW) == 0,
                      leaf.st_dev == namedLeaf.st_dev,
                      leaf.st_ino == namedLeaf.st_ino,
                      Darwin.lseek(heldPreparation, 0, SEEK_SET) == 0 else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                let policy = try ProtectedFilePolicyV1.observeTemporalPolicy(
                    .journal,
                    at: applicationSupportURL
                        .appendingPathComponent("FieldEvidenceErase")
                        .appendingPathComponent("preparation.json"))
                guard policy.state == .strictComplete,
                      policy.device == UInt64(leaf.st_dev),
                      policy.inode == UInt64(leaf.st_ino) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                var bytes = Data(count: Int(leaf.st_size))
                try bytes.withUnsafeMutableBytes { raw in
                    var offset = 0
                    while offset < raw.count {
                        let count = Darwin.read(heldPreparation,
                            raw.baseAddress!.advanced(by: offset),
                            raw.count - offset)
                        if count < 0 && errno == EINTR { continue }
                        guard count > 0 else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                        offset += count
                    }
                }
                var after = stat(), namedAfter = stat()
                guard Darwin.fstat(heldPreparation, &after) == 0,
                      Darwin.fstatat(heldErase, "preparation.json",
                          &namedAfter, AT_SYMLINK_NOFOLLOW) == 0,
                      leaf.st_dev == after.st_dev,
                      leaf.st_ino == after.st_ino,
                      leaf.st_size == after.st_size,
                      after.st_dev == namedAfter.st_dev,
                      after.st_ino == namedAfter.st_ino else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                let preparation = try ErasePreparationCodecV2.decode(bytes)
                if preparation.c05JobDrainV3?.phase == .drained
                    || preparation.c05JobDrainV3?.phase == .rootRemoved {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
        }
    }

    private func removeControlLocked(
        name: String,
        expectedData: Data?
    ) throws {
        guard try itemExistsLocked(name) else {
            // A retry can observe absence after unlink succeeded but its
            // directory fsync failed. Close that durability ambiguity before
            // treating the removal as idempotently complete.
            guard Darwin.fsync(leaseDescriptor) == 0 else {
                throw Self.mappedFailure()
            }
            return
        }
        let captured = try readControlLocked(name: name)
        if let expectedData, captured.data != expectedData {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: name,
            expected: captured.identity
        )
        guard Darwin.unlinkat(leaseDescriptor, name, 0) == 0,
              Darwin.fsync(leaseDescriptor) == 0 else {
            throw Self.mappedFailure()
        }
    }

    private func readControlLocked(
        name: String
    ) throws -> (data: Data, identity: Identity) {
        try Self.requireSafeName(name)
        let descriptor = Darwin.openat(
            leaseDescriptor,
            name,
            O_RDONLY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        defer { _ = Darwin.close(descriptor) }
        let before = try Self.regularFileSnapshot(descriptor)
        try verifyControlFilePolicy(
            try Self.controlKind(for: name),
            name: name,
            expected: before.identity
        )
        let data = try Self.readAll(from: descriptor)
        let after = try Self.regularFileSnapshot(descriptor)
        guard before == after,
              data.count == Int(before.byteCount) else {
            throw Self.identityFailure()
        }
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: name,
            expected: before.identity
        )
        return (data, before.identity)
    }

    private func itemExistsLocked(_ name: String) throws -> Bool {
        try Self.itemExists(parent: leaseDescriptor, name: name)
    }

    private func protectDirectory(
        _ kind: OwnedFileKindV1,
        at url: URL
    ) throws {
        try ProtectedFilePolicyV1.applyAndVerify(
            kind,
            at: url,
            authorityCheck: { [self] in try verify() }
        )
    }

    private func protectFile(
        _ kind: OwnedFileKindV1,
        parent: Int32,
        directoryURL: URL,
        name: String,
        expected: Identity, causalIO: EraseAbortCheckedSnapshotIOV1? = nil
    ) throws {
        if let io = causalIO {
            try io.selectedControlSemanticCallV1 {
                try ProtectedFilePolicyV1.applyAndVerify(kind,
                    at: directoryURL.appendingPathComponent(name), authorityCheck: { [self] in
                        try verify(causalIO: io)
                        try requireNamedIdentity(parent: parent, name: name, expected: expected, causalIO: io)
                    })
            }
            return
        }
        try ProtectedFilePolicyV1.applyAndVerify(
            kind,
            at: directoryURL.appendingPathComponent(name),
            authorityCheck: { [self] in
                try verify()
                try requireNamedIdentity(
                    parent: parent,
                    name: name,
                    expected: expected
                )
            }
        )
    }

    private func verifyControlFilePolicy(
        _ kind: OwnedFileKindV1,
        name: String,
        expected: Identity
    ) throws {
        try verify()
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: name,
            expected: expected
        )
        try ProtectedFilePolicyV1.verify(
            kind,
            at: leaseURL.appendingPathComponent(name)
        )
        try verify()
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: name,
            expected: expected
        )
    }

    private func verify(causalIO: EraseAbortCheckedSnapshotIOV1? = nil) throws {
        guard !coldSchema2RetirementUncertain else { throw Self.uncertainOwnerFailure() }
        guard !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) else {
            throw Self.uncertainOwnerFailure()
        }
        guard !originalEraseRetainedReaderAbsenceUncertain,
              !originalEraseRetainedReaderEffectUncertain,
              !originalEraseWriterProjectionUncertain,
              !originalErasePointerEffectUncertain,
              originalEraseRetainedReaderPolicyUncertainDescriptors.isEmpty else {
            throw Self.uncertainOwnerFailure()
        }
#if DEBUG
        try requireOriginalEraseAdmission()
        guard eraseAbandonmentLock.withLock({ !eraseAbandonedForColdRestart }) else {
            throw Self.uncertainOwnerFailure()
        }
#endif
        if let causalIO { return try verifySelectedControlCausalV1(io: causalIO) }
        if isEraseC05ColdOwner {
            guard !eraseC05ColdMutationUncertain else {
                throw Self.uncertainOwnerFailure()
            }
            // The exact cold owner already holds every directory/control FD.
            // Reopening the root here would create an unretained descriptor on
            // a post-marker failure, so use held and named identity only.
            var namedRoot = stat()
            guard Darwin.lstat(applicationSupportURL.path, &namedRoot) == 0,
                  Identity(namedRoot) == rootIdentity,
                  try Self.directoryIdentity(rootDescriptor) == rootIdentity,
                  try Self.directoryIdentity(operationsDescriptor) == operationsIdentity,
                  try Self.directoryIdentity(leaseDescriptor) == leaseIdentity,
                  try Self.directoryIdentity(ownersDescriptor) == ownersIdentity,
                  try Self.regularFileIdentity(mutationLockDescriptor) == mutationLockIdentity,
                  try Self.regularFileIdentity(ownerLockDescriptor) == ownerLockIdentity else {
                throw Self.identityFailure()
            }
            try requireNamedDirectoryIdentity(parent: rootDescriptor,
                name: Self.operationsName, expected: operationsIdentity)
            try requireNamedDirectoryIdentity(parent: operationsDescriptor,
                name: Self.leaseDirectoryName, expected: leaseIdentity)
            try requireNamedDirectoryIdentity(parent: leaseDescriptor,
                name: Self.ownerDirectoryName, expected: ownersIdentity)
            try requireNamedIdentity(parent: leaseDescriptor,
                name: Self.mutationLockName, expected: mutationLockIdentity)
            try requireNamedIdentity(parent: ownersDescriptor,
                name: Self.ownerLockName(ownerID), expected: ownerLockIdentity)
            return
        }
        if isEraseSchema2ColdOwner {
            guard eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
                  !eraseSchema2ColdMutationUncertain,
                  coldSchema2NamespaceCloseAttempt == nil else {
                throw Self.uncertainOwnerFailure()
            }
            // The operation already retains the exact opened controls. Do not
            // acquire an untracked transient descriptor to reprove them.
            var named = stat()
            guard Darwin.lstat(applicationSupportURL.path, &named) == 0,
                  Identity(named) == rootIdentity,
                  try Self.directoryIdentity(rootDescriptor) == rootIdentity,
                  try Self.directoryIdentity(operationsDescriptor)
                    == operationsIdentity,
                  try Self.directoryIdentity(leaseDescriptor) == leaseIdentity,
                  try Self.directoryIdentity(ownersDescriptor) == ownersIdentity,
                  try Self.regularFileIdentity(mutationLockDescriptor)
                    == mutationLockIdentity,
                  try Self.regularFileIdentity(ownerLockDescriptor)
                    == ownerLockIdentity else {
                throw Self.identityFailure()
            }
            for (parent, name, expected) in [
                (rootDescriptor, Self.operationsName, operationsIdentity),
                (operationsDescriptor, Self.leaseDirectoryName, leaseIdentity),
                (leaseDescriptor, Self.ownerDirectoryName, ownersIdentity),
                (leaseDescriptor, Self.mutationLockName, mutationLockIdentity),
                (ownersDescriptor, Self.ownerLockName(ownerID), ownerLockIdentity),
            ] {
                guard Darwin.fstatat(parent, name, &named,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      Identity(named) == expected else {
                    throw Self.identityFailure()
                }
            }
            return
        }
        let reopenedRoot = Darwin.open(
            applicationSupportURL.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard reopenedRoot >= 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        defer { _ = Darwin.close(reopenedRoot) }
        guard try Self.directoryIdentity(rootDescriptor) == rootIdentity,
              try Self.directoryIdentity(reopenedRoot) == rootIdentity,
              try Self.directoryIdentity(operationsDescriptor)
                == operationsIdentity,
              try Self.directoryIdentity(leaseDescriptor) == leaseIdentity,
              try Self.directoryIdentity(ownersDescriptor) == ownersIdentity,
              try Self.regularFileIdentity(mutationLockDescriptor)
                == mutationLockIdentity,
              try Self.regularFileIdentity(ownerLockDescriptor)
                == ownerLockIdentity else {
            throw Self.identityFailure()
        }
        try requireNamedDirectoryIdentity(
            parent: rootDescriptor,
            name: Self.operationsName,
            expected: operationsIdentity
        )
        try requireNamedDirectoryIdentity(
            parent: operationsDescriptor,
            name: Self.leaseDirectoryName,
            expected: leaseIdentity
        )
        try requireNamedDirectoryIdentity(
            parent: leaseDescriptor,
            name: Self.ownerDirectoryName,
            expected: ownersIdentity
        )
        try requireNamedIdentity(
            parent: leaseDescriptor,
            name: Self.mutationLockName,
            expected: mutationLockIdentity
        )
        try requireNamedIdentity(
            parent: ownersDescriptor,
            name: Self.ownerLockName(ownerID),
            expected: ownerLockIdentity
        )
    }

    private func requireNamedIdentity(
        parent: Int32,
        name: String,
        expected: Identity, causalIO: EraseAbortCheckedSnapshotIOV1? = nil
    ) throws {
        if let io = causalIO {
            if isEraseSchema2ColdOwner {
                var named = stat()
                guard eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
                      try io.selectedControlFStatAtV1(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      Identity(named) == expected else { throw Self.identityFailure() }
            } else {
                try io.selectedControlWithOpenV1(parent: parent, name: name, flags: O_RDONLY | O_NOFOLLOW) { fd in
                    guard try Self.regularFileSnapshot(fd, causalIO: io).identity == expected else { throw Self.identityFailure() }
                }
            }
            return
        }
        if isEraseSchema2ColdOwner {
            var named = stat()
            guard eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
                  Darwin.fstatat(parent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  Identity(named) == expected else {
                throw Self.identityFailure()
            }
            return
        }
        try Self.requireNamedIdentity(
            parent: parent,
            name: name,
            expected: expected
        )
    }

    private static func requireNamedIdentity(
        parent: Int32,
        name: String,
        expected: Identity
    ) throws {
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        defer { _ = Darwin.close(descriptor) }
        guard try regularFileIdentity(descriptor) == expected else {
            throw Self.identityFailure()
        }
    }

    private func requireNamedDirectoryIdentity(
        parent: Int32,
        name: String,
        expected: Identity
    ) throws {
        if isEraseSchema2ColdOwner {
            var named = stat()
            guard eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
                  Darwin.fstatat(parent, name, &named,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  Identity(named) == expected else {
                throw Self.identityFailure()
            }
            return
        }
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        defer { _ = Darwin.close(descriptor) }
        guard try Self.directoryIdentity(descriptor) == expected else {
            throw Self.identityFailure()
        }
    }

    private static func openOrCreateDirectory(
        parent: Int32,
        name: String
    ) throws -> Int32 {
        try requireSafeName(name)
        var descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        if descriptor >= 0 { return descriptor }
        guard errno == ENOENT else { throw mappedFailure() }
        if Darwin.mkdirat(parent, name, mode_t(0o700)) != 0,
           errno != EEXIST {
            throw mappedFailure()
        }
        guard Darwin.fsync(parent) == 0 else { throw mappedFailure() }
        descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard descriptor >= 0 else { throw mappedFailure() }
        return descriptor
    }

    private static func openOrCreateRegularFile(
        parent: Int32,
        name: String
    ) throws -> (descriptor: Int32, identity: Identity) {
        try requireSafeName(name)
        var descriptor = Darwin.openat(
            parent,
            name,
            O_RDWR | O_NOFOLLOW
        )
        if descriptor < 0, errno == ENOENT {
            descriptor = Darwin.openat(
                parent,
                name,
                O_RDWR | O_CREAT | O_EXCL | O_NOFOLLOW,
                mode_t(0o600)
            )
            if descriptor < 0, errno == EEXIST {
                descriptor = Darwin.openat(
                    parent,
                    name,
                    O_RDWR | O_NOFOLLOW
                )
            }
            guard descriptor >= 0, Darwin.fsync(parent) == 0 else {
                let failureErrno = errno
                if descriptor >= 0 { _ = Darwin.close(descriptor) }
                throw mappedFailure(errorNumber: failureErrno)
            }
        }
        guard descriptor >= 0 else { throw mappedFailure() }
        do {
            return (descriptor, try regularFileIdentity(descriptor))
        } catch {
            _ = Darwin.close(descriptor)
            throw error
        }
    }

    private static func directoryIdentity(_ descriptor: Int32) throws -> Identity {
        var information = stat()
        guard Darwin.fstat(descriptor, &information) == 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        guard (information.st_mode & S_IFMT) == S_IFDIR,
              information.st_nlink >= 1 else {
            throw Self.identityFailure()
        }
        return Identity(information)
    }

    private static func regularFileIdentity(_ descriptor: Int32) throws -> Identity {
        try regularFileSnapshot(descriptor).identity
    }

    private static func regularFileSnapshot(
        _ descriptor: Int32, causalIO: EraseAbortCheckedSnapshotIOV1? = nil
    ) throws -> FileSnapshot {
        var information = stat()
        guard (try causalIO?.selectedControlFStatV1(descriptor, &information) ?? Darwin.fstat(descriptor, &information)) == 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        guard (information.st_mode & S_IFMT) == S_IFREG,
              information.st_nlink == 1,
              information.st_size >= 0,
              information.st_size <= off_t(maximumControlFileBytes) else {
            throw Self.identityFailure()
        }
        return FileSnapshot(information)
    }

    private static func namedRegularFileSnapshot(
        parent: Int32,
        name: String
    ) throws -> FileSnapshot {
        try requireSafeName(name)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw mappedFailure() }
        defer { _ = Darwin.close(descriptor) }
        return try regularFileSnapshot(descriptor)
    }

    private static func controlKind(
        for name: String
    ) throws -> OwnedFileKindV1 {
        switch name {
        case registryTemporaryName,
             pruneIntentTemporaryName,
             pruneReceiptTemporaryName:
            return .generationLeaseControlTemporary
        case registryName,
             schema2ColdReaderRecordName,
             originalEraseRetainedReaderRecordName,
             pruneIntentName,
             pruneReceiptName:
            return .generationLeaseControl
        default:
            throw GenerationLeaseRegistryFailureV1.invalidPath
        }
    }

    private static func itemExists(parent: Int32, name: String) throws -> Bool {
        try requireSafeName(name)
        var information = stat()
        guard Darwin.fstatat(
            parent,
            name,
            &information,
            AT_SYMLINK_NOFOLLOW
        ) == 0 else {
            if errno == ENOENT { return false }
            throw mappedFailure()
        }
        guard (information.st_mode & S_IFMT) != S_IFLNK else {
            throw Self.identityFailure()
        }
        return true
    }

    private static func readAll(from descriptor: Int32) throws -> Data {
        guard Darwin.lseek(descriptor, 0, SEEK_SET) >= 0 else {
            throw Self.identityFailure(errorNumber: errno)
        }
        var data = Data()
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count == 0 { return data }
            guard count > 0 else {
                if errno == EINTR { continue }
                throw mappedFailure()
            }
            guard data.count <= maximumControlFileBytes - count else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
            data.append(contentsOf: buffer.prefix(count))
        }
    }

    private static func writeAll(_ data: Data, to descriptor: Int32) throws {
        guard data.count <= maximumControlFileBytes else {
            throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
        }
        try data.withUnsafeBytes { bytes in
            var offset = 0
            while offset < bytes.count {
                let count = Darwin.write(
                    descriptor,
                    bytes.baseAddress?.advanced(by: offset),
                    bytes.count - offset
                )
                guard count > 0 else {
                    if count < 0 && errno == EINTR { continue }
                    throw mappedFailure()
                }
                offset += count
            }
        }
    }

    private static func requireSafeName(_ name: String) throws {
        guard !name.isEmpty,
              name != ".",
              name != "..",
              !name.contains("/"),
              !name.contains("\\") else {
            throw GenerationLeaseRegistryFailureV1.invalidPath
        }
    }

    private static func ownerLockName(_ ownerID: UUID) -> String {
        "\(ownerID.uuidString.lowercased()).lock"
    }

    private static func idOrder(_ lhs: UUID, _ rhs: UUID) -> Bool {
        lhs.uuidString.lowercased() < rhs.uuidString.lowercased()
    }

    private static func mappedFailure(
        errorNumber: Int32 = errno,
        operation: StaticString = #function,
        line: UInt = #line
    ) -> GenerationLeaseRegistryFailureV1 {
        reportFailure(operation: operation, line: line, errorNumber: errorNumber)
        if errorNumber == EACCES || errorNumber == EPERM {
            return .protectedDataUnavailable
        }
        return .invalidIdentity
    }

    private static func uncertainOwnerFailure(
        operation: StaticString = #function,
        line: UInt = #line
    ) -> GenerationLeaseRegistryFailureV1 {
        // No errno is inferred from a failed logical ownership predicate.
        reportFailure(operation: operation, line: line, errorNumber: nil)
        return .uncertainOwner
    }

    private static func identityFailure(
        errorNumber: Int32? = nil,
        operation: StaticString = #function,
        line: UInt = #line
    ) -> GenerationLeaseRegistryFailureV1 {
        // This may be a failed predicate after a successful syscall. Report
        // no errno rather than attributing an unrelated earlier value to it.
        reportFailure(operation: operation, line: line, errorNumber: errorNumber)
        return .invalidIdentity
    }

    private static func reportFailure(
        operation: StaticString,
        line: UInt,
        errorNumber: Int32?
    ) {
        #if DEBUG
        let code = errorNumber.map { String($0) } ?? "not-captured"
        print("GenerationLeaseRegistryV1.failure operation=\(operation) line=\(line) errno=\(code)")
        #endif
    }
}

// The job runner executes off the main actor. This adapter retains the actual
// registry and writer lease, then performs the same no-suspension G-locked
// writer/epoch reproof as a normal commit without crossing a MainActor fence.
extension GenerationLeaseRegistryV1 {
    /// A fresh cold Registry has a new ownerID. It cannot adopt the prior
    /// process's target reader. Classify the exact durable record and
    /// Registry cut under this operation's EX/G; if the recorded old owner
    /// guard is provably dead, remove only that one old token and then let
    /// the new operation mint its own token. No broad abandoned-owner sweep.
    @MainActor
    func settleEraseSchema2ColdRecordedTargetReader(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        manifest: EraseSchema2ColdManifestOwnerV1,
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1
    ) throws -> [GenerationLeaseTokenV1] {
        try operation.requireConstructedSchema2ColdRegistry(self)
        try operation.requireSchema2ColdManifestOwner(manifest)
        try operation.requireSchema2ColdOriginalControls(
            intent: intent, preparation: preparation)
        return try withEraseSchema2ColdMutationLock(
            operation: operation, activity: activity) {
#if DEBUG
            var c25ReplayStage = "manifest-begin"
            do {
            try manifest.beginSchema2ColdRecordedReaderSettlement(
                operation: operation, registry: self)
#if DEBUG
            c25ReplayStage = "recorded-reader-replay"
#endif
            let result = try settleEraseSchema2ColdRecordedTargetReaderLocked(
                intent: intent, preparation: preparation,
                operation: operation)
#if DEBUG
            c25ReplayStage = "manifest-finish"
#endif
            try manifest.finishSchema2ColdRecordedReaderSettlement(
                operation: operation, registry: self)
            return result
            } catch {
#if DEBUG
                C25TargetClosedErrorDiagnosticV1.emit(owner: "cold-recorded-reader",
                    stage: c25ReplayStage,error: error)
#endif
                throw error
            }
#else
            try manifest.beginSchema2ColdRecordedReaderSettlement(
                operation: operation, registry: self)
            let result = try settleEraseSchema2ColdRecordedTargetReaderLocked(
                intent: intent, preparation: preparation,
                operation: operation)
            try manifest.finishSchema2ColdRecordedReaderSettlement(
                operation: operation, registry: self)
            return result
#endif
        }
    }

    @MainActor
    private func settleEraseSchema2ColdRecordedTargetReaderLocked(
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws -> [GenerationLeaseTokenV1] {
        guard eraseSchema2ColdReaderSettlement == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let settlement = EraseSchema2ColdReaderSettlementV1()
        eraseSchema2ColdReaderSettlement = settlement
        let observed = try readEraseSchema2ColdRegistryLocked(
            operation: operation)
        var named = stat()
        let recordExists = Darwin.fstatat(leaseDescriptor,
            Self.schema2ColdReaderRecordName, &named,
            AT_SYMLINK_NOFOLLOW) == 0
        guard recordExists || errno == ENOENT else {
            throw Self.identityFailure()
        }
        if !recordExists {
            guard try !Self.itemExists(parent: leaseDescriptor,
                    name: Self.registryTemporaryName) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            settlement.completed = true
            return observed
        }
        let recordFD = Darwin.openat(leaseDescriptor,
            Self.schema2ColdReaderRecordName,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard recordFD >= 0 else { throw Self.mappedFailure() }
        settlement.recordFD = recordFD
        let recordSnapshot = try Self.regularFileSnapshot(recordFD)
        try requireNamedIdentity(parent: leaseDescriptor,
            name: Self.schema2ColdReaderRecordName,
            expected: recordSnapshot.identity)
        let recordBytes = try Self.readAll(from: recordFD)
        guard try Self.regularFileSnapshot(recordFD) == recordSnapshot else {
            throw Self.identityFailure()
        }
        let currentBytes = try RegistryStateV1(leases: observed)
            .canonicalData()
        let currentSHA = StoreMigrationCanonicalJSONV1.sha256(
            currentBytes)
        if try EraseSchema2ColdReaderPublicationRecordV1
                .isAdmissiblePrefix(recordBytes, intent: intent,
                    priorSHA256: currentSHA) {
            // Publication cannot precede a complete, fsynced record. The
            // current Registry is therefore the prior state and no temp may
            // exist. Check the actual partial inode before unlinking it.
            guard try !Self.itemExists(parent: leaseDescriptor,
                    name: Self.registryTemporaryName) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try requireSchema2ColdPublicationPolicy(
                descriptor: recordFD,
                name: Self.schema2ColdReaderRecordName,
                kind: .generationLeaseControl,
                bytes: recordBytes)
            try unlinkSchema2ColdSettledFile(recordFD,
                name: Self.schema2ColdReaderRecordName,
                before: recordSnapshot)
            try settlement.finishChecked()
            return observed
        }
        let record = try EraseSchema2ColdReaderPublicationRecordV1
            .decodeCanonical(recordBytes)
        guard record.eraseID == intent.eraseID,
              record.targetGenerationID == intent.newGenerationID,
              record.targetManifestSHA256
                == intent.targetPointer?.generationManifestSHA256 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let epoch = try GenerationEpochV1(
            generationID: intent.newGenerationID,
            generationManifestSHA256:
                record.targetManifestSHA256)
        let oldToken = try record.token(epoch: epoch)
        guard oldToken.ownerID != ownerID else {
            // Same-owner publication belongs to its original retained
            // allocation. A fresh operation never reconstructs that owner.
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let matches = observed.filter({
            $0.leaseID == oldToken.leaseID
        })
        guard matches.isEmpty || matches == [oldToken] else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let prior = observed.filter({
            $0.leaseID != oldToken.leaseID
        })
        let priorBytes = try RegistryStateV1(leases: prior)
            .canonicalData()
        guard StoreMigrationCanonicalJSONV1.sha256(priorBytes)
                == record.priorRegistrySHA256 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireSchema2ColdPublicationPolicy(
            descriptor: recordFD,
            name: Self.schema2ColdReaderRecordName,
            kind: .generationLeaseControl,
            bytes: recordBytes)
        try lockDeadSchema2ColdRecordOwner(oldToken.ownerID,
            settlement: settlement)
        if try Self.itemExists(parent: leaseDescriptor,
                name: Self.registryTemporaryName) {
            // Before the original publication rename, current is `prior`
            // and this temp is a prefix of `prior + oldToken`. After that
            // rename, a fresh owner's checked removal can itself crash:
            // current still contains exactly oldToken and its temp is a
            // prefix of `prior`. These are distinct held cuts; a mismatch
            // never becomes permission to adopt an arbitrary temp.
            let replacement = try RegistryStateV1(leases:
                matches.isEmpty ? prior + [oldToken] : prior)
                .canonicalData()
            let fd = Darwin.openat(leaseDescriptor,
                Self.registryTemporaryName,
                O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            guard fd >= 0 else { throw Self.mappedFailure() }
            settlement.registryTemporaryFD = fd
            let snapshot = try requireSchema2ColdExactFilePrefix(
                descriptor: fd, name: Self.registryTemporaryName,
                expected: replacement)
            let tempBytes = try Self.readAll(from: fd)
            try requireSchema2ColdPublicationPolicy(
                descriptor: fd, name: Self.registryTemporaryName,
                kind: .generationLeaseControlTemporary,
                bytes: tempBytes)
            try unlinkSchema2ColdSettledFile(fd,
                name: Self.registryTemporaryName,
                before: snapshot)
            try settlement.closeRegistryTemporaryChecked()
        }
        if matches == [oldToken] {
            try removeSchema2ColdRecordedOldReader(oldToken,
                observed: observed, prior: prior,
                settlement: settlement,
                intent: intent, preparation: preparation,
                operation: operation)
        }
        guard try readEraseSchema2ColdRegistryLocked(
                operation: operation) == prior else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try unlinkSchema2ColdSettledFile(recordFD,
            name: Self.schema2ColdReaderRecordName,
            before: recordSnapshot)
        try settlement.finishChecked()
        return prior
    }

    @MainActor
    private func unlinkSchema2ColdSettledFile(
        _ descriptor: Int32, name: String,
        before: FileSnapshot
    ) throws {
        guard try Self.regularFileSnapshot(descriptor) == before else {
            throw Self.identityFailure()
        }
        try requireNamedIdentity(parent: leaseDescriptor,
            name: name, expected: before.identity)
        guard Darwin.unlinkat(leaseDescriptor, name, 0) == 0,
              Darwin.fsync(leaseDescriptor) == 0 else {
            throw Self.mappedFailure()
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              held.st_dev == before.identity.device,
              held.st_ino == before.identity.inode,
              held.st_nlink == 0,
              Darwin.fstatat(leaseDescriptor, name, &named,
                AT_SYMLINK_NOFOLLOW) != 0,
              errno == ENOENT else {
            throw Self.identityFailure()
        }
    }

    @MainActor
    private func lockDeadSchema2ColdRecordOwner(
        _ oldOwner: UUID,
        settlement: EraseSchema2ColdReaderSettlementV1
    ) throws {
        let name = Self.ownerLockName(oldOwner)
        let fd = Darwin.openat(ownersDescriptor, name,
            O_RDWR | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard fd >= 0 else { throw Self.mappedFailure() }
        settlement.guardFD = fd
        let before = try Self.regularFileSnapshot(fd)
        try requireNamedIdentity(parent: ownersDescriptor,
            name: name, expected: before.identity)
        guard flock(fd, LOCK_EX | LOCK_NB) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        settlement.guardLocked = true
        guard try Self.regularFileSnapshot(fd) == before else {
            throw Self.identityFailure()
        }
        try requireNamedIdentity(parent: ownersDescriptor,
            name: name, expected: before.identity)
        _ = try ProtectedFilePolicyV1
            .verifyEraseColdTemporalPolicyWithCheckedRequest(
                .generationLeaseOwnerLock,
                at: ownersURL.appendingPathComponent(name),
                retainUncertainDescriptor: { value in
                    self.eraseSchema2ColdPolicyUncertainDescriptors.append(
                        value)
                }, unchangedWitness: {
                    let observed = try Self.regularFileSnapshot(fd)
                    try self.requireNamedIdentity(
                        parent: self.ownersDescriptor,
                        name: name, expected: observed.identity)
                    return observed
                })
        guard eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
              try Self.regularFileSnapshot(fd) == before else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    @MainActor
    private func removeSchema2ColdRecordedOldReader(
        _ token: GenerationLeaseTokenV1,
        observed: [GenerationLeaseTokenV1],
        prior: [GenerationLeaseTokenV1],
        settlement: EraseSchema2ColdReaderSettlementV1,
        intent: EraseIntentV1,
        preparation: ErasePreparationV2,
        operation: EraseColdPreparationOperationV1
    ) throws {
        guard settlement.guardLocked,
              observed.filter({ $0.leaseID == token.leaseID })
                == [token] else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let original = Darwin.openat(leaseDescriptor,
            Self.registryName,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard original >= 0 else { throw Self.mappedFailure() }
        settlement.registryOriginalFD = original
        let oldBytes = try RegistryStateV1(leases: observed)
            .canonicalData()
        let oldSnapshot = try requireSchema2ColdPublicationFile(
            descriptor: original, name: Self.registryName,
            bytes: oldBytes)
        let replacement = try RegistryStateV1(leases: prior)
            .canonicalData()
        let temporary = Darwin.openat(leaseDescriptor,
            Self.registryTemporaryName,
            O_RDWR | O_CREAT | O_EXCL | O_NONBLOCK
                | O_NOFOLLOW | O_CLOEXEC,
            mode_t(0o600))
        guard temporary >= 0 else { throw Self.mappedFailure() }
        settlement.registryTemporaryFD = temporary
        try Self.writeAll(replacement, to: temporary)
        guard Darwin.fsync(temporary) == 0 else {
            throw Self.mappedFailure()
        }
        try applySchema2ColdNewPublicationPolicy(
            descriptor: temporary,
            name: Self.registryTemporaryName,
            kind: .generationLeaseControlTemporary,
            bytes: replacement,
            diagnosticStage: .temporaryPolicy,
            ownerCheck: {
                try operation.requireSchema2ColdOriginalControls(
                    intent: intent, preparation: preparation)
            })
        let prepared = try requireSchema2ColdPublicationFile(
            descriptor: temporary,
            name: Self.registryTemporaryName,
            bytes: replacement)
        var beforeRename = stat()
        guard try Self.regularFileSnapshot(original) == oldSnapshot,
              Darwin.fstat(temporary, &beforeRename) == 0,
              FileSnapshot(beforeRename) == prepared,
              Darwin.renameat(leaseDescriptor,
                Self.registryTemporaryName,
                leaseDescriptor, Self.registryName) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // A failed post-rename projection cannot be retried against a later
        // ctime or a substituted same-name inode in this retained settlement.
        do {
            _ = try requireSchema2ColdOwnedRegistryRenamePostimage(
                descriptor: temporary, bytes: replacement,
                prepared: prepared, beforeRename: beforeRename)
            guard Darwin.fsync(leaseDescriptor) == 0,
                  try readEraseSchema2ColdRegistryLocked(
                    operation: operation) == prior else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        } catch {
            settlement.uncertain = true
            throw error
        }
        var displaced = stat()
        guard Darwin.fstat(original, &displaced) == 0,
              displaced.st_dev == oldSnapshot.identity.device,
              displaced.st_ino == oldSnapshot.identity.inode,
              displaced.st_mode & S_IFMT == S_IFREG,
              displaced.st_nlink == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try settlement.closeRegistryOriginalChecked()
        try settlement.closeRegistryTemporaryChecked()
    }
    func makeBoundLocalJobPublicationAdapter(
        writerHandle: GenerationLeaseHandleV1,
        expectedEpoch: GenerationEpochV1
    ) throws -> GenerationLocalJobPublicationAdapterV1 {
        try expectedEpoch.validate()
        guard writerHandle.token.role == .writer,
              writerHandle.token.epoch == expectedEpoch else {
            throw GenerationLeaseRegistryFailureV1.wrongLeaseRole
        }
        try writerHandle.requireExactRegistry(self)
        try writerHandle.requireLiveTemporalIdentity(mutationRegistry: self)
        _ = try currentBoundLocalJobEpoch(
            writerHandle: writerHandle, expectedEpoch: expectedEpoch)
        return GenerationLocalJobPublicationAdapterV1(
            currentGenerationEpoch: { [self, writerHandle] in
                try currentBoundLocalJobEpoch(
                    writerHandle: writerHandle, expectedEpoch: expectedEpoch)
            },
            withAuthorizedCommit: { [self, writerHandle] epoch, effect in
                guard epoch == expectedEpoch else {
                    throw GenerationLocalJobPublicationFailureV1.staleGeneration
                }
                try writerHandle.requireExactRegistry(self)
                try writerHandle.requireLiveTemporalIdentity(mutationRegistry: self)
                return try withExclusiveGenerationCommitLock {
                    try requireNoMigrationReservationLocked()
                    try validateActiveLocked(writerHandle.token, requiredRole: .writer)
                    try requireBoundLocalJobEpochLocked(expectedEpoch)
                    return try effect()
                }
            }
        )
    }

    private func currentBoundLocalJobEpoch(
        writerHandle: GenerationLeaseHandleV1,
        expectedEpoch: GenerationEpochV1
    ) throws -> GenerationEpochV1 {
        try writerHandle.requireExactRegistry(self)
        try writerHandle.requireLiveTemporalIdentity(mutationRegistry: self)
        return try withExclusiveGenerationMutationLock {
            try requireNoMigrationReservationLocked()
            try validateActiveLocked(writerHandle.token, requiredRole: .writer)
            try requireBoundLocalJobEpochLocked(expectedEpoch)
            return expectedEpoch
        }
    }

    private func requireBoundLocalJobEpochLocked(
        _ expected: GenerationEpochV1
    ) throws {
        guard localJobPublicationUncertainDescriptors.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let dataName = "FieldEvidenceData"
        let dataURL = applicationSupportURL.appendingPathComponent(
            dataName, isDirectory: true)
        try withLocalJobPublicationDirectory(
            parent: rootDescriptor, name: dataName,
            url: dataURL, kind: .durableDirectory
        ) { dataDescriptor in
            var pending = stat()
            guard Darwin.fstatat(dataDescriptor, ".current.json.restore-next",
                &pending, AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
            let pointerData = try readLocalJobPublicationFile(
                parent: dataDescriptor, name: "current.json",
                url: dataURL.appendingPathComponent("current.json"),
                kind: .generationPointer, maximumBytes: Self.maximumControlFileBytes)
            guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(pointerData),
                  pointer.generationID == expected.generationID.uuidString.lowercased(),
                  pointer.generationManifestSHA256 == expected.generationManifestSHA256 else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
        }
        let migrationName = StoreMigrationJournalStoreV1.migrationName
        let migrationURL = applicationSupportURL
            .appendingPathComponent(Self.operationsName, isDirectory: true)
            .appendingPathComponent(migrationName, isDirectory: true)
        try withLocalJobPublicationDirectory(
            parent: operationsDescriptor, name: migrationName,
            url: migrationURL, kind: .stagingDirectory
        ) { migrationDescriptor in
            let manifestName = "manifest-"
                + expected.generationID.uuidString.lowercased() + ".json"
            let manifestData = try readLocalJobPublicationFile(
                parent: migrationDescriptor, name: manifestName,
                url: migrationURL.appendingPathComponent(manifestName),
                kind: .journal, maximumBytes: 32 * 1_048_576)
            guard StoreMigrationCanonicalJSONV1.sha256(manifestData)
                    == expected.generationManifestSHA256 else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
            let manifest = try StoreGenerationManifestV1.decodeCanonical(
                from: manifestData)
            guard manifest.generationID == expected.generationID,
                  manifest.storeSchemaRelease == PersistentSchemaReleaseRegistryV1.activeRelease else {
                throw GenerationLeaseRegistryFailureV1.staleGeneration
            }
        }
    }

    private func withLocalJobPublicationDirectory<Value>(
        parent: Int32, name: String, url: URL, kind: OwnedFileKindV1,
        _ body: (Int32) throws -> Value
    ) throws -> Value {
        let descriptor = Darwin.openat(
            parent, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else {
            throw GenerationLeaseRegistryFailureV1.invalidIdentity
        }
        var didAttemptClose = false
        do {
            let before = try Self.directoryIdentity(descriptor)
            let policy = try ProtectedFilePolicyV1.observeTemporalPolicy(kind, at: url)
            guard policy.state == .strictComplete,
                  policy.device == UInt64(before.device),
                  policy.inode == UInt64(before.inode) else {
                throw GenerationLeaseRegistryFailureV1.invalidIdentity
            }
            let result = try body(descriptor)
            let after = try Self.directoryIdentity(descriptor)
            let afterPolicy = try ProtectedFilePolicyV1.observeTemporalPolicy(kind, at: url)
            var named = stat()
            guard before == after, afterPolicy == policy,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  Identity(named) == before else {
                throw GenerationLeaseRegistryFailureV1.invalidIdentity
            }
            didAttemptClose = true
            guard closeLocalJobPublicationDescriptor(descriptor) else {
                localJobPublicationUncertainDescriptors.append(descriptor)
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return result
        } catch {
            if !didAttemptClose {
                didAttemptClose = true
                guard closeLocalJobPublicationDescriptor(descriptor) else {
                    localJobPublicationUncertainDescriptors.append(descriptor)
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
            throw error
        }
    }

    private func readLocalJobPublicationFile(
        parent: Int32, name: String, url: URL,
        kind: OwnedFileKindV1, maximumBytes: Int
    ) throws -> Data {
        let descriptor = Darwin.openat(
            parent, name, O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
        guard descriptor >= 0 else {
            throw GenerationLeaseRegistryFailureV1.invalidIdentity
        }
        var didAttemptClose = false
        do {
            var before = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1,
                  before.st_size >= 0,
                  before.st_size <= off_t(maximumBytes) else {
                throw GenerationLeaseRegistryFailureV1.invalidIdentity
            }
            let protection = try ProtectedFilePolicyV1.observeTemporalPolicy(
                kind, at: url)
            guard protection.state == .strictComplete,
                  protection.device == UInt64(before.st_dev),
                  protection.inode == UInt64(before.st_ino) else {
                throw GenerationLeaseRegistryFailureV1.invalidIdentity
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count == 0 { break }
                if count < 0, errno == EINTR { continue }
                guard count > 0, bytes.count <= maximumBytes - count else {
                    throw GenerationLeaseRegistryFailureV1.invalidIdentity
                }
                bytes.append(contentsOf: buffer.prefix(count))
            }
            var after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  before.st_dev == after.st_dev, before.st_ino == after.st_ino,
                  before.st_size == after.st_size,
                  before.st_mtimespec.tv_sec == after.st_mtimespec.tv_sec,
                  before.st_mtimespec.tv_nsec == after.st_mtimespec.tv_nsec,
                  before.st_ctimespec.tv_sec == after.st_ctimespec.tv_sec,
                  before.st_ctimespec.tv_nsec == after.st_ctimespec.tv_nsec,
                  named.st_dev == before.st_dev, named.st_ino == before.st_ino,
                  named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1,
                  bytes.count == Int(after.st_size) else {
                throw GenerationLeaseRegistryFailureV1.invalidIdentity
            }
            didAttemptClose = true
            guard closeLocalJobPublicationDescriptor(descriptor) else {
                localJobPublicationUncertainDescriptors.append(descriptor)
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return bytes
        } catch {
            if !didAttemptClose {
                didAttemptClose = true
                guard closeLocalJobPublicationDescriptor(descriptor) else {
                    localJobPublicationUncertainDescriptors.append(descriptor)
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
            throw error
        }
    }
}

/// Idempotent lifetime wrapper. A failed close deliberately leaves the durable
/// lease record in place; startup owner-lock reconciliation is the only crash
/// cleanup authority.
final class GenerationLeaseHandleV1: @unchecked Sendable {
    let token: GenerationLeaseTokenV1

    private let registry: GenerationLeaseRegistryV1
    private let lock = NSLock()
    private var isClosed = false
    private var isSchema2ColdTargetReader = false

    init(
        registry: GenerationLeaseRegistryV1,
        token: GenerationLeaseTokenV1
    ) throws {
        try token.validate()
        self.registry = registry
        self.token = token
        try registry.validateActive(token, requiredRole: token.role)
    }

    fileprivate init(registry: GenerationLeaseRegistryV1,
                     publishedReaderToken: GenerationLeaseTokenV1) throws {
        try publishedReaderToken.validate()
        guard publishedReaderToken.role == .reader else { throw GenerationLeaseRegistryFailureV1.invalidContract }
        self.registry = registry; token = publishedReaderToken
    }

    /// Issued only by the actual schema2 cold target publisher. Its lifetime
    /// is closed by that exact allocation's checked retirement, never deinit
    /// or the ordinary temporal maintenance release.
    fileprivate init(registry: GenerationLeaseRegistryV1,
        schema2ColdTargetReaderToken: GenerationLeaseTokenV1) throws {
        try schema2ColdTargetReaderToken.validate()
        guard schema2ColdTargetReaderToken.role == .reader else {
            throw GenerationLeaseRegistryFailureV1.invalidContract
        }
        self.registry = registry; token = schema2ColdTargetReaderToken
        isSchema2ColdTargetReader = true
    }

    fileprivate init(registry: GenerationLeaseRegistryV1,
                     publishedWriterToken: GenerationLeaseTokenV1) throws {
        try publishedWriterToken.validate()
        guard publishedWriterToken.role == .writer else { throw GenerationLeaseRegistryFailureV1.invalidContract }
        self.registry = registry; token = publishedWriterToken
    }
    fileprivate func requireRecordedFreshAdoptionRelease(registry expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected, isClosed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
    }
    fileprivate func recordFreshAdoptionRelease(registry expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            isClosed = true // fixed durable release finished; outer G failure remains owned for retry
        }
    }

    /// The actual retained wrapper must still own its lease. This is a pure
    /// physical comparison; the caller's one G interval supplies the census.
    func requireLiveTemporalIdentity(mutationRegistry: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard !isClosed else { throw GenerationLeaseRegistryFailureV1.leaseNotActive }
            try registry.requireSharedTemporalRegistryIdentity(mutationRegistry)
        }
    }

    /// A publication owner must use the wrapper's actual retained registry,
    /// not a second owner opened over the same physical control directory.
    func requireExactRegistry(_ expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            guard !isClosed else {
                throw GenerationLeaseRegistryFailureV1.leaseNotActive
            }
        }
    }

    func close() throws {
        lock.lock()
        defer { lock.unlock() }
        guard !isSchema2ColdTargetReader else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        guard !isClosed else { return }
        try registry.release(token)
        isClosed = true
    }

    @MainActor
    func closeForOriginalRestoreTransition(
        registry expected: GenerationLeaseRegistryV1,
        targetRegistry: GenerationLeaseRegistryV1,
        targetReader: GenerationLeaseHandleV1,
        targetWriter: GenerationLeaseHandleV1,
        reproveSource: () throws -> Void
    ) throws {
        try requireExactRegistry(expected)
        try expected.releaseOriginalRestoreSourceReader(self,
            targetRegistry: targetRegistry, targetReader: targetReader,
            targetWriter: targetWriter, reproveSource: reproveSource)
    }

    fileprivate func recordRestoreTransitionRelease(
        registry expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard registry === expected, !isClosed else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            isClosed = true
        }
    }

    /// A checked writer release must precede retirement of the original
    /// reader cohort after a no-effect Erase abort.  An invalidated writer is
    /// insufficient: its durable lease may still be held by a producer.
    func requireClosedForAbortedEraseReaderRetirement() throws {
        try lock.withLock {
            guard isClosed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
    }

    func requireClosedForRestoreTransition() throws {
        try lock.withLock {
            guard isClosed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
    }

    func requireClosedForRestoreTransition(
        registry expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard isClosed, registry === expected else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    /// The original Erase writer was removed through the exact retained EX
    /// transition, not through ordinary close or restore-transition authority.
    func requireClosedForOriginalEraseWriterTransition(
        registry expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard isClosed, registry === expected else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    @MainActor
    fileprivate func closeForOriginalEraseWriterTransition(
        registry expected: GenerationLeaseRegistryV1,
        release: () throws -> Void
    ) throws {
        try lock.withLock {
            guard registry === expected, !isClosed,
                  token.role == .writer else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try release()
            isClosed = true
        }
    }

    /// Fixed maintenance release through an actual still-held normalization
    /// EX. Ordinary close semantics are unchanged for all other callers.
    func closeForTemporalMaintenance(activity: GenerationTemporalActivityHandleV1) throws {
        try lock.withLock {
            guard !isSchema2ColdTargetReader else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            guard !isClosed else { return }
            try registry.releaseTemporalMaintenance(token, activity: activity)
            isClosed = true
        }
    }

#if DEBUG
    @MainActor
    func closeForOriginalEraseShutdown(witness: EraseOriginalShutdownWitnessV1,
        activity: GenerationTemporalActivityHandleV1) throws {
        try lock.withLock {
            guard !isClosed else { return }
            try registry.releaseOriginalEraseShutdownLease(token,
                witness: witness, activity: activity)
            isClosed = true
        }
    }

    func requireCheckedClosedForOriginalEraseShutdown(
        registry expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected, isClosed else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }
#endif

    deinit {
        // Failure is fail-closed: the record remains durable and cannot make a
        // generation prune-eligible until owner-lock recovery proves death.
        if !isSchema2ColdTargetReader { try? close() }
    }
}

@MainActor
final class StaleWriterFenceV1 {
    let expectedGenerationEpoch: GenerationEpochV1
    let writerLeaseToken: GenerationLeaseTokenV1

    private var completedStartupOwner: ColdEraseSchema2CompletedStartupOwnerV1?
    private var completedStartupOriginWasBound = false
    private var completedStartupLifecycleTransfer: ColdEraseSchema2CompletedFenceLifecycleTransferV1?

    fileprivate func bindCompletedStartupOwner(_ owner: ColdEraseSchema2CompletedStartupOwnerV1) throws {
        guard !completedStartupOriginWasBound, completedStartupOwner == nil,
              completedStartupLifecycleTransfer == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try owner.requireCompletedRegistryObservationAssociationForFence(registry: registry,
            writerToken: writerLeaseToken, epoch: expectedGenerationEpoch)
        completedStartupOriginWasBound = true
        completedStartupOwner = owner
    }

    private func requireCompletedObservationOwner() throws -> ColdEraseSchema2CompletedStartupOwnerV1? {
        guard completedStartupOriginWasBound else { return nil }
        if let transfer = completedStartupLifecycleTransfer {
            try transfer.requireBound(fence: self, registry: registry,
                writerToken: writerLeaseToken, epoch: expectedGenerationEpoch)
            return nil // genuine ownership transfer; current ordinary fence still validates every operation
        }
        guard let owner = completedStartupOwner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try owner.requireCompletedRegistryObservationAssociationForFence(registry: registry,
            writerToken: writerLeaseToken, epoch: expectedGenerationEpoch)
        return owner
    }

    func transferCompletedStartupPublishedLifecycle(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1) throws {
        guard completedStartupOriginWasBound, completedStartupOwner === owner,
              completedStartupLifecycleTransfer == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let transfer = try ColdEraseSchema2CompletedFenceLifecycleTransferV1(fence: self,
            registry: registry, writerToken: writerLeaseToken, epoch: expectedGenerationEpoch,
            owner: owner, receiver: receiver)
        completedStartupLifecycleTransfer = transfer
        completedStartupOwner = nil // only after actual Ready receiver/resource consumers
    }

    private let registry: GenerationLeaseRegistryV1
    private let currentGenerationEpoch: () throws -> GenerationEpochV1
    /// Exact retained object for owner-wide activity. This is not a mint or
    /// a substitute for this fence's fixed under-G validation.
    var retainedTemporalRegistry: GenerationLeaseRegistryV1 { registry }

    static func makeForSchema2ColdCompletedStartup(expectedGenerationEpoch: GenerationEpochV1,
        writerLeaseToken: GenerationLeaseTokenV1, registry: GenerationLeaseRegistryV1,
        currentGenerationEpoch: @escaping () throws -> GenerationEpochV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1) throws -> StaleWriterFenceV1 {
        let fence = try StaleWriterFenceV1(expectedGenerationEpoch: expectedGenerationEpoch,
            writerLeaseToken: writerLeaseToken, registry: registry, currentGenerationEpoch: currentGenerationEpoch)
        try fence.bindCompletedStartupOwner(owner) // no IO before actual closed origin
        return fence
    }

    init(
        expectedGenerationEpoch: GenerationEpochV1,
        writerLeaseToken: GenerationLeaseTokenV1,
        registry: GenerationLeaseRegistryV1,
        currentGenerationEpoch: @escaping () throws -> GenerationEpochV1
    ) throws {
        try expectedGenerationEpoch.validate()
        try writerLeaseToken.validate()
        guard writerLeaseToken.role == .writer,
              writerLeaseToken.epoch == expectedGenerationEpoch else {
            throw GenerationLeaseRegistryFailureV1.invalidContract
        }
        self.expectedGenerationEpoch = expectedGenerationEpoch
        self.writerLeaseToken = writerLeaseToken
        self.registry = registry
        self.currentGenerationEpoch = currentGenerationEpoch
    }

    func validateCurrent() throws {
        if let owner = try requireCompletedObservationOwner() {
            return try registry.withSchema2ColdCompletedStartupObservation(owner: owner,
                writerToken: writerLeaseToken, epoch: expectedGenerationEpoch,
                verifyAfterOperation: false) {}
        }
        let activity = try registry.acquireTemporalWriterRegistrationActivity()
        defer { activity.close() }
        try registry.withExclusiveGenerationMutationLock {
            try validateCurrentLocked()
        }
    }

    struct ReadFenceFailure: Error {
        let underlying: any Error
    }

    /// A read interval holds the same cross-process generation lock as writes,
    /// and proves the writer epoch at both ends. The body cannot suspend.
    /// Tag only fence/root failures so the journal can map those without
    /// converting a graph or domain rejection thrown by the read itself.
    func withAuthorizedRead<Value>(_ body: () throws -> Value) throws -> Value {
        let completedOwner: ColdEraseSchema2CompletedStartupOwnerV1?
        do { completedOwner = try requireCompletedObservationOwner() }
        catch { throw ReadFenceFailure(underlying: error) }
        if let owner = completedOwner {
            var bodyFailure: (any Error)?
            do {
                return try registry.withSchema2ColdCompletedStartupObservation(owner: owner,
                    writerToken: writerLeaseToken, epoch: expectedGenerationEpoch,
                    verifyAfterOperation: true) {
                    do { return try body() }
                    catch { bodyFailure = error; throw error }
                }
            } catch {
                if let bodyFailure { throw bodyFailure }
                throw ReadFenceFailure(underlying: error)
            }
        }
        let activity: GenerationTemporalActivityHandleV1
        do { activity = try registry.acquireTemporalWriterRegistrationActivity() }
        catch { throw ReadFenceFailure(underlying: error) }
        defer { activity.close() }
        var bodyFailure: (any Error)?
        do {
            return try registry.withExclusiveGenerationMutationLock {
                try validateCurrentLocked()
                let result: Value
                do { result = try body() }
                catch {
                    bodyFailure = error
                    throw error
                }
                try validateCurrentLocked()
                return result
            }
        } catch {
            if let bodyFailure { throw bodyFailure }
            throw ReadFenceFailure(underlying: error)
        }
    }

    func withAuthorizedCommit<Value>(
        _ operation: () throws -> Value
    ) throws -> Value {
        if let owner = try requireCompletedObservationOwner() {
            try owner.requireCompletedRegistryCommitAuthorizationForCurrentFrame()
            return try registry.withSchema2ColdCompletedStartupObservation(owner: owner,
                writerToken: writerLeaseToken, epoch: expectedGenerationEpoch,
                verifyAfterOperation: false, operation)
        }
        let activity = try registry.acquireTemporalWriterRegistrationActivity()
        defer { activity.close() }
        return try registry.withExclusiveGenerationCommitLock {
            try validateCurrentLocked()
            return try operation()
        }
    }

    /// The original Erase's already-held EX supplies temporal exclusion;
    /// Registry still proves this exact writer and epoch under its actual G.
    func withAuthorizedOriginalEraseWriterRecovery(
        activity: GenerationTemporalActivityHandleV1,
        operation: EraseRouterOperationV1,
        targetAllocation: GenerationWriterAllocationAttemptV1,
        targetHandle: GenerationLeaseHandleV1,
        _ body: () throws -> Void
    ) throws -> OriginalEraseRetainedWriterRecoveryReceiptV1 {
        guard writerLeaseToken == targetHandle.token,
              writerLeaseToken.epoch == expectedGenerationEpoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return try registry.withOriginalEraseRetainedWriterRecovery(
            activity: activity, operation: operation,
            targetAllocation: targetAllocation, targetHandle: targetHandle,
            expectedEpoch: expectedGenerationEpoch,
            currentEpoch: currentGenerationEpoch, body)
    }

    private func validateCurrentLocked() throws {
        try registry.requireNoMigrationReservationLocked()
        try registry.validateActiveLocked(
            writerLeaseToken,
            requiredRole: .writer
        )
        guard try currentGenerationEpoch() == expectedGenerationEpoch else {
            throw GenerationLeaseRegistryFailureV1.staleGeneration
        }
    }
}


/// Minted only after the original operation's exact dual-writer journal
/// recovery, post-census and checked G unlock all succeeded. It grants one
/// operation-bound transition to old-writer close, never a new Registry read.
@MainActor
final class OriginalEraseRetainedWriterRecoveryReceiptV1 {
    private let registryID: ObjectIdentifier
    private let operationID: ObjectIdentifier
    private let activityID: ObjectIdentifier
    private let allocationID: ObjectIdentifier
    private let handleID: ObjectIdentifier
    private let token: GenerationLeaseTokenV1

    fileprivate init(registry: GenerationLeaseRegistryV1,
                     operation: EraseRouterOperationV1,
                     activity: GenerationTemporalActivityHandleV1,
                     targetAllocation: GenerationWriterAllocationAttemptV1,
                     targetHandle: GenerationLeaseHandleV1) {
        registryID = ObjectIdentifier(registry)
        operationID = ObjectIdentifier(operation)
        activityID = ObjectIdentifier(activity)
        allocationID = ObjectIdentifier(targetAllocation)
        handleID = ObjectIdentifier(targetHandle)
        token = targetHandle.token
    }

    func requireBound(registry: GenerationLeaseRegistryV1,
                      operation: EraseRouterOperationV1,
                      activity: GenerationTemporalActivityHandleV1,
                      targetAllocation: GenerationWriterAllocationAttemptV1,
                      targetHandle: GenerationLeaseHandleV1) throws {
        guard registryID == ObjectIdentifier(registry),
              operationID == ObjectIdentifier(operation),
              activityID == ObjectIdentifier(activity),
              allocationID == ObjectIdentifier(targetAllocation),
              handleID == ObjectIdentifier(targetHandle),
              token == targetHandle.token,
              targetAllocation.allocatedHandle === targetHandle else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

/// An advisory activity lifetime, never canonical or filesystem mutation
/// authority. Each handle owns a distinct open description of the already
/// pinned registry directory. Keeping this object alive keeps its registry
/// owner guard alive across asynchronous producer work.
final class GenerationTemporalActivityHandleV1: @unchecked Sendable {
    private let registry: GenerationLeaseRegistryV1
    private let lock = NSLock()
    private var descriptor: Int32
    private var originalRecoveryUncertainCloseDescriptor: Int32?
    private enum RetirementCloseState { case open, closed, uncertain }
    private var retirementCloseState: RetirementCloseState = .open
    private weak var coldSchema2TerminalReleaseProof: ColdEraseSchema2TerminalReleaseProofV1?
    private var coldSchema2TerminalRegistryClose: ColdEraseSchema2RegistryControlCloseReceiptV1?
    private var coldSchema2TerminalUnlockResult: (returned: Int32, savedErrno: Int32)?
    private var coldSchema2TerminalCloseResult: (returned: Int32, savedErrno: Int32)?
    private var coldSchema2TerminalStatResult: (returned: Int32, savedErrno: Int32,
        fact: EraseColdControlLeafFactV1)?
    private var coldSchema2RegistryCloseStarted = false
    private var coldSchema2RegistryCloseAttempt: ColdEraseSchema2RegistryControlCloseAttemptV1?
    private var coldSchema2TerminalUncertainDescriptor: Int32?
    fileprivate let exclusive: Bool

    fileprivate init(registry: GenerationLeaseRegistryV1, descriptor: Int32,
                     exclusive: Bool) {
        self.registry = registry
        self.descriptor = descriptor
        self.exclusive = exclusive
    }

    fileprivate func validate(for expectedRegistry: GenerationLeaseRegistryV1,
                              exclusive expectedExclusive: Bool) throws {
        lock.lock()
        defer { lock.unlock() }
        guard registry === expectedRegistry, exclusive == expectedExclusive,
              descriptor >= 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.validateTemporalActivityDescriptor(descriptor, observationOnly: exclusive)
    }

    fileprivate func validateSharedNormalizationRegistry(_ expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard exclusive, descriptor >= 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try registry.requireSharedTemporalRegistryIdentity(expected)
            try registry.validateTemporalActivityDescriptor(descriptor, observationOnly: true)
        }
    }

    /// Original Scratch lends this existing exclusive handle only. The fixed
    /// validator uses held/named identities and checked policy descriptors;
    /// it never takes SH, a second EX or an ordinary constructor/reopen.
    @MainActor
    fileprivate func validateOriginalEraseScratchCleanupRegistry(
        _ expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard registry === expected, exclusive, descriptor >= 0,
                  retirementCloseState == .open,
                  originalRecoveryUncertainCloseDescriptor == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.validateOriginalEraseScratchCleanupActivityDescriptor(descriptor)
        }
    }

    /// Only the Coordinator can hand out a retained producer resource. This
    /// checks the real SH descriptor without admitting or extending a writer.
    func requireLiveProducerResource() throws {
        try validate(for: registry, exclusive: false)
    }

    func closeCheckedForMaintenance() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if retirementCloseState == .closed { return }
            guard retirementCloseState == .open, exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.validateTemporalActivityDescriptor(descriptor, observationOnly: true)
            guard flock(descriptor, LOCK_UN) == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let owned = descriptor; descriptor = -1
            guard Darwin.close(owned) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    /// Cold C05 writer registration/release owns this exact SH description.
    /// It never upgrades to EX; a failed close is terminally uncertain.
    func closeCheckedForEraseC05ColdWriter() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if retirementCloseState == .closed { return }
            guard retirementCloseState == .open, !exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.validateTemporalActivityDescriptor(
                descriptor, observationOnly: true)
            guard flock(descriptor, LOCK_UN) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let owned = descriptor
            descriptor = -1
            guard Darwin.close(owned) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    fileprivate func validateAfterEraseC05GuardRemoval(
        registry expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard registry === expected, !exclusive,
                  retirementCloseState == .open, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireEraseC05PostGuardIdentity(
                activityDescriptor: descriptor)
        }
    }

    fileprivate func c05HeldDescriptorForGuardRemoval(
        registry expected: GenerationLeaseRegistryV1
    ) throws -> Int32 {
        try lock.withLock {
            guard registry === expected, !exclusive,
                  retirementCloseState == .open, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return descriptor
        }
    }

    /// Pure live resource association for the distinct cold Registry close.
    /// This getter neither reacquires a lock nor enters a closed Registry.
    @MainActor fileprivate func coldSchema2DescriptorForRegistryClose(
        registry expected: GenerationLeaseRegistryV1) throws -> Int32 {
        try lock.withLock {
            guard registry === expected, retirementCloseState == .open,
                  exclusive, descriptor >= 0,
                  coldSchema2TerminalReleaseProof == nil,
                  coldSchema2TerminalRegistryClose == nil,
                  coldSchema2TerminalUnlockResult == nil,
                  coldSchema2TerminalCloseResult == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return descriptor
        }
    }

    @MainActor fileprivate func retainColdSchema2RegistryCloseAttempt(
        _ attempt: ColdEraseSchema2RegistryControlCloseAttemptV1,
        registry expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected, retirementCloseState == .open,
                  exclusive, descriptor >= 0, !coldSchema2RegistryCloseStarted,
                  coldSchema2RegistryCloseAttempt == nil,
                  attempt.storage.activity === self,
                  attempt.storage.registry === expected,
                  attempt.storage.activityDescriptor == descriptor else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            coldSchema2RegistryCloseAttempt = attempt
            coldSchema2RegistryCloseStarted = true // permanent before Registry resource IO
        }
    }

    @MainActor fileprivate func requireColdSchema2RegistryCloseAttempt(
        _ attempt: ColdEraseSchema2RegistryControlCloseAttemptV1,
        registry expected: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard registry === expected, coldSchema2RegistryCloseStarted,
                  coldSchema2RegistryCloseAttempt === attempt else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    func closeCheckedAfterEraseC05GuardRemoval() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if retirementCloseState == .closed { return }
            guard retirementCloseState == .open, !exclusive,
                  descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireEraseC05PostGuardIdentity(
                activityDescriptor: descriptor)
            guard flock(descriptor, LOCK_UN) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let owned = descriptor
            descriptor = -1
            guard Darwin.close(owned) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    /// The original recovery observer closes this EX only after its own
    /// checked registry proof. An ambiguous unlock or close stays retained
    /// and makes the Registry terminal; no deinit retry is permitted.
    @MainActor
    func closeCheckedForOriginalEraseRecovery() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            guard retirementCloseState == .open, exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireOriginalEraseRecoveryActivityDescriptor(descriptor)
            guard flock(descriptor, LOCK_UN) == 0 else {
                registry.markOriginalEraseRecoveryUncertain()
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let owned = descriptor
            descriptor = -1
            guard Darwin.close(owned) == 0 else {
                originalRecoveryUncertainCloseDescriptor = owned
                registry.markOriginalEraseRecoveryUncertain()
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    @MainActor
    fileprivate func requireOriginalEraseRecoveryCheckedRegistry(
        _ expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard registry === expected, retirementCloseState == .open,
                  exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireOriginalEraseRecoveryActivityDescriptor(descriptor)
        }
    }

    func closeAfterColdOwnerGuardRemoval() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if retirementCloseState == .closed { return }
            guard retirementCloseState == .open, exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireColdGuardRemoved(activityDescriptor: descriptor)
            guard flock(descriptor, LOCK_UN) == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let owned = descriptor; descriptor = -1
            guard Darwin.close(owned) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    func closeAfterNamespaceRemoval() throws {
        try lock.withLock {
            guard !coldSchema2RegistryCloseStarted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if retirementCloseState == .closed { return }
            guard retirementCloseState == .open, exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireHeldTemporalNamespaceAfterRemoval(activityDescriptor: descriptor)
            guard flock(descriptor, LOCK_UN) == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let owned = descriptor; descriptor = -1
            guard Darwin.close(owned) == 0 else {
                retirementCloseState = .uncertain
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            retirementCloseState = .closed
        }
    }

    /// The same cold EX consumes the actual checked Registry-close lineage.
    /// No ordinary validator reopens the already closed Registry resources.
    @MainActor
    func closeColdSchema2AfterNamespaceRemoval(proof: ColdEraseSchema2TerminalReleaseProofV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        let registryClose = try proof.requireRegistryControlCloseForActivity(exclusion: exclusion,
            registry: registry, activity: self, binding: binding, witness: witness)
        // Receipt/descriptor association is checked outside this NSLock;
        // its memory getter takes the same lock and cannot be nested.
        let expected = try registryClose.requireActivityResource(activity: self,
            registry: registry, exclusion: exclusion, binding: binding, witness: witness)
        try lock.withLock {
            guard retirementCloseState == .open, exclusive, descriptor >= 0,
                  coldSchema2RegistryCloseStarted, coldSchema2RegistryCloseAttempt != nil,
                  coldSchema2TerminalReleaseProof == nil,
                  coldSchema2TerminalUnlockResult == nil, coldSchema2TerminalCloseResult == nil,
                  coldSchema2TerminalStatResult == nil,
                  coldSchema2TerminalUncertainDescriptor == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            var held = stat()
            let observed = Darwin.fstat(descriptor, &held), observationErrno = errno
            coldSchema2TerminalStatResult = (observed, observationErrno, EraseColdControlLeafFactV1(held))
            guard observed == 0,
                  EraseColdControlLeafFactV1(held) == expected,
                  held.st_mode & mode_t(S_IFMT) == mode_t(S_IFDIR), held.st_nlink == 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            coldSchema2TerminalReleaseProof = proof
            coldSchema2TerminalRegistryClose = registryClose
            let owned = descriptor
            descriptor = -1 // permanently before the first unlock/close attempt
            retirementCloseState = .uncertain
            coldSchema2TerminalUncertainDescriptor = owned
            let unlocked = flock(owned, LOCK_UN)
            let unlockErrno = errno
            coldSchema2TerminalUnlockResult = (unlocked, unlockErrno)
            guard unlocked == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let closed = Darwin.close(owned)
            let closeErrno = errno
            coldSchema2TerminalCloseResult = (closed, closeErrno)
            guard closed == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            coldSchema2TerminalUncertainDescriptor = nil
            retirementCloseState = .closed
        }
    }

    @MainActor
    func requireColdSchema2TerminalCheckedClosed(proof: ColdEraseSchema2TerminalReleaseProofV1) throws {
        try lock.withLock {
            guard retirementCloseState == .closed, exclusive, descriptor < 0,
                  coldSchema2TerminalReleaseProof === proof,
                  coldSchema2TerminalRegistryClose != nil,
                  coldSchema2TerminalStatResult?.returned == 0,
                  coldSchema2TerminalStatResult?.fact.links == 0,
                  coldSchema2TerminalUncertainDescriptor == nil,
                  coldSchema2TerminalUnlockResult?.returned == 0,
                  coldSchema2TerminalCloseResult?.returned == 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

#if DEBUG
    @MainActor
    func requireUnlinkedOriginalOwnerGuardForEraseAbandonment() throws {
        try lock.withLock {
            guard retirementCloseState == .open, exclusive, descriptor >= 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.proveUnlinkedOriginalOwnerGuardForEraseAbandonment(
                activityDescriptor: descriptor)
        }
    }
#endif

    func close() {
        lock.lock()
        defer { lock.unlock() }
        if coldSchema2RegistryCloseStarted { return }
        if case .uncertain = retirementCloseState { return }
        guard descriptor >= 0 else { return }
        let owned = descriptor
        descriptor = -1
        _ = flock(owned, LOCK_UN)
        _ = Darwin.close(owned)
    }

    deinit { close() }
}

extension GenerationLeaseRegistryV1 {
    /// No create or policy repair. A free directory lock establishes only
    /// exclusion; callers must still obtain their genuine generation owner.
    private func acquireTemporalActivity(exclusive: Bool) throws
        -> GenerationTemporalActivityHandleV1 {
        try verify()
        let descriptor = Darwin.openat(leaseDescriptor, ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        var transferred = false
        defer { if !transferred { _ = Darwin.close(descriptor) } }
        // Physical identity is pure. Ordinary policy verification may have
        // DEBUG fallback effects, so it must occur only AFTER SH admission.
        try validateTemporalActivityIdentity(descriptor)
        guard flock(descriptor, (exclusive ? LOCK_EX : LOCK_SH) | LOCK_NB) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do { try validateTemporalActivityDescriptor(descriptor, observationOnly: exclusive) }
        catch { _ = flock(descriptor, LOCK_UN); throw error }
        let handle = GenerationTemporalActivityHandleV1(registry: self,
            descriptor: descriptor, exclusive: exclusive)
        transferred = true
        return handle
    }

    fileprivate func validateTemporalActivityDescriptor(_ descriptor: Int32,
                                                       observationOnly: Bool) throws {
        try validateTemporalActivityIdentity(descriptor)
        if observationOnly {
            _ = try ProtectedFilePolicyV1.observeTemporalPolicy(.stagingDirectory, at: leaseURL)
        } else {
            try ProtectedFilePolicyV1.verify(.stagingDirectory, at: leaseURL)
        }
        try requireNamedDirectoryIdentity(parent: operationsDescriptor,
            name: Self.leaseDirectoryName, expected: leaseIdentity)
        guard try Self.directoryIdentity(descriptor) == leaseIdentity else {
            throw Self.identityFailure()
        }
    }

    private func validateTemporalActivityIdentity(_ descriptor: Int32) throws {
        try verify()
        guard try Self.directoryIdentity(descriptor) == leaseIdentity else {
            throw Self.identityFailure()
        }
        try requireNamedDirectoryIdentity(parent: operationsDescriptor,
            name: Self.leaseDirectoryName, expected: leaseIdentity)
    }

    /// Held only through a writer token's registry publication. This uses a
    /// distinct SH open description and never waits behind normalization.
    fileprivate func acquireTemporalWriterRegistrationActivity() throws
        -> GenerationTemporalActivityHandleV1 {
        try acquireTemporalActivity(exclusive: false)
    }

    func acquireTemporalProducerActivity(writer: GenerationLeaseTokenV1) throws
        -> GenerationTemporalActivityHandleV1 {
        let handle = try acquireTemporalActivity(exclusive: false)
        do {
            try withExclusiveGenerationMutationLock {
                try requireNoMigrationReservationLocked()
                try handle.validate(for: self, exclusive: false)
                try validateActiveLocked(writer, requiredRole: .writer)
            }
            return handle
        } catch {
            handle.close()
            throw error
        }
    }

    /// The caller has already closed its local admission and drained actual
    /// asynchronous work. A foreign writer is never guessed idle or harmless.
    func acquireTemporalNormalizationActivity(retainedWriter: GenerationLeaseTokenV1?) throws
        -> GenerationTemporalActivityHandleV1 {
        let handle = try acquireTemporalActivity(exclusive: true)
        do {
            try validateTemporalNormalizationActivity(handle, retainedWriter: retainedWriter)
            return handle
        } catch {
            handle.close()
            throw error
        }
    }

#if DEBUG
    /// The original owner already retained this exact EX before its pointer
    /// effect. Shutdown transfers that activity into the checked witness;
    /// acquiring another activity here would contend with the same EX.
    @MainActor
    func retainExistingTemporalNormalizationActivityForOriginalEraseShutdown(
        witness: EraseOriginalShutdownWitnessV1,
        activity: GenerationTemporalActivityHandleV1,
        retainedWriter: GenerationLeaseTokenV1
    ) throws -> OriginalEraseRetainedExclusionShutdownRegistryReceiptV1 {
        return try withOriginalEraseShutdownScope(witness) {
            try retainedWriter.validate()
            guard retainedWriter.ownerID == ownerID,
                  retainedWriter.role == .writer,
                  originalEraseForeignLeases == nil,
                  temporalReleaseAttempts.isEmpty,
                  preparationWriterPublications.isEmpty else {
                throw Self.uncertainOwnerFailure()
            }
            try withTemporalNormalizationMutationLock(activity: activity) {
                try requireNoMigrationReservationLocked()
                let observed = try observeTemporalRegistryLocked()
                guard observed.leases.filter({ $0.role == .writer })
                        == [retainedWriter],
                      observed.leases.filter({
                          $0.leaseID == retainedWriter.leaseID
                      }) == [retainedWriter],
                      originalEraseForeignLeases == nil,
                      temporalReleaseAttempts.isEmpty,
                      preparationWriterPublications.isEmpty else {
                    throw Self.uncertainOwnerFailure()
                }
                originalEraseForeignLeases = observed.leases.filter {
                    $0.ownerID != ownerID
                }
            }
            return OriginalEraseRetainedExclusionShutdownRegistryReceiptV1(
                registry: self, witness: witness, activity: activity,
                retainedWriter: retainedWriter)
        }
    }

    /// The retained operation receives the exact EX before any validation or
    /// root construction can throw. A failure leaves that owner reachable.
    @MainActor
    func acquireTemporalNormalizationActivityForOriginalEraseShutdown(
        witness: EraseOriginalShutdownWitnessV1,
        retainedWriter: GenerationLeaseTokenV1,
        retain: (GenerationTemporalActivityHandleV1) throws -> Void
    ) throws {
        try withOriginalEraseShutdownScope(witness) {
            guard retainedWriter.ownerID == ownerID,
                  retainedWriter.role == .writer else { throw Self.uncertainOwnerFailure() }
            let handle = try acquireTemporalActivity(exclusive: true)
            try retain(handle)
            try validateTemporalNormalizationActivity(handle, retainedWriter: retainedWriter)
            try withTemporalNormalizationMutationLock(activity: handle) {
                let observed = try observeTemporalRegistryLocked()
                originalEraseForeignLeases = observed.leases.filter { $0.ownerID != ownerID }
            }
        }
    }
#endif

    func validateTemporalProducerActivity(_ handle: GenerationTemporalActivityHandleV1,
                                         writer: GenerationLeaseTokenV1) throws {
        try withExclusiveGenerationMutationLock {
            try requireNoMigrationReservationLocked()
            try handle.validate(for: self, exclusive: false)
            try validateActiveLocked(writer, requiredRole: .writer)
        }
    }

    /// Full current writer census, re-read under the same G at every effect.
    /// This intentionally does not reconcile or delete abandoned owners.
    func validateTemporalNormalizationActivity(_ handle: GenerationTemporalActivityHandleV1,
                                              retainedWriter: GenerationLeaseTokenV1?) throws {
        try withTemporalNormalizationMutationLock(activity: handle) {
            try requireNoMigrationReservationLocked()
            try handle.validate(for: self, exclusive: true)
            let observation = try observeTemporalRegistryLocked()
            let writers = observation.leases.filter { $0.role == .writer }
            if let retainedWriter {
                try retainedWriter.validate()
                guard retainedWriter.role == .writer,
                      retainedWriter.ownerID == ownerID, writers == [retainedWriter] else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            } else {
                guard writers.isEmpty else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            }
            // This is writer census only. All reader/retired/source owners in
            // observation.leases still require the concrete source owner's
            // separate lifetime classification; EX does not discharge them.
        }
    }
}


/// Raw, independently reread registry facts. This has no completion/admission
/// bit: a source owner must classify every retained lease and its lifetime.
/// One exact C05 cold registry read. The Router operation retains this owner
/// before opening; a close error is terminal and its numeric FD is never retried.
@MainActor
final class EraseC05ColdRegistryObservationAttemptV1 {
    private var descriptor: Int32 = -1
    private var closeAttempted = false
    private var closeUncertain = false
    fileprivate func retain(_ value: Int32) {
        precondition(descriptor < 0 && !closeAttempted)
        descriptor = value
    }
    fileprivate func closeChecked() throws {
        guard !closeUncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if closeAttempted { return }
        closeAttempted = true
        guard descriptor >= 0 else { return }
        let owned = descriptor
        descriptor = -1
        guard Darwin.close(owned) == 0 else {
            closeUncertain = true
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

struct TemporalGenerationRegistryObservationV1 {
    let leases: [GenerationLeaseTokenV1]
    let registryBytes: Data
    let registryPolicy: TemporalPolicyObservationV1
    let directoryPolicy: TemporalPolicyObservationV1
}

extension GenerationLeaseRegistryV1 {
    private func observeTemporalRegistryLocked() throws -> TemporalGenerationRegistryObservationV1 {
        try verify()
        let directoryPolicy = try ProtectedFilePolicyV1.observeTemporalPolicy(.stagingDirectory, at: leaseURL)
        let descriptor = Darwin.openat(leaseDescriptor, Self.registryName,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        defer { _ = Darwin.close(descriptor) }
        let before = try Self.regularFileSnapshot(descriptor)
        try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryName, expected: before.identity)
        let policy = try ProtectedFilePolicyV1.observeTemporalPolicy(
            try Self.controlKind(for: Self.registryName),
            at: leaseURL.appendingPathComponent(Self.registryName))
        let data = try Self.readAll(from: descriptor)
        guard try Self.regularFileSnapshot(descriptor) == before,
              data.count == Int(before.byteCount) else { throw Self.identityFailure() }
        try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryName, expected: before.identity)
        let state: RegistryStateV1
        do { state = try RegistryStateV1.decodeCanonical(from: data) }
        catch { throw GenerationLeaseRegistryFailureV1.corruptRegistry }
        try verify()
        return TemporalGenerationRegistryObservationV1(leases: state.leases,
            registryBytes: data, registryPolicy: policy, directoryPolicy: directoryPolicy)
    }

    /// C05 cold observation retains the opened FD before any validation and
    /// closes it exactly once. A failing close leaves the attempt on the
    /// original cold operation and prevents a second numeric-FD attempt.
    @MainActor
    private func observeEraseC05ColdRegistryLocked(
        operation: EraseColdPreparationOperationV1
    ) throws -> TemporalGenerationRegistryObservationV1 {
        try operation.requireConstructedC05ColdRegistry(self)
        let attempt = EraseC05ColdRegistryObservationAttemptV1()
        try operation.retainC05ColdRegistryObservation(attempt, registry: self)
        let descriptor = Darwin.openat(leaseDescriptor, Self.registryName,
            O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        attempt.retain(descriptor)
        let result: TemporalGenerationRegistryObservationV1
        do {
            try verify()
            let directoryPolicy = try ProtectedFilePolicyV1.observeTemporalPolicy(
                .stagingDirectory, at: leaseURL)
            let before = try Self.regularFileSnapshot(descriptor)
            try requireNamedIdentity(parent: leaseDescriptor,
                name: Self.registryName, expected: before.identity)
            let policy = try ProtectedFilePolicyV1.observeTemporalPolicy(
                try Self.controlKind(for: Self.registryName),
                at: leaseURL.appendingPathComponent(Self.registryName))
            let data = try Self.readAll(from: descriptor)
            guard try Self.regularFileSnapshot(descriptor) == before,
                  data.count == Int(before.byteCount) else {
                throw Self.identityFailure()
            }
            try requireNamedIdentity(parent: leaseDescriptor,
                name: Self.registryName, expected: before.identity)
            let state: RegistryStateV1
            do { state = try RegistryStateV1.decodeCanonical(from: data) }
            catch { throw GenerationLeaseRegistryFailureV1.corruptRegistry }
            try verify()
            result = TemporalGenerationRegistryObservationV1(
                leases: state.leases, registryBytes: data,
                registryPolicy: policy, directoryPolicy: directoryPolicy)
        } catch {
            try attempt.closeChecked()
            throw error
        }
        try attempt.closeChecked()
        return result
    }

    /// Pure observation under the actual retained registry's G. The exact EX
    /// descriptor is required; this method never reconciles owners or controls.
    func observeTemporalNormalizationRegistry(_ handle: GenerationTemporalActivityHandleV1) throws
        -> TemporalGenerationRegistryObservationV1 {
        try withTemporalNormalizationMutationLock(activity: handle) {
            try requireNoMigrationReservationLocked()
            try handle.validate(for: self, exclusive: true)
            return try observeTemporalRegistryLocked()
        }
    }
}


extension GenerationLeaseRegistryV1 {
    fileprivate func requireSharedTemporalRegistryIdentity(_ other: GenerationLeaseRegistryV1) throws {
        try verify(); try other.verify()
        guard rootIdentity == other.rootIdentity,
              operationsIdentity == other.operationsIdentity,
              leaseIdentity == other.leaseIdentity,
              mutationLockIdentity == other.mutationLockIdentity else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}


extension GenerationLeaseRegistryV1 {
    /// Changes only this genuine handle's durable lease membership. Existing
    /// controls are read through pure observations; policy setters apply only
    /// to the new temp inode retained by this exact release attempt.
    fileprivate func releaseTemporalMaintenance(_ token: GenerationLeaseTokenV1,
        activity: GenerationTemporalActivityHandleV1) throws {
        try withTemporalNormalizationMutationLock(activity: activity) {
            try token.validate()
            guard token.ownerID == ownerID else { throw GenerationLeaseRegistryFailureV1.leaseNotActive }
            try activity.validateSharedNormalizationRegistry(self)
            let attempt: TemporalReleaseAttempt
            if let retained = temporalReleaseAttempts[token.leaseID] {
                guard retained.token == token else { throw GenerationLeaseRegistryFailureV1.leaseNotActive }
                attempt = retained
            } else {
                let observed = try observeTemporalRegistryLocked()
                guard observed.leases.filter({ $0.leaseID == token.leaseID }) == [token] else {
                    throw GenerationLeaseRegistryFailureV1.leaseNotActive
                }
                let replacement = try RegistryStateV1(leases: observed.leases.filter { $0.leaseID != token.leaseID })
                let original = Darwin.openat(leaseDescriptor, Self.registryName,
                    O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
                guard original >= 0 else { throw Self.mappedFailure() }
                do {
                    let snapshot = try Self.regularFileSnapshot(original)
                    try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryName,
                        expected: snapshot.identity)
                    let bytes = try Self.readAll(from: original)
                    guard bytes == observed.registryBytes,
                          try Self.regularFileSnapshot(original) == snapshot else { throw Self.identityFailure() }
                    attempt = TemporalReleaseAttempt(token: token, original: original,
                        snapshot: snapshot, originalBytes: bytes,
                        replacementBytes: try replacement.canonicalData())
                } catch { _ = Darwin.close(original); throw error }
                temporalReleaseAttempts[token.leaseID] = attempt
            }
            try finishTemporalReplacementLocked(attempt)
            let persisted = try observeTemporalRegistryLocked()
            guard !persisted.leases.contains(where: { $0.leaseID == token.leaseID }) else {
                throw GenerationLeaseRegistryFailureV1.corruptRegistry
            }
        }
        // Preserve the exact attempt until all G/activity postconditions have
        // returned successfully, not merely until the rename body finished.
        temporalReleaseAttempts.removeValue(forKey: token.leaseID)
    }
}


