@MainActor
final class GenerationWriterAllocationAttemptV1 {
    private struct CompletedStartupStorage {
        var entered = false
        weak var owner: ColdEraseSchema2CompletedStartupOwnerV1?
        var scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1?
        var publication: ColdEraseSchema2CompletedLeasePublicationV1?
    }
    private var completedStartupStorage = CompletedStartupStorage()
    static var completedStartupDeclaredRetentionBackingBytes: UInt64 {
        UInt64(MemoryLayout<CompletedStartupStorage>.stride)
    }
    var completedSchema2StartupCapturedToken: GenerationLeaseTokenV1? {
        completedStartupStorage.entered ? token : nil
    }
    private func requireNotCompletedStartupOrigin() throws {
        guard !completedStartupStorage.entered else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
    func acquireWriterForSchema2ColdCompletedStartup(owner expected: ColdEraseSchema2CompletedStartupOwnerV1) throws -> GenerationLeaseHandleV1 {
        guard !completedStartupStorage.entered, !preparationAcquisitionStarted, !acquisitionStarted, !restoreAcquisitionStarted,
              !closed, !sealedForRetirement, token == nil, handle == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireWriterAllocation(self, registry: registry)
        // Enter before Scope allocation. A thrown producer cannot retry or
        // fall through an ordinary/Original acquisition or failure disposer.
        completedStartupStorage.entered = true
        completedStartupStorage.owner = expected
        do {
            let scope = try registry.prepareSchema2ColdCompletedWriterAllocation(self, owner: expected)
            completedStartupStorage.scope = scope // before first token/helper IO
            let value = try registry.publishSchema2ColdCompletedStartupWriter(self, owner: expected, scope: scope)
            guard handle === value, token == value.token else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let publication = try ColdEraseSchema2CompletedLeasePublicationV1(owner: expected,
                registry: registry, scope: scope, writer: self, handle: value)
            completedStartupStorage.publication = publication
            try publication.requireRetainedWriter(self, owner: expected, registry: registry)
            return value
        } catch {
            sealedForRetirement = true
            completedStartupStorage.scope?.poisonOnUncertainEffect()
            throw error
        }
    }
    fileprivate func requireCompletedSchema2StartupAcquiring(_ expected: ColdEraseSchema2CompletedStartupOwnerV1,
        scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
        guard completedStartupStorage.entered, completedStartupStorage.owner === expected,
              completedStartupStorage.scope === scope, completedStartupStorage.publication == nil,
              !preparationAcquisitionStarted, !acquisitionStarted, !restoreAcquisitionStarted, !closed, !sealedForRetirement else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireWriterAllocation(self, registry: registry)
    }
    func requireCompletedSchema2StartupPublication(owner expected: ColdEraseSchema2CompletedStartupOwnerV1,
        registry expectedRegistry: GenerationLeaseRegistryV1) throws {
        guard completedStartupStorage.entered, completedStartupStorage.owner === expected,
              registry === expectedRegistry, !closed, !sealedForRetirement,
              let publication = completedStartupStorage.publication else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try publication.requireRetainedWriter(self, owner: expected, registry: registry)
    }
    func consumeCompletedSchema2StartupPublication(owner expected: ColdEraseSchema2CompletedStartupOwnerV1,
        registry expectedRegistry: GenerationLeaseRegistryV1,
        receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1) throws {
        try requireCompletedSchema2StartupPublication(owner: expected, registry: expectedRegistry)
        guard let publication = completedStartupStorage.publication,
              let scope = completedStartupStorage.scope else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try receiver.requireTransferredRegistry(registry: registry, owner: expected)
        try publication.consumePublishedOwnership(owner: expected, registry: registry)
        try scope.releaseAfterPublicationReceiver(receiver, registry: registry, owner: expected, writer: self)
    }

    func requireCompletedSchema2StartupOwnershipConsumed(owner expected: ColdEraseSchema2CompletedStartupOwnerV1,
        registry expectedRegistry: GenerationLeaseRegistryV1,
        receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1) throws {
        guard completedStartupStorage.entered, completedStartupStorage.owner === expected,
              registry === expectedRegistry, !closed, !sealedForRetirement,
              let publication = completedStartupStorage.publication else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try publication.requirePublishedOwnershipConsumed(owner: expected, registry: registry, receiver: receiver, writer: self)
    }

    fileprivate let registry: GenerationLeaseRegistryV1
    let generationEpoch: GenerationEpochV1
    fileprivate var token: GenerationLeaseTokenV1?
    fileprivate var handle: GenerationLeaseHandleV1?
    fileprivate var closed = false
    fileprivate var freshDisposalCompletion: FreshAdoptionDisposalCompletionV1?
    private var preparationAcquisitionStarted = false
    private weak var preparationOperation: EraseRouterOperationV1?
    private var acquisitionStarted = false
    private weak var adoption: EraseFreshAdoptionOwnerV1?
    private var restoreAcquisitionStarted = false
    private weak var restoreOwner: RestoreWriterTransitionOwnerV1?
    fileprivate var originalEraseWriterTreeIO:
        EraseAbortCheckedSnapshotIOV1?
    fileprivate var originalEraseOldWriterTreeIO:
        EraseAbortCheckedSnapshotIOV1?
    fileprivate var originalEraseWriterPublicationProjection:
        OriginalEraseRetainedWriterPublicationProjectionV1?
    fileprivate var originalEraseOldWriterReleaseProjection:
        OriginalEraseRetainedOldWriterReleaseProjectionV1?
    fileprivate var originalErasePermanentBackingV1: OriginalEraseWriterPermanentBackingReservationV1?
    fileprivate var originalErasePermanentPublicationV1: OriginalEraseWriterPermanentSettlementV1?
    fileprivate var originalErasePermanentReleaseV1: OriginalEraseWriterPermanentSettlementV1?
    fileprivate var originalEraseWriterProjectionUncertain = false
    fileprivate var originalEraseWriterEnumerationUncertain = false
    fileprivate var originalEraseOldWriterRetainedAttemptIdentity:
        ObjectIdentifier?
    fileprivate var originalEraseOldWriterRetryPending = false
    fileprivate var originalEraseOldWriterOpeningDescriptor: Int32 = -1
    private(set) var sealedForRetirement = false
    fileprivate init(registry: GenerationLeaseRegistryV1, epoch: GenerationEpochV1) {
        self.registry = registry; generationEpoch = epoch
    }
    var allocatedHandle: GenerationLeaseHandleV1? { handle }
    var originalEraseRetainedWriterPublicationProjection:
        OriginalEraseRetainedWriterPublicationProjectionV1? {
        guard !originalEraseWriterProjectionUncertain,
              !sealedForRetirement, !closed,
              handle != nil else { return nil }
        return originalEraseWriterPublicationProjection
    }
    var originalEraseRetainedOldWriterReleaseProjection:
        OriginalEraseRetainedOldWriterReleaseProjectionV1? {
        guard !originalEraseWriterProjectionUncertain,
              !sealedForRetirement, !closed,
              handle != nil else { return nil }
        return originalEraseOldWriterReleaseProjection
    }
    func matches(registry expected: GenerationLeaseRegistryV1) -> Bool { registry === expected }
    func sealForRetirement() { sealedForRetirement = true }
    func acquireWriter(adoption expected: EraseFreshAdoptionOwnerV1) throws -> GenerationLeaseHandleV1 {
        try requireNotCompletedStartupOrigin()
        try requireNotCompletedStartupOrigin()
        try requireNotCompletedStartupOrigin()
        guard !preparationAcquisitionStarted, !acquisitionStarted, !restoreAcquisitionStarted,
              !closed, !sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try expected.requireWriterAllocation(self, registry: registry)
        acquisitionStarted = true; adoption = expected
        do { return try registry.publishFreshAdoptionWriter(self, adoption: expected) }
        catch { sealedForRetirement = true; throw error }
    }
    fileprivate func requireAcquiring(adoption expected: EraseFreshAdoptionOwnerV1) throws {
        try requireNotCompletedStartupOrigin()
        guard acquisitionStarted, adoption === expected, !closed, !sealedForRetirement else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireWriterAllocation(self, registry: registry)
    }
    var preparationPublishedToken: GenerationLeaseTokenV1? {
        guard !completedStartupStorage.entered else { return nil }
        guard preparationAcquisitionStarted, !closed else { return nil }
        return registry.preparationPublishedToken(writer: self)
    }
    func acquireWriterForErasePreparation(operation expected: EraseRouterOperationV1) throws -> GenerationLeaseHandleV1 {
        try requireNotCompletedStartupOrigin()
        guard !preparationAcquisitionStarted, !acquisitionStarted, !restoreAcquisitionStarted,
              !closed, !sealedForRetirement,
              token == nil, handle == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try expected.requirePreparationWriterAllocation(self, registry: registry)
        preparationAcquisitionStarted = true; preparationOperation = expected
        do { return try registry.publishPreparationWriter(self, operation: expected) }
        catch { sealedForRetirement = true; throw error }
    }

    /// Original Erase has already retained its one EX/G owner and complete
    /// auxiliary pre-effect roster. This route cannot fall back to the
    /// ordinary writer-registration activity or a second Registry owner.
    func acquireWriterForOriginalEraseUnderRetainedExclusion(
        operation expected: EraseRouterOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        oldWriter: GenerationLeaseHandleV1
    ) throws -> GenerationLeaseHandleV1 {
        try requireNotCompletedStartupOrigin()
        guard !preparationAcquisitionStarted, !acquisitionStarted,
              !restoreAcquisitionStarted, !closed, !sealedForRetirement,
              token == nil, handle == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requirePreparationWriterAllocation(self,
            registry: registry)
        preparationAcquisitionStarted = true
        preparationOperation = expected
        do {
            return try registry
                .publishOriginalErasePreparationWriterUnderRetainedExclusion(
                    self, operation: expected, activity: activity,
                    oldWriter: oldWriter)
        } catch {
            // Every physical attempt remains on this exact retained wrapper.
            // A thrown publication never falls back to ordinary activation.
            sealedForRetirement = true
            throw error
        }
    }
    fileprivate func requirePreparationAcquiring(_ expected: EraseRouterOperationV1) throws {
        try requireNotCompletedStartupOrigin()
        guard preparationAcquisitionStarted, !acquisitionStarted, preparationOperation === expected,
              !closed, !sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try expected.requirePreparationWriterAllocation(self, registry: registry)
    }
    fileprivate func requirePreparationDisposalEligibility() throws {
        try requireNotCompletedStartupOrigin()
        guard !acquisitionStarted, !restoreAcquisitionStarted,
              preparationAcquisitionStarted || (token == nil && handle == nil) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    /// The Router retains this exact attempt before the first durable B writer
    /// publication. An ambiguous publication is never replaced by an ordinary
    /// writer acquisition or by an Erase allocation.
    func acquireWriterForRestoreTransition(
        owner expected: RestoreWriterTransitionOwnerV1
    ) throws -> GenerationLeaseHandleV1 {
        try requireNotCompletedStartupOrigin()
        guard !preparationAcquisitionStarted, !acquisitionStarted,
              !restoreAcquisitionStarted, !closed, !sealedForRetirement,
              token == nil, handle == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireWriterAllocation(self, registry: registry)
        restoreAcquisitionStarted = true
        restoreOwner = expected
        do { return try registry.publishRestoreTransitionWriter(self, owner: expected) }
        catch { sealedForRetirement = true; throw error }
    }

    fileprivate func requireRestoreAcquiring(
        _ expected: RestoreWriterTransitionOwnerV1
    ) throws {
        try requireNotCompletedStartupOrigin()
        guard restoreAcquisitionStarted, !preparationAcquisitionStarted,
              !acquisitionStarted, restoreOwner === expected,
              !closed, !sealedForRetirement else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireWriterAllocation(self, registry: registry)
    }

    func closeAfterRestoreTransitionFailure(
        owner expected: RestoreWriterTransitionOwnerV1
    ) throws {
        try requireNotCompletedStartupOrigin()
        try expected.requireFailedWriterDrained(self, registry: registry)
        guard restoreAcquisitionStarted, sealedForRetirement,
              restoreOwner === expected else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if closed { return }
        try registry.closeRestoreTransitionWriter(self, owner: expected)
        closed = true
    }
#if DEBUG
    /// Installed target writers are eligible only through this exact original
    /// shutdown witness. The ordinary preparation-failure close stays guarded.
    func closeForOriginalEraseShutdown(proof: EraseOriginalShutdownWitnessV1,
        activity: GenerationTemporalActivityHandleV1) throws {
        try requireNotCompletedStartupOrigin()
        try proof.requirePreparationWriter(self, registry: registry)
        try requirePreparationDisposalEligibility()
        guard sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if closed { return }
        if let handle {
            try handle.closeForOriginalEraseShutdown(witness: proof, activity: activity)
        } else {
            guard token == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
        closed = true
    }
#endif

    func closeAfterErasePreparationFailure(proof: ErasePreparationFailureDrainWitnessV1) throws {
        try requireNotCompletedStartupOrigin()
        try proof.requireDrained(registry: registry, writerAllocation: self)
        try requirePreparationDisposalEligibility()
        guard sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if closed { return }
        try registry.closePreparationWriter(self, proof: proof)
        closed = true
    }
    func closeAfterEraseFreshAdoptionFailure(proof: EraseFreshAdoptionDrainWitnessV1) throws {
        try requireNotCompletedStartupOrigin()
        try proof.requireDrained(registry: registry, writerAllocation: self)
        guard !preparationAcquisitionStarted, sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if closed { return }
        try registry.closeFreshAdoptionWriter(self, proof: proof)
        closed = true
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor
    fileprivate func requireOriginalEraseWriterProjectionSettled(
        allocation: GenerationWriterAllocationAttemptV1
    ) throws {
        guard allocation.registry === self,
              !allocation.originalEraseWriterProjectionUncertain,
              !originalEraseWriterProjectionUncertain,
              !originalEraseRetainedReaderEffectUncertain else {
            throw Self.uncertainOwnerFailure()
        }
    }

    /// A checked, nonrecursive G completion for the two original writer
    /// Registry effects. The private receipt is constructed only after this
    /// scope reports a checked unlock; an ambiguous effect stays poisoned.
    @MainActor
    private func withOriginalEraseWriterProjectionG<Value>(
        allocation: GenerationWriterAllocationAttemptV1,
        activity: GenerationTemporalActivityHandleV1,
        retainedRetryProof: (() throws -> Bool)? = nil,
        permanentSettlement: OriginalEraseWriterPermanentSettlementV1,
        _ body: () throws -> Value
    ) throws -> Value {
        try activity.validateSharedNormalizationRegistry(self)
        Self.processMutationLock.lock()
        defer { Self.processMutationLock.unlock() }
        try permanentSettlement.storage.reservation.requireAssociation(registry: self,
            operation: try permanentOriginalEraseOperationV1(permanentSettlement), allocation: allocation)
        try permanentSettlement.storage.reservation.chargeGBirth()
        let gReturn = OriginalEraseWriterPermanentGReturnV1(previous: permanentSettlement.storage.lastG,
            descriptor: mutationLockDescriptor)
        permanentSettlement.storage.lastG = gReturn // before actual G call
        guard let causalIO = permanentSettlement.storage.treeIO else { throw Self.uncertainOwnerFailure() }
        let causalOwner = try OriginalEraseSelectedControlSnapshotOwnerV1.makeBeforeActualScope(
            snapshotIO: causalIO, backing: permanentSettlement.storage.reservation.storage.selectedControlBackingV1)
        permanentSettlement.storage.selectedControlOwnerV1 = causalOwner // before actual G entry
        permanentSettlement.storage.selectedControlPostV1 = nil
        guard !originalEraseWriterProjectionUncertain,
              !allocation.originalEraseWriterProjectionUncertain,
              generationMutationLockDepth == 0 else {
            originalEraseWriterProjectionUncertain = true
            allocation.originalEraseWriterProjectionUncertain = true
            throw Self.uncertainOwnerFailure()
        }
        gReturn.storage.lockEntered = true
        let lockResult = flock(mutationLockDescriptor, LOCK_EX), lockErrno = errno
        gReturn.storage.lockResult = lockResult; gReturn.storage.lockErrno = lockErrno
        guard lockResult == 0 else {
            originalEraseWriterProjectionUncertain = true
            allocation.originalEraseWriterProjectionUncertain = true
            throw Self.uncertainOwnerFailure()
        }
        generationMutationLockDepth = 1
        var causalStarted = false
        defer {
            if causalStarted {
                causalIO.finishSelectedControlActualScopeV1(causalOwner, error: gReturn.storage.scopeSucceeded ? nil
                    : gReturn.storage.bodyError ?? gReturn.storage.boundaryError ?? Self.uncertainOwnerFailure())
            }
        }
        var result: Result<Value, any Error>?
        var retryAllowed = false
        do {
            try causalIO.beginSelectedControlActualScopeV1(causalOwner)
            causalStarted = true
            try activity.validateSharedNormalizationRegistry(self)
            try verify(causalIO: causalIO)
            result = Result { try body() }
            gReturn.storage.bodyReturned = true
            if case .success = result { gReturn.storage.bodySucceeded = true }
            if case .failure(let error) = result { gReturn.storage.bodyError = error }
            try verify(causalIO: causalIO)
            if case .success = result {
                let post = try causalOwner.finishPostFrame()
                permanentSettlement.storage.selectedControlPostV1 = post
            }
            try activity.validateSharedNormalizationRegistry(self)
        } catch {
            gReturn.storage.boundaryError = error
            result = .failure(error)
        }
        if case .failure = result,
           let retainedRetryProof {
            retryAllowed = (try? retainedRetryProof()) == true
        }
        gReturn.storage.retryAllowed = retryAllowed
        gReturn.storage.unlockEntered = true
        let unlockResult = flock(mutationLockDescriptor, LOCK_UN), unlockErrno = errno
        gReturn.storage.unlockResult = unlockResult; gReturn.storage.unlockErrno = unlockErrno
        guard unlockResult == 0 else {
            originalEraseWriterProjectionUncertain = true
            allocation.originalEraseWriterProjectionUncertain = true
            throw Self.uncertainOwnerFailure()
        }
        generationMutationLockDepth = 0
        guard let result else { throw Self.uncertainOwnerFailure() }
        do {
            let value = try result.get()
            gReturn.storage.scopeSucceeded = true; gReturn.storage.returned = true
            return value
        }
        catch {
            if !retryAllowed {
                originalEraseWriterProjectionUncertain = true
                allocation.originalEraseWriterProjectionUncertain = true
            } else {
                allocation.originalEraseOldWriterRetryPending = true
            }
            throw error
        }
    }

    @MainActor
    private func originalEraseWriterLeaseNames(
        allocation: GenerationWriterAllocationAttemptV1,
        allowOwnedTemporary: Bool = false, causalIO: EraseAbortCheckedSnapshotIOV1? = nil
    ) throws -> [String] {
        guard !allocation.originalEraseWriterEnumerationUncertain else {
            throw Self.uncertainOwnerFailure()
        }
        if let io = causalIO {
            try io.selectedControlContextV1(.leaseNames, parent: leaseDescriptor, name: ".")
            do {
                let names = try io.names(in: leaseDescriptor)
                guard names.count == Set(names).count,
                      allowOwnedTemporary || !names.contains(Self.registryTemporaryName) else { throw Self.uncertainOwnerFailure() }
                return names
            } catch {
                do { try io.requireSettled() }
                catch { allocation.originalEraseWriterEnumerationUncertain = true }
                throw error
            }
        }
        let descriptor = Darwin.openat(leaseDescriptor, ".",
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw Self.mappedFailure() }
        guard let stream = Darwin.fdopendir(descriptor) else {
            guard Darwin.close(descriptor) == 0 else {
                allocation.originalEraseWriterEnumerationUncertain = true
                throw Self.uncertainOwnerFailure()
            }
            throw Self.mappedFailure()
        }
        var names: [String] = []
        var readFailure = false
        errno = 0
        while let entry = Darwin.readdir(stream) {
            guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                readFailure = true
                break
            }
            if name != "." && name != ".." { names.append(name) }
            errno = 0
        }
        if errno != 0 { readFailure = true }
        guard Darwin.closedir(stream) == 0 else {
            allocation.originalEraseWriterEnumerationUncertain = true
            throw Self.uncertainOwnerFailure()
        }
        guard !readFailure, names.count == Set(names).count,
              (allowOwnedTemporary ||
                !names.contains(Self.registryTemporaryName)) else {
            throw Self.uncertainOwnerFailure()
        }
        return names.sorted()
    }

    /// Only registry.json and its owned temporary may change in either
    /// writer transition. Owners, lock, reader record and prune controls are
    /// checked independently as complete siblings, not inferred from names.
    @MainActor
    private func originalEraseWriterUnchangedSiblings(
        names: [String], io: EraseAbortCheckedSnapshotIOV1
    ) throws -> [OriginalEraseRetainedLeaseSiblingV1] {
        var values: [OriginalEraseRetainedLeaseSiblingV1] = []
        for name in names where name != Self.registryName
            && name != Self.registryTemporaryName {
            try io.selectedControlContextV1(.sibling(name), parent: leaseDescriptor, name: name)
            var before = stat(), after = stat()
            guard try io.selectedControlFStatAtV1(leaseDescriptor, name, &before,
                    AT_SYMLINK_NOFOLLOW) == 0 else {
                throw Self.uncertainOwnerFailure()
            }
            let kind: String
            let digest: String
            switch before.st_mode & S_IFMT {
            case S_IFDIR:
                kind = "directory"
                digest = try io.postRetiredTree(
                    parent: leaseDescriptor, name: name)
            case S_IFREG:
                kind = "regular"
                guard before.st_nlink == 1 else {
                    throw Self.uncertainOwnerFailure()
                }
                digest = try io.withOpen(parent: leaseDescriptor,
                    name: name, flags: O_RDONLY | O_NONBLOCK) { fd in
                    var held = stat(), heldAfter = stat()
                    guard try io.selectedControlFStatV1(fd, &held) == 0,
                          Self.originalEraseRetainedFullFact(held)
                            == Self.originalEraseRetainedFullFact(before),
                          io.selectedControlOwnerV1 == nil || Self.selectedControlFullStatEqualV1(before, held)
                    else { throw Self.uncertainOwnerFailure() }
                    let bytes = try Self.selectedControlReadAllV1(from: fd, io: io)
                    try io.selectedControlOwnerV1?.retainBytes(bytes, role: .sibling(name), descriptor: fd)
                    guard try io.selectedControlFStatV1(fd, &heldAfter) == 0,
                          Self.originalEraseRetainedFullFact(heldAfter)
                            == Self.originalEraseRetainedFullFact(held),
                          io.selectedControlOwnerV1 == nil || Self.selectedControlFullStatEqualV1(held, heldAfter)
                    else { throw Self.uncertainOwnerFailure() }
                    return StoreMigrationCanonicalJSONV1.sha256(bytes)
                }
            default:
                throw Self.uncertainOwnerFailure()
            }
            guard try io.selectedControlFStatAtV1(leaseDescriptor, name, &after,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  Self.originalEraseRetainedFullFact(before)
                    == Self.originalEraseRetainedFullFact(after),
                  io.selectedControlOwnerV1 == nil || Self.selectedControlFullStatEqualV1(before, after) else {
                throw Self.uncertainOwnerFailure()
            }
            values.append(OriginalEraseRetainedLeaseSiblingV1(
                name: name, kind: kind,
                fullFact: Self.originalEraseRetainedFullFact(before),
                digest: digest))
        }
        try io.requireSettled()
        return values
    }

    @MainActor
    func makeWriterAllocationAttempt(epoch: GenerationEpochV1) throws -> GenerationWriterAllocationAttemptV1 {
        try epoch.validate()
        return GenerationWriterAllocationAttemptV1(registry: self, epoch: epoch)
    }
    /// Captures only this actual retained replacement's original descriptor.
    /// Caller registers `record` before this first open; failed fstat/read and
    /// canonical encoding leave that exact FD owned for fixed disposal.
    private func captureFreshAdoptionReplacementLocked(_ record: FreshAdoptionReplacement,
        observed: TemporalGenerationRegistryObservationV1, replacement: RegistryStateV1, causalIO: EraseAbortCheckedSnapshotIOV1? = nil) throws {
        try causalIO?.selectedControlContextV1(.registryPre, parent: leaseDescriptor, name: Self.registryName)
        guard record.replacement == nil, !record.originalCloseAttempted, !record.closeUncertain else { throw Self.identityFailure() }
        if record.original < 0 {
            let raw = try causalIO?.selectedControlKernelV1(.borrowedOpen, parent: leaseDescriptor, name: Self.registryName, {
                Int64(Darwin.openat(leaseDescriptor, Self.registryName, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC))
            }) ?? Int64(Darwin.openat(leaseDescriptor, Self.registryName, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC))
            guard let fd = Int32(exactly: raw) else { throw Self.identityFailure() }
            guard fd >= 0 else { throw Self.mappedFailure() }
            record.original = fd
        }
        let fd = record.original
        let snapshot = try Self.regularFileSnapshot(fd, causalIO: causalIO)
        try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryName, expected: snapshot.identity, causalIO: causalIO)
        let bytes = try Self.selectedControlReadAllV1(from: fd, io: causalIO)
        guard bytes == observed.registryBytes, try Self.regularFileSnapshot(fd, causalIO: causalIO) == snapshot else { throw Self.identityFailure() }
        let attempt = TemporalReleaseAttempt(token: record.token, original: fd, snapshot: snapshot,
            originalBytes: bytes, replacementBytes: try replacement.canonicalData())
        record.replacement = attempt
        record.original = -1 // transfer only after the actual replacement owns it
    }
    @MainActor
    fileprivate func publishFreshAdoptionWriter(_ allocation: GenerationWriterAllocationAttemptV1,
        adoption: EraseFreshAdoptionOwnerV1) throws -> GenerationLeaseHandleV1 {
        guard allocation.registry === self else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try allocation.requireAcquiring(adoption: adoption)
        let handle = try withExclusiveGenerationMutationLock {
            try allocation.requireAcquiring(adoption: adoption)
            try requireNoMigrationReservationLocked()
            let observed = try observeTemporalRegistryLocked()
            guard !observed.leases.contains(where: { $0.role == .writer }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            guard observed.leases.count < Self.maximumActiveLeaseCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let owners = Set(observed.leases.map(\.ownerID))
            guard owners.contains(ownerID) || owners.count < Self.maximumOwnerCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let token = try GenerationLeaseTokenV1(leaseID: makeLeaseID(), ownerID: ownerID,
                epoch: allocation.generationEpoch, role: .writer, acquiredAt: now())
            guard !observed.leases.contains(where: { $0.leaseID == token.leaseID }), allocation.token == nil else {
                throw GenerationLeaseRegistryFailureV1.duplicateLease
            }
            allocation.token = token
            let record = FreshAdoptionReplacement(token: token)
            let id = ObjectIdentifier(allocation)
            guard freshWriterPublications[id] == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            freshWriterPublications[id] = record
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases + [token]))
            guard let attempt = record.replacement else { throw Self.identityFailure() }
            try finishTemporalReplacementLocked(attempt)
            let current = try observeTemporalRegistryLocked()
            guard current.leases.filter({ $0.role == .writer }) == [token] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let handle = try GenerationLeaseHandleV1(registry: self, publishedWriterToken: token)
            allocation.handle = handle // before outer G/post-admission can throw
            try allocation.requireAcquiring(adoption: adoption)
            return handle
        }
        try allocation.requireAcquiring(adoption: adoption)
        try withExclusiveGenerationMutationLock {
            try allocation.requireAcquiring(adoption: adoption)
            guard let record = freshWriterPublications[ObjectIdentifier(allocation)] else { throw Self.identityFailure() }
            let observed = try observeTemporalRegistryLocked()
            guard observed.leases.filter({ $0.leaseID == handle.token.leaseID }) == [handle.token] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try record.closeOwnedDescriptorsChecked()
            freshWriterPublications.removeValue(forKey: ObjectIdentifier(allocation))
        }
        try allocation.requireAcquiring(adoption: adoption)
        return handle
    }

    /// Restore's target writer is a different authority from Erase adoption.
    /// The Router-owned attempt is retained before this method opens or
    /// publishes anything; the existing fixed replacement record owns every
    /// partial rename and descriptor until its checked disposition.
    @MainActor
    fileprivate func publishRestoreTransitionWriter(
        _ allocation: GenerationWriterAllocationAttemptV1,
        owner: RestoreWriterTransitionOwnerV1
    ) throws -> GenerationLeaseHandleV1 {
        guard allocation.registry === self else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try allocation.requireRestoreAcquiring(owner)
        let handle = try withExclusiveGenerationMutationLock {
            try allocation.requireRestoreAcquiring(owner)
            try requireNoMigrationReservationLocked()
            let observed = try observeTemporalRegistryLocked()
            try owner.requireWriterLeaseCensus(observed.leases, registry: self)
            guard !observed.leases.contains(where: { $0.role == .writer }),
                  observed.leases.count < Self.maximumActiveLeaseCount else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let owners = Set(observed.leases.map(\.ownerID))
            guard owners.contains(ownerID) || owners.count < Self.maximumOwnerCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let token = try GenerationLeaseTokenV1(
                leaseID: makeLeaseID(), ownerID: ownerID,
                epoch: allocation.generationEpoch, role: .writer, acquiredAt: now())
            guard !observed.leases.contains(where: { $0.leaseID == token.leaseID }),
                  allocation.token == nil else {
                throw GenerationLeaseRegistryFailureV1.duplicateLease
            }
            allocation.token = token
            let record = FreshAdoptionReplacement(token: token)
            let id = ObjectIdentifier(allocation)
            guard freshWriterPublications[id] == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            freshWriterPublications[id] = record
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases + [token]))
            guard let attempt = record.replacement else { throw Self.identityFailure() }
            try finishTemporalReplacementLocked(attempt)
            let current = try observeTemporalRegistryLocked()
            try owner.requirePublishedWriterLeaseCensus(
                current.leases, token: token, registry: self)
            let handle = try GenerationLeaseHandleV1(
                registry: self, publishedWriterToken: token)
            allocation.handle = handle
            try allocation.requireRestoreAcquiring(owner)
            return handle
        }
        try allocation.requireRestoreAcquiring(owner)
        try withExclusiveGenerationMutationLock {
            try allocation.requireRestoreAcquiring(owner)
            guard let record = freshWriterPublications[ObjectIdentifier(allocation)] else {
                throw Self.identityFailure()
            }
            let observed = try observeTemporalRegistryLocked()
            try owner.requirePublishedWriterLeaseCensus(
                observed.leases, token: handle.token, registry: self)
            try record.closeOwnedDescriptorsChecked()
            freshWriterPublications.removeValue(forKey: ObjectIdentifier(allocation))
        }
        try allocation.requireRestoreAcquiring(owner)
        return handle
    }

    @MainActor
    fileprivate func publishFreshAdoptionReader(_ allocation: GenerationLeaseAllocationAttemptV1,
        adoption: EraseFreshAdoptionOwnerV1) throws -> GenerationLeaseHandleV1 {
        guard allocation.registry === self else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try allocation.requireFreshAdoptionAcquiring(adoption)
        let handle = try withExclusiveGenerationMutationLock {
            try allocation.requireFreshAdoptionAcquiring(adoption)
            try requireNoMigrationReservationLocked()
            let observed = try observeTemporalRegistryLocked()
            guard !observed.leases.contains(where: { $0.role == .writer }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            guard observed.leases.count < Self.maximumActiveLeaseCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let owners = Set(observed.leases.map(\.ownerID))
            guard owners.contains(ownerID) || owners.count < Self.maximumOwnerCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let token = try GenerationLeaseTokenV1(leaseID: makeLeaseID(), ownerID: ownerID,
                epoch: allocation.epoch, role: .reader, acquiredAt: now())
            guard !observed.leases.contains(where: { $0.leaseID == token.leaseID }), allocation.token == nil else {
                throw GenerationLeaseRegistryFailureV1.duplicateLease
            }
            allocation.token = token
            let record = FreshAdoptionReplacement(token: token)
            let id = ObjectIdentifier(allocation)
            guard freshReaderPublications[id] == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            freshReaderPublications[id] = record
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases + [token]))
            guard let attempt = record.replacement else { throw Self.identityFailure() }
            try finishTemporalReplacementLocked(attempt)
            let current = try observeTemporalRegistryLocked()
            guard current.leases.filter({ $0.leaseID == token.leaseID }) == [token],
                  !current.leases.contains(where: { $0.role == .writer }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let handle = try GenerationLeaseHandleV1(registry: self, publishedReaderToken: token)
            allocation.handle = handle // before outer G/post-admission can throw
            try allocation.requireFreshAdoptionAcquiring(adoption)
            return handle
        }
        try allocation.requireFreshAdoptionAcquiring(adoption)
        try withExclusiveGenerationMutationLock {
            try allocation.requireFreshAdoptionAcquiring(adoption)
            guard let record = freshReaderPublications[ObjectIdentifier(allocation)] else { throw Self.identityFailure() }
            let observed = try observeTemporalRegistryLocked()
            guard observed.leases.filter({ $0.leaseID == handle.token.leaseID }) == [handle.token] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try record.closeOwnedDescriptorsChecked()
            freshReaderPublications.removeValue(forKey: ObjectIdentifier(allocation))
        }
        try allocation.requireFreshAdoptionAcquiring(adoption)
        return handle
    }

    /// Disposes only a retained insertion that never crossed rename. Never
    /// publishes a synthetic lease merely to be able to release one.
    private func abandonFreshAdoptionInsertionLocked(_ attempt: TemporalReleaseAttempt) throws {
        try attempt.requireCertainDescriptors()
        guard !attempt.renamed else { throw Self.identityFailure() }
        try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryName, expected: attempt.originalSnapshot.identity)
        guard try Self.regularFileSnapshot(attempt.original) == attempt.originalSnapshot else { throw Self.identityFailure() }
        if attempt.temporary >= 0, !attempt.temporaryRemoved {
            let held = try Self.regularFileIdentity(attempt.temporary)
            if let expected = attempt.temporaryIdentity { guard held == expected else { throw Self.identityFailure() } }
            else { attempt.temporaryIdentity = held } // actual still-held O_EXCL-created FD, never name discovery
            try requireNamedIdentity(parent: leaseDescriptor, name: Self.registryTemporaryName, expected: held)
            guard Darwin.unlinkat(leaseDescriptor, Self.registryTemporaryName, 0) == 0 else { throw Self.mappedFailure() }
            attempt.temporaryRemoved = true
        }
        if attempt.temporaryRemoved {
            var held = stat(), named = stat()
            guard let identity = attempt.temporaryIdentity,
                  Darwin.fstat(attempt.temporary, &held) == 0,
                  held.st_dev == identity.device, held.st_ino == identity.inode,
                  held.st_nlink == 0, held.st_mode & S_IFMT == S_IFREG,
                  Darwin.fstatat(leaseDescriptor, Self.registryTemporaryName, &named, AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else { throw Self.identityFailure() }
        }
        guard Darwin.fsync(leaseDescriptor) == 0,
              try !observeTemporalRegistryLocked().leases.contains(where: { $0.leaseID == attempt.token.leaseID }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    /// Fixed genuine fresh-owner release under ordinary SH + G. The caller's
    /// exact weak-alias witness is checked before and after this operation.
    private func releaseFreshAdoptionTokenLocked(_ token: GenerationLeaseTokenV1) throws {
        try token.validate()
        guard token.ownerID == ownerID else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let record: FreshAdoptionReplacement
        if let retained = freshAdoptionReleases[token.leaseID] {
            guard retained.token == token else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            record = retained
        } else {
            let observed = try observeTemporalRegistryLocked()
            guard observed.leases.filter({ $0.leaseID == token.leaseID }) == [token] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            record = FreshAdoptionReplacement(token: token)
            freshAdoptionReleases[token.leaseID] = record
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases.filter { $0.leaseID != token.leaseID }))
        }
        guard !record.closeUncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if record.replacement == nil {
            // Retry the same retained read/capture record and descriptor. No
            // second removal owner or reconstructed publication is introduced.
            let observed = try observeTemporalRegistryLocked()
            guard observed.leases.filter({ $0.leaseID == token.leaseID }) == [token] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases.filter { $0.leaseID != token.leaseID }))
        }
        guard let attempt = record.replacement else { throw Self.identityFailure() }
        try finishTemporalReplacementLocked(attempt)
        guard try !observeTemporalRegistryLocked().leases.contains(where: { $0.leaseID == token.leaseID }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        record.completed = true
    }
    private func finishFreshAdoptionRelease(_ token: GenerationLeaseTokenV1) throws {
        guard let record = freshAdoptionReleases[token.leaseID], record.completed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try record.closeOwnedDescriptorsChecked()
        freshAdoptionReleases.removeValue(forKey: token.leaseID)
    }
    private func requireFreshDisposalCompletionLocked(_ completion: FreshAdoptionDisposalCompletionV1,
        token: GenerationLeaseTokenV1?, handle: GenerationLeaseHandleV1?) throws {
        guard completion.token == token else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if let token {
            guard freshAdoptionReleases[token.leaseID] == nil,
                  try !observeTemporalRegistryLocked().leases.contains(where: { $0.leaseID == token.leaseID }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        try handle?.requireRecordedFreshAdoptionRelease(registry: self)
    }
    @MainActor
    fileprivate func closeFreshAdoptionWriter(_ allocation: GenerationWriterAllocationAttemptV1,
        proof: EraseFreshAdoptionDrainWitnessV1) throws {
        guard allocation.registry === self, allocation.sealedForRetirement else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try proof.requireDrained(registry: self, writerAllocation: allocation)
        try withExclusiveGenerationMutationLock {
            try proof.requireDrained(registry: self, writerAllocation: allocation)
            if let completed = allocation.freshDisposalCompletion {
                guard freshWriterPublications[ObjectIdentifier(allocation)] == nil else { throw Self.identityFailure() }
                try requireFreshDisposalCompletionLocked(completed, token: allocation.token, handle: allocation.handle)
                return
            }
            if let retained = freshWriterPublications[ObjectIdentifier(allocation)], retained.closeUncertain {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            var published = allocation.handle != nil
            if let insertion = freshWriterPublications[ObjectIdentifier(allocation)]?.replacement {
                if insertion.renamed {
                    published = true
                    if allocation.handle == nil, freshAdoptionReleases[insertion.token.leaseID] == nil {
                        try finishTemporalReplacementLocked(insertion)
                    }
                } else { try abandonFreshAdoptionInsertionLocked(insertion) }
            }
            if published {
                guard let token = allocation.token else { throw Self.identityFailure() }
                try releaseFreshAdoptionTokenLocked(token)
                try finishFreshAdoptionRelease(token)
            } else if let token = allocation.token {
                guard try !observeTemporalRegistryLocked().leases.contains(where: { $0.leaseID == token.leaseID }) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
            if let insertion = freshWriterPublications[ObjectIdentifier(allocation)] {
                try insertion.closeOwnedDescriptorsChecked()
                freshWriterPublications.removeValue(forKey: ObjectIdentifier(allocation))
            }
            try allocation.handle?.recordFreshAdoptionRelease(registry: self)
            allocation.freshDisposalCompletion = .init(token: allocation.token)
            try proof.requireDrained(registry: self, writerAllocation: allocation)
        }
        try proof.requireDrained(registry: self, writerAllocation: allocation)
    }

    @MainActor
    fileprivate func closeRestoreTransitionWriter(
        _ allocation: GenerationWriterAllocationAttemptV1,
