            } else if let token = allocation.token {
                guard try !observeTemporalRegistryLocked().leases.contains(
                    where: { $0.leaseID == token.leaseID }) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
