            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGNamedBefore)
            #endif
            try requireOriginalEraseScratchCleanupNamedRegistry()
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGCohort)
            #endif
            let cohort = try operation
                .requireOriginalEraseScratchCleanupEffectUnderHeldG(
                    registry: self, activity: activity, store: store,
                    exclusion: exclusion)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGMigrationBefore)
            #endif
            let migrationBefore = try observeOriginalEraseScratchCleanupNoMigrationReservationLocked(
                activity: activity, operation: operation, store: store,
                exclusion: exclusion, expectedCohort: cohort)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGRegistryBefore)
            #endif
            let before = try observeOriginalEraseScratchCleanupRegistryLocked(
                activity: activity, operation: operation, store: store,
                exclusion: exclusion, expectedCohort: cohort)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGCohortBeforeGuard)
            #endif
            guard before.leases == cohort else {
                throw Self.uncertainOwnerFailure()
            }
            let held = OriginalEraseScratchCleanupHeldGScopeV1(
                registry: self, operation: operation, store: store,
                exclusion: exclusion, activity: activity, cohort: cohort)
            scope = held
            originalEraseScratchCleanupEffectScope = held // BEFORE control/body IO
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGHeldBefore)
            #endif
            try held.requireHeld(operation: operation, store: store,
                registry: self, exclusion: exclusion, activity: activity)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlMaker)
            #endif
            let controlsScope = try operation.makeOriginalEraseScratchCanonicalControlReadScope(
                heldG: held, registry: self, activity: activity,
                store: store, exclusion: exclusion)
            controlReadScope = controlsScope // Router also retains BEFORE reader IO
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGExpectedControlGuard)
            #endif
            guard controlsScope.purpose == .originalScratchCleanupFixedConsumer,
                  controlsScope.expectedIntent.schemaVersion == 2,
                  controlsScope.expectedIntent.phase == .sessionActivated,
                  controlsScope.expectedPreparation.matches(controlsScope.expectedIntent) else {
