            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlScopeBefore)
            #endif
            try controlsScope.requireHeld(store: store)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlsBefore)
            #endif
            let controlsBefore = try store.observeOriginalCanonicalControls(scope: controlsScope)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGHeldBeforeBody)
            #endif
            try held.requireHeld(operation: operation, store: store,
                registry: self, exclusion: exclusion, activity: activity)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGBody)
            #endif
            let receipt = try body(held)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGReceiptSettlement)
            #endif
            try receipt.requireCheckedSettlement()
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGReceiptOrigin)
            #endif
            try receipt.requireBound(operation: operation, store: store,
                registry: self, exclusion: exclusion, activity: activity)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGHeldAfterBody)
            #endif
            try held.requireHeld(operation: operation, store: store,
                registry: self, exclusion: exclusion, activity: activity)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGRegistryAfter)
            #endif
            let after = try observeOriginalEraseScratchCleanupRegistryLocked(
                activity: activity, operation: operation, store: store,
                exclusion: exclusion, expectedCohort: cohort)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGRegistryEqualityGuard)
            #endif
            guard after.leases == before.leases,
                  after.registryBytes == before.registryBytes,
                  after.registryPolicy == before.registryPolicy,
                  after.directoryPolicy == before.directoryPolicy else {
