            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlScopeAfter)
            #endif
            try controlsScope.requireHeld(store: store)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlsAfter)
            #endif
            let controlsAfter = try store.observeOriginalCanonicalControls(scope: controlsScope)
            #if DEBUG
            operation.recordOriginalScratchLoanDiagnosticStep(.effectGControlEquality)
            #endif
