        }
    }
}

/// A cold Scratch interval is minted only by the actual Registry while its
/// mutation depth is one. It carries the retained operation/Store/activity;
/// no decoded control, callback or numeric descriptor constructs this owner.
@MainActor
final class ColdEraseScratchCleanupHeldGScopeV1 {
    private enum State: Equatable { case held, revoked, released, uncertain }
    let operationID: UUID
    private let operationIdentity: ObjectIdentifier
    private let storeIdentity: ObjectIdentifier
    private let registryIdentity: ObjectIdentifier
    private let activityIdentity: ObjectIdentifier
    private var operation: EraseColdPreparationOperationV1?
    private var store: EraseIntentStore?
    private var registry: GenerationLeaseRegistryV1?
    private var activity: GenerationTemporalActivityHandleV1?
    fileprivate let cohort: [GenerationLeaseTokenV1]
    private var state: State = .held

    fileprivate init(operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore, registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1,
        cohort: [GenerationLeaseTokenV1]) {
        operationID = operation.retainedColdOperationIDForComparison
        operationIdentity = ObjectIdentifier(operation)
        storeIdentity = ObjectIdentifier(store)
        registryIdentity = ObjectIdentifier(registry)
        activityIdentity = ObjectIdentifier(activity)
        self.operation = operation; self.store = store
        self.registry = registry; self.activity = activity
        self.cohort = cohort
    }

    func requireNonrecursiveCurrentFrame() throws {
        do {
            guard state == .held, let operation, let store,
                  let registry, let activity else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireColdScratchNonrecursiveScope(self,
                operation: operation, store: store, activity: activity)
        } catch { poisonOnUncertainCleanup(); throw error }
    }

    func requireHeld() throws {
        try requireNonrecursiveCurrentFrame()
        do {
            guard let registry, let activity else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try activity.validateColdScratchRegistry(registry)
            try requireNonrecursiveCurrentFrame()
        } catch { poisonOnUncertainCleanup(); throw error }
    }

    func requireOrigin(operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore) throws {
        try requireNonrecursiveCurrentFrame()
        guard self.operation === operation, self.store === store else {
            poisonOnUncertainCleanup()
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    func requireCurrentTokenCensus() throws {
        try requireHeld()
        do {
            guard let operation, let store, let registry, let activity else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try registry.requireColdScratchTokenCensus(self, operation: operation,
                store: store, activity: activity)
            try requireHeld()
        } catch { poisonOnUncertainCleanup(); throw error }
    }

    func poisonOnUncertainCleanup() {
        guard state != .released else { return }
        state = .uncertain
        operation?.poisonColdScratchOwner()
        registry?.poisonColdScratchScope()
    }

    fileprivate func revokeBeforeUnlock() {
        if state == .held { state = .revoked }
    }

    fileprivate func completeCheckedUnlock() throws {
        guard state == .revoked, operation != nil, store != nil,
              registry != nil, activity != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        state = .released
        operation = nil; store = nil; registry = nil; activity = nil
    }

    func requireCheckedRelease(operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore, registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1) throws {
        guard state == .released,
              operationIdentity == ObjectIdentifier(operation),
              storeIdentity == ObjectIdentifier(store),
              registryIdentity == ObjectIdentifier(registry),
              activityIdentity == ObjectIdentifier(activity),
              operationID == operation.retainedColdOperationIDForComparison else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

extension GenerationTemporalActivityHandleV1 {
    @MainActor fileprivate func validateColdScratchRegistry(
        _ expected: GenerationLeaseRegistryV1
    ) throws {
        try lock.withLock {
            guard registry === expected, exclusive, descriptor >= 0,
                  retirementCloseState == .open,
                  originalRecoveryUncertainCloseDescriptor == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try expected.validateColdScratchActivityDescriptor(descriptor)
        }
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func requireColdScratchTokenCensus(
        _ scope: ColdEraseScratchCleanupHeldGScopeV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        activity: GenerationTemporalActivityHandleV1) throws {
        try requireColdScratchNonrecursiveScope(scope, operation: operation,
            store: store, activity: activity)
        guard try readEraseSchema2ColdRegistryLocked(operation: operation) == scope.cohort else {
            throw Self.uncertainOwnerFailure()
        }
        try requireColdScratchNonrecursiveScope(scope, operation: operation,
            store: store, activity: activity)
    }

    @MainActor fileprivate func validateColdScratchActivityDescriptor(
        _ descriptor: Int32
    ) throws {
        try requireColdScratchNamedRegistry()
        guard try Self.directoryIdentity(descriptor) == leaseIdentity else {
            throw Self.identityFailure()
        }
        try requireColdScratchNamedRegistry()
    }

    @MainActor fileprivate func poisonColdScratchScope() {
        coldEraseScratchScopeUncertain = true
    }

    /// No loader/observer/G acquisition here. Store and policy checks can
    /// call this frame without scope→Store→scope recursion.
    @MainActor fileprivate func requireColdScratchNonrecursiveScope(
        _ scope: ColdEraseScratchCleanupHeldGScopeV1,
        operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore,
        activity: GenerationTemporalActivityHandleV1
    ) throws {
        guard isEraseSchema2ColdOwner, !isEraseC05ColdOwner,
              generationMutationLockDepth == 1,
              coldEraseScratchScope === scope,
              !coldEraseScratchScopeUncertain,
              !eraseSchema2ColdMutationUncertain,
              eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
              !restoreSourceCloseLock.withLock({ restoreSourceTerminal }),
              try operation.requireColdScratchNonrecursiveFrame(
                store: store, registry: self, activity: activity,
                scope: scope) == scope.cohort else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    @MainActor fileprivate func requireColdScratchNamedRegistry() throws {
        guard isEraseSchema2ColdOwner, !isEraseC05ColdOwner,
              !coldEraseScratchScopeUncertain,
              !eraseSchema2ColdMutationUncertain,
              eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
              !restoreSourceCloseLock.withLock({ restoreSourceTerminal }) else {
            throw Self.uncertainOwnerFailure()
        }
        var named = stat()
        guard Darwin.lstat(applicationSupportURL.path, &named) == 0,
              named.st_mode & S_IFMT == S_IFDIR, named.st_nlink >= 1,
              Identity(named) == rootIdentity,
              try Self.directoryIdentity(rootDescriptor) == rootIdentity,
              try Self.directoryIdentity(operationsDescriptor) == operationsIdentity,
              try Self.directoryIdentity(leaseDescriptor) == leaseIdentity,
              try Self.directoryIdentity(ownersDescriptor) == ownersIdentity,
              try Self.regularFileIdentity(mutationLockDescriptor) == mutationLockIdentity,
              try Self.regularFileIdentity(ownerLockDescriptor) == ownerLockIdentity else {
            throw Self.identityFailure()
        }
        for (parent, name, expected) in [
            (rootDescriptor, Self.operationsName, operationsIdentity),
            (operationsDescriptor, Self.leaseDirectoryName, leaseIdentity),
            (leaseDescriptor, Self.ownerDirectoryName, ownersIdentity),
            (leaseDescriptor, Self.mutationLockName, mutationLockIdentity),
            (ownersDescriptor, Self.ownerLockName(ownerID), ownerLockIdentity)
        ] {
            guard Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  Identity(named) == expected,
                  ((named.st_mode & S_IFMT == S_IFDIR && named.st_nlink >= 1)
                    || (named.st_mode & S_IFMT == S_IFREG && named.st_nlink == 1
                        && named.st_size >= 0
                        && named.st_size <= off_t(Self.maximumControlFileBytes))) else {
                throw Self.identityFailure()
            }
        }
        let policy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(
            .stagingDirectory, at: leaseURL,
            retainUncertainDescriptor: {
                self.eraseSchema2ColdPolicyUncertainDescriptors.append($0)
            })
        guard policy.state == .strictComplete,
              eraseSchema2ColdPolicyUncertainDescriptors.isEmpty else {
            throw Self.uncertainOwnerFailure()
        }
    }

    /// Same genuine EX/activity, with exact token census on both sides. The
    /// scope is revoked inside the G body, before the existing wrapper unlocks.
    @MainActor
    func withColdScratchHeldG<Value>(operation: EraseColdPreparationOperationV1,
        store: EraseIntentStore, activity: GenerationTemporalActivityHandleV1,
        _ body: @MainActor (ColdEraseScratchCleanupHeldGScopeV1) throws -> Value
    ) throws -> Value {
        guard coldEraseScratchScope == nil, !coldEraseScratchScopeUncertain else {
            throw Self.uncertainOwnerFailure()
        }
        let expected = try operation.requireColdScratchNonrecursiveFrame(
            store: store, registry: self, activity: activity, scope: nil)
        var retained: ColdEraseScratchCleanupHeldGScopeV1?
        do {
            let value = try withEraseSchema2ColdMutationLock(
                operation: operation, activity: activity) {
                try requireColdScratchNamedRegistry()
                guard try readEraseSchema2ColdRegistryLocked(operation: operation)
                        == expected else { throw Self.uncertainOwnerFailure() }
                let scope = ColdEraseScratchCleanupHeldGScopeV1(operation: operation,
                    store: store, registry: self, activity: activity, cohort: expected)
                retained = scope
                coldEraseScratchScope = scope
                try operation.retainColdScratchHeldG(scope, store: store,
                    registry: self, activity: activity)
                defer { scope.revokeBeforeUnlock() }
                try scope.requireHeld()
                let value = try body(scope)
                try scope.requireHeld()
                guard try readEraseSchema2ColdRegistryLocked(operation: operation)
                        == expected else { throw Self.uncertainOwnerFailure() }
                try requireColdScratchNamedRegistry()
                return value
            }
            guard let retained else { throw Self.uncertainOwnerFailure() }
            try retained.completeCheckedUnlock()
            try operation.completeColdScratchHeldG(retained, store: store,
                registry: self, activity: activity)
            coldEraseScratchScope = nil
            return value
        } catch {
            retained?.revokeBeforeUnlock()
            retained?.poisonOnUncertainCleanup()
            coldEraseScratchScopeUncertain = true
            operation.poisonColdScratchOwner()
            throw error
        }
    }
}

/// A predecessor guard is probed only while the exact cold Registry holds G
/// and the operation holds its pre-existing lease EX. The opened descriptor is
/// retained by the operation before any stat, policy observation, or flock.
/// An unlocked guard is evidence about this one owner, not permission to
/// reconcile tokens or delete an Operations subtree.
@MainActor
final class EraseSchema2ColdGuardProbeV1 {
    private struct GuardFact: Equatable {
        let device: dev_t, inode: ino_t, mode: mode_t
        let links: nlink_t, size: off_t
        let modifiedSeconds: Int64, modifiedNanoseconds: Int64
        let changedSeconds: Int64, changedNanoseconds: Int64
        init(_ value: stat) {
            device = value.st_dev; inode = value.st_ino
            mode = value.st_mode; links = value.st_nlink
            size = value.st_size
            modifiedSeconds = Int64(value.st_mtimespec.tv_sec)
            modifiedNanoseconds = Int64(value.st_mtimespec.tv_nsec)
            changedSeconds = Int64(value.st_ctimespec.tv_sec)
            changedNanoseconds = Int64(value.st_ctimespec.tv_nsec)
        }
    }
    let predecessor: UUID
    var heldDevice: dev_t { device }
    var heldInode: ino_t { inode }
    private(set) var descriptor: Int32 = -1
    private var parent: Int32 = -1
    private var name = ""
    private var device: dev_t = 0
    private var inode: ino_t = 0
    private var original: GuardFact?
    private var locked = false
    private var closeAttempted = false
    private var uncertain = false
    var isCheckedClosed: Bool { closeAttempted && !uncertain && descriptor < 0 }

    init(predecessor: UUID) { self.predecessor = predecessor }

    fileprivate func retain(_ value: Int32, parent: Int32, name: String) throws {
        guard descriptor < 0, !closeAttempted, !uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        descriptor = value
        self.parent = parent
        self.name = name
    }

    fileprivate func bindAndLock() throws {
        guard descriptor >= 0, !locked, !closeAttempted, !uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
              held.st_mode & S_IFMT == S_IFREG, held.st_nlink == 1,
              held.st_size == 0,
              named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1,
              GuardFact(held) == GuardFact(named),
              flock(descriptor, LOCK_EX | LOCK_NB) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // The lock remains held across later effect reproof; do not accept
        // an inode/name swap immediately after acquiring it.
        locked = true
        device = held.st_dev
        inode = held.st_ino
        original = GuardFact(held)
        try requireHeldNamed()
    }

    func requireHeldNamed() throws {
        guard descriptor >= 0, locked, !closeAttempted, !uncertain,
              let original else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
              GuardFact(held) == original,
              GuardFact(named) == original else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    func closeAfterFailureChecked() throws {
        guard !closeAttempted, !uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if descriptor < 0 {
            closeAttempted = true
            return
        }
        closeAttempted = true
        uncertain = true
        if locked {
            guard flock(descriptor, LOCK_UN) == 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            locked = false
        }
        let owned = descriptor
        descriptor = -1
        guard Darwin.close(owned) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        uncertain = false
    }
}

extension GenerationLeaseRegistryV1 {
    /// Observes only predecessor guards named by the canonical Registry.
    /// Extra orphan guards and partial namespace subsets require the separate
    /// six-owner classifier; this method never removes them or a lease token.
    @MainActor
    func probeEraseSchema2ColdPredecessors(
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        expectedTokens: [GenerationLeaseTokenV1]
    ) throws -> [EraseSchema2ColdGuardProbeV1] {
        try withEraseSchema2ColdMutationLock(operation: operation,
            activity: activity) {
            let tokens = try readEraseSchema2ColdRegistryLocked(
                operation: operation)
            guard tokens == expectedTokens else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let predecessors = Set(tokens.map(\.ownerID))
                .subtracting([ownerID])
            var probes: [EraseSchema2ColdGuardProbeV1] = []
            for previous in predecessors.sorted(by: Self.idOrder) {
                let probe = EraseSchema2ColdGuardProbeV1(
                    predecessor: previous)
                try operation.retainSchema2ColdGuardProbe(probe,
                    registry: self)
                let name = Self.ownerLockName(previous)
                let descriptor = Darwin.openat(ownersDescriptor, name,
                    O_RDWR | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
                guard descriptor >= 0 else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try probe.retain(descriptor, parent: ownersDescriptor,
                    name: name)
                try probe.bindAndLock()
                let guardPolicy = try ProtectedFilePolicyV1
                    .observeTemporalPolicyWithCheckedClose(
                        .generationLeaseOwnerLock,
                        at: ownersURL.appendingPathComponent(name),
                        retainUncertainDescriptor: { value in
                            self.eraseSchema2ColdPolicyUncertainDescriptors
                                .append(value)
                        })
                guard guardPolicy.state == .strictComplete,
                      eraseSchema2ColdPolicyUncertainDescriptors.isEmpty else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try probe.requireHeldNamed()
                probes.append(probe)
            }
            return probes
        }
    }
}


extension GenerationLeaseRegistryV1 {
    /// Value-only full census. Only this Registry's actual held-G reader makes
    /// it; it carries no publication, token-close or namespace authority.
    fileprivate struct ColdSchema2RetirementCensusV1: Equatable {
        let tokens: [GenerationLeaseTokenV1]
        let leaseNames: [String]
        let ownerNames: [String]
        let facts: [String: String]
        let bytes: [String: Data]
        let policies: [String: TemporalPolicyObservationV1]
    }

    @MainActor
    private func requireColdSchema2RetirementOrigin(
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1, heldG: Bool) throws -> [GenerationLeaseTokenV1] {
        guard isEraseSchema2ColdOwner, !isEraseC05ColdOwner,
              !coldSchema2RetirementUncertain,
              !eraseSchema2ColdMutationUncertain,
              !coldEraseScratchScopeUncertain, coldEraseScratchScope == nil,
              eraseSchema2ColdPolicyUncertainDescriptors.isEmpty,
              generationMutationLockDepth == (heldG ? 1 : 0) else {
            throw Self.uncertainOwnerFailure()
        }
        try coldSchema2RetirementIO.requireSettled()
        let expected = try operation.requireColdSchema2RetirementFrame(
            exclusion: exclusion, binding: binding, witness: witness,
            registry: self, activity: activity)
        try exclusion.requireSupport(binding: binding)
        try witness.requireDrained(binding: binding)
        try activity.validateColdScratchRegistry(self)
        try requireTemporalEraseNamespace(binding.registryIdentity)
        return expected
    }

    /// One checked G only; the already consumed same-EX successor and actual
    /// activity remain owners. The failed interval is permanently fenced even
    /// if its kernel unlock succeeds. No descriptor integer is retried.
    @MainActor
    private func withColdSchema2RetirementG<Value>(
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1,
        _ body: @MainActor () throws -> Value) throws -> Value {
        _ = try requireColdSchema2RetirementOrigin(operation: operation,
            activity: activity, exclusion: exclusion, binding: binding,
            witness: witness, heldG: false)
        Self.processMutationLock.lock()
        defer { Self.processMutationLock.unlock() }
        guard generationMutationLockDepth == 0,
              flock(mutationLockDescriptor, LOCK_EX) == 0 else {
            coldSchema2RetirementUncertain = true
            operation.poisonColdScratchOwner()
            throw Self.uncertainOwnerFailure()
        }
        generationMutationLockDepth = 1
        let outcome = Result<Value, Error> {
            _ = try requireColdSchema2RetirementOrigin(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding,
                witness: witness, heldG: true)
            let value = try body()
            _ = try requireColdSchema2RetirementOrigin(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding,
                witness: witness, heldG: true)
            return value
        }
        let unlock = flock(mutationLockDescriptor, LOCK_UN)
        let unlockErrno = errno
        guard unlock == 0 else {
            coldSchema2RetirementUncertain = true
            operation.poisonColdScratchOwner()
            throw Self.identityFailure(errorNumber: unlockErrno)
        }
        generationMutationLockDepth = 0
        do { return try outcome.get() }
        catch {
            coldSchema2RetirementUncertain = true
            operation.poisonColdScratchOwner()
            throw error
        }
    }

    /// Fixed <=4MiB readonly leaf consumer. Each actual FD is registered on
    /// the operation before open; all policy and own IO closes are checked.
    /// Positive short reads advance, errors including EINTR are not retried.
    @MainActor
    private func readColdSchema2RetirementControl(
        parent: Int32, name: String, url: URL, kind: OwnedFileKindV1,
        operation: EraseColdPreparationOperationV1,
        requireOrigin: @MainActor () throws -> Void) throws -> (bytes: Data, fact: String,
        policy: TemporalPolicyObservationV1)? {
        try requireOrigin()
        let attempt = EraseSchema2ColdRegistryObservationAttemptV1()
        try operation.retainSchema2ColdRegistryObservation(attempt, registry: self)
        @MainActor func read() throws -> (bytes: Data, fact: String, policy: TemporalPolicyObservationV1)? {
            var named = stat()
            let found = Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW)
            let foundErrno = errno
            if found < 0 {
                guard foundErrno == ENOENT else { throw Self.identityFailure(errorNumber: foundErrno) }
                try requireOrigin()
                guard Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) < 0,
                      errno == ENOENT else { throw Self.identityFailure() }
                return nil
            }
            guard named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1,
                  named.st_size >= 0, named.st_size <= off_t(Self.maximumControlFileBytes) else {
                throw Self.identityFailure()
            }
            let fact = Self.originalEraseRetainedFullFact(named)
            let descriptor = Darwin.openat(parent, name,
                O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
            let openErrno = errno
            guard descriptor >= 0 else { throw Self.identityFailure(errorNumber: openErrno) }
            try attempt.retain(descriptor)
            @MainActor func requireLeaf() throws {
                try requireOrigin()
                var held = stat(), current = stat()
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &current, AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(held) == fact,
                      Self.originalEraseRetainedFullFact(current) == fact else {
                    throw Self.identityFailure()
                }
            }
            try requireLeaf()
            let policy = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(kind,
                at: url, retainUncertainDescriptor: {
                    self.eraseSchema2ColdPolicyUncertainDescriptors.append($0)
                })
            guard policy.state == .strictComplete,
                  eraseSchema2ColdPolicyUncertainDescriptors.isEmpty else {
                throw Self.uncertainOwnerFailure()
            }
            var bytes = Data(count: Int(named.st_size))
            try bytes.withUnsafeMutableBytes { buffer in
                var offset = 0
                while offset < buffer.count {
                    try requireLeaf()
                    let wanted = min(64 * 1024, buffer.count - offset)
                    let count = Darwin.pread(descriptor,
                        buffer.baseAddress!.advanced(by: offset), wanted, off_t(offset))
                    let readErrno = errno
                    try requireLeaf()
                    guard count > 0, count <= wanted else {
                        throw Self.identityFailure(errorNumber: count < 0 ? readErrno : EIO)
                    }
                    offset += count
                }
            }
            try requireLeaf()
            var extra: UInt8 = 0
            let eof = Darwin.pread(descriptor, &extra, 1, named.st_size)
            let eofErrno = errno
            try requireLeaf()
            guard eof == 0 else { throw Self.identityFailure(errorNumber: eof < 0 ? eofErrno : EIO) }
            return (bytes, fact, policy)
        }
        let observed: (bytes: Data, fact: String, policy: TemporalPolicyObservationV1)?
        do { observed = try read() }
        catch { try attempt.closeChecked(); throw error }
        try attempt.closeChecked()
        try requireOrigin()
        return observed
    }

    /// Complete owner/control inventory and the ordinary reservation predicate
    /// through a distinct checked consumer. No aggregate initializer or ordinary
    /// temporal observer can replace this actual retained reader.
    @MainActor
    private func observeColdSchema2RetirementCensusLocked(
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdSchema2RetirementCensusV1 {
        @MainActor func requireOrigin() throws {
            _ = try requireColdSchema2RetirementOrigin(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding,
                witness: witness, heldG: true)
        }
        try requireOrigin()
        var facts: [String: String] = [:], bytes: [String: Data] = [:]
        var policies: [String: TemporalPolicyObservationV1] = [:]
        func retain(_ key: String, _ value: (bytes: Data, fact: String,
            policy: TemporalPolicyObservationV1)?) {
            if let value { facts[key] = value.fact; bytes[key] = value.bytes; policies[key] = value.policy }
        }
        func directoryFact(_ descriptor: Int32) throws -> String {
            var held = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  held.st_mode & S_IFMT == S_IFDIR, held.st_nlink >= 1 else {
                throw Self.identityFailure()
            }
            return Self.originalEraseRetainedFullFact(held)
        }
        facts["lease-root"] = try directoryFact(leaseDescriptor)
        facts["owner-root"] = try directoryFact(ownersDescriptor)
        let leaseNames = try coldSchema2RetirementIO.boundedNames(in: leaseDescriptor, maximumCount: 6)
        let ownerNames = try coldSchema2RetirementIO.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount)
        var heldLeaseRoot = stat(), heldOwnerRoot = stat()
        guard Darwin.fstat(leaseDescriptor, &heldLeaseRoot) == 0,
              Darwin.fstat(ownersDescriptor, &heldOwnerRoot) == 0,
              Self.originalEraseRetainedFullFact(heldLeaseRoot) == facts["lease-root"],
              Self.originalEraseRetainedFullFact(heldOwnerRoot) == facts["owner-root"],
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(heldLeaseRoot.st_nlink),
                directEntryCount: leaseNames.count),
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(heldOwnerRoot.st_nlink),
                directEntryCount: ownerNames.count) else { throw Self.identityFailure() }
        let allowed: Set<String> = [Self.registryName, Self.mutationLockName,
            Self.ownerDirectoryName, Self.pruneIntentName, Self.pruneReceiptName,
            Self.schema2ColdReaderRecordName]
        guard leaseNames.count == Set(leaseNames).count,
              Set(leaseNames).isSubset(of: allowed),
              Set([Self.registryName, Self.mutationLockName, Self.ownerDirectoryName])
                .isSubset(of: Set(leaseNames)),
              ownerNames.count == Set(ownerNames).count,
              ownerNames.count <= Self.maximumOwnerCount,
              ownerNames.contains(Self.ownerLockName(ownerID)) else { throw Self.uncertainOwnerFailure() }
        for name in leaseNames where name != Self.ownerDirectoryName {
            let value = try readColdSchema2RetirementControl(parent: leaseDescriptor,
                name: name, url: leaseURL.appendingPathComponent(name),
                kind: name == Self.mutationLockName ? .generationLeaseControl
                    : Self.controlKind(for: name), operation: operation,
                requireOrigin: requireOrigin)
            guard let value else { throw Self.identityFailure() }
            if name == Self.mutationLockName { guard value.bytes.isEmpty else { throw Self.identityFailure() } }
            retain("lease/" + name, value)
        }
        for name in ownerNames {
            guard name.hasSuffix(".lock"),
                  let id = UUID(uuidString: String(name.dropLast(5))),
                  Self.ownerLockName(id) == name else { throw Self.identityFailure() }
            let value = try readColdSchema2RetirementControl(parent: ownersDescriptor,
                name: name, url: ownersURL.appendingPathComponent(name),
                kind: .generationLeaseOwnerLock, operation: operation,
                requireOrigin: requireOrigin)
            guard let value, value.bytes.isEmpty else { throw Self.identityFailure() }
            retain("owners/" + name, value)
        }
        guard let registryBytes = bytes["lease/" + Self.registryName] else { throw Self.identityFailure() }
        let tokens = try RegistryStateV1.decodeCanonical(from: registryBytes).leases
        guard tokens == (try operation.requireColdSchema2RetirementFrame(
            exclusion: exclusion, binding: binding, witness: witness,
            registry: self, activity: activity)),
              Set(tokens.map({ Self.ownerLockName($0.ownerID) })).isSubset(of: Set(ownerNames)) else {
            throw Self.uncertainOwnerFailure()
        }
        var migration = stat()
        let found = Darwin.fstatat(operationsDescriptor, "schema-migration", &migration, AT_SYMLINK_NOFOLLOW)
        let foundErrno = errno
        if found < 0 {
            guard foundErrno == ENOENT else { throw Self.identityFailure(errorNumber: foundErrno) }
            try requireOrigin()
            guard Darwin.fstatat(operationsDescriptor, "schema-migration", &migration,
                    AT_SYMLINK_NOFOLLOW) < 0, errno == ENOENT else { throw Self.identityFailure() }
        } else {
            guard migration.st_mode & S_IFMT == S_IFDIR, migration.st_nlink >= 1 else { throw Self.identityFailure() }
            let before = Self.originalEraseRetainedFullFact(migration)
            try coldSchema2RetirementIO.withOpen(parent: operationsDescriptor, name: "schema-migration",
                flags: O_RDONLY | O_DIRECTORY) { directory in
                guard try directoryFact(directory) == before else { throw Self.identityFailure() }
                let url = operationsURL.appendingPathComponent("schema-migration")
                let canonical = try readColdSchema2RetirementControl(parent: directory,
                    name: StoreAggregateMigrationControlV1.name,
                    url: url.appendingPathComponent(StoreAggregateMigrationControlV1.name),
                    kind: .journal, operation: operation, requireOrigin: requireOrigin)
                let temporary = try readColdSchema2RetirementControl(parent: directory,
                    name: StoreAggregateMigrationControlV1.temporaryName,
                    url: url.appendingPathComponent(StoreAggregateMigrationControlV1.temporaryName),
                    kind: .journalTemporary, operation: operation, requireOrigin: requireOrigin)
                let value = try canonical.map { try StoreAggregateMigrationJournalV1.decodeCanonical(from: $0.bytes) }
                if let temporary {
                    let pending = try StoreAggregateMigrationJournalV1.decodeCanonical(from: temporary.bytes)
                    if let value {
                        let nextValue = value.revision.addingReportingOverflow(1)
                        let nextPending = pending.revision.addingReportingOverflow(1)
                        if !nextValue.overflow, pending.revision == nextValue.partialValue {
                            try pending.validateReplacement(of: value)
                        } else if !nextPending.overflow, value.revision == nextPending.partialValue {
                            try value.validateReplacement(of: pending)
                        } else { throw StoreMigrationFailure.invalidPhaseTransition }
                    } else {
                        guard pending.phase == .recoveringSource, pending.revision == 0 else {
                            throw StoreMigrationFailure.invalidPhaseTransition
                        }
                    }
                    guard !(value ?? pending).reservationIsActive else { throw Self.uncertainOwnerFailure() }
                } else if value?.reservationIsActive == true { throw Self.uncertainOwnerFailure() }
                retain("migration/" + StoreAggregateMigrationControlV1.name, canonical)
                retain("migration/" + StoreAggregateMigrationControlV1.temporaryName, temporary)
                for (name, sampled) in [(StoreAggregateMigrationControlV1.name, canonical),
                    (StoreAggregateMigrationControlV1.temporaryName, temporary)] {
                    var current = stat()
                    let result = Darwin.fstatat(directory, name, &current, AT_SYMLINK_NOFOLLOW)
                    let observedErrno = errno
                    if let sampled {
                        guard result == 0, Self.originalEraseRetainedFullFact(current) == sampled.fact else {
                            throw Self.identityFailure()
                        }
                    } else {
                        guard result < 0, observedErrno == ENOENT else {
                            throw Self.identityFailure(errorNumber: observedErrno)
                        }
                    }
                }
                guard try directoryFact(directory) == before,
                      Darwin.fstatat(operationsDescriptor, "schema-migration", &migration,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(migration) == before else { throw Self.identityFailure() }
                facts["migration-root"] = before
            }
        }
        guard try coldSchema2RetirementIO.boundedNames(in: leaseDescriptor, maximumCount: 6) == leaseNames,
              try coldSchema2RetirementIO.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount) == ownerNames,
              try directoryFact(leaseDescriptor) == facts["lease-root"],
              try directoryFact(ownersDescriptor) == facts["owner-root"] else { throw Self.identityFailure() }
        // Recheck every cached member after the complete last hash/read;
        // later sibling reads cannot make an earlier sampled fact timeless.
        for (key, expected) in facts {
            if key == "lease-root" || key == "owner-root" { continue }
            let parts = key.split(separator: "/", maxSplits: 1).map(String.init)
            var current = stat()
            if key == "migration-root" {
                guard Darwin.fstatat(operationsDescriptor, "schema-migration", &current,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(current) == expected else { throw Self.identityFailure() }
            } else if parts.count == 2, parts[0] == "lease" || parts[0] == "owners" {
                let parent = parts[0] == "lease" ? leaseDescriptor : ownersDescriptor
                guard Darwin.fstatat(parent, parts[1], &current, AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(current) == expected else { throw Self.identityFailure() }
            }
        }
        if facts["migration-root"] == nil {
            guard Darwin.fstatat(operationsDescriptor, "schema-migration", &migration,
                    AT_SYMLINK_NOFOLLOW) < 0, errno == ENOENT else { throw Self.identityFailure() }
        }
        try coldSchema2RetirementIO.requireSettled()
        try requireOrigin()
        return ColdSchema2RetirementCensusV1(tokens: tokens, leaseNames: leaseNames,
            ownerNames: ownerNames, facts: facts, bytes: bytes, policies: policies)
    }

    @MainActor
    func observeColdSchema2RetirementRegistry(
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> [GenerationLeaseTokenV1] {
        try withColdSchema2RetirementG(operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness) {
            let before = try observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            let after = try observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            guard after == before else { throw Self.uncertainOwnerFailure() }
            return before.tokens
        }
    }
}


/// Real checked close of the separately held cold target Source. The private
/// producer retains it only after its single kernel close actually succeeds.
/// No decoded file, integer FD or absence observation can construct it.
@MainActor
final class ColdEraseSchema2TerminalTargetSourceCloseReceiptV1 {
    private weak var source: EraseSchema2ColdTargetSourceV1?
    private weak var owner: ColdEraseSchema2TerminalOwnerV1?
    private weak var observation: ColdEraseSchema2TerminalTargetObservationV1?
    private let fact: stat

    fileprivate init(source: EraseSchema2ColdTargetSourceV1,
        owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1, fact: stat) {
        self.source = source; self.owner = owner
        self.observation = observation; self.fact = fact
    }

    fileprivate func requireBound(source expectedSource: EraseSchema2ColdTargetSourceV1,
        owner expectedOwner: ColdEraseSchema2TerminalOwnerV1,
        observation expectedObservation: ColdEraseSchema2TerminalTargetObservationV1) throws {
        guard source === expectedSource, owner === expectedOwner,
              observation === expectedObservation else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedSource.requireColdTerminalSourceCloseReceipt(self)
    }

    fileprivate func requireCurrentRoot(_ root: Int32) throws {
        var current = stat()
        guard Darwin.fstat(root, &current) == 0,
              EraseSchema2ColdTargetSourceV1.sameColdTerminalFullFact(fact, current) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

extension EraseSchema2ColdTargetSourceV1 {
    fileprivate static func sameColdTerminalFullFact(_ a: stat, _ b: stat) -> Bool {
        sameColdModelFullFact(a, b)
    }

    /// The genuine Manifest supplies its already held target root. The two
    /// actual descriptors must describe the same full target-root postimage.
    fileprivate func requireColdTerminalHeldRoot(_ root: Int32) throws -> stat {
        try requirePhysicalIdentity()
        var held = stat(), manifestHeld = stat()
        guard descriptor >= 0, !closeAttempted, !uncertain,
              Darwin.fstat(descriptor, &held) == 0,
              Darwin.fstat(root, &manifestHeld) == 0,
              Self.sameColdTerminalFullFact(held, manifestHeld) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try preparedTargetIO.requireSettled()
        return held
    }

    fileprivate func requireColdTerminalSourceCloseReceipt(
        _ receipt: ColdEraseSchema2TerminalTargetSourceCloseReceiptV1) throws {
        guard coldTerminalSourceCloseReceipt === receipt, isCheckedClosed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try preparedTargetIO.requireSettled()
    }

    fileprivate func requireColdTerminalSourceClosedAssociation(
        owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1) throws {
        guard let receipt = coldTerminalSourceCloseReceipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try receipt.requireBound(source: self, owner: owner, observation: observation)
    }

    fileprivate func requireColdTerminalCheckedClose(
        owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        root: Int32) throws {
        try requireColdTerminalSourceClosedAssociation(owner: owner, observation: observation)
        guard let receipt = coldTerminalSourceCloseReceipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try receipt.requireCurrentRoot(root)
    }

    /// Registered terminal observation and immutable target ZERO precede this
    /// single close. Failure permanently fences the real Source and operation;
    /// neither ordinary close nor a new descriptor can settle its ownership.
    func closeColdTerminalChecked(owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        operation expectedOperation: EraseColdPreparationOperationV1,
        proof: ColdEraseSchema2TargetSemanticProofV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        guard operation === expectedOperation, let manifestOwner,
              !closeAttempted, !uncertain, coldTerminalSourceCloseReceipt == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try owner.requireTargetObservationFrame(manifest: manifestOwner,
                source: self, proof: proof, binding: binding, witness: witness)
            try observation.requireBound(owner: owner, operation: expectedOperation,
                manifest: manifestOwner, source: self, proof: proof,
                binding: binding, witness: witness)
            try observation.requireCurrent(owner: owner, witness: witness, binding: binding)
            let before = try manifestOwner.requireColdTerminalTargetRoot(owner: owner,
                observation: observation) { root in
                try self.requireColdTerminalHeldRoot(root)
            }
            try preparedTargetIO.requireSettled()
            closeAttempted = true // monotonic before the sole real close
            let owned = descriptor
            descriptor = -1
            guard Darwin.close(owned) == 0 else {
                uncertain = true
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let receipt = ColdEraseSchema2TerminalTargetSourceCloseReceiptV1(
                source: self, owner: owner, observation: observation, fact: before)
            coldTerminalSourceCloseReceipt = receipt
            try receipt.requireBound(source: self, owner: owner, observation: observation)
            try observation.requireCurrent(owner: owner, witness: witness, binding: binding)
            try owner.recordCheckedTargetSourceClose(observation)
            // Source dependency is replaced only after real close and fresh
            // unchanged held Manifest reproof have both completed.
            try proof.registerColdTerminalTargetObservation(observation: observation, owner: owner)
        } catch {
            uncertain = true
            expectedOperation.poisonColdScratchOwner()
            throw error
        }
    }
}

/// Only the same retained Manifest makes this actual target observation. Its
/// immutable Factory tree is kept through terminal Source/control close and
/// continuous EX. It cannot authorize a constructor, lease or namespace effect.
@MainActor
final class ColdEraseSchema2TerminalTargetObservationV1 {
    private weak var owner: ColdEraseSchema2TerminalOwnerV1?
    private weak var operation: EraseColdPreparationOperationV1?
    private weak var manifest: EraseSchema2ColdManifestOwnerV1?
    private weak var source: EraseSchema2ColdTargetSourceV1?
    private weak var proof: ColdEraseSchema2TargetSemanticProofV1?
    private weak var witness: EraseSessionDrainWitnessV1?
    let binding: EraseRetirementBindingV1
    private let physical: ColdEraseSchema2TerminalTargetPhysicalWitnessV1

    fileprivate init(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1,
        manifest: EraseSchema2ColdManifestOwnerV1,
        source: EraseSchema2ColdTargetSourceV1,
        proof: ColdEraseSchema2TargetSemanticProofV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        physical: ColdEraseSchema2TerminalTargetPhysicalWitnessV1) {
        self.owner = owner; self.operation = operation; self.manifest = manifest
        self.source = source; self.proof = proof; self.binding = binding
        self.witness = witness; self.physical = physical
    }

    func requireBound(owner expectedOwner: ColdEraseSchema2TerminalOwnerV1,
        operation expectedOperation: EraseColdPreparationOperationV1,
        manifest expectedManifest: EraseSchema2ColdManifestOwnerV1,
        source expectedSource: EraseSchema2ColdTargetSourceV1,
        proof expectedProof: ColdEraseSchema2TargetSemanticProofV1,
        binding expectedBinding: EraseRetirementBindingV1,
        witness expectedWitness: EraseSessionDrainWitnessV1) throws {
        guard owner === expectedOwner, operation === expectedOperation,
              manifest === expectedManifest, source === expectedSource,
              proof === expectedProof, binding == expectedBinding,
              witness === expectedWitness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedManifest.requireColdTerminalTargetObservationAssociation(self)
        try physical.requireBound(proof: expectedProof, binding: binding, witness: expectedWitness)
        try expectedOwner.requireTargetObservationFrame(manifest: expectedManifest,
            source: expectedSource, proof: expectedProof, binding: binding, witness: expectedWitness)
    }

    fileprivate func requireOwnerCurrent(_ expectedOwner: ColdEraseSchema2TerminalOwnerV1) throws {
        guard owner === expectedOwner, let manifest, let source, let proof, let witness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedOwner.requireTargetObservationFrame(manifest: manifest, source: source,
            proof: proof, binding: binding, witness: witness)
    }

    func requireSemanticProof(_ expectedProof: ColdEraseSchema2TargetSemanticProofV1,
        binding expectedBinding: EraseRetirementBindingV1,
        witness expectedWitness: EraseSessionDrainWitnessV1) throws {
        guard proof === expectedProof, binding == expectedBinding, witness === expectedWitness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try physical.requireBound(proof: expectedProof, binding: expectedBinding, witness: expectedWitness)
    }

    /// Pure real checked-close association remains usable after EX release.
    /// It performs no target/root IO and lends no current physical authority;
    /// requireCurrent independently proves the held immutable tree before EX.
    func requireCheckedSourceClosed(owner expectedOwner: ColdEraseSchema2TerminalOwnerV1) throws {
        guard owner === expectedOwner, operation != nil, let manifest, let source,
              let proof, let witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try manifest.requireColdTerminalTargetObservationAssociation(self)
        try physical.requireBound(proof: proof, binding: binding, witness: witness)
        try source.requireColdTerminalSourceClosedAssociation(owner: expectedOwner, observation: self)
    }

    func requireCurrent(owner expectedOwner: ColdEraseSchema2TerminalOwnerV1,
        witness expectedWitness: EraseSessionDrainWitnessV1,
        binding expectedBinding: EraseRetirementBindingV1) throws {
        guard owner === expectedOwner, witness === expectedWitness, binding == expectedBinding,
              let operation, let manifest, let source, let proof else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireBound(owner: expectedOwner, operation: operation, manifest: manifest,
            source: source, proof: proof, binding: binding, witness: expectedWitness)
        try manifest.requireColdTerminalTargetRoot(owner: expectedOwner, observation: self) { root in
            if source.isCheckedClosed {
                try source.requireColdTerminalCheckedClose(owner: expectedOwner, observation: self, root: root)
            } else {
                _ = try source.requireColdTerminalHeldRoot(root)
            }
            try physical.requireCurrent(root: root, io: manifest.coldTerminalTargetSnapshotIO)
        }
        try requireBound(owner: expectedOwner, operation: operation, manifest: manifest,
            source: source, proof: proof, binding: binding, witness: expectedWitness)
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    fileprivate var coldTerminalTargetSnapshotIO: EraseAbortCheckedSnapshotIOV1 { coldTerminalTargetIO }

    fileprivate func requireColdTerminalTargetObservationAssociation(
        _ observation: ColdEraseSchema2TerminalTargetObservationV1) throws {
        guard coldTerminalTargetObservation === observation, opened, !closeAttempted,
              uncertainFDs.isEmpty, enumerationFD == nil, directoryStream == nil,
              !uncertainStreamClose, targetLiveOpenState == .settled else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try coldTerminalTargetIO.requireSettled()
    }

    /// No Operations/Store/G reentry here. The true owner proves continuous EX;
    /// Manifest independently reproves its still-held target/pointer controls.
    fileprivate func requireColdTerminalTargetRoot<Value>(
        owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        _ body: (Int32) throws -> Value) throws -> Value {
        try requireColdTerminalTargetObservationAssociation(observation)
        guard let projection = postGenerationProjection,
              let data, let generations, let currentPointer, let retiredPointer,
              let targetManifest, let targetBytes = capturedTargetManifestBytes,
              let targetControlRoot, let targetSource,
              targetSource.generationID == projection.intent.newGenerationID else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        func requireControls() throws {
            try requireColdTerminalTargetObservationAssociation(observation)
            try observation.requireOwnerCurrent(owner)
            for node in [data, generations, currentPointer, retiredPointer, targetManifest, targetControlRoot] {
                try requireNamed(node)
            }
            guard try namesChecked(in: generations) == projection.generationNames,
                  projection.generationNames == [targetSource.generationID.uuidString.lowercased()],
                  try readExact(currentPointer, kind: .generationPointer) == projection.pointerBytes,
                  try readExact(retiredPointer, kind: .generationPointer) == projection.retiredBytes,
                  try readExact(targetManifest, kind: .journal,
                    maximumBytes: 32 * 1_024 * 1_024) == targetBytes else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        try requireControls()
        let outcome = Result<Value, Error> { try body(targetControlRoot.descriptor) }
        try coldTerminalTargetIO.requireSettled()
        try requireControls()
        return try outcome.get()
    }

    func makeColdTerminalTargetObservation(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1,
        source: EraseSchema2ColdTargetSourceV1,
        proof: ColdEraseSchema2TargetSemanticProofV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2TerminalTargetObservationV1 {
        try owner.requireTargetObservationFrame(manifest: self, source: source,
            proof: proof, binding: binding, witness: witness)
        guard targetSource === source, !source.isCheckedClosed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if let actual = coldTerminalTargetObservation {
            try actual.requireBound(owner: owner, operation: operation, manifest: self,
                source: source, proof: proof, binding: binding, witness: witness)
            try actual.requireCurrent(owner: owner, witness: witness, binding: binding)
            return actual
        }
        let physical = try proof.makeColdTerminalTargetPhysicalWitness(binding: binding, witness: witness)
        let actual = ColdEraseSchema2TerminalTargetObservationV1(owner: owner,
            operation: operation, manifest: self, source: source, proof: proof,
            binding: binding, witness: witness, physical: physical)
        coldTerminalTargetObservation = actual // retain before any source close
        do {
            try actual.requireBound(owner: owner, operation: operation, manifest: self,
                source: source, proof: proof, binding: binding, witness: witness)
            try actual.requireCurrent(owner: owner, witness: witness, binding: binding)
            try owner.retainTargetObservation(actual)
            return actual
        } catch { operation.poisonColdScratchOwner(); throw error }
    }
}


