        let record = try EraseSchema2ColdReaderPublicationRecordV1.decodeCanonical(recordBytes)
        guard record.eraseID == binding.subject.eraseID,
              record.targetGenerationID == binding.subject.newGenerationID,
              record.targetManifestSHA256 == binding.generationEpoch.generationManifestSHA256,
              record.priorRegistrySHA256 == StoreMigrationCanonicalJSONV1.sha256(oldBytes),
              try record.token(epoch: binding.generationEpoch) == reader.token,
              try RegistryStateV1.decodeCanonical(from: publishedBytes).leases == [reader.token] else {
            throw Self.uncertainOwnerFailure()
        }
        let prepared = try withColdSchema2RetirementG(operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness) {
            let before = try observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            let after = try observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            var heldRecord = stat()
            guard before == after, before.tokens == [reader.token],
                  before.bytes["lease/" + Self.registryName] == publishedBytes,
                  before.bytes["lease/" + Self.schema2ColdReaderRecordName] == recordBytes,
                  Darwin.fstat(allocation.schema2ColdRecordDescriptor, &heldRecord) == 0,
                  before.facts["lease/" + Self.schema2ColdReaderRecordName]
