                throw Self.uncertainOwnerFailure()
            }
            if let retained = coldSchema2ReaderRetirementPreparation {
                try retained.requireBound(registry: self, allocation: allocation, reader: reader,
                    operation: operation, activity: activity, exclusion: exclusion,
                    binding: binding, witness: witness)
                guard retained.census == before else { throw Self.uncertainOwnerFailure() }
                return retained
            }
            let replacement = try RegistryStateV1(leases: []).canonicalData()
            let prepared = try ColdEraseSchema2ReaderRetirementPreparationV1(registry: self,
                operation: operation, activity: activity, exclusion: exclusion,
                binding: binding, witness: witness, allocation: allocation, reader: reader,
                census: before, replacement: replacement, registryName: Self.registryName,
                temporaryName: Self.registryTemporaryName, recordName: Self.schema2ColdReaderRecordName)
            coldSchema2ReaderRetirementPreparation = prepared // retained before checked G release
            return prepared
        }
        try prepared.requireBound(registry: self, allocation: allocation, reader: reader,
            operation: operation, activity: activity, exclusion: exclusion,
            binding: binding, witness: witness)
