/// A private result of this same Manifest's complete single checked FD close,
/// issued only after actual cold EX release. It conveys no source authority.
@MainActor
final class ColdEraseSchema2TerminalManifestCloseReceiptV1 {
    private weak var owner: ColdEraseSchema2TerminalOwnerV1?
    private weak var manifest: EraseSchema2ColdManifestOwnerV1?
    private weak var observation: ColdEraseSchema2TerminalTargetObservationV1?
    fileprivate init(owner: ColdEraseSchema2TerminalOwnerV1,
        manifest: EraseSchema2ColdManifestOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1) {
        self.owner = owner; self.manifest = manifest; self.observation = observation
    }
    func requireBound(owner expectedOwner: ColdEraseSchema2TerminalOwnerV1,
        manifest expectedManifest: EraseSchema2ColdManifestOwnerV1,
        observation expectedObservation: ColdEraseSchema2TerminalTargetObservationV1) throws {
        guard owner === expectedOwner, manifest === expectedManifest,
              observation === expectedObservation else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedManifest.requireColdTerminalManifestCloseReceipt(self,
            observation: expectedObservation)
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    fileprivate func requireColdTerminalManifestCloseReceipt(
        _ receipt: ColdEraseSchema2TerminalManifestCloseReceiptV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1) throws {
        guard coldTerminalManifestCloseReceipt === receipt,
              coldTerminalTargetObservation === observation,
              closeAttempted, held.isEmpty, uncertainFDs.isEmpty,
              !uncertainStreamClose, enumerationFD == nil, directoryStream == nil,
              auxiliaryCachesParent == nil, auxiliaryTemporaryParent == nil,
              targetSource?.isCheckedClosed == true,
              originalSource == nil || originalSource?.isCheckedClosed == true,
              retiredSources?.values.allSatisfy({ $0.isCheckedClosed }) ?? true else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try coldTerminalTargetIO.requireSettled()
        try coldScratchProjectionIO.requireSettled()
    }

    /// The original close path stays unchanged. This distinct consumer joins
    /// genuine post-EX owner association, then closes each retained FD once;
    /// it never reads/reopens a released namespace or retries a failed integer.
    func closeColdTerminalChecked(owner: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        releaseProof: ColdEraseSchema2TerminalReleaseProofV1)
        throws -> ColdEraseSchema2TerminalManifestCloseReceiptV1 {
        try releaseProof.requireAfterExRelease(manifest: self, owner: owner)
        try owner.requireAfterExReleaseManifestClose(manifest: self, observation: observation)
        guard opened, !closeAttempted, coldTerminalManifestCloseReceipt == nil,
              coldTerminalTargetObservation === observation,
              uncertainFDs.isEmpty, !uncertainStreamClose,
              !retainedSourcePhaseProjectionInFlight,
              !deletionRosterPublicationInFlight, !deletionRosterReplayInFlight,
              !deletionStepInFlight, !postGenerationCaptureInFlight,
              !originalAuxiliaryReplayInFlight, !auxiliaryCaptureInFlight,
              !auxiliaryRosterRereadInFlight,
              !(auxiliaryRosterSealAttempted && auxiliaryRosterSeal == nil),
              !schema2ColdNotificationCaptureInFlight, !schema2ColdNotificationMutationInFlight,
              targetSource?.isCheckedClosed == true,
              originalSource == nil || originalSource?.isCheckedClosed == true,
              retiredSources?.values.allSatisfy({ $0.isCheckedClosed }) ?? true,
              Set(held.map({ $0.descriptor })).count == held.count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try coldTerminalTargetIO.requireSettled()
        try coldScratchProjectionIO.requireSettled()
        closeAttempted = true // permanent before any kernel close
        if let directoryStream {
            self.directoryStream = nil
            if Darwin.closedir(directoryStream) != 0 { uncertainStreamClose = true }
        }
        if let enumerationFD {
            self.enumerationFD = nil
            if Darwin.close(enumerationFD) != 0 { uncertainFDs.append(enumerationFD) }
        }
        if let temporary = auxiliaryTemporaryParent {
            auxiliaryTemporaryParent = nil
            if Darwin.close(temporary.descriptor) != 0 { uncertainFDs.append(temporary.descriptor) }
        }
        if let caches = auxiliaryCachesParent {
            auxiliaryCachesParent = nil
            if Darwin.close(caches.descriptor) != 0 { uncertainFDs.append(caches.descriptor) }
        }
        for node in held.reversed() {
            if Darwin.close(node.descriptor) != 0 { uncertainFDs.append(node.descriptor) }
        }
        held.removeAll()
        guard uncertainFDs.isEmpty, !uncertainStreamClose else {
            owner.poisonOnUncertainEffect()
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let receipt = ColdEraseSchema2TerminalManifestCloseReceiptV1(owner: owner,
            manifest: self, observation: observation)
        coldTerminalManifestCloseReceipt = receipt
        do {
            try receipt.requireBound(owner: owner, manifest: self, observation: observation)
            try owner.recordCheckedManifestClose(receipt)
            return receipt
        } catch { owner.poisonOnUncertainEffect(); throw error }
    }
}


/// Closed two-role post-content kernel vocabulary, distinct from Scratch15.
/// Namespace storage DATA has fixed scalar layout. It grants no observed
/// prefix, resource ownership or removal authority. Variable names live once
/// in a separately charged UTF-8 arena; complete paths use a bounded window.
struct ColdEraseSchema2NamespaceNodeStorageV1 {
    var device: Int64
    var inode: UInt64
    var mode: UInt32
    var ownerUID: UInt32
    var ownerGID: UInt32
    var linkCount: UInt64
    var byteCount: Int64
    var modificationSeconds: Int64
    var modificationNanoseconds: Int64
    var changeSeconds: Int64
    var changeNanoseconds: Int64
    var digestWord0: UInt64
    var digestWord1: UInt64
    var digestWord2: UInt64
    var digestWord3: UInt64
    var policyCode: UInt64
    var settledSequence: UInt64
    var parentOrdinal: UInt32
    var physicalOrdinal: UInt32
    var memberOffset: UInt32
    var firstChildOffset: UInt32
    var childCount: UInt32
    var memberByteCount: UInt16
    var lineageDomain: UInt8
    var physicalKind: UInt8
    var projectionState: UInt8
}

/// A retained descriptor/stream slot exists before its first syscall. Result
/// fields record actual returns; state bytes cannot create a positive receipt.
struct ColdEraseSchema2NamespaceResourceStorageV1 {
    var descriptor: Int32
    var stream: OpaquePointer?
    var nodeOrdinal: UInt32
    var depth: UInt16
    var role: UInt8
    var state: UInt8
    var openReturned: Int64
    var openErrno: Int32
    var readReturned: Int64
    var readErrno: Int32
    var unlockReturned: Int32
    var unlockErrno: Int32
    var closeReturned: Int32
    var closeErrno: Int32
}

/// Scalar parser for the authenticated original full9 DATA. Ownership and
/// policy fields are deliberately not inferred from this older vocabulary.
private struct ColdEraseSchema2NamespaceFirstNineParserV1 {
    private var field = 0
    private var magnitude: UInt64 = 0
    private var digits = 0
    private var negative = false
    private var leadingZero = false

    mutating func parse(_ text: String, ordinal: UInt64, parent: UInt32,
        kind: String) throws -> ColdEraseSchema2NamespaceNodeStorageV1 {
        guard field == 0, ordinal <= UInt64(UInt32.max), text.utf8.count <= 197,
              kind == "file" || kind == "directory" else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var node = ColdEraseSchema2NamespaceNodeStorageV1(device: 0, inode: 0, mode: 0,
            ownerUID: 0, ownerGID: 0, linkCount: 0, byteCount: 0,
            modificationSeconds: 0, modificationNanoseconds: 0, changeSeconds: 0,
            changeNanoseconds: 0, digestWord0: 0, digestWord1: 0, digestWord2: 0,
            digestWord3: 0, policyCode: 0, settledSequence: 0, parentOrdinal: parent,
            physicalOrdinal: UInt32(ordinal), memberOffset: 0, firstChildOffset: 0,
            childCount: 0, memberByteCount: 0, lineageDomain: 1,
            physicalKind: kind == "directory" ? 1 : 2, projectionState: 0)
        for byte in text.utf8 {
            if byte == 124 { try finish(into: &node); continue }
            if byte == 45 && digits == 0 && !negative { negative = true; continue }
            guard byte >= 48, byte <= 57, digits < 20,
                  !(digits > 0 && leadingZero) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            if digits == 0 { leadingZero = byte == 48 }
            let multiplied = magnitude.multipliedReportingOverflow(by: 10)
            let added = multiplied.partialValue.addingReportingOverflow(UInt64(byte - 48))
            guard !multiplied.overflow, !added.overflow else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            magnitude = added.partialValue; digits += 1
        }
        try finish(into: &node)
        guard field == 9, node.inode > 0, node.mode > 0, node.linkCount > 0,
              (kind == "directory" && node.mode & UInt32(S_IFMT) == UInt32(S_IFDIR))
                || (kind == "file" && node.mode & UInt32(S_IFMT) == UInt32(S_IFREG)
                    && node.linkCount == 1) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return node
    }

    private mutating func finish(into node: inout ColdEraseSchema2NamespaceNodeStorageV1) throws {
        guard field < 9, digits > 0, !(negative && magnitude == 0),
              !negative || field == 5 || field == 7 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let signed: Int64
        if negative {
            guard magnitude <= UInt64(Int64.max) + 1 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            signed = magnitude == UInt64(Int64.max) + 1 ? Int64.min : -Int64(magnitude)
        } else {
            // Inode and link fields retain UInt64; all other admitted fields
            // are represented by the exact signed/UInt32 scalar below.
            if field == 1 || field == 3 { signed = 0 }
            else {
                guard magnitude <= UInt64(Int64.max) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                signed = Int64(magnitude)
            }
        }
        switch field {
        case 0: node.device = signed
        case 1: node.inode = magnitude
        case 2:
            guard magnitude <= UInt64(UInt32.max) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            node.mode = UInt32(magnitude)
        case 3: node.linkCount = magnitude
        case 4: node.byteCount = signed
        case 5: node.modificationSeconds = signed
        case 6:
            guard magnitude < 1_000_000_000 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            node.modificationNanoseconds = signed
        case 7: node.changeSeconds = signed
        case 8:
            guard magnitude < 1_000_000_000 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            node.changeNanoseconds = signed
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        field += 1; magnitude = 0; digits = 0; negative = false; leadingZero = false
    }
}

