/// Borrowed Registry descriptors remain owned by the real Registry. This
/// entered owner retains every actual fstat/fstatat/pread result before a
/// callback. It does not open, duplicate, close or retry borrowed resources.
@MainActor
fileprivate final class ColdEraseSchema2NamespaceMutationLockReadResourceV1 {
    fileprivate enum Primitive { case parentHeld, parentNamed, leafHeld, leafNamed, emptyEOF }
    fileprivate struct Storage {
        let context: ColdEraseSchema2NamespaceOperationsRootReadContextV1
        let origin: ColdEraseSchema2NamespaceMutationLockOriginV1
        var primitive: Primitive?
        var consumed = true
        var returned: Int64?
        var savedErrno: Int32?
        var information = stat()
        var fullFact: String?
        var byte: UInt8 = 0
        var enteredCount: UInt64 = 0
        var completedObservations: UInt64 = 0
        var lastObservedContextState: ColdEraseSchema2NamespaceOperationsRootReadContextV1.State?
        var lastEOFReturned: Int64?
        var lastEOFErrno: Int32?
        var uncertain = false
    }
    fileprivate var storage: Storage
    fileprivate init(context: ColdEraseSchema2NamespaceOperationsRootReadContextV1,
        origin: ColdEraseSchema2NamespaceMutationLockOriginV1) {
        storage = Storage(context: context, origin: origin)
    }
    private func frame(heldG: Bool) throws {
        guard !storage.uncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.context.requireMutationLockReadResource(self, heldG: heldG)
        try storage.origin.requireAssociation()
    }
    private func enter(_ primitive: Primitive, heldG: Bool) throws {
        try frame(heldG: heldG)
        guard storage.consumed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let count = storage.enteredCount.addingReportingOverflow(1)
        guard !count.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.enteredCount = count.partialValue; storage.primitive = primitive
        storage.consumed = false; storage.returned = nil; storage.savedErrno = nil
        storage.fullFact = nil
    }
    private func retainStat(_ result: Int32, _ saved: Int32, _ information: stat) {
        storage.returned = Int64(result); storage.savedErrno = saved
        storage.information = information
        storage.fullFact = GenerationLeaseRegistryV1.coldSchema2TerminalFullFact(information)
    }
    private func consume() throws {
        guard !storage.consumed, storage.returned != nil, storage.savedErrno != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.consumed = true
    }
    fileprivate func requireCurrent(heldG: Bool) throws {
        do {
            let stateBefore = storage.context.storage.state
            try enter(.parentHeld, heldG: heldG)
            var information = stat()
            let ph = Darwin.fstat(storage.origin.storage.parentDescriptor, &information), phe = errno
            retainStat(ph, phe, information); try frame(heldG: heldG)
            guard ph == 0, information.st_mode & S_IFMT == S_IFDIR,
                  storage.fullFact == storage.origin.storage.parentFullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.parentNamed, heldG: heldG)
            let pn = Darwin.fstatat(storage.context.storage.operationsDescriptor,
                "generation-leases", &information, AT_SYMLINK_NOFOLLOW), pne = errno
            retainStat(pn, pne, information); try frame(heldG: heldG)
            guard pn == 0, storage.fullFact == storage.origin.storage.parentFullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.leafHeld, heldG: heldG)
            let lh = Darwin.fstat(storage.origin.storage.descriptor, &information), lhe = errno
            retainStat(lh, lhe, information); try frame(heldG: heldG)
            guard lh == 0, information.st_mode & S_IFMT == S_IFREG,
                  information.st_mode & 0o777 == 0o600, information.st_nlink == 1,
                  information.st_size == 0, storage.fullFact == storage.origin.storage.fullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.leafNamed, heldG: heldG)
            let ln = Darwin.fstatat(storage.origin.storage.parentDescriptor,
                "mutation.lock", &information, AT_SYMLINK_NOFOLLOW), lne = errno
            retainStat(ln, lne, information); try frame(heldG: heldG)
            guard ln == 0, storage.fullFact == storage.origin.storage.fullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.emptyEOF, heldG: heldG)
            let er = Darwin.pread(storage.origin.storage.descriptor, &storage.byte, 1, 0), ee = errno
            storage.returned = Int64(er); storage.savedErrno = ee // before callbacks/refusal
            storage.lastEOFReturned = Int64(er); storage.lastEOFErrno = ee
            try frame(heldG: heldG)
            guard er == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try consume()
            // Content EOF is bracketed by fresh exact original-cache held
            // and named facts; same-byte metadata mutation cannot escape.
            try enter(.parentHeld, heldG: heldG)
            let aph = Darwin.fstat(storage.origin.storage.parentDescriptor, &information), aphe = errno
            retainStat(aph, aphe, information); try frame(heldG: heldG)
            guard aph == 0, storage.fullFact == storage.origin.storage.parentFullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.parentNamed, heldG: heldG)
            let apn = Darwin.fstatat(storage.context.storage.operationsDescriptor,
                "generation-leases", &information, AT_SYMLINK_NOFOLLOW), apne = errno
            retainStat(apn, apne, information); try frame(heldG: heldG)
            guard apn == 0, storage.fullFact == storage.origin.storage.parentFullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.leafHeld, heldG: heldG)
            let alh = Darwin.fstat(storage.origin.storage.descriptor, &information), alhe = errno
            retainStat(alh, alhe, information); try frame(heldG: heldG)
            guard alh == 0, storage.fullFact == storage.origin.storage.fullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume(); try enter(.leafNamed, heldG: heldG)
            let aln = Darwin.fstatat(storage.origin.storage.parentDescriptor,
                "mutation.lock", &information, AT_SYMLINK_NOFOLLOW), alne = errno
            retainStat(aln, alne, information); try frame(heldG: heldG)
            guard aln == 0, storage.fullFact == storage.origin.storage.fullFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try consume()
            guard storage.context.storage.state == stateBefore else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let completed = storage.completedObservations.addingReportingOverflow(1)
            guard !completed.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.completedObservations = completed.partialValue
            storage.lastObservedContextState = stateBefore
        } catch {
            storage.uncertain = true; storage.context.poison(); throw error
        }
    }
    fileprivate func requirePositivePostUnlockObservation() throws {
        guard !storage.uncertain, storage.consumed, storage.completedObservations > 0,
              storage.lastObservedContextState == .checked,
              storage.primitive == .leafNamed, storage.returned == 0,
              storage.savedErrno != nil, storage.lastEOFReturned == 0,
              storage.lastEOFErrno != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
}

/// Immutable DATA supplied only by the actual Target-private Origin/Scope.
/// A full11 parser is PFP-owned DATA, never a lease or effect capability.
@MainActor
struct ColdEraseSchema2NamespaceMutationLockPolicyNodeV1 {
    let kind: OwnedFileKindV1
    let url: URL
    let fullFact: String
    let parentFullFact: String
