    let selectedName: String
    let isDirectory: Bool
    let absoluteURLUTF8Count: UInt64
    let fact: ColdEraseSchema2NamespaceMutationLockFullFactV1
    let parentFact: ColdEraseSchema2NamespaceMutationLockFullFactV1
    let expectedByteCount: UInt64
    let expectedContentSHA256: String
    let expectedPolicy: TemporalPolicyObservationV1
    func sameActualFields(as other: Self) -> Bool {
        kind == other.kind && url == other.url && fullFact == other.fullFact
            && parentFullFact == other.parentFullFact && parentDescriptor == other.parentDescriptor
            && selectedName == other.selectedName && isDirectory == other.isDirectory
            && absoluteURLUTF8Count == other.absoluteURLUTF8Count
            && expectedByteCount == other.expectedByteCount
            && expectedContentSHA256 == other.expectedContentSHA256
            && expectedPolicy == other.expectedPolicy
    }
}

/// Two fixed roles only. First observes before acquisition without requiring
/// HeldG; second observes under real owned G after both cursor closes. Both
/// stay strongly retained through the actual checked unlock/consumer.
@MainActor
final class ColdEraseSchema2NamespaceMutationLockPolicyScopeV1 {
    fileprivate enum Role: UInt8 { case beforeAcquisition, beforeRelease }
    fileprivate enum State { case retained, observed, consuming, consumed, uncertain }
    fileprivate struct Storage {
        let context: ColdEraseSchema2NamespaceOperationsRootReadContextV1
        let origin: ColdEraseSchema2NamespaceMutationLockOriginV1
        let role: Role
        let node: ColdEraseSchema2NamespaceMutationLockPolicyNodeV1
        var state: State = .retained
        var observation: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1?
        var uncertainDescriptor: Int32?
    }
    private var storage: Storage
    fileprivate init(context: ColdEraseSchema2NamespaceOperationsRootReadContextV1,
        origin: ColdEraseSchema2NamespaceMutationLockOriginV1, role: Role) throws {
        let current = origin.storage
        storage = Storage(context: context, origin: origin, role: role,
            node: ColdEraseSchema2NamespaceMutationLockPolicyNodeV1(kind: .generationLeaseControl,
                url: current.url, fullFact: current.fullFact, parentFullFact: current.parentFullFact,
                parentDescriptor: current.parentDescriptor, selectedName: "mutation.lock", isDirectory: false,
                absoluteURLUTF8Count: current.absoluteURLUTF8Count,
                fact: try ColdEraseSchema2NamespaceMutationLockFullFactV1(current.fullFact),
                parentFact: try ColdEraseSchema2NamespaceMutationLockFullFactV1(current.parentFullFact),
                expectedByteCount: 0, expectedContentSHA256: current.contentSHA256,
                expectedPolicy: current.policy))
    }
    var operationID: UUID { storage.context.storage.capture.operationsRootReadOperationID }
    fileprivate var role: Role { storage.role }
    fileprivate func requireAssociation(context: ColdEraseSchema2NamespaceOperationsRootReadContextV1) throws {
        guard storage.state != .uncertain, storage.context === context,
              storage.origin === context.storage.mutationLockOrigin else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireCurrentBinding() throws {
        guard storage.state == .retained || storage.state == .observed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.context.requireMutationLockPolicyScope(self, current: true)
        try storage.context.requireRootCurrent(heldG: storage.role == .beforeRelease)
    }
    func requireNode() throws -> ColdEraseSchema2NamespaceMutationLockPolicyNodeV1 {
        try requireCurrentBinding(); return storage.node
    }
    func requireNode(_ kind: OwnedFileKindV1, at url: URL, fullFact: String)
        throws -> ColdEraseSchema2NamespaceMutationLockPolicyNodeV1 {
        try requireCurrentBinding()
        guard kind == .generationLeaseControl, storage.node.kind == kind,
              storage.node.url == url, storage.node.fullFact == fullFact else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return storage.node
    }
    func requireMutationLockDescriptor() throws -> Int32 {
        try requireCurrentBinding(); return storage.origin.storage.descriptor
    }
    func requireObservationConstructionCapacity(additionalBytes: UInt64) throws {
        try requireCurrentBinding()
        guard storage.state == .retained, storage.observation == nil,
              additionalBytes == (try ColdEraseSchema2NamespaceMutationLockPolicyObservationV1
                .requiredBackingBytes(absoluteURLUTF8Count: storage.node.absoluteURLUTF8Count)),
              additionalBytes <= (try ColdEraseSchema2NamespaceMutationLockPolicyObservationV1
                .requiredBackingBytes(absoluteURLUTF8Count: 16_640)) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // Capture's genuine pre-constructor reservation includes two actual
        // Observation profiles at the fixed admitted URL bound. No scalar
        // additionalBytes grants ownership or IO.
    }
    func retainObservationAttempt(_ actual: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1) throws {
        guard storage.state == .retained, storage.observation == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.observation = actual // BEFORE fallible association/current proof
        do {
            try requireObservationCapacity(actual, additionalBytes: actual.actualBackingBytes)
            try requireCurrentBinding()
        } catch { poisonOnUncertainEffect(); throw error }
    }
    /// Pure identity checker also usable after checked G release. Per-IO
    /// current proof is separate; it cannot rearm a completed role.
    func requireObservationAttempt(_ actual: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1) throws {
        guard storage.state != .uncertain, storage.observation === actual else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.context.requireMutationLockPolicyScope(self, current: false)
    }
    func requireObservationCapacity(_ actual: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1,
        additionalBytes: UInt64) throws {
        try requireObservationAttempt(actual)
        guard additionalBytes == (try ColdEraseSchema2NamespaceMutationLockPolicyObservationV1
                .requiredBackingBytes(absoluteURLUTF8Count: storage.node.absoluteURLUTF8Count)),
              additionalBytes <= (try ColdEraseSchema2NamespaceMutationLockPolicyObservationV1
                .requiredBackingBytes(absoluteURLUTF8Count: 16_640)) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireCheckedObservation(_ actual: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1) throws {
        do {
            try requireCurrentBinding(); try requireObservationAttempt(actual)
            guard storage.state == .retained, actual.value == storage.origin.storage.policy,
                  storage.uncertainDescriptor == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try actual.requireCheckedSettlement()
            storage.state = .observed // DATA join only, never G ownership
        } catch { poisonOnUncertainEffect(); throw error }
    }
    func requireConsumedObservationAttempt(_ actual: ColdEraseSchema2NamespaceMutationLockPolicyObservationV1) throws {
        try requireObservationAttempt(actual)
        guard storage.state == .observed || storage.state == .consuming || storage.state == .consumed,
              storage.uncertainDescriptor == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.context.requireMutationLockPolicyCompletion(self)
    }
    fileprivate func requireObserved() throws {
        guard storage.state == .observed, let actual = storage.observation,
              actual.value == storage.origin.storage.policy, storage.uncertainDescriptor == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireObservationAttempt(actual); try actual.requireCheckedSettlement()
    }
    fileprivate func consumeAfterCheckedRootRead() throws {
        guard storage.state == .observed, let actual = storage.observation else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        do {
            try requireConsumedObservationAttempt(actual)
            try actual.requireCheckedSettlement()
            storage.state = .consuming // fence before the real release callback
            try actual.releaseConsumedScope(self)
            storage.state = .consumed
        } catch { poisonOnUncertainEffect(); throw error }
    }
    fileprivate func requireConsumed() throws {
        guard storage.state == .consumed, let actual = storage.observation else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireConsumedObservationAttempt(actual)
        try actual.requireCheckedSettlement()
    }
    func retainUncertainDescriptor(_ descriptor: Int32) {
        if storage.uncertainDescriptor == nil { storage.uncertainDescriptor = descriptor }
        poisonOnUncertainEffect()
    }
    func poisonOnUncertainEffect() {
        storage.state = .uncertain; storage.context.poison()
    }
}

extension ColdEraseSchema2ReaderRetirementReceiptV1 {
    fileprivate func makeNamespaceMutationLockOrigin(
        context: ColdEraseSchema2NamespaceOperationsRootReadContextV1,
        registry: GenerationLeaseRegistryV1, descriptor: Int32, parentDescriptor: Int32,
        url: URL) throws -> ColdEraseSchema2NamespaceMutationLockOriginV1 {
        try context.storage.capture.requireOperationsRootReadReceipt(self)
        try requireNamespaceMutationLockReceiptFrame(context)
        let key = "lease/mutation.lock"
        guard let leaf = attempt.currentFacts[key], let parent = attempt.currentFacts["lease-root"],
              let bytes = attempt.currentBytes[key], bytes.isEmpty,
              let policy = attempt.namespaceFinalFirstCensus?.policies[key],
              leaf.utf8.count <= 241, parent.utf8.count <= 241 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let absoluteCount = UInt64(url.absoluteString.utf8.count)
        guard url.isFileURL, absoluteCount > 0, absoluteCount <= 16_640 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var digest = String(); digest.reserveCapacity(64)
        func hex(_ value: UInt8) -> UInt8 { value < 10 ? value + 48 : value + 87 }
        for byte in SHA256.hash(data: bytes) {
            digest.append(Character(UnicodeScalar(hex(byte >> 4))))
            digest.append(Character(UnicodeScalar(hex(byte & 15))))
        }
        return ColdEraseSchema2NamespaceMutationLockOriginV1(receipt: self,
            context: context, registry: registry, descriptor: descriptor,
            parentDescriptor: parentDescriptor, parentFullFact: parent, fullFact: leaf,
            policy: policy, contentSHA256: digest, url: url, absoluteURLUTF8Count: absoluteCount)
    }
    private func requireNamespaceMutationLockReceiptFrame(
        _ context: ColdEraseSchema2NamespaceOperationsRootReadContextV1) throws {
        let actors = try context.storage.capture.operationsRootReadReceiptActors()
        let resources = try attempt.requireProjectionResources(operation: actors.operation,
            registry: actors.registry, activity: actors.activity, exclusion: actors.exclusion,
            binding: actors.binding, witness: actors.witness)
        try requireBound(operation: actors.operation, registry: actors.registry,
            activity: actors.activity, allocation: resources.allocation, reader: resources.reader,
            exclusion: actors.exclusion, binding: actors.binding, witness: actors.witness)
        guard let first = attempt.namespaceFinalFirstCensus,
              let second = attempt.namespaceFinalSecondCensus, first == second,
              first.tokens.isEmpty, first.facts == attempt.currentFacts,
              first.bytes == attempt.currentBytes,
              first.leaseNames == attempt.currentLeaseNames,
              first.ownerNames == attempt.ownerNames else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    fileprivate func requireNamespaceMutationLockOrigin(_ origin: ColdEraseSchema2NamespaceMutationLockOriginV1) throws {
        try requireNamespaceMutationLockReceiptFrame(origin.storage.context)
        guard origin.storage.receipt === self,
              attempt.currentFacts["lease-root"] == origin.storage.parentFullFact,
              attempt.currentFacts["lease/mutation.lock"] == origin.storage.fullFact,
              attempt.currentBytes["lease/mutation.lock"]?.isEmpty == true,
              attempt.namespaceFinalFirstCensus?.policies["lease/mutation.lock"] == origin.storage.policy else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

