extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func requireColdSchema2NamespaceOperationsRootRead(
        _ capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        context: ColdEraseSchema2NamespaceOperationsRootReadContextV1, heldG: Bool) throws {
        try requireColdSchema2NamespaceCapture(capture)
        guard isEraseSchema2ColdOwner, !isEraseC05ColdOwner,
              coldSchema2NamespaceCloseAttempt == nil, coldSchema2NamespaceCloseReceipt == nil,
              generationMutationLockDepth == (heldG ? 1 : 0),
              context.storage.supportDescriptor == rootDescriptor,
              context.storage.operationsDescriptor == operationsDescriptor,
              context.storage.supportURL == applicationSupportURL else { throw Self.uncertainOwnerFailure() }
    }
    @MainActor
    func compareColdSchema2NamespaceOperationsRoot(owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2NamespaceCaptureOwnerV1 {
        let capture = try makeColdSchema2NamespaceCapture(owner: owner, basis: basis,
            operation: operation, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        do {
            try capture.buildOriginalIndex() // original roots-only question retains its existing authentic index
            let context = try capture.makeOperationsRootReadContext(support: rootDescriptor,
                operations: operationsDescriptor, url: applicationSupportURL)
            Self.processMutationLock.lock()
            defer { Self.processMutationLock.unlock() }
            try capture.requireOperationsRootReadFrame(context, heldG: false)
            try context.makeMutationLockControl(registry: self, descriptor: mutationLockDescriptor,
                parentDescriptor: leaseDescriptor, url: leaseURL.appendingPathComponent(Self.mutationLockName))
            try context.observeMutationLockPolicy(.beforeAcquisition)
            try context.requireRootCurrent(heldG: false)
            try context.enter(.lockG); context.storage.state = .lockEntering
            let lr = flock(mutationLockDescriptor, LOCK_EX), le = errno
            context.storage.returned = lr; context.storage.savedErrno = le
            context.storage.lockReturned = lr; context.storage.lockErrno = le
            guard lr == 0 else { throw Self.uncertainOwnerFailure() }
            generationMutationLockDepth = 1
            try context.consume(); context.storage.state = .held
            try context.requireRootCurrent()
            let first = ColdEraseSchema2NamespaceOperationsRootReadAttemptV1(context: context, pass: 0)
            try context.retain(first, pass: 0) // BEFORE open/cursor/stat/readdir
            try first.scanAndClose()
            let second = ColdEraseSchema2NamespaceOperationsRootReadAttemptV1(context: context, pass: 1)
            try context.retain(second, pass: 1)
            try second.scanAndClose(); try context.requireBothChecked(); try context.requireRootCurrent()
            try context.observeMutationLockPolicy(.beforeRelease)
            try context.requireRootCurrent()
            try context.enter(.unlockG); context.storage.state = .unlockEntering // fences further read entry BEFORE sole unlock
            let ur = flock(mutationLockDescriptor, LOCK_UN), ue = errno
            context.storage.returned = ur; context.storage.savedErrno = ue
            context.storage.unlockReturned = ur; context.storage.unlockErrno = ue
            guard ur == 0 else { throw Self.identityFailure(errorNumber: ue) }
            generationMutationLockDepth = 0
            try context.consume(); context.storage.state = .checked
            try capture.requireOperationsRootReadFrame(context, heldG: false)
            try context.requireRootCurrent(heldG: false) // actual held/named G/parent/EOF after checked unlock
            try context.consumeMutationLockPolicies()
            try capture.requireCheckedOperationsRootRead()
            return capture // root comparison only, no Preparation/namespace effect receipt
        } catch {
            coldSchema2RetirementUncertain = true
            capture.poisonOnUncertainEffect(); owner.poisonOnUncertainEffect()
            // Entered uncertain resources/G remain owned and fenced. No
            // ordinary cleanup, numeric retry or replacement context occurs.
            throw error
        }
    }
}
