    /// Declared scalar/reference storage only. Allocator headers and whole VM
    /// remain unmeasured; this number is never an RSS admission or IO permit.
    static func requiredBackingBytes() throws -> UInt64 {
        let backings = UInt64(MemoryLayout<ColdEraseSchema2NamespaceMetadataBackingV1.Storage>.stride)
            .multipliedReportingOverflow(by: 6)
        let total = UInt64(MemoryLayout<Storage>.stride)
            .addingReportingOverflow(backings.partialValue)
        let scratch = UInt64(MemoryLayout<ColdEraseSchema2RegistryControlCloseAttemptV1.Storage>.stride
            + MemoryLayout<ColdEraseSchema2RegistryControlCloseReceiptV1.Storage>.stride
            + MemoryLayout<ColdEraseSchema2NamespaceRegistryResourcesV1>.stride
            + 2 * MemoryLayout<ColdEraseSchema2NamespaceNodeStorageV1>.stride
            + MemoryLayout<ColdEraseSchema2NamespaceFirstNineParserV1>.stride
            + 2 * MemoryLayout<String.UTF8View>.stride
            + 2 * MemoryLayout<String.UTF8View.SubSequence>.stride)
        let complete = total.partialValue.addingReportingOverflow(scratch)
        let rootRead = try operationsRootReadDeclaredBackingBytes()
        let withRootRead = complete.partialValue.addingReportingOverflow(rootRead)
        guard !backings.overflow, !total.overflow, !complete.overflow,
              !withRootRead.overflow else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
