    /// Deliberately memory-only. Native's full frame calls this checker and
    /// never recursively calls requireBound or re-enters an old loan/G scope.
    func requireReservationAssociation(reservation: ColdEraseSchema2NamespaceCaptureReservationV1,
        owner: ColdEraseSchema2TerminalOwnerV1, basis: ColdEraseSchema2NamespacePreparationBasisV1,
        registry: GenerationLeaseRegistryV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        guard storage.state != .uncertain, storage.reservation === reservation,
              storage.owner === owner, storage.basis === basis, storage.registry === registry,
              storage.operation === operation, storage.activity === activity,
              storage.exclusion === exclusion, storage.binding == binding,
              storage.witness === witness else {
