    fileprivate func allocateMetadata(kind: ColdEraseSchema2NamespaceMetadataKindV1,
        elementCount: UInt64) throws -> ColdEraseSchema2NamespaceMetadataBackingV1 {
        guard storage.state == .capturing, backing(kind) == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
