            elementCount: elementCount, capture: self) // before either object/buffer allocation
        let value = try ColdEraseSchema2NamespaceMetadataBackingV1(lease: lease,
            capture: self, kind: kind, capacity: elementCount)
        retain(value, kind: kind) // actual backing survives failed capacity/association checks
        do { try lease.recordAllocation(capture: self, backing: value) }
        catch { poisonOnUncertainEffect(); throw error }
        return value
    }

    private func backing(_ kind: ColdEraseSchema2NamespaceMetadataKindV1)
        -> ColdEraseSchema2NamespaceMetadataBackingV1? {
        switch kind {
        case .nodeTable: return storage.nodeTable
        case .memberUTF8: return storage.memberUTF8
        case .childOrdinals: return storage.childOrdinals
        case .pathUTF8: return storage.pathUTF8
        case .readWindow: return storage.readWindow
        case .descriptorSlots: return storage.descriptorSlots
        }
    }

    private func retain(_ value: ColdEraseSchema2NamespaceMetadataBackingV1,
        kind: ColdEraseSchema2NamespaceMetadataKindV1) {
        switch kind {
        case .nodeTable: storage.nodeTable = value
        case .memberUTF8: storage.memberUTF8 = value
        case .childOrdinals: storage.childOrdinals = value
        case .pathUTF8: storage.pathUTF8 = value
        case .readWindow: storage.readWindow = value
        case .descriptorSlots: storage.descriptorSlots = value
        }
    }

    /// Original comparison DATA only. Full9 never supplies a current UID/GID
    /// or policy observation. Those fields remain zero/unobserved until the
    /// real complete current-prefix scanner and second scan join them.
    fileprivate func buildOriginalIndex() throws {
        do {
            guard storage.state == .capturing, storage.originalNodeCount == nil,
                  !storage.originalIndexCompleted else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try storage.reservation.requireCaptureFrame(capture: self)
            let count = try storage.reservation.requireOriginalOperationsNodeCount(capture: self)
            guard count > 0, count < 100_000 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let capacity = count
            let namesCapacity = capacity.multipliedReportingOverflow(by: 255)
            guard !namesCapacity.overflow else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            storage.originalNodeCount = count // actual authenticated count, before allocation
            let nodes = try allocateMetadata(kind: .nodeTable, elementCount: capacity)
            let names = try allocateMetadata(kind: .memberUTF8, elementCount: namesCapacity.partialValue)
            let edges: ColdEraseSchema2NamespaceMetadataBackingV1?
            if count > 1 {
                edges = try allocateMetadata(kind: .childOrdinals, elementCount: count - 1)
            } else {
                edges = nil // exact root-only Original has no child ordinal backing
            }
            let path = try allocateMetadata(kind: .pathUTF8, elementCount: 16_640)
            let read = try allocateMetadata(kind: .readWindow, elementCount: 65_536)
            let resources = try allocateMetadata(kind: .descriptorSlots, elementCount: 130)
            try path.initializeByteWindow(); try read.initializeByteWindow()
            if let edges { try edges.initializeOrdinalWindow() }
            try resources.initializeResourceWindow()
            for ordinal in 0..<count {
                try storage.reservation.withOriginalOperationsNode(ordinal: ordinal, capture: self) { first in
                    guard first.ordinal == ordinal, first.path.utf8.count <= 16_640,
                          first.path.utf8.allSatisfy({ $0 != 0 }),
                          nodes.elementCount == ordinal else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    let pathBytes = first.path.utf8
                    let lastSlash = pathBytes.lastIndex(of: 47)
                    let memberStart = lastSlash.map({ pathBytes.index(after: $0) }) ?? pathBytes.startIndex
                    let member = pathBytes[memberStart...]
                    guard (ordinal == 0 && member.isEmpty && first.path.isEmpty && first.kind == "directory")
                            || (ordinal > 0 && !member.isEmpty && member.count <= 255
                                && !member.elementsEqual(".".utf8) && !member.elementsEqual("..".utf8)) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    let parent: UInt32
                    if ordinal == 0 { parent = UInt32.max }
                    else {
                        let parentPath = lastSlash.map({ pathBytes[..<$0] }) ?? pathBytes[..<pathBytes.startIndex]
                        parent = try findOriginalParent(pathBytes: parentPath, before: ordinal,
                            nodes: nodes, names: names, path: path)
                        guard try nodes.originalNode(UInt64(parent)).physicalKind == 1 else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                    }
                    var parser = ColdEraseSchema2NamespaceFirstNineParserV1()
                    var node = try parser.parse(first.firstNineFact, ordinal: ordinal,
                        parent: parent, kind: first.kind)
                    guard UInt64(node.byteCount) == first.byteCount,
                          names.elementCount <= UInt64(UInt32.max) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    node.memberOffset = UInt32(names.elementCount)
                    node.memberByteCount = UInt16(member.count)
                    for byte in member { try names.appendOriginalByte(byte) }
                    if let sha = first.sha256 { try Self.decodeOriginalSHA(sha, node: &node) }
                    else { guard node.physicalKind == 1 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner } }
                    if ordinal > 0 {
                        // Authenticated global UTF-8 order is checked from the
                        // charged path window; no path alias leaves the callback.
                        guard try compareOriginalPath(ordinal: ordinal - 1, with: pathBytes[...],
                            nodes: nodes, names: names, path: path) < 0 else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                    }
                    try nodes.appendOriginalNode(node)
                    guard try compareOriginalPath(ordinal: ordinal, with: pathBytes[...],
                        nodes: nodes, names: names, path: path) == 0 else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                }
            }
            var edgeCount: UInt64 = 0
            for ordinal in 1..<count {
                let node = try nodes.originalNode(ordinal)
                try nodes.incrementOriginalChildCount(UInt64(node.parentOrdinal))
            }
            for ordinal in 0..<count {
                var node = try nodes.originalNode(ordinal)
                guard edgeCount <= UInt64(UInt32.max) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                node.firstChildOffset = UInt32(edgeCount)
                edgeCount += UInt64(node.childCount)
                // The same charged scalar is a fill cursor only during this
                // pure index pass. It is zero in the retained first image.
                node.settledSequence = 0
                try nodes.replaceOriginalNode(node, ordinal: ordinal)
            }
            guard edgeCount == count - 1 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            for ordinal in 1..<count {
                let node = try nodes.originalNode(ordinal)
                var parent = try nodes.originalNode(UInt64(node.parentOrdinal))
                guard parent.settledSequence < UInt64(parent.childCount) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                let edge = UInt64(parent.firstChildOffset) + parent.settledSequence
                guard let edges else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try edges.writeOriginalOrdinal(UInt32(ordinal), at: edge)
                parent.settledSequence += 1
                try nodes.replaceOriginalNode(parent, ordinal: UInt64(node.parentOrdinal))
            }
            for ordinal in 0..<count {
                var node = try nodes.originalNode(ordinal)
                guard node.settledSequence == UInt64(node.childCount) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                node.settledSequence = 0
                try nodes.replaceOriginalNode(node, ordinal: ordinal)
            }
            try storage.reservation.requireCaptureFrame(capture: self)
            storage.originalIndexCompleted = true // not a current physical/policy proof
        } catch { poisonOnUncertainEffect(); throw error }
    }

    private func findOriginalParent(pathBytes: String.UTF8View.SubSequence, before: UInt64,
        nodes: ColdEraseSchema2NamespaceMetadataBackingV1,
        names: ColdEraseSchema2NamespaceMetadataBackingV1,
        path: ColdEraseSchema2NamespaceMetadataBackingV1) throws -> UInt32 {
        var lower: UInt64 = 0, upper = before
        while lower < upper {
            let middle = lower + (upper - lower) / 2
            let order = try compareOriginalPath(ordinal: middle, with: pathBytes,
                nodes: nodes, names: names, path: path)
            if order < 0 { lower = middle + 1 } else { upper = middle }
        }
        guard lower < before, lower <= UInt64(UInt32.max),
              try compareOriginalPath(ordinal: lower, with: pathBytes,
                nodes: nodes, names: names, path: path) == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return UInt32(lower)
    }

    private func compareOriginalPath(ordinal: UInt64, with expected: String.UTF8View.SubSequence,
        nodes: ColdEraseSchema2NamespaceMetadataBackingV1,
        names: ColdEraseSchema2NamespaceMetadataBackingV1,
        path: ColdEraseSchema2NamespaceMetadataBackingV1) throws -> Int {
        var current = ordinal, cursor = path.actualCapacity, depth: UInt64 = 0
        let maximumDepth: UInt64 = try nodes.originalNode(ordinal).physicalKind == 2 ? 65 : 64
        while current != 0 {
            let node = try nodes.originalNode(current)
            guard depth < maximumDepth, UInt64(node.parentOrdinal) < current else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let length = UInt64(node.memberByteCount)
            guard length > 0, length <= cursor else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            for offset in (0..<length).reversed() {
                cursor -= 1
                try path.writeOriginalByte(try names.originalByte(UInt64(node.memberOffset) + offset), at: cursor)
            }
            current = UInt64(node.parentOrdinal); depth += 1
            if current != 0 {
                guard cursor > 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                cursor -= 1; try path.writeOriginalByte(47, at: cursor)
            }
        }
        var candidate = cursor, expectedIndex = expected.startIndex
        while candidate < path.actualCapacity && expectedIndex != expected.endIndex {
            let left = try path.originalByte(candidate), right = expected[expectedIndex]
            if left != right { return left < right ? -1 : 1 }
            candidate += 1; expectedIndex = expected.index(after: expectedIndex)
        }
        if candidate == path.actualCapacity { return expectedIndex == expected.endIndex ? 0 : -1 }
        return 1
    }

    private static func decodeOriginalSHA(_ sha: String,
        node: inout ColdEraseSchema2NamespaceNodeStorageV1) throws {
        guard sha.utf8.count == 64 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var word: UInt64 = 0, index = 0
        for byte in sha.utf8 {
            let value: UInt64
            if byte >= 48 && byte <= 57 { value = UInt64(byte - 48) }
            else if byte >= 97 && byte <= 102 { value = UInt64(byte - 87) }
            else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            word = (word << 4) | value; index += 1
            if index % 16 == 0 {
                switch index { case 16: node.digestWord0 = word; case 32: node.digestWord1 = word
                case 48: node.digestWord2 = word; case 64: node.digestWord3 = word
                default: throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                word = 0
            }
        }
        guard node.physicalKind == 2 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }

    fileprivate func requireMetadataReleaseConsumer(_ receipt: ColdEraseSchema2NamespaceRemovalReceiptV1) throws {
        guard storage.state == .captured, storage.checkedConsumer === receipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try receipt.requireCaptureConsumerCompleted(capture: self)
    }

    fileprivate func retainRegistryCloseAttempt(_ attempt: ColdEraseSchema2RegistryControlCloseAttemptV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1) throws {
        guard storage.state == .captured, storage.checkedConsumer === namespace,
              storage.registryCloseAttempt == nil, storage.registryCloseReceipt == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.registryCloseAttempt = attempt // before any entered control-close IO
        try namespace.requireCaptureConsumerCompleted(capture: self)
    }

    fileprivate func retainRegistryCloseReceipt(_ receipt: ColdEraseSchema2RegistryControlCloseReceiptV1,
        attempt: ColdEraseSchema2RegistryControlCloseAttemptV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1) throws {
        guard storage.state == .captured, storage.checkedConsumer === namespace,
              storage.registryCloseAttempt === attempt, storage.registryCloseReceipt == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.registryCloseReceipt = receipt
    }

    func requireCheckedReleased() throws {
        guard storage.state == .released, let receipt = storage.checkedConsumer else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try receipt.requireCaptureConsumerCompleted(capture: self)
        try storage.nodeTable?.requireCheckedReleasedForCapture(self)
        try storage.memberUTF8?.requireCheckedReleasedForCapture(self)
        try storage.childOrdinals?.requireCheckedReleasedForCapture(self)
        try storage.pathUTF8?.requireCheckedReleasedForCapture(self)
        try storage.readWindow?.requireCheckedReleasedForCapture(self)
        try storage.descriptorSlots?.requireCheckedReleasedForCapture(self)
    }

    func poisonOnUncertainEffect() {
        storage.state = .uncertain
        storage.operation.poisonColdScratchOwner()
    }
}

/// One genuine fixed-capacity allocation of a closed kind. Raw pointers and
/// initialized elements remain private; no table/arena alias escapes its owner.
@MainActor
final class ColdEraseSchema2NamespaceMetadataBackingV1 {
    fileprivate struct Storage {
        let lease: ColdEraseSchema2NamespaceMetadataLeaseV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let kind: ColdEraseSchema2NamespaceMetadataKindV1
        let capacity: UInt64
        var initializedCount: UInt64 = 0
        var nodes: UnsafeMutablePointer<ColdEraseSchema2NamespaceNodeStorageV1>?
        var bytes: UnsafeMutablePointer<UInt8>?
        var ordinals: UnsafeMutablePointer<UInt32>?
        var resources: UnsafeMutablePointer<ColdEraseSchema2NamespaceResourceStorageV1>?
        var released = false
    }
    private var storage: Storage
    var kind: ColdEraseSchema2NamespaceMetadataKindV1 { storage.kind }
    var elementCount: UInt64 { storage.initializedCount }
    var actualCapacity: UInt64 { storage.capacity }

    fileprivate init(lease: ColdEraseSchema2NamespaceMetadataLeaseV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        kind: ColdEraseSchema2NamespaceMetadataKindV1, capacity: UInt64) throws {
        guard capacity > 0, capacity <= UInt64(Int.max) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage = Storage(lease: lease, capture: capture, kind: kind, capacity: capacity)
        let count = Int(capacity)
        switch kind {
        case .nodeTable: storage.nodes = .allocate(capacity: count)
        case .memberUTF8, .pathUTF8, .readWindow: storage.bytes = .allocate(capacity: count)
        case .childOrdinals: storage.ordinals = .allocate(capacity: count)
        case .descriptorSlots: storage.resources = .allocate(capacity: count)
        }
    }

    func requireReservationAssociation(lease: ColdEraseSchema2NamespaceMetadataLeaseV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        kind: ColdEraseSchema2NamespaceMetadataKindV1) throws {
        guard storage.lease === lease, storage.capture === capture, storage.kind == kind,
              storage.initializedCount <= storage.capacity else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if storage.released {
            guard storage.nodes == nil, storage.bytes == nil, storage.ordinals == nil,
                  storage.resources == nil, storage.initializedCount == 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        } else {
            switch kind {
            case .nodeTable: guard storage.nodes != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            case .memberUTF8, .pathUTF8, .readWindow:
                guard storage.bytes != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            case .childOrdinals: guard storage.ordinals != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            case .descriptorSlots: guard storage.resources != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            }
        }
    }

    fileprivate func initializeByteWindow() throws {
        guard !storage.released, storage.initializedCount == 0,
              storage.kind == .pathUTF8 || storage.kind == .readWindow,
              let bytes = storage.bytes else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        bytes.initialize(repeating: 0, count: Int(storage.capacity))
        storage.initializedCount = storage.capacity
    }

    fileprivate func initializeOrdinalWindow() throws {
        guard !storage.released, storage.initializedCount == 0, storage.kind == .childOrdinals,
              let ordinals = storage.ordinals else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        ordinals.initialize(repeating: 0, count: Int(storage.capacity))
