    fileprivate func appendOriginalNode(_ node: ColdEraseSchema2NamespaceNodeStorageV1) throws {
        guard !storage.released, storage.kind == .nodeTable, node.lineageDomain == 1,
              node.projectionState == 0, node.ownerUID == 0, node.ownerGID == 0,
              node.policyCode == 0, UInt64(node.physicalOrdinal) == storage.initializedCount,
              storage.initializedCount < storage.capacity, let nodes = storage.nodes else {
