    fileprivate func originalNode(_ ordinal: UInt64) throws -> ColdEraseSchema2NamespaceNodeStorageV1 {
        guard !storage.released, storage.kind == .nodeTable,
              ordinal < storage.initializedCount, let nodes = storage.nodes else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let node = nodes[Int(ordinal)]
        guard node.lineageDomain == 1, node.projectionState == 0,
              UInt64(node.physicalOrdinal) == ordinal else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
