        ordinal: UInt64) throws {
        guard !storage.released, storage.kind == .nodeTable, ordinal < storage.initializedCount,
              UInt64(node.physicalOrdinal) == ordinal, node.lineageDomain == 1,
              node.projectionState == 0, let nodes = storage.nodes else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        nodes[Int(ordinal)] = node
    }

    fileprivate func incrementOriginalChildCount(_ ordinal: UInt64) throws {
        var node = try originalNode(ordinal)
        guard node.physicalKind == 1, node.childCount < UInt32.max else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        node.childCount += 1
        try replaceOriginalNode(node, ordinal: ordinal)
    }

    fileprivate func writeOriginalOrdinal(_ ordinal: UInt32, at offset: UInt64) throws {
        guard !storage.released, storage.kind == .childOrdinals,
              offset < storage.initializedCount, let ordinals = storage.ordinals else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        ordinals[Int(offset)] = ordinal
    }

    fileprivate func releaseAfterCheckedConsumer(_ receipt: ColdEraseSchema2NamespaceRemovalReceiptV1) throws {
        guard !storage.released, storage.initializedCount <= storage.capacity else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.capture.requireMetadataReleaseConsumer(receipt)
        let count = Int(storage.initializedCount)
        storage.released = true // permanently before any memory dependency is destroyed
        if let nodes = storage.nodes { nodes.deinitialize(count: count); nodes.deallocate(); storage.nodes = nil }
        if let bytes = storage.bytes { bytes.deinitialize(count: count); bytes.deallocate(); storage.bytes = nil }
        if let ordinals = storage.ordinals { ordinals.deinitialize(count: count); ordinals.deallocate(); storage.ordinals = nil }
        if let resources = storage.resources { resources.deinitialize(count: count); resources.deallocate(); storage.resources = nil }
        storage.initializedCount = 0
    }

    func requireCheckedReleased(lease: ColdEraseSchema2NamespaceMetadataLeaseV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        try requireReservationAssociation(lease: lease, capture: capture, kind: storage.kind)
        try requireCheckedReleasedForCapture(capture)
    }

    fileprivate func requireCheckedReleasedForCapture(_ capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard storage.capture === capture, storage.released, storage.initializedCount == 0,
              storage.nodes == nil, storage.bytes == nil, storage.ordinals == nil,
              storage.resources == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
}

