        binding expectedBinding: EraseRetirementBindingV1,
        witness expectedWitness: EraseSessionDrainWitnessV1)
        throws -> (allocation: GenerationLeaseAllocationAttemptV1, reader: GenerationLeaseHandleV1) {
        guard let allocation, let reader else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireBound(preparation: preparation, registry: expectedRegistry,
            allocation: allocation, reader: reader, operation: expectedOperation,
            activity: expectedActivity, exclusion: expectedExclusion,
            binding: expectedBinding, witness: expectedWitness)
