/// First-role completion, distinct from the final reader retirement receipt.
/// The canonical replacement and its transient resources are settled while
/// the original publication record remains separately retained under live G.
@MainActor
final class ColdEraseSchema2ReaderReplacementCompletionV1 {
    private let attempt: ColdEraseSchema2ReaderRetirementAttemptV1
    private let directoryDurability: ColdEraseSchema2ReaderRetirementOutcomeV1
    private let renamedClose: ColdEraseSchema2ReaderRetirementOutcomeV1
    private let publicationDescriptor: Int32
    fileprivate var readerJournalCaptureEnteredV4 = false
    fileprivate var readerJournalFirstV4: ColdEraseSchema2ReaderJournalCensusV4?
    fileprivate var readerJournalSecondV4: ColdEraseSchema2ReaderJournalCensusV4?
    fileprivate var readerJournalPostimageV4: ColdEraseSchema2ReaderJournalPostimageV4?
    let beforeTokens: [GenerationLeaseTokenV1]
    let afterTokens: [GenerationLeaseTokenV1]
    let fullFacts: [String: String]
    let leaseNames: [String]
    let ownerNames: [String]

    fileprivate init(attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        allocation: GenerationLeaseAllocationAttemptV1) throws {
        guard !attempt.uncertain, !attempt.ownedMutationPending,
              attempt.replacementCompletion == nil,
              let directoryDurability = attempt.replacementOutcome,
              let renamedClose = attempt.lastOutcome,
              renamedClose.primitive == .closeRenamedRegistry,
              case .syscall(let closeReturned, _) = renamedClose.result,
              closeReturned == 0, attempt.original < 0, attempt.temporary < 0,
              attempt.uncertainCloseDescriptors.isEmpty,
              !attempt.recordClosed, !attempt.recordUnlinked,
              allocation.schema2ColdRecordDescriptor >= 0,
              !attempt.checkedGReleased, !attempt.completed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try directoryDurability.requireReplacementSettled(attempt: attempt)
        try renamedClose.requireBound(attempt: attempt, primitive: .closeRenamedRegistry)
        for pin in attempt.readPins.values { try pin.requireCheckedClosed() }
        try attempt.io.requireSettled()
        self.attempt = attempt; self.directoryDurability = directoryDurability
        self.renamedClose = renamedClose
        publicationDescriptor = allocation.schema2ColdRecordDescriptor
        beforeTokens = attempt.preparation.beforeTokens
        afterTokens = attempt.preparation.afterTokens
        fullFacts = attempt.currentFacts; leaseNames = attempt.currentLeaseNames
        ownerNames = attempt.ownerNames
    }

    func requireBound(attempt expected: ColdEraseSchema2ReaderRetirementAttemptV1,
        registry: GenerationLeaseRegistryV1, allocation: GenerationLeaseAllocationAttemptV1,
        reader: GenerationLeaseHandleV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        guard attempt === expected, expected.replacementCompletion === self,
              !expected.uncertain, expected.replacementOutcome === directoryDurability,
              expected.original < 0, expected.temporary < 0,
              beforeTokens == [reader.token], afterTokens.isEmpty,
              renamedClose.primitive == .closeRenamedRegistry,
              case .syscall(let closeReturned, _) = renamedClose.result,
              closeReturned == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireBound(preparation: expected.preparation, registry: registry,
            allocation: allocation, reader: reader, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        try directoryDurability.requireReplacementSettled(attempt: expected)
    }

    func requireBeforePublicationRecordClose(attempt expected: ColdEraseSchema2ReaderRetirementAttemptV1,
        registry: GenerationLeaseRegistryV1, allocation: GenerationLeaseAllocationAttemptV1,
        reader: GenerationLeaseHandleV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        try requireBound(attempt: expected, registry: registry, allocation: allocation,
            reader: reader, operation: operation, activity: activity, exclusion: exclusion,
            binding: binding, witness: witness)
        guard expected.lastOutcome === renamedClose, !expected.ownedMutationPending,
              !expected.recordClosed, !expected.recordUnlinked,
              allocation.schema2ColdRecordDescriptor == publicationDescriptor,
              !expected.checkedGReleased, !expected.completed,
              expected.currentFacts == fullFacts, expected.currentLeaseNames == leaseNames,
              expected.ownerNames == ownerNames else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for pin in expected.readPins.values { try pin.requireCheckedClosed() }
        try expected.io.requireSettled()
    }
}

/// Final result after the genuine writer, all resource closes and actual G
/// unlock. Only the same Registry's completed retained attempt can issue it.
@MainActor
final class ColdEraseSchema2ReaderRetirementReceiptV1 {
    private let attempt: ColdEraseSchema2ReaderRetirementAttemptV1
    let beforeTokens: [GenerationLeaseTokenV1]
    let afterTokens: [GenerationLeaseTokenV1]
    private let registryProjection: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild
    fileprivate var readerJournalPostimageV4: ColdEraseSchema2ReaderJournalPostimageV4?
    fileprivate init(attempt: ColdEraseSchema2ReaderRetirementAttemptV1) throws {
        guard attempt.completed, attempt.checkedGReleased,
              let projection = attempt.finalRegistryProjection else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        self.attempt = attempt; beforeTokens = attempt.preparation.beforeTokens
        afterTokens = attempt.preparation.afterTokens; registryProjection = projection
    }

    /// Fresh checked DATA join against the original completed writer image.
    /// This cannot mint a namespace task or accept a newly sampled baseline.
    func requireCurrentRegistryProjection(operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1)
        throws -> EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild {
        let resources = try attempt.requireProjectionResources(operation: operation,
            registry: registry, activity: activity, exclusion: exclusion,
            binding: binding, witness: witness)
        try requireBound(operation: operation, registry: registry, activity: activity,
            allocation: resources.allocation, reader: resources.reader, exclusion: exclusion,
            binding: binding, witness: witness)
        return try registry.requireColdSchema2ReaderRegistryProjection(receipt: self,
            attempt: attempt, expected: registryProjection, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness)
    }
    func requireBound(operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1, activity: GenerationTemporalActivityHandleV1,
        allocation: GenerationLeaseAllocationAttemptV1, reader: GenerationLeaseHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        try attempt.requireBound(preparation: attempt.preparation, registry: registry,
            allocation: allocation, reader: reader, operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness)
        guard attempt.completed, attempt.checkedGReleased, attempt.recordClosed,
              attempt.recordUnlinked, attempt.original < 0, attempt.temporary < 0,
              attempt.publicationUnlinkedFullFact != nil,
              allocation.closed, allocation.schema2ColdRecordDescriptor < 0,
              attempt.uncertainCloseDescriptors.isEmpty,
              beforeTokens == [reader.token], afterTokens.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try reader.requireColdSchema2RetirementClosed(registry: registry)
        try registry.requireColdSchema2ReaderRetirementReceipt(self)
        try attempt.io.requireSettled()
        guard let publicationPin = attempt.readPins["unlink-publication-record"] else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try publicationPin.requireCheckedClosed()
    }
}

