/// One scoped read pin retained before open. Positive reads/close store real
/// results; a failed close never retries the potentially reused descriptor.
@MainActor
fileprivate final class ColdEraseSchema2ReaderRetirementReadPinV1 {
    private(set) var descriptor: Int32 = -1
    private(set) var openResult: ColdEraseSchema2ReaderRetirementResultV1?
    private(set) var lastReadResult: ColdEraseSchema2ReaderRetirementResultV1?
    private(set) var closeResult: ColdEraseSchema2ReaderRetirementResultV1?
    private var closeAttempted = false
    private var uncertain = false

    func open(parent: Int32, name: String) throws {
        guard descriptor < 0, openResult == nil, !closeAttempted, !uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let value = Darwin.openat(parent, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        let saved = errno
        descriptor = value // before any fallible image/policy read
        openResult = .syscall(returnValue: Int64(value), savedErrno: saved)
        guard value >= 0 else { uncertain = true; throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }

    func readExactly(_ expected: Data, requireCurrent: @MainActor () throws -> Void) throws {
        guard descriptor >= 0, !closeAttempted, !uncertain,
              expected.count <= GenerationLeaseRegistryV1.maximumControlFileBytes else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var offset = 0
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while offset < expected.count {
            try requireCurrent()
            let wanted = min(buffer.count, expected.count - offset)
            let result = buffer.withUnsafeMutableBytes {
                Darwin.pread(descriptor, $0.baseAddress, wanted, off_t(offset))
            }
            let saved = errno
            lastReadResult = .syscall(returnValue: Int64(result), savedErrno: saved)
            try requireCurrent()
            guard result > 0, result <= wanted,
                  buffer.prefix(result).elementsEqual(expected[offset..<(offset + result)]) else {
                uncertain = true
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            offset += result
        }
        try requireCurrent()
        var extra: UInt8 = 0
        let result = Darwin.pread(descriptor, &extra, 1, off_t(expected.count))
        let saved = errno
        lastReadResult = .syscall(returnValue: Int64(result), savedErrno: saved)
        try requireCurrent()
        guard result == 0 else { uncertain = true; throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }

    func closeChecked() throws {
        guard descriptor >= 0, !closeAttempted else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        closeAttempted = true
        let owned = descriptor
        descriptor = -1
        let result = Darwin.close(owned)
        let saved = errno
        closeResult = .syscall(returnValue: Int64(result), savedErrno: saved)
        guard result == 0 else { uncertain = true; throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }

    func requireCheckedClosed() throws {
        guard closeAttempted, descriptor < 0, !uncertain,
              case .syscall(let returned, _)? = closeResult, returned == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor private func requireColdSchema2RetirementWriterFrame(
        _ attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        allocation: GenerationLeaseAllocationAttemptV1, reader: GenerationLeaseHandleV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        try attempt.requireBound(preparation: attempt.preparation, registry: self,
            allocation: allocation, reader: reader, operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness)
        _ = try requireColdSchema2RetirementOrigin(operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness, heldG: true)
        guard attempt.policyUncertainDescriptors.isEmpty else { throw Self.uncertainOwnerFailure() }
    }

    @MainActor private func coldSchema2WriterFact(_ key: String,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1) throws -> stat {
        var value = stat()
        if key == "lease-root" || key == "owner-root" {
            let descriptor = key == "lease-root" ? leaseDescriptor : ownersDescriptor
            guard Darwin.fstat(descriptor, &value) == 0 else { throw Self.identityFailure() }
        } else if key == "migration-root" {
            guard Darwin.fstatat(operationsDescriptor, "schema-migration", &value, AT_SYMLINK_NOFOLLOW) == 0 else {
                throw Self.identityFailure()
            }
        } else {
            let pair = key.split(separator: "/", maxSplits: 1).map(String.init)
            guard pair.count == 2 else { throw Self.identityFailure() }
            if pair[0] == "lease" || pair[0] == "owners" {
                let parent = pair[0] == "lease" ? leaseDescriptor : ownersDescriptor
                guard Darwin.fstatat(parent, pair[1], &value, AT_SYMLINK_NOFOLLOW) == 0 else {
                    throw Self.identityFailure()
                }
            } else if pair[0] == "migration" {
                try attempt.io.withOpen(parent: operationsDescriptor, name: "schema-migration",
                    flags: O_RDONLY | O_DIRECTORY) { directory in
                    var held = stat(), named = stat()
                    guard Darwin.fstat(directory, &held) == 0,
                          Darwin.fstatat(operationsDescriptor, "schema-migration", &named, AT_SYMLINK_NOFOLLOW) == 0,
                          Self.originalEraseRetainedFullFact(held) == attempt.currentFacts["migration-root"],
                          Self.originalEraseRetainedFullFact(named) == attempt.currentFacts["migration-root"],
                          Darwin.fstatat(directory, pair[1], &value, AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw Self.identityFailure()
                    }
                }
            } else { throw Self.identityFailure() }
        }
        return value
    }

    @MainActor private func readColdSchema2WriterMember(
        _ key: String, bytes: Data, fact: String,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        requireFrame: @MainActor () throws -> Void) throws {
        let pair = key.split(separator: "/", maxSplits: 1).map(String.init)
        guard pair.count == 2 else { throw Self.identityFailure() }
        @MainActor func withParent(_ parent: Int32) throws {
            if let previous = attempt.readPins[key] { try previous.requireCheckedClosed() }
            let pin = ColdEraseSchema2ReaderRetirementReadPinV1()
            attempt.readPins[key] = pin // actual owner before open
            try requireFrame()
            try pin.open(parent: parent, name: pair[1])
            @MainActor func requireLeaf() throws {
                try requireFrame()
                var held = stat(), named = stat()
                guard Darwin.fstat(pin.descriptor, &held) == 0,
                      Darwin.fstatat(parent, pair[1], &named, AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(held) == fact,
                      Self.originalEraseRetainedFullFact(named) == fact,
                      held.st_mode & S_IFMT == S_IFREG, held.st_nlink == 1 else {
                    throw Self.identityFailure()
                }
            }
            do { try pin.readExactly(bytes, requireCurrent: requireLeaf) }
            catch { try pin.closeChecked(); throw error }
            try pin.closeChecked()
            try pin.requireCheckedClosed()
            try requireFrame()
        }
        if pair[0] == "lease" || pair[0] == "owners" {
            try withParent(pair[0] == "lease" ? leaseDescriptor : ownersDescriptor)
        } else if pair[0] == "migration" {
            try attempt.io.withOpen(parent: operationsDescriptor, name: "schema-migration",
                flags: O_RDONLY | O_DIRECTORY) { directory in
                var held = stat(), named = stat()
                guard Darwin.fstat(directory, &held) == 0,
                      Darwin.fstatat(operationsDescriptor, "schema-migration", &named, AT_SYMLINK_NOFOLLOW) == 0,
                      Self.originalEraseRetainedFullFact(held) == attempt.currentFacts["migration-root"],
                      Self.originalEraseRetainedFullFact(named) == attempt.currentFacts["migration-root"] else {
                    throw Self.identityFailure()
                }
                try withParent(directory)
            }
        } else { throw Self.identityFailure() }
    }

    @MainActor private func requireColdSchema2WriterCurrent(
        _ attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        requireFrame: @MainActor () throws -> Void) throws {
        try requireFrame()
        let names = try attempt.io.boundedNames(in: leaseDescriptor, maximumCount: 7)
        let owners = try attempt.io.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount)
        guard names == attempt.currentLeaseNames, owners == attempt.ownerNames else { throw Self.identityFailure() }
        for (key, expected) in attempt.currentFacts {
            let fact = try coldSchema2WriterFact(key, attempt: attempt)
            guard Self.originalEraseRetainedFullFact(fact) == expected else { throw Self.identityFailure() }
        }
        for (key, bytes) in attempt.currentBytes {
            guard let fact = attempt.currentFacts[key] else { throw Self.identityFailure() }
            try readColdSchema2WriterMember(key, bytes: bytes, fact: fact,
                attempt: attempt, requireFrame: requireFrame)
        }
        // Final original-cached whole membership/fact pass after every read.
        guard try attempt.io.boundedNames(in: leaseDescriptor, maximumCount: 7) == names,
              try attempt.io.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount) == owners else {
            throw Self.identityFailure()
        }
        for (key, expected) in attempt.currentFacts {
            guard Self.originalEraseRetainedFullFact(try coldSchema2WriterFact(key, attempt: attempt)) == expected else {
                throw Self.identityFailure()
            }
        }
        if attempt.currentFacts["migration-root"] == nil {
            var absent = stat()
            guard Darwin.fstatat(operationsDescriptor, "schema-migration", &absent, AT_SYMLINK_NOFOLLOW) < 0,
                  errno == ENOENT else { throw Self.identityFailure() }
        }
        try attempt.io.requireSettled()
        try requireFrame()
    }

    /// Only a positive owned namespace syscall may project this parent. Its
    /// stable identity/mode/owner, exact declared membership and every untouched
    /// member remain fixed; the known link delta is at most one, never ignored.
    @MainActor private func projectColdSchema2WriterDirectory(
        _ attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        linkDelta: Int) throws {
        guard let before = attempt.currentFacts["lease-root"], linkDelta == 1 || linkDelta == -1 else {
            throw Self.identityFailure()
        }
        var held = stat(), named = stat()
        guard Darwin.fstat(leaseDescriptor, &held) == 0,
              Darwin.fstatat(operationsDescriptor, Self.leaseDirectoryName, &named, AT_SYMLINK_NOFOLLOW) == 0 else {
            throw Self.identityFailure()
        }
        let after = Self.originalEraseRetainedFullFact(held)
        let a = before.split(separator: "|", omittingEmptySubsequences: false)
        let b = after.split(separator: "|", omittingEmptySubsequences: false)
        guard a.count == 11, b.count == 11, a.prefix(5) == b.prefix(5),
              after == Self.originalEraseRetainedFullFact(named),
              let oldLinks = UInt64(a[5]), let newLinks = UInt64(b[5]), oldLinks > 0, newLinks > 0 else {
            throw Self.identityFailure()
        }
        let beforeCount = attempt.currentLeaseNames.count - linkDelta
        guard beforeCount >= 0,
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(oldLinks), directEntryCount: beforeCount),
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(newLinks),
                directEntryCount: attempt.currentLeaseNames.count),
              try attempt.io.boundedNames(in: leaseDescriptor, maximumCount: 7) == attempt.currentLeaseNames else {
            throw Self.identityFailure()
        }
        attempt.currentFacts["lease-root"] = after // true named owned effect lineage
    }
}


extension GenerationLeaseRegistryV1 {
    /// All members outside the one genuine pending owned primitive stay byte
