    /// This descriptor was retained before its real open; no unnamed inode is
    /// reopened. Reads retain their true result before the after-read check.
    @MainActor private func readColdSchema2WriterHeld(
        descriptor: Int32, role: String, bytes: Data,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        requireCurrent: @MainActor () throws -> Void) throws {
        guard descriptor >= 0, bytes.count <= Self.maximumControlFileBytes else { throw Self.identityFailure() }
        var offset = 0
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while offset < bytes.count {
            try requireCurrent()
            let count = min(buffer.count, bytes.count - offset)
            let result = buffer.withUnsafeMutableBytes {
                Darwin.pread(descriptor, $0.baseAddress, count, off_t(offset))
            }
            let saved = errno
            attempt.lastReadResults[role] = .syscall(returnValue: Int64(result), savedErrno: saved)
            try requireCurrent()
            guard result > 0, result <= count,
                  buffer.prefix(result).elementsEqual(bytes[offset..<(offset + result)]) else {
                throw Self.identityFailure(errorNumber: saved)
            }
            offset += result
        }
        try requireCurrent()
        var extra: UInt8 = 0
        let result = Darwin.pread(descriptor, &extra, 1, off_t(bytes.count))
        let saved = errno
        attempt.lastReadResults[role] = .syscall(returnValue: Int64(result), savedErrno: saved)
        try requireCurrent()
        guard result == 0 else { throw Self.identityFailure(errorNumber: saved) }
    }

    @MainActor private func coldSchema2WriterNamedHeld(
        descriptor: Int32, name: String, bytes: Data,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        requireFrame: @MainActor () throws -> Void) throws -> stat {
        try requireFrame()
