              Darwin.fstatat(leaseDescriptor, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
              initial.st_mode & S_IFMT == S_IFREG, initial.st_nlink == 1,
              initial.st_size == off_t(bytes.count),
              Self.originalEraseRetainedFullFact(initial) == Self.originalEraseRetainedFullFact(named) else {
            throw Self.identityFailure()
