        let exact = Self.originalEraseRetainedFullFact(initial)
        try readColdSchema2WriterHeld(descriptor: descriptor, role: "held/" + name,
            bytes: bytes, attempt: attempt) {
            try requireFrame()
            var held = stat(), named = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(self.leaseDescriptor, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  Self.originalEraseRetainedFullFact(held) == exact,
                  Self.originalEraseRetainedFullFact(named) == exact else { throw Self.identityFailure() }
        }
        return initial
    }

    /// Closed writer for the two actual durable post-content roles. No caller
    /// can instantiate its attempt, outcome or receipt. Failure is permanent;
    /// neither an existing temporary nor a failed original is rearmed.
    @MainActor
    func closeColdSchema2TargetAllocationAfterDrain(
