                attempt.currentBytes[registryKey] = replacement
                attempt.currentLeaseNames.removeAll { $0 == preparation.registryTemporaryName }
                try self.projectColdSchema2WriterDirectory(attempt, linkDelta: -1)
                try finish()

                try begin(.fsyncRegistryDirectory)
                let syncRegistry = Darwin.fsync(self.leaseDescriptor)
                let syncRegistryErrno = errno
                try returned(Int64(syncRegistry), savedErrno: syncRegistryErrno)
                // Private positive intermediate moves the OP cohort only through
                // Permit.recordOutcome, before any checked census can observe [].
                try finish(replacementSettled: true)

                try begin(.closeDisplacedRegistry)
                var oldHeld = stat()
                guard Darwin.fstat(original, &oldHeld) == 0,
                      Self.originalEraseRetainedFullFact(oldHeld) == attempt.displacedFact else { throw Self.identityFailure() }
                attempt.uncertainCloseDescriptors.append(original) // retained before close
                attempt.original = -1 // latch before close; no reused-FD retry
                let closeOriginal = Darwin.close(original)
                let closeOriginalErrno = errno
                try returned(Int64(closeOriginal), savedErrno: closeOriginalErrno)
                attempt.uncertainCloseDescriptors.removeAll { $0 == original }
                attempt.checkedCloses.insert(original)
                try finish()

                try begin(.closeRenamedRegistry)
                _ = try self.coldSchema2WriterNamedHeld(descriptor: temporary,
                    name: preparation.registryName, bytes: replacement, attempt: attempt, requireFrame: frame)
                attempt.uncertainCloseDescriptors.append(temporary) // retained before close
                attempt.temporary = -1
                let closeTemporary = Darwin.close(temporary)
                let closeTemporaryErrno = errno
                try returned(Int64(closeTemporary), savedErrno: closeTemporaryErrno)
                attempt.uncertainCloseDescriptors.removeAll { $0 == temporary }
                attempt.checkedCloses.insert(temporary)
                try finish()

                // Settle the first logical role before asking for the second
                // durable REQUEST. The publication descriptor remains the
                // original retained loan, and G/EX have not been released.
                try current()
                let replacementCompletion = try ColdEraseSchema2ReaderReplacementCompletionV1(
                    attempt: attempt, allocation: allocation)
                attempt.replacementCompletion = replacementCompletion
                try replacementCompletion.requireBeforePublicationRecordClose(attempt: attempt,
                    registry: self, allocation: allocation, reader: reader,
                    operation: operation, activity: activity, exclusion: exclusion,
                    binding: binding, witness: witness)
                try permit.recordReplacementCompletion(replacementCompletion, attempt: attempt)
                try permit.requireReplacementCompleted(replacementCompletion, attempt: attempt)
                try current()

                try begin(.closePublicationRecord)
                let publication = allocation.schema2ColdRecordDescriptor
                guard publication >= 0 else { throw Self.uncertainOwnerFailure() }
                let publicationFact = try self.coldSchema2WriterNamedHeld(descriptor: publication,
                    name: preparation.publicationRecordName, bytes: preparation.publicationRecordBytes,
                    attempt: attempt, requireFrame: frame)
                guard Self.originalEraseRetainedFullFact(publicationFact) == preparation.fullFacts[recordKey] else {
                    throw Self.identityFailure()
                }
                attempt.uncertainCloseDescriptors.append(publication) // retained before close
                allocation.schema2ColdRecordDescriptor = -1
                let closePublication = Darwin.close(publication)
                let closePublicationErrno = errno
                try returned(Int64(closePublication), savedErrno: closePublicationErrno)
                attempt.uncertainCloseDescriptors.removeAll { $0 == publication }
                attempt.checkedCloses.insert(publication)
                attempt.recordClosed = true
                try finish()

                try begin(.unlinkPublicationRecord)
                // This is a new distinct read pin, not the closed publication FD.
                // It stays held through the single committed unlink and proves
                // the exact removed inode before its own checked close.
                let pin = ColdEraseSchema2ReaderRetirementReadPinV1()
                let pinKey = "unlink-publication-record"
                attempt.readPins[pinKey] = pin
                try pin.open(parent: self.leaseDescriptor, name: preparation.publicationRecordName)
                @MainActor func namedPublicationPin() throws {
                    try frame()
                    var held = stat(), named = stat()
                    guard Darwin.fstat(pin.descriptor, &held) == 0,
                          Darwin.fstatat(self.leaseDescriptor, preparation.publicationRecordName,
                            &named, AT_SYMLINK_NOFOLLOW) == 0,
                          Self.originalEraseRetainedFullFact(held) == preparation.fullFacts[recordKey],
                          Self.originalEraseRetainedFullFact(named) == preparation.fullFacts[recordKey] else {
                        throw Self.identityFailure()
                    }
                }
                try pin.readExactly(preparation.publicationRecordBytes, requireCurrent: namedPublicationPin)
                try namedPublicationPin()
                let unlinked = Darwin.unlinkat(self.leaseDescriptor, preparation.publicationRecordName, 0)
                let unlinkErrno = errno
                try returned(Int64(unlinked), savedErrno: unlinkErrno)
                attempt.recordUnlinked = true
                var removed = stat()
                guard Darwin.fstat(pin.descriptor, &removed) == 0,
                      removed.st_dev == publicationFact.st_dev, removed.st_ino == publicationFact.st_ino,
                      removed.st_mode == publicationFact.st_mode, removed.st_uid == publicationFact.st_uid,
                      removed.st_gid == publicationFact.st_gid, removed.st_nlink == 0,
                      removed.st_size == publicationFact.st_size,
                      removed.st_mtimespec.tv_sec == publicationFact.st_mtimespec.tv_sec,
                      removed.st_mtimespec.tv_nsec == publicationFact.st_mtimespec.tv_nsec,
                      Darwin.fstatat(self.leaseDescriptor, preparation.publicationRecordName,
                        &absent, AT_SYMLINK_NOFOLLOW) < 0, errno == ENOENT else { throw Self.identityFailure() }
                let removedFact = Self.originalEraseRetainedFullFact(removed)
                attempt.publicationUnlinkedFullFact = removedFact // actual held-unlinked proof, not canonical replay DATA
                try pin.readExactly(preparation.publicationRecordBytes) {
                    try frame()
                    var held = stat(), absent = stat()
                    guard Darwin.fstat(pin.descriptor, &held) == 0,
                          Self.originalEraseRetainedFullFact(held) == removedFact,
                          Darwin.fstatat(self.leaseDescriptor, preparation.publicationRecordName,
                            &absent, AT_SYMLINK_NOFOLLOW) < 0, errno == ENOENT else { throw Self.identityFailure() }
                }
                try pin.closeChecked()
                try pin.requireCheckedClosed()
                attempt.currentFacts.removeValue(forKey: recordKey)
                attempt.currentBytes.removeValue(forKey: recordKey)
                attempt.currentLeaseNames.removeAll { $0 == preparation.publicationRecordName }
                try self.projectColdSchema2WriterDirectory(attempt, linkDelta: -1)
                try finish()

                try begin(.fsyncPublicationRecordDirectory)
                let syncRecordDirectory = Darwin.fsync(self.leaseDescriptor)
                let syncRecordDirectoryErrno = errno
                try returned(Int64(syncRecordDirectory), savedErrno: syncRecordDirectoryErrno)
                try finish()
                let first = try self.observeColdSchema2RetirementCensusLocked(operation: operation,
                    activity: activity, exclusion: exclusion, binding: binding, witness: witness)
                attempt.namespaceFinalFirstCensus = first // actual return retained before second observer/refusal
                let second = try self.observeColdSchema2RetirementCensusLocked(operation: operation,
                    activity: activity, exclusion: exclusion, binding: binding, witness: witness)
                attempt.namespaceFinalSecondCensus = second // actual return retained before all equality predicates
                guard first == second, first.tokens.isEmpty,
                      first.facts == attempt.currentFacts, first.bytes == attempt.currentBytes,
                      first.leaseNames == attempt.currentLeaseNames, first.ownerNames == attempt.ownerNames,
                      attempt.original < 0, attempt.temporary < 0, attempt.recordClosed,
                      attempt.recordUnlinked, attempt.replacementOutcome != nil,
                      attempt.replacementCompletion === replacementCompletion,
                      attempt.policyUncertainDescriptors.isEmpty,
                      attempt.uncertainCloseDescriptors.isEmpty else { throw Self.uncertainOwnerFailure() }
                for pin in attempt.readPins.values { try pin.requireCheckedClosed() }
                try attempt.io.requireSettled()
                try permit.retainReaderJournalFinalCensusesV4(attempt: attempt) // SAME actual still-held G before unlock
                try current()
                let digest = try attempt.io.postRetiredTree(parent: self.operationsDescriptor,
                    name: Self.leaseDirectoryName)
                try current()
                guard let rootFact = attempt.currentFacts["lease-root"] else { throw Self.identityFailure() }
                attempt.finalRegistryProjection = .directory(rootFact: rootFact, digest: digest)
            }
            // The scope returns only after a positive real G unlock. Failure
            // after this line still fences the owner; no receipt is reissued.
            attempt.checkedGReleased = true
            try reader.recordColdSchema2RetirementClosed(registry: self)
            allocation.closed = true
            attempt.completed = true
            let receipt = try ColdEraseSchema2ReaderRetirementReceiptV1(attempt: attempt)
            coldSchema2ReaderRetirementReceipt = receipt
            try permit.recordSettled(attempt: attempt, receipt: receipt)
            try permit.requireSettled(attempt: attempt, receipt: receipt)
            return receipt
        } catch {
            #if DEBUG
            print("COLD_SCHEMA2_READER_RETIREMENT_V1 stage=refused primitive=\(String(describing: attempt.activePrimitive)) result=\(String(describing: attempt.lastKernelResult))")
            #endif
            attempt.uncertain = true
            coldSchema2RetirementUncertain = true
            eraseSchema2ColdMutationUncertain = true
            allocation.schema2ColdUncertainClose = true
            permit.poisonOnUncertainEffect()
            operation.poisonColdScratchOwner()
            throw error
        }
    }
}


extension ColdEraseSchema2TerminalTargetObservationV1 {
    /// Pure retained association for namespace input DATA. Current EX and the
    /// full physical image are reproved by the actual preparation consumer.
    fileprivate func requireNamespaceBasisAssociation(owner expectedOwner: ColdEraseSchema2TerminalOwnerV1,
        operation expectedOperation: EraseColdPreparationOperationV1,
        manifest expectedManifest: EraseSchema2ColdManifestOwnerV1) throws {
        guard owner === expectedOwner, operation === expectedOperation,
              manifest === expectedManifest, let proof, let witness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expectedManifest.requireColdTerminalTargetObservationAssociation(self)
        try physical.requireBound(proof: proof, binding: binding, witness: witness)
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    func requireColdTerminalNamespaceBasis(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1)
        throws -> (notificationAfter: EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot,
                   firstObserver: EraseSchema2ColdAuxiliaryFirstObserverV1) {
        guard let observation = coldTerminalTargetObservation,
              let notificationAfter = coldScratchNotificationAfter,
              postGenerationProjection != nil else { throw StoreMigrationFailure.invalidIdentity }
        try observation.requireNamespaceBasisAssociation(owner: owner, operation: operation, manifest: self)
        let observer = try operation.requireColdPostContentFirstObserver(manifest: self, owner: owner)
        try observation.requireNamespaceBasisAssociation(owner: owner, operation: operation, manifest: self)
        return (notificationAfter, observer) // immutable retained DATA, no effect permit
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func requireColdSchema2ReaderRegistryProjection(
        receipt: ColdEraseSchema2ReaderRetirementReceiptV1,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1,
        expected: EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild,
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1)
        throws -> EraseSchema2ColdAuxiliaryFirstObserverV1.OperationsChild {
        try requireColdSchema2ReaderRetirementReceipt(receipt)
        try requireColdSchema2ReaderRetirementAttempt(attempt)
        guard attempt.completed, attempt.checkedGReleased,
              attempt.finalRegistryProjection == expected else { throw Self.uncertainOwnerFailure() }
        return try withColdSchema2RetirementG(operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness) {
            let before = try self.observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            guard before.tokens.isEmpty, before.facts == attempt.currentFacts,
                  before.bytes == attempt.currentBytes,
                  before.leaseNames == attempt.currentLeaseNames, before.ownerNames == attempt.ownerNames else {
                throw Self.identityFailure()
            }
            let digest = try self.coldSchema2RetirementIO.postRetiredTree(parent: self.operationsDescriptor,
                name: Self.leaseDirectoryName)
            let after = try self.observeColdSchema2RetirementCensusLocked(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            guard after == before, let fact = before.facts["lease-root"],
                  expected == .directory(rootFact: fact, digest: digest) else { throw Self.identityFailure() }
            try self.coldSchema2RetirementIO.requireSettled()
            return expected
        }
    }
}

/// A single real constructor entry, retained by the completed-startup owner
/// before provider/initialization IO. Deep hooks are nonisolated because the
/// sole synchronous Registry helper engine is nonisolated. The actor entry
/// installs this private frame; a thread is only a lifetime comparison and
/// never supplies constructor permission.
final class ColdEraseSchema2CompletedRegistryConstructorAttemptV1: @unchecked Sendable {
    fileprivate final class Frame {
        enum State: Equatable { case entered, returned, revoked, uncertain }
        fileprivate struct Storage {
            let thread: pthread_t
            var state: State = .entered
            var activeHelper: Helper?
        }
        private var storage: Storage
        var thread: pthread_t { storage.thread }
        var state: State { get { storage.state } set { storage.state = newValue } }
        var activeHelper: Helper? { get { storage.activeHelper } set { storage.activeHelper = newValue } }
        init() { storage = Storage(thread: pthread_self()) }
    }
    fileprivate enum Helper: Equatable {
        case initializationActivity, support, operations, lease, owners
        case mutationControl, ownerControl, directoryPolicy, filePolicy
        case generationMutation, ownershipTransfer
    }
    fileprivate struct Storage {
        let lock: NSRecursiveLock
        weak var owner: ColdEraseSchema2CompletedStartupOwnerV1?
        var factory: StoreGenerationFactory?
        let factoryProvenance: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1
        weak var factoryRetentionReceiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1?
        var retainedFactoryRetentionReceiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1?
        weak var inventory: EraseReaderRetirementInventoryV1?
        let applicationSupportURL: URL
        let firstSupport: EraseColdControlLeafFactV1
        let firstSupportNames: [String]
        let firstSupportProjectionV4: ColdEraseSchema2TerminalFinalSupportProjectionV4
        let firstSupportFlagsV4: UInt32
        var currentSupport: EraseColdControlLeafFactV1
        var currentSupportFlagsV4: UInt32
        var frame: Frame?
        var entered = false
        var positiveReturned = false
        var uncertain = false
        var activityResource: ColdEraseSchema2CompletedRegistryActivityResourceV1?
        weak var engineScope: ColdEraseSchema2CompletedRegistryEngineScopeV1?
        weak var transferredRegistry: GenerationLeaseRegistryV1?
    }
    private var storage: Storage
    private var lock: NSRecursiveLock { storage.lock }
    private var owner: ColdEraseSchema2CompletedStartupOwnerV1? { get { storage.owner } set { storage.owner = newValue } }
    private var factoryProvenance: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1 { storage.factoryProvenance }
    private var inventory: EraseReaderRetirementInventoryV1? { get { storage.inventory } set { storage.inventory = newValue } }
    var applicationSupportURL: URL { storage.applicationSupportURL }
    private var firstSupport: EraseColdControlLeafFactV1 { storage.firstSupport }
    private var firstSupportNames: [String] { storage.firstSupportNames }
    private var currentSupport: EraseColdControlLeafFactV1 { get { storage.currentSupport } set { storage.currentSupport = newValue } }
    private var firstSupportFlagsV4: UInt32 { storage.firstSupportFlagsV4 }
    private var currentSupportFlagsV4: UInt32 { get { storage.currentSupportFlagsV4 } set { storage.currentSupportFlagsV4 = newValue } }
    private var frame: Frame? { get { storage.frame } set { storage.frame = newValue } }
    private var entered: Bool { get { storage.entered } set { storage.entered = newValue } }
    private var positiveReturned: Bool { get { storage.positiveReturned } set { storage.positiveReturned = newValue } }
    private var uncertain: Bool { get { storage.uncertain } set { storage.uncertain = newValue } }
    private var activityResource: ColdEraseSchema2CompletedRegistryActivityResourceV1? { get { storage.activityResource } set { storage.activityResource = newValue } }
    private var transferredRegistry: GenerationLeaseRegistryV1? { get { storage.transferredRegistry } set { storage.transferredRegistry = newValue } }

    /// This is the actual declared storage of the three implemented carrier
    /// objects. It is a component accounting input, not the complete Registry
    /// constructor reservation or permission to enter that constructor.
    /// Activity/helper backing and their actual bounded path/result storage
    /// must be added by the genuine completed-owner reservation before entry.
    static func implementedCarrierBackingBytes() throws -> UInt64 {
        let own = UInt64(MemoryLayout<Storage>.stride)
        let frame = UInt64(MemoryLayout<Frame.Storage>.stride)
        let resource = try ColdEraseSchema2CompletedRegistryActivityResourceV1.implementedBackingBytes()
        let provenance = ColdEraseSchema2CompletedRegistryFactoryProvenanceV1.declaredBackingBytes()
        let pair = own.addingReportingOverflow(frame)
        let resourceTotal = pair.partialValue.addingReportingOverflow(resource)
        let total = resourceTotal.partialValue.addingReportingOverflow(provenance)
        guard !pair.overflow, !resourceTotal.overflow, !total.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return total.partialValue
        // Reference fields are accounted here; allocator/header/lock/VM
        // internals remain unmeasured. No whole-object or RSS claim is made.
    }

    @MainActor private init(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1) throws {
        let root = factory.restoreApplicationSupportURL
        guard root.isFileURL, root == root.standardizedFileURL,
              !root.path.utf8.contains(0), owner.readerInventory === inventory else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try owner.requireReaderConstructionFrame(factory: factory)
        // Both values must come from the actual final control-close producer,
        // not from a fresh Support stat or the old first/pre-content image.
        let supportProjectionV4 = try owner.requireConstructorSupportProjectionWithFlagsV4(factory: factory, inventory: inventory)
        let support = supportProjectionV4.fullFact
        let supportFlagsV4 = supportProjectionV4.flags
        let supportNames = try owner.requireConstructorSupportNames(factory: factory, inventory: inventory)
        guard supportNames == supportProjectionV4.names else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        guard support.mode & S_IFMT == S_IFDIR, support.links > 0,
              supportNames.count <= 9 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var previous: String?
        for name in supportNames {
            guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
                  !name.utf8.contains(0), name.utf8.count <= 255,
                  previous.map({ $0 < name }) ?? true else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            previous = name
        }
        guard !supportNames.contains("FieldEvidenceOperations"),
              !supportNames.contains("FieldEvidenceErase"),
              supportNames.contains("FieldEvidenceData") else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage = Storage(lock: NSRecursiveLock(), owner: owner,
            factory: factory, factoryProvenance: try factory.completedSchema2ConstructorFactoryProvenance(),
            inventory: inventory, applicationSupportURL: root,
            firstSupport: support, firstSupportNames: supportNames,
            firstSupportProjectionV4: supportProjectionV4, firstSupportFlagsV4: supportFlagsV4,
            currentSupport: support, currentSupportFlagsV4: supportFlagsV4)
    }

    @MainActor static func make(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1)
        throws -> ColdEraseSchema2CompletedRegistryConstructorAttemptV1 {
        try owner.requireReaderConstructionFrame(factory: factory)
        let value = try ColdEraseSchema2CompletedRegistryConstructorAttemptV1(
            owner: owner, factory: factory, inventory: inventory)
        try owner.retainRegistryConstructorAttempt(value, factory: factory, inventory: inventory)
        try value.requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
        return value
    }

    /// Pure owner/provider association. This method cannot enter the provider
    /// lock, request another Registry or read a closed terminal descriptor.
    @MainActor func requireOwnerFrame(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1) throws {
        try lock.withLock {
            guard !uncertain, self.owner === owner, self.inventory === inventory,
                  applicationSupportURL == factory.restoreApplicationSupportURL else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        try factoryProvenance.requireMatches(factory: factory)
        try owner.requireRegistryConstructorAttempt(self, factory: factory, inventory: inventory)
    }

    /// Only the actor-isolated, nonsuspending provider engine may invoke this
    /// once. The frame is revoked on every exit, and failed frames remain
    /// retained permanently with their actual resources/outcomes.
    @MainActor fileprivate func withConstructorFrame(
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1,
        _ body: @MainActor () throws -> GenerationLeaseRegistryV1)
        throws -> GenerationLeaseRegistryV1 {
        try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
        try lock.withLock {
            guard !entered, frame == nil, transferredRegistry == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            entered = true; frame = Frame()
        }
        defer {
            lock.withLock {
                if let frame, frame.state != .uncertain { frame.state = .revoked }
            }
        }
        do {
            let registry = try body()
            try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
            try requireTransferredRegistry(registry: registry, owner: owner,
                factory: factory, inventory: inventory)
            lock.withLock { positiveReturned = true; frame?.state = .returned }
            let resource = try lock.withLock {
                guard let activityResource else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                return activityResource
            }
            try resource.releaseConstructorCycleAfterPositiveTransfer(attempt: self, registry: registry)
            return registry
        } catch {
            poisonOnUncertainEffect()
            throw error
        }
    }

    @MainActor fileprivate func withHelper<Value>(_ helper: Helper,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1,
        _ body: @MainActor () throws -> Value) throws -> Value {
        try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
        try lock.withLock {
            let value = try requireEnteredFrame()
            guard value.activeHelper == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            value.activeHelper = helper
        }
        do {
            let value = try body()
            try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
            try lock.withLock {
                let frame = try requireEnteredFrame()
                guard frame.activeHelper == helper else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                frame.activeHelper = nil
            }
            return value
        } catch { poisonOnUncertainEffect(); throw error }
    }

    private func requireEnteredFrame() throws -> Frame {
        guard !uncertain, entered, let frame, frame.state == .entered,
              pthread_equal(frame.thread, pthread_self()) != 0,
              owner != nil, inventory != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return frame
    }

    fileprivate func makeInitializationActivityResource()
        throws -> ColdEraseSchema2CompletedRegistryActivityResourceV1 {
        try lock.withLock {
            let frame = try requireEnteredFrame()
            guard frame.activeHelper == .initializationActivity, activityResource == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let value = ColdEraseSchema2CompletedRegistryActivityResourceV1(
                attempt: self, frame: frame, applicationSupportURL: applicationSupportURL)
            activityResource = value // retained before the first open
            return value
        }
    }

    fileprivate func requireActivityFrame(_ resource: ColdEraseSchema2CompletedRegistryActivityResourceV1,
        frame expectedFrame: Frame) throws {
        try lock.withLock {
            let frame = try requireEnteredFrame()
            guard activityResource === resource, frame === expectedFrame,
                  frame.activeHelper != nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    /// The first value is the authentic completed-owner close projection.
    /// Future own constructor namespace changes must advance it only through
    /// their real retained primitive/resource completion; Activity cannot
    /// replace it merely because held and named views happen to agree.
    fileprivate func requireActivitySupportProjection(
        _ resource: ColdEraseSchema2CompletedRegistryActivityResourceV1,
        frame expectedFrame: Frame) throws -> EraseColdControlLeafFactV1 {
        try lock.withLock {
            let value = try requireEnteredFrame()
            guard activityResource === resource, value === expectedFrame,
                  value.activeHelper != nil,
                  currentSupport.device == firstSupport.device,
                  currentSupport.inode == firstSupport.inode,
                  currentSupport.mode == firstSupport.mode,
                  currentSupport.user == firstSupport.user,
                  currentSupport.group == firstSupport.group,
                  currentSupportFlagsV4 == firstSupportFlagsV4 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return currentSupport
        }
    }

    /// Actual incoming flags remain paired with the current full11 image.
    /// Only the real own constructor mkdir return may advance these cells.
    fileprivate func requireActivitySupportFlagsV4(
        _ resource: ColdEraseSchema2CompletedRegistryActivityResourceV1,
        frame expectedFrame: Frame) throws -> UInt32 {
        try lock.withLock {
            let value = try requireEnteredFrame()
            guard activityResource === resource, value === expectedFrame,
                  value.activeHelper != nil,
                  currentSupportFlagsV4 == firstSupportFlagsV4 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return currentSupportFlagsV4
        }
    }

    /// An actual Registry return can be recorded only by the sole engine,
    /// after all helper resources and the initialization activity positively
    /// settle. The engine must also join every transferred Registry FD.
    @MainActor fileprivate func recordTransferredRegistry(
        _ registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1) throws {
        try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
        let resource = try lock.withLock {
            let frame = try requireEnteredFrame()
            guard frame.activeHelper == .ownershipTransfer, transferredRegistry == nil,
                  let activityResource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return activityResource
        }
        // Never acquire the resource lock while holding the attempt lock;
        // deep hooks reprove the actual attempt under their resource lock.
        try resource.requirePositivePermanentClose()
        try registry.requireCompletedSchema2ConstructorResourceTransfer(self)
        try lock.withLock {
            let frame = try requireEnteredFrame()
            guard frame.activeHelper == .ownershipTransfer, transferredRegistry == nil,
                  activityResource === resource else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            transferredRegistry = registry
        }
    }

    @MainActor func requireTransferredRegistry(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1) throws {
        try requireOwnerFrame(owner: owner, factory: factory, inventory: inventory)
        let resource = try lock.withLock {
            guard entered, !uncertain, transferredRegistry === registry,
                  let frame, [.entered, .returned, .revoked].contains(frame.state),
                  let activityResource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return activityResource
        }
        try resource.requirePositivePermanentClose()
        try registry.requireCompletedSchema2ConstructorResourceTransfer(self)
        try lock.withLock {
            guard !uncertain, transferredRegistry === registry, activityResource === resource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    /// Positive permanent constructor result, distinct from the active
    /// owner/Router entry. A prepared startup must retain this same actual
    /// attempt before that entry ends. This checker performs no old owner
    /// callback, descriptor IO or provider lock acquisition.
    @MainActor func requireRetainedTransferredRegistry(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory, inventory: EraseReaderRetirementInventoryV1) throws {
        let resource = try lock.withLock {
            guard entered, positiveReturned, !uncertain, self.owner === owner,
                  self.inventory === inventory,
                  applicationSupportURL == factory.restoreApplicationSupportURL,
                  transferredRegistry === registry, let frame,
                  frame.state == .returned || frame.state == .revoked,
                  frame.activeHelper == nil, let activityResource else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return activityResource
        }
        try factoryProvenance.requireMatches(factory: factory)
        try resource.requirePositivePermanentClose()
        try registry.requireCompletedSchema2ConstructorResourceTransfer(self)
        try lock.withLock {
            guard positiveReturned, !uncertain, transferredRegistry === registry,
                  activityResource === resource, let frame,
                  frame.state == .returned || frame.state == .revoked else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    /// Pure permanent association after the actual sole constructor engine
    /// has joined all transferred Registry resources and its one returned
    /// initialization Activity. It is not an active entry/frame callback.
    fileprivate func requirePositiveTransferForActivityResource(
        _ resource: ColdEraseSchema2CompletedRegistryActivityResourceV1,
        registry: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard entered, positiveReturned, !uncertain,
                  owner != nil, inventory != nil,
                  activityResource === resource, transferredRegistry === registry,
                  let frame, frame.state == .returned || frame.state == .revoked,
                  frame.activeHelper == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    func poisonOnUncertainEffect() {
        lock.withLock { uncertain = true; frame?.state = .uncertain }
    }
}

/// The real Support SH acquisition belongs to the constructor carrier before
/// its first syscall. The Ledger's closed-origin implementation records each
/// actual return here before applying predicates; no failed integer is retried
/// or discharged by ordinary close/deinit.
final class ColdEraseSchema2CompletedRegistryActivityResourceV1: @unchecked Sendable {
    enum Primitive: Equatable {
        case supportOpen, supportHeldStat, supportNamedStat, sharedLock
        case supportRecheckHeld, supportRecheckNamed, sharedUnlock, supportClose
    }
    fileprivate struct Outcome {
        let primitive: Primitive
        let returned: Int64
        let savedErrno: Int32
        let information: stat?
    }
    fileprivate struct Storage {
        let lock: NSRecursiveLock
        weak var attempt: ColdEraseSchema2CompletedRegistryConstructorAttemptV1?
        var retainedAttempt: ColdEraseSchema2CompletedRegistryConstructorAttemptV1?
        let frame: ColdEraseSchema2CompletedRegistryConstructorAttemptV1.Frame
        let applicationSupportURL: URL
        var returnedActivity: OwnedStorageProducerActivityV1?
        var pending: Primitive?
        var lastOutcome: Outcome?
        var descriptorValue: Int32 = -1
        var firstHeld: stat?
        var currentHeld: stat?
        var sharedLockReturned: Int64?
        var sharedUnlockReturned: Int64?
        var closeReturned: Int64?
        var closeEntered = false
        var uncertain = false
        var positiveCycleReleased = false
    }
    private var storage: Storage
    private var lock: NSRecursiveLock { storage.lock }
    private var frame: ColdEraseSchema2CompletedRegistryConstructorAttemptV1.Frame { storage.frame }
    var applicationSupportURL: URL { storage.applicationSupportURL }
    private var returnedActivity: OwnedStorageProducerActivityV1? { get { storage.returnedActivity } set { storage.returnedActivity = newValue } }
    private var pending: Primitive? { get { storage.pending } set { storage.pending = newValue } }
    private var lastOutcome: Outcome? { get { storage.lastOutcome } set { storage.lastOutcome = newValue } }
    private var descriptorValue: Int32 { get { storage.descriptorValue } set { storage.descriptorValue = newValue } }
    private var firstHeld: stat? { get { storage.firstHeld } set { storage.firstHeld = newValue } }
    private var currentHeld: stat? { get { storage.currentHeld } set { storage.currentHeld = newValue } }
    private var sharedLockReturned: Int64? { get { storage.sharedLockReturned } set { storage.sharedLockReturned = newValue } }
    private var sharedUnlockReturned: Int64? { get { storage.sharedUnlockReturned } set { storage.sharedUnlockReturned = newValue } }
    private var closeReturned: Int64? { get { storage.closeReturned } set { storage.closeReturned = newValue } }
    private var closeEntered: Bool { get { storage.closeEntered } set { storage.closeEntered = newValue } }
    private var uncertain: Bool { get { storage.uncertain } set { storage.uncertain = newValue } }
    var descriptor: Int32 { lock.withLock { descriptorValue } }

    fileprivate static func implementedBackingBytes() throws -> UInt64 {
        let stored = UInt64(MemoryLayout<Storage>.stride)
        let rawCapture = UInt64(MemoryLayout<Outcome>.stride)
        let total = stored.addingReportingOverflow(rawCapture)
        guard !total.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return total.partialValue
    }

    fileprivate init(attempt: ColdEraseSchema2CompletedRegistryConstructorAttemptV1,
        frame: ColdEraseSchema2CompletedRegistryConstructorAttemptV1.Frame,
        applicationSupportURL: URL) {
        storage = Storage(lock: NSRecursiveLock(), attempt: attempt,
            retainedAttempt: attempt, frame: frame, applicationSupportURL: applicationSupportURL)
    }

    private func actualAttempt() throws -> ColdEraseSchema2CompletedRegistryConstructorAttemptV1 {
        guard let attempt = storage.attempt,
              (storage.positiveCycleReleased
                ? storage.retainedAttempt == nil
                : storage.retainedAttempt === attempt) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return attempt
    }

    func requireCurrentFrame() throws {
        try lock.withLock {
            guard !uncertain, pending == nil, closeReturned == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try actualAttempt().requireActivityFrame(self, frame: frame)
        }
    }

    func enter(_ primitive: Primitive) throws {
        try lock.withLock {
            try requireCurrentFrame()
            switch primitive {
            case .supportOpen:
                guard descriptorValue < 0, lastOutcome == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            case .supportHeldStat:
                guard descriptorValue >= 0, firstHeld == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            case .supportNamedStat:
                guard firstHeld != nil, sharedLockReturned == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            case .sharedLock:
                guard lastOutcome?.primitive == .supportNamedStat,
                      sharedLockReturned == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            case .supportRecheckHeld, .supportRecheckNamed:
                guard sharedLockReturned == 0, sharedUnlockReturned == nil else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                if primitive == .supportRecheckNamed {
                    guard lastOutcome?.primitive == .supportRecheckHeld else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                }
            case .sharedUnlock:
                guard returnedActivity != nil, sharedLockReturned == 0,
                      sharedUnlockReturned == nil, !closeEntered else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            case .supportClose:
                guard sharedUnlockReturned == 0, !closeEntered else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                closeEntered = true // permanent before the actual close
            }
            pending = primitive // retained before IO
        }
    }

    func record(_ primitive: Primitive, returned: Int64, savedErrno: Int32,
        information: stat? = nil) throws {
        try lock.withLock {
            // Raw capture precedes every possibly throwing frame/predicate
            // check, including a failure that occurred inside the helper.
            lastOutcome = Outcome(primitive: primitive, returned: returned,
                savedErrno: savedErrno, information: information)
            if primitive == .supportOpen, returned >= 0,
               let actualDescriptor = Int32(exactly: returned) { descriptorValue = actualDescriptor }
            if primitive == .sharedLock { sharedLockReturned = returned }
            if primitive == .sharedUnlock { sharedUnlockReturned = returned }
            if primitive == .supportClose { closeReturned = returned }
            do {
                guard pending == primitive else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                pending = nil
                let attempt = try actualAttempt()
                try attempt.requireActivityFrame(self, frame: frame)
                guard (primitive == .supportOpen
                        ? returned >= 0 && Int32(exactly: returned) != nil : returned == 0) else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                switch primitive {
                case .supportHeldStat:
                    guard let information, information.st_mode & S_IFMT == S_IFDIR,
                          information.st_nlink > 0,
                          information.st_flags == (try attempt.requireActivitySupportFlagsV4(self, frame: frame)),
                          EraseColdControlLeafFactV1(information) == (try attempt.requireActivitySupportProjection(self, frame: frame)) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    firstHeld = information; currentHeld = information
                case .supportNamedStat, .supportRecheckNamed:
                    guard let information, let currentHeld,
                          Self.sameFull(information, currentHeld) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                case .supportRecheckHeld:
                    guard let information, let firstHeld,
                          information.st_dev == firstHeld.st_dev,
                          information.st_ino == firstHeld.st_ino,
                          information.st_mode == firstHeld.st_mode,
                          information.st_flags == firstHeld.st_flags,
                          information.st_uid == firstHeld.st_uid,
                          information.st_gid == firstHeld.st_gid,
                          information.st_mode & S_IFMT == S_IFDIR,
                          information.st_nlink > 0,
                          information.st_flags == (try attempt.requireActivitySupportFlagsV4(self, frame: frame)),
                          EraseColdControlLeafFactV1(information) == (try attempt.requireActivitySupportProjection(self, frame: frame)) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    currentHeld = information
                case .supportClose:
                    descriptorValue = -1
                default: break
                }
            } catch {
                uncertain = true; storage.attempt?.poisonOnUncertainEffect(); throw error
            }
        }
    }

    func registerReturnedActivity(_ activity: OwnedStorageProducerActivityV1) throws {
        try lock.withLock {
            do {
                guard returnedActivity == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                returnedActivity = activity // before any returned-object postcondition can throw
                try requireCurrentFrame()
                guard sharedLockReturned == 0, lastOutcome?.primitive == .supportRecheckNamed,
                      descriptorValue >= 0, activity.applicationSupportURL == applicationSupportURL else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            } catch {
                uncertain = true; storage.attempt?.poisonOnUncertainEffect(); throw error
            }
        }
    }

    func poisonOnUncertainEffect() {
        lock.withLock { uncertain = true; storage.attempt?.poisonOnUncertainEffect() }
    }

    func requireAcquired(activity: OwnedStorageProducerActivityV1) throws {
        try lock.withLock {
            try requireCurrentFrame()
            guard returnedActivity === activity, descriptorValue >= 0,
                  sharedLockReturned == 0, sharedUnlockReturned == nil, !closeEntered else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    func requireCheckedClosed(activity: OwnedStorageProducerActivityV1) throws {
        try lock.withLock {
            guard returnedActivity === activity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requirePositivePermanentClose()
        }
    }

    fileprivate func requirePositivePermanentClose() throws {
        try lock.withLock {
            guard !uncertain, pending == nil, closeEntered, descriptorValue == -1,
                  sharedLockReturned == 0, sharedUnlockReturned == 0, closeReturned == 0,
                  returnedActivity != nil, lastOutcome?.primitive == .supportClose else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    /// The reverse strong edge is removed only after actual transferred
    /// Registry/resource settlement and the permanent checked Activity close.
    /// Uncertainty keeps it strong. Returned Activity evidence remains owned
    /// by this same carrier; no FD is read, reopened or closed here.
    fileprivate func releaseConstructorCycleAfterPositiveTransfer(
        attempt: ColdEraseSchema2CompletedRegistryConstructorAttemptV1,
        registry: GenerationLeaseRegistryV1) throws {
        try lock.withLock {
            guard !storage.positiveCycleReleased,
                  storage.attempt === attempt, storage.retainedAttempt === attempt else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try requirePositivePermanentClose()
            try attempt.requirePositiveTransferForActivityResource(self, registry: registry)
            storage.positiveCycleReleased = true
            storage.retainedAttempt = nil
        }
    }

    private static func sameFull(_ first: stat, _ second: stat) -> Bool {
        let identity = first.st_dev == second.st_dev && first.st_ino == second.st_ino
            && first.st_mode == second.st_mode && first.st_flags == second.st_flags
        let ownership = first.st_uid == second.st_uid && first.st_gid == second.st_gid
            && first.st_nlink == second.st_nlink && first.st_size == second.st_size
        let modified = first.st_mtimespec.tv_sec == second.st_mtimespec.tv_sec
            && first.st_mtimespec.tv_nsec == second.st_mtimespec.tv_nsec
        let changed = first.st_ctimespec.tv_sec == second.st_ctimespec.tv_sec
            && first.st_ctimespec.tv_nsec == second.st_ctimespec.tv_nsec
        return identity && ownership && modified && changed
    }
}


/// Private final namespace projection of the actual still-held Registry
/// resources. Only the same completed namespace kernel may retain this DATA;
/// named absence or a caller stat cannot manufacture a close receipt.
fileprivate struct ColdEraseSchema2NamespaceRegistryResourcesV1 {
    let support: EraseColdControlLeafFactV1
    let operations: EraseColdControlLeafFactV1
    let lease: EraseColdControlLeafFactV1
    let owners: EraseColdControlLeafFactV1
    let mutation: EraseColdControlLeafFactV1
    let ownerLock: EraseColdControlLeafFactV1
    let supportFlags: UInt32
    let operationsFlags: UInt32
    let leaseFlags: UInt32
    let ownersFlags: UInt32
    let mutationFlags: UInt32
    let ownerLockFlags: UInt32
}

@MainActor
final class ColdEraseSchema2RegistryControlCloseAttemptV1 {
    fileprivate struct Observation {
        var entered = false
        var returned: Int32?
        var savedErrno: Int32?
        var fact: EraseColdControlLeafFactV1?
        var flags: UInt32?
    }
    fileprivate struct Slot {
        let descriptor: Int32
        let expected: EraseColdControlLeafFactV1
        let expectedFlags: UInt32
        var observedFlags: UInt32?
        var statEntered = false
        var statReturned: Int32?
        var statErrno: Int32?
        var observed: EraseColdControlLeafFactV1?
        var closeEntered = false
        var closeReturned: Int32?
        var closeErrno: Int32?
    }
    fileprivate struct Storage {
        weak var owner: ColdEraseSchema2TerminalOwnerV1?
        weak var registry: GenerationLeaseRegistryV1?
        weak var activity: GenerationTemporalActivityHandleV1?
        weak var operation: EraseColdPreparationOperationV1?
        weak var exclusion: EraseRetirementExclusionV1?
        weak var witness: EraseSessionDrainWitnessV1?
        let binding: EraseRetirementBindingV1
        let namespace: ColdEraseSchema2NamespaceRemovalReceiptV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let activityDescriptor: Int32
        let activityFact: EraseColdControlLeafFactV1
        let activityFlags: UInt32
        var support: Slot
        var operations: Slot
        var lease: Slot
        var owners: Slot
        var mutation: Slot
        var ownerLock: Slot
        var ownerUnlockEntered = false
        var ownerUnlockReturned: Int32?
        var ownerUnlockErrno: Int32?
        var activityBefore = Observation()
        var supportNamedBefore = Observation()
        var operationsAbsentBefore = Observation()
        var supportHeldAfter = Observation()
        var supportNamedAfter = Observation()
        var activityAfter = Observation()
        var operationsAbsentAfter = Observation()
        var checked = false
        var uncertain = false
        var uncertainOwner: ColdEraseSchema2TerminalOwnerV1?
        var receipt: ColdEraseSchema2RegistryControlCloseReceiptV1?
    }
    fileprivate var storage: Storage

    fileprivate init(owner: ColdEraseSchema2TerminalOwnerV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        registry: GenerationLeaseRegistryV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        activityDescriptor: Int32, resources: ColdEraseSchema2NamespaceRegistryResourcesV1,
        support: Int32, operations: Int32, lease: Int32, owners: Int32,
        mutation: Int32, ownerLock: Int32) {
        storage = Storage(owner: owner, registry: registry, activity: activity,
            operation: operation, exclusion: exclusion, witness: witness,
            binding: binding, namespace: namespace, capture: capture,
            activityDescriptor: activityDescriptor, activityFact: resources.lease, activityFlags: resources.leaseFlags,
            support: Slot(descriptor: support, expected: resources.support, expectedFlags: resources.supportFlags),
            operations: Slot(descriptor: operations, expected: resources.operations, expectedFlags: resources.operationsFlags),
            lease: Slot(descriptor: lease, expected: resources.lease, expectedFlags: resources.leaseFlags),
            owners: Slot(descriptor: owners, expected: resources.owners, expectedFlags: resources.ownersFlags),
            mutation: Slot(descriptor: mutation, expected: resources.mutation, expectedFlags: resources.mutationFlags),
            ownerLock: Slot(descriptor: ownerLock, expected: resources.ownerLock, expectedFlags: resources.ownerLockFlags))
    }

    fileprivate func requireAssociation(owner: ColdEraseSchema2TerminalOwnerV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1,
        registry: GenerationLeaseRegistryV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        guard !storage.uncertain, storage.owner === owner,
              storage.namespace === namespace, storage.registry === registry,
              storage.operation === operation, storage.activity === activity,
              storage.exclusion === exclusion, storage.binding == binding,
              storage.witness === witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try registry.requireColdSchema2RegistryCloseAttempt(self)
    }

    fileprivate func poison() {
        storage.uncertain = true
        if let owner = storage.owner { storage.uncertainOwner = owner; owner.poisonOnUncertainEffect() }
    }

    /// Save the entered primitive and raw result before every predicate.
    /// Each slot is checked exactly once; failure cannot enter cleanup.
    fileprivate static func check(_ slot: inout Slot, directory: Bool, unlinked: Bool) throws {
        guard !slot.statEntered, !slot.closeEntered, slot.descriptor >= 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        slot.statEntered = true
        var held = stat()
        let returned = Darwin.fstat(slot.descriptor, &held), savedErrno = errno
        slot.statReturned = returned; slot.statErrno = savedErrno
        slot.observed = EraseColdControlLeafFactV1(held); slot.observedFlags = held.st_flags
        guard returned == 0, slot.observed == slot.expected, slot.observedFlags == slot.expectedFlags,
              held.st_mode & S_IFMT == (directory ? S_IFDIR : S_IFREG),
              held.st_nlink == (unlinked ? 0 : slot.expected.links) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    fileprivate static func close(_ slot: inout Slot) throws {
        guard slot.statReturned == 0, slot.observed == slot.expected, slot.observedFlags == slot.expectedFlags,
              !slot.closeEntered, slot.closeReturned == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        slot.closeEntered = true // permanent before the sole real close
        let returned = Darwin.close(slot.descriptor), savedErrno = errno
        slot.closeReturned = returned; slot.closeErrno = savedErrno
        guard returned == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }

    fileprivate static func observeHeld(_ descriptor: Int32, into observation: inout Observation) throws {
        guard !observation.entered, descriptor >= 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        observation.entered = true
        var information = stat()
        let returned = Darwin.fstat(descriptor, &information), savedErrno = errno
        observation.returned = returned; observation.savedErrno = savedErrno
        observation.fact = EraseColdControlLeafFactV1(information); observation.flags = information.st_flags
    }

    fileprivate static func observeSupport(_ url: URL, into observation: inout Observation) throws {
        guard !observation.entered else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        observation.entered = true
        var information = stat()
        let returned = Darwin.lstat(url.path, &information), savedErrno = errno
        observation.returned = returned; observation.savedErrno = savedErrno
        observation.fact = EraseColdControlLeafFactV1(information); observation.flags = information.st_flags
    }

    fileprivate static func observeOperationsAbsence(_ support: Int32, into observation: inout Observation) throws {
        guard !observation.entered, support >= 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        observation.entered = true
        var information = stat()
        let returned = Darwin.fstatat(support, "FieldEvidenceOperations", &information, AT_SYMLINK_NOFOLLOW)
        let savedErrno = errno
        observation.returned = returned; observation.savedErrno = savedErrno
        observation.fact = EraseColdControlLeafFactV1(information)
    }

    fileprivate func requireCheckedResult() throws {
        func closed(_ slot: Slot) -> Bool {
            slot.statEntered && slot.statReturned == 0 && slot.observed == slot.expected
                && slot.observedFlags == slot.expectedFlags && slot.closeEntered && slot.closeReturned == 0
        }
        guard storage.checked, !storage.uncertain, storage.uncertainOwner == nil,
              storage.ownerUnlockEntered, storage.ownerUnlockReturned == 0,
              storage.activityBefore.returned == 0, storage.activityBefore.fact == storage.activityFact,
              storage.supportNamedBefore.returned == 0, storage.supportNamedBefore.fact == storage.support.expected,
              storage.operationsAbsentBefore.returned == -1, storage.operationsAbsentBefore.savedErrno == ENOENT,
              storage.supportHeldAfter.returned == 0, storage.supportHeldAfter.fact == storage.support.expected,
              storage.supportNamedAfter.returned == 0, storage.supportNamedAfter.fact == storage.support.expected,
              storage.activityAfter.returned == 0, storage.activityAfter.fact == storage.activityFact,
              storage.activityBefore.flags == storage.activityFlags, storage.activityAfter.flags == storage.activityFlags,
              storage.supportNamedBefore.flags == storage.support.expectedFlags,
              storage.supportHeldAfter.flags == storage.support.expectedFlags,
              storage.supportNamedAfter.flags == storage.support.expectedFlags,
              storage.operationsAbsentAfter.returned == -1, storage.operationsAbsentAfter.savedErrno == ENOENT,
              closed(storage.ownerLock), closed(storage.mutation), closed(storage.owners),
              closed(storage.lease), closed(storage.operations), closed(storage.support) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

/// Real checked-control closure under the same retained namespace/EX graph.
/// It grants neither activity unlock nor EX release by itself.
@MainActor
final class ColdEraseSchema2RegistryControlCloseReceiptV1 {
    fileprivate struct Storage {
        let attempt: ColdEraseSchema2RegistryControlCloseAttemptV1
        weak var owner: ColdEraseSchema2TerminalOwnerV1?
        weak var registry: GenerationLeaseRegistryV1?
        weak var activity: GenerationTemporalActivityHandleV1?
        weak var exclusion: EraseRetirementExclusionV1?
        weak var witness: EraseSessionDrainWitnessV1?
        let binding: EraseRetirementBindingV1
        let namespace: ColdEraseSchema2NamespaceRemovalReceiptV1
    }
    private let storage: Storage
    fileprivate init(attempt: ColdEraseSchema2RegistryControlCloseAttemptV1,
        owner: ColdEraseSchema2TerminalOwnerV1, registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1) {
        storage = Storage(attempt: attempt, owner: owner, registry: registry,
            activity: activity, exclusion: exclusion, witness: witness,
            binding: binding, namespace: namespace)
    }

    func requireBound(owner: ColdEraseSchema2TerminalOwnerV1,
        registry: GenerationLeaseRegistryV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1, namespace: ColdEraseSchema2NamespaceRemovalReceiptV1) throws {
        guard storage.owner === owner, storage.registry === registry,
              storage.activity === activity, storage.exclusion === exclusion,
              storage.binding == binding, storage.witness === witness,
              storage.namespace === namespace,
              storage.attempt.storage.receipt === self else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.attempt.requireCheckedResult()
        try registry.requireColdSchema2RegistryCloseReceipt(self, attempt: storage.attempt)
    }

    fileprivate func requireActivityResource(activity: GenerationTemporalActivityHandleV1,
        registry: GenerationLeaseRegistryV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1)
        throws -> EraseColdControlLeafFactV1 {
        guard let owner = storage.owner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireBound(owner: owner, registry: registry, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness, namespace: storage.namespace)
        try activity.requireColdSchema2RegistryCloseAttempt(storage.attempt, registry: registry)
        let actual = try activity.coldSchema2DescriptorForRegistryClose(registry: registry)
        guard actual == storage.attempt.storage.activityDescriptor,
              storage.attempt.storage.activityFact == storage.attempt.storage.lease.expected,
              storage.attempt.storage.activityFact.links == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return storage.attempt.storage.activityFact
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func requireColdSchema2RegistryCloseAttempt(
        _ attempt: ColdEraseSchema2RegistryControlCloseAttemptV1) throws {
        guard coldSchema2NamespaceCloseAttempt === attempt, isEraseSchema2ColdOwner,
              !coldSchema2RetirementUncertain, !eraseSchema2ColdMutationUncertain else {
            throw Self.uncertainOwnerFailure()
        }
    }

    @MainActor fileprivate func requireColdSchema2RegistryCloseReceipt(
        _ receipt: ColdEraseSchema2RegistryControlCloseReceiptV1,
        attempt: ColdEraseSchema2RegistryControlCloseAttemptV1) throws {
        try requireColdSchema2RegistryCloseAttempt(attempt)
        guard coldSchema2NamespaceCloseReceipt === receipt else { throw Self.uncertainOwnerFailure() }
    }

    @MainActor
    func closeColdSchema2NamespaceResources(owner: ColdEraseSchema2TerminalOwnerV1,
        namespace: ColdEraseSchema2NamespaceRemovalReceiptV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2RegistryControlCloseReceiptV1 {
        try owner.requireBeforeRegistryClose(registry: self, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness, namespace: namespace)
        guard isEraseSchema2ColdOwner, !coldSchema2RetirementUncertain,
              !eraseSchema2ColdMutationUncertain, coldSchema2NamespaceCloseAttempt == nil,
              coldSchema2NamespaceCloseReceipt == nil, let capture = coldSchema2NamespaceCapture else {
            throw Self.uncertainOwnerFailure()
        }
        // Pure private settled namespace DATA; no IO/absence-based issuer.
        let resources = try namespace.requireRegistryResourcesBeforeClose(owner: owner,
            operation: operation, registry: self, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness)
        let activityDescriptor = try activity.coldSchema2DescriptorForRegistryClose(registry: self)
        let attempt = ColdEraseSchema2RegistryControlCloseAttemptV1(owner: owner,
            namespace: namespace, capture: capture, registry: self, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness,
            activityDescriptor: activityDescriptor, resources: resources,
            support: rootDescriptor, operations: operationsDescriptor, lease: leaseDescriptor,
            owners: ownersDescriptor, mutation: mutationLockDescriptor, ownerLock: ownerLockDescriptor)
        coldSchema2NamespaceCloseAttempt = attempt // fences ordinary IO/deinit BEFORE IO
        do {
            try capture.retainRegistryCloseAttempt(attempt, namespace: namespace)
            try activity.retainColdSchema2RegistryCloseAttempt(attempt, registry: self)
            try attempt.requireAssociation(owner: owner, namespace: namespace, registry: self,
                operation: operation, activity: activity, exclusion: exclusion,
                binding: binding, witness: witness)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.support, directory: true, unlinked: false)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.operations, directory: true, unlinked: true)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.lease, directory: true, unlinked: true)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.owners, directory: true, unlinked: true)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.mutation, directory: false, unlinked: true)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.check(&attempt.storage.ownerLock, directory: false, unlinked: true)
            // The genuine lease-root EX descriptor is still open and retained
            // by its Activity. This does not unlock or close it here.
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeHeld(activityDescriptor, into: &attempt.storage.activityBefore)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeSupport(applicationSupportURL, into: &attempt.storage.supportNamedBefore)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeOperationsAbsence(rootDescriptor, into: &attempt.storage.operationsAbsentBefore)
            guard attempt.storage.activityBefore.returned == 0, attempt.storage.activityBefore.fact == resources.lease,
                  attempt.storage.supportNamedBefore.returned == 0, attempt.storage.supportNamedBefore.fact == resources.support,
                  attempt.storage.operationsAbsentBefore.returned == -1,
                  attempt.storage.operationsAbsentBefore.savedErrno == ENOENT,
                  attempt.storage.activityBefore.flags == resources.leaseFlags,
                  attempt.storage.supportNamedBefore.flags == resources.supportFlags else {
                throw Self.uncertainOwnerFailure()
            }
            try exclusion.requireSupport(binding: binding)
            try operation.requireColdTerminalEffectFrame(owner)
            attempt.storage.ownerUnlockEntered = true
            let unlocked = flock(ownerLockDescriptor, LOCK_UN), unlockErrno = errno
            attempt.storage.ownerUnlockReturned = unlocked; attempt.storage.ownerUnlockErrno = unlockErrno
            guard unlocked == 0 else { throw Self.uncertainOwnerFailure() }
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.ownerLock)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.mutation)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.owners)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.lease)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.operations)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeHeld(rootDescriptor, into: &attempt.storage.supportHeldAfter)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeSupport(applicationSupportURL, into: &attempt.storage.supportNamedAfter)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeHeld(activityDescriptor, into: &attempt.storage.activityAfter)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.observeOperationsAbsence(rootDescriptor, into: &attempt.storage.operationsAbsentAfter)
            guard attempt.storage.supportHeldAfter.returned == 0, attempt.storage.supportHeldAfter.fact == resources.support,
                  attempt.storage.supportNamedAfter.returned == 0, attempt.storage.supportNamedAfter.fact == resources.support,
                  attempt.storage.activityAfter.returned == 0, attempt.storage.activityAfter.fact == resources.lease,
                  attempt.storage.operationsAbsentAfter.returned == -1,
                  attempt.storage.operationsAbsentAfter.savedErrno == ENOENT,
                  attempt.storage.supportHeldAfter.flags == resources.supportFlags,
                  attempt.storage.supportNamedAfter.flags == resources.supportFlags,
                  attempt.storage.activityAfter.flags == resources.leaseFlags else {
                throw Self.uncertainOwnerFailure()
            }
            try exclusion.requireSupport(binding: binding)
            try operation.requireColdTerminalEffectFrame(owner)
            try ColdEraseSchema2RegistryControlCloseAttemptV1.close(&attempt.storage.support)
            attempt.storage.checked = true
            try attempt.requireCheckedResult()
            let receipt = ColdEraseSchema2RegistryControlCloseReceiptV1(attempt: attempt,
                owner: owner, registry: self, activity: activity, exclusion: exclusion,
                binding: binding, witness: witness, namespace: namespace)
            attempt.storage.receipt = receipt; coldSchema2NamespaceCloseReceipt = receipt
            try capture.retainRegistryCloseReceipt(receipt, attempt: attempt, namespace: namespace)
            try receipt.requireBound(owner: owner, registry: self, activity: activity,
                exclusion: exclusion, binding: binding, witness: witness, namespace: namespace)
            return receipt // Main records its identical receipt exactly once
        } catch {
            coldSchema2RetirementUncertain = true
            attempt.poison(); capture.poisonOnUncertainEffect()
            throw error
        }
    }
}

// BIRTH_OPERATIONS_ROOT_SOURCE_V1_BEGIN
// A registered BIRTH read owner, never a Seed, Namespace Preparation or effect
// permit. Native must privately reserve/retain this exact Capture before entry.
@MainActor
final class ColdEraseScratchBirthImageCaptureV1 {
    fileprivate enum State: Equatable { case registered, preparing, prepared, scanning, rootCompared, uncertain }
    fileprivate enum RootPrimitive: Equatable { case held, named }
    fileprivate struct Storage {
        let reservation: ColdEraseScratchBirthImageReservationV1
        let operation: EraseColdPreparationOperationV1
        let scope: ColdEraseScratchCleanupHeldGScopeV1
        var state: State = .registered
        var root: ColdEraseScratchBirthOperationsRootV1?
        var rootEntry: RootPrimitive?
        var rootEntered = false
        var rootConsumed = true
        var rootReturned: Int32?
        var rootErrno: Int32?
        var rootStat: stat?
        var rootRendered: String?
        var membershipEntry = false
        var membership: UnsafeMutablePointer<UInt8>?
        var membershipCapacity = 0
        var membershipInitialized = 0
        var membershipBytesPerPass = 0
        var first: ColdEraseScratchBirthImageReadNodeV1?
        var second: ColdEraseScratchBirthImageReadNodeV1?
    }
    fileprivate var storage: Storage

    private init(reservation: ColdEraseScratchBirthImageReservationV1,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) {
        storage = Storage(reservation: reservation, operation: operation, scope: scope)
    }

    /// Actual stored operands only. Native additionally precharges its authentic
    /// names/root DTO and exact TWO bitmaps before this constructor. All shared
    /// root/cursor/storage and raw capacity remain charged for Capture lifetime;
    /// this component provides no final whole-image/cycle/metadata release.
    static func requiredBackingBytes() throws -> UInt64 {
        var total = UInt64(MemoryLayout<Storage>.stride)
        func add(_ bytes: UInt64) throws {
            let next = total.addingReportingOverflow(bytes)
            guard !next.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            total = next.partialValue
        }
        let cursors = UInt64(MemoryLayout<ColdEraseScratchBirthImageReadNodeV1.Storage>.stride)
            .multipliedReportingOverflow(by: 2)
        guard !cursors.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try add(cursors.partialValue)
        // Actual lexical Capture and first/second ReadNode reference cells.
        try add(UInt64(MemoryLayout<ColdEraseScratchBirthImageCaptureV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthImageReadNodeV1>.stride))
        // Source full11 renders: max241 UTF8 each; retained current dirent name:
        // max255 UTF8 each: closed first name plus second old/new assignment
        // overlap. Local stat/dirent/value cells overlap stored cells.
        try add(UInt64(3 * 241 + 3 * 255))
        try add(UInt64(3 * MemoryLayout<stat>.stride + MemoryLayout<dirent>.stride
            + 3 * MemoryLayout<String>.stride + 3 * MemoryLayout<String.UTF8View>.stride
            + 3 * MemoryLayout<ColdEraseScratchBirthOperationsRootV1>.stride
            + MemoryLayout<UnsafeRawBufferPointer>.stride
            + MemoryLayout<UnsafeRawBufferPointer.SubSequence>.stride))
        return total // class/allocator/URL/Foundation/header/VM/RSS not measured
    }

    /// Memory-only Native callback. No getter/scan/FD/PFP/current callback.
    func requireReservationAssociation(reservation: ColdEraseScratchBirthImageReservationV1) throws {
        guard storage.reservation === reservation, storage.state != .uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    static func compareOperationsRoot(reservation: ColdEraseScratchBirthImageReservationV1,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws -> ColdEraseScratchBirthImageCaptureV1 {
        try reservation.requireReservedCaptureFrame(operation: operation, scope: scope)
        let capture = ColdEraseScratchBirthImageCaptureV1(reservation: reservation,
            operation: operation, scope: scope)
        do {
            try reservation.bindCapture(capture) // same owner retained BEFORE postproof/IO
            try capture.prepareRoot()
            capture.storage.state = .scanning
            let first = ColdEraseScratchBirthImageReadNodeV1(capture: capture, pass: 0)
            capture.storage.first = first // BEFORE open/fdopendir/stat/readdir
            try first.compareAndClose()
            let second = ColdEraseScratchBirthImageReadNodeV1(capture: capture, pass: 1)
            capture.storage.second = second // BEFORE independent second cursor
            try second.compareAndClose()
            try capture.requireRootCurrent()
            try first.requireCheckedResult(); try second.requireCheckedResult()
            capture.storage.state = .rootCompared
            try capture.requireCheckedOperationsRootComparison()
            return capture // ROOT COMPARISON ONLY; no complete Image/Receipt/Seed
        } catch { capture.poison(); throw error }
    }

    private func prepareRoot() throws {
        guard storage.state == .registered, storage.root == nil, !storage.membershipEntry,
              storage.first == nil, storage.second == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.state = .preparing // once entry before root getter/allocation
        try frame()
        let root = try storage.reservation.requireOperationsRoot(capture: self)
        storage.root = root // actual returned Source/root/loan BEFORE any postproof
        guard root.operationID == storage.scope.operationID,
              root.operationID == storage.operation.retainedColdOperationIDForComparison,
              root.fullFact.utf8.count <= 241 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for position in root.names.indices {
            let name = root.names[position]
            guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
                  !name.utf8.contains(0), name.utf8.count <= 255,
                  position == root.names.startIndex || root.names[position - 1] < name else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        let bits = root.names.count.addingReportingOverflow(7)
        guard !bits.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let each = bits.partialValue / 8
        let both = each.multipliedReportingOverflow(by: 2)
        guard !both.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.membershipEntry = true // before genuine closed Native reservation
        let bytes = try storage.reservation.reserveOperationsRootMembership(capture: self)
        guard bytes == both.partialValue, bytes >= 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.membershipBytesPerPass = each
        if bytes > 0 {
            let raw = UnsafeMutablePointer<UInt8>.allocate(capacity: bytes)
            storage.membership = raw // retain actual raw allocation BEFORE callbacks
            storage.membershipCapacity = bytes
            raw.initialize(repeating: 0, count: bytes)
            storage.membershipInitialized = bytes
        }
        // Zero-name membership has explicit once-entry/allocation/initialization
        // evidence, not a missing-pointer success. Both actual EOF cursors run.
        try storage.reservation.recordOperationsRootMembershipAllocation(capture: self)
        try requireRootCurrent()
        storage.state = .prepared
    }

    /// Pure exact allocation callback; absent pointer is admissible only for the
    /// authentic zero-byte prepaid membership and explicit same once-entry.
    func requireOperationsRootMembershipAllocation(
        reservation: ColdEraseScratchBirthImageReservationV1, byteCount: Int) throws {
        try requireReservationAssociation(reservation: reservation)
        guard storage.membershipEntry, storage.root != nil, byteCount >= 0,
              storage.membershipCapacity == byteCount,
              storage.membershipInitialized == byteCount,
              (byteCount == 0) == (storage.membership == nil),
              storage.membershipBytesPerPass <= Int.max / 2,
              storage.membershipBytesPerPass * 2 == byteCount else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    fileprivate func frame() throws {
        guard storage.state != .uncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.reservation.requireCaptureFrame(capture: self)
    }

    fileprivate func root() throws -> ColdEraseScratchBirthOperationsRootV1 {
        guard let root = storage.root else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return root // shared authentic Native-owned DATA backing remains charged
    }

    fileprivate static func full(_ value: stat) -> String {
        "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_uid)|\(value.st_gid)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
    }

    private func enterRoot(_ primitive: RootPrimitive) throws {
        try frame()
        guard storage.rootConsumed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.rootEntry = primitive; storage.rootEntered = true; storage.rootConsumed = false
        storage.rootReturned = nil; storage.rootErrno = nil; storage.rootStat = nil; storage.rootRendered = nil
    }
    private func recordRoot(_ result: Int32, saved: Int32, information: stat) {
        storage.rootReturned = result; storage.rootErrno = saved; storage.rootStat = information
    }
    private func consumeRoot() throws {
        guard storage.rootEntered, !storage.rootConsumed, storage.rootReturned == 0,
              storage.rootErrno != nil, storage.rootStat != nil, storage.rootRendered != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.rootConsumed = true
    }

    fileprivate func requireRootCurrent() throws {
        try frame()
        let root = try root()
        try root.loan.requireBound(operation: storage.operation, scope: storage.scope)
        let now = try storage.reservation.requireOperationsRoot(capture: self)
        guard now.loan === root.loan, now.operationID == root.operationID,
              now.operationsURL == root.operationsURL, now.fullFact == root.fullFact,
              now.names == root.names else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try enterRoot(.held)
        var held = stat()
        let hr = Darwin.fstat(root.loan.operations, &held), he = errno
        recordRoot(hr, saved: he, information: held) // before every fallible callback
        try frame()
        storage.rootRendered = Self.full(held)
        guard hr == 0, held.st_mode & S_IFMT == S_IFDIR, held.st_nlink >= 1,
              storage.rootRendered == root.fullFact else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try consumeRoot()
        try enterRoot(.named)
        var named = stat()
        let nr = Darwin.fstatat(root.loan.support, "FieldEvidenceOperations", &named, AT_SYMLINK_NOFOLLOW), ne = errno
        recordRoot(nr, saved: ne, information: named)
        try frame()
        storage.rootRendered = Self.full(named)
        guard nr == 0, named.st_mode & S_IFMT == S_IFDIR, named.st_nlink >= 1,
              storage.rootRendered == root.fullFact else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try consumeRoot()
        try root.loan.requireBound(operation: storage.operation, scope: storage.scope)
        try frame()
    }

    fileprivate func requireReadNode(_ node: ColdEraseScratchBirthImageReadNodeV1) throws {
        try frame()
        guard storage.state == .scanning, node.storage.capture === self,
              (node.storage.pass == 0 && storage.first === node && storage.second == nil)
                || (node.storage.pass == 1 && storage.second === node && storage.first != nil) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    fileprivate func recordMember(pass: UInt8, ordinal: Int) throws {
        let root = try root()
        guard storage.state == .scanning, pass < 2, ordinal >= 0, ordinal < root.names.count,
              storage.membershipInitialized == storage.membershipCapacity,
              let bytes = storage.membership else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let offset = Int(pass) * storage.membershipBytesPerPass + ordinal / 8
        guard offset >= 0, offset < storage.membershipCapacity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let mask = UInt8(1 << (ordinal % 8))
        guard bytes[offset] & mask == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        bytes[offset] |= mask
    }

    fileprivate func requireMembersComplete(pass: UInt8) throws {
        let root = try root()
        guard pass < 2 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for ordinal in root.names.indices {
            guard let bytes = storage.membership else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let offset = Int(pass) * storage.membershipBytesPerPass + ordinal / 8
            guard offset >= 0, offset < storage.membershipCapacity,
                  bytes[offset] & UInt8(1 << (ordinal % 8)) != 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }

    func requireCheckedOperationsRootComparison() throws {
        do {
            try frame()
            guard storage.state == .rootCompared, storage.rootConsumed,
                  let first = storage.first, let second = storage.second else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try first.requireCheckedResult(); try second.requireCheckedResult()
            try requireMembersComplete(pass: 0); try requireMembersComplete(pass: 1)
            try requireRootCurrent()
            // Actual existing G remains held. No acquire/revoke/unlock, complete
            // Image, cold-first accepted baseline, Seed or effect capability here.
        } catch { poison(); throw error }
    }

    fileprivate func poison() {
        storage.state = .uncertain
        storage.scope.poisonOnUncertainCleanup()
        storage.operation.poisonColdScratchOwner()
        // Strong actual Capture/Reservation/loan/two-node/raw backing retained.
    }
}

@MainActor
final class ColdEraseScratchBirthImageReadNodeV1 {
    fileprivate enum State: Equatable { case retained, opening, open, cursorEntering, cursor, closing, closed, uncertain }
    fileprivate enum Primitive: Equatable { case open, cursor, held, entry, close }
    fileprivate struct Storage {
        let capture: ColdEraseScratchBirthImageCaptureV1
        let pass: UInt8
        var state: State = .retained
        var primitive: Primitive?
        var entered = false
        var consumed = true
        var returned: Int64?
        var savedErrno: Int32?
        var descriptor: Int32 = -1
        var cursor: UnsafeMutablePointer<DIR>?
        var openReturned: Int32?
        var openErrno: Int32?
        var cursorReturned: UnsafeMutablePointer<DIR>?
        var cursorErrno: Int32?
        var closeReturned: Int32?
        var closeErrno: Int32?
        var currentStat: stat?
        var currentFull: String?
        var latestEntry: dirent?
        var latestName: String?
        var entryCalls = 0
        var nameCount = 0
        var dotSeen = false
        var dotDotSeen = false
        var eofObserved = false
    }
    fileprivate var storage: Storage
    fileprivate init(capture: ColdEraseScratchBirthImageCaptureV1, pass: UInt8) {
        storage = Storage(capture: capture, pass: pass)
    }
    private func frame() throws { try storage.capture.requireReadNode(self) }
    private func enter(_ primitive: Primitive) throws {
        try frame()
        guard storage.consumed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.primitive = primitive; storage.entered = true; storage.consumed = false
        storage.returned = nil; storage.savedErrno = nil
        storage.currentStat = nil; storage.currentFull = nil
    }
    private func consume() throws {
        guard storage.entered, !storage.consumed, storage.returned != nil, storage.savedErrno != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.consumed = true
    }
    private func requireHeld() throws {
        try frame(); try storage.capture.requireRootCurrent()
        guard storage.descriptor >= 0, storage.state == .open || storage.state == .cursor else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try enter(.held)
        var information = stat()
        let sr = Darwin.fstat(storage.descriptor, &information), se = errno
        storage.returned = Int64(sr); storage.savedErrno = se; storage.currentStat = information
        try frame()
        storage.currentFull = ColdEraseScratchBirthImageCaptureV1.full(information)
        guard sr == 0, information.st_mode & S_IFMT == S_IFDIR, information.st_nlink >= 1,
              storage.currentFull == (try storage.capture.root()).fullFact else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try consume(); try storage.capture.requireRootCurrent()
    }
    fileprivate func compareAndClose() throws {
        guard storage.state == .retained, storage.pass < 2 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        do {
            try frame(); try storage.capture.requireRootCurrent()
            let root = try storage.capture.root()
            try enter(.open); storage.state = .opening
            let fd = Darwin.openat(root.loan.operations, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC), oe = errno
            storage.openReturned = fd; storage.openErrno = oe; storage.returned = Int64(fd); storage.savedErrno = oe
            if fd >= 0 { storage.descriptor = fd } // retain actual FD before predicates
            try frame(); guard fd >= 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try consume(); storage.state = .open; try requireHeld()
            try enter(.cursor); storage.state = .cursorEntering
            let stream = Darwin.fdopendir(fd), ce = errno
            storage.cursorReturned = stream; storage.cursorErrno = ce; storage.cursor = stream
            storage.returned = stream.map { Int64(Int(bitPattern: $0)) } ?? 0; storage.savedErrno = ce
            try frame(); guard stream != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try consume(); storage.state = .cursor
            let limit = root.names.count.addingReportingOverflow(3)
            guard !limit.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            while !storage.eofObserved {
                guard storage.entryCalls < limit.partialValue else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try requireHeld(); try enter(.entry); storage.entryCalls += 1
                errno = 0
                let entry = Darwin.readdir(storage.cursor!), re = errno
                storage.returned = entry.map { Int64(Int(bitPattern: $0)) } ?? 0; storage.savedErrno = re
                if let entry { storage.latestEntry = entry.pointee }
                try frame()
                guard re == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner } // EINTR refuses; no retry
                if entry == nil { storage.eofObserved = true; try consume(); break }
                guard var actual = storage.latestEntry, actual.d_namlen > 0, actual.d_namlen <= 255 else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                storage.latestName = withUnsafeBytes(of: &actual.d_name) { raw in
                    String(bytes: raw.prefix(Int(actual.d_namlen)), encoding: .utf8)
                }
                guard let name = storage.latestName, !name.utf8.contains(0), !name.contains("/") else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                if name == "." { guard !storage.dotSeen else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }; storage.dotSeen = true }
                else if name == ".." { guard !storage.dotDotSeen else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }; storage.dotDotSeen = true }
                else {
                    var lower = 0, upper = root.names.count
                    while lower < upper { let middle = lower + (upper - lower) / 2
                        if root.names[middle] < name { lower = middle + 1 } else { upper = middle }
                    }
                    guard lower < root.names.count, root.names[lower].utf8.elementsEqual(name.utf8) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    try storage.capture.recordMember(pass: storage.pass, ordinal: lower)
                    storage.nameCount += 1
                }
                try consume(); try requireHeld()
            }
            guard storage.nameCount == root.names.count else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try storage.capture.requireMembersComplete(pass: storage.pass)
            try requireHeld(); try enter(.close); storage.state = .closing
            let cr = Darwin.closedir(storage.cursor!), cErrno = errno
            storage.closeReturned = cr; storage.closeErrno = cErrno; storage.returned = Int64(cr); storage.savedErrno = cErrno
            try frame(); guard cr == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try consume(); storage.cursor = nil; storage.descriptor = -1; storage.state = .closed
            try storage.capture.requireRootCurrent() // borrowed live parents only, never closed cursor FD
            try requireCheckedResult()
        } catch { storage.state = .uncertain; storage.capture.poison(); throw error }
    }
    fileprivate func requireCheckedResult() throws {
        guard storage.state == .closed, storage.consumed, storage.primitive == .close,
              storage.descriptor == -1, storage.cursor == nil,
              storage.openReturned != nil, storage.openReturned! >= 0, storage.openErrno != nil,
              storage.cursorReturned != nil, storage.cursorErrno != nil,
              storage.closeReturned == 0, storage.closeErrno != nil, storage.eofObserved,
              storage.nameCount == (try storage.capture.root()).names.count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}
// BIRTH_OPERATIONS_ROOT_SOURCE_V1_END

// BIRTH_CURRENT_READ_RESOURCE_PROFILE_V1_BEGIN
// This is an entered read-only CURRENT node producer. Its Native reservation
// and distinct PFP producer are real upstream dependencies, not declared here.
// It cannot produce a whole Image, Seed, REQUEST, effect permit or acceptance.
import CryptoKit

enum ColdEraseScratchBirthCurrentReadFailureV1: Error {
    case genuineOwnedRoleIssuerDue
    case checkedOwnWriterOriginDue
}

/// An actual initialized current-row cell. Original UID/GID are absent from
/// first9: these two fields come only from this process's entered observation.
/// Ordinals are comparison DATA; no path/DTO/range is retained in this cell.
struct ColdEraseScratchBirthCurrentRowStorageV1 {
    let originalOperationsOrdinal: UInt64
    let selectedPhysicalOrdinal: UInt64?
    let information: stat
    let contentDigest: (UInt64, UInt64, UInt64, UInt64)?
    let policy: TemporalPolicyObservationV1
}

/// A genuine fixed ONE-node window, with its own retained entered/result slots
/// and private Void-return boundary. Native issues at most one per registered
/// root owner for this component. It is not a many-node traversal allowance.
@MainActor
final class ColdEraseScratchBirthCurrentReadWindowV1 {
    fileprivate enum State: Equatable { case retained, entering, entered, checked, uncertain }
    fileprivate struct Storage {
        let reservation: ColdEraseScratchBirthCurrentReadReservationV1
        let rootReservation: ColdEraseScratchBirthImageReservationV1
        let rootCapture: ColdEraseScratchBirthImageCaptureV1
        let operation: EraseColdPreparationOperationV1
        let scope: ColdEraseScratchCleanupHeldGScopeV1
        let originalOperationsOrdinal: UInt64
        let selectedPhysicalOrdinal: UInt64
        var state: State = .retained
        var nodeEntry = false
        var activeNode: ColdEraseScratchBirthCurrentReadNodeV1?
        var checkedNode: ColdEraseScratchBirthCurrentReadNodeV1?
        var row: ColdEraseScratchBirthCurrentRowStorageV1?
        var helperReturned = false
        var activeFieldCleared = false
        var retainedFailure: Error?
    }
    fileprivate var storage: Storage
    private init(reservation: ColdEraseScratchBirthCurrentReadReservationV1,
        rootReservation: ColdEraseScratchBirthImageReservationV1,
        rootCapture: ColdEraseScratchBirthImageCaptureV1,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        originalOperationsOrdinal: UInt64, selectedPhysicalOrdinal: UInt64) {
        storage = Storage(reservation: reservation, rootReservation: rootReservation,
            rootCapture: rootCapture, operation: operation, scope: scope,
            originalOperationsOrdinal: originalOperationsOrdinal,
            selectedPhysicalOrdinal: selectedPhysicalOrdinal)
    }
    /// Actual fixed Window storage. Native separately adds the exact Node
    /// profile from authentic row/root path counts before either constructor,
    /// plus exact min(65536, originalByteCount+1) raw file-read capacity.
    static func requiredBackingBytes() throws -> UInt64 {
        UInt64(MemoryLayout<Storage>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentReadWindowV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentReadNodeV1>.stride
            + 2 * MemoryLayout<ColdEraseScratchBirthCurrentRowStorageV1>.stride)
    }
    static func readOriginalNode(reservation: ColdEraseScratchBirthCurrentReadReservationV1,
        rootReservation: ColdEraseScratchBirthImageReservationV1,
        rootCapture: ColdEraseScratchBirthImageCaptureV1,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        originalOperationsOrdinal: UInt64, selectedPhysicalOrdinal: UInt64) throws
        -> ColdEraseScratchBirthCurrentReadWindowV1 {
        try reservation.requireReservedReadWindowFrame(rootCapture: rootCapture,
            operation: operation, scope: scope,
            originalOperationsOrdinal: originalOperationsOrdinal,
            selectedPhysicalOrdinal: selectedPhysicalOrdinal)
        let window = ColdEraseScratchBirthCurrentReadWindowV1(reservation: reservation,
            rootReservation: rootReservation, rootCapture: rootCapture,
            operation: operation, scope: scope,
            originalOperationsOrdinal: originalOperationsOrdinal,
            selectedPhysicalOrdinal: selectedPhysicalOrdinal)
        do {
            try reservation.bindReadWindow(window) // SAME actual owner BEFORE postproof/IO
            window.storage.state = .entering
            try window.runPrivateNodeHelper()
            // The real private helper has returned; no lexical Node/row borrow
            // from that helper remains. Native still retains exact metadata.
            window.storage.helperReturned = true
            guard let actual = window.storage.activeNode,
                  window.storage.checkedNode === actual,
                  window.storage.row != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            window.storage.activeNode = nil
            window.storage.activeFieldCleared = true
            window.storage.state = .checked
            try window.requireCheckedReadWindowReturn(reservation: reservation)
            try reservation.recordCheckedReadWindowReturn(window: window)
            return window // one authentic current-row DATA owner; no Image/Seed
        } catch { window.poison(error); throw error }
    }
    private func runPrivateNodeHelper() throws {
        guard storage.state == .entering, !storage.nodeEntry,
              storage.activeNode == nil, storage.checkedNode == nil,
              storage.row == nil, !storage.helperReturned else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.nodeEntry = true; storage.state = .entered
        let node = try ColdEraseScratchBirthCurrentReadNodeV1.openOriginalNode(window: self,
            reservation: storage.reservation, rootReservation: storage.rootReservation,
            rootCapture: storage.rootCapture, operation: storage.operation,
            heldScope: storage.scope, parent: nil,
            originalOperationsOrdinal: storage.originalOperationsOrdinal,
            selectedPhysicalOrdinal: storage.selectedPhysicalOrdinal)
        guard storage.activeNode === node else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try node.closeAndConsumeRow { row in try self.consumeActualRow(row, node: node) }
        try node.requireCheckedRowConsumption(reservation: storage.reservation)
        storage.checkedNode = node // real checked node retained BEFORE helper return
    }
    fileprivate func retainEnteredNode(_ node: ColdEraseScratchBirthCurrentReadNodeV1) throws {
        guard storage.state == .entered, storage.nodeEntry,
              storage.activeNode == nil, storage.checkedNode == nil,
              node.storage.window === self, node.storage.reservation === storage.reservation,
              node.storage.rootCapture === storage.rootCapture,
              node.storage.parent == nil,
              node.storage.originalOperationsOrdinal == storage.originalOperationsOrdinal,
              node.storage.selectedPhysicalOrdinal == storage.selectedPhysicalOrdinal else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.activeNode = node // entered owner BEFORE Native reproof/open
    }
    private func consumeActualRow(_ row: ColdEraseScratchBirthCurrentRowStorageV1,
        node: ColdEraseScratchBirthCurrentReadNodeV1) throws {
        guard storage.state == .entered, storage.activeNode === node,
              storage.row == nil, node.storage.state == .consuming,
              node.storage.closeResult == 0, node.storage.closeErrno != nil,
              node.storage.descriptor == -1,
              row.originalOperationsOrdinal == storage.originalOperationsOrdinal,
              row.selectedPhysicalOrdinal == storage.selectedPhysicalOrdinal,
              let actual = node.storage.row,
              ColdEraseScratchBirthCurrentReadNodeV1.sameFull(row.information, actual.information),
              row.policy == actual.policy else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        switch (row.contentDigest, actual.contentDigest) {
        case (nil, nil): guard node.storage.isDirectory else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        case (.some(let a), .some(let b)):
            guard !node.storage.isDirectory, a.0 == b.0, a.1 == b.1, a.2 == b.2, a.3 == b.3,
                  node.storage.eofObserved, node.storage.readOffset == node.storage.expectedBytes else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.row = row // same real, fixed initialized result cell; shared strings stay charged
    }
    /// Native callbacks are memory-only. This checker grants no next Node or
    /// fixed-metadata decharge; ONE Window/Node metadata remains core charged.
    func requireReservationAssociation(reservation: ColdEraseScratchBirthCurrentReadReservationV1,
        rootReservation: ColdEraseScratchBirthImageReservationV1,
        rootCapture: ColdEraseScratchBirthImageCaptureV1,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1,
        originalOperationsOrdinal: UInt64, selectedPhysicalOrdinal: UInt64) throws {
        guard storage.reservation === reservation, storage.rootReservation === rootReservation,
              storage.rootCapture === rootCapture,
              storage.operation === operation, storage.scope === scope,
              storage.originalOperationsOrdinal == originalOperationsOrdinal,
              storage.selectedPhysicalOrdinal == selectedPhysicalOrdinal,
              storage.state != .uncertain, storage.retainedFailure == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireEnteredReadNode(_ node: ColdEraseScratchBirthCurrentReadNodeV1,
        reservation: ColdEraseScratchBirthCurrentReadReservationV1) throws {
        guard storage.reservation === reservation, storage.state == .entered,
              storage.nodeEntry, storage.activeNode === node,
              node.storage.window === self, storage.retainedFailure == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireCheckedReadWindowReturn(reservation: ColdEraseScratchBirthCurrentReadReservationV1) throws {
        guard storage.reservation === reservation, storage.state == .checked,
              storage.retainedFailure == nil, storage.nodeEntry, storage.helperReturned,
              storage.activeFieldCleared, storage.activeNode == nil,
              let node = storage.checkedNode, storage.row != nil,
              node.storage.window === self else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try node.requireCheckedRowConsumption(reservation: reservation)
    }
    private func poison(_ error: Error) {
        storage.retainedFailure = error; storage.state = .uncertain
        storage.scope.poisonOnUncertainCleanup()
        if let node = storage.activeNode ?? storage.checkedNode { node.poison(error) }
    }
}

/// Immutable PFP comparison DATA. The live resource is retained by Scope,
/// never hidden in this value which PFP retains after its own checked close.
@MainActor
struct ColdEraseScratchBirthCurrentPolicyNodeV1 {
    let kind: OwnedFileKindV1
    let url: URL
    let fullFact: String
    let parentFullFact: String
    let parentDescriptor: Int32
    let selectedName: String
    let isDirectory: Bool
    let absoluteURLUTF8Count: UInt64
    let fact: ColdEraseScratchBirthCurrentPolicyFullFactV1
    let parentFact: ColdEraseScratchBirthCurrentPolicyFullFactV1

    fileprivate init(kind: OwnedFileKindV1, url: URL, fullFact: String,
        parentFullFact: String, parentDescriptor: Int32, selectedName: String,
        isDirectory: Bool, absoluteURLUTF8Count: UInt64) throws {
        self.kind = kind; self.url = url; self.fullFact = fullFact
        self.parentFullFact = parentFullFact; self.parentDescriptor = parentDescriptor
        self.selectedName = selectedName; self.isDirectory = isDirectory
        self.absoluteURLUTF8Count = absoluteURLUTF8Count
        fact = try ColdEraseScratchBirthCurrentPolicyFullFactV1(fullFact)
        parentFact = try ColdEraseScratchBirthCurrentPolicyFullFactV1(parentFullFact)
    }
    func sameActualFields(as other: Self) -> Bool {
        kind == other.kind && url == other.url && fullFact == other.fullFact
            && parentFullFact == other.parentFullFact
            && parentDescriptor == other.parentDescriptor
            && selectedName.utf8.elementsEqual(other.selectedName.utf8)
            && isDirectory == other.isDirectory
            && absoluteURLUTF8Count == other.absoluteURLUTF8Count
    }
}

