    /// Read capacity is separately reserved from authentic expected byteCount.
    /// Swift/Foundation/URL/Error/class/allocator/header/VM are unmeasured.
    static func requiredBackingBytes(relativePathUTF8Count: UInt64,
        absoluteURLUTF8Count: UInt64) throws -> UInt64 {
        guard relativePathUTF8Count > 0, relativePathUTF8Count <= 16_640,
              absoluteURLUTF8Count >= relativePathUTF8Count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var total = UInt64(MemoryLayout<Storage>.stride
            + MemoryLayout<ColdEraseScratchBirthCurrentReadNodeV1>.stride
            + MemoryLayout<ColdEraseScratchBirthCurrentPolicyScopeV1.Storage>.stride
            + 3 * MemoryLayout<ColdEraseScratchBirthCurrentPolicyNodeV1>.stride
            + 3 * MemoryLayout<ColdEraseScratchBirthCurrentRowStorageV1>.stride
            + 2 * MemoryLayout<ReadEvidence>.stride
            + 4 * MemoryLayout<RawCall>.stride + 6 * MemoryLayout<stat>.stride
            + 2 * MemoryLayout<SHA256>.stride
            + MemoryLayout<SHA256.Digest>.stride
            + 2 * MemoryLayout<UnsafeRawBufferPointer>.stride
            + 2 * MemoryLayout<UnsafeRawBufferPointer.SubSequence>.stride
            + 20 * MemoryLayout<String>.stride + 14 * MemoryLayout<String.UTF8View>.stride
            + 22 * MemoryLayout<Substring>.stride + 2 * MemoryLayout<[Substring]>.stride
            + 4 * MemoryLayout<String.Index>.stride + MemoryLayout<String.Indices>.stride
            + 3 * MemoryLayout<URL>.stride + 2 * MemoryLayout<UUID>.stride)
