        // overlap. Native callback aliases remain charged by the borrower.
        for _ in 0..<3 { try add(relativePathUTF8Count) }
        let spellingCeiling = absoluteURLUTF8Count.addingReportingOverflow(1)
        guard !spellingCeiling.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for _ in 0..<3 { try add(spellingCeiling.partialValue) }
        // Original9/selected full11/current/parent/source renders and copies;
        // numeric interpolation has eleven <=20-byte scalar temporaries.
        try add(UInt64(2 * 197))
        try add(UInt64(10 * 241))
        try add(UInt64(4 * 64))
        try add(UInt64(4 * 255))
        try add(UInt64(11 * 20))
        try add(UInt64(MemoryLayout<(UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64, UInt64)>.stride
            + 4 * MemoryLayout<UInt64>.stride + 2 * MemoryLayout<Int>.stride
            + MemoryLayout<TemporalPolicyObservationV1>.stride + 4 * 36))
