    private func ownedCopy(_ text: String, ceiling: Int) throws -> String {
        // Allocation occurs only after the issuer's closed profile reservation.
        guard text.utf8.count <= ceiling else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return String(decoding: text.utf8, as: UTF8.self)
