        // No close retry, deinit close, field clearing, pointer free or rebaseline.
    }
}

/// Distinct PFP origin under the same actual entered node; no FirstCatalog,
/// Notification or Namespace Scope is relabeled. There is no G acquisition.
@MainActor
final class ColdEraseScratchBirthCurrentPolicyScopeV1 {
    fileprivate enum State: Equatable { case retained, observing, checked, consumed, released, uncertain }
    fileprivate struct Storage {
        var node: ColdEraseScratchBirthCurrentReadNodeV1?
        let operationID: UUID
        var state: State = .retained
        var observation: ColdEraseScratchBirthCurrentPolicyObservationV1?
        var uncertainDescriptor: Int32?
        var releasedObservationIdentity: ObjectIdentifier?
    }
    fileprivate var storage: Storage
    fileprivate init(node: ColdEraseScratchBirthCurrentReadNodeV1) {
        storage = Storage(node: node, operationID: node.storage.heldScope.operationID)
    }
    var operationID: UUID { storage.operationID }
    private func actualNode() throws -> ColdEraseScratchBirthCurrentReadNodeV1 {
        guard let node = storage.node, node.storage.policyScope === self,
              node.storage.heldScope.operationID == operationID,
              node.storage.operation.retainedColdOperationIDForComparison == operationID,
              storage.state != .uncertain else { throw ProtectedFilePolicyError.identityChanged }
        return node
    }
    /// Pure SAME-object checker for Native, never calls PFP/row/physical frame.
    func requireReservationAssociation(node: ColdEraseScratchBirthCurrentReadNodeV1) throws {
        guard storage.node === node, node.storage.policyScope === self,
              operationID == node.storage.heldScope.operationID, storage.state != .uncertain else {
            throw ProtectedFilePolicyError.identityChanged
        }
    }
    func requireCurrentBinding() throws {
        let node = try actualNode()
        try node.storage.reservation.requirePolicyScope(self, node: node)
        try node.requireCurrentBinding()
    }
    func requireNode() throws -> ColdEraseScratchBirthCurrentPolicyNodeV1 {
        try requireCurrentBinding(); return try actualNode().policyNode()
    }
    func requireNode(_ kind: OwnedFileKindV1, at url: URL, fullFact: String) throws
        -> ColdEraseScratchBirthCurrentPolicyNodeV1 {
        let node = try requireNode()
        guard node.kind == kind, node.url == url, node.fullFact == fullFact else {
            throw ProtectedFilePolicyError.identityChanged
        }
        return node
    }
    func requireKernelDescriptor() throws -> Int32 {
        try requireCurrentBinding(); let node = try actualNode()
        guard node.storage.descriptor >= 0 else { throw ProtectedFilePolicyError.identityChanged }
        return node.storage.descriptor // borrowed, NEVER closed by PFP
    }
    func requireObservationConstructionCapacity(additionalBytes: UInt64) throws {
        let node = try actualNode(); try requireCurrentBinding()
        guard storage.state == .retained, storage.observation == nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try node.storage.reservation.requirePolicyObservationConstructionCapacity(node: node,
            scope: self, additionalBytes: additionalBytes) // comparison to exact precharged operand only
    }
    func retainObservationAttempt(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        let node = try actualNode()
        guard storage.state == .retained, storage.observation == nil,
              node.storage.observation == nil else { throw ProtectedFilePolicyError.identityChanged }
        storage.observation = observation; node.storage.observation = observation
        storage.state = .observing // retain SAME actual object BEFORE fallible callbacks
        try node.storage.reservation.retainPolicyObservation(observation, node: node, scope: self)
        try requireObservationAttempt(observation); try requireCurrentBinding()
    }
    /// Pure checker after PFP positive close. No current FD/reentrant observer.
    func requireObservationAttempt(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        guard storage.observation === observation,
              storage.state == .observing || storage.state == .checked || storage.state == .consumed,
              storage.uncertainDescriptor == nil,
              observation.scopeIdentity == ObjectIdentifier(self), observation.operationID == operationID else {
            throw ProtectedFilePolicyError.identityChanged
        }
    }
    func requireObservationCapacity(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1,
        additionalBytes: UInt64) throws {
        let node = try actualNode(); try requireObservationAttempt(observation)
        try node.storage.reservation.requirePolicyObservationCapacity(node: node,
            scope: self, observation: observation, additionalBytes: additionalBytes)
    }
    func completeObservationAttempt(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        try requireObservationAttempt(observation)
        guard storage.state == .observing else { throw ProtectedFilePolicyError.identityChanged }
        try observation.requireCheckedSettlement(); try requireCurrentBinding()
        storage.state = .checked
    }
    func requireConsumedObservationAttempt(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        try requireObservationAttempt(observation)
        let node = try actualNode()
        guard storage.state == .checked || storage.state == .consumed,
              node.storage.state == .consuming,
              node.storage.closeResult == 0, node.storage.closeErrno != nil,
              node.storage.descriptor == -1, node.storage.call?.consumed == true,
              node.storage.rowConsumed, node.storage.rowConsumerReturned,
              node.storage.row != nil,
              node.storage.isDirectory || (node.storage.eofObserved
                && node.storage.readOffset == node.storage.expectedBytes),
              node.storage.observation === observation else { throw ProtectedFilePolicyError.identityChanged }
        try observation.requireCheckedSettlement()
        storage.state = .consumed // positive producer, no live closed-FD proof
    }
    fileprivate func recordCheckedReleasedObservation(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        try requireConsumedObservationAttempt(observation)
        storage.releasedObservationIdentity = ObjectIdentifier(observation)
        storage.state = .released
        storage.node = nil // only after actual node-close/row/private helper return
        storage.observation = nil
    }
    fileprivate func requireCheckedReleasedObservation(_ observation: ColdEraseScratchBirthCurrentPolicyObservationV1) throws {
        guard storage.state == .released,
              storage.releasedObservationIdentity == ObjectIdentifier(observation),
              storage.uncertainDescriptor == nil else { throw ProtectedFilePolicyError.identityChanged }
    }
    func retainUncertainDescriptor(_ descriptor: Int32) {
        storage.uncertainDescriptor = descriptor // one PFP pin; ambiguity retained
        poisonOnUncertainObservation()
    }
    func poisonOnUncertainObservation() {
        storage.state = .uncertain
        if let node = storage.node { node.poison(ProtectedFilePolicyError.identityChanged) }
    }
}
