/// Privately issued comparison-storage bounds from the same retained Source
/// and completed Reader. These scalars grant no role, IO, policy or Capture.
@MainActor
final class ColdEraseSchema2NamespaceCurrentSourceProfileV1 {
    fileprivate struct Storage {
        let scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let manifest: EraseSchema2ColdManifestOwnerV1
        let reader: ColdEraseSchema2ReaderRetirementReceiptV1
        let maximumNodeCount: UInt64
        let maximumMemberUTF8Count: UInt64
        let maximumPathUTF8Count: UInt64
        let maximumReaderControlByteCount: UInt64
        let declaredTargetBackingBytes: UInt64
    }
    fileprivate let storage: Storage
    var maximumNodeCount: UInt64 { storage.maximumNodeCount }
    var maximumMemberUTF8Count: UInt64 { storage.maximumMemberUTF8Count }
    var maximumPathUTF8Count: UInt64 { storage.maximumPathUTF8Count }
    var maximumReaderControlByteCount: UInt64 { storage.maximumReaderControlByteCount }
    var declaredTargetBackingBytes: UInt64 { storage.declaredTargetBackingBytes }

    /// Actual stored/reference/value/derivation cells only. Source maps and
    /// their original payload stay retained by their existing issuer. No
    /// allocator, Foundation, URL, class header or VM claim is made here.
    static func requiredBackingBytes() throws -> UInt64 {
        UInt64(MemoryLayout<Storage>.stride
            + 3 * MemoryLayout<ColdEraseSchema2NamespaceNodeStorageV1>.stride
            + 4 * MemoryLayout<UInt64>.stride
            + 16 * MemoryLayout<UInt64>.stride
            + 3 * MemoryLayout<[String]>.stride
            + 3 * MemoryLayout<String.UTF8View>.stride
            + MemoryLayout<[String: String].Iterator>.stride
            + MemoryLayout<[String: Data].Iterator>.stride
            + MemoryLayout<[String: Data].Keys.Iterator>.stride
            + 3 * MemoryLayout<String>.stride
            + 2 * MemoryLayout<EraseSchema2ColdAuxiliaryFirstObserverV1.Snapshot>.stride
            + MemoryLayout<ColdEraseSchema2NamespaceOriginalNodeV1>.stride
            + MemoryLayout<GenerationLeaseRegistryV1.ColdSchema2RetirementCensusV1>.stride
            + MemoryLayout<Range<UInt64>.Iterator>.stride + MemoryLayout<Range<UInt64>>.stride
            + 2 * MemoryLayout<String.UTF8View.SubSequence>.stride)
    }

    fileprivate init(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        manifest: EraseSchema2ColdManifestOwnerV1,
        reader: ColdEraseSchema2ReaderRetirementReceiptV1,
        maximumNodeCount: UInt64, maximumMemberUTF8Count: UInt64,
        maximumPathUTF8Count: UInt64, maximumReaderControlByteCount: UInt64,
        declaredTargetBackingBytes: UInt64) {
        storage = Storage(scope: scope, capture: capture, manifest: manifest,
            reader: reader, maximumNodeCount: maximumNodeCount,
            maximumMemberUTF8Count: maximumMemberUTF8Count,
            maximumPathUTF8Count: maximumPathUTF8Count,
            maximumReaderControlByteCount: maximumReaderControlByteCount,
            declaredTargetBackingBytes: declaredTargetBackingBytes)
    }

    /// Pure identity, including the actual privately retained return. No
    /// callback to Source/Native, capacity IO or current observer is hidden.
    func requireAssociation(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard storage.scope === scope, storage.capture === capture else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try capture.requireWholeCurrentSourceProfileAssociation(self, scope: scope)
    }
}

extension ColdEraseSchema2NamespaceCaptureOwnerV1 {
    /// The real Native provisional Scope is already retained by its issuer.
    /// Retain it here BEFORE any delegated checker or profile callback.
    func retainWholeCurrentScope(_ scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1) throws {
        guard storage.state == .capturing,
              !storage.wholeCurrentScopeEntered, storage.wholeCurrentScope == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        storage.wholeCurrentScopeEntered = true
        storage.wholeCurrentScope = scope
        // Native performs its fallible returned-owner proof after this method.
        // This method cannot re-enter that provisional Native frame.
    }

    func requireWholeCurrentScopeAssociation(_ scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1) throws {
        guard storage.state == .capturing || storage.state == .captured,
              storage.wholeCurrentScopeEntered, storage.wholeCurrentScope === scope,
              storage.wholeCurrentFailure == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    /// Pure SAME privately retained profile/Reader association. This checker
    /// stays inside Capture; it neither exposes private storage nor calls a
    /// Native live observer, capacity query or G acquisition.
    fileprivate func requireWholeCurrentSourceProfileAssociation(
        _ profile: ColdEraseSchema2NamespaceCurrentSourceProfileV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1) throws {
        try requireWholeCurrentScopeAssociation(scope)
        guard storage.wholeCurrentSourceProfile === profile,
              profile.storage.scope === scope, profile.storage.capture === self,
              profile.storage.reader === storage.basis.readerReceipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    /// One genuine constructor/profile callback. The private Source maps and
    /// Reader fields are borrowed, not reparsed from a current filesystem or
    /// passed in by the caller. Any reached error keeps the actual profile.
    func withWholeCurrentSourceProfile(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        _ body: (ColdEraseSchema2NamespaceCurrentSourceProfileV1) throws -> Void) throws {
        do {
            try requireWholeCurrentScopeAssociation(scope)
            guard !storage.wholeCurrentProfileEntered, storage.wholeCurrentSourceProfile == nil,
                  !storage.originalIndexCompleted, storage.nodeTable == nil,
                  storage.memberUTF8 == nil, storage.originalNodeCount == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            storage.wholeCurrentProfileEntered = true // BEFORE the delegated borrow
            try scope.withManifestForProfile(capture: self) { manifest in
                let retained = try manifest.requireColdTerminalNamespaceBasis(
                    owner: self.storage.owner, operation: self.storage.operation)
                guard retained.notificationAfter == self.storage.basis.notificationAfter else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try scope.withManifestSnapshots(manifest: manifest, capture: self) { first, after in
                    guard after == self.storage.basis.notificationAfter,
                          first == (try retained.firstObserver.firstObservation()) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    try manifest.withColdNamespaceRetainedCreatorProfile(capture: self, scope: scope) {
                        creatorNodes, creatorNameBytes, creatorMaximumPath in
                        try self.storage.basis.readerReceipt.withColdNamespaceRetainedReaderProfile(
                            capture: self, scope: scope) { readerNodes, readerNameBytes,
                                readerMaximumPath, readerBytes in
                        func add(_ left: UInt64, _ right: UInt64) throws -> UInt64 {
                            let result = left.addingReportingOverflow(right)
                            guard !result.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                            return result.partialValue
                        }
                        let originalCount = try self.storage.reservation.requireOriginalOperationsNodeCount(capture: self)
                        guard originalCount > 0, originalCount < 100_000 else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                        var originalMemberBytes: UInt64 = 0, maximumPath: UInt64 = 0
                        // Authenticated Original partition callbacks, before the
                        // first table/node constructor. No generated-node spare,
                        // dictionary lookup or current filesystem sample is used.
                        for ordinal in 0..<originalCount {
                            try self.storage.reservation.withOriginalOperationsNode(ordinal: ordinal,
                                capture: self) { original in
                                guard original.ordinal == ordinal, original.path.utf8.count <= 16_640,
                                      !original.path.utf8.contains(0),
                                      original.kind == "directory" || original.kind == "file" else {
                                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                                }
                                let bytes = original.path.utf8
                                let slash = bytes.lastIndex(of: 47)
                                let start = slash.map { bytes.index(after: $0) } ?? bytes.startIndex
                                let member = bytes[start...]
                                guard ordinal == 0 ? (original.path.isEmpty && original.kind == "directory")
                                    : (!member.isEmpty && member.count <= 255
                                        && !member.elementsEqual(".".utf8)
                                        && !member.elementsEqual("..".utf8)) else {
                                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                                }
                                originalMemberBytes = try add(originalMemberBytes, UInt64(member.count))
                                maximumPath = max(maximumPath, UInt64(bytes.count))
                            }
                        }
                        let count = try add(try add(originalCount, creatorNodes), readerNodes)
                        let memberBytes = try add(try add(originalMemberBytes, creatorNameBytes), readerNameBytes)
                        maximumPath = max(maximumPath, max(creatorMaximumPath, readerMaximumPath))
                        guard count > 0, count <= UInt64(Int.max / 2), maximumPath <= 16_640 else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                        let profile = ColdEraseSchema2NamespaceCurrentSourceProfileV1(scope: scope,
                            capture: self, manifest: manifest, reader: self.storage.basis.readerReceipt,
                            maximumNodeCount: count, maximumMemberUTF8Count: memberBytes,
                            maximumPathUTF8Count: maximumPath, maximumReaderControlByteCount: readerBytes,
                            declaredTargetBackingBytes: try Self.wholeCurrentDeclaredBackingBytes(
                                nodeCount: count, memberUTF8Count: memberBytes, pathUTF8Count: maximumPath))
                        self.storage.wholeCurrentSourceProfile = profile // BEFORE its fallible consumer
                        try profile.requireAssociation(scope: scope, capture: self)
                        try body(profile)
                        try profile.requireAssociation(scope: scope, capture: self)
                        }
                    }
                }
            }
            guard storage.wholeCurrentSourceProfile != nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            storage.wholeCurrentProfileReturned = true
        } catch {
            storage.wholeCurrentFailure = error
            poisonOnUncertainEffect(); scope.poisonOnUncertainEffect()
            throw error
        }
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    /// Pure actual creator-map count/lexical operands. It issues neither a
    /// generated node nor a policy role. Original backing is not copied here.
    fileprivate func withColdNamespaceRetainedCreatorProfile(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        _ body: (UInt64, UInt64, UInt64) throws -> Void) throws {
        try scope.requireManifestOrigin(manifest: self, capture: capture)
        guard opened, !closeAttempted, !coldScratchParentsUncertain,
              !leaseReaderPublicationInFlight, !leaseReaderSettlementInFlight,
              !schema2ColdNotificationCaptureInFlight, !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil,
              let source = schema2ColdNotificationWitness,
              postGenerationProjection != nil else { throw StoreMigrationFailure.invalidIdentity }
        let notificationNames = schema2ColdNotificationProjectedNames ?? source.names
        guard notificationNames.count == schema2ColdNotificationFiles.count,
              (schema2ColdNotificationProjectedFacts ?? source.leafFacts).count == notificationNames.count,
              (schema2ColdNotificationProjectedBytes ?? source.leafBytes).count == notificationNames.count,
              (capturedMigrationNames?.count ?? 0) == migrationFiles.count,
              capturedMigrationBytes.count == migrationFiles.count,
              (capturedDeletionNames?.count ?? 0) == deletionFiles.count,
              capturedDeletionBytes.count == deletionFiles.count,
              (capturedFinalizationNames?.count ?? 0) == finalizationFiles.count,
              capturedFinalizationBytes.count == finalizationFiles.count else {
            throw StoreMigrationFailure.invalidIdentity
        }
        var count: UInt64 = 0, memberBytes: UInt64 = 0, maximumPath: UInt64 = 0
        func add(_ left: UInt64, _ right: UInt64) throws -> UInt64 {
            let result = left.addingReportingOverflow(right)
            guard !result.overflow else { throw StoreMigrationFailure.invalidIdentity }
            return result.partialValue
        }
        func branch(_ name: String, _ members: [String]?) throws {
            guard name.utf8.count <= 255, !name.isEmpty, !name.contains("/"),
                  !name.utf8.contains(0) else { throw StoreMigrationFailure.invalidIdentity }
            guard let members else { return }
            count = try add(count, 1); memberBytes = try add(memberBytes, UInt64(name.utf8.count))
            maximumPath = max(maximumPath, UInt64(name.utf8.count))
            for member in members {
                guard !member.isEmpty, member != ".", member != "..", !member.contains("/"),
                      !member.utf8.contains(0), member.utf8.count <= 255 else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                count = try add(count, 1); memberBytes = try add(memberBytes, UInt64(member.utf8.count))
                maximumPath = max(maximumPath, try add(UInt64(name.utf8.count + 1), UInt64(member.utf8.count)))
            }
        }
        if operationsChildren[AppLockNotificationControlStoreV1.rootName] != nil {
            try branch(AppLockNotificationControlStoreV1.rootName, notificationNames)
        } else { guard notificationNames.isEmpty else { throw StoreMigrationFailure.invalidIdentity } }
        if operationsChildren["schema-migration"] != nil { try branch("schema-migration", capturedMigrationNames) }
        else { guard capturedMigrationNames?.isEmpty == true else { throw StoreMigrationFailure.invalidIdentity } }
        if operationsChildren["deletion"] != nil { try branch("deletion", capturedDeletionNames) }
        else { guard capturedDeletionNames?.isEmpty == true else { throw StoreMigrationFailure.invalidIdentity } }
        if operationsChildren["finalization"] != nil { try branch("finalization", capturedFinalizationNames) }
        else { guard capturedFinalizationNames?.isEmpty == true else { throw StoreMigrationFailure.invalidIdentity } }
        if let fact = schema2ColdNotificationCreationFact {
            guard let bytes = schema2ColdNotificationCreationBytes,
                  let pin = operationsChildren[EraseSchema2ColdNotificationSourceV1.creationRecordName],
                  pin.descriptor >= 0, fact.size == bytes.count,
                  bytes == schema2ColdNotificationExpectedCreationBytes,
                  schema2ColdNotificationCreationRecord == schema2ColdNotificationExpectedCreationRecord else {
                throw StoreMigrationFailure.invalidIdentity
            }
            let name = EraseSchema2ColdNotificationSourceV1.creationRecordName
            count = try add(count, 1); memberBytes = try add(memberBytes, UInt64(name.utf8.count))
            maximumPath = max(maximumPath, UInt64(name.utf8.count))
        } else {
            guard schema2ColdNotificationCreationBytes == nil,
                  schema2ColdNotificationCreationRecord == nil else { throw StoreMigrationFailure.invalidIdentity }
        }
        try body(count, memberBytes, maximumPath)
        try scope.requireManifestOrigin(manifest: self, capture: capture)
    }
}

extension ColdEraseSchema2ReaderRetirementReceiptV1 {
    /// Same-type access to the private completed attempt. The true resource
    /// tuple never escapes; this calls only the incumbent memory/settlement
    /// checkers and does not reacquire G or sample a filesystem survivor.
    fileprivate func requireColdNamespaceRetainedOrigin(
        operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        let resources = try attempt.requireProjectionResources(operation: operation,
            registry: registry, activity: activity, exclusion: exclusion,
            binding: binding, witness: witness)
        try requireBound(operation: operation, registry: registry, activity: activity,
            allocation: resources.allocation, reader: resources.reader,
            exclusion: exclusion, binding: binding, witness: witness)
    }

    /// Exact completed-writer fields only. This borrower neither calls the
    /// ordinary registry observer nor reacquires G; current proof is separate.
    fileprivate func withColdNamespaceRetainedReaderProfile(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        _ body: (UInt64, UInt64, UInt64, UInt64) throws -> Void) throws {
        try capture.requireNamespaceReaderReceiptAssociation(self, scope: scope)
        guard attempt.completed, attempt.checkedGReleased, attempt.recordClosed,
              attempt.recordUnlinked, attempt.original < 0, attempt.temporary < 0,
              attempt.uncertainCloseDescriptors.isEmpty, attempt.policyUncertainDescriptors.isEmpty,
              afterTokens.isEmpty, attempt.finalRegistryProjection != nil,
              let census = attempt.namespaceFinalFirstCensus,
              let second = attempt.namespaceFinalSecondCensus, census == second,
              census.tokens.isEmpty, census.facts == attempt.currentFacts,
              census.bytes == attempt.currentBytes,
              census.leaseNames == attempt.currentLeaseNames,
              census.ownerNames == attempt.ownerNames,
              attempt.currentLeaseNames.count <= 7,
              attempt.ownerNames.count <= GenerationLeaseRegistryV1.maximumOwnerCount else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for pin in attempt.readPins.values { try pin.requireCheckedClosed() }
        try attempt.io.requireSettled()
        var memberBytes: UInt64 = 0, maximumPath: UInt64 = 0, controlBytes: UInt64 = 0
        func add(_ left: UInt64, _ right: UInt64) throws -> UInt64 {
            let result = left.addingReportingOverflow(right)
            guard !result.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return result.partialValue
        }
        for (key, fact) in census.facts {
            guard !key.isEmpty, key.utf8.count <= 128, fact.utf8.count <= 241 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // Exact lexical count from the actual closed Registry role key.
            // This is a maximum-storage operand only, never a node/role grant.
            let counts = try GenerationLeaseRegistryV1.coldNamespaceRetainedReaderLexicalCounts(key: key)
            memberBytes = try add(memberBytes, counts.memberBytes)
            maximumPath = max(maximumPath, counts.pathBytes)
        }
        for (key, bytes) in census.bytes {
            guard census.facts[key] != nil,
                  bytes.count <= GenerationLeaseRegistryV1.maximumControlFileBytes else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            controlBytes = try add(controlBytes, UInt64(bytes.count))
        }
        try body(UInt64(census.facts.count), memberBytes, maximumPath, controlBytes)
        try capture.requireNamespaceReaderReceiptAssociation(self, scope: scope)
    }
}

extension ColdEraseSchema2NamespaceCaptureOwnerV1 {
    fileprivate func requireNamespaceReaderReceiptAssociation(
        _ receipt: ColdEraseSchema2ReaderRetirementReceiptV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1) throws {
        try requireWholeCurrentScopeAssociation(scope)
        guard storage.basis.readerReceipt === receipt else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let actors = try operationsRootReadReceiptActors()
        try receipt.requireColdNamespaceRetainedOrigin(operation: actors.operation,
            registry: actors.registry, activity: actors.activity, exclusion: actors.exclusion,
            binding: actors.binding, witness: actors.witness)
    }
}
extension GenerationLeaseRegistryV1 {
    /// Closed actual retirement-census key grammar, derived from this
    /// Registry's own constants. No filesystem read, policy acceptance or
    /// caller supplied maximum is used. UTF8 subsequences stay borrowed.
    fileprivate static func coldNamespaceRetainedReaderLexicalCounts(key: String)
        throws -> (memberBytes: UInt64, pathBytes: UInt64) {
        let registryBytes = UInt64("generation-leases".utf8.count)
        let ownerBytes = UInt64(Self.ownerDirectoryName.utf8.count)
        let migrationBytes = UInt64("schema-migration".utf8.count)
        switch key {
        case "lease-root": return (registryBytes, registryBytes)
        case "owner-root": return (ownerBytes, registryBytes + 1 + ownerBytes)
        case "migration-root": return (migrationBytes, migrationBytes)
        default: break
        }
        let prefix: Int, parentBytes: UInt64
        if key.hasPrefix("lease/") {
            prefix = "lease/".utf8.count; parentBytes = registryBytes
        } else if key.hasPrefix("owners/") {
            prefix = "owners/".utf8.count; parentBytes = registryBytes + 1 + ownerBytes
        } else if key.hasPrefix("migration/") {
            prefix = "migration/".utf8.count; parentBytes = migrationBytes
        } else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let member = key.utf8.dropFirst(prefix)
        guard !member.isEmpty, member.count <= 255,
              !member.contains(0), !member.contains(47),
              !member.elementsEqual(".".utf8), !member.elementsEqual("..".utf8) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // Names are already authenticated by the SAME completed writer's
        // retained census; this profile does not accept a current leaf.
        let memberBytes = UInt64(member.count)
        let path = parentBytes.addingReportingOverflow(1 + memberBytes)
        guard !path.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return (memberBytes, path.partialValue)
    }
}
