// POSTCONTENT_NAMESPACE_CURRENT_POLICY_SCOPE_V1_BEGIN
/// Immutable DATA from a genuine entered postcontent read resource. The
/// descriptor remains in that resource; this value never owns or closes it.
@MainActor
struct ColdEraseSchema2NamespaceCurrentPolicyNodeV1 {
    let kind: OwnedFileKindV1
    let url: URL
    let fullFact: String
    let parentFullFact: String
    let parentDescriptor: Int32
    let selectedName: String
    let isDirectory: Bool
    let absoluteURLUTF8Count: UInt64
    let fact: ColdEraseSchema2NamespaceCurrentPolicyFullFactV1
    let parentFact: ColdEraseSchema2NamespaceCurrentPolicyFullFactV1
    fileprivate init(kind: OwnedFileKindV1, url: URL, fullFact: String,
        parentFullFact: String, parentDescriptor: Int32, selectedName: String,
        isDirectory: Bool, absoluteURLUTF8Count: UInt64) throws {
        self.kind = kind; self.url = url; self.fullFact = fullFact
        self.parentFullFact = parentFullFact; self.parentDescriptor = parentDescriptor
        self.selectedName = selectedName; self.isDirectory = isDirectory
        self.absoluteURLUTF8Count = absoluteURLUTF8Count
        fact = try ColdEraseSchema2NamespaceCurrentPolicyFullFactV1(fullFact)
        parentFact = try ColdEraseSchema2NamespaceCurrentPolicyFullFactV1(parentFullFact)
    }
    func sameActualFields(as other: Self) -> Bool {
        kind == other.kind && url == other.url && fullFact == other.fullFact
            && parentFullFact == other.parentFullFact && parentDescriptor == other.parentDescriptor
            && selectedName.utf8.elementsEqual(other.selectedName.utf8)
            && isDirectory == other.isDirectory
            && absoluteURLUTF8Count == other.absoluteURLUTF8Count
    }
}

/// New same-current-prefix provenance. This does not adapt a revoked BIRTH
/// or pre-Seed scope. PFP owns and records its own transient policy pin and
/// URL/FileManager getter returns; the actual Target node remains retained.
@MainActor
final class ColdEraseSchema2NamespaceCurrentPolicyScopeV1 {
    fileprivate enum State { case retained, observing, checked, consumed, uncertain }
    fileprivate struct Storage {
        let resource: ColdEraseSchema2NamespaceCurrentReadResourceV1
        let operationID: UUID
        var state: State = .retained
        var observation: ColdEraseSchema2NamespaceCurrentPolicyObservationV1?
        var uncertainDescriptor: Int32?
    }
    fileprivate var storage: Storage
    fileprivate init(resource: ColdEraseSchema2NamespaceCurrentReadResourceV1) {
        storage = Storage(resource: resource, operationID: resource.operationID)
    }
    var operationID: UUID { storage.operationID }
    private func resource() throws -> ColdEraseSchema2NamespaceCurrentReadResourceV1 {
        guard storage.state != .uncertain,
              storage.resource.storage.policyScope === self,
              storage.operationID == storage.resource.operationID else {
            throw ProtectedFilePolicyError.identityChanged
        }
        return storage.resource
    }
    func requireCurrentBinding() throws {
        try resource().requireCurrentPolicyFrame(scope: self)
    }
    func requireNode() throws -> ColdEraseSchema2NamespaceCurrentPolicyNodeV1 {
        try requireCurrentBinding(); return try resource().currentPolicyNode(scope: self)
    }
    func requireNode(_ kind: OwnedFileKindV1, at url: URL, fullFact: String)
        throws -> ColdEraseSchema2NamespaceCurrentPolicyNodeV1 {
        let actual = try requireNode()
        guard actual.kind == kind, actual.url == url, actual.fullFact == fullFact else {
            throw ProtectedFilePolicyError.identityChanged
        }
        return actual
    }
    func requireKernelDescriptor() throws -> Int32 {
        try requireCurrentBinding()
        let actual = try resource()
        guard actual.storage.descriptor >= 0 else { throw ProtectedFilePolicyError.identityChanged }
        return actual.storage.descriptor // borrowed; PFP NEVER closes this FD
    }
    func requireObservationConstructionCapacity(additionalBytes: UInt64) throws {
        guard storage.state == .retained, storage.observation == nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try requireCurrentBinding()
        try resource().requirePolicyDeclaredBacking(scope: self, additionalBytes: additionalBytes)
    }
    func retainObservationAttempt(_ actual: ColdEraseSchema2NamespaceCurrentPolicyObservationV1) throws {
        guard storage.state == .retained, storage.observation == nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        storage.observation = actual // before any fallible returned-owner check
        storage.state = .observing
        try resource().retainPolicyObservation(actual, scope: self)
        try requireObservationAttempt(actual); try requireCurrentBinding()
    }
    func requireObservationAttempt(_ actual: ColdEraseSchema2NamespaceCurrentPolicyObservationV1) throws {
        guard storage.state == .observing || storage.state == .checked || storage.state == .consumed,
              storage.observation === actual, storage.uncertainDescriptor == nil,
              actual.scopeIdentity == ObjectIdentifier(self), actual.operationID == operationID else {
            throw ProtectedFilePolicyError.identityChanged
        }
    }
    func requireObservationCapacity(_ actual: ColdEraseSchema2NamespaceCurrentPolicyObservationV1,
        additionalBytes: UInt64) throws {
        try requireObservationAttempt(actual)
        try resource().requirePolicyDeclaredBacking(scope: self, additionalBytes: additionalBytes)
    }
    func completeObservationAttempt(_ actual: ColdEraseSchema2NamespaceCurrentPolicyObservationV1) throws {
        try requireObservationAttempt(actual)
        guard storage.state == .observing else { throw ProtectedFilePolicyError.identityChanged }
        try actual.requireCheckedSettlement(); try requireCurrentBinding()
        storage.state = .checked
    }
    func requireConsumedObservationAttempt(_ actual: ColdEraseSchema2NamespaceCurrentPolicyObservationV1) throws {
        try requireObservationAttempt(actual)
        guard storage.state == .checked || storage.state == .consumed else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try resource().requireCheckedPolicyConsumer(scope: self, observation: actual)
        try actual.requireCheckedSettlement()
        storage.state = .consumed
    }
    func retainUncertainDescriptor(_ descriptor: Int32) {
        if storage.uncertainDescriptor == nil { storage.uncertainDescriptor = descriptor }
        poisonOnUncertainObservation()
    }
    func poisonOnUncertainObservation() {
        storage.state = .uncertain
        storage.resource.poison(ProtectedFilePolicyError.identityChanged)
    }
}
// POSTCONTENT_NAMESPACE_CURRENT_POLICY_SCOPE_V1_END

// POSTCONTENT_NAMESPACE_CURRENT_ORIGIN_BRIDGES_V1_BEGIN
/// Immutable borrower DATA from an actual retained Source or completed
/// Reader. No path/policy/census callback creates a node or effect permit.
@MainActor
fileprivate struct ColdEraseSchema2NamespaceCurrentNodeOriginV1 {
    enum Provenance: Equatable { case settledOperations, originalCreator, generatedCreator, retiredReader }
    let provenance: Provenance
    let kind: OwnedFileKindV1
    let fullFact: String?
    let members: [String]?
    let bytes: Data?
    let policy: TemporalPolicyObservationV1?
    let creatorDescriptor: Int32?
    let requiresUntouchedOriginal: Bool
}

@MainActor
struct ColdEraseSchema2NamespaceRetiredReaderNodeV1 {
    let key: String
    let fullFact: String
    let bytes: Data?
    let policy: TemporalPolicyObservationV1?
    let members: [String]?
    let kind: OwnedFileKindV1
    fileprivate init(key: String, fullFact: String, bytes: Data?,
        policy: TemporalPolicyObservationV1?, members: [String]?, kind: OwnedFileKindV1) {
        self.key = key; self.fullFact = fullFact; self.bytes = bytes
        self.policy = policy; self.members = members; self.kind = kind
    }
}

extension ColdEraseSchema2ReaderRetirementReceiptV1 {
    /// BOTH retained final census returns came from the real completed writer
    /// under its real G and were equal before its checked G release. The stale
    /// pre-replacement preparation policy is never borrowed as current policy.
    fileprivate func withColdNamespaceRetainedFinalCensus(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        _ body: (GenerationLeaseRegistryV1.ColdSchema2RetirementCensusV1) throws -> Void) throws {
        try capture.requireNamespaceReaderReceiptAssociation(self, scope: scope)
        guard attempt.completed, attempt.checkedGReleased, attempt.recordClosed,
              attempt.recordUnlinked, attempt.original < 0, attempt.temporary < 0,
              attempt.activePrimitive == .fsyncPublicationRecordDirectory,
              !attempt.ownedMutationPending, !attempt.uncertain,
              attempt.uncertainCloseDescriptors.isEmpty,
              attempt.policyUncertainDescriptors.isEmpty,
              let first = attempt.namespaceFinalFirstCensus,
              let second = attempt.namespaceFinalSecondCensus, first == second,
              first.tokens.isEmpty, afterTokens.isEmpty,
              first.facts == attempt.currentFacts, first.bytes == attempt.currentBytes,
              first.leaseNames == attempt.currentLeaseNames, first.ownerNames == attempt.ownerNames,
              first.leaseNames.count <= 7,
              first.ownerNames.count <= GenerationLeaseRegistryV1.maximumOwnerCount,
              attempt.finalRegistryProjection != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for pin in attempt.readPins.values { try pin.requireCheckedClosed() }
        try attempt.io.requireSettled()
        try body(first)
        try capture.requireNamespaceReaderReceiptAssociation(self, scope: scope)
    }
    fileprivate func withColdNamespaceRetainedReaderNode(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1, key: String,
        _ body: (ColdEraseSchema2NamespaceRetiredReaderNodeV1) throws -> Void) throws {
        try withColdNamespaceRetainedFinalCensus(capture: capture, scope: scope) { census in
            guard let full = census.facts[key], full.utf8.count <= 241 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let names: [String]?, kind: OwnedFileKindV1
            if key == "lease-root" { names = census.leaseNames; kind = .generationLeaseDirectory }
            else if key == "owner-root" { names = census.ownerNames; kind = .generationLeaseDirectory }
            else if key.hasPrefix("lease/") {
                let name = String(key.dropFirst("lease/".count))
                guard census.leaseNames.contains(name), census.bytes[key] != nil,
                      census.policies[key] != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                names = nil
                kind = try GenerationLeaseRegistryV1.namespaceRetainedReaderControlKind(name: name)
            } else if key.hasPrefix("owners/") {
                let name = String(key.dropFirst("owners/".count))
                guard census.ownerNames.contains(name), census.bytes[key]?.isEmpty == true,
                      census.policies[key] != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                names = nil; kind = .generationLeaseOwnerLock
            } else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try body(ColdEraseSchema2NamespaceRetiredReaderNodeV1(key: key, fullFact: full,
                bytes: census.bytes[key], policy: census.policies[key], members: names, kind: kind))
        }
    }
}

extension ColdEraseSchema2NamespaceCaptureOwnerV1 {
    /// Narrow readonly same-Receipt borrower. No ordinary census or
    /// requireCurrentRegistryProjection (which would reacquire G) is called.
    func withNamespaceRetiredReaderOrigin(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        key: String, _ body: (ColdEraseSchema2NamespaceRetiredReaderNodeV1) throws -> Void) throws {
        try storage.basis.readerReceipt.withColdNamespaceRetainedReaderNode(capture: self,
            scope: scope, key: key, body)
    }
    fileprivate func withWholeCurrentOrigin(path: String,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        _ body: (ColdEraseSchema2NamespaceCurrentNodeOriginV1) throws -> Void) throws {
        try requireWholeCurrentScopeAssociation(scope)
        guard let profile = storage.wholeCurrentSourceProfile else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if path.isEmpty {
            let image = storage.basis.finalScratchImage
            guard image.scratch == nil, image.ingress == nil,
                  !image.operationsNames.contains("ScratchDataV1"),
                  !image.operationsNames.contains("ProtectedIngressReceiptsV1") else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try body(.init(provenance: .settledOperations, kind: .stagingDirectory,
                fullFact: image.operationsFullFact, members: image.operationsNames,
                bytes: nil, policy: nil, creatorDescriptor: nil, requiresUntouchedOriginal: false))
        } else if path == "generation-leases" || path.hasPrefix("generation-leases/") {
            let key: String
            if path == "generation-leases" { key = "lease-root" }
            else if path == "generation-leases/owners" { key = "owner-root" }
            else if path.hasPrefix("generation-leases/owners/") {
                let suffix = path.dropFirst("generation-leases/owners/".count)
                guard !suffix.isEmpty, !suffix.contains("/") else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                key = "owners/" + suffix
            } else {
                let suffix = path.dropFirst("generation-leases/".count)
                guard !suffix.isEmpty, !suffix.contains("/") else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                key = "lease/" + suffix
            }
            try withNamespaceRetiredReaderOrigin(scope: scope, key: key) { row in
                let pin = try self.storage.registry.namespaceRetiredReaderHeldPin(capture: self, key: key)
                try body(.init(provenance: .retiredReader, kind: row.kind, fullFact: row.fullFact,
                    members: row.members, bytes: row.bytes, policy: row.policy,
                    creatorDescriptor: pin, requiresUntouchedOriginal: false))
            }
        } else {
            try profile.storage.manifest.withColdNamespaceRetainedNodeOrigin(capture: self,
                scope: scope, path: path, body)
        }
        try requireWholeCurrentScopeAssociation(scope)
    }
}

extension GenerationLeaseRegistryV1 {
    /// Only actual still-held Registry pins are lent. The replacement registry
    /// file was genuinely closed by Reader and therefore returns nil. Its
    /// origin is the durable Reader receipt plus Target's new checked reads.
    @MainActor fileprivate func namespaceRetiredReaderHeldPin(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1, key: String) throws -> Int32? {
        try requireColdSchema2NamespaceCapture(capture)
        guard generationMutationLockDepth == 1 else { throw Self.uncertainOwnerFailure() }
        if key == "lease-root" { return leaseDescriptor }
        if key == "owner-root" { return ownersDescriptor }
        if key == "lease/" + Self.mutationLockName { return mutationLockDescriptor }
        if key == "owners/" + Self.ownerLockName(ownerID) { return ownerLockDescriptor }
        return nil
    }
    fileprivate static func namespaceRetainedReaderControlKind(name: String) throws -> OwnedFileKindV1 {
        if name == Self.mutationLockName { return .generationLeaseControl }
        return try Self.controlKind(for: name)
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    private func namespaceCurrentManifestMemoryFrame(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1) throws {
        try scope.requireManifestOrigin(manifest: self, capture: capture)
        guard opened, !closeAttempted, !coldScratchParentsUncertain,
              !leaseReaderPublicationInFlight, !leaseReaderSettlementInFlight,
              !schema2ColdNotificationCaptureInFlight, !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil,
              postGenerationProjection != nil, coldTerminalTargetObservation != nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
    }
    /// Every role comes from the actual retained closed creator map. A lexical
    /// prefix alone never selects a policy role or an accepted current census.
    fileprivate func withColdNamespaceRetainedNodeOrigin(
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1, path: String,
        _ body: (ColdEraseSchema2NamespaceCurrentNodeOriginV1) throws -> Void) throws {
        try namespaceCurrentManifestMemoryFrame(capture: capture, scope: scope)
        try scope.withManifestSnapshots(manifest: self, capture: capture) { first, after in
            let separator = path.firstIndex(of: "/")
            let branch = separator.map { String(path[..<$0]) } ?? path
            let leaf = separator.map { String(path[path.index(after: $0)...]) }
            guard !branch.isEmpty, let afterBranch = after.operationsChildren[branch],
                  branch != "ScratchDataV1", branch != "ProtectedIngressReceiptsV1",
                  leaf == nil || (!(leaf!.isEmpty) && !leaf!.contains("/")) else {
                throw StoreMigrationFailure.invalidIdentity
            }
            if branch == EraseSchema2ColdNotificationSourceV1.creationRecordName {
                guard leaf == nil, let pin = operationsChildren[branch], pin.descriptor >= 0,
                      let fact = schema2ColdNotificationCreationFact,
                      let bytes = schema2ColdNotificationCreationBytes,
                      bytes == schema2ColdNotificationExpectedCreationBytes,
                      schema2ColdNotificationCreationRecord == schema2ColdNotificationExpectedCreationRecord,
                      case .regular(let retainedFact, let retainedSHA) = afterBranch,
                      retainedFact == Self.coldScratchFullFactString(fact),
                      try Self.coldScratchNotificationDigestMatches(bytes, sha: retainedSHA) else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                try body(.init(provenance: .generatedCreator, kind: .journal,
                    fullFact: Self.coldScratchFullFactString(fact), members: nil, bytes: bytes,
                    policy: nil, creatorDescriptor: pin.descriptor, requiresUntouchedOriginal: false))
            } else {
                guard case .directory(let rootFact, _) = afterBranch,
                      let root = operationsChildren[branch], root.descriptor >= 0 else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                let names: [String], pin: Opened?, bytes: Data?, full: String?, kind: OwnedFileKindV1
                if branch == AppLockNotificationControlStoreV1.rootName {
                    guard let source = schema2ColdNotificationWitness else { throw StoreMigrationFailure.invalidIdentity }
                    names = schema2ColdNotificationProjectedNames ?? source.names
                    let facts = schema2ColdNotificationProjectedFacts ?? source.leafFacts
                    let payloads = schema2ColdNotificationProjectedBytes ?? source.leafBytes
                    guard names.count == schema2ColdNotificationFiles.count,
                          facts.count == names.count, payloads.count == names.count else {
                        throw StoreMigrationFailure.invalidIdentity
                    }
                    if let leaf {
                        guard names.contains(leaf), let fact = facts[leaf],
                              let selected = schema2ColdNotificationFiles[leaf], let raw = payloads[leaf] else {
                            throw StoreMigrationFailure.invalidIdentity
                        }
                        pin = selected; bytes = raw; full = Self.coldScratchFullFactString(fact)
                        kind = [AppLockNotificationControlStoreV1.pendingName,
                            AppLockNotificationControlStoreV1.mappingPendingName,
                            AppLockNotificationControlStoreV1.erasePendingName,
                            EraseSchema2ColdNotificationSourceV1.ownedIDsTemporaryName,
                            EraseSchema2ColdNotificationSourceV1.drainTemporaryName].contains(leaf)
                            ? .journalTemporary : .journal
                    } else { pin = root; bytes = nil; full = rootFact; kind = .stagingDirectory }
                } else if branch == "schema-migration" {
                    guard let capturedMigrationNames, capturedMigrationBytes.count == migrationFiles.count,
                          capturedMigrationNames.count == migrationFiles.count else { throw StoreMigrationFailure.invalidIdentity }
                    names = capturedMigrationNames; pin = leaf.flatMap { migrationFiles[$0] } ?? (leaf == nil ? root : nil)
                    bytes = leaf.flatMap { capturedMigrationBytes[$0] }; full = leaf == nil ? rootFact : nil
                    kind = leaf == nil ? .stagingDirectory : .journal
                } else if branch == "deletion" {
                    guard let capturedDeletionNames, capturedDeletionBytes.count == deletionFiles.count,
                          capturedDeletionNames.count == deletionFiles.count else { throw StoreMigrationFailure.invalidIdentity }
                    names = capturedDeletionNames; pin = leaf.flatMap { deletionFiles[$0] } ?? (leaf == nil ? root : nil)
                    bytes = leaf.flatMap { capturedDeletionBytes[$0] }; full = leaf == nil ? rootFact : nil
                    kind = leaf == nil ? .stagingDirectory : .journal
                } else if branch == "finalization" {
                    guard let capturedFinalizationNames, capturedFinalizationBytes.count == finalizationFiles.count,
                          capturedFinalizationNames.count == finalizationFiles.count else { throw StoreMigrationFailure.invalidIdentity }
                    names = capturedFinalizationNames; pin = leaf.flatMap { finalizationFiles[$0] } ?? (leaf == nil ? root : nil)
                    bytes = leaf.flatMap { capturedFinalizationBytes[$0] }; full = leaf == nil ? rootFact : nil
                    kind = leaf == nil ? .stagingDirectory : .journal
                } else { throw StoreMigrationFailure.invalidIdentity }
                guard let pin, pin.descriptor >= 0, leaf == nil || (names.contains(leaf!) && bytes != nil) else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                // Migration/deletion/finalization leaves have Original9 pins,
                // not new writer full11. They MUST remain untouched original.
                // A changed root instead binds genuine Source-after full11.
                let unchanged = leaf != nil && branch != AppLockNotificationControlStoreV1.rootName
                try body(.init(provenance: unchanged ? .originalCreator : .generatedCreator,
                    kind: kind, fullFact: full, members: leaf == nil ? names : nil,
                    bytes: bytes, policy: nil, creatorDescriptor: pin.descriptor,
                    requiresUntouchedOriginal: unchanged))
                if leaf == nil, first.operationsChildren[branch] == nil {
                    guard branch == AppLockNotificationControlStoreV1.rootName else {
                        throw StoreMigrationFailure.invalidIdentity
                    }
                }
            }
        }
        try namespaceCurrentManifestMemoryFrame(capture: capture, scope: scope)
    }

    /// Actual postcontent creator bridge. Both own-writer and Original9
    /// conservation checks stay explicit; the old pre-Seed Scope is not used.
    func requireColdNamespaceGeneratedNodeOrigin(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1, branch: String, relativePath: String,
        fact: EraseColdControlLeafFactV1, firstNineFact: String,
        originalFirstNineFact: String?, originalSHA256: String?, sha256: String?, members: [String]?,
        requireCreatorPin: (Int32) throws -> Void) throws {
        guard relativePath == branch || relativePath.hasPrefix(branch + "/") else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try withColdNamespaceRetainedNodeOrigin(capture: capture, scope: scope, path: relativePath) { origin in
            guard origin.members == members, (members != nil) == (fact.mode & S_IFMT == S_IFDIR),
                  fact.user == Darwin.geteuid(), let pin = origin.creatorDescriptor else {
                throw StoreMigrationFailure.invalidIdentity
            }
            if let expected = origin.fullFact {
                guard expected == Self.coldScratchFullFactString(fact) else { throw StoreMigrationFailure.invalidIdentity }
            }
            if origin.requiresUntouchedOriginal {
                guard originalFirstNineFact == firstNineFact, originalSHA256 == sha256 else {
                    throw StoreMigrationFailure.invalidIdentity
                }
            }
            if let bytes = origin.bytes {
                guard members == nil, fact.links == 1, fact.size == bytes.count,
                      let sha256, try Self.coldScratchNotificationDigestMatches(bytes, sha: sha256) else {
                    throw StoreMigrationFailure.invalidIdentity
                }
            }
            try requireCreatorPin(pin)
        }
    }
}
// POSTCONTENT_NAMESPACE_CURRENT_ORIGIN_BRIDGES_V1_END

// POSTCONTENT_NAMESPACE_WHOLE_OPERATIONS_READ_V1_BEGIN
@MainActor
final class ColdEraseSchema2NamespaceCurrentObservedNodeV1 {
    fileprivate struct Storage {
        let resource: ColdEraseSchema2NamespaceCurrentReadResourceV1
        let scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let pass: UInt8
        let ordinal: UInt64
        let path: String
        let information: stat
        let policy: TemporalPolicyObservationV1
        let policyCode: UInt64
        let contentSHA256: String?
        let members: [String]?
        let declaredBackingBytes: UInt64
    }
    fileprivate let storage: Storage
    var pass: UInt8 { storage.pass }
    var ordinal: UInt64 { storage.ordinal }
    var path: String { storage.path }
    var information: stat { storage.information }
    var policy: TemporalPolicyObservationV1 { storage.policy }
    var contentSHA256: String? { storage.contentSHA256 }
    var members: [String]? { storage.members }
    static func requiredBackingBytes(pathUTF8Count: UInt64, memberUTF8Count: UInt64) throws -> UInt64 {
        try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<Storage>.stride),
            pathUTF8Count, memberUTF8Count, 64,
            UInt64(4 * MemoryLayout<String>.stride + 2 * MemoryLayout<stat>.stride
                + MemoryLayout<TemporalPolicyObservationV1>.stride))
    }
    fileprivate init(resource: ColdEraseSchema2NamespaceCurrentReadResourceV1,
        ordinal: UInt64, policy: TemporalPolicyObservationV1, memberBytes: UInt64) throws {
        guard let information = resource.storage.information else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage = Storage(resource: resource, scope: resource.storage.window.storage.scope,
            capture: resource.storage.window.storage.capture, pass: resource.storage.pass,
            ordinal: ordinal, path: resource.storage.path, information: information,
            policy: policy, policyCode: try ColdEraseSchema2NamespacePolicyDataCodecV1.encode(policy),
            contentSHA256: resource.storage.contentSHA256, members: resource.storage.origin.members,
            declaredBackingBytes: try Self.requiredBackingBytes(
                pathUTF8Count: UInt64(resource.storage.path.utf8.count), memberUTF8Count: memberBytes))
    }
    func actualBackingBytes() throws -> UInt64 { storage.declaredBackingBytes }
    func requireAssociation(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1, pass: UInt8, ordinal: UInt64) throws {
        guard storage.scope === scope, storage.capture === capture, storage.pass == pass,
              storage.ordinal == ordinal, storage.resource.storage.row === self,
              storage.resource.storage.window.storage.scope === scope,
              storage.resource.storage.window.storage.capture === capture else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func requireCheckedResourceReturn(scope: ColdEraseSchema2NamespaceCurrentPrefixScopeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        try requireAssociation(scope: scope, capture: capture, pass: pass, ordinal: ordinal)
        try storage.resource.requireCheckedRowReturn(self)
    }
}

@MainActor
fileprivate final class ColdEraseSchema2NamespaceCurrentCursorV1 {
    fileprivate struct Storage {
        let resource: ColdEraseSchema2NamespaceCurrentReadResourceV1
        let pass: UInt8
        var descriptor: Int32 = -1
        var stream: UnsafeMutablePointer<DIR>?
        var enteredStream: UnsafeMutablePointer<DIR>?
        var openResult: Int32?
        var openErrno: Int32?
        var heldResult: Int32?
        var heldErrno: Int32?
        var heldInformation: stat?
        var adoptResult: Int64?
        var adoptErrno: Int32?
        var closeResult: Int32?
        var closeErrno: Int32?
        var closeEntered = false
        var entryResult: Int64?
        var entryErrno: Int32?
        var latestEntry: dirent?
        var latestName: String?
        var calls: UInt64 = 0
        var eof = false
        var dot = false
        var dotdot = false
        var count: UInt64 = 0
        var bitmap: UnsafeMutablePointer<UInt8>?
        var bitmapCapacity: Int = 0
        var bitmapInitialized: Int = 0
        var checked = false
        var failure: Error?
    }
    fileprivate var storage: Storage
    fileprivate init(resource: ColdEraseSchema2NamespaceCurrentReadResourceV1, pass: UInt8) {
        storage = Storage(resource: resource, pass: pass)
    }
    fileprivate func scan() throws {
        do {
