        case .pathUTF8Bytes: actual = storage.pathCapacity; initialized = storage.initializedPathCells; present = storage.paths != nil
        case .childEdges: actual = storage.edgeCapacity; initialized = storage.initializedEdgeCells; present = storage.edges != nil
        case .retainedNodeSlots: actual = storage.retainedNodeCapacity; initialized = storage.initializedNodeCells; present = storage.retainedNodes != nil
