        guard low < parent.childCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let child = storage.entries![storage.edges![parent.childStart + low]]
        guard child.nameByteCount == byteCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for i in 0..<byteCount where storage.paths![child.nameOffset + i] != bytes[i] { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
