    func requireCheckedTraversalReturn(reservation: ColdEraseScratchBirthCurrentTraversalReservationV1) throws {
        guard storage.reservation === reservation, storage.state == .checked, storage.retainedFailure == nil,
              storage.partitionComplete, storage.completedPasses == 2, storage.privateTraversalHelperReturned,
              storage.activeNodeCount == 0, storage.retainedNodeCount == storage.retainedNodeCapacity,
              storage.recordedBackingCount == 6 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
