/// Source-owned selected/original/current partition only after actual two-pass
/// entered capture. Not an all-Operations role issuer or effect/Seed authority.
@MainActor final class ColdEraseScratchBirthUntouchedSelectedOriginalProjectionV1 {
    fileprivate enum State: Equatable { case available, checkingBefore, iterating, checkingAfter, consumed, uncertain }
    fileprivate struct Storage {
        let traversal: ColdEraseScratchBirthCurrentTraversalV1
        var state: State = .available
        var nextIndex = 0
        var callbackEntered = false
        var callbackReturned = false
        var privateIteratorReturned = false
