        storage.contentDigest = (a, b, c, d)
        // Scalar ASCII renderer, no 32-String map/join graph.
        var hex = (UInt64(0), UInt64(0), UInt64(0), UInt64(0), UInt64(0), UInt64(0), UInt64(0), UInt64(0))
        let text = withUnsafeMutableBytes(of: &hex) { output -> String in
            var position = 0
            for byte in digest {
                let high = byte >> 4, low = byte & 15
                output[position] = high < 10 ? high + 48 : high + 87
                output[position + 1] = low < 10 ? low + 48 : low + 87
                position += 2
            }
            return String(decoding: output, as: UTF8.self)
        }
        storage.contentSHA256 = text
        guard storage.readOffset == storage.expectedBytes, storage.eofObserved,
              text == storage.expectedSHA256,
              storage.sourceChildDigest == nil || text == storage.sourceChildDigest else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let evidence = ReadEvidence(calls: storage.readCalls, offset: storage.readOffset,
            eofObserved: storage.eofObserved, digest: (a, b, c, d), sha256: text)
        if storage.readPasses == 1 {
            guard storage.beforePolicyRead == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.beforePolicyRead = evidence
