    private static func invokeRowConsumer(_ row: ColdEraseScratchBirthCurrentTraversalObservedRowV1,
        body: (ColdEraseScratchBirthCurrentTraversalObservedRowV1) throws -> Void) throws { try body(row) }
    func requireCheckedRowConsumption(reservation: ColdEraseScratchBirthCurrentTraversalReservationV1) throws {
