              storage.retainedFailure == nil, storage.openResult != nil,
              storage.closeResult == 0, storage.closeErrno != nil, storage.descriptor == -1,
              storage.call?.consumed == true, storage.rowConsumed, storage.rowConsumerReturned,
              storage.policyConsumed, storage.row != nil,
              !storage.isDirectory || (storage.cursorBefore?.isChecked == true && storage.cursorAfter?.isChecked == true),
              storage.isDirectory || (storage.readPasses == 2 && storage.beforePolicyRead != nil
                && storage.afterPolicyRead != nil && storage.eofObserved && storage.readOffset == storage.expectedBytes
                && storage.readReleaseEntered && storage.readDeallocationReturned
                && storage.readDeinitializedCount == storage.readCapacity
