    private func releaseCheckedReadBacking() throws {
        guard storage.state == .consumed, storage.closeResult == 0,
              storage.descriptor == -1, storage.rowConsumed, storage.rowConsumerReturned,
              storage.policyConsumed, storage.readPasses == 2,
              storage.beforePolicyRead != nil, storage.afterPolicyRead != nil,
              storage.eofObserved, !storage.readReleaseEntered,
