              storage.retainedFailure == nil, storage.readReleaseEntered,
              storage.readDeallocationReturned, storage.readDeinitializedCount == byteCount,
              storage.readCapacity == byteCount, storage.readInitialized == 0,
              storage.readBacking == nil, storage.eofObserved,
