        try operation.requireColdScratchManifestFrame(manifest: self, store: store,
            projection: projection, scope: scope)
        try body(.init(support: support.path, caches: caches.path, temporary: temporary.path))
        try operation.requireColdScratchRangeOwner(ranges, scope: scope, store: store)
        try operation.requireColdScratchManifestFrame(manifest: self, store: store,
            projection: projection, scope: scope)
    }

    /// Source-owned current branch origin, comparison only. The Native owner
    /// separately proves every actual node/byte/census against this exact
    /// retained after snapshot. A caller value never grants a policy effect.
    func requireColdScratchPreSeedCurrentBranchOrigin(name: String,
        creator: ColdEraseScratchPreSeedCreatorProjectionV1,
        ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1,
        scope: ColdEraseScratchCleanupHeldGScopeV1) throws {
        try creator.requireBound(manifest: self, ranges: ranges, store: store, operation: operation, scope: scope)
        let first = creator.storage.first, after = creator.storage.after
        guard let projection = postGenerationProjection, coldScratchStore === store,
              opened, !closeAttempted, !coldScratchParentsUncertain,
              !leaseReaderPublicationInFlight, !leaseReaderSettlementInFlight,
              !schema2ColdNotificationCaptureInFlight, !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil,
              let source = schema2ColdNotificationWitness,
              after.operationsChildren[name] != nil else { throw StoreMigrationFailure.invalidIdentity }
        try operation.requireColdScratchRangeOwner(ranges, scope: scope, store: store)
        guard try operation.requireColdScratchRetainedNotificationLineage(manifest: self,
            store: store, ranges: ranges, scope: scope) === source else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try operation.requireColdScratchManifestFrame(manifest: self, store: store,
            projection: projection, scope: scope)
        if first.operationsChildren[name] == after.operationsChildren[name] { return }
        switch name {
        case "generation-leases":
            guard let pin = operationsChildren[name], let fact = coldScratchProjectedLeaseFact ?? coldScratchFirstLeaseFact,
                  case .directory(let current, _) = after.operationsChildren[name],
                  current == Self.coldScratchFullFactString(fact), pin.descriptor >= 0,
                  targetLiveOpenState == .settled, coldScratchParentLoanInFlight else {
                throw StoreMigrationFailure.invalidIdentity
            }
        case AppLockNotificationControlStoreV1.rootName:
            guard let fact = schema2ColdNotificationProjectedRootFact ?? source.rootFact,
                  case .directory(let current, _) = after.operationsChildren[name],
                  current == Self.coldScratchFullFactString(fact),
                  operationsChildren[name] != nil,
                  (schema2ColdNotificationProjectedNames ?? source.names).count <= 10,
                  (schema2ColdNotificationProjectedNames ?? source.names).count == schema2ColdNotificationFiles.count else {
                throw StoreMigrationFailure.invalidIdentity
            }
        case EraseSchema2ColdNotificationSourceV1.creationRecordName:
            guard let fact = schema2ColdNotificationCreationFact,
                  let bytes = schema2ColdNotificationCreationBytes,
                  schema2ColdNotificationCreationRecord == schema2ColdNotificationExpectedCreationRecord,
                  bytes == schema2ColdNotificationExpectedCreationBytes,
                  case .regular(let current, let sha) = after.operationsChildren[name],
                  current == Self.coldScratchFullFactString(fact),
                  try Self.coldScratchNotificationDigestMatches(bytes, sha: sha),
                  operationsChildren[name] != nil else { throw StoreMigrationFailure.invalidIdentity }
        case "schema-migration":
            guard migration != nil, capturedMigrationNames != nil,
                  capturedMigrationBytes.count == migrationFiles.count else { throw StoreMigrationFailure.invalidIdentity }
        case "deletion":
            guard operationsChildren[name] != nil, capturedDeletionNames != nil,
                  capturedDeletionBytes.count == deletionFiles.count else { throw StoreMigrationFailure.invalidIdentity }
        case "finalization":
            guard operationsChildren[name] != nil, capturedFinalizationNames != nil,
                  capturedFinalizationBytes.count == finalizationFiles.count else { throw StoreMigrationFailure.invalidIdentity }
        default:
            // No inferred creator, temporary/stage role or generic prefix.
            throw StoreMigrationFailure.invalidIdentity
        }
    }
}
