extension EraseSchema2ColdManifestOwnerV1 {
    /// Retained creator maps, not an aggregate digest-as-permission. The
    /// caller independently holds its entered current node and positively
    /// compares this real borrowed creator pin before/after this Void borrow.
    func requireColdScratchPreSeedGeneratedNodeOrigin(branch: String, relativePath: String,
        fact: EraseColdControlLeafFactV1, firstNineFact: String,
        originalFirstNineFact: String?, originalSHA256: String?, sha256: String?, members: [String]?,
        creator: ColdEraseScratchPreSeedCreatorProjectionV1,
        ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1, scope: ColdEraseScratchCleanupHeldGScopeV1,
        loan: ColdEraseScratchBorrowedParentsV1, _ requireCreatorPin: (Int32) throws -> Void) throws {
        try requireColdScratchPreSeedCurrentBranchOrigin(name: branch, creator: creator,
            ranges: ranges, store: store, operation: operation, scope: scope)
        guard relativePath == branch || relativePath.hasPrefix(branch + "/"),
              fact.user == Darwin.geteuid(), fact.mode & S_IFMT == (members == nil ? S_IFREG : S_IFDIR) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        func requirePin(_ pin: Opened) throws {
            guard pin.descriptor >= 0, pin.fact.device == fact.device, pin.fact.inode == fact.inode,
                  pin.fact.mode == fact.mode, pin.fact.links == fact.links,
                  pin.fact.size == fact.size, pin.fact.modifiedSeconds == fact.modifiedSeconds,
                  pin.fact.modifiedNanoseconds == fact.modifiedNanoseconds,
                  pin.fact.changedSeconds == fact.changedSeconds, pin.fact.changedNanoseconds == fact.changedNanoseconds else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try requireCreatorPin(pin.descriptor)
        }
        func requireBytes(_ bytes: Data) throws {
            guard members == nil, fact.links == 1, fact.size == bytes.count,
                  let sha256, try Self.coldScratchNotificationDigestMatches(bytes, sha: sha256) else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
        if branch == "generation-leases" {
            try scope.requirePreSeedRegistryNodeOrigin(relativePath: relativePath, fact: fact,
                firstNineFact: firstNineFact, originalFirstNineFact: originalFirstNineFact,
                originalSHA256: originalSHA256, sha256: sha256, members: members,
                ranges: ranges, store: store, operation: operation, loan: loan,
                requireCreatorPin: requireCreatorPin)
        } else if relativePath == branch {
            guard let pin = operationsChildren[branch], members != nil || branch == EraseSchema2ColdNotificationSourceV1.creationRecordName else {
                throw StoreMigrationFailure.invalidIdentity
            }
            try requireCreatorPin(pin.descriptor) // mutable directory origin is authentic Source-after full11, not stale Opened.fact9
            if branch == AppLockNotificationControlStoreV1.rootName {
                guard members == (schema2ColdNotificationProjectedNames ?? schema2ColdNotificationWitness?.names) else { throw StoreMigrationFailure.invalidIdentity }
            } else if branch == "schema-migration" { guard members == capturedMigrationNames else { throw StoreMigrationFailure.invalidIdentity } }
            else if branch == "deletion" { guard members == capturedDeletionNames else { throw StoreMigrationFailure.invalidIdentity } }
            else if branch == "finalization" { guard members == capturedFinalizationNames else { throw StoreMigrationFailure.invalidIdentity } }
            else if branch == EraseSchema2ColdNotificationSourceV1.creationRecordName {
                guard let bytes = schema2ColdNotificationCreationBytes, let origin = schema2ColdNotificationCreationFact,
                      origin == fact, bytes == schema2ColdNotificationExpectedCreationBytes,
                      schema2ColdNotificationCreationRecord == schema2ColdNotificationExpectedCreationRecord else { throw StoreMigrationFailure.invalidIdentity }
                try requireBytes(bytes)
            } else { throw StoreMigrationFailure.invalidIdentity }
        } else {
            let name = String(relativePath.dropFirst(branch.count + 1)) // bounded caller-prepaid lexical relative spelling
            guard !name.isEmpty, !name.contains("/"), members == nil, fact.mode & mode_t(0o7777) == mode_t(0o600) else { throw StoreMigrationFailure.invalidIdentity }
            if branch == AppLockNotificationControlStoreV1.rootName {
                guard let source = schema2ColdNotificationWitness,
                      let pin = schema2ColdNotificationFiles[name],
                      let origin = (schema2ColdNotificationProjectedFacts ?? source.leafFacts)[name],
                      let bytes = (schema2ColdNotificationProjectedBytes ?? source.leafBytes)[name],
                      origin == fact, (schema2ColdNotificationProjectedNames ?? source.names).contains(name) else { throw StoreMigrationFailure.invalidIdentity }
                try requirePin(pin); try requireBytes(bytes)
            } else if branch == "schema-migration" {
                guard let pin = migrationFiles[name], let bytes = capturedMigrationBytes[name], capturedMigrationNames?.contains(name) == true else { throw StoreMigrationFailure.invalidIdentity }
                try requirePin(pin); try requireBytes(bytes)
            } else if branch == "deletion" {
                guard let pin = deletionFiles[name], let bytes = capturedDeletionBytes[name], capturedDeletionNames?.contains(name) == true else { throw StoreMigrationFailure.invalidIdentity }
                try requirePin(pin); try requireBytes(bytes)
            } else if branch == "finalization" {
                guard let pin = finalizationFiles[name], let bytes = capturedFinalizationBytes[name], capturedFinalizationNames?.contains(name) == true else { throw StoreMigrationFailure.invalidIdentity }
                try requirePin(pin); try requireBytes(bytes)
            } else { throw StoreMigrationFailure.invalidIdentity }
        }
        try requireColdScratchPreSeedCurrentBranchOrigin(name: branch, creator: creator,
            ranges: ranges, store: store, operation: operation, scope: scope)
    }
}

extension ColdEraseScratchCleanupHeldGScopeV1 {
    /// Continuous already-held G; no recursive acquisition or ordinary census.
    /// Main's exact retained allocation getter is a separate reviewed input.
    fileprivate func requirePreSeedRegistryNodeOrigin(relativePath: String,
        fact: EraseColdControlLeafFactV1, firstNineFact: String, originalFirstNineFact: String?,
        originalSHA256: String?, sha256: String?, members: [String]?,
        ranges: ColdEraseScratchPayloadRangesV1, store: EraseIntentStore,
        operation: EraseColdPreparationOperationV1, loan: ColdEraseScratchBorrowedParentsV1,
        requireCreatorPin: (Int32) throws -> Void) throws {
        try requireOrigin(operation: operation, store: store)
        guard state == .held, self.operation === operation, self.store === store,
              let registry, let activity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let allocation = try operation.requireColdScratchPreSeedTargetReaderAllocation(ranges: ranges,
            store: store, scope: self, loan: loan)
        try registry.requirePreSeedRegistryNodeOrigin(scope: self, operation: operation, store: store,
            activity: activity, allocation: allocation, relativePath: relativePath,
            fact: fact, firstNineFact: firstNineFact, originalFirstNineFact: originalFirstNineFact,
            originalSHA256: originalSHA256, sha256: sha256, members: members,
            requireCreatorPin: requireCreatorPin)
        guard try operation.requireColdScratchPreSeedTargetReaderAllocation(ranges: ranges,
            store: store, scope: self, loan: loan) === allocation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireOrigin(operation: operation, store: store)
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func requirePreSeedRegistryNodeOrigin(scope: ColdEraseScratchCleanupHeldGScopeV1,
        operation: EraseColdPreparationOperationV1, store: EraseIntentStore,
        activity: GenerationTemporalActivityHandleV1, allocation: GenerationLeaseAllocationAttemptV1,
        relativePath: String, fact: EraseColdControlLeafFactV1, firstNineFact: String,
        originalFirstNineFact: String?, originalSHA256: String?, sha256: String?, members: [String]?,
        requireCreatorPin: (Int32) throws -> Void) throws {
        try requireColdScratchNonrecursiveScope(scope, operation: operation, store: store, activity: activity)
        guard generationMutationLockDepth == 1, allocation.matches(registry: self),
              allocation.schema2ColdRegistryRenamed, !allocation.schema2ColdRenameProjectionUncertain,
              allocation.schema2ColdRecordDurable, !allocation.schema2ColdUncertainClose,
              let record = allocation.schema2ColdRecordBytes, let replacement = allocation.schema2ColdReplacementBytes,
              allocation.schema2ColdRecordDescriptor >= 0,
              allocation.schema2ColdOriginalDescriptor == -1, allocation.schema2ColdTemporaryDescriptor == -1 else {
            throw Self.uncertainOwnerFailure()
        }
        func bytesMatch(_ bytes: Data) throws {
            guard members == nil, fact.size == bytes.count, fact.links == 1,
                  fact.mode & mode_t(0o7777) == mode_t(0o600), fact.user == Darwin.geteuid(),
                  let sha256, sha256.utf8.count == 64 else { throw Self.uncertainOwnerFailure() }
            var iterator = sha256.utf8.makeIterator()
            func ascii(_ n: UInt8) -> UInt8 { n < 10 ? n + 48 : n + 87 }
            for byte in SHA256.hash(data: bytes) {
                guard iterator.next() == ascii(byte >> 4), iterator.next() == ascii(byte & 15) else { throw Self.uncertainOwnerFailure() }
            }
            guard iterator.next() == nil else { throw Self.uncertainOwnerFailure() }
        }
        if relativePath == "generation-leases" {
            guard members != nil else { throw Self.uncertainOwnerFailure() }
            try requireCreatorPin(leaseDescriptor)
        } else if relativePath == "generation-leases/owners" {
            guard let members, members.count <= Self.maximumOwnerCount,
                  members.contains(Self.ownerLockName(ownerID)) else { throw Self.uncertainOwnerFailure() }
            try requireCreatorPin(ownersDescriptor)
        } else if relativePath == "generation-leases/mutation.lock" {
            try bytesMatch(Data()); try requireCreatorPin(mutationLockDescriptor)
            guard originalFirstNineFact == firstNineFact else { throw Self.uncertainOwnerFailure() }
        } else if relativePath == "generation-leases/owners/" + Self.ownerLockName(ownerID) {
            try bytesMatch(Data()); try requireCreatorPin(ownerLockDescriptor)
        } else if relativePath == "generation-leases/cold-reader-publication.v1" {
            try bytesMatch(record); try requireCreatorPin(allocation.schema2ColdRecordDescriptor)
        } else if relativePath == "generation-leases/registry.json" {
            guard let snapshot = allocation.schema2ColdTemporarySnapshot,
                  snapshot.identity.device == fact.device, snapshot.identity.inode == fact.inode,
                  snapshot.identity.type == S_IFREG, snapshot.identity.linkCount == fact.links,
                  snapshot.byteCount == fact.size, snapshot.modificationSeconds == fact.modifiedSeconds,
                  snapshot.modificationNanoseconds == fact.modifiedNanoseconds,
                  snapshot.changeSeconds == fact.changedSeconds, snapshot.changeNanoseconds == fact.changedNanoseconds else {
                throw Self.uncertainOwnerFailure()
            }
            try bytesMatch(replacement)
        } else {
            // Existing controls/other owners must be exact authentic originals.
            // Current producer never invents a dead-owner/pending-temp proof.
            guard originalFirstNineFact == firstNineFact, originalSHA256 == sha256 else { throw Self.uncertainOwnerFailure() }
            if relativePath.hasPrefix("generation-leases/owners/") {
                let name = String(relativePath.dropFirst("generation-leases/owners/".count))
                guard name.hasSuffix(".lock"), !name.contains("/"), let id = UUID(uuidString: String(name.dropLast(5))),
                      Self.ownerLockName(id) == name else { throw Self.uncertainOwnerFailure() }
                try bytesMatch(Data())
            } else {
                guard relativePath == "generation-leases/prune-intent.json" || relativePath == "generation-leases/last-prune-receipt.json" || relativePath == "generation-leases/original-reader-publication.v1",
                      members == nil else { throw Self.uncertainOwnerFailure() }
            }
        }
        try requireColdScratchNonrecursiveScope(scope, operation: operation, store: store, activity: activity)
    }
}

