@MainActor fileprivate final class ColdEraseSchema2ReaderJournalCensusV4 {
    fileprivate let owner: ColdEraseSchema2ReaderCensusOwnerV4
    fileprivate let base: GenerationLeaseRegistryV1.ColdSchema2RetirementCensusV1
    fileprivate let flags: [String: UInt32]
    fileprivate let directoryPolicies: [String: TemporalPolicyObservationV1]
    fileprivate let migrationNames: [String]?
