        base: GenerationLeaseRegistryV1.ColdSchema2RetirementCensusV1,
        flags: [String: UInt32], directories: [String: TemporalPolicyObservationV1], migrationNames: [String]?) throws {
        guard Set(base.facts.keys) == Set(flags.keys), base.facts.count <= 80,
              Set(directories.keys) == Set(base.facts.keys.filter { !$0.contains("/") }),
              directories.values.allSatisfy({ $0.state == .strictComplete && $0.isDirectory == true }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        guard (base.facts["migration-root"] != nil) == (migrationNames != nil) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        self.owner = owner; self.base = base; self.flags = flags; directoryPolicies = directories
        self.migrationNames = migrationNames
    }
    fileprivate func isSameClosedData(as other: ColdEraseSchema2ReaderJournalCensusV4) -> Bool {
        base == other.base && flags == other.flags && directoryPolicies == other.directoryPolicies && migrationNames == other.migrationNames
    }
    fileprivate func policy(_ key: String) -> TemporalPolicyObservationV1? {
        directoryPolicies[key] ?? base.policies[key]
    }
}

/// Registered on the real Native Request before any syscall, allocation or
/// PFP call. Every leaf is a separate once-close owner; uncertainty retains it.
@MainActor final class ColdEraseSchema2ReaderCensusOwnerV4 {
    enum Stage: Equatable { case prepared, replacement, final }
    fileprivate struct Entry {
        let ordinal: UInt64, kind: UInt64, descriptor: Int32, offset: UInt64, requested: Int
        var returned: Int64?, savedErrno: Int32?, information: stat?
    }
    fileprivate final class Leaf {
        var descriptor: Int32 = -1
        var opened: Entry?
        var lastRead: Entry?
        var eof: Entry?
