        enum Result { case returned(TemporalPolicyObservationV1), threw(Error) }
        let kind: OwnedFileKindV1, url: URL
        var result: Result?
        var uncertainDescriptor0: Int32?, uncertainDescriptor1: Int32?
        var callbackCount: UInt64 = 0
        var unexpectedCallback = false
        init(kind: OwnedFileKindV1, url: URL) { self.kind = kind; self.url = url }
        static var declaredStoredBytes: UInt64 {
            UInt64(MemoryLayout<OwnedFileKindV1>.stride + MemoryLayout<URL>.stride
                + MemoryLayout<Result?>.stride + 2 * MemoryLayout<Int32?>.stride
                + MemoryLayout<UInt64>.stride + MemoryLayout<Bool>.stride + 128)
        }
    }
    fileprivate let request: ColdEraseSchema2ReaderRetirementRequestV1
    fileprivate let preparation: ColdEraseSchema2ReaderRetirementPreparationV1
    fileprivate let registry: GenerationLeaseRegistryV1
    fileprivate let allocation: GenerationLeaseAllocationAttemptV1
    fileprivate let reader: GenerationLeaseHandleV1
    fileprivate let operation: EraseColdPreparationOperationV1
    fileprivate let activity: GenerationTemporalActivityHandleV1
    fileprivate let exclusion: EraseRetirementExclusionV1
    fileprivate let binding: EraseRetirementBindingV1
    fileprivate let witness: EraseSessionDrainWitnessV1
    fileprivate let stage: Stage
    fileprivate let attempt: ColdEraseSchema2ReaderRetirementAttemptV1?
    fileprivate let completion: ColdEraseSchema2ReaderReplacementCompletionV1?
    fileprivate var directories: [Directory] = []
    fileprivate var leaves: [Leaf] = []
    fileprivate var policies: [PolicyCall] = []
    fileprivate var currentLeaf: Leaf?
    fileprivate var active: Entry?
    fileprivate var last: Entry?
    fileprivate var ordinal: UInt64 = 0
    fileprivate var census = SHA256()
    fileprivate var failure: Error?
    fileprivate var result: ColdEraseSchema2ReaderJournalCensusV4?
    fileprivate var checked = false
    fileprivate init(request: ColdEraseSchema2ReaderRetirementRequestV1,
        preparation: ColdEraseSchema2ReaderRetirementPreparationV1,
        registry: GenerationLeaseRegistryV1, allocation: GenerationLeaseAllocationAttemptV1,
        reader: GenerationLeaseHandleV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        stage: Stage, attempt: ColdEraseSchema2ReaderRetirementAttemptV1?,
        completion: ColdEraseSchema2ReaderReplacementCompletionV1?) {
        self.request = request; self.preparation = preparation; self.registry = registry
        self.allocation = allocation; self.reader = reader; self.operation = operation
        self.activity = activity; self.exclusion = exclusion; self.binding = binding; self.witness = witness
        self.stage = stage; self.attempt = attempt; self.completion = completion
    }
    fileprivate func frame() throws {
        guard failure == nil, !checked else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try request.requireReaderCensusMechanicalFrame(self)
        try registry.requireReaderCensusHeldGFrameV4(self)
    }
    fileprivate func fail(_ error: Error) {
        if failure == nil { failure = error }
        request.poisonOnUncertainEffect()
        operation.poisonColdScratchOwner()
    }
    fileprivate func entered(_ kind: UInt64, descriptor: Int32, offset: UInt64 = 0, count: Int = 0) throws {
        try frame()
        guard active == nil, ordinal < UInt64.max else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        ordinal += 1; active = .init(ordinal: ordinal, kind: kind, descriptor: descriptor,
            offset: offset, requested: count) // entered before each actual syscall
    }
    fileprivate func returned(_ result: Int64, errno: Int32, information: stat? = nil) throws -> Entry {
        guard var entry = active, entry.returned == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        entry.returned = result; entry.savedErrno = errno; entry.information = information
        active = entry; last = entry // raw return and information BEFORE postpredicate
        for word in [entry.ordinal, entry.kind, UInt64(bitPattern: Int64(entry.descriptor)),
            entry.offset, UInt64(entry.requested), UInt64(bitPattern: result), UInt64(bitPattern: Int64(errno))] {
            var little = word.littleEndian
            withUnsafeBytes(of: &little) { census.update(bufferPointer: $0) }
