    fileprivate func statNamed(_ parent: Int32, _ name: String, _ value: inout stat) throws -> Int32 {
        try entered(1, descriptor: parent)
        let result = Darwin.fstatat(parent, name, &value, AT_SYMLINK_NOFOLLOW), saved = errno
        _ = try returned(Int64(result), errno: saved, information: result == 0 ? value : nil)
        return result
    }
    fileprivate func statHeld(_ descriptor: Int32, _ value: inout stat) throws -> Int32 {
        try entered(2, descriptor: descriptor)
        let result = Darwin.fstat(descriptor, &value), saved = errno
        _ = try returned(Int64(result), errno: saved, information: result == 0 ? value : nil)
        return result
    }
    fileprivate func statURL(_ url: URL, _ value: inout stat) throws -> Int32 {
        try entered(3, descriptor: -1)
        let result = Darwin.lstat(url.path, &value), saved = errno
        _ = try returned(Int64(result), errno: saved, information: result == 0 ? value : nil)
        return result
    }
    fileprivate var savedErrno: Int32 {
        get throws {
            guard let value = last?.savedErrno else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return value
        }
    }
    fileprivate func beginLeaf() throws -> Leaf {
        try frame()
        guard currentLeaf == nil, leaves.count < 80 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let leaf = Leaf(); leaves.append(leaf); currentLeaf = leaf
        return leaf
    }
    fileprivate func openLeaf(_ parent: Int32, _ name: String) throws -> Int32 {
        guard let leaf = currentLeaf, leaf.opened == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try entered(4, descriptor: parent)
        let descriptor = Darwin.openat(parent, name, O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        let saved = errno
        if descriptor >= 0 { leaf.descriptor = descriptor } // raw returned owner before anything fallible
        leaf.opened = try returned(Int64(descriptor), errno: saved)
        return descriptor
    }
    fileprivate func readLeaf(_ descriptor: Int32, _ destination: UnsafeMutableRawPointer?,
        _ count: Int, _ offset: off_t) throws -> Int {
        guard let leaf = currentLeaf, leaf.descriptor == descriptor, !leaf.closeEntered,
              count > 0, count <= 65_536, offset >= 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try entered(count == 1 ? 6 : 5, descriptor: descriptor, offset: UInt64(offset), count: count)
        let result = Darwin.pread(descriptor, destination, count, offset), saved = errno
        let entry = try returned(Int64(result), errno: saved)
