        if result == 0 { leaf.eof = entry }
        return result
    }
    fileprivate func closeLeaf(_ leaf: Leaf) throws {
        guard currentLeaf === leaf, !leaf.closeEntered, !leaf.closed else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if leaf.descriptor < 0 {
            guard leaf.opened == nil || leaf.opened!.returned! < 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            leaf.closeEntered = true; leaf.closed = true; currentLeaf = nil; return
        }
        let descriptor = leaf.descriptor
        try entered(7, descriptor: descriptor)
        leaf.closeEntered = true; leaf.descriptor = -1 // fence BEFORE the only close
        let result = Darwin.close(descriptor), saved = errno
        leaf.close = try returned(Int64(result), errno: saved)
        guard result == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        leaf.closed = true; currentLeaf = nil
    }
    fileprivate func observePolicy(_ kind: OwnedFileKindV1, _ url: URL) throws -> TemporalPolicyObservationV1 {
        try frame()
        guard policies.count < 83 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let call = PolicyCall(kind: kind, url: url); policies.append(call) // BEFORE helper entry
        do {
            let value = try ProtectedFilePolicyV1.observeTemporalPolicyWithCheckedClose(kind, at: url,
                retainUncertainDescriptor: { descriptor in
                    if call.callbackCount == 0 { call.uncertainDescriptor0 = descriptor }
                    else if call.callbackCount == 1 { call.uncertainDescriptor1 = descriptor }
                    else { call.unexpectedCallback = true }
                    call.callbackCount += 1
                })
            call.result = .returned(value)
            guard call.callbackCount == 0, !call.unexpectedCallback else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return value // actual DATA; unchanged strict predicate lives in consumer
        } catch {
