    }
    fileprivate func requireClosedResources() throws {
        guard failure == nil, active == nil, currentLeaf == nil,
              leaves.allSatisfy({ $0.closed && $0.descriptor < 0 }),
              directories.allSatisfy({ $0.checkedClosed && $0.descriptor < 0 && $0.stream == nil }),
              policies.allSatisfy({ $0.callbackCount == 0 && !$0.unexpectedCallback && $0.result != nil }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }

    }
    static var declaredCensusStoredAndRawCeiling: UInt64 {
        UInt64(8 * 4_194_304 + 80 * (256 + 128)
            + 80 * Int(Leaf.declaredStoredBytes) + 83 * Int(PolicyCall.declaredStoredBytes)
            + 80 * MemoryLayout<Leaf>.stride + 83 * MemoryLayout<PolicyCall>.stride
