        static var declaredStoredBytes: UInt64 {
            UInt64(2 * MemoryLayout<Int32>.stride + 2 * MemoryLayout<UnsafeMutablePointer<DIR>?>.stride
                + 4 * MemoryLayout<Entry?>.stride + MemoryLayout<stat?>.stride
                + MemoryLayout<dirent?>.stride + MemoryLayout<String?>.stride
                + MemoryLayout<[String]>.stride + 2 * MemoryLayout<Bool>.stride
                + 80 * (128 + MemoryLayout<String>.stride) + 256)
        }
    }
    private func beginDirectory() throws -> Directory {
        try frame()
        guard directories.count < 24 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let actual = Directory(); directories.append(actual) // retained before open/cursor allocation
        return actual
    }
    private func openDirectory(_ value: Directory, parent: Int32, name: String, flags: Int32) throws {
        guard value.opened == nil, value.descriptor < 0, value.stream == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try entered(8, descriptor: parent)
        let fd = Darwin.openat(parent, name, flags | O_NOFOLLOW | O_CLOEXEC), saved = errno
        if fd >= 0 { value.descriptor = fd }
        value.opened = try returned(Int64(fd), errno: saved) // retain raw resource/error before postproof
        guard fd >= 0, fd != parent else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var held = stat(), named = stat()
        guard try statHeld(fd, &held) == 0, try statNamed(parent, name, &named) == 0,
              held.st_mode & S_IFMT == S_IFDIR,
              GenerationLeaseRegistryV1.readerJournalFullFactV4(held) == GenerationLeaseRegistryV1.readerJournalFullFactV4(named),
              held.st_flags == named.st_flags else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        value.before = held
        try frame()
    }
    private func pinDirectory(_ value: Directory, parent: Int32, name: String) throws {
        guard value.descriptor >= 0, !value.closeEntered, let before = value.before else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var held = stat(), named = stat()
        guard try statHeld(value.descriptor, &held) == 0,
              try statNamed(parent, name, &named) == 0,
              GenerationLeaseRegistryV1.readerJournalFullFactV4(held) == GenerationLeaseRegistryV1.readerJournalFullFactV4(before),
              GenerationLeaseRegistryV1.readerJournalFullFactV4(named) == GenerationLeaseRegistryV1.readerJournalFullFactV4(before),
              held.st_flags == before.st_flags, named.st_flags == before.st_flags else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    private func closeDirectory(_ value: Directory) throws {
        guard !value.closeEntered, !value.checkedClosed else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let fd = value.descriptor
        if let stream = value.stream {
            try entered(11, descriptor: fd)
            value.closeEntered = true; value.stream = nil; value.descriptor = -1
            let result = Darwin.closedir(stream), saved = errno
            value.closedReturn = try returned(Int64(result), errno: saved)
            guard result == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            value.checkedClosed = true
        } else if fd >= 0 {
            try entered(12, descriptor: fd)
            value.closeEntered = true; value.descriptor = -1
            let result = Darwin.close(fd), saved = errno
            value.closedReturn = try returned(Int64(result), errno: saved)
            guard result == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            value.checkedClosed = true
        } else {
            guard value.opened == nil || value.opened!.returned! < 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            value.closeEntered = true; value.checkedClosed = true
        }
        // Failed close retains its exact entered FD/pointer and raw return;
        // the owned descriptor is already fenced and cannot be retried.
    }
    fileprivate func withOpen<Value>(parent: Int32, name: String, flags: Int32,
        _ body: (Int32) throws -> Value) throws -> Value {
        let actual = try beginDirectory()
        do {
            try openDirectory(actual, parent: parent, name: name, flags: flags)
            let result = try body(actual.descriptor)
            try pinDirectory(actual, parent: parent, name: name)
            try closeDirectory(actual); try frame()
            return result
        } catch {
            if !actual.closeEntered { try closeDirectory(actual) }
            throw error
        }
    }
    fileprivate func boundedNames(in parent: Int32, maximumCount: Int) throws -> [String] {
        guard maximumCount >= 0, maximumCount <= 100_000 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let actual = try beginDirectory()
        do {
            try openDirectory(actual, parent: parent, name: ".", flags: O_RDONLY | O_DIRECTORY)
            try entered(9, descriptor: actual.descriptor)
            let stream = Darwin.fdopendir(actual.descriptor), saved = errno
            actual.lastReturnedStream = stream
            if let stream { actual.stream = stream }
            actual.adopted = try returned(stream == nil ? -1 : 0, errno: saved)
            guard let stream else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try pinDirectory(actual, parent: parent, name: ".")
            while true {
                try pinDirectory(actual, parent: parent, name: ".")
                guard actual.readCount <= UInt64(maximumCount + 2) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try entered(10, descriptor: actual.descriptor)
                errno = 0
                let entry = Darwin.readdir(stream), savedRead = errno
                if let entry { actual.lastDirectoryEntry = entry.pointee }
                let raw = try returned(entry == nil ? 0 : 1, errno: savedRead)
                guard savedRead == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                guard let entry else { actual.eof = raw; break }
                actual.readCount += 1
                guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry), name.utf8.count <= 128 else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                actual.lastName = name // actual decode retained before bounded vocabulary postpredicate
                if name == "." || name == ".." {
                    let bit: UInt8 = name == "." ? 1 : 2
                    guard actual.dotSeen & bit == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    actual.dotSeen |= bit
                } else {
                    guard OperationalDiagnosticsBoundsV1.validRelativeName(name),
                          actual.names.count < maximumCount, !actual.names.contains(name) else {
                        throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    actual.names.append(name)
                }
            }
            try pinDirectory(actual, parent: parent, name: ".")
            guard actual.eof?.returned == 0, actual.eof?.savedErrno == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            actual.names.sort()
            try closeDirectory(actual); try frame()
            return actual.names
        } catch {
            if !actual.closeEntered { try closeDirectory(actual) }
            throw error
        }
    }
}
// READER_DISTINCT_V4_DIRECTORY_RAW_OWNER_END

extension GenerationLeaseRegistryV1 {
    fileprivate static func readerJournalFullFactV4(_ value: stat) -> String {
        originalEraseRetainedFullFact(value) // exact incumbent decimal11 pure DATA grammar
    }
}

// READER_DISTINCT_CHARGED_V4_CENSUS_ALGORITHM_BEGIN
extension GenerationLeaseRegistryV1 {
    @MainActor
    private func readColdSchema2ReaderJournalControlV4(
        owner: ColdEraseSchema2ReaderCensusOwnerV4,
        parent: Int32, name: String, url: URL, kind: OwnedFileKindV1,
        operation: EraseColdPreparationOperationV1,
        requireOrigin: @MainActor () throws -> Void) throws -> (bytes: Data, fact: String,
        policy: TemporalPolicyObservationV1, flags: UInt32)? {
        try requireOrigin()
        let leaf = try owner.beginLeaf() // actual owner already Native charged/retained
        @MainActor func read() throws -> (bytes: Data, fact: String, policy: TemporalPolicyObservationV1, flags: UInt32)? {
            var named = stat()
            let found = try owner.statNamed(parent, name, &named)
            let foundErrno = try owner.savedErrno
            if found < 0 {
                guard foundErrno == ENOENT else { throw Self.identityFailure(errorNumber: foundErrno) }
                try requireOrigin()
                guard try owner.statNamed(parent, name, &named) < 0,
                      (try owner.savedErrno) == ENOENT else { throw Self.identityFailure() }
                return nil
            }
            guard named.st_mode & S_IFMT == S_IFREG, named.st_nlink == 1,
                  named.st_size >= 0, named.st_size <= off_t(Self.maximumControlFileBytes) else {
                throw Self.identityFailure()
            }
            let fact = Self.originalEraseRetainedFullFact(named)
            let flags = UInt32(named.st_flags)
            let descriptor = try owner.openLeaf(parent, name)
            let openErrno = try owner.savedErrno
            guard descriptor >= 0 else { throw Self.identityFailure(errorNumber: openErrno) }
            @MainActor func requireLeaf() throws {
                try requireOrigin()
                var held = stat(), current = stat()
                guard try owner.statHeld(descriptor, &held) == 0,
                      try owner.statNamed(parent, name, &current) == 0,
                      Self.originalEraseRetainedFullFact(held) == fact,
                      Self.originalEraseRetainedFullFact(current) == fact,
                      UInt32(held.st_flags) == flags, UInt32(current.st_flags) == flags else {
                    throw Self.identityFailure()
                }
            }
            try requireLeaf()
            let policy = try owner.observePolicy(kind, url)
            guard policy.state == .strictComplete,
                  eraseSchema2ColdPolicyUncertainDescriptors.isEmpty else {
                throw Self.uncertainOwnerFailure()
            }
            leaf.rawBytes = Data(count: Int(named.st_size)) // registered raw storage before read; retained on uncertainty
            try leaf.rawBytes!.withUnsafeMutableBytes { buffer in
                var offset = 0
                while offset < buffer.count {
                    try requireLeaf()
                    let wanted = min(64 * 1024, buffer.count - offset)
                    let count = try owner.readLeaf(descriptor, buffer.baseAddress!.advanced(by: offset), wanted, off_t(offset))
                    let readErrno = try owner.savedErrno
                    try requireLeaf()
                    guard count > 0, count <= wanted else {
                        throw Self.identityFailure(errorNumber: count < 0 ? readErrno : EIO)
                    }
                    offset += count
                }
            }
            try requireLeaf()
            var extra: UInt8 = 0
            let eof = try owner.readLeaf(descriptor, &extra, 1, named.st_size)
            let eofErrno = try owner.savedErrno
            try requireLeaf()
            guard eof == 0 else { throw Self.identityFailure(errorNumber: eof < 0 ? eofErrno : EIO) }
            guard let bytes = leaf.rawBytes else { throw Self.identityFailure() }
            return (bytes, fact, policy, flags)
        }
        let observed: (bytes: Data, fact: String, policy: TemporalPolicyObservationV1, flags: UInt32)?
        do { observed = try read() }
        catch { try owner.closeLeaf(leaf); throw error }
        try owner.closeLeaf(leaf)
        try requireOrigin()
        if let observed {
            var current = stat()
            guard try owner.statNamed(parent, name, &current) == 0,
                  Self.originalEraseRetainedFullFact(current) == observed.fact,
                  UInt32(current.st_flags) == observed.flags,
                  leaf.eof?.returned == 0, leaf.close?.returned == 0,
                  leaf.close?.savedErrno != nil else { throw Self.identityFailure() }
        }
        return observed
    }

    /// Complete owner/control inventory and the ordinary reservation predicate
    /// through a distinct checked consumer. No aggregate initializer or ordinary
    /// temporal observer can replace this actual retained reader.
    @MainActor
    fileprivate func observeColdSchema2ReaderJournalCensusV4(
        owner: ColdEraseSchema2ReaderCensusOwnerV4,
        operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2ReaderJournalCensusV4 {
        @MainActor func requireOrigin() throws {
            try owner.frame()
            _ = try requireColdSchema2RetirementOrigin(operation: operation,
                activity: activity, exclusion: exclusion, binding: binding,
                witness: witness, heldG: true)
        }
        try requireOrigin()
        var facts: [String: String] = [:], bytes: [String: Data] = [:]
        var policies: [String: TemporalPolicyObservationV1] = [:]
        var flags: [String: UInt32] = [:]
        var directoryPolicies: [String: TemporalPolicyObservationV1] = [:]
        var migrationNames: [String]?
        func retain(_ key: String, _ value: (bytes: Data, fact: String,
            policy: TemporalPolicyObservationV1, flags: UInt32)?) {
            if let value {
                facts[key] = value.fact; bytes[key] = value.bytes
                policies[key] = value.policy; flags[key] = value.flags
            }
        }
        func directoryFact(_ descriptor: Int32, key: String) throws -> String {
            var held = stat()
            guard try owner.statHeld(descriptor, &held) == 0,
                  held.st_mode & S_IFMT == S_IFDIR, held.st_nlink >= 1 else {
                throw Self.identityFailure()
            }
            let actualFlags = UInt32(held.st_flags)
            if let expected = flags[key] { guard expected == actualFlags else { throw Self.identityFailure() } }
            else { flags[key] = actualFlags }
            return Self.originalEraseRetainedFullFact(held)
        }
        facts["lease-root"] = try directoryFact(leaseDescriptor, key: "lease-root")
        facts["owner-root"] = try directoryFact(ownersDescriptor, key: "owner-root")
        let leaseNames = try owner.boundedNames(in: leaseDescriptor, maximumCount: 6)
        let ownerNames = try owner.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount)
        var heldLeaseRoot = stat(), heldOwnerRoot = stat()
        guard try owner.statHeld(leaseDescriptor, &heldLeaseRoot) == 0,
              try owner.statHeld(ownersDescriptor, &heldOwnerRoot) == 0,
              Self.originalEraseRetainedFullFact(heldLeaseRoot) == facts["lease-root"],
              Self.originalEraseRetainedFullFact(heldOwnerRoot) == facts["owner-root"],
              UInt32(heldLeaseRoot.st_flags) == flags["lease-root"],
              UInt32(heldOwnerRoot.st_flags) == flags["owner-root"],
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(heldLeaseRoot.st_nlink),
                directEntryCount: leaseNames.count),
              EraseDirectoryEntryLinkModelV1.matches(linkCount: Int64(heldOwnerRoot.st_nlink),
                directEntryCount: ownerNames.count) else { throw Self.identityFailure() }
        let allowed: Set<String> = [Self.registryName, Self.mutationLockName,
            Self.ownerDirectoryName, Self.pruneIntentName, Self.pruneReceiptName,
            Self.schema2ColdReaderRecordName]
        guard leaseNames.count == Set(leaseNames).count,
              Set(leaseNames).isSubset(of: allowed),
              Set([Self.registryName, Self.mutationLockName, Self.ownerDirectoryName])
                .isSubset(of: Set(leaseNames)),
              ownerNames.count == Set(ownerNames).count,
              ownerNames.count <= Self.maximumOwnerCount,
              ownerNames.contains(Self.ownerLockName(ownerID)) else { throw Self.uncertainOwnerFailure() }
        for name in leaseNames where name != Self.ownerDirectoryName {
            let value = try readColdSchema2ReaderJournalControlV4(owner: owner, parent: leaseDescriptor,
                name: name, url: leaseURL.appendingPathComponent(name),
                kind: name == Self.mutationLockName ? .generationLeaseControl
                    : Self.controlKind(for: name), operation: operation,
                requireOrigin: requireOrigin)
            guard let value else { throw Self.identityFailure() }
            if name == Self.mutationLockName { guard value.bytes.isEmpty else { throw Self.identityFailure() } }
            retain("lease/" + name, value)
        }
        for name in ownerNames {
            guard name.hasSuffix(".lock"),
                  let id = UUID(uuidString: String(name.dropLast(5))),
                  Self.ownerLockName(id) == name else { throw Self.identityFailure() }
            let value = try readColdSchema2ReaderJournalControlV4(owner: owner, parent: ownersDescriptor,
                name: name, url: ownersURL.appendingPathComponent(name),
                kind: .generationLeaseOwnerLock, operation: operation,
                requireOrigin: requireOrigin)
            guard let value, value.bytes.isEmpty else { throw Self.identityFailure() }
            retain("owners/" + name, value)
        }
        guard let registryBytes = bytes["lease/" + Self.registryName] else { throw Self.identityFailure() }
        let tokens = try RegistryStateV1.decodeCanonical(from: registryBytes).leases
        guard tokens == (try operation.requireColdSchema2RetirementFrame(
            exclusion: exclusion, binding: binding, witness: witness,
            registry: self, activity: activity)),
              Set(tokens.map({ Self.ownerLockName($0.ownerID) })).isSubset(of: Set(ownerNames)) else {
            throw Self.uncertainOwnerFailure()
        }
        var migration = stat()
        let found = try owner.statNamed(operationsDescriptor, "schema-migration", &migration)
        let foundErrno = try owner.savedErrno
        if found < 0 {
            guard foundErrno == ENOENT else { throw Self.identityFailure(errorNumber: foundErrno) }
            try requireOrigin()
            guard try owner.statNamed(operationsDescriptor, "schema-migration", &migration) < 0, (try owner.savedErrno) == ENOENT else { throw Self.identityFailure() }
        } else {
            guard migration.st_mode & S_IFMT == S_IFDIR, migration.st_nlink >= 1 else { throw Self.identityFailure() }
            let before = Self.originalEraseRetainedFullFact(migration)
            flags["migration-root"] = UInt32(migration.st_flags)
            try owner.withOpen(parent: operationsDescriptor, name: "schema-migration",
                flags: O_RDONLY | O_DIRECTORY) { directory in
                guard try directoryFact(directory, key: "migration-root") == before else { throw Self.identityFailure() }
                migrationNames = try owner.boundedNames(in: directory, maximumCount: 100_000)
                let url = operationsURL.appendingPathComponent("schema-migration")
                let canonical = try readColdSchema2ReaderJournalControlV4(owner: owner, parent: directory,
                    name: StoreAggregateMigrationControlV1.name,
                    url: url.appendingPathComponent(StoreAggregateMigrationControlV1.name),
                    kind: .journal, operation: operation, requireOrigin: requireOrigin)
                let temporary = try readColdSchema2ReaderJournalControlV4(owner: owner, parent: directory,
                    name: StoreAggregateMigrationControlV1.temporaryName,
                    url: url.appendingPathComponent(StoreAggregateMigrationControlV1.temporaryName),
                    kind: .journalTemporary, operation: operation, requireOrigin: requireOrigin)
                let value = try canonical.map { try StoreAggregateMigrationJournalV1.decodeCanonical(from: $0.bytes) }
                if let temporary {
                    let pending = try StoreAggregateMigrationJournalV1.decodeCanonical(from: temporary.bytes)
                    if let value {
                        let nextValue = value.revision.addingReportingOverflow(1)
                        let nextPending = pending.revision.addingReportingOverflow(1)
                        if !nextValue.overflow, pending.revision == nextValue.partialValue {
                            try pending.validateReplacement(of: value)
                        } else if !nextPending.overflow, value.revision == nextPending.partialValue {
                            try value.validateReplacement(of: pending)
                        } else { throw StoreMigrationFailure.invalidPhaseTransition }
                    } else {
                        guard pending.phase == .recoveringSource, pending.revision == 0 else {
                            throw StoreMigrationFailure.invalidPhaseTransition
                        }
                    }
                    guard !(value ?? pending).reservationIsActive else { throw Self.uncertainOwnerFailure() }
                } else if value?.reservationIsActive == true { throw Self.uncertainOwnerFailure() }
                retain("migration/" + StoreAggregateMigrationControlV1.name, canonical)
                retain("migration/" + StoreAggregateMigrationControlV1.temporaryName, temporary)
                for (name, sampled) in [(StoreAggregateMigrationControlV1.name, canonical),
                    (StoreAggregateMigrationControlV1.temporaryName, temporary)] {
                    var current = stat()
                    let result = try owner.statNamed(directory, name, &current)
                    let observedErrno = try owner.savedErrno
                    if let sampled {
                        guard result == 0, Self.originalEraseRetainedFullFact(current) == sampled.fact,
                              UInt32(current.st_flags) == sampled.flags else {
                            throw Self.identityFailure()
                        }
                    } else {
                        guard result < 0, observedErrno == ENOENT else {
                            throw Self.identityFailure(errorNumber: observedErrno)
                        }
                    }
                }
                guard try directoryFact(directory, key: "migration-root") == before,
                      try owner.statNamed(operationsDescriptor, "schema-migration", &migration) == 0,
                      Self.originalEraseRetainedFullFact(migration) == before,
                      UInt32(migration.st_flags) == flags["migration-root"] else { throw Self.identityFailure() }
                facts["migration-root"] = before
            }
        }
        guard try owner.boundedNames(in: leaseDescriptor, maximumCount: 6) == leaseNames,
              try owner.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount) == ownerNames,
              try directoryFact(leaseDescriptor, key: "lease-root") == facts["lease-root"],
              try directoryFact(ownersDescriptor, key: "owner-root") == facts["owner-root"] else { throw Self.identityFailure() }
        // Recheck every cached member after the complete last hash/read;
        // later sibling reads cannot make an earlier sampled fact timeless.
        for (key, expected) in facts {
            if key == "lease-root" || key == "owner-root" { continue }
            let parts = key.split(separator: "/", maxSplits: 1).map(String.init)
            var current = stat()
            if key == "migration-root" {
                guard try owner.statNamed(operationsDescriptor, "schema-migration", &current) == 0,
                      Self.originalEraseRetainedFullFact(current) == expected,
                      UInt32(current.st_flags) == flags[key] else { throw Self.identityFailure() }
            } else if parts.count == 2, parts[0] == "lease" || parts[0] == "owners" {
                let parent = parts[0] == "lease" ? leaseDescriptor : ownersDescriptor
                guard try owner.statNamed(parent, parts[1], &current) == 0,
                      Self.originalEraseRetainedFullFact(current) == expected,
                      UInt32(current.st_flags) == flags[key] else { throw Self.identityFailure() }
            }
        }
        if facts["migration-root"] == nil {
            guard try owner.statNamed(operationsDescriptor, "schema-migration", &migration) < 0, (try owner.savedErrno) == ENOENT else { throw Self.identityFailure() }
        }
        for (key, url) in [("lease-root", leaseURL), ("owner-root", ownersURL),
            ("migration-root", operationsURL.appendingPathComponent("schema-migration"))] {
            guard let expected = facts[key] else { continue }
            try requireOrigin()
            let actual = try owner.observePolicy(key == "migration-root" ? .stagingDirectory : .generationLeaseDirectory, url)
            directoryPolicies[key] = actual // actual helper result before predicate
            var current = stat()
            guard actual.state == .strictComplete, actual.isDirectory == true,
                  actual.backupExcluded == true,
                  try owner.statURL(url, &current) == 0,
                  Self.originalEraseRetainedFullFact(current) == expected,
                  UInt32(current.st_flags) == flags[key],
                  actual.device == UInt64(current.st_dev), actual.inode == UInt64(current.st_ino),
                  actual.mode == UInt16(current.st_mode), actual.linkCount == UInt64(current.st_nlink) else {
                throw Self.uncertainOwnerFailure()
            }
        }
        // Re-observe the COMPLETE closed inventory after every policy call.
        guard try owner.boundedNames(in: leaseDescriptor, maximumCount: 6) == leaseNames,
              try owner.boundedNames(in: ownersDescriptor, maximumCount: Self.maximumOwnerCount) == ownerNames,
              try directoryFact(leaseDescriptor, key: "lease-root") == facts["lease-root"],
              try directoryFact(ownersDescriptor, key: "owner-root") == facts["owner-root"] else { throw Self.identityFailure() }
        for (key, expected) in facts {
            if key == "lease-root" || key == "owner-root" { continue }
            var current = stat(); let parts = key.split(separator: "/", maxSplits: 1).map(String.init)
            if key == "migration-root" {
                guard try owner.statNamed(operationsDescriptor, "schema-migration", &current) == 0 else { throw Self.identityFailure() }
            } else if parts.count == 2, parts[0] == "lease" || parts[0] == "owners" {
                guard try owner.statNamed(parts[0] == "lease" ? leaseDescriptor : ownersDescriptor,
                    parts[1], &current) == 0 else { throw Self.identityFailure() }
            } else if parts.count == 2, parts[0] == "migration" {
                try owner.withOpen(parent: operationsDescriptor, name: "schema-migration", flags: O_RDONLY | O_DIRECTORY) { fd in
                    guard try owner.statNamed(fd, parts[1], &current) == 0 else { throw Self.identityFailure() }
                }
            } else { throw Self.identityFailure() }
            guard Self.originalEraseRetainedFullFact(current) == expected,
                  UInt32(current.st_flags) == flags[key] else { throw Self.identityFailure() }
        }
        if let names = migrationNames {
            try owner.withOpen(parent: operationsDescriptor, name: "schema-migration", flags: O_RDONLY | O_DIRECTORY) { fd in
                guard try owner.boundedNames(in: fd, maximumCount: 100_000) == names else { throw Self.identityFailure() }
            }
        }
        try owner.requireClosedResources()
        try requireOrigin()
        return try ColdEraseSchema2ReaderJournalCensusV4(owner: owner,
            base: ColdSchema2RetirementCensusV1(tokens: tokens, leaseNames: leaseNames,
                ownerNames: ownerNames, facts: facts, bytes: bytes, policies: policies),
            flags: flags, directories: directoryPolicies, migrationNames: migrationNames)
    }

}
