// READER_DISTINCT_V4_CENSUS_JOIN_BEGIN
extension ColdEraseSchema2ReaderCensusOwnerV4 {
    func requireRequestAssociation(request: ColdEraseSchema2ReaderRetirementRequestV1,
        preparation: ColdEraseSchema2ReaderRetirementPreparationV1) throws {
        guard self.request === request, self.preparation === preparation, failure == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

extension GenerationLeaseRegistryV1 {
    fileprivate static func readerJournalFixedRolesV4(preparation: ColdEraseSchema2ReaderRetirementPreparationV1)
        -> [(String, UInt64)] {
        [(preparation.registryName, 3), (mutationLockName, 4),
         (preparation.publicationRecordName, 5), (pruneIntentName, 6), (pruneReceiptName, 7)]
    }
    @MainActor fileprivate func requireReaderCensusHeldGFrameV4(_ owner: ColdEraseSchema2ReaderCensusOwnerV4) throws {
        guard owner.registry === self, generationMutationLockDepth == 1 else {
            throw Self.uncertainOwnerFailure()
        }
        try owner.preparation.requireBound(registry: self, allocation: owner.allocation,
            reader: owner.reader, operation: owner.operation, activity: owner.activity,
            exclusion: owner.exclusion, binding: owner.binding, witness: owner.witness)
        _ = try requireColdSchema2RetirementOrigin(operation: owner.operation,
            activity: owner.activity, exclusion: owner.exclusion, binding: owner.binding,
            witness: owner.witness, heldG: true)
        switch owner.stage {
        case .prepared:
            guard coldSchema2ReaderRetirementAttempt == nil, coldSchema2ReaderRetirementReceipt == nil,
                  owner.attempt == nil, owner.completion == nil else { throw Self.uncertainOwnerFailure() }
        case .replacement:
            guard let attempt = owner.attempt, let completion = owner.completion,
                  coldSchema2ReaderRetirementAttempt === attempt,
                  attempt.replacementCompletion === completion else { throw Self.uncertainOwnerFailure() }
            try completion.requireBeforePublicationRecordClose(attempt: attempt, registry: self,
                allocation: owner.allocation, reader: owner.reader, operation: owner.operation,
                activity: owner.activity, exclusion: owner.exclusion, binding: owner.binding, witness: owner.witness)
        case .final:
            guard let attempt = owner.attempt, coldSchema2ReaderRetirementAttempt === attempt,
                  owner.completion == nil, attempt.activePrimitive == .fsyncPublicationRecordDirectory,
                  attempt.recordClosed, attempt.recordUnlinked, attempt.original < 0, attempt.temporary < 0,
                  !attempt.completed, !attempt.checkedGReleased, !attempt.uncertain,
                  !attempt.ownedMutationPending, attempt.policyUncertainDescriptors.isEmpty,
                  attempt.uncertainCloseDescriptors.isEmpty else { throw Self.uncertainOwnerFailure() }
            try attempt.requireBound(preparation: owner.preparation, registry: self,
                allocation: owner.allocation, reader: owner.reader, operation: owner.operation,
                activity: owner.activity, exclusion: owner.exclusion, binding: owner.binding, witness: owner.witness)
        }
    }
    @MainActor fileprivate func captureReaderJournalCensusPairV4(
        request: ColdEraseSchema2ReaderRetirementRequestV1,
        preparation: ColdEraseSchema2ReaderRetirementPreparationV1,
        allocation: GenerationLeaseAllocationAttemptV1, reader: GenerationLeaseHandleV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1, stage: ColdEraseSchema2ReaderCensusOwnerV4.Stage,
        attempt: ColdEraseSchema2ReaderRetirementAttemptV1?,
        completion: ColdEraseSchema2ReaderReplacementCompletionV1?,
        retain: (ColdEraseSchema2ReaderJournalCensusV4, Int) throws -> Void)
        throws -> (ColdEraseSchema2ReaderJournalCensusV4, ColdEraseSchema2ReaderJournalCensusV4) {
        // The actual Request's positive fixed reservation precedes both
        // constructor and raw buffers. Both returned owners stay retained.
        let firstOwner = ColdEraseSchema2ReaderCensusOwnerV4(request: request, preparation: preparation,
            registry: self, allocation: allocation, reader: reader, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness,
            stage: stage, attempt: attempt, completion: completion)
        try request.retainReaderCensusCapture(firstOwner)
        let secondOwner = ColdEraseSchema2ReaderCensusOwnerV4(request: request, preparation: preparation,
            registry: self, allocation: allocation, reader: reader, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness,
            stage: stage, attempt: attempt, completion: completion)
        try request.retainReaderCensusCapture(secondOwner)
        @MainActor func capture() throws -> (ColdEraseSchema2ReaderJournalCensusV4, ColdEraseSchema2ReaderJournalCensusV4) {
            do {
                let first = try observeColdSchema2ReaderJournalCensusV4(owner: firstOwner,
                    operation: operation, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
                firstOwner.result = first; try retain(first, 0) // retain raw return before second read
                try firstOwner.requireClosedResources(); firstOwner.checked = true
                let second = try observeColdSchema2ReaderJournalCensusV4(owner: secondOwner,
                    operation: operation, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
                secondOwner.result = second; try retain(second, 1) // retain before comparison
                try secondOwner.requireClosedResources(); secondOwner.checked = true
                guard first.isSameClosedData(as: second) else { throw Self.uncertainOwnerFailure() }
                return (first, second)
            } catch {
                firstOwner.fail(error); secondOwner.fail(error); throw error
            }
        }
        if stage == .prepared {
            guard generationMutationLockDepth == 0 else { throw Self.uncertainOwnerFailure() }
            return try withColdSchema2RetirementG(operation: operation, activity: activity,
                exclusion: exclusion, binding: binding, witness: witness, capture)
        }
        guard generationMutationLockDepth == 1 else { throw Self.uncertainOwnerFailure() }
        return try capture() // same genuine continuously held writer G; never rearm
    }
}

extension ColdEraseSchema2ReaderRetirementAttemptV1 {
    func retainReaderJournalFinalCensusesV4(request: ColdEraseSchema2ReaderRetirementRequestV1,
        registry: GenerationLeaseRegistryV1, allocation: GenerationLeaseAllocationAttemptV1,
        reader: GenerationLeaseHandleV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
