        guard !readerJournalFinalCaptureEnteredV4, readerJournalFinalFirstV4 == nil,
              readerJournalFinalSecondV4 == nil, let oldFirst = namespaceFinalFirstCensus,
              let oldSecond = namespaceFinalSecondCensus, oldFirst == oldSecond,
              oldFirst.facts == currentFacts, oldFirst.bytes == currentBytes else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        readerJournalFinalCaptureEnteredV4 = true
        let pair = try registry.captureReaderJournalCensusPairV4(request: request, preparation: preparation,
            allocation: allocation, reader: reader, operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness, stage: .final,
            attempt: self, completion: nil) { actual, ordinal in
                if ordinal == 0 { self.readerJournalFinalFirstV4 = actual }
                else { self.readerJournalFinalSecondV4 = actual }
            }
        guard pair.0.base == oldFirst, pair.1.base == oldSecond else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try request.requireReaderFinalCensusIssuer(attempt: self)
    }
}
