/// DATA from the actual once retained preparation; it cannot grant a task.
@MainActor final class ColdEraseSchema2ReaderJournalInputV4 {
    struct Record {
        let inventoryOrdinal: UInt64
        let parentInventoryOrdinal: UInt64?
        let roleCode: UInt64
        let canonicalKey: String
        let fullFact: String
        let flags: UInt32
        let policy: TemporalPolicyObservationV1
        let rawBytes: Data?
        let members: [String]?
        fileprivate init(ordinal: UInt64, parent: UInt64?, role: UInt64, key: String,
            fact: String, flags: UInt32, policy: TemporalPolicyObservationV1,
            raw: Data?, members: [String]?) {
            inventoryOrdinal = ordinal; parentInventoryOrdinal = parent; roleCode = role
            canonicalKey = key; fullFact = fact; self.flags = flags
            self.policy = policy; rawBytes = raw; self.members = members
        }
    }
    private let preparation: ColdEraseSchema2ReaderRetirementPreparationV1
    let records: [Record]
    let beforeRegistry: Data
    let replacementRegistry: Data
    let originalPublication: Data
    fileprivate let first: ColdEraseSchema2ReaderJournalCensusV4
    fileprivate let second: ColdEraseSchema2ReaderJournalCensusV4
    fileprivate init(preparation: ColdEraseSchema2ReaderRetirementPreparationV1,
        first: ColdEraseSchema2ReaderJournalCensusV4, second: ColdEraseSchema2ReaderJournalCensusV4) throws {
        let census = first.base
        guard first.isSameClosedData(as: second), census == preparation.census,
              census.facts.count <= 80, Set(census.facts.keys) == Set(first.flags.keys),
              preparation.beforeTokens.count == 1, preparation.afterTokens.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var keys: [(String, UInt64, UInt64?)] = [("lease-root", 1, nil), ("owner-root", 2, 0)]
        for (name, role) in GenerationLeaseRegistryV1.readerJournalFixedRolesV4(preparation: preparation) {
            let key = "lease/" + name
            if census.facts[key] != nil { keys.append((key, role, 0)) }
        }
        // Canonical owner-name order is emitted ONCE from authentic PRE. It
        // is the encoded inventory schema, never an ordinal of a later census.
        for name in census.ownerNames.sorted() { keys.append(("owners/" + name, 8, 1)) }
        if census.facts["migration-root"] != nil {
            let parent = UInt64(keys.count); keys.append(("migration-root", 9, nil))
            for (name, role) in [(StoreAggregateMigrationControlV1.name, UInt64(10)),
                (StoreAggregateMigrationControlV1.temporaryName, UInt64(11))] {
                let key = "migration/" + name
                if census.facts[key] != nil { keys.append((key, role, parent)) }
            }
        }
        guard keys.count == census.facts.count, keys.count <= 80,
              Set(keys.map { $0.0 }) == Set(census.facts.keys),
              Set(keys.map { $0.0 }).count == keys.count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var actual: [Record] = []; actual.reserveCapacity(keys.count)
        for (index, item) in keys.enumerated() {
            guard let full = census.facts[item.0], full.utf8.count <= 256,
                  item.0.utf8.count <= 128, let flags = first.flags[item.0],
                  let policy = first.policy(item.0), policy.state == .strictComplete else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let names: [String]?
            if item.0 == "lease-root" { names = census.leaseNames }
            else if item.0 == "owner-root" { names = census.ownerNames }
            else if item.0 == "migration-root" {
                guard let observed = first.migrationNames else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                names = observed // genuine closed directory cursor returns, never inferred names
            } else { names = nil }
            actual.append(Record(ordinal: UInt64(index), parent: item.2, role: item.1,
                key: item.0, fact: full, flags: flags, policy: policy,
                raw: census.bytes[item.0], members: names))
        }
        self.preparation = preparation; self.first = first; self.second = second; records = actual
        beforeRegistry = preparation.beforeRegistryBytes
        replacementRegistry = preparation.replacementRegistryBytes
        originalPublication = preparation.publicationRecordBytes
    }
    func requireAssociation(preparation: ColdEraseSchema2ReaderRetirementPreparationV1) throws {
        guard self.preparation === preparation, preparation.readerJournalInputV4 === self,
              preparation.readerJournalInputEnteredV4 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    static var declaredStoredBackingBytes: UInt64 {
        UInt64(MemoryLayout<ColdEraseSchema2ReaderJournalInputV4>.stride
            + 80 * MemoryLayout<Record>.stride + 80 * (256 + 128)
            + 6 * MemoryLayout<Data>.stride + 80 * MemoryLayout<TemporalPolicyObservationV1>.stride)
    }
}

extension ColdEraseSchema2ReaderRetirementPreparationV1 {
    func withReaderJournalInputV4(request: ColdEraseSchema2ReaderRetirementRequestV1,
        _ body: (ColdEraseSchema2ReaderJournalInputV4) throws -> Void) throws {
        try request.requireReaderRecipeInputIssuer(preparation: self)
        guard !readerJournalInputEnteredV4, readerJournalInputV4 == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        readerJournalInputEnteredV4 = true
        guard let registry, let allocation, let reader, let operation,
              let activity, let exclusion, let witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let pair = try registry.captureReaderJournalCensusPairV4(request: request, preparation: self,
            allocation: allocation, reader: reader, operation: operation, activity: activity,
            exclusion: exclusion, binding: binding, witness: witness, stage: .prepared,
            attempt: nil, completion: nil) { actual, ordinal in
                if ordinal == 0 { self.readerJournalInputFirstV4 = actual }
                else { self.readerJournalInputSecondV4 = actual }
            }
        let actual = try ColdEraseSchema2ReaderJournalInputV4(preparation: self, first: pair.0, second: pair.1)
        readerJournalInputV4 = actual // before a fallible Native borrower
        try body(actual); try actual.requireAssociation(preparation: self)
        try request.requireReaderRecipeInputIssuer(preparation: self)
    }
}

/// Actual closed census DATA. Native cannot construct it from a fact tuple.
@MainActor final class ColdEraseSchema2ReaderJournalPostimageV4 {
    private let request: ColdEraseSchema2ReaderRetirementRequestV1
    private let preparation: ColdEraseSchema2ReaderRetirementPreparationV1
    private let completion: ColdEraseSchema2ReaderReplacementCompletionV1?
    private let receipt: ColdEraseSchema2ReaderRetirementReceiptV1?
    fileprivate let census: ColdEraseSchema2ReaderJournalCensusV4
    let publicationUnlinkedFullFact: String?
    fileprivate init(request: ColdEraseSchema2ReaderRetirementRequestV1,
        preparation: ColdEraseSchema2ReaderRetirementPreparationV1,
        completion: ColdEraseSchema2ReaderReplacementCompletionV1?,
        receipt: ColdEraseSchema2ReaderRetirementReceiptV1?,
        census: ColdEraseSchema2ReaderJournalCensusV4,
        publicationUnlinked: String?) throws {
        guard (completion != nil) != (receipt != nil), census.base.tokens.isEmpty,
              Set(census.base.facts.keys) == Set(census.flags.keys), census.base.facts.count <= 80 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        self.request = request; self.preparation = preparation; self.completion = completion
        self.receipt = receipt; self.census = census; publicationUnlinkedFullFact = publicationUnlinked
    }
    func requireAssociation(request: ColdEraseSchema2ReaderRetirementRequestV1,
        preparation: ColdEraseSchema2ReaderRetirementPreparationV1,
        completion: ColdEraseSchema2ReaderReplacementCompletionV1?,
        receipt: ColdEraseSchema2ReaderRetirementReceiptV1?) throws {
        guard self.request === request, self.preparation === preparation,
              self.completion === completion, self.receipt === receipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
    func withRecord(key: String, _ body: (ColdEraseSchema2ReaderJournalInputV4.Record) throws -> Void) throws {
        guard let input = preparation.readerJournalInputV4,
              let record = input.records.first(where: { $0.canonicalKey == key }),
              let full = census.base.facts[key], let flags = census.flags[key],
              let policy = census.policy(key), policy.state == .strictComplete else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let names: [String]?
        if key == "lease-root" { names = census.base.leaseNames }
        else if key == "owner-root" { names = census.base.ownerNames }
        else if key == "migration-root" { names = census.migrationNames }
        else { names = nil }
        try body(.init(ordinal: record.inventoryOrdinal, parent: record.parentInventoryOrdinal,
            role: record.roleCode, key: key, fact: full, flags: flags, policy: policy,
            raw: census.base.bytes[key], members: names))
    }
    var leaseMemberCount: UInt64 { UInt64(census.base.leaseNames.count) }
    static var twoCensusStoredAndRawCeiling: UInt64 {
        // Closed controls: <=6 lease leaves and <=2 migration leaves, each
        // retaining the incumbent <=4MiB cap; owner lock bytes are empty.
        UInt64(2 * (8 * 4_194_304 + 80 * (256 + 128)
            + MemoryLayout<GenerationLeaseRegistryV1.ColdSchema2RetirementCensusV1>.stride
            + 80 * (MemoryLayout<Data>.stride + MemoryLayout<String>.stride
                + MemoryLayout<TemporalPolicyObservationV1>.stride)))
    }
}

extension ColdEraseSchema2ReaderReplacementCompletionV1 {
    func captureReaderJournalReplacementV4(request: ColdEraseSchema2ReaderRetirementRequestV1,
        registry: GenerationLeaseRegistryV1, allocation: GenerationLeaseAllocationAttemptV1,
