/// Immutable DATA borrowed from the actual completed two-pass Capture.
/// Constructors and the row/Source association stay Target-private.
@MainActor
final class ColdEraseSchema2NamespaceRemovalSourceOriginV1 {
    enum Provenance { case settledOperations, originalCreator, generatedCreator, retiredReader }
    fileprivate struct Storage {
        let provenance: Provenance
        let kind: OwnedFileKindV1
        let originalPhysicalOrdinal: UInt64?
        let requiresColdFirstMetadata: Bool
        let capture: ColdEraseSchema2NamespaceCaptureOwnerV1
        let row: ColdEraseSchema2NamespaceCurrentObservedNodeV1
    }
    fileprivate let storage: Storage
    var provenance: Provenance { storage.provenance }
    var kind: OwnedFileKindV1 { storage.kind }
    var originalPhysicalOrdinal: UInt64? { storage.originalPhysicalOrdinal }
    var requiresColdFirstMetadata: Bool { storage.requiresColdFirstMetadata }
    fileprivate init(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        row: ColdEraseSchema2NamespaceCurrentObservedNodeV1, originalPhysicalOrdinal: UInt64?) {
        let actual = row.storage.resource.storage.origin
        let provenance: Provenance
        switch actual.provenance {
        case .settledOperations: provenance = .settledOperations
        case .originalCreator: provenance = .originalCreator
        case .generatedCreator: provenance = .generatedCreator
        case .retiredReader: provenance = .retiredReader
        }
        storage = Storage(provenance: provenance, kind: actual.kind,
            originalPhysicalOrdinal: originalPhysicalOrdinal,
            requiresColdFirstMetadata: actual.requiresUntouchedOriginal, capture: capture, row: row)
    }
    func requireAssociation(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        row: ColdEraseSchema2NamespaceCurrentObservedNodeV1) throws {
        guard storage.capture === capture, storage.row === row,
              row.storage.capture === capture, row.storage.resource.storage.originCompleted else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try row.requireCheckedResourceReturn(scope: row.storage.scope, capture: capture)
    }
    /// Pure SAME-row proof for the distinct Native selector producer. The
    /// caller cannot replace the privately retained current Source origin.
    func requireNodeAssociation(node: ColdEraseSchema2NamespaceRemovalNodeV1,
        capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard node.sourceOrigin === self, node.row === storage.row,
              node.path == storage.row.path, node.ordinal == storage.row.ordinal,
              ColdEraseSchema2NamespaceCurrentReadResourceV1.same(node.information,
                storage.row.information), node.policy == storage.row.policy,
              node.contentSHA256 == storage.row.contentSHA256,
              node.members == storage.row.members else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireAssociation(capture: capture, row: node.row)
    }
}

