        let nodeCount: UInt64
        let canonicalSHA256: String
        let declaredBackingBytes: UInt64
        var rows: UnsafeMutablePointer<ColdEraseSchema2NamespaceCurrentObservedNodeV1?>?
        var nodes: UnsafeMutablePointer<ColdEraseSchema2NamespaceRemovalNodeV1?>?
        var pathOrder: UnsafeMutablePointer<UInt64>?
        var initialized = 0
        var coldFirstMetadataCount: UInt64 = 0
        var ready = false
        var attempt: ColdEraseSchema2NamespaceRemovalAttemptV1?
        var failure: Error?
        // CREATOR_V4_PREPARATION_RETAINED_OWNER_BEGIN
        var creatorInventoryV4Entered = false
        var creatorInventoryV4BackingBytes: UInt64 = 0
        var creatorInventoryV4: ColdEraseSchema2NamespaceCreatorInventoryV4?
        // CREATOR_V4_PREPARATION_RETAINED_OWNER_END
    }
    fileprivate var storage: Storage
    var nodeCount: UInt64 { storage.nodeCount }
    var canonicalSHA256: String { storage.canonicalSHA256 }
    var declaredBackingBytes: UInt64 { storage.declaredBackingBytes }
    var coldFirstMetadataCount: UInt64 { storage.coldFirstMetadataCount }
    var capture: ColdEraseSchema2NamespaceCaptureOwnerV1 { storage.capture }
    var reservation: ColdEraseSchema2NamespaceCaptureReservationV1 { storage.capture.namespaceConsumerReservation }
    fileprivate init(capture: ColdEraseSchema2NamespaceCaptureOwnerV1,
        owner: ColdEraseSchema2TerminalOwnerV1, basis: ColdEraseSchema2NamespacePreparationBasisV1,
        registry: GenerationLeaseRegistryV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1,
        nodeCount: UInt64, canonicalSHA256: String, declaredBackingBytes: UInt64) {
        storage = Storage(capture: capture, owner: owner, basis: basis, registry: registry,
            operation: operation, activity: activity, exclusion: exclusion, binding: binding,
            witness: witness, nodeCount: nodeCount, canonicalSHA256: canonicalSHA256,
            declaredBackingBytes: declaredBackingBytes)
    }
    static func requiredBackingBytes(nodeCount: UInt64, maximumPathUTF8Count: UInt64) throws -> UInt64 {
        guard nodeCount > 0, nodeCount <= UInt64(Int.max), maximumPathUTF8Count <= 16_640 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<Storage>.stride),
            ColdEraseControlBinaryV1.multiplying(nodeCount,
                UInt64(MemoryLayout<ColdEraseSchema2NamespaceCurrentObservedNodeV1?>.stride
                    + MemoryLayout<ColdEraseSchema2NamespaceRemovalNodeV1?>.stride
                    + MemoryLayout<UInt64>.stride + MemoryLayout<ColdEraseSchema2NamespaceRemovalNodeV1>.stride
                    + MemoryLayout<ColdEraseSchema2NamespaceRemovalSourceOriginV1.Storage>.stride)
                    + maximumPathUTF8Count + 255), 64,
            UInt64(12 * MemoryLayout<UInt64>.stride + 4 * MemoryLayout<String.UTF8View>.stride
                + 4 * MemoryLayout<String.UTF8View.SubSequence>.stride))
    }
    func requireBound(owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1, registry: GenerationLeaseRegistryV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws {
        guard storage.failure == nil, storage.ready, storage.owner === owner,
              storage.basis === basis, storage.registry === registry, storage.operation === operation,
              storage.activity === activity, storage.exclusion === exclusion,
              storage.binding == binding, storage.witness === witness,
              storage.initialized == Int(storage.nodeCount), storage.nodes != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.capture.requireNamespacePreparationAssociation(self)
    }
    func requireCaptureAssociation(capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard storage.capture === capture else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireBound(owner: storage.owner, basis: storage.basis, registry: storage.registry,
            operation: storage.operation, activity: storage.activity, exclusion: storage.exclusion,
            binding: storage.binding, witness: storage.witness)
    }
    func withCapturedNode(ordinal: UInt64,
        _ body: (ColdEraseSchema2NamespaceRemovalNodeV1) throws -> Void) throws {
        try requireCaptureAssociation(capture: storage.capture)
        guard ordinal < storage.nodeCount, let node = storage.nodes?[Int(ordinal)],
              node.ordinal == ordinal else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try body(node)
        try requireCaptureAssociation(capture: storage.capture)
    }
    func withColdFirstMetadataRecords(
        _ body: (ColdEraseSchema2NamespaceColdFirstMetadataRecordV1) throws -> Void) throws {
        try requireCaptureAssociation(capture: storage.capture)
        guard let order = storage.pathOrder, let nodes = storage.nodes else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var previous: UInt64?, count: UInt64 = 0
        for index in 0..<storage.initialized {
            guard let node = nodes[Int(order[index])] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if node.sourceOrigin.requiresColdFirstMetadata {
                let record = try ColdEraseSchema2NamespaceColdFirstMetadataRecordV1(node: node)
                guard previous == nil || previous! < record.originalOrdinal else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                previous = record.originalOrdinal; count += 1
                try body(record) // fixed scalar record; no array, recipe or path copy
            }
        }
        guard count == storage.coldFirstMetadataCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireCaptureAssociation(capture: storage.capture)
    }
    fileprivate func find(path: String.UTF8View.SubSequence) throws -> UInt64 {
        guard let order = storage.pathOrder, let rows = storage.rows else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var low = 0, high = Int(storage.nodeCount)
        while low < high {
            let mid = low + (high - low) / 2
            guard let row = rows[Int(order[mid])] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if row.path.utf8.lexicographicallyPrecedes(path) { low = mid + 1 } else { high = mid }
        }
        guard low < Int(storage.nodeCount), let row = rows[Int(order[low])],
              row.path.utf8.elementsEqual(path) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return order[low]
    }
    fileprivate func initialize() throws {
        do {
            guard !storage.ready, storage.rows == nil, storage.nodes == nil, storage.pathOrder == nil,
                  let count = Int(exactly: storage.nodeCount), count > 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let rows = UnsafeMutablePointer<ColdEraseSchema2NamespaceCurrentObservedNodeV1?>.allocate(capacity: count)
            storage.rows = rows; rows.initialize(repeating: nil, count: count)
            let nodes = UnsafeMutablePointer<ColdEraseSchema2NamespaceRemovalNodeV1?>.allocate(capacity: count)
            storage.nodes = nodes; nodes.initialize(repeating: nil, count: count)
            let order = UnsafeMutablePointer<UInt64>.allocate(capacity: count)
            storage.pathOrder = order; order.initialize(repeating: 0, count: count)
            storage.initialized = count
            try storage.capture.withNamespaceCapturedRows { row in
                guard row.pass == 0, row.ordinal < self.storage.nodeCount,
                      rows[Int(row.ordinal)] == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                rows[Int(row.ordinal)] = row // SAME actual row before getter/association failure
            }
            for index in 0..<count {
                guard let row = rows[index], row.ordinal == UInt64(index) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                order[index] = UInt64(index)
            }
            func less(_ a: UInt64, _ b: UInt64) throws -> Bool {
                guard let a = rows[Int(a)], let b = rows[Int(b)] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                return a.path.utf8.lexicographicallyPrecedes(b.path.utf8)
            }
            func sift(_ start: Int, _ end: Int) throws {
                var root = start
                while root <= (end - 2) / 2, end > 1 {
                    let left = root * 2 + 1
                    if left >= end { break }
                    var child = left
                    if left + 1 < end, try less(order[left], order[left + 1]) { child = left + 1 }
                    if try !less(order[root], order[child]) { break }
                    let value = order[root]; order[root] = order[child]; order[child] = value; root = child
                }
            }
            if count > 1 {
                for index in stride(from: count / 2 - 1, through: 0, by: -1) { try sift(index, count) }
                for end in stride(from: count - 1, through: 1, by: -1) {
                    let value = order[0]; order[0] = order[end]; order[end] = value; try sift(0, end)
                }
            }
            guard rows[Int(order[0])]!.path.isEmpty, UInt64(count - 1) == order[0] else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            for index in 1..<count {
                guard try less(order[index - 1], order[index]) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            }
            for ordinal in 0..<count {
                let row = rows[ordinal]!
                let parent: UInt64?
                if row.path.isEmpty { parent = nil; guard row.members != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner } }
                else {
                    let bytes = row.path.utf8, slash = bytes.lastIndex(of: 47)
                    let path = slash.map { bytes[..<$0] } ?? bytes[..<bytes.startIndex]
                    parent = try find(path: path)
                    guard parent! > UInt64(ordinal), let parentRow = rows[Int(parent!)],
                          let names = parentRow.members else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    let nameStart = slash.map { bytes.index(after: $0) } ?? bytes.startIndex
                    let name = bytes[nameStart...]
                    var matched = 0
                    for member in names where member.utf8.elementsEqual(name) { matched += 1 }
                    guard matched == 1 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                }
                let origin = ColdEraseSchema2NamespaceRemovalSourceOriginV1(capture: storage.capture,
                    row: row, originalPhysicalOrdinal: try storage.capture.namespaceOriginalPhysicalOrdinal(path: row.path))
                nodes[ordinal] = ColdEraseSchema2NamespaceRemovalNodeV1(ordinal: UInt64(ordinal), parentOrdinal: parent,
                    row: row, sourceOrigin: origin)
                try origin.requireAssociation(capture: storage.capture, row: row)
                if origin.requiresColdFirstMetadata {
                    guard origin.originalPhysicalOrdinal != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    storage.coldFirstMetadataCount += 1
                }
            }
            // Complete direct-child conservation using binary path lookup.
            // This does not create a second names census or quadratic table.
            for ordinal in 0..<count {
                let node = nodes[ordinal]!
                if let names = node.members {
                    for name in names {
                        let child = node.path.isEmpty ? name : node.path + "/" + name
                        let childOrdinal = try find(path: child.utf8[...])
                        guard nodes[Int(childOrdinal)]!.parentOrdinal == UInt64(ordinal) else {
                            throw GenerationLeaseRegistryFailureV1.uncertainOwner
                        }
                    }
                }
            }
            storage.ready = true
            try requireCaptureAssociation(capture: storage.capture)
        } catch { storage.failure = error; storage.capture.poisonOnUncertainEffect(); throw error }
    }
}

extension ColdEraseSchema2NamespaceCaptureOwnerV1 {
    var namespaceConsumerReservation: ColdEraseSchema2NamespaceCaptureReservationV1 { storage.reservation }
    func withNamespaceOriginalSelectorNode(node: ColdEraseSchema2NamespaceRemovalNodeV1,
        _ body: (ColdEraseSchema2NamespaceOriginalSelectorNodeV1) throws -> Void) throws {
        guard storage.state == .captured, storage.wholeCurrentFailure == nil,
              let preparation = storage.namespacePreparation, preparation.storage.capture === self,
              node.ordinal < preparation.nodeCount,
              let actual = preparation.storage.nodes?[Int(node.ordinal)],
              actual.sourceOrigin === node.sourceOrigin, actual.row === node.row,
              let ordinal = node.sourceOrigin.originalPhysicalOrdinal,
              let nodes = storage.nodeTable, ordinal < (storage.originalNodeCount ?? 0),
              try namespaceOriginalPhysicalOrdinal(path: node.path) == ordinal else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try node.sourceOrigin.requireNodeAssociation(node: node, capture: self)
        let original = try nodes.originalNode(ordinal)
        guard original.physicalOrdinal == UInt32(ordinal),
              original.device == Int64(node.information.st_dev),
              original.inode == UInt64(node.information.st_ino),
              original.mode == UInt32(node.information.st_mode),
              original.physicalKind == (node.members == nil ? 2 : 1),
              original.projectionState == 0 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try body(ColdEraseSchema2NamespaceOriginalSelectorNodeV1(original))
        try node.sourceOrigin.requireNodeAssociation(node: node, capture: self)
        try requireNamespacePreparationAssociation(preparation)
    }
    fileprivate func namespaceOriginalPhysicalOrdinal(path: String) throws -> UInt64? {
        guard storage.originalIndexCompleted, let count = storage.originalNodeCount,
              let nodes = storage.nodeTable, let names = storage.memberUTF8,
              let window = storage.pathUTF8 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var low: UInt64 = 0, high = count
        while low < high {
            let mid = low + (high - low) / 2
            if try compareOriginalPath(ordinal: mid, with: path.utf8[...], nodes: nodes, names: names, path: window) < 0 {
                low = mid + 1
            } else { high = mid }
        }
        guard low < count, try compareOriginalPath(ordinal: low, with: path.utf8[...],
            nodes: nodes, names: names, path: window) == 0 else { return nil }
        return low // authenticated PhysicalOrdinal DATA; generated provenance is separately mandatory
    }
    fileprivate func withNamespaceCapturedRows(_ body: (ColdEraseSchema2NamespaceCurrentObservedNodeV1) throws -> Void) throws {
        guard storage.state == .captured, storage.wholeCurrentFailure == nil,
              let window = storage.wholeCurrentWindow, let scope = storage.wholeCurrentScope,
              window.storage.firstRows == window.storage.secondRows, window.storage.firstHelperReturned,
              window.storage.secondHelperReturned, window.storage.firstRows > 0,
              let resources = window.storage.resources else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireWholeCurrentUnlockReturn(scope: scope)
        for index in 0..<Int(window.storage.firstResources) {
            guard let resource = resources[index], resource.storage.state == .completed,
                  let row = resource.storage.row else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try row.requireCheckedResourceReturn(scope: scope, capture: self)
            try body(row)
        }
        try requireWholeCurrentUnlockReturn(scope: scope)
    }
    fileprivate func requireNamespacePreparationAssociation(_ preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        guard (storage.state == .captured || storage.state == .released),
              storage.namespacePreparation === preparation, storage.wholeCurrentFailure == nil,
              preparation.storage.capture === self else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor func prepareColdSchema2NamespaceRemoval(owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1,
        operation: EraseColdPreparationOperationV1, activity: GenerationTemporalActivityHandleV1,
        exclusion: EraseRetirementExclusionV1, binding: EraseRetirementBindingV1,
        witness: EraseSessionDrainWitnessV1) throws -> ColdEraseSchema2NamespaceRemovalPreparationV1 {
        let capture = try captureColdSchema2WholeNamespace(owner: owner, basis: basis,
            operation: operation, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        do {
            guard capture.storage.state == .captured, capture.storage.namespacePreparation == nil,
                  let scope = capture.storage.wholeCurrentScope, let window = capture.storage.wholeCurrentWindow,
                  let profile = capture.storage.wholeCurrentSourceProfile,
                  window.storage.firstRows > 0, window.storage.firstRows == window.storage.secondRows else {
                throw Self.uncertainOwnerFailure()
            }
            let digest = try scope.requireCanonicalDigestReturn(pass: 0, capture: capture)
            guard digest == (try scope.requireCanonicalDigestReturn(pass: 1, capture: capture)) else {
                throw Self.uncertainOwnerFailure()
            }
            let bytes = try ColdEraseSchema2NamespaceRemovalPreparationV1.requiredBackingBytes(
                nodeCount: window.storage.firstRows, maximumPathUTF8Count: profile.maximumPathUTF8Count)
            try capture.storage.reservation.reserveNamespaceConsumerBacking(capture: capture, bytes: bytes)
            let preparation = ColdEraseSchema2NamespaceRemovalPreparationV1(capture: capture,
                owner: owner, basis: basis, registry: self, operation: operation, activity: activity,
                exclusion: exclusion, binding: binding, witness: witness, nodeCount: window.storage.firstRows,
                canonicalSHA256: digest, declaredBackingBytes: bytes)
            capture.storage.namespacePreparation = preparation // before allocation, callbacks or validation
            try preparation.initialize()
            try preparation.requireBound(owner: owner, basis: basis, registry: self, operation: operation,
                activity: activity, exclusion: exclusion, binding: binding, witness: witness)
            return preparation
        } catch {
            coldSchema2RetirementUncertain = true; capture.poisonOnUncertainEffect()
            owner.poisonOnUncertainEffect(); throw error
        }
    }
}
