/// Immutable actual selected-resource DATA. The descriptor is borrowed from
/// Target; PFP closes only its own separately entered transient pin.
@MainActor
struct ColdEraseSchema2NamespaceSelectedPolicyNodeV1 {
    let kind: OwnedFileKindV1
    let url: URL
    let fullFact: String
    let parentFullFact: String
    let parentDescriptor: Int32
    let selectedName: String
    let isDirectory: Bool
    let absoluteURLUTF8Count: UInt64
    let fact: ColdEraseSchema2NamespaceSelectedPolicyFullFactV1
    let parentFact: ColdEraseSchema2NamespaceSelectedPolicyFullFactV1
    fileprivate init(kind: OwnedFileKindV1, url: URL, fullFact: String,
        parentFullFact: String, parentDescriptor: Int32, selectedName: String,
        isDirectory: Bool, absoluteURLUTF8Count: UInt64) throws {
        self.kind = kind; self.url = url; self.fullFact = fullFact
        self.parentFullFact = parentFullFact; self.parentDescriptor = parentDescriptor
        self.selectedName = selectedName; self.isDirectory = isDirectory
        self.absoluteURLUTF8Count = absoluteURLUTF8Count
        fact = try ColdEraseSchema2NamespaceSelectedPolicyFullFactV1(fullFact)
        parentFact = try ColdEraseSchema2NamespaceSelectedPolicyFullFactV1(parentFullFact)
    }
    func sameActualFields(as other: Self) -> Bool {
        kind == other.kind && url == other.url && fullFact == other.fullFact
            && parentFullFact == other.parentFullFact && parentDescriptor == other.parentDescriptor
            && selectedName.utf8.elementsEqual(other.selectedName.utf8)
            && isDirectory == other.isDirectory && absoluteURLUTF8Count == other.absoluteURLUTF8Count
    }
}

/// A fresh namespace-effect Scope retained before PFP entry. It never forwards
/// to the completed readonly Capture Scope, whose original roots are stale
/// after this process's positively returned namespace mutations.
@MainActor
final class ColdEraseSchema2NamespaceSelectedPolicyScopeV1 {
    fileprivate enum State { case retained, observing, checked, consuming, consumed, uncertain }
    fileprivate struct Storage {
        let resource: ColdEraseSchema2NamespaceSelectedResourceV1
        let request: ColdEraseSchema2NamespaceSelectedPolicyRequestV1
        let attempt: ColdEraseSchema2NamespaceRemovalAttemptV1
        let operationID: UUID
        var state: State = .retained
        var observation: ColdEraseSchema2NamespaceSelectedPolicyObservationV1?
        var uncertainDescriptor: Int32?
    }
    fileprivate var storage: Storage
    fileprivate init(resource: ColdEraseSchema2NamespaceSelectedResourceV1,
        request: ColdEraseSchema2NamespaceSelectedPolicyRequestV1) {
        storage = Storage(resource: resource, request: request,
            attempt: resource.storage.attempt, operationID: resource.operationID)
    }
    var operationID: UUID { storage.operationID }
    private func resource() throws -> ColdEraseSchema2NamespaceSelectedResourceV1 {
        guard storage.state != .uncertain, storage.resource.storage.policyScope === self,
              storage.resource.storage.policyRequest === storage.request,
              storage.resource.storage.attempt === storage.attempt,
              storage.operationID == storage.resource.operationID else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try storage.request.requireAssociation(attempt: storage.attempt,
            ordinal: storage.resource.storage.node.ordinal)
        return storage.resource
    }
    func requireCurrentBinding() throws { try resource().requireCurrentPolicyFrame(scope: self) }
    func requireNode() throws -> ColdEraseSchema2NamespaceSelectedPolicyNodeV1 {
        try requireCurrentBinding(); return try resource().currentPolicyNode(scope: self)
    }
    func requireNode(_ kind: OwnedFileKindV1, at url: URL, fullFact: String)
        throws -> ColdEraseSchema2NamespaceSelectedPolicyNodeV1 {
        let actual = try requireNode()
        guard actual.kind == kind, actual.url == url, actual.fullFact == fullFact else {
            throw ProtectedFilePolicyError.identityChanged
        }
        return actual
    }
    func requireKernelDescriptor() throws -> Int32 {
        try requireCurrentBinding(); let actual = try resource()
        guard actual.storage.descriptor >= 0, actual.storage.openReturned != nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        return actual.storage.descriptor
    }
    func requireObservationConstructionCapacity(additionalBytes: UInt64) throws {
        guard storage.state == .retained, storage.observation == nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try requireCurrentBinding()
        try resource().requirePolicyDeclaredBacking(scope: self, additionalBytes: additionalBytes)
    }
    func retainObservationAttempt(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1) throws {
        guard storage.state == .retained, storage.observation == nil else {
            throw ProtectedFilePolicyError.identityChanged
        }
        storage.observation = actual; storage.state = .observing // before delegated checks or IO
        try resource().retainPolicyObservation(actual, scope: self)
        try requireObservationAttempt(actual); try requireCurrentBinding()
    }
    func requireObservationAttempt(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1) throws {
        guard storage.state == .observing || storage.state == .checked || storage.state == .consuming
                || storage.state == .consumed,
              storage.observation === actual, storage.uncertainDescriptor == nil,
              actual.scopeIdentity == ObjectIdentifier(self), actual.operationID == operationID else {
            throw ProtectedFilePolicyError.identityChanged
        }
        _ = try resource() // pure returned Native request/Target owner association only
    }
    func requireObservationCapacity(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1,
        additionalBytes: UInt64) throws {
        try requireObservationAttempt(actual)
        try resource().requirePolicyDeclaredBacking(scope: self, additionalBytes: additionalBytes)
    }
    func completeObservationAttempt(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1) throws {
        try requireObservationAttempt(actual)
        guard storage.state == .observing else { throw ProtectedFilePolicyError.identityChanged }
        try actual.requireCheckedSettlement(); try requireCurrentBinding()
        storage.state = .checked
    }
    /// Selected pin has actually closed and the same Attempt's real durable
    /// consumer returned. This check is intentionally memory-only: the old
    /// selected name and PRE full11 no longer exist after successful unlink.
    func requireConsumedObservationAttempt(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1) throws {
        try requireObservationAttempt(actual)
        guard storage.state == .checked || storage.state == .consuming || storage.state == .consumed else {
            throw ProtectedFilePolicyError.identityChanged
        }
        try resource().requireCheckedPolicyConsumer(scope: self, observation: actual)
        try actual.requireCheckedSettlement()
    }
    fileprivate func consumeAfterCheckedNodeCompletion() throws {
        guard storage.state == .checked, let actual = storage.observation else {
            throw ProtectedFilePolicyError.identityChanged
        }
        do {
            try requireConsumedObservationAttempt(actual); storage.state = .consuming
            try actual.releaseConsumedScope(self)
            storage.state = .consumed; try requireConsumedObservationAttempt(actual)
        } catch { poisonOnUncertainObservation(); throw error }
    }
    func retainUncertainDescriptor(_ descriptor: Int32) {
        if storage.uncertainDescriptor == nil { storage.uncertainDescriptor = descriptor }
        poisonOnUncertainObservation()
    }
    func poisonOnUncertainObservation() {
        storage.state = .uncertain; storage.resource.poison(ProtectedFilePolicyError.identityChanged)
    }
}
