/// Concrete factual checked-setter witness. It is produced only after this
/// selected resource's real full11+flags, content and closed-census checks.
struct ColdEraseSchema2NamespaceSelectedPolicyWitnessV1: Equatable {
    let selected: EraseColdControlLeafFactV1
    let selectedFlags: UInt32
    let parent: EraseColdControlLeafFactV1
    let parentFlags: UInt32
    let contentSHA256: String?
    let parentMembershipSHA256: String
    fileprivate init(selected: stat, parent: stat, contentSHA256: String?, parentMembershipSHA256: String) {
        self.selected = EraseColdControlLeafFactV1(selected); selectedFlags = selected.st_flags
        self.parent = EraseColdControlLeafFactV1(parent); parentFlags = parent.st_flags
        self.contentSHA256 = contentSHA256; self.parentMembershipSHA256 = parentMembershipSHA256
    }
}

/// DATA from one actual positively returned own unlink and actual parent
/// fstat/selected fstat/named-absence returns, retained before Native postproof.
/// It neither denotes a complete remaining scan nor authorizes another effect.
@MainActor
struct ColdEraseSchema2NamespaceReturnedParentProjectionV1 {
    let ordinal: UInt64
    let parentFact: EraseColdControlLeafFactV1
    let parentFlags: UInt32
    let selectedFact: EraseColdControlLeafFactV1
    let selectedFlags: UInt32
    let selectedAbsentReturn: Int32
    let selectedAbsentErrno: Int32
    fileprivate let resource: ColdEraseSchema2NamespaceSelectedResourceV1
    fileprivate init(resource: ColdEraseSchema2NamespaceSelectedResourceV1, parent: stat,
        selected: stat, absentReturn: Int32, absentErrno: Int32) {
        self.resource = resource; ordinal = resource.storage.node.ordinal
        parentFact = EraseColdControlLeafFactV1(parent); parentFlags = parent.st_flags
        selectedFact = EraseColdControlLeafFactV1(selected); selectedFlags = selected.st_flags
        selectedAbsentReturn = absentReturn; selectedAbsentErrno = absentErrno
    }
    func requireAssociation(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        guard resource.storage.attempt === attempt, ordinal == resource.storage.node.ordinal,
              let parent = resource.storage.afterParent, let selected = resource.storage.afterSelected,
              parentFact == EraseColdControlLeafFactV1(parent), parentFlags == parent.st_flags,
              selectedFact == EraseColdControlLeafFactV1(selected), selectedFlags == selected.st_flags,
              selectedAbsentReturn == -1, selectedAbsentErrno == ENOENT,
