    let parentFact: ColdEraseSchema2NamespaceGPolicyFullFactV1
    let flags: UInt32
    let parentFlags: UInt32
    fileprivate init(context: ColdEraseSchema2NamespaceEffectGContextV1) throws {
        let leaf = context.storage.mutationNode.information
        let parent = context.storage.leaseNode.information
        kind = .generationLeaseControl; url = context.storage.mutationURL
        fullFact = GenerationLeaseRegistryV1.coldSchema2TerminalFullFact(leaf)
        parentFullFact = GenerationLeaseRegistryV1.coldSchema2TerminalFullFact(parent)
        parentDescriptor = context.storage.leaseDescriptor
        selectedName = "mutation.lock"; isDirectory = false
        absoluteURLUTF8Count = UInt64(url.absoluteString.utf8.count)
        fact = try ColdEraseSchema2NamespaceGPolicyFullFactV1(fullFact)
        parentFact = try ColdEraseSchema2NamespaceGPolicyFullFactV1(parentFullFact)
        flags = leaf.st_flags; parentFlags = parent.st_flags
    }
    func sameActualFields(as other: Self) -> Bool {
        kind == other.kind && url == other.url && fullFact == other.fullFact
            && parentFullFact == other.parentFullFact && parentDescriptor == other.parentDescriptor
            && selectedName == other.selectedName && isDirectory == other.isDirectory
            && absoluteURLUTF8Count == other.absoluteURLUTF8Count
            && flags == other.flags && parentFlags == other.parentFlags
    }
}

