            if returned == 0 { storage.attempt.storage.registry.recordNamespaceMutationDepth(self, depth: 0) }
            let outcome = ColdEraseSchema2NamespaceRemovalOutcomeV1(attempt: storage.attempt, context: self,
                primitive: .releaseG, returned: returned, saved: saved)
