            guard returned == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.phase = .released; storage.attempt.storage.phase = .releasing
            storage.releasePostProof = .entered
            do { try requireUnlinkedMutationCurrent(); storage.releasePostProof = .returned }
            catch { storage.releasePostProof = .threw(error); throw error }
