              storage.beforeReleaseEOF == 0, storage.beforeReleaseEOFErrno != nil,
              storage.beforeReleaseMutationReturn == 0, storage.beforeReleaseMutationErrno != nil,
              storage.beforeReleaseLeaseReturn == 0, storage.beforeReleaseLeaseErrno != nil,
              storage.beforeReleaseOperationsReturn == 0, storage.beforeReleaseOperationsErrno != nil,
              storage.probeConsumed, let request = storage.releasePolicyRequest else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
