            case "generation-leases/mutation.lock": guard mutation == nil else { throw Self.uncertainOwnerFailure() }; mutation = node
            case "generation-leases": guard lease == nil else { throw Self.uncertainOwnerFailure() }; lease = node
            case "": guard operations == nil else { throw Self.uncertainOwnerFailure() }; operations = node
            default: break
