        let context = ColdEraseSchema2NamespaceEffectGContextV1(attempt: attempt, support: rootDescriptor,
            operations: operationsDescriptor, lease: leaseDescriptor, mutation: mutationLockDescriptor,
            supportURL: applicationSupportURL, mutationURL: url,
            operationsNode: operations, leaseNode: lease, mutationNode: mutation)
