                preimage: resource.storage.preimage, request: resource.storage.policyRequest,
                scope: scope, observation: observation, selected: selected, parent: parent,
                rawCount: resource.storage.rawCount, raw: resource.storage.raw,
                firstRead: resource.storage.firstRead, secondRead: resource.storage.secondRead,
