    func requireKernelReturned(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        primitive: ColdEraseSchema2NamespaceRemovalPrimitiveV1) throws {
        guard storage.attempt === attempt, storage.preparation === attempt.namespacePreparation,
