    private static func flush(into tokens: inout Tokens) {
        let count = tokens.pendingCount; guard count > 0 else { return }
        var pending = tokens.pending
        withUnsafeBytes(of: &pending) {
            tokens.hash.update(bufferPointer: UnsafeRawBufferPointer(start: $0.baseAddress, count: count))
        }
        tokens.pendingCount = 0
    }
    private static func unsigned(_ value: UInt64, into tokens: inout Tokens) {
        var divisor: UInt64 = 1
        while value / divisor >= 10 { divisor *= 10 }
        while true {
            byte(UInt8((value / divisor) % 10) + 48, into: &tokens)
            if divisor == 1 { return }; divisor /= 10
        }
    }
    private static func signed(_ value: Int64, into tokens: inout Tokens) {
        if value < 0 { byte(45, into: &tokens); unsigned(0 &- UInt64(bitPattern: value), into: &tokens) }
        else { unsigned(UInt64(value), into: &tokens) }
    }
    private static func hex<C: Collection>(_ bytes: C, into tokens: inout Tokens) where C.Element == UInt8 {
        for value in bytes {
            let high = value >> 4, low = value & 15
            byte(high < 10 ? high + 48 : high + 87, into: &tokens)
            byte(low < 10 ? low + 48 : low + 87, into: &tokens)
        }
    }
    private static func token(_ row: ColdEraseSchema2NamespaceCurrentScanRowV4, into tokens: inout Tokens) throws {
        let fact = row.storage.information, directory = row.storage.members != nil
        guard directory ? fact.st_mode & S_IFMT == S_IFDIR && row.storage.contentSHA256 == nil
            : fact.st_mode & S_IFMT == S_IFREG && row.storage.contentSHA256 != nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        byte(directory ? 68 : 70, into: &tokens); byte(124, into: &tokens)
        hex(row.path.utf8, into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_dev), into: &tokens); byte(124, into: &tokens)
        unsigned(UInt64(fact.st_ino), into: &tokens); byte(124, into: &tokens)
        unsigned(UInt64(fact.st_mode), into: &tokens); byte(124, into: &tokens)
        unsigned(UInt64(fact.st_nlink), into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_size), into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_mtimespec.tv_sec), into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_mtimespec.tv_nsec), into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_ctimespec.tv_sec), into: &tokens); byte(124, into: &tokens)
        signed(Int64(fact.st_ctimespec.tv_nsec), into: &tokens); byte(124, into: &tokens)
        if let members = row.storage.members {
            for index in members.indices { if index != 0 { byte(44, into: &tokens) }; hex(members[index].utf8, into: &tokens) }
        } else {
            guard let sha = row.storage.contentSHA256, StoreMigrationCanonicalJSONV1.isLowercaseSHA256(sha) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            for value in sha.utf8 { byte(value, into: &tokens) }
        }
    }
    func poison(_ error: Error) {
        if storage.failure == nil { storage.failure = error }
        storage.phase = .uncertain; storage.attempt.poisonOnUncertainEffect()
        // Preserve every initialized row/resource/name/cursor/request, current
        // FD and stream. No catch/deinit cleanup, retry or capacity decharge.
    }
}

@MainActor
final class ColdEraseSchema2NamespaceOperationsAbsenceV1 {
    fileprivate let scanner: ColdEraseSchema2NamespaceCurrentScannerV4
    fileprivate init(scanner: ColdEraseSchema2NamespaceCurrentScannerV4) { self.scanner = scanner }
    fileprivate func requireCheckedReturn() throws {
        guard scanner.storage.removedPrefixCount == UInt64(scanner.storage.nodeCount),
              let first = scanner.storage.firstAbsence, let second = scanner.storage.secondAbsence,
              first.returned == -1, first.savedErrno == ENOENT, second.returned == -1, second.savedErrno == ENOENT,
              case .returned = first.postProof, case .returned = second.postProof else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try scanner.compareCompletePasses()
    }
}

@MainActor
final class ColdEraseSchema2NamespaceCurrentFrameV1 {
    enum Operations {
        case present(fact: EraseColdControlLeafFactV1, flags: UInt32, policyCode: UInt64)
        case absent(ColdEraseSchema2NamespaceOperationsAbsenceV1)
    }
    fileprivate struct Storage {
        let scanner: ColdEraseSchema2NamespaceCurrentScannerV4
        let supportRow: ColdEraseSchema2NamespaceCurrentScanRowV4
        let operations: Operations
        let currentPrefixSHA256: String
    }
    fileprivate let storage: Storage
    var operations: Operations { storage.operations }
    var support: EraseColdControlLeafFactV1 { EraseColdControlLeafFactV1(storage.supportRow.storage.information) }
    var supportFact: EraseColdControlLeafFactV1 { support }
    var supportFlags: UInt32 { storage.supportRow.storage.information.st_flags }
    var supportPolicyCode: UInt64 { storage.supportRow.storage.policyCode }
    var supportDirectChildCount: UInt64 { UInt64(storage.supportRow.storage.members!.count) }
    var currentPrefixSHA256: String { storage.currentPrefixSHA256 }
    var operationsPolicyCode: UInt64 {
        get throws {
            guard case .present(_, _, let value) = storage.operations else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return value
        }
    }
    fileprivate init(scanner: ColdEraseSchema2NamespaceCurrentScannerV4) throws {
        guard scanner.storage.phase == .checked, let support = scanner.storage.secondSupport?.storage.row,
              support.storage.members != nil, let digest = scanner.storage.secondTokens.digest else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let operations: Operations
        if scanner.storage.removedPrefixCount == UInt64(scanner.storage.nodeCount) {
            let absence = ColdEraseSchema2NamespaceOperationsAbsenceV1(scanner: scanner)
            scanner.storage.operationsAbsenceOwner = absence // before fallible returned-data proof
            try absence.requireCheckedReturn(); operations = .absent(absence)
        } else {
            guard let root = scanner.storage.rows?[2 * scanner.storage.nodeCount - 1], root.path.isEmpty else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            operations = .present(fact: EraseColdControlLeafFactV1(root.storage.information),
                flags: root.storage.information.st_flags, policyCode: root.storage.policyCode)
        }
        storage = Storage(scanner: scanner, supportRow: support, operations: operations, currentPrefixSHA256: digest)
    }
    func requireCurrentScanAssociation(epoch: ColdEraseSchema2NamespaceCurrentScanEpochV4,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        let scanner = storage.scanner
        guard scanner.storage.epoch === epoch, scanner.storage.attempt === attempt,
              scanner.storage.phase == .checked, scanner.storage.failure == nil,
              scanner.storage.frame === self, scanner.storage.declaredBackingBytes != nil,
              scanner.storage.firstTokens.returned, scanner.storage.secondTokens.returned,
              scanner.storage.firstTokens.digest == currentPrefixSHA256,
              scanner.storage.secondTokens.digest == currentPrefixSHA256 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var retained = attempt.storage.firstCurrentScanner
        var found = false
        while let actual = retained {
            if actual === scanner { found = true; break }; retained = actual.storage.next
        }
        guard found else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try scanner.compareCompletePasses() // pure closed-resource receipts; no Native/current-owner recursion
    }
    func requireMetadataCurrent(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        try requireCurrentScanAssociation(epoch: storage.scanner.storage.epoch, attempt: attempt)
        guard attempt.namespacePreparation === preparation,
              storage.scanner.storage.removedPrefixCount == 0,
              case .present = operations else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        // Pure returned DATA from all real unchanged remaining rows. Native
        // separately proves this exact epoch/stage and its current IO frame.
    }
    func requireFinishedSelection(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        try requireCurrentScanAssociation(epoch: storage.scanner.storage.epoch, attempt: attempt)
        guard storage.scanner.storage.removedPrefixCount == UInt64(storage.scanner.storage.nodeCount),
              case .absent(let actual) = operations else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try actual.requireCheckedReturn()
    }
}

extension ColdEraseSchema2NamespaceRemovalAttemptV1 {
    /// Actual returned scanner DATA. Subsequent metadata/Creator REQUEST/OBS,
    /// selected PRE/Completion and final receipts are distinct consumers.
    func captureCurrentNamespace() throws -> ColdEraseSchema2NamespaceCurrentFrameV1 {
        do {
            guard let request = storage.request, let count = Int(exactly: storage.preparation.nodeCount) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try requireCurrentScanEntry(request: request)
            let epoch = try request.beginCurrentScan(attempt: self)
            try storage.preparation.reservation.reserveNamespaceConsumerBacking(capture: storage.preparation.capture,
                bytes: ColdEraseSchema2NamespaceCurrentScannerV4.fixedBackingBytes)
            let scanner = ColdEraseSchema2NamespaceCurrentScannerV4(attempt: self, request: request, epoch: epoch,
                nodeCount: count, removedPrefixCount: epoch.removedPrefixCount,
                fixedBackingBytes: ColdEraseSchema2NamespaceCurrentScannerV4.fixedBackingBytes)
            if let previous = storage.lastCurrentScanner {
                guard previous.storage.next == nil, previous.storage.phase == .checked else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                previous.storage.next = scanner
            } else {
                guard storage.firstCurrentScanner == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                storage.firstCurrentScanner = scanner
            }
            storage.lastCurrentScanner = scanner // retain same epoch/Scanner before tables/resources/PFP
            try scanner.initializeAndScan()
            guard let frame = scanner.storage.frame else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try frame.requireCurrentScanAssociation(epoch: epoch, attempt: self)
            return frame
        } catch { poisonOnUncertainEffect(); throw error }
    }
}
// COLD_SCHEMA2_NAMESPACE_CURRENT_DYNAMIC_SCANNER_V4_END

// COLD_SCHEMA2_NAMESPACE_SELECTED_PREIMAGE_V4_BEGIN
/// Closed Source/Reader provenance DATA. This issuer consumes the actual
/// encoded inventory ordinal; it never manufactures one from path order.
@MainActor
fileprivate final class ColdEraseSchema2NamespaceReaderNodeSelectorV4 {
    struct Storage {
        let origin: ColdEraseSchema2ReaderNamespaceJournalOriginV4
        let pin: ColdEraseSchema2ReaderRecipePinV4
        let record: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord
        let parentRecord: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord?
        let source: ColdEraseSchema2NamespaceRemovalSourceOriginV1
        let parentSource: ColdEraseSchema2NamespaceRemovalSourceOriginV1
        let nodeOrdinal: UInt64
        let parentOrdinal: UInt64
        let parentDomain: UInt64
        let parentValue: UInt64
    }
    let storage: Storage
    init(origin: ColdEraseSchema2ReaderNamespaceJournalOriginV4,
        record: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord,
        parentRecord: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord?,
        node: ColdEraseSchema2NamespaceRemovalNodeV1, parent: ColdEraseSchema2NamespaceRemovalNodeV1,
        parentDomain: UInt64, parentValue: UInt64) {
        storage = Storage(origin: origin, pin: origin.pin, record: record, parentRecord: parentRecord,
            source: node.sourceOrigin, parentSource: parent.sourceOrigin,
            nodeOrdinal: node.ordinal, parentOrdinal: parent.ordinal,
            parentDomain: parentDomain, parentValue: parentValue)
    }
    func requireAssociation(node: ColdEraseSchema2NamespaceRemovalNodeV1,
        parent: ColdEraseSchema2NamespaceRemovalNodeV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        guard storage.source === node.sourceOrigin, storage.parentSource === parent.sourceOrigin,
              storage.nodeOrdinal == node.ordinal, storage.parentOrdinal == parent.ordinal,
              node.parentOrdinal == parent.ordinal,
              storage.origin.receipt === preparation.storage.basis.readerReceipt,
              storage.pin === storage.origin.pin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.origin.requireAssociation(receipt: storage.origin.receipt, preparation: storage.origin.preparation)
        try node.sourceOrigin.requireReaderJournalRecordAssociation(record: storage.record, pin: storage.pin)
        try parent.sourceOrigin.requireNodeAssociation(node: parent, capture: preparation.capture)
        if let parentRecord = storage.parentRecord {
            guard storage.parentDomain == 2, storage.parentValue == parentRecord.inventoryOrdinal,
                  storage.record.parentInventoryOrdinal == parentRecord.inventoryOrdinal else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try parent.sourceOrigin.requireReaderJournalRecordAssociation(record: parentRecord, pin: storage.pin)
        } else {
            guard storage.parentDomain == 1, storage.record.roleCode == 1,
                  storage.record.parentInventoryOrdinal == nil, parent.path.isEmpty,
                  parent.sourceOrigin.provenance == .settledOperations,
                  parent.sourceOrigin.originalPhysicalOrdinal == storage.parentValue else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }
}

extension ColdEraseSchema2NamespaceRemovalSourceOriginV1 {
    /// Memory-only join to the SAME privately issued final Reader record.
    /// Migration comparison records and the removed publication are excluded.
    func requireReaderJournalRecordAssociation(record: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord,
        pin: ColdEraseSchema2ReaderRecipePinV4) throws {
        let row = storage.row, actual = row.storage.resource.storage.origin
        guard storage.provenance == .retiredReader, actual.provenance == .retiredReader,
              storage.capture.storage.basis.readerReceipt === record.receipt,
              pin.receipt === record.receipt, pin.preparation === record.preparation,
              (1...8).contains(record.roleCode), record.roleCode != 5,
              record.kind == (row.members == nil ? 1 : 2), record.rawSHA256.count == 32,
              record.fullFact == GenerationLeaseRegistryV1.coldSchema2TerminalFullFact(row.information),
              record.flags == row.information.st_flags, record.policyCode == row.storage.policyCode else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireAssociation(capture: storage.capture, row: row)
        try record.requireAssociation(receipt: record.receipt, preparation: record.preparation, pin: pin)
        let key = record.canonicalKey, path = row.path
        switch record.roleCode {
        case 1:
            guard key == "lease-root", path == "generation-leases", record.parentInventoryOrdinal == nil,
                  row.members != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        case 2:
            guard key == "owner-root", path == "generation-leases/owners", record.parentInventoryOrdinal != nil,
                  row.members != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        case 3, 4, 6, 7:
            let expected: String
            switch record.roleCode {
            case 3: expected = "registry.json"
            case 4: expected = "mutation.lock"
            case 6: expected = "prune-intent.json"
            default: expected = "last-prune-receipt.json"
            }
            guard key == "lease/" + expected, path == "generation-leases/" + expected,
                  record.parentInventoryOrdinal != nil, row.members == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        case 8:
            guard key.hasPrefix("owners/"), path.hasPrefix("generation-leases/owners/"),
                  key.utf8.dropFirst(7).elementsEqual(path.utf8.dropFirst(25)),
                  record.parentInventoryOrdinal != nil, row.members == nil,
                  storage.kind == .generationLeaseOwnerLock else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if row.members == nil {
            guard row.information.st_size >= 0, UInt64(row.information.st_size) == record.rawByteCount,
                  let digest = row.contentSHA256,
                  try ColdEraseControlBinaryV1.rawSHA256(digest) == record.rawSHA256,
                  let bytes = actual.bytes, UInt64(bytes.count) == record.rawByteCount else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // The captured Resource's genuine completed Source check already
            // joined these immutable bytes to its actual two-read digest.
            // This pure record association borrows that conserved digest.
        } else {
            guard record.rawByteCount == 0, record.rawSHA256.allSatisfy({ $0 == 0 }),
                  actual.members == row.members else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
    }
}

/// SAME identity is retained by Attempt before any selector borrower or names
/// copy. The underlying rows are complete returned scans with owned closures.
@MainActor
final class ColdEraseSchema2NamespaceSelectedPreimageV1 {
    fileprivate enum Selector {
        case original(ColdEraseSchema2NamespaceNodeSelectorV1)
        case creator(ColdEraseSchema2NamespaceCreatorNodeSelectorV4)
        case reader(ColdEraseSchema2NamespaceReaderNodeSelectorV4)
    }
    fileprivate struct Storage {
        let frame: ColdEraseSchema2NamespaceCurrentFrameV1
        let attempt: ColdEraseSchema2NamespaceRemovalAttemptV1
        let node: ColdEraseSchema2NamespaceRemovalNodeV1
        let parent: ColdEraseSchema2NamespaceRemovalNodeV1?
        let row: ColdEraseSchema2NamespaceCurrentScanRowV4
        let parentRow: ColdEraseSchema2NamespaceCurrentScanRowV4
        let declaredBackingBytes: UInt64
        let absentRecipeSHA256 = Data(repeating: 0, count: 32)
        var selector: Selector?
        var readerRecord: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord?
        var readerParentRecord: ColdEraseSchema2ReaderRecipePinV4.InventoryRecord?
        var parentMembers: [String] = []
        var ready = false
        var parentGraph: ColdEraseSchema2NamespaceSelectedParentGraphV4?
        var failure: Error?
    }
    fileprivate var storage: Storage
    var ordinal: UInt64 { storage.node.ordinal }
    var path: String { storage.node.path }
    var url: URL { storage.row.storage.resource.storage.url }
    var ownedKind: OwnedFileKindV1 { storage.node.sourceOrigin.kind }
    var information: stat { storage.row.storage.information }
    var parentInformation: stat { storage.parentRow.storage.information }
    var fact: EraseColdControlLeafFactV1 { EraseColdControlLeafFactV1(information) }
    var parentFact: EraseColdControlLeafFactV1 { EraseColdControlLeafFactV1(parentInformation) }
    var policy: TemporalPolicyObservationV1 { storage.row.storage.policy }
    var policyCode: UInt64 { storage.row.storage.policyCode }
    var parentPolicyCode: UInt64 { storage.parentRow.storage.policyCode }
    var kindCode: UInt64 { storage.row.storage.members == nil ? 1 : 2 }
    var contentSHA256: String? { storage.row.storage.contentSHA256 }
    var directChildCount: UInt64 { UInt64(storage.parentMembers.count) }
    var selectedDirectChildCount: UInt64 { UInt64(storage.row.storage.members?.count ?? 0) }
    var parentMembers: [String] { storage.parentMembers }
    var currentPrefixSHA256: String { storage.frame.currentPrefixSHA256 }
    var selectorDomain: UInt64 {
        get throws { switch try selector() { case .original: return 1; case .creator: return 3; case .reader: return 2 } }
    }
    var selectorOrdinal: UInt64 {
        get throws { switch try selector() {
        case .original(let value): return value.selectorOrdinal
        case .creator(let value): return value.selectorOrdinal
        case .reader(let value): return value.storage.record.inventoryOrdinal
        } }
    }
    var parentDomain: UInt64 {
        get throws { switch try selector() {
        case .original(let value): return value.parentDomain
        case .creator(let value): return value.parentDomain
        case .reader(let value): return value.storage.parentDomain
        } }
    }
    var parentOrdinal: UInt64 {
        get throws { switch try selector() {
        case .original(let value): return value.parentOrdinal
        case .creator(let value): return value.parentOrdinal
        case .reader(let value): return value.storage.parentValue
        } }
    }
    var readerRecipeOffset: UInt64 { get throws { if case .reader(let value) = try selector() { return value.storage.pin.recipeOffset }; return 0 } }
    var readerRecipeByteCount: UInt64 { get throws { if case .reader(let value) = try selector() { return value.storage.pin.recipeByteCount }; return 0 } }
    var readerRecipeSHA256: Data { get throws { if case .reader(let value) = try selector() { return value.storage.pin.recipeSHA256 }; return storage.absentRecipeSHA256 } }
    var creatorRecipeOffset: UInt64 { get throws { if case Selector.creator(let value) = try selector() { return value.creatorRecipeOffset }; return 0 } }
    var creatorRecipeByteCount: UInt64 { get throws { if case Selector.creator(let value) = try selector() { return value.creatorRecipeByteCount }; return 0 } }
    var creatorRecipeSHA256: Data { get throws { if case Selector.creator(let value) = try selector() { return value.creatorRecipeSHA256 }; return storage.absentRecipeSHA256 } }
    fileprivate func selector() throws -> Selector {
        guard storage.ready, storage.failure == nil, let value = storage.selector else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return value
    }
    fileprivate init(frame: ColdEraseSchema2NamespaceCurrentFrameV1,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1, node: ColdEraseSchema2NamespaceRemovalNodeV1,
        parent: ColdEraseSchema2NamespaceRemovalNodeV1?, row: ColdEraseSchema2NamespaceCurrentScanRowV4,
        parentRow: ColdEraseSchema2NamespaceCurrentScanRowV4, declaredBackingBytes: UInt64) {
        storage = Storage(frame: frame, attempt: attempt, node: node, parent: parent,
            row: row, parentRow: parentRow, declaredBackingBytes: declaredBackingBytes)
    }
    fileprivate static func requiredBackingBytes(parentMembers: ColdEraseSchema2NamespaceScanMembersV4) throws -> UInt64 {
        try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<Storage>.stride
            + MemoryLayout<Selector>.stride + MemoryLayout<ColdEraseSchema2NamespaceReaderNodeSelectorV4.Storage>.stride
            + 4 * MemoryLayout<ColdEraseSchema2ReaderRecipePinV4.InventoryRecord?>.stride
            + 4 * MemoryLayout<ColdEraseSchema2NamespaceRemovalNodeV1>.stride
            + MemoryLayout<ColdEraseSchema2NamespaceOriginalSelectorNodeV1>.stride
            + 4 * MemoryLayout<String.UTF8View>.stride + 8 * MemoryLayout<UInt64>.stride),
            ColdEraseControlBinaryV1.multiplying(UInt64(parentMembers.count), UInt64(MemoryLayout<String>.stride)),
            4 * 32, 16_640, 512)
    }
    fileprivate func initialize() throws {
        do {
            let preparation = storage.attempt.namespacePreparation, native = storage.frame.storage.scanner.storage.request
            guard !storage.ready, storage.selector == nil, let names = storage.parentRow.storage.members,
                  names.storage.completed, storage.parentMembers.isEmpty,
                  storage.declaredBackingBytes == (try Self.requiredBackingBytes(parentMembers: names)),
                  directChildCount == 0, names.count > 0,
                  selectedDirectChildCount == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try storage.row.requireClosedReturn(); try storage.parentRow.requireClosedReturn()
            storage.parentMembers.reserveCapacity(names.count)
            var found = 0
            for index in names.indices {
                let name = names[index]; storage.parentMembers.append(name)
                if name.utf8.elementsEqual(storage.node.name.utf8) { found += 1 }
            }
            guard found == 1, storage.parentMembers.count == names.count else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if storage.node.sourceOrigin.provenance == .retiredReader {
                guard let parent = storage.parent else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try native.withNamespaceReaderSelectorOrigin(preparation: preparation) { origin in
                    guard origin.receipt === preparation.storage.basis.readerReceipt,
                          origin.pin.inventoryCount <= 80 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    try origin.requireAssociation(receipt: origin.receipt, preparation: origin.preparation)
                    // Authentic recipe ordinals include absent/migration records.
                    // A key-directed borrower avoids trying to select those roles.
                    try origin.pin.withNamespaceInventoryRecord(key: try Self.readerKey(node: self.storage.node)) { record in
                        self.storage.readerRecord = record // retained before Source postproof
                        try self.storage.node.sourceOrigin.requireReaderJournalRecordAssociation(record: record, pin: origin.pin)
                    }
                    guard let record = self.storage.readerRecord else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    let parentDomain: UInt64, parentValue: UInt64
                    if record.roleCode == 1 {
                        guard parent.path.isEmpty, parent.sourceOrigin.provenance == .settledOperations,
                              record.parentInventoryOrdinal == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                        var originalParent: ColdEraseSchema2NamespaceOriginalSelectorNodeV1?
                        try preparation.capture.withNamespaceOriginalSelectorNode(node: parent) { value in originalParent = value }
                        guard let actualParent = originalParent else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                        parentDomain = 1; parentValue = actualParent.physicalOrdinal
                    } else {
                        guard let ordinal = record.parentInventoryOrdinal else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                        // The selected borrower has actually returned. This
                        // separate real parent borrower never nests pin IO.
                        try origin.pin.withInventoryRecord(ordinal: ordinal) { value in
                            self.storage.readerParentRecord = value
                            try parent.sourceOrigin.requireReaderJournalRecordAssociation(record: value, pin: origin.pin)
                        }
                        guard let actual = self.storage.readerParentRecord else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                        parentDomain = 2; parentValue = actual.inventoryOrdinal
                    }
                    let value = ColdEraseSchema2NamespaceReaderNodeSelectorV4(origin: origin, record: record,
                        parentRecord: self.storage.readerParentRecord, node: self.storage.node, parent: parent,
                        parentDomain: parentDomain, parentValue: parentValue)
                    self.storage.selector = .reader(value)
                    try value.requireAssociation(node: self.storage.node, parent: parent, preparation: preparation)
                }
            } else if ColdEraseSchema2NamespaceCreatorRoleV4.pathRole(storage.node) != nil {
                guard let parent = storage.parent, storage.node.sourceOrigin.provenance == .generatedCreator else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try native.withNamespaceCreatorSelectorOrigin(preparation: preparation) { inventory, pin in
                    try ColdEraseSchema2NamespaceCreatorNodeSelectorV4.withCreator(node: self.storage.node,
                        parent: parent, preparation: preparation, inventory: inventory, pin: pin) { value in
                        self.storage.selector = .creator(value)
                    }
                }
            } else {
                try ColdEraseSchema2NamespaceNodeSelectorV1.withOriginal(node: storage.node,
                    parent: storage.parent, preparation: preparation) { value in self.storage.selector = .original(value) }
            }
            guard storage.selector != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.ready = true
