              currentPrefixSHA256 == preimage.currentPrefixSHA256,
              let before = old.storage.rows, let after = current.storage.rows,
              ColdEraseSchema2NamespaceSelectedResourceV1.same(storage.supportRow.storage.information,
                preimage.storage.frame.storage.supportRow.storage.information),
              storage.supportRow.storage.policy == preimage.storage.frame.storage.supportRow.storage.policy,
              storage.supportRow.storage.policyCode == preimage.storage.frame.storage.supportRow.storage.policyCode else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        func sameMembers(_ first: ColdEraseSchema2NamespaceScanMembersV4?,
            _ second: ColdEraseSchema2NamespaceScanMembersV4?) throws {
            if let first {
                guard let second, first.storage.completed, second.storage.completed,
                      first.count == second.count else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                for index in first.indices { guard first[index].utf8.elementsEqual(second[index].utf8) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner } }
            } else { guard second == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner } }
        }
        try sameMembers(storage.supportRow.storage.members, preimage.storage.frame.storage.supportRow.storage.members)
        let count = current.storage.nodeCount
        for ordinal in Int(preimage.ordinal)..<count {
            guard let first = before[count + ordinal], let second = after[count + ordinal],
                  first.ordinal == UInt64(ordinal), second.ordinal == UInt64(ordinal),
                  first.storage.resource.storage.node?.sourceOrigin === second.storage.resource.storage.node?.sourceOrigin,
                  ColdEraseSchema2NamespaceSelectedResourceV1.same(first.storage.information, second.storage.information),
                  ColdEraseSchema2NamespaceSelectedResourceV1.same(first.storage.parentInformation, second.storage.parentInformation),
                  first.storage.policy == second.storage.policy, first.storage.policyCode == second.storage.policyCode,
                  first.storage.contentSHA256 == second.storage.contentSHA256 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try first.requireClosedReturn(); try second.requireClosedReturn()
            try sameMembers(first.storage.members, second.storage.members)
        }
        guard case .present = operations, case .present = preimage.storage.frame.operations else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}
// COLD_SCHEMA2_NAMESPACE_SELECTED_CURRENT_SCAN_RECEIVER_V4_END

// COLD_SCHEMA2_NAMESPACE_ACTUAL_NODE_COMPLETION_V4_BEGIN
/// The real selected FD, ancestor loans and complete remaining namespace
/// scans have returned before this owner can expose a durable OBS preimage.
@MainActor
final class ColdEraseSchema2NamespaceNodeCompletionV1 {
    enum NextSelection {
        case selected(ColdEraseSchema2NamespaceSelectedPreimageV1)
        case finished(ColdEraseSchema2NamespaceCurrentFrameV1)
    }
    fileprivate struct Storage {
        let attempt: ColdEraseSchema2NamespaceRemovalAttemptV1
        let resource: ColdEraseSchema2NamespaceSelectedResourceV1
        let preimage: ColdEraseSchema2NamespaceSelectedPreimageV1
        let frame: ColdEraseSchema2NamespaceCurrentFrameV1
        let parentRow: ColdEraseSchema2NamespaceCurrentScanRowV4
        let declaredBackingBytes: UInt64
        var prepared: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1?
        var unlinked: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1?
        var synced: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1?
        var closed: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1?
        var next: NextSelection?
        var ready = false
        var failure: Error?
    }
    fileprivate var storage: Storage
    var ordinal: UInt64 { storage.resource.storage.node.ordinal }
    var parentFact: EraseColdControlLeafFactV1 { EraseColdControlLeafFactV1(storage.parentRow.storage.information) }
    var parentPolicyCode: UInt64 { storage.parentRow.storage.policyCode }
    var directChildCount: UInt64 { UInt64(storage.parentRow.storage.members!.count) }
    var currentPrefixSHA256: String { storage.frame.currentPrefixSHA256 }
    fileprivate static var requiredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + MemoryLayout<NextSelection>.stride
            + 4 * MemoryLayout<ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1?>.stride
            + 8 * MemoryLayout<UInt64>.stride + 2 * MemoryLayout<stat>.stride)
    }
    fileprivate init(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        resource: ColdEraseSchema2NamespaceSelectedResourceV1,
        frame: ColdEraseSchema2NamespaceCurrentFrameV1,
        parentRow: ColdEraseSchema2NamespaceCurrentScanRowV4) {
        storage = Storage(attempt: attempt, resource: resource, preimage: resource.storage.preimage,
            frame: frame, parentRow: parentRow, declaredBackingBytes: Self.requiredBackingBytes)
    }
    fileprivate func requireActualReturnedResources() throws {
        let attempt = storage.attempt, resource = storage.resource, preimage = storage.preimage
        guard resource.storage.attempt === attempt, resource.storage.preimage === preimage,
              attempt.storage.resources?[Int(ordinal)] === resource, resource.storage.failure == nil,
              resource.storage.state == .closed || resource.storage.state == .consuming || resource.storage.state == .completed,
              resource.storage.unlinkEntered, resource.storage.unlinkReturned == 0, resource.storage.unlinkErrno != nil,
              resource.storage.fsyncEntered, resource.storage.fsyncReturned == 0, resource.storage.fsyncErrno != nil,
              resource.storage.closeEntered, resource.storage.closeReturned == 0, resource.storage.closeErrno != nil,
              resource.storage.descriptor == -1, let graph = preimage.storage.parentGraph,
              graph.preimage === preimage, let afterParent = resource.storage.afterParent,
              let members = storage.parentRow.storage.members, members.storage.completed,
              preimage.directChildCount > 0, UInt64(members.count) == preimage.directChildCount - 1,
              ColdEraseSchema2NamespaceSelectedResourceV1.same(afterParent, storage.parentRow.storage.information),
              storage.parentRow.storage.policyCode == preimage.parentPolicyCode else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try graph.requireClosedReturn()
        try resource.requireReturnedParentProjection()
        try storage.parentRow.requireClosedReturn()
        try storage.frame.requireCurrentScanAssociation(epoch: storage.frame.storage.scanner.storage.epoch, attempt: attempt)
        let nextOrdinal = ordinal.addingReportingOverflow(1)
        guard !nextOrdinal.overflow,
              storage.frame.storage.scanner.storage.removedPrefixCount == nextOrdinal.partialValue else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // Independent complete direct names conservation against the true
        // PRE. Exactly this selected name is absent; no extra name is adopted.
        var index = 0, selected = 0
        for name in preimage.parentMembers {
            if name.utf8.elementsEqual(resource.storage.node.name.utf8) { selected += 1; continue }
            guard index < members.count, members[index].utf8.elementsEqual(name.utf8) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            index += 1
        }
        guard selected == 1, index == members.count else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
    fileprivate func retainActualHistoricalReturn(_ actual: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1) throws {
        guard case .selected(let returned) = actual.storage.source,
              returned.resource === storage.resource, returned.preimage === storage.preimage,
              returned.sourceOrigin === storage.resource.storage.node.sourceOrigin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        switch actual.primitive {
        case .prepareNode(let value):
            guard value == ordinal, storage.prepared == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.prepared = actual
        case .unlinkNode(let value):
            guard value == ordinal, storage.unlinked == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.unlinked = actual
        case .fsyncParent(let value):
            guard value == ordinal, storage.synced == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.synced = actual
        case .closeNode(let value):
            guard value == ordinal, storage.closed == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.closed = actual
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // The exact returned owner is retained above BEFORE this fallible
        // pure consumed-callback proof. No current-lastOutcome check is used.
        try actual.requireConsumedReturn(attempt: storage.attempt, primitive: actual.primitive)
    }
    fileprivate func initialize() throws {
        do {
            let attempt = storage.attempt
            guard !storage.ready, storage.next == nil, storage.failure == nil,
                  attempt.storage.completionCandidate === self,
                  storage.declaredBackingBytes == Self.requiredBackingBytes,
                  let prepared = storage.resource.storage.preparedHistory,
                  let unlinked = storage.resource.storage.unlinkedHistory,
                  let synced = storage.resource.storage.syncedHistory,
                  let closed = storage.resource.storage.closedHistory else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requireActualReturnedResources()
            try retainActualHistoricalReturn(prepared)
            try retainActualHistoricalReturn(unlinked)
            try retainActualHistoricalReturn(synced)
            try retainActualHistoricalReturn(closed)
            try requireActualHistoricalReturns()
            let nextOrdinal = try ColdEraseControlBinaryV1.adding(ordinal, 1)
            if nextOrdinal < attempt.namespacePreparation.nodeCount {
                try storage.frame.withSelectedPreimage(ordinal: nextOrdinal, attempt: attempt) { actual in
                    self.storage.next = .selected(actual) // SAME owner before next Source postproof
                    try actual.requireAssociation(preparation: attempt.namespacePreparation, attempt: attempt)
                }
            } else {
                guard nextOrdinal == attempt.namespacePreparation.nodeCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try storage.frame.requireFinishedSelection(attempt: attempt)
                storage.next = .finished(storage.frame) // real two ENOENT/empty-scan owner, no scalar receipt
            }
            guard storage.next != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.ready = true
            try requireSelectedRequest(preimage: storage.preimage, attempt: attempt)
        } catch {
            if storage.failure == nil { storage.failure = error }
            storage.attempt.poisonOnUncertainEffect(); throw error
        }
    }
    fileprivate func requireActualHistoricalReturns() throws {
        let attempt = storage.attempt
        guard let prepared = storage.prepared, let unlinked = storage.unlinked,
              let synced = storage.synced, let closed = storage.closed,
              prepared.sequence < unlinked.sequence, unlinked.sequence < synced.sequence,
              synced.sequence < closed.sequence else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try prepared.requireConsumedReturn(attempt: attempt, primitive: .prepareNode(ordinal: ordinal))
        try unlinked.requireConsumedReturn(attempt: attempt, primitive: .unlinkNode(ordinal: ordinal))
        try synced.requireConsumedReturn(attempt: attempt, primitive: .fsyncParent(ordinal: ordinal))
        try closed.requireConsumedReturn(attempt: attempt, primitive: .closeNode(ordinal: ordinal))
    }
    /// Nonrecursive historical removed-prefix DATA consumer. Readiness was
    /// issued only after this actual complete Frame and four own returns were
    /// checked. Never calls that same Frame or Native consumer from its scan.
    fileprivate func requireHistoricalResourceAssociation(resource: ColdEraseSchema2NamespaceSelectedResourceV1,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        guard storage.attempt === attempt, storage.resource === resource,
              storage.preimage === resource.storage.preimage, storage.ready, storage.failure == nil,
              resource.storage.completedConsumer === self, resource.storage.durableConsumerReturned,
              resource.storage.state == .consuming || resource.storage.state == .completed,
              resource.storage.descriptor == -1, resource.storage.unlinkReturned == 0,
              resource.storage.fsyncReturned == 0, resource.storage.closeReturned == 0,
              resource.storage.failure == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireActualHistoricalReturns()
        guard let graph = storage.preimage.storage.parentGraph else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try graph.requireClosedReturn()
    }
    func requireSelectedRequest(preimage: ColdEraseSchema2NamespaceSelectedPreimageV1,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        guard storage.preimage === preimage, storage.attempt === attempt,
              storage.ready, storage.failure == nil, ordinal == preimage.ordinal,
              storage.resource.storage.preimage === preimage else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try preimage.requireAssociation(preparation: attempt.namespacePreparation, attempt: attempt)
        try requireActualReturnedResources(); try requireActualHistoricalReturns()
    }
    func requireBound(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        owner: ColdEraseSchema2TerminalOwnerV1, basis: ColdEraseSchema2NamespacePreparationBasisV1,
        registry: GenerationLeaseRegistryV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        guard storage.attempt === attempt else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try attempt.requireBound(preparation: attempt.namespacePreparation, owner: owner, basis: basis,
            registry: registry, operation: operation, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        try requireSelectedRequest(preimage: storage.preimage, attempt: attempt)
    }
    func requireCapacitySupportProjection(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws -> EraseColdControlLeafFactV1? {
        guard attempt.namespacePreparation === preparation, attempt.storage.owner === owner,
              attempt.storage.operation === operation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireSelectedRequest(preimage: storage.preimage, attempt: attempt)
        if !storage.resource.storage.node.path.isEmpty { return nil }
        guard storage.resource.storage.node.parentOrdinal == nil,
              storage.parentRow === storage.frame.storage.supportRow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.frame.requireFinishedSelection(attempt: attempt)
        return parentFact // true own Operations-root returned unlink + fresh canonical Support proof
    }
    func withNextSelectedPreimage(ordinal nextOrdinal: UInt64,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        _ body: (NextSelection) throws -> Void) throws {
        try requireSelectedRequest(preimage: storage.preimage, attempt: attempt)
        guard nextOrdinal == (try ColdEraseControlBinaryV1.adding(ordinal, 1)), let actual = storage.next else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        switch actual {
        case .selected(let next):
            guard next.ordinal == nextOrdinal, next.storage.frame === storage.frame else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try next.requireAssociation(preparation: attempt.namespacePreparation, attempt: attempt)
        case .finished(let frame):
            guard nextOrdinal == attempt.namespacePreparation.nodeCount, frame === storage.frame else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try frame.requireFinishedSelection(attempt: attempt)
        }
        try body(actual)
        try requireSelectedRequest(preimage: storage.preimage, attempt: attempt)
    }
}

fileprivate extension ColdEraseSchema2NamespaceSelectedResourceV1 {
    /// Actual private publisher called while the original live Outcome still
    /// passes. Slots retain SAME proof before its second live postproof.
    func retainActualHistoricalReturn(_ actual: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1) throws {
        guard actual.storage.attempt === storage.attempt, case .selected(let source) = actual.storage.source,
              source.resource === self, source.preimage === storage.preimage,
              source.sourceOrigin === storage.node.sourceOrigin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        switch actual.primitive {
        case .prepareNode(let ordinal):
            guard ordinal == storage.node.ordinal, storage.preparedHistory == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.preparedHistory = actual
        case .unlinkNode(let ordinal):
            guard ordinal == storage.node.ordinal, storage.unlinkedHistory == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.unlinkedHistory = actual
        case .fsyncParent(let ordinal):
            guard ordinal == storage.node.ordinal, storage.syncedHistory == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.syncedHistory = actual
        case .closeNode(let ordinal):
            guard ordinal == storage.node.ordinal, storage.closedHistory == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.closedHistory = actual
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

extension ColdEraseSchema2NamespaceRemovalAttemptV1 {
    /// Distinct permanent readonly fault association. Native's own retained
    /// primary-error frame supplies the only consumer; this is never a grant.
    func requireNamespaceFaultGAssociation(request: ColdEraseSchema2NamespaceRemovalRequestV1,
        permit: ColdEraseSchema2NamespaceRemovalPermitV1) throws {
        guard storage.request === request, storage.permit === permit,
              storage.preparation.storage.attempt === self,
              storage.processMutexEntered, storage.processMutexReturned,
              !storage.processMutexExitEntered, let context = storage.g,
              context.storage.attempt === self else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try context.requireFaultHeldAssociation() // actual acquire0/errno and no entered release; no normal phase revival
    }
    fileprivate func completeClosedSelectedNode() throws -> ColdEraseSchema2NamespaceNodeCompletionV1 {
        do {
            guard storage.completionCandidate == nil, storage.completion == nil,
                  let resource = storage.currentResource, resource.storage.state == .closed,
                  let graph = resource.storage.preimage.storage.parentGraph else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try graph.requireClosedReturn()
            let frame = try captureCurrentNamespace() // real consumed close; Native afterClose epoch and two full passes
            let ordinal = resource.storage.node.ordinal, count = frame.storage.scanner.storage.nodeCount
            let parentRow: ColdEraseSchema2NamespaceCurrentScanRowV4
            if let parent = resource.storage.node.parentOrdinal {
                guard let row = frame.storage.scanner.storage.rows?[count + Int(parent)] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                parentRow = row
            } else { parentRow = frame.storage.supportRow }
            try storage.preparation.reservation.reserveNamespaceConsumerBacking(capture: storage.preparation.capture,
                bytes: ColdEraseSchema2NamespaceNodeCompletionV1.requiredBackingBytes)
            let completion = ColdEraseSchema2NamespaceNodeCompletionV1(attempt: self, resource: resource,
                frame: frame, parentRow: parentRow)
            storage.completionCandidate = completion // before any historical-return/next-selector postproof
            try completion.initialize()
            try consumeCompletion(completion) // actual Main/Native OBS + next REQUEST return, then PFP consumer release
            guard storage.resources?[Int(ordinal)]?.storage.completedConsumer === completion,
                  storage.currentResource == nil, storage.completedResources == ordinal + 1 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            storage.completionCandidate = nil // only actual Resource+Main+Native retain returned completion now
            return completion
        } catch { poisonOnUncertainEffect(); throw error }
    }
}
// COLD_SCHEMA2_NAMESPACE_ACTUAL_NODE_COMPLETION_V4_END


// COLD_SCHEMA2_NAMESPACE_HISTORICAL_COMPLETED_POLICY_FRAME_V4_BEGIN
fileprivate extension ColdEraseSchema2NamespaceSelectedPolicyScopeV1 {
    /// The live Request/physical-pin borrower has already been consumed.
    /// Its actual returned consumer, not a new live grant, owns this DATA.
    func requireCompletedHistoricalObservation(_ actual: ColdEraseSchema2NamespaceSelectedPolicyObservationV1,
        resource: ColdEraseSchema2NamespaceSelectedResourceV1,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        guard storage.state == .consumed, storage.resource === resource, storage.attempt === attempt,
              resource.storage.attempt === attempt, resource.storage.policyScope === self,
              resource.storage.policyRequest === storage.request, storage.observation === actual,
              resource.storage.observation === actual, storage.uncertainDescriptor == nil,
              actual.scopeIdentity == ObjectIdentifier(self), actual.operationID == operationID,
              operationID == attempt.namespaceOperationID, resource.storage.state == .completed,
              resource.storage.failure == nil, resource.storage.durableConsumerReturned,
              let completion = resource.storage.completedConsumer else { throw ProtectedFilePolicyError.identityChanged }
        try completion.requireHistoricalResourceAssociation(resource: resource, attempt: attempt)
        try actual.requireCheckedSettlement() // PFP's immutable checked own-pin-return DATA only
    }
}

fileprivate extension ColdEraseSchema2NamespaceCurrentScanRowV4 {
    /// Exact closed row facts, with the real consumed Scope association and
    /// returned consumer checked locally instead of reentering Native.
    func requireConsumedHistoricalClosedReturn() throws {
        let resource = storage.resource
        guard resource.storage.failure == nil, resource.storage.closeEntered,
              resource.storage.closeReturned == 0, resource.storage.closeErrno != nil, resource.storage.descriptor == -1,
              let post = resource.storage.closePostProof, case .returned = post,
              resource.storage.state == .rowConsumed, resource.storage.row === self,
              let scope = resource.storage.policyScope, scope.storage.state == .consumed,
              scope.storage.context === resource, scope.storage.request === resource.storage.policyRequest,
              scope.storage.attempt === resource.storage.attempt, scope.storage.uncertainDescriptor == nil,
              let observation = resource.storage.observation, scope.storage.observation === observation,
              observation.value == storage.policy, observation.scopeIdentity == ObjectIdentifier(scope),
              observation.operationID == scope.operationID,
              let returned = resource.storage.policyConsumerReturn, case .returned = returned else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try observation.requireCheckedSettlement()
        if let members = storage.members {
            guard members.storage.completed, let cursor = resource.storage.cursor,
                  cursor.storage.completed, cursor.storage.eof, cursor.storage.closeReturned == 0,
                  cursor.storage.members == UInt64(members.count), cursor.storage.closeErrno != nil,
                  cursor.storage.cursorDescriptorReturned == cursor.storage.openReturned,
                  cursor.storage.cursorDescriptorErrno != nil, cursor.storage.cursorInformationReturned == 0,
                  cursor.storage.cursorInformationErrno != nil, let closedInformation = cursor.storage.cursorInformation,
                  ColdEraseSchema2NamespaceSelectedResourceV1.same(closedInformation, storage.information),
                  let post = cursor.storage.closedPostProof, case .returned = post else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        } else {
            guard resource.storage.eof, resource.storage.readOffset == UInt64(storage.information.st_size),
                  storage.contentSHA256 != nil, resource.storage.contentSHA256 == storage.contentSHA256 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }
}

extension ColdEraseSchema2NamespaceCurrentFrameV1 {
    /// Historical closed empty namespace. This performs no Native request,
    /// epoch, live resource, Source, Reader physical pin or policy getter call.
    func requireHistoricalFinishedSelection(attempt: ColdEraseSchema2NamespaceRemovalAttemptV1) throws {
        let scanner = storage.scanner
        guard scanner.storage.attempt === attempt, scanner.storage.frame === self,
              scanner.storage.phase == .checked, scanner.storage.failure == nil,
              scanner.storage.declaredBackingBytes != nil,
              scanner.storage.nodeCount > 0,
              scanner.storage.removedPrefixCount == UInt64(scanner.storage.nodeCount),
              scanner.storage.firstClosed == 0, scanner.storage.secondClosed == 0,
              scanner.storage.firstTokens.returned, scanner.storage.secondTokens.returned,
              scanner.storage.firstTokens.rowCount == 0, scanner.storage.secondTokens.rowCount == 0,
              scanner.storage.firstTokens.pendingCount == 0, scanner.storage.secondTokens.pendingCount == 0,
              scanner.storage.firstTokens.finalized != nil, scanner.storage.secondTokens.finalized != nil,
              scanner.storage.firstTokens.digest == currentPrefixSHA256,
              scanner.storage.secondTokens.digest == currentPrefixSHA256,
              case .absent(let absence) = storage.operations, absence.scanner === scanner,
              scanner.storage.operationsAbsenceOwner === absence,
              let first = scanner.storage.firstAbsence, let second = scanner.storage.secondAbsence,
              first.support === scanner.storage.firstSupport, second.support === scanner.storage.secondSupport,
              first.returned == -1, first.savedErrno == ENOENT, second.returned == -1, second.savedErrno == ENOENT,
              case .returned = first.postProof, case .returned = second.postProof,
              let a = scanner.storage.firstSupport?.storage.row, let b = scanner.storage.secondSupport?.storage.row,
              b === storage.supportRow, let namesA = a.storage.members, let namesB = b.storage.members,
              namesA.count == namesB.count,
              ColdEraseSchema2NamespaceSelectedResourceV1.same(a.storage.information, b.storage.information),
              ColdEraseSchema2NamespaceSelectedResourceV1.same(a.storage.parentInformation, b.storage.parentInformation),
              a.storage.policy == b.storage.policy, a.storage.policyCode == b.storage.policyCode,
              let root = attempt.storage.resources?[scanner.storage.nodeCount - 1],
              root.storage.node.path.isEmpty, root.storage.node.parentOrdinal == nil,
              root.storage.state == .completed, root.storage.durableConsumerReturned,
              let completion = root.storage.completedConsumer,
              completion.storage.frame === self, completion.storage.parentRow === b else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try completion.requireHistoricalResourceAssociation(resource: root, attempt: attempt)
        try a.requireConsumedHistoricalClosedReturn(); try b.requireConsumedHistoricalClosedReturn()
        for index in namesA.indices {
            guard namesA[index].utf8.elementsEqual(namesB[index].utf8) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
        var found = false, retained = attempt.storage.firstCurrentScanner
