    }
}
// COLD_SCHEMA2_NAMESPACE_HISTORICAL_COMPLETED_POLICY_FRAME_V4_END

// COLD_SCHEMA2_NAMESPACE_ACTUAL_FINAL_RECEIPT_REMOVER_V4_BEGIN
/// Actual returned namespace DATA. Construction is private to the real
/// remover after every node's durable consumer and the sole G unlock return.
/// Later borrowers do not rearm a completed epoch or a physical Reader pin.
@MainActor
final class ColdEraseSchema2NamespaceRemovalReceiptV1 {
    fileprivate enum Phase { case retained, ready, consuming, settled, uncertain }
    fileprivate struct ResourceProjection {
        let resource: ColdEraseSchema2NamespaceSelectedResourceV1
        let information: stat
        let completion: ColdEraseSchema2NamespaceNodeCompletionV1
    }
    fileprivate struct Storage {
        let attempt: ColdEraseSchema2NamespaceRemovalAttemptV1
        let request: ColdEraseSchema2NamespaceRemovalRequestV1
        let preparation: ColdEraseSchema2NamespaceRemovalPreparationV1
        let frame: ColdEraseSchema2NamespaceCurrentFrameV1
        let rootCompletion: ColdEraseSchema2NamespaceNodeCompletionV1
        let acquire: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1
        let release: ColdEraseSchema2NamespaceHistoricalReturnedOutcomeV1
        let declaredBackingBytes: UInt64
        var operations: ResourceProjection?
        var lease: ResourceProjection?
        var owners: ResourceProjection?
        var mutation: ResourceProjection?
        var ownerLock: ResourceProjection?
        var resources: ColdEraseSchema2NamespaceRegistryResourcesV1?
        var phase = Phase.retained
        var consumerReturn: ColdEraseSchema2NamespaceRemovalAttemptV1.ConsumerReturn?
        var failure: Error?
    }
    fileprivate var storage: Storage
    fileprivate static var requiredBackingBytes: UInt64 {
        UInt64(MemoryLayout<Storage>.stride + 5 * MemoryLayout<ResourceProjection>.stride
            + MemoryLayout<ColdEraseSchema2NamespaceRegistryResourcesV1>.stride
            + 8 * MemoryLayout<stat>.stride + 12 * MemoryLayout<UInt64>.stride
            + 4 * MemoryLayout<String.UTF8View>.stride + 2 * MemoryLayout<String>.stride
