        var selected: ColdEraseSchema2NamespaceSelectedResourceV1?
        for ordinal in 0..<attempt.storage.initializedResources {
            guard let resource = rows[ordinal], resource.storage.node.ordinal == UInt64(ordinal) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            if resource.storage.node.path == path {
                guard selected == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                selected = resource
            }
        }
        guard let resource = selected, let after = resource.storage.afterSelected,
              let completion = resource.storage.completedConsumer else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try completion.requireHistoricalResourceAssociation(resource: resource, attempt: attempt)
        guard resource.storage.afterSelectedReturned == 0, resource.storage.afterSelectedErrno != nil,
              after.st_nlink == 0, let before = resource.storage.selectedInformation,
              ColdEraseSchema2NamespaceSelectedResourceV1.samePermanent(after, before) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
