                lease: EraseColdControlLeafFactV1(lease.information), owners: EraseColdControlLeafFactV1(owners.information),
                mutation: EraseColdControlLeafFactV1(mutation.information), ownerLock: EraseColdControlLeafFactV1(ownerLock.information),
                supportFlags: support.st_flags, operationsFlags: operations.information.st_flags,
                leaseFlags: lease.information.st_flags, ownersFlags: owners.information.st_flags,
