    private func requireActualKernelHistory() throws {
        let attempt = storage.attempt
        guard storage.failure == nil, attempt.storage.receipt === self,
              attempt.storage.request === storage.request, attempt.namespacePreparation === storage.preparation,
              storage.preparation.storage.attempt === attempt,
              attempt.storage.phase == .released, attempt.storage.failure == nil,
              attempt.storage.completedResources == storage.preparation.nodeCount,
              attempt.storage.currentResource == nil, attempt.storage.completion == nil,
              attempt.storage.completionCandidate == nil, attempt.storage.completionConsumer == nil,
              let slots = attempt.storage.resources, let context = attempt.storage.g,
              context.storage.attempt === attempt, context.storage.phase == .released,
              context.storage.acquireEntered, context.storage.acquireReturned == 0, context.storage.acquireErrno != nil,
              context.storage.releaseEntered, context.storage.releaseReturned == 0, context.storage.releaseErrno != nil,
              let post = context.storage.releasePostProof, case .returned = post,
              storage.acquire.sequence == 1, storage.acquire.sequence < storage.release.sequence,
              storage.release.sequence == UInt64(attempt.storage.initializedHistoricalReturns),
              context.storage.releaseOutcome === storage.release.storage.outcome,
              context.storage.acquireOutcome === storage.acquire.storage.outcome,
              let resources = storage.resources else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try storage.acquire.requireConsumedReturn(attempt: attempt, primitive: .acquireG)
        try storage.release.requireConsumedReturn(attempt: attempt, primitive: .releaseG)
        try storage.frame.requireHistoricalFinishedSelection(attempt: attempt)
        for ordinal in 0..<attempt.storage.initializedResources {
            guard let resource = slots[ordinal], resource.storage.attempt === attempt,
                  resource.storage.node.ordinal == UInt64(ordinal), let completion = resource.storage.completedConsumer else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
