            guard let policy = resource.storage.policyScope, policy.storage.state == .consumed,
                  let actual = resource.storage.observation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try policy.requireCompletedHistoricalObservation(actual, resource: resource, attempt: attempt)
        }
        func same(_ projection: ResourceProjection?, _ fact: EraseColdControlLeafFactV1, _ flags: UInt32) throws {
            guard let projection, projection.resource.storage.completedConsumer === projection.completion,
                  let actual = projection.resource.storage.afterSelected,
                  ColdEraseSchema2NamespaceSelectedResourceV1.same(actual, projection.information),
                  EraseColdControlLeafFactV1(actual) == fact, actual.st_flags == flags, actual.st_nlink == 0 else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try projection.completion.requireHistoricalResourceAssociation(resource: projection.resource, attempt: attempt)
        }
        try same(storage.operations, resources.operations, resources.operationsFlags)
        try same(storage.lease, resources.lease, resources.leaseFlags)
        try same(storage.owners, resources.owners, resources.ownersFlags)
        try same(storage.mutation, resources.mutation, resources.mutationFlags)
        try same(storage.ownerLock, resources.ownerLock, resources.ownerLockFlags)
        guard resources.support == storage.frame.supportFact, resources.supportFlags == storage.frame.supportFlags,
              storage.rootCompletion.storage.frame === storage.frame else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
    func requireCompletedNamespaceRequest(request: ColdEraseSchema2NamespaceRemovalRequestV1,
        attempt: ColdEraseSchema2NamespaceRemovalAttemptV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        guard storage.request === request, storage.attempt === attempt, storage.preparation === preparation,
              storage.phase == .ready || storage.phase == .consuming || storage.phase == .settled else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
