        try requireActualKernelHistory() // no Native/current owner/epoch/Reader physical borrower callback
    }
    func requireBound(owner: ColdEraseSchema2TerminalOwnerV1, registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1) throws {
        let a = storage.attempt.storage
        guard a.owner === owner, a.registry === registry, a.activity === activity,
              a.exclusion === exclusion, a.binding == binding, a.witness === witness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireCompletedNamespaceRequest(request: storage.request, attempt: storage.attempt, preparation: storage.preparation)
    }
    func requireCapacitySupportProjection(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1) throws -> EraseColdControlLeafFactV1 {
        guard storage.attempt.storage.owner === owner, storage.attempt.storage.operation === operation,
              let resources = storage.resources else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireActualKernelHistory(); return resources.support
    }
    func requireCaptureConsumerCompleted(capture: ColdEraseSchema2NamespaceCaptureOwnerV1) throws {
        guard storage.preparation.capture === capture, capture.storage.checkedConsumer === self,
              storage.phase == .settled, let returned = storage.consumerReturn, case .returned = returned else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try requireActualKernelHistory()
    }
    fileprivate func requireRegistryResourcesBeforeClose(owner: ColdEraseSchema2TerminalOwnerV1,
        operation: EraseColdPreparationOperationV1, registry: GenerationLeaseRegistryV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1)
        throws -> ColdEraseSchema2NamespaceRegistryResourcesV1 {
        try requireBound(owner: owner, registry: registry, activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        try requireCaptureConsumerCompleted(capture: storage.preparation.capture)
        guard storage.attempt.storage.operation === operation,
              storage.attempt.storage.processMutexExitEntered, storage.attempt.storage.processMutexExitReturned,
              let resources = storage.resources else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        return resources // fresh Registry close owner supplies its own actual held/named checks
    }
    fileprivate func consume() throws {
        do {
            let attempt = storage.attempt
            guard storage.phase == .ready, storage.consumerReturn == nil,
                  storage.preparation.capture.storage.checkedConsumer == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            storage.phase = .consuming; storage.consumerReturn = .entered
            try attempt.storage.permit.recordSettled(attempt: attempt, receipt: self)
            storage.consumerReturn = .returned // the actual Main+Native+Owner Void consumer returned
            storage.phase = .settled
            storage.preparation.capture.storage.checkedConsumer = self // retain before fallible postproof
            try requireCaptureConsumerCompleted(capture: storage.preparation.capture)
            try attempt.storage.permit.requireSettled(attempt: attempt, receipt: self)
        } catch { storage.consumerReturn = .threw(error); poison(error); throw error }
    }
    fileprivate func poison(_ error: Error) {
        if storage.failure == nil { storage.failure = error }
        storage.phase = .uncertain; storage.attempt.poisonOnUncertainEffect()
        // All same Resource/Scope/Frame/history/journal/FD/error owners stay
        // retained. Failure enters no retry, cleanup, release or decharge.
    }
