extension ColdEraseSchema2NamespaceRemovalAttemptV1 {
    fileprivate func finishActualNamespace() throws -> ColdEraseSchema2NamespaceRemovalReceiptV1 {
        do {
            guard storage.receipt == nil, let request = storage.request, let context = storage.g,
                  storage.completedResources == storage.preparation.nodeCount,
                  let rootResource = storage.resources?[Int(storage.preparation.nodeCount - 1)],
                  let root = rootResource.storage.completedConsumer,
                  let acquire = context.storage.acquireOutcome?.historicalReturned,
                  let release = context.storage.releaseOutcome?.historicalReturned else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try storage.preparation.reservation.reserveNamespaceConsumerBacking(capture: storage.preparation.capture,
                bytes: ColdEraseSchema2NamespaceRemovalReceiptV1.requiredBackingBytes)
            let receipt = ColdEraseSchema2NamespaceRemovalReceiptV1(attempt: self, request: request,
                root: root, acquire: acquire, release: release)
            storage.receipt = receipt // before projection/history/final durable-consumer checks
            try receipt.initialize(); try receipt.consume(); return receipt
        } catch { poisonOnUncertainEffect(); throw error }
    }
}

extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func namespaceActualOwnerLockPath() -> String {
        "generation-leases/owners/" + Self.ownerLockName(ownerID)
    }
    /// One actual finite remover. Durable issuers remain in Native; this
    /// engine consumes real resource operations and their checked returns.
    @MainActor func removeColdSchema2Namespace(preparation: ColdEraseSchema2NamespaceRemovalPreparationV1,
        permit: ColdEraseSchema2NamespaceRemovalPermitV1, owner: ColdEraseSchema2TerminalOwnerV1,
        basis: ColdEraseSchema2NamespacePreparationBasisV1, operation: EraseColdPreparationOperationV1,
        activity: GenerationTemporalActivityHandleV1, exclusion: EraseRetirementExclusionV1,
        binding: EraseRetirementBindingV1, witness: EraseSessionDrainWitnessV1)
        throws -> ColdEraseSchema2NamespaceRemovalReceiptV1 {
        try preparation.requireBound(owner: owner, basis: basis, registry: self, operation: operation,
            activity: activity, exclusion: exclusion, binding: binding, witness: witness)
        return try withColdSchema2NamespaceAttempt(preparation: preparation, permit: permit) { attempt in
            do {
                guard let context = attempt.storage.g, let request = attempt.storage.request else {
                    throw Self.uncertainOwnerFailure()
                }
                try context.acquire() // actual consumed acquire return, no recursive metadata scanner
                for _ in 0..<3 {
                    let frame = try attempt.captureCurrentNamespace()
                    try request.consumeBaselineCurrentScan(epoch: frame.storage.scanner.storage.epoch,
                        attempt: attempt, frame: frame)
                }
                for ordinal in 0..<preparation.nodeCount {
                    guard attempt.storage.completedResources == ordinal,
                          let preimage = attempt.storage.preimages?[Int(ordinal)], preimage.ordinal == ordinal else {
                        throw Self.uncertainOwnerFailure()
                    }
                    try preimage.requireAssociation(preparation: preparation, attempt: attempt)
                    try attempt.prepareSelected(preimage: preimage)
                    try attempt.unlinkSelected()
                    try attempt.syncSelectedParent()
                    try attempt.closeSelected() // own selected and separate ancestor once-closes
                    let completion = try attempt.completeClosedSelectedNode() // real fresh two scans; OBS+nextREQUEST
                    guard completion.ordinal == ordinal, attempt.storage.completedResources == ordinal + 1 else {
                        throw Self.uncertainOwnerFailure()
                    }
                }
                try attempt.requireAllSelectedCompleted()
                try context.release() // actual held-unlinked policy proof and sole consumed LOCK_UN
                return try attempt.finishActualNamespace()
            } catch { attempt.poisonOnUncertainEffect(); throw error }
        }
    }
}
// COLD_SCHEMA2_NAMESPACE_ACTUAL_FINAL_RECEIPT_REMOVER_V4_END

// COLD_SCHEMA2_NAMESPACE_CREATOR_SOURCE_V4_BEGIN
/// Closed representation codes, never Original/Reader inventory ordinals.
/// A code acquires Source provenance only inside the private issuer below.
enum ColdEraseSchema2NamespaceCreatorRoleV4: UInt64 {
    case notificationRoot = 1, creationRecord = 2, control = 3, controlPending = 4
    case mapping = 5, mappingPending = 6, erase = 7, erasePending = 8
    case ownedIDs = 9, ownedIDsTemporary = 10, drain = 11, drainTemporary = 12
    @MainActor fileprivate var memberName: String {
        switch self {
        case .notificationRoot: return AppLockNotificationControlStoreV1.rootName
        case .creationRecord: return EraseSchema2ColdNotificationSourceV1.creationRecordName
        case .control: return AppLockNotificationControlStoreV1.recordName
        case .controlPending: return AppLockNotificationControlStoreV1.pendingName
        case .mapping: return AppLockNotificationControlStoreV1.mappingName
        case .mappingPending: return AppLockNotificationControlStoreV1.mappingPendingName
        case .erase: return AppLockNotificationControlStoreV1.eraseName
        case .erasePending: return AppLockNotificationControlStoreV1.erasePendingName
        case .ownedIDs: return EraseSchema2ColdNotificationSourceV1.ownedIDsName
        case .ownedIDsTemporary: return EraseSchema2ColdNotificationSourceV1.ownedIDsTemporaryName
        case .drain: return EraseSchema2ColdNotificationSourceV1.drainName
        case .drainTemporary: return EraseSchema2ColdNotificationSourceV1.drainTemporaryName
        }
    }
    @MainActor fileprivate static func pathRole(_ node: ColdEraseSchema2NamespaceRemovalNodeV1)
        -> Self? {
        // DATA selection only. Actual Source/row/pin/creator comparisons are
        // mandatory before a selected name is installed in any record.
        if node.path == AppLockNotificationControlStoreV1.rootName { return .notificationRoot }
        if node.path == EraseSchema2ColdNotificationSourceV1.creationRecordName { return .creationRecord }
        guard node.path.utf8.starts(with: AppLockNotificationControlStoreV1.rootName.utf8),
              node.path.utf8.count > AppLockNotificationControlStoreV1.rootName.utf8.count,
              let slash = node.path.firstIndex(of: "/"),
              node.path[..<slash].utf8.elementsEqual(AppLockNotificationControlStoreV1.rootName.utf8) else { return nil }
        let name = node.path[node.path.index(after: slash)...]
        guard !name.isEmpty, !name.contains("/") else { return nil }
        for code in UInt64(3)...12 {
            guard let role = Self(rawValue: code) else { return nil }
            if name.utf8.elementsEqual(role.memberName.utf8) { return role }
        }
        return nil
    }
}

@MainActor
final class ColdEraseSchema2NamespaceCreatorInventoryV4 {
    fileprivate enum State { case building, ready, uncertain }
    fileprivate struct Entry {
        let role: ColdEraseSchema2NamespaceCreatorRoleV4
        let node: ColdEraseSchema2NamespaceRemovalNodeV1
        let parent: ColdEraseSchema2NamespaceRemovalNodeV1
        let parentDomain: UInt64
        let parentValue: UInt64
        let originalOrdinalPlusOne: UInt64
        let raw: Data?
        let rawSHA256: Data
