        var populated: UInt64 = 0
        var recordCount: UInt64 = 0
        var rawByteCount: UInt64 = 0
        var recipeByteCount: UInt64 = 0
        var buffer: UnsafeMutablePointer<UInt8>?
        var bufferCapacity = 0
        var bufferInitialized = 0
        var used = 0
        var emitted: UInt64 = 0
        var state = State.building
        var busy = false
        var recordBorrowEpoch: UInt64 = 0
        var activeRecordIndex: Int?
