    fileprivate func memoryAssociation() throws {
        let preparation = storage.preparation
        guard storage.failure == nil, preparation.storage.creatorInventoryV4 === self,
              preparation.storage.creatorInventoryV4Entered,
              preparation.storage.creatorInventoryV4BackingBytes > 0,
              preparation.capture === storage.capture else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
