              !storage.busy, storage.initialized == storage.entryCapacity,
              storage.populated == storage.recordCount,
              storage.recipeByteCount >= 128, storage.recipeByteCount <= 10_493_056,
              storage.creatorCauseSHA256.count == 32, storage.recordsSHA256.count == 32,
              storage.recipeSHA256.count == 32, storage.basisSHA256.count == 32 else {
