    fileprivate func index(_ role: ColdEraseSchema2NamespaceCreatorRoleV4) throws -> Int {
        let bit = UInt16(1) << Int(role.rawValue - 1)
        guard storage.presentBits & bit != 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let lower = storage.presentBits & (bit - 1)
