            storage.manifest = profile.storage.manifest // real Source owner BEFORE checks
            try profile.storage.manifest.retainNamespaceCreatorLineageV4(inventory: self)
            storage.basisSHA256 = try ColdEraseControlBinaryV1.rawSHA256(storage.preparation.canonicalSHA256)
            for ordinal in 0..<storage.preparation.nodeCount {
                try storage.preparation.withCapturedNode(ordinal: ordinal) { node in
                    guard let role = ColdEraseSchema2NamespaceCreatorRoleV4.pathRole(node) else { return }
                    try self.requireActualCreatorNode(node, role: role)
                    let bit = UInt16(1) << Int(role.rawValue - 1)
