                }
            }
            guard storage.populated == storage.recordCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requireCompleteRoleParents()
            var rawOffset = try ColdEraseControlBinaryV1.adding(128, recordsBytes)
            for index in 0..<storage.entryCapacity {
                guard var value = storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                if let raw = value.raw { value.rawOffset = rawOffset; rawOffset = try ColdEraseControlBinaryV1.adding(rawOffset, UInt64(raw.count)) }
                storage.entries?[index] = value
            }
            guard rawOffset == storage.recipeByteCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let bodyBytes = storage.recipeByteCount - 128
            let causeBytes = try ColdEraseControlBinaryV1.adding(bodyBytes, 72,
                UInt64("FE_COLD_NS_CREATOR_CAUSE_V1\n".utf8.count))
            storage.creatorCauseSHA256 = try hash(expectedByteCount: causeBytes) { sink in
                try self.ascii("FE_COLD_NS_CREATOR_CAUSE_V1\n", sink: sink)
                try self.bytes(self.storage.auxiliary.sha256, sink: sink)
                try self.bytes(self.storage.basisSHA256, sink: sink)
                try self.word(self.storage.recordCount, sink: sink)
                try self.body(zeroCause: true, sink: sink)
            }
            storage.recordsSHA256 = try hash(expectedByteCount: bodyBytes) { sink in try self.body(zeroCause: false, sink: sink) }
            storage.recipeSHA256 = try hash(expectedByteCount: storage.recipeByteCount) { sink in try self.header(sink: sink); try self.body(zeroCause: false, sink: sink) }
            try memoryAssociation(); try requireAllSourceRows()
            storage.state = .ready
            try requireAssociation(preparation: storage.preparation)
        } catch { poison(error); throw error }
    }

    fileprivate func requireActualCreatorNode(_ node: ColdEraseSchema2NamespaceRemovalNodeV1,
        role: ColdEraseSchema2NamespaceCreatorRoleV4) throws {
        try node.sourceOrigin.requireNodeAssociation(node: node, capture: storage.capture)
        let origin = node.row.storage.resource.storage.origin
        guard node.sourceOrigin.provenance == .generatedCreator, origin.provenance == .generatedCreator,
              node.row.storage.resource.storage.originCompleted,
              !origin.requiresUntouchedOriginal, origin.creatorDescriptor != nil,
              origin.members == node.members, origin.kind == node.sourceOrigin.kind,
              node.information.st_flags == node.row.information.st_flags,
              let full = origin.fullFact,
              full == GenerationLeaseRegistryV1.coldSchema2TerminalFullFact(node.information) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if role == .notificationRoot {
            guard node.members != nil, origin.bytes == nil, node.information.st_mode & S_IFMT == S_IFDIR,
                  node.sourceOrigin.kind == .stagingDirectory else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        } else {
            let temporary = role == .controlPending || role == .mappingPending || role == .erasePending
                || role == .ownedIDsTemporary || role == .drainTemporary
            guard node.members == nil, node.information.st_mode & S_IFMT == S_IFREG,
                  node.information.st_nlink == 1, node.information.st_size >= 0,
                  node.sourceOrigin.kind == (temporary ? .journalTemporary : .journal),
                  let raw = origin.bytes, UInt64(raw.count) == UInt64(node.information.st_size),
                  raw.count <= (role == .creationRecord ? 4096 : AppLockNotificationControlStoreV1.maximumRecordBytes),
                  let sha = node.contentSHA256,
                  StoreMigrationCanonicalJSONV1.sha256(raw) == sha else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            if role == .creationRecord {
                guard let actual = storage.creationBytes, raw == actual else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            }
        }
    }
    fileprivate func installEntry(_ node: ColdEraseSchema2NamespaceRemovalNodeV1,
        role: ColdEraseSchema2NamespaceCreatorRoleV4) throws {
        try requireActualCreatorNode(node, role: role)
        let index = try index(role)
        guard storage.entries?[index] == nil, let parentOrdinal = node.parentOrdinal else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.preparation.withCapturedNode(ordinal: parentOrdinal) { parent in
            try parent.sourceOrigin.requireNodeAssociation(node: parent, capture: self.storage.capture)
            let parentDomain: UInt64, parentValue: UInt64
            if role == .notificationRoot || role == .creationRecord {
                guard parent.path.isEmpty, parent.sourceOrigin.provenance == .settledOperations,
                      parent.members != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                var originalParent: UInt64?
                try self.storage.capture.withNamespaceOriginalSelectorNode(node: parent) { original in
                    guard original.parentPhysicalOrdinal == nil, original.physicalKind == 1 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                    originalParent = original.physicalOrdinal
                }
                guard let originalParent else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                parentDomain = 1; parentValue = originalParent
            } else {
                guard parent.path == AppLockNotificationControlStoreV1.rootName,
                      ColdEraseSchema2NamespaceCreatorRoleV4.pathRole(parent) == .notificationRoot else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try self.requireActualCreatorNode(parent, role: .notificationRoot)
                parentDomain = 4; parentValue = 1
            }
            let origin = node.row.storage.resource.storage.origin
            let rawSHA = try node.contentSHA256.map { try ColdEraseControlBinaryV1.rawSHA256($0) } ?? Data(repeating: 0, count: 32)
            let membersSHA = try self.memberDigest(node.members)
            let originalPlusOne = try node.sourceOrigin.originalPhysicalOrdinal.map { try ColdEraseControlBinaryV1.adding($0, 1) } ?? 0
            let value = Entry(role: role, node: node, parent: parent, parentDomain: parentDomain,
                parentValue: parentValue, originalOrdinalPlusOne: originalPlusOne,
                raw: origin.bytes, rawSHA256: rawSHA, membersSHA256: membersSHA)
            self.storage.entries?[index] = value // actual borrowed row/raw retained BEFORE postproof
            self.storage.populated = try ColdEraseControlBinaryV1.adding(self.storage.populated, 1)
            try self.requireActualCreatorNode(node, role: role)
        }
    }
    fileprivate func requireCompleteRoleParents() throws {
        if storage.recordCount == 0 { return }
        let root = try entry(.notificationRoot)
        guard let names = root.node.members else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        var count: UInt64 = 0
        for index in 0..<storage.entryCapacity {
            guard let value = storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if value.role.rawValue >= 3 {
                guard value.parent.sourceOrigin === root.node.sourceOrigin,
                      value.node.parentOrdinal == root.node.ordinal,
                      names.lazy.filter({ $0.utf8.elementsEqual(value.role.memberName.utf8) }).count == 1 else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                count = try ColdEraseControlBinaryV1.adding(count, 1)
            }
        }
        guard count == UInt64(names.count) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for index in names.indices {
            guard !names[index].isEmpty, index == names.startIndex
                || names[names.index(before: index)].utf8.lexicographicallyPrecedes(names[index].utf8) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
        if let source = storage.source, source.rootFact == nil {
            let created = storage.createdReceipt
            guard created?.source === source, created?.checkedSettled == true,
                  let fact = created?.rootFact,
                  fact.device == root.node.information.st_dev, fact.inode == root.node.information.st_ino,
                  fact.mode == root.node.information.st_mode,
                  fact.user == root.node.information.st_uid, fact.group == root.node.information.st_gid,
                  storage.presentBits & (UInt16(1) << 1) != 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        }
    }
    fileprivate func requireAllSourceRows() throws {
        for index in 0..<storage.entryCapacity {
            guard let value = storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try value.node.sourceOrigin.requireNodeAssociation(node: value.node, capture: storage.capture)
            try value.parent.sourceOrigin.requireNodeAssociation(node: value.parent, capture: storage.capture)
        }
    }

    /// Exact immutable recipe byte stream. The buffer is retained before the
    /// first callback; nested entry or a caught callback failure poisons it.
    func withRecipeChunks(_ body: (UInt64, UnsafeRawBufferPointer) throws -> Void) throws {
        do {
            try requireAssociation(preparation: storage.preparation)
            storage.busy = true; storage.used = 0; storage.emitted = 0
            let sink: (UnsafeRawBufferPointer) throws -> Void = { raw in
                let offset = self.storage.emitted
                try self.memoryAssociation(); try self.requireAllSourceRows()
                guard raw.count > 0, raw.count <= 65_536,
                      offset <= self.storage.recipeByteCount,
                      UInt64(raw.count) <= self.storage.recipeByteCount - offset else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                try body(offset, raw)
                try self.memoryAssociation(); try self.requireAllSourceRows()
                self.storage.emitted = try ColdEraseControlBinaryV1.adding(offset, UInt64(raw.count))
            }
            try header(sink: sink); try self.body(zeroCause: false, sink: sink); try flush(sink: sink)
            guard storage.emitted == storage.recipeByteCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            storage.busy = false
            try requireAssociation(preparation: storage.preparation)
        } catch { poison(error); throw error }
    }
    func withRecord(roleCode: UInt64, _ body: (ColdEraseSchema2NamespaceCreatorRecordV4) throws -> Void) throws {
        do {
            try requireAssociation(preparation: storage.preparation)
            guard let role = ColdEraseSchema2NamespaceCreatorRoleV4(rawValue: roleCode) else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let index = try index(role); _ = try entry(role)
            storage.recordBorrowEpoch = try ColdEraseControlBinaryV1.adding(storage.recordBorrowEpoch, 1)
            storage.activeRecordIndex = index
            storage.busy = true
            let record = ColdEraseSchema2NamespaceCreatorRecordV4(inventory: self, index: index,
                borrowEpoch: storage.recordBorrowEpoch)
            try body(record)
            try record.requireRetainedAssociation()
            storage.activeRecordIndex = nil
            storage.busy = false
            try requireAssociation(preparation: storage.preparation)
        } catch { poison(error); throw error }
    }

    fileprivate func flush(sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        guard let buffer = storage.buffer, storage.bufferInitialized == storage.bufferCapacity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if storage.used > 0 { try sink(UnsafeRawBufferPointer(start: buffer, count: storage.used)); storage.used = 0 }
    }
    fileprivate func byte(_ value: UInt8, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        guard let buffer = storage.buffer, storage.used < storage.bufferCapacity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        buffer[storage.used] = value; storage.used += 1
        if storage.used == storage.bufferCapacity { try flush(sink: sink) }
    }
    fileprivate func word(_ value: UInt64, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        for index in 0..<8 { try byte(UInt8(truncatingIfNeeded: value >> (index * 8)), sink: sink) }
    }
    fileprivate func word32(_ value: UInt32, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        for index in 0..<4 { try byte(UInt8(truncatingIfNeeded: value >> (index * 8)), sink: sink) }
    }
    fileprivate func bytes(_ value: Data, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        try value.withUnsafeBytes { raw in
            var offset = 0
            while offset < raw.count {
                guard let input = raw.baseAddress, let buffer = storage.buffer,
                      storage.used >= 0, storage.used < storage.bufferCapacity,
                      storage.bufferInitialized == storage.bufferCapacity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                let count = min(storage.bufferCapacity - storage.used, raw.count - offset)
                buffer.advanced(by: storage.used).update(
                    from: input.advanced(by: offset).assumingMemoryBound(to: UInt8.self), count: count)
                storage.used += count; offset += count
                if storage.used == storage.bufferCapacity { try flush(sink: sink) }
            }
        }
    }
    fileprivate func ascii(_ value: String, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        for byte in value.utf8 { try self.byte(byte, sink: sink) }
    }
    fileprivate func hash(expectedByteCount: UInt64,
        _ encode: ((UnsafeRawBufferPointer) throws -> Void) throws -> Void) throws -> Data {
        guard !storage.busy else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        storage.busy = true; storage.used = 0; storage.emitted = 0
        var hash = SHA256()
        let sink: (UnsafeRawBufferPointer) throws -> Void = { raw in
            self.storage.emitted = try ColdEraseControlBinaryV1.adding(self.storage.emitted, UInt64(raw.count))
            guard self.storage.emitted <= expectedByteCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            hash.update(bufferPointer: raw)
        }
        try encode(sink); try flush(sink: sink)
        guard storage.emitted == expectedByteCount else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let digest = hash.finalize(); let result = Data(digest)
        storage.busy = false
        return result
    }
    fileprivate func memberDigest(_ names: [String]?) throws -> Data {
        guard let names else { return Data(repeating: 0, count: 32) }
        var expected = try ColdEraseControlBinaryV1.adding(8,
            UInt64("FE_COLD_NS_CREATOR_MEMBERS_V1\n".utf8.count))
        for name in names { expected = try ColdEraseControlBinaryV1.adding(expected, 8, UInt64(name.utf8.count)) }
        return try hash(expectedByteCount: expected) { sink in
            try self.ascii("FE_COLD_NS_CREATOR_MEMBERS_V1\n", sink: sink)
            try self.word(UInt64(names.count), sink: sink)
            for name in names {
                try self.word(UInt64(name.utf8.count), sink: sink); try self.ascii(name, sink: sink)
            }
        }
    }
    fileprivate func header(sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        let magic = "FE_COLD_NS_CRE1"
        try ascii(magic, sink: sink)
        for _ in magic.utf8.count..<16 { try byte(0, sink: sink) }
        try word(1, sink: sink); try word(storage.recordCount, sink: sink)
        try bytes(storage.auxiliary.sha256, sink: sink)
        try bytes(storage.basisSHA256, sink: sink); try bytes(storage.recordsSHA256, sink: sink)
    }
    fileprivate func body(zeroCause: Bool, sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        for index in 0..<storage.entryCapacity {
            guard let value = storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try record(value, zeroCause: zeroCause, sink: sink)
        }
        for index in 0..<storage.entryCapacity {
            guard let value = storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if let raw = value.raw { try bytes(raw, sink: sink) }
        }
    }
    fileprivate func record(_ value: Entry, zeroCause: Bool,
        sink: (UnsafeRawBufferPointer) throws -> Void) throws {
        try word(value.role.rawValue, sink: sink); try word(value.parentDomain, sink: sink)
        try word(value.parentValue, sink: sink); try word(value.node.members == nil ? 2 : 1, sink: sink)
        try word(value.node.policyCode, sink: sink); try word(value.originalOrdinalPlusOne, sink: sink)
        try word(value.rawOffset, sink: sink); try word(UInt64(value.raw?.count ?? 0), sink: sink)
        let fact = value.node.information
        try word(UInt64(bitPattern: Int64(fact.st_dev)), sink: sink)
        try word(UInt64(fact.st_ino), sink: sink); try word(UInt64(fact.st_mode), sink: sink)
        try word(UInt64(fact.st_uid), sink: sink); try word(UInt64(fact.st_gid), sink: sink)
        try word(UInt64(fact.st_nlink), sink: sink); try word(UInt64(bitPattern: Int64(fact.st_size)), sink: sink)
        try word(UInt64(bitPattern: Int64(fact.st_mtimespec.tv_sec)), sink: sink)
        try word(UInt64(bitPattern: Int64(fact.st_mtimespec.tv_nsec)), sink: sink)
        try word(UInt64(bitPattern: Int64(fact.st_ctimespec.tv_sec)), sink: sink)
        try word(UInt64(bitPattern: Int64(fact.st_ctimespec.tv_nsec)), sink: sink)
        try bytes(value.rawSHA256, sink: sink)
        if zeroCause { for _ in 0..<32 { try byte(0, sink: sink) } }
        else { try bytes(storage.creatorCauseSHA256, sink: sink) }
        try bytes(value.membersSHA256, sink: sink)
        try word32(UInt32(fact.st_flags), sink: sink); try word32(0, sink: sink)
    }
}

@MainActor
struct ColdEraseSchema2NamespaceCreatorRecordV4 {
    fileprivate let inventory: ColdEraseSchema2NamespaceCreatorInventoryV4
    fileprivate let index: Int
    fileprivate let borrowEpoch: UInt64
    fileprivate var value: ColdEraseSchema2NamespaceCreatorInventoryV4.Entry {
        get throws {
            try requireRetainedAssociation()
            guard let value = inventory.storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return value
        }
    }
    var roleCode: UInt64 { get throws { try value.role.rawValue } }
    var parentDomain: UInt64 { get throws { try value.parentDomain } }
    var parentValue: UInt64 { get throws { try value.parentValue } }
    var node: ColdEraseSchema2NamespaceRemovalNodeV1 { get throws { try value.node } }
    var parent: ColdEraseSchema2NamespaceRemovalNodeV1 { get throws { try value.parent } }
    var rawByteCount: UInt64 { get throws { UInt64(try value.raw?.count ?? 0) } }
    var rawSHA256: Data { get throws { try value.rawSHA256 } }
    var membersSHA256: Data { get throws { try value.membersSHA256 } }
    fileprivate func requireRetainedAssociation() throws {
        guard inventory.storage.failure == nil, inventory.storage.state == .ready,
              inventory.storage.busy, index >= 0, index < inventory.storage.entryCapacity,
              inventory.storage.activeRecordIndex == index,
              inventory.storage.recordBorrowEpoch == borrowEpoch,
              let value = inventory.storage.entries?[index] else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try inventory.memoryAssociation()
        try value.node.sourceOrigin.requireNodeAssociation(node: value.node, capture: inventory.storage.capture)
        try value.parent.sourceOrigin.requireNodeAssociation(node: value.parent, capture: inventory.storage.capture)
    }
    func withRawChunks(_ body: (UInt64, UnsafeRawBufferPointer) throws -> Void) throws {
        do {
            try requireRetainedAssociation()
            guard let raw = try value.raw else { return }
            try raw.withUnsafeBytes { bytes in
                var offset = 0
                while offset < bytes.count {
                    let count = min(65_536, bytes.count - offset)
                    try requireRetainedAssociation()
                    try body(UInt64(offset), UnsafeRawBufferPointer(rebasing: bytes[offset..<(offset + count)]))
                    try requireRetainedAssociation(); offset += count
                }
            }
        } catch { inventory.poison(error); throw error }
    }
}

extension ColdEraseSchema2NamespaceRemovalPreparationV1 {
    func withCreatorInventoryV4(_ body: (ColdEraseSchema2NamespaceCreatorInventoryV4) throws -> Void) throws {
        do {
            try requireCaptureAssociation(capture: capture)
            if storage.creatorInventoryV4 == nil {
                guard !storage.creatorInventoryV4Entered, storage.creatorInventoryV4BackingBytes == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                let bytes = try ColdEraseSchema2NamespaceCreatorInventoryV4.requiredFixedBackingBytes()
                storage.creatorInventoryV4Entered = true; storage.creatorInventoryV4BackingBytes = bytes
                try reservation.reserveNamespaceConsumerBacking(capture: capture, bytes: bytes)
                try reservation.withNamespaceAuxiliaryDigest(capture: capture, preparation: self) { auxiliary in
                    let inventory = ColdEraseSchema2NamespaceCreatorInventoryV4(preparation: self, auxiliary: auxiliary)
                    self.storage.creatorInventoryV4 = inventory // SAME actual aux owner BEFORE any checker/hash/profile callback
                    try inventory.initialize()
                }
            }
            guard let actual = storage.creatorInventoryV4 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try actual.requireAssociation(preparation: self)
            try body(actual)
            try actual.requireAssociation(preparation: self)
        } catch {
            if let actual = storage.creatorInventoryV4 { actual.poison(error) }
            else { storage.failure = error; capture.poisonOnUncertainEffect(); storage.owner.poisonOnUncertainEffect() }
            throw error
        }
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    fileprivate func retainNamespaceCreatorLineageV4(inventory: ColdEraseSchema2NamespaceCreatorInventoryV4) throws {
        let capture = inventory.storage.capture
        guard inventory.storage.manifest === self, let source = schema2ColdNotificationWitness else { throw StoreMigrationFailure.invalidIdentity }
        inventory.storage.source = source
        inventory.storage.createdReceipt = schema2ColdNamespaceCreatorReceiptV4
        inventory.storage.creationBytes = schema2ColdNotificationCreationBytes
        try source.requireNamespaceCreatorLineageV4(manifest: self,
            operation: inventory.storage.preparation.storage.operation)
        guard opened, !closeAttempted, !coldScratchParentsUncertain,
              !schema2ColdNotificationCaptureInFlight, !schema2ColdNotificationMutationInFlight,
              schema2ColdNotificationMutationToken == nil, !leaseReaderPublicationInFlight,
              !leaseReaderSettlementInFlight, postGenerationProjection != nil, coldTerminalTargetObservation != nil,
              source.manifestIdentity == ObjectIdentifier(self),
              capture.storage.basis === inventory.storage.preparation.storage.basis,
              (schema2ColdNotificationProjectedNames ?? source.names).count == schema2ColdNotificationFiles.count,
              (schema2ColdNotificationProjectedBytes ?? source.leafBytes).count == schema2ColdNotificationFiles.count,
              (schema2ColdNotificationProjectedFacts ?? source.leafFacts).count == schema2ColdNotificationFiles.count else {
            throw StoreMigrationFailure.invalidIdentity
        }
        if let raw = schema2ColdNotificationCreationBytes {
            guard raw.count <= 4096, raw == schema2ColdNotificationExpectedCreationBytes,
                  schema2ColdNotificationCreationRecord == schema2ColdNotificationExpectedCreationRecord,
                  schema2ColdNotificationCreationFact != nil,
                  operationsChildren[EraseSchema2ColdNotificationSourceV1.creationRecordName] != nil else {
                throw StoreMigrationFailure.invalidIdentity
            }
        } else {
            guard schema2ColdNotificationCreationRecord == nil, schema2ColdNotificationCreationFact == nil,
                  operationsChildren[EraseSchema2ColdNotificationSourceV1.creationRecordName] == nil else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
        if source.rootFact == nil {
            if operationsChildren[AppLockNotificationControlStoreV1.rootName] != nil {
                guard let actual = inventory.storage.createdReceipt, actual.source === source,
                      actual.checkedSettled, source.projectedRootIdentity == actual.rootIdentity else {
                    throw StoreMigrationFailure.invalidIdentity
                }
            } else {
                // Genuine retained absence, not permission to omit a present
                // Creator receipt or manufacture an empty inventory.
                guard source.projectedRootIdentity == nil,
                      schema2ColdNotificationFiles.isEmpty,
                      (schema2ColdNotificationProjectedNames ?? source.names).isEmpty,
                      schema2ColdNotificationCreationBytes == nil,
                      inventory.storage.createdReceipt == nil else {
                    throw StoreMigrationFailure.invalidIdentity
                }
            }
        }
    }
}

extension EraseSchema2ColdNotificationSourceV1 {
    fileprivate func requireNamespaceCreatorLineageV4(manifest: EraseSchema2ColdManifestOwnerV1,
        operation: EraseColdPreparationOperationV1) throws {
        guard manifestOwner === manifest, self.operation === operation,
              manifestIdentity == ObjectIdentifier(manifest) else { throw StoreMigrationFailure.invalidIdentity }
    }
}
