// COLD_SCHEMA2_NAMESPACE_CREATOR_SELECTOR_V4_BEGIN
/// Creator provenance DATA from the genuine closed Source inventory and
/// actual durable kind3 pin. No Original/Reader ordinal is constructed.
@MainActor
struct ColdEraseSchema2NamespaceCreatorNodeSelectorV4 {
    private struct Storage {
        let inventory: ColdEraseSchema2NamespaceCreatorInventoryV4
        let pin: ColdEraseSchema2NamespaceCreatorRecipePinV4
        let sourceOrigin: ColdEraseSchema2NamespaceRemovalSourceOriginV1
        let parentSourceOrigin: ColdEraseSchema2NamespaceRemovalSourceOriginV1
        let nodeOrdinal: UInt64
        let capturedParentOrdinal: UInt64
        let recordIndex: Int
        let roleCode: UInt64
        let parentDomain: UInt64
        let parentValue: UInt64
    }
    private let storage: Storage
    var selectorDomain: UInt64 { 3 }
    var selectorOrdinal: UInt64 { storage.roleCode }
    var parentDomain: UInt64 { storage.parentDomain }
    var parentOrdinal: UInt64 { storage.parentValue }
    var creatorRecipeOffset: UInt64 { storage.pin.offset }
    var creatorRecipeByteCount: UInt64 { storage.pin.byteCount }
    var creatorRecipeSHA256: Data { storage.pin.sha256 }

    static func requiredBackingBytes() throws -> UInt64 {
        try ColdEraseControlBinaryV1.adding(UInt64(MemoryLayout<Storage>.stride),
            UInt64(MemoryLayout<ColdEraseSchema2NamespaceCreatorRecordV4>.stride),
            UInt64(MemoryLayout<ColdEraseSchema2NamespaceCreatorInventoryV4.Entry>.stride),
            UInt64(2 * MemoryLayout<ColdEraseSchema2NamespaceRemovalNodeV1>.stride),
            UInt64(4 * MemoryLayout<UInt64>.stride))
    }
    private init(inventory: ColdEraseSchema2NamespaceCreatorInventoryV4,
        pin: ColdEraseSchema2NamespaceCreatorRecipePinV4,
        entry: ColdEraseSchema2NamespaceCreatorInventoryV4.Entry, index: Int) {
        storage = Storage(inventory: inventory, pin: pin, sourceOrigin: entry.node.sourceOrigin,
            parentSourceOrigin: entry.parent.sourceOrigin, nodeOrdinal: entry.node.ordinal,
            capturedParentOrdinal: entry.parent.ordinal, recordIndex: index,
            roleCode: entry.role.rawValue, parentDomain: entry.parentDomain, parentValue: entry.parentValue)
    }
    static func withCreator(node: ColdEraseSchema2NamespaceRemovalNodeV1,
        parent: ColdEraseSchema2NamespaceRemovalNodeV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1,
        inventory: ColdEraseSchema2NamespaceCreatorInventoryV4,
        pin: ColdEraseSchema2NamespaceCreatorRecipePinV4,
        _ body: (ColdEraseSchema2NamespaceCreatorNodeSelectorV4) throws -> Void) throws {
        do {
            try inventory.requireAssociation(preparation: preparation)
            try pin.requireAssociation(inventory: inventory, preparation: preparation)
            try preparation.reservation.reserveNamespaceConsumerBacking(capture: preparation.capture,
                bytes: try requiredBackingBytes())
            guard let role = ColdEraseSchema2NamespaceCreatorRoleV4.pathRole(node),
                  node.sourceOrigin.provenance == .generatedCreator,
                  node.parentOrdinal == parent.ordinal else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            var index: Int?
            try inventory.withRecord(roleCode: role.rawValue) { record in
                let entry = try record.value
                guard entry.node.sourceOrigin === node.sourceOrigin,
                      entry.parent.sourceOrigin === parent.sourceOrigin,
                      entry.node.ordinal == node.ordinal, entry.parent.ordinal == parent.ordinal else {
                    throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
                try node.sourceOrigin.requireNodeAssociation(node: node, capture: preparation.capture)
                try parent.sourceOrigin.requireNodeAssociation(node: parent, capture: preparation.capture)
                index = record.index
            }
            guard let index, let entry = inventory.storage.entries?[index], entry.role == role else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try pin.requireAssociation(inventory: inventory, preparation: preparation)
            let selector = Self(inventory: inventory, pin: pin, entry: entry, index: index)
            // The genuine selected-preimage receiver retains this SAME value
            // before its first fallible postproof. No range is invented here.
            try body(selector)
            try selector.requireNodeAssociation(node: node, parent: parent, preparation: preparation)
        } catch { inventory.poison(error); throw error }
    }
    func requireNodeAssociation(node: ColdEraseSchema2NamespaceRemovalNodeV1,
        parent: ColdEraseSchema2NamespaceRemovalNodeV1,
        preparation: ColdEraseSchema2NamespaceRemovalPreparationV1) throws {
        try storage.inventory.requireAssociation(preparation: preparation)
        try storage.pin.requireAssociation(inventory: storage.inventory, preparation: preparation)
        guard storage.sourceOrigin === node.sourceOrigin, storage.parentSourceOrigin === parent.sourceOrigin,
              storage.nodeOrdinal == node.ordinal, storage.capturedParentOrdinal == parent.ordinal,
              node.parentOrdinal == parent.ordinal,
              let entry = storage.inventory.storage.entries?[storage.recordIndex],
              entry.node.sourceOrigin === node.sourceOrigin, entry.parent.sourceOrigin === parent.sourceOrigin,
              entry.role.rawValue == storage.roleCode, entry.parentDomain == storage.parentDomain,
              entry.parentValue == storage.parentValue,
              storage.pin.byteCount == storage.inventory.recipeByteCount,
              storage.pin.sha256 == storage.inventory.recipeSHA256 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try node.sourceOrigin.requireNodeAssociation(node: node, capture: preparation.capture)
        try parent.sourceOrigin.requireNodeAssociation(node: parent, capture: preparation.capture)
    }
}
