/// Actual post-Erase ordinary lease publication result. A caller token or an
/// old constructor frame cannot mint this result: the fixed Registry publisher
/// supplies its returned wrapper and same ended allocation/resource Scope.
@MainActor
final class ColdEraseSchema2CompletedLeasePublicationV1 {
    fileprivate enum Origin: Equatable { case reader, writer }
    private weak var readerOrigin: GenerationLeaseAllocationAttemptV1?
    private weak var writerOrigin: GenerationWriterAllocationAttemptV1?
    private weak var owner: ColdEraseSchema2CompletedStartupOwnerV1?
    private let registry: GenerationLeaseRegistryV1
    private let scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1
    private let origin: Origin
    private let token: GenerationLeaseTokenV1
    private let handle: GenerationLeaseHandleV1
    private var publishedOwnershipConsumed = false

    fileprivate init(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        registry: GenerationLeaseRegistryV1,
        scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1,
        reader: GenerationLeaseAllocationAttemptV1, handle: GenerationLeaseHandleV1) throws {
        try owner.requireReaderAllocation(reader, registry: registry)
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, reader: reader)
        guard reader.registry === registry, reader.handle === handle,
              reader.token == handle.token, handle.token.role == .reader,
              handle.token.ownerID == registry.ownerID,
              handle.token.epoch == reader.generationEpoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try handle.requireExactRegistry(registry)
        try registry.requireCompletedStartupReaderPublicationRecord(reader,
            owner: owner, scope: scope, handle: handle)
        self.owner = owner; self.registry = registry; self.scope = scope
        origin = .reader; readerOrigin = reader; token = handle.token; self.handle = handle
    }

    fileprivate init(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        registry: GenerationLeaseRegistryV1,
        scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1,
        writer: GenerationWriterAllocationAttemptV1, handle: GenerationLeaseHandleV1) throws {
        try owner.requireWriterAllocation(writer, registry: registry)
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, writer: writer)
        guard writer.registry === registry, writer.handle === handle,
              writer.token == handle.token, handle.token.role == .writer,
              handle.token.ownerID == registry.ownerID,
              handle.token.epoch == writer.generationEpoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try handle.requireExactRegistry(registry)
        try registry.requireCompletedStartupWriterPublicationRecord(writer,
            owner: owner, scope: scope, handle: handle)
        self.owner = owner; self.registry = registry; self.scope = scope
        origin = .writer; writerOrigin = writer; token = handle.token; self.handle = handle
    }

    func requireRetainedReader(_ reader: GenerationLeaseAllocationAttemptV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1, registry: GenerationLeaseRegistryV1) throws {
        guard !publishedOwnershipConsumed, self.owner === owner, self.registry === registry,
              origin == .reader, readerOrigin === reader,
              reader.handle === handle, reader.token == token, handle.token == token,
              reader.generationEpoch == token.epoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, reader: reader)
        try registry.requireCompletedStartupReaderPublicationRecord(reader,
            owner: owner, scope: scope, handle: handle)
    }

    func requireRetainedWriter(_ writer: GenerationWriterAllocationAttemptV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1, registry: GenerationLeaseRegistryV1) throws {
        guard !publishedOwnershipConsumed, self.owner === owner, self.registry === registry,
              origin == .writer, writerOrigin === writer,
              writer.handle === handle, writer.token == token, handle.token == token,
              writer.generationEpoch == token.epoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, writer: writer)
        try registry.requireCompletedStartupWriterPublicationRecord(writer,
            owner: owner, scope: scope, handle: handle)
    }

    func requirePublishedOwnershipConsumed(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        registry: GenerationLeaseRegistryV1, receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        reader: GenerationLeaseAllocationAttemptV1) throws {
        guard publishedOwnershipConsumed, self.owner === owner, self.registry === registry,
              origin == .reader, readerOrigin === reader, reader.handle === handle,
              reader.token == token, handle.token == token else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, reader: reader)
        try registry.requireConsumedCompletedStartupPublicationRecord(reader: reader, token: token)
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
    }
    func requirePublishedOwnershipConsumed(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        registry: GenerationLeaseRegistryV1, receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        writer: GenerationWriterAllocationAttemptV1) throws {
        guard publishedOwnershipConsumed, self.owner === owner, self.registry === registry,
              origin == .writer, writerOrigin === writer, writer.handle === handle,
              writer.token == token, handle.token == token else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try scope.requirePositivePermanentSettlement(registry: registry, owner: owner, writer: writer)
        try registry.requireConsumedCompletedStartupPublicationRecord(writer: writer, token: token)
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
    }

    /// Called only after the actual Router has installed this same Session,
    /// Coordinator, Writer and provider in its published lifecycle.
    func consumePublishedOwnership(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        registry: GenerationLeaseRegistryV1) throws {
        guard !publishedOwnershipConsumed, self.owner === owner, self.registry === registry else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try owner.requirePublishedRegistryOwnershipTransfer(registry)
        switch origin {
        case .reader:
            guard let reader = readerOrigin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requireRetainedReader(reader, owner: owner, registry: registry)
            try registry.consumeCompletedStartupReaderPublicationRecord(reader,
                owner: owner, scope: scope, handle: handle)
        case .writer:
            guard let writer = writerOrigin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try requireRetainedWriter(writer, owner: owner, registry: registry)
            try registry.consumeCompletedStartupWriterPublicationRecord(writer,
                owner: owner, scope: scope, handle: handle)
        }
        publishedOwnershipConsumed = true
    }
}

extension GenerationLeaseRegistryV1 {
    /// Completed-only overload of the same original/replacement capture
    /// algorithm. Its fixed Scope owns the actual original before open.
    @MainActor private func captureFreshAdoptionReplacementLocked(
        _ record: FreshAdoptionReplacement,
        observed: TemporalGenerationRegistryObservationV1,
        replacement: RegistryStateV1,
        completedSchema2Scope scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
        guard record.completedSchema2Scope === scope, record.replacement == nil,
              !record.originalCloseAttempted, !record.closeUncertain else { throw Self.identityFailure() }
        let resource = try scope.registryOriginalResource(registry: self)
        guard record.completedSchema2OriginalResource == nil, record.original < 0 else {
            throw Self.uncertainOwnerFailure()
        }
        record.completedSchema2OriginalResource = resource
        try resource.open(flags: O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC, mode: 0)
        record.original = resource.descriptor // actual result before later proof/encoding
        let before = try resource.heldStat()
        let snapshot = FileSnapshot(before)
        try resource.requireNamed(fact: before)
        let bytes = try resource.readAll(maximumBytes: Self.maximumControlFileBytes)
        guard bytes == observed.registryBytes,
              FileSnapshot(try resource.heldStat()) == snapshot else { throw Self.identityFailure() }
        let replacementBytes = try replacement.canonicalData()
        let attempt = TemporalReleaseAttempt(token: record.token, original: resource.descriptor,
            snapshot: snapshot, originalBytes: bytes, replacementBytes: replacementBytes)
        attempt.completedSchema2Scope = scope
        attempt.completedSchema2OriginalResource = resource
        record.replacement = attempt
        record.original = -1 // the actual replacement now owns the exact resource
    }

    /// Same held-original/O_EXCL-temp/canonical-write/rename/fsync algorithm
    /// as the incumbent engine, using the new actual allocation resources.
    /// The ordinary and Original overloads retain their exact bodies.
    @MainActor private func finishTemporalReplacementLocked(
        _ attempt: TemporalReleaseAttempt,
        completedSchema2Scope scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws {
        try attempt.requireCertainDescriptors()
        guard attempt.completedSchema2Scope === scope,
              let original = attempt.completedSchema2OriginalResource else {
            throw Self.uncertainOwnerFailure()
        }
        if !attempt.renamed {
            let old = try RegistryStateV1.decodeCanonical(from: attempt.originalBytes)
            let replacement = try RegistryStateV1.decodeCanonical(from: attempt.replacementBytes)
            let oldIDs = Set(old.leases.map(\.leaseID))
            if replacement.leases.contains(where: { !oldIDs.contains($0.leaseID) }) {
                try scope.requireNoDrainedC05PreparationForLeaseInsertion(registry: self)
            }
            let originalBefore = try original.heldStat()
            try original.requireNamed(fact: originalBefore)
            guard FileSnapshot(originalBefore) == attempt.originalSnapshot else { throw Self.identityFailure() }
            _ = try scope.observePolicy(resource: original, kind: .generationLeaseControl)
            if attempt.temporary < 0 {
                let resource = try scope.registryTemporaryResource(registry: self)
                guard attempt.completedSchema2TemporaryResource == nil else { throw Self.uncertainOwnerFailure() }
                attempt.completedSchema2TemporaryResource = resource // before O_EXCL open
                try resource.open(flags: O_RDWR | O_CREAT | O_EXCL | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC,
                    mode: mode_t(0o600))
                attempt.temporary = resource.descriptor
                attempt.temporaryIdentity = Identity(try resource.heldStat())
            }
            guard let temporary = attempt.completedSchema2TemporaryResource,
                  let temporaryIdentity = attempt.temporaryIdentity else { throw Self.identityFailure() }
            let temporaryBefore = try temporary.heldStat()
            try temporary.requireNamed(fact: temporaryBefore)
            guard Identity(temporaryBefore) == temporaryIdentity else { throw Self.identityFailure() }
            if attempt.preparedSnapshot == nil {
                _ = try scope.applyPolicy(resource: temporary, kind: .generationLeaseControlTemporary)
                try temporary.truncateToZero()
                try temporary.rewind()
                try temporary.writeAll(attempt.replacementBytes)
                try temporary.synchronize()
                try temporary.rewind()
                let before = FileSnapshot(try temporary.heldStat())
                guard try temporary.readAll(maximumBytes: Self.maximumControlFileBytes) == attempt.replacementBytes,
                      FileSnapshot(try temporary.heldStat()) == before else { throw Self.identityFailure() }
                _ = try scope.observePolicy(resource: temporary, kind: .generationLeaseControlTemporary)
                attempt.preparedSnapshot = FileSnapshot(try temporary.heldStat())
            }
            guard let prepared = attempt.preparedSnapshot,
                  FileSnapshot(try temporary.heldStat()) == prepared,
                  FileSnapshot(try original.heldStat()) == attempt.originalSnapshot else {
                throw Self.identityFailure()
            }
            try original.requireNamed(fact: try original.heldStat())
            try temporary.requireNamed(fact: try temporary.heldStat())
            try scope.requireRegistryProjection(registry: self)
            try scope.installRegistryTemporary(registry: self, original: original, temporary: temporary)
            attempt.renamed = true // the Scope captured the real returned rename first
        }
        guard let temporary = attempt.completedSchema2TemporaryResource,
              let identity = attempt.temporaryIdentity else { throw Self.identityFailure() }
        let canonical = try temporary.heldStat()
        guard Identity(canonical) == identity else { throw Self.identityFailure() }
        try temporary.requireNamed(fact: canonical)
        try scope.synchronizeLeaseDirectory(registry: self)
        let persisted = try scope.observeRegistry(registry: self)
        guard persisted.registryBytes == attempt.replacementBytes else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        try temporary.requireNamed(fact: try temporary.heldStat())
    }

    @MainActor fileprivate func publishSchema2ColdCompletedStartupReader(
        _ allocation: GenerationLeaseAllocationAttemptV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1) throws -> GenerationLeaseHandleV1 {
        guard allocation.registry === self else { throw Self.uncertainOwnerFailure() }
        try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
        let handle = try scope.withGenerationMutation(registry: self, owner: owner, reader: allocation) {
            try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
            try scope.requireNoMigrationReservation(registry: self)
            let observed = try scope.observeRegistry(registry: self)
            guard observed.leases.isEmpty else { throw Self.uncertainOwnerFailure() }
            guard observed.leases.count < Self.maximumActiveLeaseCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let owners = Set(observed.leases.map(\.ownerID))
            guard owners.contains(ownerID) || owners.count < Self.maximumOwnerCount else {
                throw GenerationLeaseRegistryFailureV1.registryLimitExceeded
            }
            let token = try GenerationLeaseTokenV1(leaseID: makeLeaseID(), ownerID: ownerID,
                epoch: allocation.epoch, role: .reader, acquiredAt: now())
            guard !observed.leases.contains(where: { $0.leaseID == token.leaseID }), allocation.token == nil else {
                throw GenerationLeaseRegistryFailureV1.duplicateLease
            }
            allocation.token = token // true non-deterministic birth, before publication
            let record = FreshAdoptionReplacement(token: token)
            record.completedSchema2Scope = scope
            let id = ObjectIdentifier(allocation)
            guard completedSchema2StartupReaderPublications.isEmpty,
                  completedSchema2StartupReaderPublications[id] == nil else { throw Self.uncertainOwnerFailure() }
            completedSchema2StartupReaderPublications[id] = record
            try captureFreshAdoptionReplacementLocked(record, observed: observed,
                replacement: RegistryStateV1(leases: observed.leases + [token]), completedSchema2Scope: scope)
            guard let attempt = record.replacement else { throw Self.identityFailure() }
            try finishTemporalReplacementLocked(attempt, completedSchema2Scope: scope)
            let current = try scope.observeRegistry(registry: self)
            guard current.leases == [token], !current.leases.contains(where: { $0.role == .writer }) else {
                throw Self.uncertainOwnerFailure()
            }
            let handle = try GenerationLeaseHandleV1(registry: self, publishedReaderToken: token)
            allocation.handle = handle // before actual outer G/SH settlement can refuse
            try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
            return handle
        }
        try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
        try scope.withGenerationMutation(registry: self, owner: owner, reader: allocation) {
            try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
            guard let record = completedSchema2StartupReaderPublications[ObjectIdentifier(allocation)],
                  record.completedSchema2Scope === scope else { throw Self.identityFailure() }
            let observed = try scope.observeRegistry(registry: self)
            guard observed.leases == [handle.token] else { throw Self.uncertainOwnerFailure() }
            try record.closeForSchema2CompletedStartup(scope: scope)
        }
        try allocation.requireCompletedSchema2StartupAcquiring(owner, scope: scope)
        try scope.requirePositivePermanentSettlement(registry: self, owner: owner, reader: allocation)
        return handle
    }

