/// Ownership transfer result from the same actual Ready receiver. It does
/// not cache a content/access decision: the ordinary writer fence continues
/// to prove its live current epoch and active lease for every operation.
@MainActor
fileprivate final class ColdEraseSchema2CompletedFenceLifecycleTransferV1 {
    private weak var fence: StaleWriterFenceV1?
    private let registry: GenerationLeaseRegistryV1
    private let writerToken: GenerationLeaseTokenV1
    private let epoch: GenerationEpochV1
    fileprivate init(fence: StaleWriterFenceV1, registry: GenerationLeaseRegistryV1,
        writerToken: GenerationLeaseTokenV1, epoch: GenerationEpochV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,
        receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1) throws {
        try owner.requireCompletedStartupLeaseOwnershipConsumed(registry: registry)
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
        guard fence.retainedTemporalRegistry === registry,
              fence.writerLeaseToken == writerToken, fence.expectedGenerationEpoch == epoch,
              writerToken.role == .writer, writerToken.ownerID == registry.ownerID,
              writerToken.epoch == epoch else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        self.fence = fence; self.registry = registry; self.writerToken = writerToken; self.epoch = epoch
    }
    fileprivate func requireBound(fence: StaleWriterFenceV1, registry: GenerationLeaseRegistryV1,
        writerToken: GenerationLeaseTokenV1, epoch: GenerationEpochV1) throws {
        guard self.fence === fence, self.registry === registry, self.writerToken == writerToken,
              self.epoch == epoch, fence.retainedTemporalRegistry === registry,
              fence.writerLeaseToken == writerToken, fence.expectedGenerationEpoch == epoch else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}


