extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func withCompletedSchema2CheckedGenerationMutation<Value>(
        resources: ColdEraseSchema2CompletedRegistryResourcesV1,
        _ body: @MainActor () throws -> Value) throws -> Value {
        try resources.requireCurrentFrame()
        Self.processMutationLock.lock()
        defer { Self.processMutationLock.unlock() }
        guard generationMutationLockDepth == 0,
              resources.storage.generationIntervals.count < 2 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let interval = ColdEraseSchema2CompletedRegistryGenerationIntervalV1(
            resources: resources, descriptor: mutationLockDescriptor)
        resources.storage.generationIntervals.append(interval) // before flock
        try resources.requireKernelGraph()
        interval.storage.lockEntered = true
        try resources.enter(interval, .generationLock)
        let locked = flock(mutationLockDescriptor, LOCK_EX), lockErrno = errno
        interval.storage.lockReturned = locked
        let result = Result {
            // Actual lock return is already retained. A capture postcondition
            // can refuse, but cannot skip teardown of a real acquired G.
            try resources.record(interval, .generationLock, returned: Int64(locked), savedErrno: lockErrno)
            guard locked == 0 else {
                resources.poisonOnUncertainEffect()
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            generationMutationLockDepth = 1
            try resources.requireKernelGraph()
            let value = try body()
            try resources.requireKernelGraph()
            interval.storage.bodyReturned = true
            return value
        }
        if case .failure(let error) = result { interval.storage.bodyError = error }
        // Independent once-unlock remains due even after a body/resource
        // failure. It uses only this genuine acquired interval's teardown,
        // never a revoked-frame product-effect permission.
        if locked == 0 {
            interval.storage.unlockEntered = true
            do {
                try resources.enterSettlement(interval, .generationUnlock)
                let unlocked = flock(mutationLockDescriptor, LOCK_UN), unlockErrno = errno
                interval.storage.unlockReturned = unlocked
                try resources.recordSettlement(interval, .generationUnlock,
                    returned: Int64(unlocked), savedErrno: unlockErrno)
                guard unlocked == 0 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            } catch {
                interval.storage.settlementError = error
                resources.poisonOnUncertainEffect()
            }
        }
        generationMutationLockDepth = 0
        if let settlementError = interval.storage.settlementError { throw settlementError }
        return try result.get()
    }
}

