        try temporary.writeAll(bytes); try temporary.synchronize()
        guard try temporary.readAll() == bytes else { throw GenerationLeaseRegistryFailureV1.corruptRegistry }
        let prepared = try temporary.heldStat(); try temporary.requireNamed(fact: prepared)
        let beforeParent = try resources.captureHeldFact(lease)
        try resources.captureNamedFact(lease, expected: beforeParent)
        let beforeNames = try resources.names(parent: lease)
        guard beforeNames == ["mutation.lock", "owners", "registry.next.json"],
              try resources.namedPresence(parent: lease, name: "registry.json") == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try resources.enter(temporary, .rename)
        let renamed = Darwin.renameatx_np(lease.descriptor, "registry.next.json", lease.descriptor,
            "registry.json", UInt32(RENAME_EXCL)), renameErrno = errno
        try resources.record(temporary, .rename, returned: Int64(renamed), savedErrno: renameErrno)
        guard renamed == 0 else { resources.poisonOnUncertainEffect(); throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        temporary.storage.selectedName = "registry.json" // actual successful same-inode rename
        let renamedFact = try temporary.heldStat(); try temporary.requireNamed(fact: renamedFact)
        guard GenerationLeaseRegistryV1.FileSnapshot(renamedFact).identity == GenerationLeaseRegistryV1.FileSnapshot(prepared).identity,
              renamedFact.st_size == prepared.st_size,
              renamedFact.st_mtimespec.tv_sec == prepared.st_mtimespec.tv_sec,
              renamedFact.st_mtimespec.tv_nsec == prepared.st_mtimespec.tv_nsec else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        temporary.storage.currentFact = renamedFact
        let afterParent = try resources.captureHeldFact(lease)
        try resources.captureNamedFact(lease, expected: afterParent)
        guard try resources.names(parent: lease) == ["mutation.lock", "owners", "registry.json"] else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try lease.adoptOwnNamespaceProjection(resources: resources, before: beforeParent, after: afterParent)
        try lease.synchronize()
        guard try temporary.readAll() == bytes,
              try GenerationLeaseRegistryV1.RegistryStateV1.decodeCanonical(from: bytes).leases.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.corruptRegistry
        }
        _ = try resources.observePolicy(resource: temporary, kind: .generationLeaseControl,
            parent: resources.captureHeldFact(lease))
        try temporary.closeChecked()
        try resources.requireKernelGraph()
    }
}

final class ColdEraseSchema2CompletedRegistryPolicyScopeV1 {
    let kind: OwnedFileKindV1
    let url: URL
    let rootURL: URL
    let parentDescriptor: Int32
    let selectedName: String
    let descriptor: Int32
    let expectedFact: EraseColdControlLeafFactV1
    let expectedFlags: UInt32
    let parentFact: EraseColdControlLeafFactV1
    let parentFlags: UInt32
    private weak var resourcesReference: ColdEraseSchema2CompletedRegistryResourcesV1?
    private weak var resourceReference: ColdEraseSchema2CompletedRegistryDescriptorResourceV1?
    private let lock = NSRecursiveLock()
    private var request: ColdEraseSchema2CompletedRegistryPolicyRequestV1?
    private var positiveSettled = false
    private var uncertain = false
    private var exactBackingReservation: UInt64?
    fileprivate init(resources: ColdEraseSchema2CompletedRegistryResourcesV1,
        resource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1,
        kind: OwnedFileKindV1, parentFact: stat, selectedFact: stat) throws {
        try resources.requireResource(resource)
        guard let parent = resource.parentDescriptor,
              parentFact.st_mode & S_IFMT == S_IFDIR,
              resource.isLive else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        self.resourcesReference = resources; self.resourceReference = resource; self.kind = kind
        url = resource.url; rootURL = resources.rootURL
        parentDescriptor = parent; selectedName = resource.selectedName
        descriptor = resource.descriptor
        expectedFact = EraseColdControlLeafFactV1(selectedFact)
        expectedFlags = selectedFact.st_flags
        self.parentFact = EraseColdControlLeafFactV1(parentFact)
        parentFlags = parentFact.st_flags
    }
    fileprivate func requireLiveResourceGraph() throws
        -> (ColdEraseSchema2CompletedRegistryResourcesV1, ColdEraseSchema2CompletedRegistryDescriptorResourceV1) {
        guard let resources = resourcesReference, let resource = resourceReference else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return (resources, resource)
    }
    func requireCurrentFrame() throws {
        try lock.withLock {
            let (resources, resource) = try requireLiveResourceGraph()
            guard !uncertain, !positiveSettled, resource.isLive,
                  resource.descriptor == descriptor,
                  resource.parentDescriptor == parentDescriptor,
                  resource.selectedName == selectedName, resource.url == url else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // This is memory-only. During a genuine own setter transition,
            // the old selected ctime is DATA, never an after-syscall predicate.
            try resources.requireResource(resource)
        }
    }
    func requireCapacityForRequest() throws {
        try requireCurrentFrame()
        let (resources, _) = try requireLiveResourceGraph()
        guard request == nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        if exactBackingReservation == nil {
            exactBackingReservation = try resources.reservePolicyRequest(scope: self)
        }
    }
    func retainRequest(_ value: ColdEraseSchema2CompletedRegistryPolicyRequestV1) throws {
        try lock.withLock {
            let (resources, _) = try requireLiveResourceGraph()
            try requireCapacityForRequest()
            request = value // actual Request retained before its first effect
            guard let reserved = exactBackingReservation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try resources.retainPolicyRequest(scope: self, request: value, reserved: reserved)
        }
    }
    func requireRequest(_ value: ColdEraseSchema2CompletedRegistryPolicyRequestV1) throws {
        try lock.withLock {
            guard !uncertain, request === value else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if !positiveSettled { try requireCurrentFrame() }
        }
    }
    func adoptSuccessfulOwnSetterTransition(request value: ColdEraseSchema2CompletedRegistryPolicyRequestV1,
        before: EraseColdControlLeafFactV1, beforeFlags: UInt32,
        after: EraseColdControlLeafFactV1, afterFlags: UInt32) throws {
        try lock.withLock {
            let (resources, resource) = try requireLiveResourceGraph()
            try requireRequest(value)
            try value.requireSuccessfulOwnSetterTransition(scope: self,
                before: before, beforeFlags: beforeFlags, after: after, afterFlags: afterFlags)
            guard let current = resource.storage.currentFact,
                  EraseColdControlLeafFactV1(current) == before,
                  current.st_flags == beforeFlags,
                  beforeFlags == afterFlags,
                  before.device == after.device, before.inode == after.inode,
                  before.mode == after.mode, before.user == after.user,
                  before.group == after.group, before.links == after.links,
                  before.size == after.size,
                  before.modifiedSeconds == after.modifiedSeconds,
                  before.modifiedNanoseconds == after.modifiedNanoseconds else {
                poisonOnUncertainEffect(); throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            // The stat is copied from the actual graph's retained selected
            // inode. Only the Request's authentic successful ctime projection
            // is adopted; no fresh survivor authorizes this replacement.
            var projected = current
            projected.st_ctimespec.tv_sec = numericCast(after.changedSeconds)
            projected.st_ctimespec.tv_nsec = numericCast(after.changedNanoseconds)
            projected.st_flags = afterFlags
            resource.storage.currentFact = projected
            // A fresh allocation alias of a permanent directory owns the
            // SAME inode. Advance that actual borrowed graph role only through
            // this same authentic successful setter receipt.
            for graphResource in try resources.permanentGraph() where graphResource !== resource {
                guard let graphFact = graphResource.storage.currentFact else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
                if graphFact.st_dev == before.device && graphFact.st_ino == before.inode {
                    guard EraseColdControlLeafFactV1(graphFact) == before, graphFact.st_flags == beforeFlags else {
                        poisonOnUncertainEffect(); throw GenerationLeaseRegistryFailureV1.uncertainOwner
                    }
                    var graphProjected = graphFact
                    graphProjected.st_ctimespec = projected.st_ctimespec
                    graphProjected.st_flags = afterFlags
                    graphResource.storage.currentFact = graphProjected
                }
            }
        }
    }
    func acceptPositivePolicySettlement(_ value: ColdEraseSchema2CompletedRegistryPolicyRequestV1) throws {
        try lock.withLock {
            let (_, resource) = try requireLiveResourceGraph()
            try requireRequest(value)
            try value.requirePositivePermanentSettlement(scope: self)
            guard let fact = value.finalFact, let flags = value.finalFlags,
                  let current = resource.storage.currentFact,
                  EraseColdControlLeafFactV1(current) == fact,
                  current.st_flags == flags else {
                poisonOnUncertainEffect(); throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            positiveSettled = true
        }
    }
    func requirePositivePermanentSettlement() throws {
        try lock.withLock {
            guard !uncertain, positiveSettled, let request else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try request.requirePositivePermanentSettlement(scope: self)
        }
    }
    func poisonOnUncertainEffect() {
        lock.withLock { uncertain = true; resourcesReference?.poisonOnUncertainEffect() }
    }
}

fileprivate extension ColdEraseSchema2CompletedRegistryResourcesV1 {
    @MainActor func makePolicyScope(resource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1,
        kind: OwnedFileKindV1, parent: stat) throws -> ColdEraseSchema2CompletedRegistryPolicyScopeV1 {
        try requireResource(resource)
        let expectedKind: OwnedFileKindV1
        switch resource.role {
        case .operations, .lease, .owners: expectedKind = .generationLeaseDirectory
        case .mutationControl, .registryOriginal: expectedKind = .generationLeaseControl
        case .ownerControl: expectedKind = .generationLeaseOwnerLock
        case .registryTemporary:
            expectedKind = resource.selectedName == "registry.next.json"
                ? .generationLeaseControlTemporary : .generationLeaseControl
        case .registryRead:
            expectedKind = resource.storage.expectedOpenFlags & O_DIRECTORY != 0
                ? .generationLeaseDirectory : .generationLeaseControl
        default: throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        guard kind == expectedKind else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        guard resource.storage.policies.count < 32 else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let selected = try resource.requireCurrentFact()
        let value = try ColdEraseSchema2CompletedRegistryPolicyScopeV1(resources: self,
            resource: resource, kind: kind, parentFact: parent, selectedFact: selected)
        resource.storage.policies.append(value) // before the PFP Request/open
        return value
    }
    @MainActor func applyPolicy(resource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1,
        kind: OwnedFileKindV1, parent: stat) throws -> ProtectedFileVerificationDispositionV1 {
        let scope = try makePolicyScope(resource: resource, kind: kind, parent: parent)
        do {
            let result = try ProtectedFilePolicyV1.applyAndVerifyForSchema2ColdCompletedRegistry(
                kind, at: resource.url, scope: scope)
            try scope.requirePositivePermanentSettlement()
            return result
        } catch { scope.poisonOnUncertainEffect(); throw error }
    }
    @MainActor func observePolicy(resource: ColdEraseSchema2CompletedRegistryDescriptorResourceV1,
        kind: OwnedFileKindV1, parent: stat) throws -> TemporalPolicyObservationV1 {
        let scope = try makePolicyScope(resource: resource, kind: kind, parent: parent)
        do {
            let result = try ProtectedFilePolicyV1.observeForSchema2ColdCompletedRegistry(
                kind, at: resource.url, scope: scope)
            try scope.requirePositivePermanentSettlement()
            return result
        } catch { scope.poisonOnUncertainEffect(); throw error }
    }
    func makeResource(role: Role, url: URL, parent: Int32?, name: String,
        permanent: Bool = false, flags: Int32, mode: mode_t = 0)
        throws -> ColdEraseSchema2CompletedRegistryDescriptorResourceV1 {
        try requireCurrentFrame()
        guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
              !name.contains("\\"), !name.utf8.contains(0), name.utf8.count <= 255 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let value = ColdEraseSchema2CompletedRegistryDescriptorResourceV1(resources: self,
            role: role, url: url, parent: parent, name: name, permanent: permanent, flags: flags, mode: mode)
        try retain(value)
        return value
    }
    func namedPresence(parent: ColdEraseSchema2CompletedRegistryDescriptorResourceV1,
        name: String) throws -> stat? {
        try requireCurrentFrame()
        guard !name.isEmpty, name != ".", name != "..", !name.contains("/"),
              !name.utf8.contains(0), name.utf8.count <= 255 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try enter(parent, .absentStat)
        var fact = stat()
        let result = Darwin.fstatat(parent.descriptor, name, &fact, AT_SYMLINK_NOFOLLOW), saved = errno
        try record(parent, .absentStat, returned: Int64(result), savedErrno: saved, information: fact)
        if result < 0 && saved == ENOENT { return nil }
        guard result == 0, fact.st_mode & S_IFMT != S_IFLNK else {
            poisonOnUncertainEffect(); throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return fact
    }
}
