fileprivate final class ColdEraseSchema2CompletedRegistryOrdinaryLifetimeTransferV1 {
    private let graph: [ColdEraseSchema2CompletedRegistryDescriptorResourceV1]
    private let descriptors: [Int32]
    private let roles: [ColdEraseSchema2CompletedRegistryResourcesV1.Role]
    private let registryIdentity: ObjectIdentifier
    private weak var receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1?
    @MainActor fileprivate init(receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        registry: GenerationLeaseRegistryV1, owner: ColdEraseSchema2CompletedStartupOwnerV1) throws {
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
        guard let engine = registry.completedSchema2RegistryEngine,
              registry.completedSchema2AllocationScopes.count == 2 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.requireCompletedSchema2ConstructorResourceTransfer(engine.attempt)
        for scope in registry.completedSchema2AllocationScopes {
            try scope.requireGenuinePublishedReceiver(receiver, registry: registry, owner: owner)
        }
        graph = engine.permanentResources
        descriptors = registry.completedSchema2TransferredDescriptors
        roles = [.support, .operations, .lease, .owners, .mutationControl, .ownerControl]
        registryIdentity = ObjectIdentifier(registry); self.receiver = receiver
        try requireOwnedDescriptors(registry: registry, descriptors: descriptors)
    }
    fileprivate func requireOwnedDescriptors(registry: GenerationLeaseRegistryV1,
        descriptors: [Int32]) throws {
        // Identity is one association; the real retained six-resource graph,
        // positive owner flock and authentic prior receiver are the proof.
        guard registryIdentity == ObjectIdentifier(registry), graph.count == 6,
              self.descriptors == descriptors, Set(descriptors).count == 6,
              graph.map(\.role) == roles else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for (resource, descriptor) in zip(graph, descriptors) {
            try resource.requireTransferredDescriptor(descriptor)
        }
    }
}

