// Fresh completed Bootstrap/Observation intervals. They share physical IO
// mechanics, while every entry binds a distinct actual current Main origin.
@MainActor fileprivate final class ColdEraseSchema2CompletedRegistryCurrentIntervalV1 {
    enum Origin {
        case bootstrap(ColdEraseSchema2CompletedRegistryBootstrapScopeV1,
            StoreGenerationFactory, EraseReaderRetirementInventoryV1)
        case observation(ColdEraseSchema2CompletedRegistryObservationScopeV1,
            GenerationLeaseTokenV1, GenerationEpochV1)
        case sessionOpening(ColdEraseSchema2CompletedSessionOpeningScopeV1)
    }
    let resources: ColdEraseSchema2CompletedRegistryResourcesV1
    weak var registry: GenerationLeaseRegistryV1?
    var retainedRegistry: GenerationLeaseRegistryV1?
    weak var owner: ColdEraseSchema2CompletedStartupOwnerV1?
    var origin: Origin?
    var entered = false
    var returned = false
    var uncertain = false
    var activity: ColdEraseSchema2CompletedRegistryDescriptorResourceV1?
    var primaryFailure: Error?
    var settlementFailure: Error?
    var declaredSourceBackingLimit: UInt64
    var reservedSourceBackingBytes: UInt64 = 0
    var chargedSourceBackingBytes: UInt64 = 0
    var sourceReservationCount = 0
    var pendingSourceReservation: UInt64?

    init(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1) throws {
        guard let engine = registry.completedSchema2RegistryEngine else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.requireCompletedSchema2ConstructorResourceTransfer(engine.attempt)
        resources = ColdEraseSchema2CompletedRegistryResourcesV1(rootURL: engine.resources.rootURL,
            profile: .freshCurrentSource)
        self.registry = registry; retainedRegistry = registry; self.owner = owner
        let perSource = try ColdEraseSchema2CompletedJournalSourceV1.requiredBackingBytes(
            absoluteRootUTF8Count: UInt64(engine.resources.rootURL.path.utf8.count))
        let limit = perSource.multipliedReportingOverflow(by: 32)
        guard !limit.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        declaredSourceBackingLimit = limit.partialValue
    }
    init(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1,sessionOpeningAdditionalOutcomes: Int) throws {
        guard let engine = registry.completedSchema2RegistryEngine,
              sessionOpeningAdditionalOutcomes >= 0,
              sessionOpeningAdditionalOutcomes <= Int.max - 147_456 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.requireCompletedSchema2ConstructorResourceTransfer(engine.attempt)
        resources = ColdEraseSchema2CompletedRegistryResourcesV1(rootURL: engine.resources.rootURL,
            sessionOpeningAdditionalOutcomes: sessionOpeningAdditionalOutcomes)
        self.registry = registry; retainedRegistry = registry; self.owner = owner
        let perSource = try ColdEraseSchema2CompletedJournalSourceV1.requiredBackingBytes(
            absoluteRootUTF8Count: UInt64(engine.resources.rootURL.path.utf8.count))
        let limit = perSource.multipliedReportingOverflow(by: 8)
        guard !limit.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        declaredSourceBackingLimit = limit.partialValue
    }
    func retainBeforeEffects(_ origin: Origin) throws {
        guard self.origin == nil, !entered, !uncertain else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        self.origin = origin
        try resources.retainOrigin(self, registry: registry)
    }
    func requireCurrentOwner() throws {
        guard !uncertain, let registry, retainedRegistry === registry,
              let owner, let origin else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        switch origin {
        case .bootstrap(let scope, let factory, let inventory):
            try owner.requireCompletedRegistryBootstrapFrame(registry: registry,
                factory: factory, inventory: inventory)
            try owner.requireCompletedRegistryBootstrapScope(scope, registry: registry,
                factory: factory, inventory: inventory)
        case .observation(let scope, let writer, let epoch):
            try owner.requireCompletedRegistryObservationFrame(registry: registry,
                writerToken: writer, epoch: epoch)
            try owner.requireCompletedRegistryObservationScope(scope, registry: registry,
                writerToken: writer, epoch: epoch)
        case .sessionOpening(let scope):
            try scope.requireCurrentSessionOrigin()
        }
    }
    func requireEntered() throws {
        try requireCurrentOwner()
        guard entered, !returned else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try resources.requireCurrentFrame()
    }
    func requireKernelBoundary(source: ColdEraseSchema2CompletedJournalSourceV1? = nil) throws {
        try requireEntered()
        let graph = try resources.permanentGraph()
        guard graph.count == 6, Set(graph.map(\.descriptor)).count == 6 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for value in graph {
            guard let expected = value.retainedCurrentFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let held = try resources.captureHeldFact(value)
            try resources.captureNamedFact(value, expected: held)
            if value.role == .operations, let source, let origin {
                switch origin {
                case .bootstrap(let scope, _, _):
                    try source.requireOperationsKernelBoundary(bootstrap: scope,
                        fact: EraseColdControlLeafFactV1(held), flags: held.st_flags)
                case .observation(let scope, _, _):
                    try source.requireOperationsKernelBoundary(observation: scope,
                        fact: EraseColdControlLeafFactV1(held), flags: held.st_flags)
                case .sessionOpening(let scope):
                    try source.requireOperationsKernelBoundary(sessionOpening: scope,
                        fact: EraseColdControlLeafFactV1(held),flags: held.st_flags)
                }
            } else {
                guard ColdEraseSchema2CompletedRegistryDescriptorResourceV1.sameFull(expected, held) else {
                    poison(); throw GenerationLeaseRegistryFailureV1.uncertainOwner
                }
            }
        }
        try requireEntered()
    }
    func withEnteredInterval<Value>(verifyGraphAfterOperation: Bool,
        _ body: @MainActor () throws -> Value) throws -> Value {
        try requireCurrentOwner()
        guard !entered, !returned, let registry else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try resources.beginFrame()
        entered = true
        let activity = try resources.makeResource(role: .allocationActivity,
            url: resources.rootURL, parent: nil, name: resources.rootURL.lastPathComponent,
            flags: O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        self.activity = activity // actual retained object before open
        let result = Result {
            try requireEntered()
            try activity.open(flags: O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            let graph = try resources.permanentGraph()
            guard let expected = graph[0].retainedCurrentFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let first = try activity.heldStat(); try activity.requireNamed(fact: first)
            guard ColdEraseSchema2CompletedRegistryDescriptorResourceV1.sameFull(first, expected) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try requireCurrentOwner()
            try activity.acquireSharedLock()
            let rechecked = try activity.heldStat(); try activity.requireNamed(fact: rechecked)
            guard ColdEraseSchema2CompletedRegistryDescriptorResourceV1.sameFull(first, rechecked) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            let value = try registry.withCompletedSchema2CheckedSourceGenerationMutation(
                resources: resources, verifyAfterOperation: verifyGraphAfterOperation) {
                try requireEntered()
                let value = try body()
                try requireCurrentOwner()
                return value
            }
            let beforeClose = try activity.heldStat(); try activity.requireNamed(fact: beforeClose)
            guard ColdEraseSchema2CompletedRegistryDescriptorResourceV1.sameFull(first, beforeClose) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            return value
        }
        if case .failure(let error) = result { primaryFailure = error }
        // Independent teardown is selected only by SAME actual captured SH
        // acquisition, even when a body/capture postcondition has refused.
        if activity.storage.sharedLockReturned == 0 {
            do { try activity.releaseSharedLockChecked() }
            catch { settlementFailure = error }
            if activity.storage.sharedUnlockReturned == 0 {
                do { try activity.closeChecked() }
                catch { if settlementFailure == nil { settlementFailure = error } }
            }
        }
        if let error = settlementFailure { poison(); throw error }
        do {
            let value = try result.get()
            try activity.requirePositiveClosed()
            try resources.requireTransientSettlement()
            try requireCurrentOwner()
            try resources.endFrame()
            returned = true
            return value
        } catch { poison(); throw error }
    }
    func requirePositivePermanentSettlement() throws {
        guard !uncertain, entered, returned,
              primaryFailure == nil, settlementFailure == nil,
              pendingSourceReservation == nil,
              chargedSourceBackingBytes == reservedSourceBackingBytes,
              resources.storage.frame?.state == .ended,
              resources.storage.generationIntervals.count == 1,
              let activity else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try activity.requirePositiveClosed()
        try resources.requireTransientSettlement()
    }
