            kind: .generationLeaseDirectory, parent: parent)
        let read = try resources.makeResource(role: .registryRead,
            url: lease.url.appendingPathComponent("registry.json"), parent: lease.descriptor,
            name: "registry.json", flags: O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        try read.open(flags: O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)
        let before = try read.heldStat(); try read.requireNamed(fact: before)
        let leaseFact = try resources.captureHeldFact(lease)
        try resources.captureNamedFact(lease, expected: leaseFact)
        let policy = try resources.observePolicy(resource: read,
            kind: .generationLeaseControl, parent: leaseFact)
