        let bytes = try read.readAll()
        let after = try read.heldStat(); try read.requireNamed(fact: after)
        guard ColdEraseSchema2CompletedRegistryDescriptorResourceV1.sameFull(projected, after) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let state = try GenerationLeaseRegistryV1.RegistryStateV1.decodeCanonical(from: bytes)
        try read.closeChecked(); try directory.closeChecked()
        try requireKernelBoundary()
        return TemporalGenerationRegistryObservationV1(leases: state.leases,
            registryBytes: bytes, registryPolicy: policy, directoryPolicy: directoryPolicy)
    }
    func releasePositiveOrigin() throws {
        try requirePositivePermanentSettlement()
        try resources.releasePositiveOriginAfterTransfer()
