extension GenerationLeaseRegistryV1 {
    @MainActor func withSchema2ColdCompletedStartupObservation<Value>(
        owner: ColdEraseSchema2CompletedStartupOwnerV1, writerToken: GenerationLeaseTokenV1,
        epoch: GenerationEpochV1, verifyAfterOperation: Bool,
        _ body: @MainActor () throws -> Value) throws -> Value {
        guard completedSchema2RegistryEngine != nil, completedSchema2StartupOwner === owner else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // A real nested Writer operation borrows only this SAME currently
        // owned G interval; no current auth lock is recursively entered.
        if let current = completedSchema2ActiveObservationScope {
            try owner.requireCompletedRegistryObservationKindForCurrentFrame(verifyAfterOperation: verifyAfterOperation)
            return try current.withCurrentBorrower(registry: self, owner: owner,
                writerToken: writerToken, epoch: epoch, verifyAfterOperation: verifyAfterOperation, body)
        }
        return try owner.withCompletedRegistryObservation(registry: self, writerToken: writerToken, epoch: epoch) {
            try owner.requireCompletedRegistryObservationKindForCurrentFrame(verifyAfterOperation: verifyAfterOperation)
            guard completedSchema2ObservationScopes.isEmpty else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            let scope = try ColdEraseSchema2CompletedRegistryObservationScopeV1(registry: self,
                owner: owner, writerToken: writerToken, epoch: epoch)
            completedSchema2ObservationScopes.append(scope)
            try scope.retainBeforeEffects()
            try owner.retainCompletedRegistryObservationScope(scope, registry: self,
                writerToken: writerToken, epoch: epoch)
            completedSchema2ActiveObservationScope = scope
            defer {
                if completedSchema2ActiveObservationScope === scope { completedSchema2ActiveObservationScope = nil }
            }
            let value = try scope.withCurrentObservation(registry: self, owner: owner,
                writerToken: writerToken, epoch: epoch, verifyAfterOperation: verifyAfterOperation, body)
            try scope.consumePositiveReturnedScope(registry: self, owner: owner)
            try scope.requireConsumedPositivePermanentSettlement(registry: self, owner: owner,
                writerToken: writerToken, epoch: epoch)
            completedSchema2ObservationScopes.removeAll(where: { $0 === scope })
            return value
        }
    }
}

