    nonisolated static func requiredBackingBytes(absoluteRootUTF8Count: UInt64) throws -> UInt64 {
        guard absoluteRootUTF8Count > 0 else { throw StoreMigrationFailure.invalidPath }
        let paths = absoluteRootUTF8Count.multipliedReportingOverflow(by: 192)
        guard !paths.overflow else { throw StoreMigrationFailure.invalidContract }
        // Immutable field/logical backing only; no Foundation/allocator/VM claim.
        let fixed = UInt64(MemoryLayout<ConstructionGraph>.stride
            + 32 * MemoryLayout<Attempt?>.stride + 128 * MemoryLayout<Resource?>.stride
            + 65536 * MemoryLayout<RawOutcome?>.stride + 128 * 4096 + 48 * 1024 + 144 * 8192
            + 48 * MemoryLayout<ColdEraseSchema2CompletedJournalPolicyScopeV1?>.stride
            + 48 * MemoryLayout<ColdEraseSchema2CompletedBootstrapSourcePolicyScopeV1?>.stride
            + 3 * MemoryLayout<NamespaceTransition?>.stride + 7 * 4 * 1024 * 1024
            + 48 * MemoryLayout<Read?>.stride
            + 6 * 64 * 1024 + 12 * 2048 * 256)
        let withProvenance = fixed.addingReportingOverflow(ColdEraseSchema2CompletedRegistryFactoryProvenanceV1.declaredBackingBytes())
        guard !withProvenance.overflow else { throw StoreMigrationFailure.invalidContract }
        let fixedWithNamedProbes = withProvenance.partialValue.addingReportingOverflow(declaredNamedChildProbeBackingBytes())
        guard !fixedWithNamedProbes.overflow else { throw StoreMigrationFailure.invalidContract }
        let maxURL = absoluteRootUTF8Count.addingReportingOverflow(512)
        guard !maxURL.overflow else { throw StoreMigrationFailure.invalidContract }
        let perJournal = try ColdEraseSchema2CompletedJournalPolicyRequestV1.requiredBackingBytes(absoluteURLUTF8Count: maxURL.partialValue)
        let perSource = try ColdEraseSchema2CompletedBootstrapSourcePolicyRequestV1.requiredBackingBytes(absoluteURLUTF8Count: maxURL.partialValue)
        let perTemporary = try ColdEraseSchema2CompletedAggregateTemporaryPolicyRequestV1.requiredBackingBytes(absoluteURLUTF8Count: maxURL.partialValue)
        let policy = (perJournal + perSource + perTemporary).multipliedReportingOverflow(by: 48)
        guard !policy.overflow else { throw StoreMigrationFailure.invalidContract }
        let fixedWithLifetime = fixedWithNamedProbes.partialValue.addingReportingOverflow(ColdEraseSchema2CompletedJournalLifetimeTransferV1.declaredBackingBytes())
        guard !fixedWithLifetime.overflow else { throw StoreMigrationFailure.invalidContract }
        let policyFixed = fixedWithLifetime.partialValue.addingReportingOverflow(policy.partialValue)
        guard !policyFixed.overflow else { throw StoreMigrationFailure.invalidContract }
        let total = policyFixed.partialValue.addingReportingOverflow(paths.partialValue)
        guard !total.overflow else { throw StoreMigrationFailure.invalidContract }
        let withSessionDataBasis = total.partialValue.addingReportingOverflow(declaredSessionDataBasisBackingBytes())
        guard !withSessionDataBasis.overflow else { throw StoreMigrationFailure.invalidContract }
        let withSessionOpening = withSessionDataBasis.partialValue.addingReportingOverflow(declaredSessionOpeningBackingBytes())
        guard !withSessionOpening.overflow else { throw StoreMigrationFailure.invalidContract }
        let withObservationProjection = withSessionOpening.partialValue.addingReportingOverflow(
            declaredObservationDataProjectionBackingBytes())
        guard !withObservationProjection.overflow else { throw StoreMigrationFailure.invalidContract }
        let withObservationBasis = withObservationProjection.partialValue.addingReportingOverflow(
            ColdEraseSchema2CompletedSourceDataPolicyBasisV1.declaredFieldBackingBytes)
        guard !withObservationBasis.overflow else { throw StoreMigrationFailure.invalidContract }
        let currentFields = UInt64(MemoryLayout<CurrentBindings>.stride + MemoryLayout<CurrentBindings.Storage>.stride
            + MemoryLayout<CurrentBindings>.stride + 32 * MemoryLayout<CurrentState?>.stride
            + 2 * MemoryLayout<ColdEraseSchema2CompletedRegistryAllocationScopeV1?>.stride
            + MemoryLayout<GenerationLeaseAllocationAttemptV1?>.stride)
        let withCurrentFields = withObservationBasis.partialValue.addingReportingOverflow(currentFields)
        guard !withCurrentFields.overflow else { throw StoreMigrationFailure.invalidContract }
        return withCurrentFields.partialValue
    }
