              retainedFactory != nil else { throw StoreMigrationFailure.invalidIdentity }
        try factoryProvenance.requireMatches(factory: factory)
        try requireTransferredStoreGraph()
        try sessionOpening.requireConsumedOpeningSourcePositiveSettlement(source: self, registry: registry,
            owner: owner, factory: factory, inventory: inventory, receiver: receiver)
        let matching = attempts.prefix(attemptCount).compactMap({ $0 }).filter {
            if case .sessionOpening(let actual)? = $0.origin { return actual === sessionOpening }
            return false
        }
        guard !matching.isEmpty else { throw StoreMigrationFailure.invalidIdentity }
        for attempt in matching {
            guard attempt.returned, attempt.primary == nil, attempt.secondary == nil,
                  attempt.sessionOpeningState.consumedReceipt == nil,
                  let receipt = attempt.receipt, let cell = attempt.sessionOpeningState.returnReceiptCell,
                  cell.storage.receipt === receipt else { throw StoreMigrationFailure.invalidIdentity }
            try requireSessionOpeningReturnReceiptCell(receipt, attempt: attempt)
            try receipt.requirePositivePermanentSettlement(owner: owner, factory: factory)
            try sessionOpening.requireRetainedPositiveOpeningSourceReceipt(receipt,
                source: self, owner: owner, factory: factory)
        }
        let consumed = try sessionOpening.completedOpeningConsumptionReceipt(source: self,
            registry: registry, owner: owner, factory: factory, inventory: inventory)
        // The genuine pending closed bank/resource object is retained before
        // reverse origins clear. Scope finalizes it only after actual bank returns.
        for attempt in matching {
            // Every cell/Receipt was joined above, and this awaitless memory
            // transfer has no fallible child between the joined owners.
            attempt.sessionOpeningState.returnReceiptCell?.storage.transferredReceipt = attempt.receipt
            attempt.sessionOpeningState.returnReceiptCell?.storage.consumedReceipt = consumed
            attempt.sessionOpeningState.consumedReceipt = consumed
            attempt.origin = nil
            // SAME Scope still strongly owns each actual Receipt through both
            // bank returns and the concrete ConsumptionReceipt finalization.
            attempt.sessionOpeningState.returnReceiptCell?.storage.receipt = nil
        }
        // Keep Source's live Factory/Registry/Bootstrap graph for the subsequent
        // real Bootstrap/Journal3FD Ready transfer and for every uncertain return.
    }
    func releaseAfterPublicationReceiver(_ receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        bootstrap: ColdEraseSchema2CompletedRegistryBootstrapScopeV1, registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1, factory: StoreGenerationFactory,
        inventory: EraseReaderRetirementInventoryV1) throws {
        try factoryProvenance.requireMatches(factory: factory)
        guard self.registry === registry, self.owner === owner,
              self.inventory === inventory, self.bootstrap === bootstrap else { throw StoreMigrationFailure.invalidIdentity }
        try requirePositiveCheckedSettlement(bootstrap: bootstrap)
        try bootstrap.requirePositivePermanentSettlement(registry: registry, owner: owner, factory: factory, inventory: inventory)
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
        try owner.requireCompletedStartupLeaseOwnershipConsumed(registry: registry)
        for a in attempts.prefix(attemptCount).compactMap({ $0 }) {
            guard a.primary == nil, a.secondary == nil else { throw StoreMigrationFailure.invalidIdentity }
            if case .bootstrap(let actual)? = a.origin {
                guard actual === bootstrap, a === attempts[0] || a.returned else { throw StoreMigrationFailure.invalidIdentity }
            }
            if a.sessionOpeningState.consumedReceipt != nil {
                guard a.origin == nil, a.returned, let receipt = a.receipt else { throw StoreMigrationFailure.invalidIdentity }
                try receipt.requireConsumedPositivePermanentSettlement(owner: owner)
            }
            if case .allocation(let scope)? = a.origin {
                guard a.returned else { throw StoreMigrationFailure.invalidIdentity }
                try scope.requireConsumedCurrentSourcePositiveSettlement(source: self, registry: registry, owner: owner, receiver: receiver)
            }
        }
        let lifetime = try ColdEraseSchema2CompletedJournalLifetimeTransferV1.retainForActualReadyTransfer(
            source: self, registry: registry, receiver: receiver, owner: owner, bootstrap: bootstrap)
        consumedBootstrap = bootstrap; self.bootstrap = nil
        // Actual strong attempt origins release below only after SAME Ready proof.
        for a in attempts.prefix(attemptCount).compactMap({ $0 }) {
            if case .bootstrap(let actual)? = a.origin {
                a.consumedBootstrap = actual; a.origin = nil
            } else if case .allocation(let scope)? = a.origin {
                a.consumedAllocation = scope; a.origin = nil
            }
        }
        active = nil
        retainedRegistry = nil; retainedOwner = nil; retainedFactory = nil; retainedInventory = nil
        self.factory = nil
        lifetime.recordActualSourceOriginRelease()
    }
    func releaseAfterObservationSettlement(observation: ColdEraseSchema2CompletedRegistryObservationScopeV1,
        registry: GenerationLeaseRegistryV1, owner: ColdEraseSchema2CompletedStartupOwnerV1,
        writerToken: GenerationLeaseTokenV1, epoch: GenerationEpochV1) throws {
        guard !uncertain, self.registry === registry, self.owner === owner, let liveFactory = retainedFactory else { throw StoreMigrationFailure.invalidIdentity }
        try observation.requireConsumedPositivePermanentSettlement(registry: registry, owner: owner, writerToken: writerToken, epoch: epoch)
        let consumedOrigin = try observation.completedObservationConsumptionReceipt(
            registry: registry, owner: owner, writerToken: writerToken, epoch: epoch)
        let matching = attempts.prefix(attemptCount).compactMap({ $0 }).filter {
            if case .observation(let actual)? = $0.origin { return actual === observation }; return false
        }
        var releases: [(Attempt,UInt64)] = []; var total: UInt64 = 0
        for a in matching {
            guard a.returned, a.primary == nil, a.secondary == nil else { throw StoreMigrationFailure.invalidIdentity }
            if let state = a.observationDataState {
                guard let receipt = state.storage.returnCell.storage.receipt,
                      let projection = state.storage.returnCell.storage.projection,
                      receipt === a.receipt, receipt.observationDataProjection === projection else {
                    throw StoreMigrationFailure.invalidIdentity
                }
                try receipt.requirePositivePermanentSettlement(owner: owner, factory: liveFactory)
                try projection.requireActualObservationReturnCellTransfer(source: self, observation: observation,
                    state: state, consumedOrigin: consumedOrigin)
            } else if let receipt = a.receipt {
                // Aggregate-only purpose never constructs a canonical Data receipt.
                _ = receipt; throw StoreMigrationFailure.invalidIdentity
            }
            var released: UInt64 = 0
            for scope in a.journalPolicies { try scope.requirePositivePermanentSettlement(); guard let request = scope.request else { throw StoreMigrationFailure.invalidIdentity }; released += request.actualBackingBytes }
            for scope in a.sourcePolicies { try scope.requirePositivePermanentSettlement(); guard let request = scope.request else { throw StoreMigrationFailure.invalidIdentity }; released += request.actualBackingBytes }
            for scope in a.temporaryPolicies { try scope.requirePositivePermanentSettlement(); guard let request = scope.request else { throw StoreMigrationFailure.invalidIdentity }; released += request.actualBackingBytes }
            total += released; releases.append((a,released))
        }
        guard pendingPolicyBacking == nil, chargedPolicyBacking >= total, reservedPolicyBacking >= total else {
            throw StoreMigrationFailure.invalidIdentity
        }
        // All concrete consumed-owner, own PFP/read/onceclose/provenance guards
        // passed before any strong edge or declared backing ownership changes.
        for (a,released) in releases {
            a.consumedObservationReceipt = consumedOrigin; a.consumedObservation = observation; a.origin = nil
            if let state = a.observationDataState {
                let cell = state.storage.returnCell
                // All same actual returned Source/native adoption/ended Scope
                // guards above passed; later bank finalization remains distinct.
                cell.storage.consumedOrigin = consumedOrigin
                cell.storage.transferredReceipt = cell.storage.receipt
                cell.storage.transferredProjection = cell.storage.projection
                cell.storage.receipt?.consumedObservationDataProjection = cell.storage.projection
                cell.storage.receipt?.observationDataProjection = nil
                cell.storage.receipt = nil; cell.storage.projection = nil
            }
            recycleConsumedObservationAttempt(a, releasedBacking: released)
        }
        retainedRegistry = nil; retainedOwner = nil; retainedFactory = nil; retainedInventory = nil
    }
    private func recycleConsumedObservationAttempt(_ attempt: Attempt, releasedBacking: UInt64) {
        for i in journalPolicies.indices where attempt.journalPolicies.contains(where: { $0 === journalPolicies[i] }) { journalPolicies[i] = nil }
        for i in sourcePolicies.indices where attempt.sourcePolicies.contains(where: { $0 === sourcePolicies[i] }) { sourcePolicies[i] = nil }
        for i in temporaryPolicies.indices where attempt.temporaryPolicies.contains(where: { $0 === temporaryPolicies[i] }) { temporaryPolicies[i] = nil }
        chargedPolicyBacking -= releasedBacking; reservedPolicyBacking -= releasedBacking
        for i in attempts.indices.dropFirst() where attempts[i] === attempt { attempts[i] = nil }
    }
    fileprivate func requirePolicyResource(_ resource: Resource, kind: OwnedFileKindV1) throws {
        try requireAssociation()
        guard let attempt = active, resource === support || resource === operations || resource === migration
                || attempt.resources.prefix(attempt.resourceCount).contains(where: { $0 === resource }),
              resource.openResult == resource.descriptor, resource.openErrno != nil,
              resource.expected != nil, !resource.closeEntered else { throw StoreMigrationFailure.invalidIdentity }
        let parent = try resourceParent(resource)
        guard parent?.descriptor == resource.parent else { throw StoreMigrationFailure.invalidIdentity }
        switch resource.role {
        case .operations, .migration: guard kind == .stagingDirectory else { throw StoreMigrationFailure.invalidIdentity }
        case .data: guard kind == .durableDirectory else { throw StoreMigrationFailure.invalidIdentity }
        case .current, .retired: guard kind == .generationPointer else { throw StoreMigrationFailure.invalidIdentity }
        case .manifest, .eraseManifest, .journal, .aggregate: guard kind == .journal else { throw StoreMigrationFailure.invalidIdentity }
        case .aggregateTemporary: guard kind == .journalTemporary else { throw StoreMigrationFailure.invalidIdentity }
        default: throw StoreMigrationFailure.invalidIdentity
        }
    }
    fileprivate func loadManifestIfPresent(_ candidate: StoreMigrationJournalStoreV1,
        id: UUID) throws -> (manifest: StoreGenerationManifestV1, digest: String)? {
        if currentBindings.storage.loanScope != nil || currentBindings.storage.loanRequest != nil {
            return try currentManifestLookup(candidate,id: id)
        }
        try requireStore(candidate); try requireOwnedJournalNames()
        guard let migration else { throw StoreMigrationFailure.invalidIdentity }
        let name = Self.manifestName(id)
        guard try namedOrAbsent(parent: migration, name: name) != nil else { try boundary(); return nil }
        let captured = try readJournalLeaf(.manifest, parent: migration, name: name)
        let manifest = try StoreGenerationManifestV1.decodeCanonical(from: captured.0)
        guard manifest.generationID == id else { throw StoreMigrationFailure.invalidIdentity }
        try boundary(); return (manifest,StoreMigrationCanonicalJSONV1.sha256(captured.0))
    }
    fileprivate func requireStore(_ candidate: StoreMigrationJournalStoreV1) throws {
        guard store === candidate, !uncertain else { throw StoreMigrationFailure.invalidIdentity }; try boundary()
    }
    fileprivate func loadJournal(_ candidate: StoreMigrationJournalStoreV1) throws -> StoreMigrationJournalV1? {
        try requireStore(candidate); try requireOwnedJournalNames()
        guard let migration else { throw StoreMigrationFailure.invalidIdentity }
        guard try namedOrAbsent(parent: migration, name: "journal.json") != nil else { try boundary(); return nil }
        let captured = try readJournalLeaf(.journal, parent: migration, name: "journal.json")
        let result = try StoreMigrationJournalV1.decodeCanonical(from: captured.0); try boundary(); return result
    }
    fileprivate func loadManifest(_ candidate: StoreMigrationJournalStoreV1, id: UUID,
        expectedDigest: String) throws -> StoreGenerationManifestV1 {
        try requireStore(candidate)
        guard StoreMigrationCanonicalJSONV1.isLowercaseSHA256(expectedDigest), let migration else { throw StoreMigrationFailure.invalidDigest }
        let captured = try readJournalLeaf(.manifest, parent: migration, name: Self.manifestName(id))
        guard StoreMigrationCanonicalJSONV1.sha256(captured.0) == expectedDigest else { throw StoreMigrationFailure.digestMismatch }
        let result = try StoreGenerationManifestV1.decodeCanonical(from: captured.0)
        guard result.generationID == id else { throw StoreMigrationFailure.invalidIdentity }; try boundary(); return result
    }
}

@MainActor
final class ColdEraseSchema2CompletedCurrentSourceReceiptV1 {
    let pointerBytes: Data
    let retiredBytes: Data
    let manifestBytes: Data
    let generationID: UUID
    let generationEpoch: GenerationEpochV1
    fileprivate weak var source: ColdEraseSchema2CompletedJournalSourceV1?
    fileprivate let attempt: ColdEraseSchema2CompletedJournalSourceV1.Attempt
    fileprivate var observationDataProjection: ColdEraseSchema2CompletedSourceDataPolicyProjectionV1?
    fileprivate weak var consumedObservationDataProjection: ColdEraseSchema2CompletedSourceDataPolicyProjectionV1?
    private let provenance: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1
    private let sourceIdentity: ObjectIdentifier
    private let attemptIdentity: ObjectIdentifier
    fileprivate init(source: ColdEraseSchema2CompletedJournalSourceV1,
        attempt: ColdEraseSchema2CompletedJournalSourceV1.Attempt,
        pointer: Data, retired: Data, manifest: Data, id: UUID, epoch: GenerationEpochV1) {
        self.source = source; self.attempt = attempt
        sourceIdentity = ObjectIdentifier(source); attemptIdentity = ObjectIdentifier(attempt)
        provenance = source.factoryProvenance
        pointerBytes = pointer; retiredBytes = retired; manifestBytes = manifest
        generationID = id; generationEpoch = epoch
    }
    func requirePositivePermanentSettlement(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory) throws {
        guard let source, ObjectIdentifier(source) == sourceIdentity,
              ObjectIdentifier(attempt) == attemptIdentity, attempt.receipt === self,
              source.owner === owner, !source.uncertain,
              attempt.returned, attempt.primary == nil, attempt.secondary == nil,
              (source.attempts.prefix(source.attemptCount).contains(where: { $0 === attempt }) || attempt.origin == nil && attempt.consumedObservationReceipt != nil),
              generationEpoch.generationID == generationID else { throw StoreMigrationFailure.invalidIdentity }
        for r in attempt.resources.prefix(attempt.resourceCount).compactMap({ $0 }) {
            guard r.openResult == r.descriptor, r.openErrno != nil, r.closeEntered,
                  r.closeResult == 0, r.closeErrno != nil else { throw StoreMigrationFailure.invalidIdentity }
        }
        try provenance.requireMatches(factory: factory)
        try requireActualBytes(source: source, attempt: attempt)
        let epoch = try StoreGenerationFactory.decodeCompletedSchema2CurrentEpochData(
            pointerBytes: pointerBytes, manifestBytes: manifestBytes, owner: owner)
        guard epoch == generationEpoch else { throw StoreMigrationFailure.invalidIdentity }
    }
    private func requireActualBytes(source: ColdEraseSchema2CompletedJournalSourceV1,
        attempt: ColdEraseSchema2CompletedJournalSourceV1.Attempt) throws {
        guard attempt.payloads[source.rootURL.appendingPathComponent("FieldEvidenceData/current.json").path] == pointerBytes,
              attempt.payloads[source.rootURL.appendingPathComponent("FieldEvidenceData/retired.json").path] == retiredBytes,
              attempt.payloads[source.rootURL.appendingPathComponent("FieldEvidenceOperations/schema-migration")
                .appendingPathComponent(ColdEraseSchema2CompletedJournalSourceV1.manifestName(generationID)).path] == manifestBytes else {
            throw StoreMigrationFailure.invalidIdentity
        }
        if let basis = attempt.sessionOpeningState.controlBasis {
            try source.requireSessionOpeningReturnReceiptCell(self, attempt: attempt)
            guard pointerBytes == basis.pointerBytes, retiredBytes == basis.retiredBytes,
                  manifestBytes == basis.manifestBytes, generationID == basis.generationID,
                  generationEpoch == basis.generationEpoch else { throw StoreMigrationFailure.invalidIdentity }
            try source.requireSessionOpeningMembers(attempt)
        }
        for scope in attempt.journalPolicies { try scope.requirePositivePermanentSettlement() }
        for scope in attempt.sourcePolicies { try scope.requirePositivePermanentSettlement() }
        for scope in attempt.temporaryPolicies { try scope.requirePositivePermanentSettlement() }
        for r in attempt.reads.prefix(attempt.readCount).compactMap({ $0 }) {
            guard r.returned, r.consumed, r.digest != nil,
                  r.resource.closeResult == 0, r.resource.closeErrno != nil else { throw StoreMigrationFailure.invalidIdentity }
        }
    }
    func requireSessionOpeningControlBasis(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory) throws -> ColdEraseSchema2CompletedJournalSourceV1.SessionOpeningControlBasis {
        try requirePositivePermanentSettlement(owner: owner, factory: factory)
        guard let source, let dataBasis = attempt.sessionDataBasis else { throw StoreMigrationFailure.invalidIdentity }
        let data = try source.requireSessionDataBasis(dataBasis, attempt: attempt)
        var leaves: [ColdEraseSchema2CompletedJournalSourceV1.SessionOpeningControlBasis.Leaf] = []
        leaves.reserveCapacity(48)
        for read in attempt.reads.prefix(attempt.readCount).compactMap({ $0 }) {
            let resource = read.resource
            guard read.returned, read.consumed, read.digest != nil,
                  resource.closeEntered, resource.closeResult == 0, resource.closeErrno != nil,
                  let expected = resource.expected, let held = resource.lastHeld, let named = resource.lastNamed,
                  ColdEraseSchema2CompletedJournalSourceV1.same(expected, held),
                  ColdEraseSchema2CompletedJournalSourceV1.same(held, named) else {
                throw StoreMigrationFailure.invalidIdentity
            }
            let prior = leaves.first(where: { $0.role == resource.role && $0.url == resource.url && $0.name == resource.name })
            if let prior {
                // Earlier own policy cohorts may differ only through actual typed PFP receipt.
                try source.requireReadCohort(url: resource.url, before: prior.fact, after: held)
                leaves.removeAll { $0.role == resource.role && $0.url == resource.url && $0.name == resource.name }
            }
            leaves.append(.init(role: resource.role, url: resource.url, name: resource.name, fact: held))
        }
        let currentURL = source.rootURL.appendingPathComponent("FieldEvidenceData/current.json")
        let retiredURL = source.rootURL.appendingPathComponent("FieldEvidenceData/retired.json")
        let manifestURL = source.rootURL.appendingPathComponent("FieldEvidenceOperations/schema-migration")
            .appendingPathComponent(ColdEraseSchema2CompletedJournalSourceV1.manifestName(generationID))
        guard leaves.contains(where: { $0.role == .current && $0.url == currentURL }),
              leaves.contains(where: { $0.role == .retired && $0.url == retiredURL }),
              leaves.contains(where: { $0.role == .manifest && $0.url == manifestURL }) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        return .init(initialReceipt: self, dataFact: data.fact, dataNames: data.names, leaves: leaves,
            pointerBytes: pointerBytes, retiredBytes: retiredBytes, manifestBytes: manifestBytes,
            generationID: generationID, generationEpoch: generationEpoch)
    }
    // Pure actual lower-returned Source proof; native adoption follows this
    // return and is intentionally absent here. No current/expired frame reentry.
    fileprivate func requireSourceOnlyReturnedObservationDataProjection(
        _ projection: ColdEraseSchema2CompletedSourceDataPolicyProjectionV1,
        state: ColdEraseSchema2CompletedJournalSourceV1.ObservationDataAttemptState) throws {
        guard let source, ObjectIdentifier(source) == sourceIdentity,
              ObjectIdentifier(attempt) == attemptIdentity, attempt.receipt === self,
              !source.uncertain, attempt.returned, attempt.primary == nil, attempt.secondary == nil,
              attempt.observationDataState === state,
              observationDataProjection === projection || consumedObservationDataProjection === projection,
              generationEpoch.generationID == generationID else { throw StoreMigrationFailure.invalidIdentity }
        let cell = state.storage.returnCell
        if let origin = attempt.origin {
            guard case .observation(_) = origin,
                  source.attempts.prefix(source.attemptCount).contains(where: { $0 === attempt }),
                  cell.storage.receipt === self, cell.storage.projection === projection,
                  cell.storage.consumedOrigin == nil else { throw StoreMigrationFailure.invalidIdentity }
        } else {
            guard let consumed = attempt.consumedObservationReceipt,
                  cell.storage.consumedOrigin === consumed,
                  cell.storage.receipt == nil, cell.storage.projection == nil,
                  cell.storage.transferredReceipt === self,
                  cell.storage.transferredProjection === projection else { throw StoreMigrationFailure.invalidIdentity }
        }
        for resource in attempt.resources.prefix(attempt.resourceCount).compactMap({ $0 }) {
            guard resource.openEntered, let descriptor = resource.descriptor, descriptor >= 0,
                  resource.openResult == descriptor, resource.openErrno != nil,
                  resource.closeEntered, resource.closeResult == 0, resource.closeErrno != nil else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
        try provenance.requireSameProvenance(source.factoryProvenance)
        try requireActualBytes(source: source, attempt: attempt)
    }
    func requirePositiveObservationDataBasisAdoption(
        observation: ColdEraseSchema2CompletedRegistryObservationScopeV1) throws {
        guard let source, ObjectIdentifier(source) == sourceIdentity,
              let state = attempt.observationDataState,
              attempt.returned, attempt.primary == nil, attempt.secondary == nil else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let cell = state.storage.returnCell
        let projection: ColdEraseSchema2CompletedSourceDataPolicyProjectionV1
        if let origin = attempt.origin {
            guard case .observation(let actual) = origin, actual === observation,
                  let retained = cell.storage.projection,
                  cell.storage.receipt === self, observationDataProjection === retained,
                  cell.storage.consumedOrigin == nil else { throw StoreMigrationFailure.invalidIdentity }
            projection = retained
        } else {
            guard attempt.consumedObservation === observation,
                  let consumed = attempt.consumedObservationReceipt,
                  cell.storage.consumedOrigin === consumed,
                  let transferred = cell.storage.transferredProjection,
                  cell.storage.transferredReceipt === self,
                  consumedObservationDataProjection === transferred,
                  cell.storage.receipt == nil, cell.storage.projection == nil,
                  observationDataProjection == nil else { throw StoreMigrationFailure.invalidIdentity }
            projection = transferred
        }
        try requireSourceOnlyReturnedObservationDataProjection(projection, state: state)
        _ = try projection.requireReturnedNativeProjectionData(basis: state.storage.basis)
        // SAME privately issued Basis's real recorded adoption and, after
        // consumption, its actual finalized bank archive; no ended frame replay.
        try state.storage.basis.requirePositiveAdoptedNativePinProjection()
    }
    func requireCompletedSessionObservationDataPolicyProjection(
        observation: ColdEraseSchema2CompletedRegistryObservationScopeV1,
        before: EraseColdControlLeafFactV1, beforeFlags: UInt32,
        after: EraseColdControlLeafFactV1, afterFlags: UInt32) throws
        -> ColdEraseSchema2CompletedSourceDataPolicyProjectionV1 {
        guard let source, let state = attempt.observationDataState,
              let projection = observationDataProjection,
              case .observation(let actual)? = attempt.origin, actual === observation else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let returned = try projection.requireReturnedNativeProjectionData(basis: state.storage.basis)
        try projection.requireReturnedProjection(basis: state.storage.basis, source: source,
            observation: observation, before: before, beforeFlags: beforeFlags,
            after: after, afterFlags: afterFlags, beforeNames: state.storage.basis.names,
            afterNames: returned.names)
        return projection // SAME pre-callback retained node, never a new/latest node
    }
    func requireSessionOpeningOwnDataPolicyProjection(sessionOpening: ColdEraseSchema2CompletedSessionOpeningScopeV1,
        before: EraseColdControlLeafFactV1, beforeFlags: UInt32,
        after: EraseColdControlLeafFactV1, afterFlags: UInt32) throws {
        guard let source, let owner = source.owner, let factory = source.retainedFactory,
              case .sessionOpening(let actual)? = attempt.origin, actual === sessionOpening,
              let basis = attempt.sessionOpeningState.controlBasis,
              ColdEraseSchema2CompletedJournalSourceV1.fact(basis.dataFact) == before,
              basis.dataFact.st_flags == beforeFlags, beforeFlags == afterFlags,
              let actualBasis = attempt.sessionDataBasis else { throw StoreMigrationFailure.invalidIdentity }
        try requirePositivePermanentSettlement(owner: owner, factory: factory)
        let final = try source.requireSessionDataBasis(actualBasis, attempt: attempt)
        guard ColdEraseSchema2CompletedJournalSourceV1.fact(final.fact) == after,
              final.fact.st_flags == afterFlags, final.names == basis.dataNames,
              ColdEraseSchema2CompletedJournalSourceV1.sameExceptChangeTime(basis.dataFact, final.fact) else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let matches = attempt.sourcePolicies.filter {
            $0.resource === actualBasis.storage.data && $0.kind == .durableDirectory
                && $0.expectedFact == before && $0.expectedFlags == beforeFlags
                && $0.settledFact == after && $0.settledFlags == afterFlags
        }
        guard let policy = matches.last, let request = policy.request else { throw StoreMigrationFailure.invalidIdentity }
        try policy.requirePositivePermanentSettlement()
        try request.requirePositivePermanentSettlement(scope: policy)
