    func requireCompletedSessionDataRootBasis(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory) throws -> (fact: stat, names: [String]) {
        try requirePositivePermanentSettlement(owner: owner, factory: factory)
        guard let source, let basis = attempt.sessionDataBasis else { throw StoreMigrationFailure.invalidIdentity }
        // DATA only. The genuine new Session frame provides current authority.
        return try source.requireSessionDataBasis(basis, attempt: attempt)
    }
    func requireConsumedPositivePermanentSettlement(owner: ColdEraseSchema2CompletedStartupOwnerV1) throws {
        guard let source, ObjectIdentifier(source) == sourceIdentity,
              ObjectIdentifier(attempt) == attemptIdentity, attempt.receipt === self,
              source.owner === owner, !source.uncertain, attempt.returned,
              attempt.primary == nil, attempt.secondary == nil,
              attempt.origin == nil, attempt.consumedBootstrap != nil || attempt.consumedObservationReceipt != nil || attempt.sessionOpeningState.consumedReceipt != nil else {
            throw StoreMigrationFailure.invalidIdentity
