@MainActor
final class ColdEraseSchema2CompletedSourceDataPolicyProjectionV1 {
    private struct Storage {
        weak var source: ColdEraseSchema2CompletedJournalSourceV1?
        weak var observation: ColdEraseSchema2CompletedRegistryObservationScopeV1?
        let attempt: ColdEraseSchema2CompletedJournalSourceV1.Attempt
        let receipt: ColdEraseSchema2CompletedCurrentSourceReceiptV1
