                  r.openEntered, r.openResult == r.descriptor, r.openErrno != nil,
                  !r.closeEntered, r.closeResult == nil, r.closeErrno == nil,
                  r.directory == nil, !r.fdopendirEntered,
                  storage.facts[i].st_mode & S_IFMT == S_IFDIR,
                  storage.facts[i].st_nlink > 0 else { throw StoreMigrationFailure.invalidIdentity }
