            let scope: ColdEraseSchema2CompletedRegistryAllocationScopeV1?
            if case .allocation(let actual)? = attempt.origin { scope = actual }
            else if attempt.origin == nil { scope = attempt.consumedAllocation }
            else { scope = nil }
