        } catch {
            value.storage.primary = error; value.storage.phase = .uncertain
            source.uncertain = true
            throw error
        }
    }
    private func requireOpenTransferredSourceGraph(source: ColdEraseSchema2CompletedJournalSourceV1,
        registry: GenerationLeaseRegistryV1) throws {
        guard storage.phase != .uncertain, storage.primary == nil,
              storage.source === source, storage.sourceIdentity == ObjectIdentifier(source),
              storage.registry === registry, storage.registryIdentity == ObjectIdentifier(registry),
              source.completedJournalLifetime === self, source.store === storage.store,
              storage.store.completedSourceForCheckedDispatch === source,
              storage.graph.count == 3, storage.descriptors.count == 3, storage.facts.count == 3,
              Set(storage.descriptors).count == 3, storage.descriptors.allSatisfy({ $0 >= 0 }),
              storage.graph[0] === source.support, storage.graph[1] === source.operations,
              storage.graph[2] === source.migration,
              storage.graph[0].role == .support, storage.graph[1].role == .operations,
              storage.graph[2].role == .migration,
              storage.graph.allSatisfy(\.isDirectory),
              storage.graph[0].url == storage.rootURL,
              storage.graph[1].url == storage.rootURL.appendingPathComponent("FieldEvidenceOperations"),
              storage.graph[2].url == storage.graph[1].url.appendingPathComponent("schema-migration"),
              storage.graph[0].parent == nil, storage.graph[1].parent == storage.descriptors[0],
              storage.graph[2].parent == storage.descriptors[1],
              storage.graph[1].name == "FieldEvidenceOperations", storage.graph[2].name == "schema-migration" else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try source.requireTransferredStoreGraph()
        for i in storage.graph.indices {
            let resource = storage.graph[i]
            guard resource.transferred, resource.openEntered,
                  resource.descriptor == storage.descriptors[i], resource.openResult == storage.descriptors[i],
                  resource.openErrno != nil, !resource.closeEntered,
                  resource.closeResult == nil, resource.closeErrno == nil,
                  resource.directory == nil, !resource.fdopendirEntered,
                  let expected = resource.expected,
                  ColdEraseSchema2CompletedJournalSourceV1.same(expected, storage.facts[i]),
                  expected.st_mode & S_IFMT == S_IFDIR, expected.st_nlink > 0 else {
                throw StoreMigrationFailure.invalidIdentity
            }
        }
    }
    fileprivate func recordActualSourceOriginRelease() {
        // Called only by the genuine Source immediately after its successful
        // Ready origin release assignments. No IO or fallible callback occurs.
        storage.phase = .sourceOriginTransferred
        storage.retainedSource = nil; storage.retainedOwner = nil
        storage.retainedBootstrap = nil; storage.retainedReceiver = nil
    }
    func requireTransferredLifetimeData(source: ColdEraseSchema2CompletedJournalSourceV1,
        registry: GenerationLeaseRegistryV1) throws {
        guard storage.phase == .sourceOriginTransferred, storage.retainedSource == nil,
              storage.retainedOwner == nil, storage.retainedBootstrap == nil,
              storage.retainedReceiver == nil, let transfer = storage.registryTransfer else {
            throw StoreMigrationFailure.invalidIdentity
        }
        try transfer.requirePermanentRegistryAssociation(registry: registry)
        try requireOpenTransferredSourceGraph(source: source, registry: registry)
        // This is permanent provenance DATA. It performs no kernel operation,
        // reenters no ended origin and authorizes no future lifecycle effect.
    }
}

@MainActor
final class ColdEraseSchema2CompletedJournalRegistryTransferV1 {
    private struct Storage {
        weak var registry: GenerationLeaseRegistryV1?
        let registryIdentity: ObjectIdentifier
        let engine: ColdEraseSchema2CompletedRegistryEngineScopeV1
        let graph: [ColdEraseSchema2CompletedRegistryDescriptorResourceV1]
        let roles: [ColdEraseSchema2CompletedRegistryResourcesV1.Role]
        let descriptors: [Int32]
        let facts: [stat]
        let allocationBanks: [ColdEraseSchema2CompletedRegistryResourcesV1]
    }
    private let storage: Storage
    var descriptors: [Int32] { storage.descriptors }
    nonisolated static func declaredBackingBytes() -> UInt64 {
        UInt64(MemoryLayout<Storage>.stride
            + 6 * MemoryLayout<ColdEraseSchema2CompletedRegistryDescriptorResourceV1>.stride
            + 6 * MemoryLayout<ColdEraseSchema2CompletedRegistryResourcesV1.Role>.stride
            + 6 * MemoryLayout<Int32>.stride + 6 * MemoryLayout<stat>.stride
            + 2 * MemoryLayout<ColdEraseSchema2CompletedRegistryResourcesV1>.stride)
    }
    fileprivate init(receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1,
        registry: GenerationLeaseRegistryV1, owner: ColdEraseSchema2CompletedStartupOwnerV1) throws {
        try receiver.requireTransferredRegistry(registry: registry, owner: owner)
        guard let engine = registry.completedSchema2RegistryEngine,
              registry.completedSchema2AllocationScopes.count == 2 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.requireCompletedSchema2ConstructorResourceTransfer(engine.attempt)
        var banks: [ColdEraseSchema2CompletedRegistryResourcesV1] = []
        banks.reserveCapacity(2)
        for scope in registry.completedSchema2AllocationScopes {
            banks.append(try scope.completedJournalReadyTransferredBank(
                receiver: receiver, registry: registry, owner: owner))
        }
        let graph = engine.permanentResources
        let descriptors = registry.completedSchema2TransferredDescriptors
        let roles: [ColdEraseSchema2CompletedRegistryResourcesV1.Role] =
            [.support, .operations, .lease, .owners, .mutationControl, .ownerControl]
        guard graph.count == 6, descriptors.count == 6,
              Set(descriptors).count == 6, graph.map(\.role) == roles,
              banks.count == 2, banks[0] !== banks[1] else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        var facts: [stat] = []; facts.reserveCapacity(6)
        for (resource, descriptor) in zip(graph, descriptors) {
            try resource.requireTransferredDescriptor(descriptor)
            guard let fact = resource.retainedCurrentFact else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            facts.append(fact) // authentic retained producer fact; no new stat adoption
        }
        storage = Storage(registry: registry, registryIdentity: ObjectIdentifier(registry),
            engine: engine, graph: graph, roles: roles, descriptors: descriptors,
            facts: facts, allocationBanks: banks)
        try requirePermanentRegistryAssociation(registry: registry)
    }
    func requirePermanentRegistryAssociation(registry: GenerationLeaseRegistryV1) throws {
        guard storage.registry === registry, storage.registryIdentity == ObjectIdentifier(registry),
              registry.completedSchema2RegistryEngine === storage.engine,
              registry.completedSchema2TransferredDescriptors == storage.descriptors,
              storage.graph.count == 6, storage.facts.count == 6,
              storage.graph.map(\.role) == storage.roles,
              storage.allocationBanks.count == 2 else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try registry.requireCompletedSchema2ConstructorResourceTransfer(storage.engine.attempt)
        for (resource, descriptor) in zip(storage.graph, storage.descriptors) {
            try resource.requireTransferredDescriptor(descriptor)
        }
        for bank in storage.allocationBanks { try bank.requirePermanentPositiveGraph() }
        // Captured full facts are provenance DATA only. A new current issuer
        // must prove later held/named/member state and causal projections.
    }
}

