/// Permanent DATA from the actual terminal checked-close graph. It is not a
/// current frame or permission to open a generation. The new Session maker
/// must retain this exact object and prove its graph again under its own frame.
@MainActor
final class ColdEraseSchema2CompletedSessionTargetBasisV1 {
    private weak var terminal: ColdEraseSchema2TerminalOwnerV1?
    private weak var observation: ColdEraseSchema2TerminalTargetObservationV1?
    private let physical: ColdEraseSchema2TerminalTargetPhysicalWitnessV1
    let binding: EraseRetirementBindingV1
    let generationsFact: stat
    let generationNames: [String]
    let nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]

    fileprivate init(terminal: ColdEraseSchema2TerminalOwnerV1,
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        physical: ColdEraseSchema2TerminalTargetPhysicalWitnessV1,
        binding: EraseRetirementBindingV1, generationsFact: stat,
        generationNames: [String], nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]) {
        self.terminal = terminal; self.observation = observation; self.physical = physical
        self.binding = binding; self.generationsFact = generationsFact
        self.generationNames = generationNames; self.nodes = nodes
    }
    func requireBound(observation expected: ColdEraseSchema2TerminalTargetObservationV1,
        binding expectedBinding: EraseRetirementBindingV1) throws {
        guard observation === expected, binding == expectedBinding,
              let terminal, generationNames == [binding.subject.newGenerationID.uuidString.lowercased()],
              nodes.first?.path == "", nodes.contains(where: { $0.path == "model.sqlite" }),
              Set(nodes.map(\.path)).count == nodes.count else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try expected.requireCompletedSessionBasis(self, terminal: terminal, physical: physical)
    }
    static func requiredBackingBytes(nodes: [EraseAbortCheckedSnapshotIOV1.CheckedTreeNode]) throws -> UInt64 {
        var bytes = UInt64(MemoryLayout<stat>.stride
            + 4 * MemoryLayout<AnyObject?>.stride + MemoryLayout<EraseRetirementBindingV1>.stride
            + 2 * MemoryLayout<Array<String>>.stride)
        for node in nodes {
            let part = UInt64(MemoryLayout<EraseAbortCheckedSnapshotIOV1.CheckedTreeNode>.stride)
                + UInt64(node.path.utf8.count) + UInt64(node.sha256?.utf8.count ?? 0)
            let sum = bytes.addingReportingOverflow(part)
            guard !sum.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            bytes = sum.partialValue
        }
        return bytes
    }
}

extension ColdEraseSchema2TerminalTargetObservationV1 {
    /// Closed association of the same real two close receipts. It does not
    /// call the Terminal's permanent checker and cannot recurse into Main.
    func requireCompletedCheckedTerminalAssociation(terminal expected: ColdEraseSchema2TerminalOwnerV1) throws {
        guard owner === expected, operation != nil, let manifest, let source,
              let proof, let witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try source.requireColdTerminalSourceClosedAssociation(owner: expected, observation: self)
        try manifest.requireCompletedCheckedTargetObservation(self, terminal: expected)
        try physical.requireBound(proof: proof, binding: binding, witness: witness)
    }
    /// The original live Manifest association is deliberately not replayed
    /// after close. These are the same privately produced Source and Manifest
    /// positive close receipts and the same genuine Factory physical proof.
    func makeCompletedSessionTargetBasis(terminal expected: ColdEraseSchema2TerminalOwnerV1)
        throws -> ColdEraseSchema2CompletedSessionTargetBasisV1 {
        guard owner === expected, operation != nil, let manifest, let source,
              let proof, let witness else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try source.requireColdTerminalSourceClosedAssociation(owner: expected, observation: self)
        let parent = try manifest.requireCompletedSessionGenerationsBasis(observation: self, terminal: expected)
        try physical.requireBound(proof: proof, binding: binding, witness: witness)
        let nodes = try physical.requireCompletedSessionTargetNodes(proof: proof, binding: binding, witness: witness)
        // Actual cost is available before the returned DATA object's birth;
        // the new Session reservation also charges it before its first effect.
        _ = try ColdEraseSchema2CompletedSessionTargetBasisV1.requiredBackingBytes(nodes: nodes)
        return ColdEraseSchema2CompletedSessionTargetBasisV1(terminal: expected,
            observation: self, physical: physical, binding: binding,
            generationsFact: parent.fact, generationNames: parent.names, nodes: nodes)
    }
    fileprivate func requireCompletedSessionBasis(_ basis: ColdEraseSchema2CompletedSessionTargetBasisV1,
        terminal expected: ColdEraseSchema2TerminalOwnerV1,
        physical expectedPhysical: ColdEraseSchema2TerminalTargetPhysicalWitnessV1) throws {
        guard owner === expected, physical === expectedPhysical, basis.binding == binding,
              let manifest, let source, let proof, let witness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try source.requireColdTerminalSourceClosedAssociation(owner: expected, observation: self)
        let parent = try manifest.requireCompletedSessionGenerationsBasis(observation: self, terminal: expected)
        guard EraseColdControlLeafFactV1(parent.fact) == EraseColdControlLeafFactV1(basis.generationsFact),
              parent.fact.st_flags == basis.generationsFact.st_flags,
              parent.names == basis.generationNames else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try expectedPhysical.requireBound(proof: proof, binding: binding, witness: witness)
        let original = try expectedPhysical.requireCompletedSessionTargetNodes(proof: proof, binding: binding, witness: witness)
        guard original.count == basis.nodes.count else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        for (left, right) in zip(original, basis.nodes) {
            guard left.path == right.path, left.sha256 == right.sha256,
                  EraseColdControlLeafFactV1(left.fact) == EraseColdControlLeafFactV1(right.fact),
                  left.fact.st_flags == right.fact.st_flags else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        }
    }
}

extension EraseSchema2ColdManifestOwnerV1 {
    fileprivate func requireCompletedCheckedTargetObservation(
        _ observation: ColdEraseSchema2TerminalTargetObservationV1,
        terminal: ColdEraseSchema2TerminalOwnerV1) throws {
        guard coldTerminalTargetObservation === observation,
              let close = coldTerminalManifestCloseReceipt else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
