    }
    /// Same retained first raw stat and actual returned deletion projection.
    /// No new stat, missing-field default or close retry is performed here.
    fileprivate func requireCompletedSessionGenerationsBasis(
        observation: ColdEraseSchema2TerminalTargetObservationV1,
        terminal: ColdEraseSchema2TerminalOwnerV1) throws -> (fact: stat, names: [String]) {
        guard coldTerminalTargetObservation === observation,
              let close = coldTerminalManifestCloseReceipt,
              let initial = completedSessionGenerationsInitialCapture,
              initial.returned == 0,
              let final = completedSessionGenerationsProjectionCapture,
              final.returned == 0,
              let projection = postGenerationProjection,
              final.fact.st_dev == initial.fact.st_dev,
              final.fact.st_ino == initial.fact.st_ino,
              final.fact.st_mode == initial.fact.st_mode,
              final.fact.st_uid == initial.fact.st_uid,
              final.fact.st_gid == initial.fact.st_gid,
              final.fact.st_flags == initial.fact.st_flags,
              EraseColdControlLeafFactV1(final.fact) == projection.generationsFact,
              completedSessionGenerationsProjectionNames == projection.generationNames else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try close.requireBound(owner: terminal, manifest: self, observation: observation)
        return (final.fact, projection.generationNames)
    }
}

// A new Session frame shares only the checked raw Registry mechanics. Its
// authority is the actual new Main Session callback and actual Reader receipt.
@MainActor
final class ColdEraseSchema2CompletedSessionOpeningScopeV1 {
    private struct Storage {
        weak var registry: GenerationLeaseRegistryV1?
        var retainedRegistry: GenerationLeaseRegistryV1?
        weak var owner: ColdEraseSchema2CompletedStartupOwnerV1?
        weak var inventory: EraseReaderRetirementInventoryV1?
        var retainedInventory: EraseReaderRetirementInventoryV1?
        weak var reader: GenerationLeaseAllocationAttemptV1?
        var retainedReader: GenerationLeaseAllocationAttemptV1?
        var factory: StoreGenerationFactory?
        let provenance: ColdEraseSchema2CompletedRegistryFactoryProvenanceV1
        let initialSourceReceipt: ColdEraseSchema2CompletedCurrentSourceReceiptV1
        let source: ColdEraseSchema2CompletedJournalSourceV1
        let observation: ColdEraseSchema2TerminalTargetObservationV1
        let basis: ColdEraseSchema2CompletedSessionTargetBasisV1
        let epoch: GenerationEpochV1
        var dataFact: stat
        var dataNames: [String]
        var currentReceipts: [ColdEraseSchema2CompletedCurrentSourceReceiptV1] = []
        var lastPositiveCurrentReceipt: ColdEraseSchema2CompletedCurrentSourceReceiptV1?
        var sourceBound = false
        var entered = false
        var returned = false
        var uncertain = false
        weak var session: StoreGenerationSession?
        var retainedSession: StoreGenerationSession?
        var constructor: ColdEraseSchema2CompletedSessionConstructorReceiptV1?
        var primaryFailure: Error?
        var settlementFailure: Error?
        weak var receiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1?
        var retainedReceiver: ColdEraseSchema2CompletedStartupPublicationReceiverV1?
        var consumption: ColdEraseSchema2CompletedSessionOpeningConsumptionReceiptV1?
        var lifetime: ColdEraseSchema2CompletedSessionLifetimeTransferV1?
    }
    private var storage: Storage
    fileprivate let interval: ColdEraseSchema2CompletedRegistryCurrentIntervalV1
    private var bank: ColdEraseSchema2CompletedSessionResourceBankV1?
    let declaredBackingBytes: UInt64
    var generationRootURL: URL {
        interval.resources.rootURL.appendingPathComponent("FieldEvidenceData/generations")
            .appendingPathComponent(storage.epoch.generationID.uuidString.lowercased())
    }
    var targetBasis: ColdEraseSchema2CompletedSessionTargetBasisV1 { storage.basis }
    var generationEpoch: GenerationEpochV1 { storage.epoch }
    var dataRootFact: stat { storage.dataFact }
    var dataRootNames: [String] { storage.dataNames }

    fileprivate init(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1, factory: StoreGenerationFactory,
        inventory: EraseReaderRetirementInventoryV1, reader: GenerationLeaseAllocationAttemptV1,
        source: ColdEraseSchema2CompletedCurrentSourceReceiptV1,
        bootstrap: ColdEraseSchema2CompletedRegistryBootstrapScopeV1) throws {
        try owner.requireReaderConstructionFrame(factory: factory)
        try owner.requireReaderInventoryBinding(inventory)
        try owner.requireReaderAllocation(reader, registry: registry)
        try reader.requireCompletedSchema2StartupPublication(owner: owner, registry: registry)
        try bootstrap.requireSessionOpeningSourceReceipt(source, registry: registry,
            owner: owner, factory: factory, inventory: inventory)
        let actualSource = try bootstrap.requireReturnedSource(registry: registry, owner: owner)
        let epoch = try factory.requireCompletedSchema2CurrentEpoch(source: source, owner: owner)
        guard epoch == reader.generationEpoch else { throw GenerationLeaseRegistryFailureV1.staleGeneration }
        let observation = try owner.requireCompletedSessionTargetObservation(factory: factory)
        let basis = try observation.makeCompletedSessionTargetBasis()
        try basis.requireBound(observation: observation, binding: owner.binding)
        guard basis.binding.workspaceIdentity == owner.binding.workspaceIdentity,
              basis.binding.subject.newGenerationID == epoch.generationID else {
            throw GenerationLeaseRegistryFailureV1.staleGeneration
        }
        let data = try source.requireCompletedSessionDataRootBasis(owner: owner, factory: factory)
        let provenance = try factory.completedSchema2ConstructorFactoryProvenance()
        let root = registry.completedSchema2RegistryRootURL
        let rootURL = root.appendingPathComponent("FieldEvidenceData/generations")
            .appendingPathComponent(epoch.generationID.uuidString.lowercased())
        let profile = try ColdEraseSchema2CompletedSessionResourceBankV1.profile(
            basis: basis, rootURL: rootURL, dataNames: data.names)
        // These real fixed banks/field costs are derived before their birth.
        // Framework allocator/VM/RSS and aggregate owner admission remain Root obligations.
        let lowerExtra = UInt64(profile.policies).multipliedReportingOverflow(by: 192 * 12)
        guard !lowerExtra.overflow, lowerExtra.partialValue <= UInt64(Int.max - 147_456) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        interval = try ColdEraseSchema2CompletedRegistryCurrentIntervalV1(registry: registry,
            owner: owner, sessionOpeningAdditionalOutcomes: Int(lowerExtra.partialValue))
        storage = Storage(registry: registry, retainedRegistry: registry, owner: owner,
            inventory: inventory, retainedInventory: inventory, reader: reader,
            retainedReader: reader, factory: factory, provenance: provenance,
            initialSourceReceipt: source, source: actualSource, observation: observation,
            basis: basis, epoch: epoch, dataFact: data.fact, dataNames: data.names)
        let base = try interval.declaredRetainedBackingBytes()
        let sourceEnvelope = base.addingReportingOverflow(interval.declaredSourceBackingLimit)
        guard !sourceEnvelope.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        let first = sourceEnvelope.partialValue.addingReportingOverflow(profile.declaredBytes)
        let second = first.partialValue.addingReportingOverflow(UInt64(MemoryLayout<Storage>.stride))
        guard !first.overflow, !second.overflow else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        declaredBackingBytes = second.partialValue
        bank = ColdEraseSchema2CompletedSessionResourceBankV1(opening: self, profile: profile)
    }
    fileprivate func retainBeforeEffects() throws { try interval.retainBeforeEffects(.sessionOpening(self)) }
    private func requireAssociation(registry: GenerationLeaseRegistryV1,
        owner: ColdEraseSchema2CompletedStartupOwnerV1, factory: StoreGenerationFactory,
        inventory: EraseReaderRetirementInventoryV1) throws {
        guard !storage.uncertain, storage.registry === registry,
              (storage.retainedRegistry === registry || storage.consumption != nil), storage.owner === owner,
              storage.inventory === inventory,
              (storage.retainedInventory === inventory || storage.consumption != nil),
              factory.matchesSchema2ColdCompletedInventory(inventory),
              registry.completedSchema2SessionOpeningScopes.contains(where: { $0 === self }),
              let reader = storage.reader,
              (storage.retainedReader === reader || storage.consumption != nil) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if storage.retainedRegistry == nil || storage.retainedReader == nil || storage.retainedInventory == nil {
            guard let consumption = storage.consumption else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try consumption.requirePositivePermanentSettlement(source: storage.source,owner: owner)
        }
        try storage.provenance.requireMatches(factory: factory)
        try reader.requireCompletedSchema2StartupPublication(owner: owner, registry: registry)
        try storage.initialSourceReceipt.requirePositivePermanentSettlement(owner: owner, factory: factory)
        try storage.basis.requireBound(observation: storage.observation, binding: owner.binding)
    }
    fileprivate func requireCurrentSessionOrigin() throws {
        guard let registry = storage.registry, let owner = storage.owner,
              let inventory = storage.inventory, let reader = storage.reader,
              let factory = storage.factory else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireAssociation(registry: registry, owner: owner, factory: factory, inventory: inventory)
        try owner.requireCompletedSessionOpeningFrame(scope: self, registry: registry,
            factory: factory, inventory: inventory, reader: reader, source: storage.initialSourceReceipt)
    }
    func requireRetainedResourceBank(_ value: ColdEraseSchema2CompletedSessionResourceBankV1) throws {
        guard bank === value, !storage.uncertain else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireCurrentSessionOrigin()
    }
    func requireCurrentResourceBankFrame(_ value: ColdEraseSchema2CompletedSessionResourceBankV1) throws {
        try requireRetainedResourceBank(value)
        guard storage.entered, !storage.returned else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try interval.requireEntered()
        try requireActualGenerationLoan()
    }
    func requireCurrentSessionKernelBoundary(bank value: ColdEraseSchema2CompletedSessionResourceBankV1) throws {
        try requireCurrentResourceBankFrame(value)
        try interval.requireKernelBoundary()
        try requireCurrentResourceBankFrame(value)
    }
    func requirePolicyResource(_ resource: ColdEraseSchema2CompletedSessionResourceBankV1.Resource,
        kind: OwnedFileKindV1, bank value: ColdEraseSchema2CompletedSessionResourceBankV1?) throws {
        guard let value, bank === value else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireCurrentResourceBankFrame(value)
        try value.requireOwnedPolicyRow(resource)
        try storage.factory?.requireCompletedSessionOwnedKind(resource: resource, kind: kind,
            rootURL: generationRootURL, basis: storage.basis)
        guard storage.factory != nil else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
    }
    func requireExpectedResourceNames(_ resource: ColdEraseSchema2CompletedSessionResourceBankV1.Resource,
        bank value: ColdEraseSchema2CompletedSessionResourceBankV1?) throws -> [String] {
        guard let value, bank === value else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireCurrentResourceBankFrame(value)
        try value.requireOwnedPolicyRow(resource)
        switch resource.role {
        case .data: return storage.dataNames
        case .generations: return storage.basis.generationNames
        case .generationRoot, .observerRoot:
            let originals = storage.basis.nodes.filter { !$0.path.isEmpty && !$0.path.contains("/") }.map(\.path)
            return (originals + (try value.ownCreatedRootMembers())).sorted()
        case .tree(let path):
            let prefix = path + "/"
            return storage.basis.nodes.compactMap { node in
                guard node.path.hasPrefix(prefix) else { return nil }
                let remainder = String(node.path.dropFirst(prefix.count))
                return remainder.contains("/") ? nil : remainder
            }.sorted()
        }
    }
    func requireSourceContext(owner: ColdEraseSchema2CompletedStartupOwnerV1,
        factory: StoreGenerationFactory) throws -> (registry: GenerationLeaseRegistryV1, rootURL: URL) {
        try interval.requireEntered()
        guard storage.owner === owner, let registry = storage.registry else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try storage.provenance.requireMatches(factory: factory)
        try requireCurrentSessionOrigin(); try requireActualGenerationLoan()
        return (registry, interval.resources.rootURL)
    }
    func bindCurrentSourceBeforeEffects(_ source: ColdEraseSchema2CompletedJournalSourceV1,
        registry: GenerationLeaseRegistryV1) throws {
        try interval.requireEntered()
        guard storage.registry === registry, storage.source === source,
              !storage.returned else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try requireCurrentSessionOrigin(); try requireActualGenerationLoan()
        storage.sourceBound = true
    }
