extension GenerationLeaseRegistryV1 {
    @MainActor fileprivate func withCompletedSessionCurrentGenerationMutation<Value>(
        bank: ColdEraseSchema2CompletedSessionCurrentRegistryBankV1,
        _ body: @MainActor () throws -> Value) throws -> Value {
        try bank.requireCurrentFrame()
        Self.processMutationLock.lock()
        defer { Self.processMutationLock.unlock() }
