        if case .failure(let error) = result,bank.storage.bodyError == nil { bank.storage.primary = error }
        if locked == 0,!bank.storage.generationUnlockEntered {
            bank.storage.generationUnlockEntered = true
            do {
                try bank.enter(bank,.generationUnlock,settlement: true)
                let unlocked = flock(mutationLockDescriptor,LOCK_UN), savedUnlock = errno
                bank.storage.generationUnlockReturned = unlocked; bank.storage.generationUnlockErrno = savedUnlock
                try bank.record(bank,.generationUnlock,returned: Int64(unlocked),savedErrno: savedUnlock,settlement: true)
