        try admission.requireReservedBeforeScopeBirth(request: request,registry: self,
            session: session,factory: factory,demand: demand)
        let scope = try ColdEraseSchema2CompletedSessionCurrentScopeV1(registry: self,owner: owner,session: session,
            factory: factory,request: request,verifyAfterOperation: verifyAfterOperation,admission: admission,demand: demand)
        try admission.retainConstructedScopeBeforeEffects(scope,request: request,registry: self,
            session: session,factory: factory,actualBackingBytes: scope.declaredBackingBytes)
        let retained = Result<Void,Error> {
            try owner.retainCompletedSessionCurrentScope(scope,registry: self,session: session,factory: factory,request: request)
        }
        scope.retainActualMainScopeRetentionResult(retained) // actual return before throwing get/postproof
        try retained.get()
        try scope.constructRetainedBankBeforeEffects()
        try scope.bindBeforeEffects()
        let result = Result<Value,Error> { try scope.withCurrentResources(body) }

        // Release the SAME actual admitted parent debit only after genuine
        // consumed positive bank/Source proof. Uncertainty retains the graph.
        switch result {
        case .success(let value):
            do {
                try scope.requireConsumedPositivePermanentSettlement(owner: owner,request: request)
                try admission.releaseAfterPositiveCurrentScopeConsumption(scope,request: request,registry: self,session: session,factory: factory)
            } catch {
                scope.retainFailedRegistryRetentionSettlement(error)
                throw error
            }
            return value
        case .failure(let original):
            do {
                try scope.requireConsumedPositivePermanentSettlement(owner: owner,request: request)
                try admission.releaseAfterPositiveCurrentScopeConsumption(scope,request: request,registry: self,session: session,factory: factory)
            } catch {
                // Preserve the actual failed retention proof as secondary
                // state, retain its graph and rethrow the original operation.
                scope.retainFailedRegistryRetentionSettlement(error)
            }
            throw original
        }
    }
}

