                Self.hashWord(UInt64(bitPattern: Int64(fact.st_mtimespec.tv_nsec)), into: &hasher)
                Self.hashWord(UInt64(bitPattern: Int64(fact.st_ctimespec.tv_sec)), into: &hasher)
